/* The git version whose behaviour this matches, plus what we are. */
#define GIT_VERSION_STRING "git version 2.47.3.bash-os"

/* What the two ends of a connection call each other. */
#define GIT_AGENT_STRING "git/2.47.3.bash-os"

#define GIT_EXIT_FATAL 128
#define GIT_EXIT_USAGE 129

static int
git_fatal (const char *format, ...)
{
    va_list args;
    fflush (stdout);
    fputs ("fatal: ", stderr);
    va_start (args, format);
    vfprintf (stderr, format, args);
    va_end (args);
    fputc ('\n', stderr);
    return GIT_EXIT_FATAL;
}

/* `-5` means the last five commits, so a count has to be told from a flag. */
static int
git_all_digits (const char *word)
{
    if (!*word) return 0;
    for (const char *p = word; *p; p++)
        if (*p < '0' || *p > '9') return 0;
    return 1;
}

static int
git_usage (const char *usage)
{
    fflush (stdout);
    fprintf (stderr, "usage: %s\n", usage);
    return GIT_EXIT_USAGE;
}

/* What git says when a name is neither a revision nor a path. */
static int
git_fatal_ambiguous (const char *name)
{
    fflush (stdout);
    fprintf (stderr, "fatal: ambiguous argument '%s': unknown revision or path "
                     "not in the working tree.\n", name);
    fprintf (stderr, "Use '--' to separate paths from revisions, like this:\n");
    fprintf (stderr, "'git <command> [<revision>...] -- [<file>...]'\n");
    return GIT_EXIT_FATAL;
}

#define GIT_NOTES_REF "refs/notes/commits"

/* `git whatchanged` shows a commit only where there is a diff to show under
   it, which is the one way it differs from `git log --raw`. */
static int git_headers_need_a_diff;

/* The notes a walk is showing, which `log` and `show` set for as long as
   they run: git puts them under the message of every commit that has one,
   and answers %N with the text. Empty means none are being shown. */
static char git_notes_showing[512];



/* Values from `git -c key=value`, applied over every configuration file. */
#define GIT_MAX_OVERRIDES 32
static const char *git_overrides[GIT_MAX_OVERRIDES];
static size_t git_n_overrides;

/* One repository plus its object store and configuration, opened when a
   command needs them. */
typedef struct {
    bgit_repo repo;
    bgit_odb odb;
    bgit_config cfg;
    int open;
    /* Where the command was run, under the top of the working tree, with a
       slash at the end; empty at the top and in a bare repository. git shows
       a path from here and takes one from here. */
    char prefix[4096];
} git_context;

/* A path of the repository's, written from where the command was run: the
   same path where that is the top, and with as many ../ as it takes
   otherwise. Returns BUF, or PATH where nothing had to change. */
static const char *
git_path_from_here (const git_context *ctx, const char *path, char *buf,
                    size_t size)
{
    const char *prefix = ctx->prefix;
    if (!*prefix) return path;
    /* However much of the two agree, component by component. */
    size_t shared = 0, at = 0;
    while (prefix[at] && path[at] && prefix[at] == path[at]) {
        if (path[at] == '/') shared = at + 1;
        at++;
    }
    if (!prefix[at] && path[at]) shared = at;   /* the whole prefix matched */
    size_t used = 0;
    for (const char *rest = prefix + shared; *rest; rest++)
        if (*rest == '/' && used + 3 < size) {
            memcpy (buf + used, "../", 3);
            used += 3;
        }
    snprintf (buf + used, size - used, "%s", path + shared);
    return buf;
}

/* A conversation with a far end. Over a path it is a child with a pipe
   each way, the way git starts its own; over HTTP it is a URL, where
   each request is a POST of its own and the answer comes back whole. */
struct git_conn {
    bgit_proto_io io;
    bgit_pkt_reader reader;
    git_context *ctx;            /* whose configuration to ask */
    int over_http;
    /* a child at the far end */
    pid_t child;
    int to_far, from_far;
    /* or a URL, and what is being built to send to it */
    char url[4096];
    const char *service;
    char secret[1024];           /* a name and secret, once one is needed */
    const char **headers;        /* what http.extraHeader adds */
    size_t n_headers;
    int follow;                  /* whether this request may be redirected */
    unsigned char *request;
    size_t request_len, request_cap;
    unsigned char *response;
    size_t response_len;
};
typedef struct git_conn git_conn;

/* Opening and closing one is written out beside the fetching and pushing
   that make one; `remote show` asks the far end too. */
static int git_far_end_open (git_conn *conn, git_context *ctx, const char *url,
                             const char *program, int for_fetch);
static int git_far_end_gone (void);
static int git_conn_close (git_conn *conn);

/* A name for a commit worked out from a ref that reaches it: the ref's own
   name, how many first-parent steps down from it the commit is, and how far
   the walk came to get there. Which of two names is better is git's rule:
   a tag beats anything else, an older tag beats a newer one, and between
   two of a kind the nearer one wins. */
struct git_rev_name {
    char sha[41];
    char *tip;
    long generation;
    long distance;
    int from_tag;
    long long taggerdate;
    int used;
};

/* A merge is counted as a long way round, so that a name coming down the
   first-parent line is preferred to one crossing a merge. git's own
   weight. */
#define GIT_MERGE_WEIGHT 65535

struct git_rev_names {
    struct git_rev_name *slots;
    size_t n_slots, n;
};

/* Working them out is written beside name-rev, which is what asks; both
   describe --contains and name-rev itself do. */
static int git_name_revs (git_context *ctx, const char *pattern, int only_tags,
                          struct git_rev_names *names);
static void git_rev_name_of (const struct git_rev_names *names,
                             const char *sha, int strip, char *out,
                             size_t outsz);
static void git_rev_name_written (const char *tip, long generation, int strip,
                                  char *out, size_t outsz);
static void git_rev_names_release (struct git_rev_names *names);

/* Both written out beside git notes, which is what keeps them. */
static int git_note_text (git_context *ctx, const char *ref,
                          const char *object, char **out, size_t *len);
static void git_notes_ref (git_context *ctx, const char *named, char *out,
                           size_t outsz);

/* One checkout of this repository: where it is, what it has checked out,
   and the administrative directory that ties the two together. */
struct git_worktree {
    char path[4096];       /* the working tree */
    char admin[4096];      /* the git directory for it; "" for the main one */
    char name[256];        /* what the admin directory is called */
    char head[41];
    char branch[4096];     /* the ref HEAD names, or "" when detached */
};

/* Every worktree of this repository, the main one first; written out
   beside git worktree, which is what makes the rest. */
static int git_worktrees (git_context *ctx, struct git_worktree **out,
                          size_t *n_out);
/* An absolute path for one that may not exist yet, beside it. */
static int git_absolute (const char *path, char *out, size_t outsz);

