static void git_format_date (const char *raw, int keep_raw, char *out,
                             size_t outsz);
static void git_ident_who (const char *ident, char *out, size_t outsz);

static int
git_context_open (git_context *ctx)
{
    if (ctx->open) return 0;
    if (bgit_repo_discover (".", &ctx->repo) < 0)
        return git_fatal ("not a git repository (or any of the parent directories): .git");
    if (bgit_odb_open (&ctx->repo, &ctx->odb) < 0) {
        bgit_repo_release (&ctx->repo);
        return git_fatal ("cannot read the object store");
    }
    /* Every message here is git's, so the store stays quiet. */
    ctx->odb.quiet = 1;
    ctx->open = 1;
    /* Where the command was run, under the top of the working tree. */
    ctx->prefix[0] = '\0';
    char here[4096];
    if (ctx->repo.work_tree && getcwd (here, sizeof here)) {
        size_t top = strlen (ctx->repo.work_tree);
        if (!strncmp (here, ctx->repo.work_tree, top)) {
            const char *rest = here + top;
            while (*rest == '/') rest++;
            if (*rest) snprintf (ctx->prefix, sizeof ctx->prefix, "%s/", rest);
        }
    }
    bgit_config_load (&ctx->cfg, &ctx->repo, git_overrides, git_n_overrides);
    /* Whether a byte outside ASCII is written as an escape in a path. */
    bgit_quote_path_fully = bgit_config_bool (&ctx->cfg, "core.quotePath", 1);
    /* Reflog entries record the configured identity. */
    char ident[1024];
    if (bgit_ident (&ctx->cfg, 1, ident, sizeof ident) == 0)
        bgit_refs_set_ident (ident);
    return 0;
}

static void
git_context_close (git_context *ctx)
{
    bgit_config_release (&ctx->cfg);
    if (!ctx->open) return;
    bgit_odb_release (&ctx->odb);
    bgit_repo_release (&ctx->repo);
    ctx->open = 0;
}

/* The branch HEAD was on before this one, and the one before that: what
   `@{-1}` names, and what `git checkout -` is short for. HEAD's reflog
   says where every move came from, so the answer is read back out of it.
   Returns 0 and the branch's name, or -1. */
static int
git_previous_branch (git_context *ctx, long back, char *out, size_t outsz)
{
    char **lines = NULL;
    size_t n = 0;
    if (back < 1 || bgit_reflog_lines (&ctx->repo, "HEAD", &lines, &n) != 0)
        return -1;
    int rc = -1;
    long seen = 0;
    /* Oldest first is how the log is kept, so the walk goes the other way. */
    for (size_t i = n; i-- > 0;) {
        const char *message = strchr (lines[i], '\t');
        if (!message) continue;
        message++;
        if (strncmp (message, "checkout: moving from ", 22)) continue;
        const char *from = message + 22;
        const char *to = strstr (from, " to ");
        if (!to) continue;
        if (++seen < back) continue;
        size_t len = (size_t) (to - from);
        if (len >= outsz) len = outsz - 1;
        memcpy (out, from, len);
        out[len] = '\0';
        rc = 0;
        break;
    }
    for (size_t i = 0; i < n; i++) free (lines[i]);
    free (lines);
    return rc;
}

/* Resolve a revision: an id, an abbreviation, a ref, or any of those with
   git's suffixes (^, ~, ^{type}, @{n}), and `@{-n}` for a branch HEAD was
   on before. */
static int
git_resolve (git_context *ctx, const char *name, char full[41], char **symref)
{
    char rewritten[4096];
    if (name && !strncmp (name, "@{-", 3)) {
        const char *close = strchr (name + 3, '}');
        char *end = NULL;
        long back = strtol (name + 3, &end, 10);
        if (close && end == close && back > 0) {
            char branch[4096];
            if (git_previous_branch (ctx, back, branch, sizeof branch) == 0 &&
                (size_t) snprintf (rewritten, sizeof rewritten, "%s%s", branch,
                                   close + 1) < sizeof rewritten)
                name = rewritten;
        }
    }
    return bgit_rev_parse (&ctx->repo, &ctx->odb, name, full, symref);
}

/* ---- init --------------------------------------------------------------- */

static int
git_write_file (const char *path, const char *content)
{
    FILE *f = fopen (path, "w");
    if (!f) return -1;
    fputs (content, f);
    return fclose (f) == 0 ? 0 : -1;
}

static int
git_cmd_init (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git init [-q | --quiet] [--bare] "
                        "[-b <branch-name>] [<directory>]";
    int quiet = 0, bare = 0;
    const char *branch = "master";   /* git's default without configuration */
    const char *where = ".";

    (void) ctx;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "--bare")) bare = 1;
        else if ((!strcmp (w, "-b") || !strcmp (w, "--initial-branch")) && p->next) {
            branch = p->next->word->word;
            p = p->next;
        } else if (!strncmp (w, "--initial-branch=", 17)) branch = w + 17;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else where = w;
    }
    if (!bgit_ref_name_ok (branch))
        return git_fatal ("invalid branch name: '%s'", branch);

    /* Every directory above it as well, which is what git makes. */
    {
        char made[4096];
        snprintf (made, sizeof made, "%s", where);
        for (char *slash = strchr (made[0] == '/' ? made + 1 : made, '/');
             slash; slash = strchr (slash + 1, '/')) {
            *slash = '\0';
            if (mkdir (made, 0777) < 0 && errno != EEXIST)
                return git_fatal ("cannot mkdir %s: %s", made,
                                  strerror (errno));
            *slash = '/';
        }
    }
    if (mkdir (where, 0777) < 0 && errno != EEXIST)
        return git_fatal ("cannot mkdir %s: %s", where, strerror (errno));
    char git_dir[4096];
    if (snprintf (git_dir, sizeof git_dir, bare ? "%s" : "%s/.git", where) >=
        (int) sizeof git_dir)
        return git_fatal ("path too long: %s", where);
    struct stat st;
    int existed = stat (git_dir, &st) == 0 && S_ISDIR (st.st_mode);
    if (mkdir (git_dir, 0777) < 0 && errno != EEXIST)
        return git_fatal ("cannot mkdir %s: %s", git_dir, strerror (errno));

    static const char *const subdirs[] = {
        "objects", "objects/info", "objects/pack", "refs", "refs/heads",
        "refs/tags", "info", "hooks", NULL
    };
    for (int i = 0; subdirs[i]; i++) {
        char path[4096];
        if (snprintf (path, sizeof path, "%s/%s", git_dir, subdirs[i]) >=
            (int) sizeof path)
            return git_fatal ("path too long: %s", git_dir);
        if (mkdir (path, 0777) < 0 && errno != EEXIST)
            return git_fatal ("cannot mkdir %s: %s", path, strerror (errno));
    }

    char path[4096], content[4096];
    snprintf (path, sizeof path, "%s/HEAD", git_dir);
    snprintf (content, sizeof content, "ref: refs/heads/%s\n", branch);
    if (access (path, F_OK) != 0 && git_write_file (path, content) < 0)
        return git_fatal ("cannot write %s: %s", path, strerror (errno));

    snprintf (path, sizeof path, "%s/config", git_dir);
    snprintf (content, sizeof content,
              "[core]\n"
              "\trepositoryformatversion = 0\n"
              "\tfilemode = true\n"
              "\tbare = %s\n%s",
              bare ? "true" : "false",
              bare ? "" : "\tlogallrefupdates = true\n");
    if (access (path, F_OK) != 0 && git_write_file (path, content) < 0)
        return git_fatal ("cannot write %s: %s", path, strerror (errno));

    snprintf (path, sizeof path, "%s/description", git_dir);
    if (access (path, F_OK) != 0 &&
        git_write_file (path, "Unnamed repository; edit this file "
                              "'description' to name the repository.\n") < 0)
        return git_fatal ("cannot write %s: %s", path, strerror (errno));

    snprintf (path, sizeof path, "%s/info/exclude", git_dir);
    if (access (path, F_OK) != 0 &&
        git_write_file (path,
                        "# git ls-files --others --exclude-from=.git/info/exclude\n"
                        "# Lines that start with '#' are comments.\n") < 0)
        return git_fatal ("cannot write %s: %s", path, strerror (errno));

    if (!quiet) {
        char *absolute = realpath (git_dir, NULL);
        printf ("%s empty Git repository in %s/\n",
                existed ? "Reinitialized existing" : "Initialized",
                absolute ? absolute : git_dir);
        free (absolute);
    }
    return 0;
}

/* ---- rev-parse ---------------------------------------------------------- */

/* The shortest unique abbreviation of at least LEN digits, as git does. */
static void
git_abbrev (git_context *ctx, const char *full, int len, char *out, size_t outsz)
{
    if (len < 4) len = 4;
    for (int n = len; n < 40; n++) {
        char prefix[41];
        memcpy (prefix, full, (size_t) n);
        prefix[n] = '\0';
        char resolved[41];
        if (bgit_odb_resolve (&ctx->odb, prefix, resolved) == 0 &&
            strcmp (resolved, full) == 0) {
            snprintf (out, outsz, "%s", prefix);
            return;
        }
    }
    snprintf (out, outsz, "%s", full);
}

static int
git_cmd_rev_parse (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git rev-parse [--git-dir] [--show-toplevel] "
                        "[--show-prefix] "
                        "[--is-inside-work-tree] [--is-bare-repository] "
                        "[--abbrev-ref] [--short[=N]] [--symbolic-full-name] "
                        "[--verify] [-q] <rev>...";
    int quiet = 0, verify = 0, abbrev_ref = 0, symbolic_full = 0, short_len = 0;
    int printed = 0;

    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--git-dir")) {
            /* git prints ".git" at the top of a worktree, and the absolute
               path anywhere else. */
            char cwd[4096], top[4096];
            if (ctx->repo.work_tree && getcwd (cwd, sizeof cwd) &&
                strcmp (cwd, ctx->repo.work_tree) == 0 &&
                snprintf (top, sizeof top, "%s/.git", ctx->repo.work_tree) <
                    (int) sizeof top &&
                strcmp (top, ctx->repo.git_dir) == 0)
                printf (".git\n");
            else
                printf ("%s\n", ctx->repo.git_dir);
            printed = 1;
        } else if (!strcmp (w, "--absolute-git-dir")) {
            printf ("%s\n", ctx->repo.git_dir);
            printed = 1;
        } else if (!strcmp (w, "--show-prefix")) {
            /* Where the command was run, under the top of the tree. */
            printf ("%s\n", ctx->prefix);
            printed = 1;
        } else if (!strcmp (w, "--show-toplevel")) {
            if (ctx->repo.work_tree) printf ("%s\n", ctx->repo.work_tree);
            printed = 1;
        } else if (!strcmp (w, "--is-inside-work-tree")) {
            printf ("%s\n", ctx->repo.work_tree ? "true" : "false");
            printed = 1;
        } else if (!strcmp (w, "--is-bare-repository")) {
            printf ("%s\n", ctx->repo.bare ? "true" : "false");
            printed = 1;
        } else if (!strcmp (w, "--all") || !strcmp (w, "--branches") ||
                   !strcmp (w, "--tags") || !strcmp (w, "--remotes")) {
            /* Every ref of that kind, as it stands, in ref order. */
            const char *under = !strcmp (w, "--branches") ? "refs/heads/"
                              : !strcmp (w, "--tags") ? "refs/tags/"
                              : !strcmp (w, "--remotes") ? "refs/remotes/"
                              : "refs/";
            bgit_ref *refs = NULL;
            size_t n_refs = 0;
            if (bgit_refs_list (&ctx->repo, under, &refs, &n_refs) < 0)
                return git_fatal ("cannot read refs");
            for (size_t i = 0; i < n_refs; i++) printf ("%s\n", refs[i].sha);
            bgit_refs_free (refs, n_refs);
            printed = 1;
        } else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) {
            quiet = 1;
        } else if (!strcmp (w, "--verify")) {
            verify = 1;
        } else if (!strcmp (w, "--abbrev-ref") ||
                   !strncmp (w, "--abbrev-ref=", 13)) {
            abbrev_ref = 1;
        } else if (!strcmp (w, "--symbolic-full-name")) {
            symbolic_full = 1;
        } else if (!strcmp (w, "--short")) {
            short_len = 7;
        } else if (!strncmp (w, "--short=", 8)) {
            short_len = atoi (w + 8);
            if (short_len <= 0) return git_usage (usage);
        } else if (w[0] == '-' && w[1]) {
            return git_usage (usage);
        } else {
            char full[41];
            char *symref = NULL;
            if (git_resolve (ctx, w, full, &symref) < 0) {
                free (symref);
                if (verify) {
                    if (quiet) return 1;
                    return git_fatal ("Needed a single revision");
                }
                printf ("%s\n", w);
                fflush (stdout);
                fprintf (stderr,
                         "fatal: ambiguous argument '%s': unknown revision or path not in the working tree.\n"
                         "Use '--' to separate paths from revisions, like this:\n"
                         "'git <command> [<revision>...] -- [<file>...]'\n", w);
                return GIT_EXIT_FATAL;
            }
            if (symbolic_full) {
                if (symref) printf ("%s\n", symref);
            } else if (abbrev_ref) {
                const char *name = symref ? symref : w;
                const char *shortened = name;
                static const char *const strip[] = {
                    "refs/heads/", "refs/tags/", "refs/remotes/", NULL
                };
                for (int i = 0; strip[i]; i++)
                    if (!strncmp (name, strip[i], strlen (strip[i])))
                        shortened = name + strlen (strip[i]);
                printf ("%s\n", shortened);
            } else if (short_len) {
                char abbreviated[41];
                git_abbrev (ctx, full, short_len, abbreviated, sizeof abbreviated);
                printf ("%s\n", abbreviated);
            } else {
                printf ("%s\n", full);
            }
            free (symref);
            printed = 1;
        }
    }
    if (!printed && !args) return git_usage (usage);
    return 0;
}

/* ---- cat-file ----------------------------------------------------------- */

/* git prints a tree entry's mode padded to six digits, with the type its
   mode implies. */
static const char *
git_tree_entry_type (const char *mode)
{
    if (!strncmp (mode, "40000", 5) || !strncmp (mode, "040000", 6)) return "tree";
    if (!strncmp (mode, "160000", 6)) return "commit";
    return "blob";
}

static int
git_print_tree (const unsigned char *data, size_t len)
{
    size_t pos = 0;
    while (pos < len) {
        size_t mode_start = pos;
        while (pos < len && data[pos] != ' ') pos++;
        if (pos >= len) return git_fatal ("corrupt tree object");
        size_t mode_len = pos - mode_start;
        char mode[16];
        if (mode_len >= sizeof mode) return git_fatal ("corrupt tree object");
        memcpy (mode, data + mode_start, mode_len);
        mode[mode_len] = '\0';
        pos++;
        size_t name_start = pos;
        while (pos < len && data[pos] != '\0') pos++;
        if (pos >= len) return git_fatal ("corrupt tree object");
        size_t name_len = pos - name_start;
        pos++;
        if (pos + 20 > len) return git_fatal ("corrupt tree object");
        char hex[41];
        bgit_sha_to_hex (data + pos, hex);
        pos += 20;
        printf ("%06lo %s %s\t%.*s\n", strtoul (mode, NULL, 8),
                git_tree_entry_type (mode), hex, (int) name_len,
                (const char *) (data + name_start));
    }
    return 0;
}

/* Read object names from stdin, as `git cat-file --batch` and
   `--batch-check` do, and report each one. */
static int
git_cat_file_batch (git_context *ctx, int with_content, int all_objects)
{
    /* Every object the store holds, in id order, instead of the ones asked
       for on stdin. */
    if (all_objects) {
        char (*names)[41] = NULL;
        size_t n = 0;
        if (bgit_odb_list (&ctx->odb, &names, &n) < 0) {
            fflush (stdout);
            fprintf (stderr, "fatal: out of memory\n");
            return GIT_EXIT_FATAL;
        }
        for (size_t i = 0; i < n; i++) {
            enum bgit_type type;
            unsigned char *data = NULL;
            size_t len = 0;
            if (bgit_odb_read (&ctx->odb, names[i], &type, &data, &len) < 0) {
                printf ("%s missing\n", names[i]);
                continue;
            }
            printf ("%s %s %zu\n", names[i], bgit_type_name (type), len);
            if (with_content) {
                fwrite (data, 1, len, stdout);
                putchar ('\n');
            }
            free (data);
        }
        free (names);
        return 0;
    }
    char *line = NULL;
    size_t cap = 0;
    ssize_t got;
    clearerr (stdin);
    while ((got = getline (&line, &cap, stdin)) > 0) {
        while (got > 0 && (line[got - 1] == '\n' || line[got - 1] == '\r'))
            line[--got] = '\0';
        if (!got) continue;
        char id[41];
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        if (git_resolve (ctx, line, id, NULL) < 0 ||
            bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0) {
            printf ("%s missing\n", line);
            continue;
        }
        printf ("%s %s %zu\n", id, bgit_type_name (type), len);
        if (with_content) {
            fwrite (data, 1, len, stdout);
            putchar ('\n');
        }
        free (data);
    }
    free (line);
    return 0;
}

static int
git_cmd_cat_file (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git cat-file (-t | -s | -e | -p | <type>) <object> "
                        "| (--batch | --batch-check) [--batch-all-objects]";
    int want_type = 0, want_size = 0, want_exists = 0, pretty = 0;
    int batch = 0, batch_check = 0, all_objects = 0;
    const char *as_type = NULL, *name = NULL;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--batch")) batch = 1;
        else if (!strcmp (w, "--batch-check")) batch_check = 1;
        else if (!strcmp (w, "--batch-all-objects")) all_objects = 1;
        /* The order this store lists them in is the sorted one either way. */
        else if (!strcmp (w, "--unordered")) ;
        else if (!strcmp (w, "-t")) want_type = 1;
        else if (!strcmp (w, "-s")) want_size = 1;
        else if (!strcmp (w, "-e")) want_exists = 1;
        else if (!strcmp (w, "-p")) pretty = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!as_type && !name && bgit_type_valid_name (w) &&
                 !want_type && !want_size && !want_exists && !pretty)
            as_type = w;
        else if (!name) name = w;
        else return git_usage (usage);
    }
    if (batch || batch_check) {
        if (want_type || want_size || want_exists || pretty)
            return git_usage (usage);
        if (name || as_type)
            return git_fatal ("batch modes take no arguments");
        if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
        return git_cat_file_batch (ctx, batch, all_objects);
    }
    if (all_objects)
        return git_fatal ("'--batch-all-objects' requires a batch mode");
    if (!name) return git_usage (usage);
    if (want_type + want_size + want_exists + pretty + (as_type ? 1 : 0) != 1)
        return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char full[41];
    if (git_resolve (ctx, name, full, NULL) < 0) {
        return git_fatal ("Not a valid object name %s", name);
    }
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    fflush (stderr);
    if (bgit_odb_read (&ctx->odb, full, &type, &data, &len) < 0) {
        if (want_exists) return 1;
        if (want_type || want_size)
            return git_fatal ("git cat-file: could not get object info");
        if (as_type)
            return git_fatal ("git cat-file %s: bad file", name);
        return git_fatal ("Not a valid object name %s", name);
    }
    int rc = 0;
    if (want_exists) {
        /* nothing to print */
    } else if (want_type) {
        printf ("%s\n", bgit_type_name (type));
    } else if (want_size) {
        printf ("%zu\n", len);
    } else if (as_type) {
        if (strcmp (as_type, bgit_type_name (type)) != 0) {
            free (data);
            return git_fatal ("%s is not a %s", full, as_type);
        }
        fwrite (data, 1, len, stdout);
    } else if (type == BGIT_TREE) {
        rc = git_print_tree (data, len);
    } else {
        fwrite (data, 1, len, stdout);
    }
    free (data);
    return rc;
}

/* ---- hash-object ------------------------------------------------------- */

static int
git_cmd_hash_object (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git hash-object [-t <type>] [-w] [--stdin | "
                        "--stdin-paths] [--literally] [<file>...]";
    const char *type = "blob";
    int write_object = 0, from_stdin = 0, stdin_paths = 0, literally = 0;
    const char *files[64];
    int n_files = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-w")) write_object = 1;
        else if (!strcmp (w, "--stdin")) from_stdin = 1;
        else if (!strcmp (w, "--stdin-paths")) stdin_paths = 1;
        else if (!strcmp (w, "--literally")) literally = 1;
        else if (!strcmp (w, "-t") && p->next) { type = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "-t", 2) && w[2]) type = w + 2;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_files < (int) (sizeof files / sizeof *files)) files[n_files++] = w;
        else return git_fatal ("too many files");
    }
    if (!literally && !bgit_type_valid_name (type))
        return git_fatal ("invalid object type \"%s\"", type);
    if (literally && !bgit_type_printable (type))
        return git_fatal ("invalid object type \"%s\"", type);
    if (!from_stdin && !stdin_paths && n_files == 0) return git_usage (usage);
    if (from_stdin && stdin_paths)
        return git_fatal ("Can't use --stdin-paths with --stdin");

    const char *objects = NULL;
    if (write_object) {
        if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
        objects = ctx->odb.object_dirs[0];
    }

    if (from_stdin) {
        unsigned char *content = NULL;
        size_t len = 0;
        if (bgit_slurp_fd (STDIN_FILENO, &content, &len) < 0)
            return git_fatal ("cannot read standard input: %s", strerror (errno));
        char id[41];
        int rc = bgit_write_object (objects, type, content, len, write_object, id);
        free (content);
        if (rc < 0) return GIT_EXIT_FATAL;
        printf ("%s\n", id);
    }
    if (stdin_paths) {
        char *line = NULL;
        size_t cap = 0;
        ssize_t got;
        clearerr (stdin);
        while ((got = getline (&line, &cap, stdin)) > 0) {
            while (got > 0 && (line[got - 1] == '\n' || line[got - 1] == '\r'))
                line[--got] = '\0';
            if (!got) continue;
            unsigned char *content = NULL;
            size_t len = 0;
            if (bgit_slurp_file (line, &content, &len) < 0) { free (line); return GIT_EXIT_FATAL; }
            char id[41];
            int rc = bgit_write_object (objects, type, content, len, write_object, id);
            free (content);
            if (rc < 0) { free (line); return GIT_EXIT_FATAL; }
            printf ("%s\n", id);
        }
        free (line);
    }
    for (int i = 0; i < n_files; i++) {
        unsigned char *content = NULL;
        size_t len = 0;
        if (bgit_slurp_file (files[i], &content, &len) < 0)
            return GIT_EXIT_FATAL;
        char id[41];
        int rc = bgit_write_object (objects, type, content, len, write_object, id);
        free (content);
        if (rc < 0) return GIT_EXIT_FATAL;
        printf ("%s\n", id);
    }
    return 0;
}

/* ---- update-ref -------------------------------------------------------- */

static int
git_cmd_update_ref (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git update-ref [-m <reason>] (-d <ref> [<oldvalue>] "
                        "| <ref> <newvalue> [<oldvalue>])";
    const char *message = NULL;
    int delete_ref = 0;
    const char *positional[3] = { NULL, NULL, NULL };
    int n = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-d") || !strcmp (w, "--delete")) delete_ref = 1;
        else if (!strcmp (w, "-m") && p->next) { message = p->next->word->word; p = p->next; }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n < 3) positional[n++] = w;
        else return git_usage (usage);
    }
    if (!positional[0]) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* update-ref follows a symbolic ref to the ref it names. */
    const char *refname = positional[0];
    char *target = NULL;
    if (bgit_symref_read (&ctx->repo, refname, &target) == 0) refname = target;

    int rc;
    if (delete_ref) {
        const char *old = positional[1];
        rc = bgit_ref_delete (&ctx->repo, refname, old, message);
    } else {
        if (!positional[1]) { free (target); return git_usage (usage); }
        char new_id[41];
        if (git_resolve (ctx, positional[1], new_id, NULL) < 0) {
            free (target);
            return git_fatal ("%s: not a valid SHA1", positional[1]);
        }
        char old_id[41];
        const char *old = NULL;
        if (positional[2]) {
            if (!*positional[2]) old = "";
            else if (git_resolve (ctx, positional[2], old_id, NULL) < 0) {
                free (target);
                return git_fatal ("%s: not a valid SHA1", positional[2]);
            } else old = old_id;
        }
        char before[41] = "";
        int had_it = bgit_ref_read (&ctx->repo, refname, before) == 0;
        rc = bgit_ref_update (&ctx->repo, refname, new_id, old, message);
        /* A branch HEAD stands on has moved, so HEAD has moved with it:
           git writes both logs, with the same message. */
        if (rc == 0 && (!had_it || strcmp (before, new_id))) {
            char *head_target = NULL;
            if (bgit_symref_read (&ctx->repo, "HEAD", &head_target) == 0 &&
                head_target && !strcmp (head_target, refname))
                bgit_reflog_append (&ctx->repo, "HEAD",
                                    had_it ? before : NULL, new_id,
                                    message ? message : "");
            free (head_target);
        }
    }
    free (target);
    return rc < 0 ? GIT_EXIT_FATAL : 0;
}

/* ---- symbolic-ref ------------------------------------------------------ */

static int
git_cmd_symbolic_ref (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git symbolic-ref [-m <reason>] [-q] [--short] "
                        "<name> [<ref>] | --delete <name>";
    int quiet = 0, shorten = 0, delete_ref = 0;
    const char *message = NULL, *name = NULL, *target = NULL;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "--short")) shorten = 1;
        else if (!strcmp (w, "-d") || !strcmp (w, "--delete")) delete_ref = 1;
        else if (!strcmp (w, "-m") && p->next) { message = p->next->word->word; p = p->next; }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else if (!target) target = w;
        else return git_usage (usage);
    }
    if (!name) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (delete_ref) {
        char path[4096];
        if (bgit_ref_path (&ctx->repo, name, path, sizeof path) < 0)
            return git_fatal ("ref name too long: %s", name);
        if (unlink (path) < 0)
            return git_fatal ("cannot delete %s: %s", name, strerror (errno));
        return 0;
    }
    if (target) {
        if (bgit_symref_write (&ctx->repo, name, target, message) < 0)
            return GIT_EXIT_FATAL;
        return 0;
    }
    char *value = NULL;
    int rc = bgit_symref_read (&ctx->repo, name, &value);
    if (rc != 0) {
        if (quiet) return 1;
        return git_fatal ("ref %s is not a symbolic ref", name);
    }
    const char *print = value;
    if (shorten && !strncmp (value, "refs/heads/", 11)) print = value + 11;
    printf ("%s\n", print);
    free (value);
    return 0;
}

/* ---- show-ref ---------------------------------------------------------- */

static int
git_cmd_show_ref (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git show-ref [--head] [--heads] [--tags] [-q] "
                        "[--verify] [<pattern>...]";
    int head = 0, heads = 0, tags = 0, quiet = 0, verify = 0;
    const char *patterns[32];
    int n_patterns = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--head")) head = 1;
        else if (!strcmp (w, "--heads")) heads = 1;
        else if (!strcmp (w, "--tags")) tags = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "--verify")) verify = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_patterns < (int) (sizeof patterns / sizeof *patterns))
            patterns[n_patterns++] = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    int found = 0;
    if (verify) {
        for (int i = 0; i < n_patterns; i++) {
            char id[41];
            if (bgit_ref_read (&ctx->repo, patterns[i], id) != 0) {
                if (!quiet)
                    fprintf (stderr, "fatal: '%s' - not a valid ref\n", patterns[i]);
                return GIT_EXIT_FATAL;
            }
            if (!quiet) printf ("%s %s\n", id, patterns[i]);
            found = 1;
        }
        return found ? 0 : 1;
    }

    if (head) {
        char id[41];
        if (bgit_ref_resolve (&ctx->repo, "HEAD", id, NULL) == 0) {
            if (!quiet) printf ("%s HEAD\n", id);
            found = 1;
        }
    }
    const char *prefix = heads && !tags ? "refs/heads/"
                       : tags && !heads ? "refs/tags/" : "";
    bgit_ref *refs = NULL;
    size_t count = 0;
    if (bgit_refs_list (&ctx->repo, prefix, &refs, &count) < 0)
        return git_fatal ("cannot read refs");
    for (size_t i = 0; i < count; i++) {
        if (heads && tags &&
            strncmp (refs[i].name, "refs/heads/", 11) != 0 &&
            strncmp (refs[i].name, "refs/tags/", 10) != 0)
            continue;
        if (n_patterns) {
            int matched = 0;
            for (int j = 0; j < n_patterns && !matched; j++) {
                size_t plen = strlen (patterns[j]);
                size_t nlen = strlen (refs[i].name);
                /* git matches a pattern against whole path components from
                   the right: "main" matches refs/heads/main. */
                if (nlen >= plen && strcmp (refs[i].name + nlen - plen, patterns[j]) == 0 &&
                    (nlen == plen || refs[i].name[nlen - plen - 1] == '/'))
                    matched = 1;
            }
            if (!matched) continue;
        }
        if (!quiet) printf ("%s %s\n", refs[i].sha, refs[i].name);
        found = 1;
    }
    bgit_refs_free (refs, count);
    return found ? 0 : 1;
}

/* ---- for-each-ref ------------------------------------------------------ */

static void
git_format_ref (git_context *ctx, const bgit_ref *ref, const char *format)
{
    for (const char *p = format; *p; p++) {
        if (*p != '%') { putchar (*p); continue; }
        if (p[1] == '%') { putchar ('%'); p++; continue; }
        if (p[1] != '(') { putchar (*p); continue; }
        const char *close = strchr (p, ')');
        if (!close) { putchar (*p); continue; }
        size_t len = (size_t) (close - p - 2);
        char field[64];
        if (len >= sizeof field) { p = close; continue; }
        memcpy (field, p + 2, len);
        field[len] = '\0';
        p = close;
        if (!strcmp (field, "refname")) {
            fputs (ref->name, stdout);
        } else if (!strcmp (field, "refname:short") || !strcmp (field, "refname:strip=2")) {
            const char *shortened = ref->name;
            static const char *const strip[] = {
                "refs/heads/", "refs/tags/", "refs/remotes/", NULL
            };
            for (int i = 0; strip[i]; i++)
                if (!strncmp (ref->name, strip[i], strlen (strip[i])))
                    shortened = ref->name + strlen (strip[i]);
            fputs (shortened, stdout);
        } else if (!strcmp (field, "objectname")) {
            fputs (ref->sha, stdout);
        } else if (!strcmp (field, "objectname:short")) {
            char abbreviated[41];
            git_abbrev (ctx, ref->sha, 7, abbreviated, sizeof abbreviated);
            fputs (abbreviated, stdout);
        } else if (!strcmp (field, "objecttype") || !strcmp (field, "objectsize")) {
            enum bgit_type type;
            unsigned char *data = NULL;
            size_t size = 0;
            if (bgit_odb_read (&ctx->odb, ref->sha, &type, &data, &size) == 0) {
                if (!strcmp (field, "objecttype")) fputs (bgit_type_name (type), stdout);
                else printf ("%zu", size);
                free (data);
            }
        }
    }
    putchar ('\n');
}

/* ---- ordering a listing of refs ---------------------------------------- */

static long long git_header_date (const char *data, size_t len,
                                  const char *field);
static long long git_object_date (git_context *ctx, const char *sha,
                                  const char *field);
static long long git_commit_date (git_context *ctx, const char *sha);

/* strverscmp's rules, which is what git's version sort follows: a run of
   digits compares as a number, a run with a leading zero as a fraction, and
   anything else byte by byte. */
static int
git_version_cmp (const char *s1, const char *s2)
{
    enum { S_N = 0, S_I = 3, S_F = 6, S_Z = 9 };
    enum { CMP = 2, LEN = 3 };
    static const unsigned char next_state[] = {
        /* state    x    d    0  */
        /* S_N */  S_N, S_I, S_Z,
        /* S_I */  S_N, S_I, S_I,
        /* S_F */  S_N, S_F, S_F,
        /* S_Z */  S_N, S_F, S_Z
    };
    static const signed char result_type[] = {
        /* state   x/x  x/d  x/0  d/x  d/d  d/0  0/x  0/d  0/0  */
        /* S_N */  CMP, CMP, CMP, CMP, LEN, CMP, CMP, CMP, CMP,
        /* S_I */  CMP,  -1,  -1,  +1, LEN, LEN,  +1, LEN, LEN,
        /* S_F */  CMP, CMP, CMP, CMP, CMP, CMP, CMP, CMP, CMP,
        /* S_Z */  CMP,  +1,  +1,  -1, CMP, CMP,  -1, CMP, CMP
    };
    const unsigned char *p1 = (const unsigned char *) s1;
    const unsigned char *p2 = (const unsigned char *) s2;
    if (p1 == p2) return 0;
    unsigned char c1 = *p1++, c2 = *p2++;
    int state = S_N + ((c1 == '0') + (isdigit (c1) != 0));
    int diff;
    while ((diff = c1 - c2) == 0) {
        if (!c1) return diff;
        state = next_state[state];
        c1 = *p1++;
        c2 = *p2++;
        state += (c1 == '0') + (isdigit (c1) != 0);
    }
    state = result_type[state * 3 + ((c2 == '0') + (isdigit (c2) != 0))];
    switch (state) {
    case CMP:
        return diff;
    case LEN:
        while (isdigit (*p1++))
            if (!isdigit (*p2++)) return 1;
        return isdigit (*p2) ? -1 : diff;
    default:
        return state;
    }
}

/* One of git's sort keys. A leading '-' turns the comparison round. */
struct git_ref_key {
    const char *name;
    int reverse;
};

/* A ref and the dates a sort might ask it for, read once so that the
   comparison need not read the object again. */
struct git_ref_order {
    bgit_ref ref;
    long long committer, author, tagger;
    char type[16];
};

static const struct git_ref_key *git_sort_keys;
static int git_n_sort_keys;

/* Is this one of the keys this build knows? */
static int
git_ref_key_known (const char *name)
{
    static const char *const known[] = {
        "refname", "objectname", "objecttype", "committerdate", "authordate",
        "taggerdate", "creatordate", "version:refname", "v:refname", NULL
    };
    for (int i = 0; known[i]; i++)
        if (!strcmp (name, known[i])) return 1;
    return 0;
}

static long long
git_ref_key_date (const struct git_ref_order *o, const char *key)
{
    if (!strcmp (key, "committerdate")) return o->committer;
    if (!strcmp (key, "authordate")) return o->author;
    if (!strcmp (key, "taggerdate")) return o->tagger;
    /* A tag has a date of its own; anything else is dated by its commit. */
    if (!strcmp (key, "creatordate"))
        return o->tagger ? o->tagger : o->committer;
    return 0;
}

static int
git_ref_order_cmp (const void *pa, const void *pb)
{
    const struct git_ref_order *a = pa, *b = pb;
    for (int k = 0; k < git_n_sort_keys; k++) {
        const char *key = git_sort_keys[k].name;
        int order = 0;
        if (!strcmp (key, "refname")) order = strcmp (a->ref.name, b->ref.name);
        else if (!strcmp (key, "objectname"))
            order = strcmp (a->ref.sha, b->ref.sha);
        else if (!strcmp (key, "objecttype")) order = strcmp (a->type, b->type);
        else if (!strcmp (key, "version:refname") || !strcmp (key, "v:refname"))
            order = git_version_cmp (a->ref.name, b->ref.name);
        else {
            long long da = git_ref_key_date (a, key);
            long long db = git_ref_key_date (b, key);
            order = da < db ? -1 : da > db ? 1 : 0;
        }
        if (order) return git_sort_keys[k].reverse ? -order : order;
    }
    /* Whatever the keys leave undecided, the name settles, as git's does. */
    return strcmp (a->ref.name, b->ref.name);
}

/* Put a listing of refs in the order KEYS asks for. The last key given is
   the one that matters most, which is git's rule; the array is rewritten in
   place. Returns 0, or -1 with nothing changed. */
static int
git_sort_refs (git_context *ctx, bgit_ref *refs, size_t n,
               const struct git_ref_key *keys, int n_keys)
{
    if (!n_keys || n < 2) return 0;
    struct git_ref_order *order = calloc (n, sizeof *order);
    if (!order) return -1;
    for (size_t i = 0; i < n; i++) {
        order[i].ref = refs[i];
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        if (bgit_odb_read (&ctx->odb, refs[i].sha, &type, &data, &len) == 0) {
            snprintf (order[i].type, sizeof order[i].type, "%s",
                      type == BGIT_COMMIT ? "commit" : type == BGIT_TREE ? "tree"
                      : type == BGIT_TAG ? "tag" : "blob");
            if (type == BGIT_TAG)
                order[i].tagger = git_header_date ((const char *) data, len,
                                                   "tagger ");
            free (data);
        }
        char commit[41];
        if (bgit_peel_to_type (&ctx->odb, refs[i].sha, BGIT_COMMIT, commit) == 0) {
            order[i].committer = git_commit_date (ctx, commit);
            order[i].author = git_object_date (ctx, commit, "author ");
        }
    }
    /* The keys are given in order of increasing importance. */
    struct git_ref_key reversed[8];
    int n_reversed = 0;
    for (int k = n_keys - 1; k >= 0 && n_reversed < 8; k--)
        reversed[n_reversed++] = keys[k];
    git_sort_keys = reversed;
    git_n_sort_keys = n_reversed;
    qsort (order, n, sizeof *order, git_ref_order_cmp);
    git_sort_keys = NULL;
    git_n_sort_keys = 0;
    for (size_t i = 0; i < n; i++) refs[i] = order[i].ref;
    free (order);
    return 0;
}

static int
git_cmd_for_each_ref (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git for-each-ref [--count=<n>] [--format=<format>] "
                        "[--sort=<key>] [<pattern>...]";
    const char *format = "%(objectname) %(objecttype)\t%(refname)";
    long limit = -1;
    const char *patterns[32];
    int n_patterns = 0;
    struct git_ref_key keys[8];
    int n_keys = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strncmp (w, "--format=", 9)) format = w + 9;
        else if (!strcmp (w, "--format") && p->next) { format = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "--count=", 8)) limit = atol (w + 8);
        else if (!strncmp (w, "--sort=", 7) || (!strcmp (w, "--sort") && p->next)) {
            const char *key = w[6] == '=' ? w + 7 : (p = p->next)->word->word;
            if (n_keys >= (int) (sizeof keys / sizeof *keys))
                return git_fatal ("too many sort keys");
            keys[n_keys].reverse = *key == '-';
            if (keys[n_keys].reverse) key++;
            if (!git_ref_key_known (key))
                return git_fatal ("unknown field name: %s", key);
            keys[n_keys++].name = key;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_patterns < (int) (sizeof patterns / sizeof *patterns))
            patterns[n_patterns++] = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    bgit_ref *refs = NULL;
    size_t count = 0;
    if (bgit_refs_list (&ctx->repo, "", &refs, &count) < 0)
        return git_fatal ("cannot read refs");
    if (git_sort_refs (ctx, refs, count, keys, n_keys) < 0) {
        bgit_refs_free (refs, count);
        return GIT_EXIT_FATAL;
    }
    long printed = 0;
    for (size_t i = 0; i < count; i++) {
        if (n_patterns) {
            int matched = 0;
            for (int j = 0; j < n_patterns && !matched; j++) {
                size_t plen = strlen (patterns[j]);
                if (!strncmp (refs[i].name, patterns[j], plen) &&
                    (refs[i].name[plen] == '\0' || refs[i].name[plen] == '/' ||
                     patterns[j][plen - 1] == '/'))
                    matched = 1;
            }
            if (!matched) continue;
        }
        if (limit >= 0 && printed >= limit) break;
        git_format_ref (ctx, &refs[i], format);
        printed++;
    }
    bgit_refs_free (refs, count);
    return 0;
}

/* ---- reflog ------------------------------------------------------------ */

/* One reflog entry written the way --format= asks. */
static void git_reflog_formatted (git_context *ctx, const char *format,
                                  const char *ref, size_t number,
                                  const char *id, const char *message);

static int
git_cmd_reflog (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git reflog [show] [--format=<format>] [-<n>] "
                        "[<ref>]";
    const char *ref = NULL, *format = NULL;
    long limit = -1;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "show")) continue;
        if (!strncmp (w, "--format=", 9)) { format = w + 9; continue; }
        if (!strncmp (w, "--pretty=", 9)) { format = w + 9; continue; }
        if (!strcmp (w, "-n") && p->next) {
            limit = atol ((p = p->next)->word->word);
            continue;
        }
        if (!strncmp (w, "--max-count=", 12)) { limit = atol (w + 12); continue; }
        if (w[0] == '-' && git_all_digits (w + 1)) { limit = atol (w + 1); continue; }
        if (w[0] == '-' && w[1]) return git_usage (usage);
        if (!ref) ref = w;
        else return git_usage (usage);
    }
    if (!ref) ref = "HEAD";
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* A name like "main" means refs/heads/main for a reflog. */
    char resolved[4096];
    snprintf (resolved, sizeof resolved, "%s", ref);
    char probe[4096];
    if (strcmp (ref, "HEAD") != 0 && strncmp (ref, "refs/", 5) != 0 &&
        snprintf (probe, sizeof probe, "refs/heads/%s", ref) < (int) sizeof probe) {
        char id[41];
        if (bgit_ref_read (&ctx->repo, probe, id) == 0)
            snprintf (resolved, sizeof resolved, "%s", probe);
    }

    char **lines = NULL;
    size_t n = 0;
    int rc = bgit_reflog_lines (&ctx->repo, resolved, &lines, &n);
    if (rc < 0) return git_fatal ("cannot read the reflog for %s", ref);
    if (rc > 0) return 0;   /* no reflog: git prints nothing */

    const char *display = resolved;
    static const char *const strip[] = { "refs/heads/", "refs/remotes/", NULL };
    for (int i = 0; strip[i]; i++)
        if (!strncmp (display, strip[i], strlen (strip[i])))
            display = display + strlen (strip[i]);

    /* Newest first, numbered from 0, as git shows them. */
    long shown = 0;
    for (size_t i = n; i > 0; i--) {
        if (limit >= 0 && shown >= limit) break;
        shown++;
        const char *line = lines[i - 1];
        char new_id[41] = "";
        const char *message = strchr (line, '\t');
        if (strlen (line) >= 82) memcpy (new_id, line + 41, 40);
        new_id[40] = '\0';
        char abbreviated[41];
        git_abbrev (ctx, new_id, 7, abbreviated, sizeof abbreviated);
        if (!format) {
            printf ("%s %s@{%zu}: %s\n", abbreviated, display, n - i,
                    message ? message + 1 : "");
            continue;
        }
        git_reflog_formatted (ctx, format, display, n - i, new_id,
                              message ? message + 1 : "");
    }
    for (size_t i = 0; i < n; i++) free (lines[i]);
    free (lines);
    return 0;
}

/* ---- the index, trees, and commits ------------------------------------- */

/* The index file: GIT_INDEX_FILE, or the repository's own. */
static int
git_index_path (git_context *ctx, char *out, size_t outsz)
{
    const char *env = getenv ("GIT_INDEX_FILE");
    if (env && *env)
        return snprintf (out, outsz, "%s", env) < (int) outsz ? 0 : -1;
    return snprintf (out, outsz, "%s/index", ctx->repo.git_dir) < (int) outsz
           ? 0 : -1;
}

static int
git_index_load (git_context *ctx, bgit_index_entry **entries, size_t *n)
{
    char path[4096];
    *entries = NULL;
    *n = 0;
    if (git_index_path (ctx, path, sizeof path) < 0) return -1;
    if (access (path, R_OK) != 0) return 0;      /* no index yet */
    return bgit_index_read (path, entries, n);
}

static int
git_index_store (git_context *ctx, bgit_index_entry *entries, size_t n)
{
    char path[4096];
    if (git_index_path (ctx, path, sizeof path) < 0) return -1;
    if (n > 1) qsort (entries, n, sizeof *entries, bgit_index_path_cmp);
    return bgit_index_write (path, entries, n);
}

/* Where PATH sits in the index, or where it would go. The index is kept in
   path order — that is how it is read and how it is written — so finding a
   path in it is a search and not a walk: a command that looks up every path
   in a working tree of a few thousand files does nothing else otherwise. */
static size_t
git_index_place (const bgit_index_entry *entries, size_t n, const char *path)
{
    size_t low = 0, high = n;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (strcmp (entries[mid].path, path) < 0) low = mid + 1;
        else high = mid;
    }
    return low;
}

/* PATH's entry, or NULL. With several stages of it, the first. */
static bgit_index_entry *
git_index_lookup (bgit_index_entry *entries, size_t n, const char *path)
{
    size_t at = git_index_place (entries, n, path);
    return at < n && !strcmp (entries[at].path, path) ? &entries[at] : NULL;
}

/* Replace or insert one path in the index, keeping it in path order. */
static int
git_index_put (bgit_index_entry **entries, size_t *n, size_t *cap,
               const bgit_index_entry *entry)
{
    size_t at = git_index_place (*entries, *n, entry->path);
    size_t past = at;
    while (past < *n && !strcmp ((*entries)[past].path, entry->path)) past++;
    if (past > at) {
        /* Staging a path that was in dispute settles it: the conflict's
           stages go, and one stage-zero entry takes their place. */
        int unmerged = 0;
        for (size_t i = at; i < past; i++)
            if (((*entries)[i].flags >> 12) & 3) unmerged = 1;
        if (!unmerged) {
            char *keep = (*entries)[at].path;
            (*entries)[at] = *entry;
            (*entries)[at].path = keep;
            free (entry->path);
            return 0;
        }
        for (size_t i = at; i < past; i++) free ((*entries)[i].path);
        memmove (&(*entries)[at], &(*entries)[past],
                 (*n - past) * sizeof **entries);
        *n -= past - at;
    }
    if (*n == *cap) {
        size_t next = *cap ? *cap * 2 : 32;
        bgit_index_entry *grown = realloc (*entries, next * sizeof *grown);
        if (!grown) return -1;
        *entries = grown;
        *cap = next;
    }
    memmove (&(*entries)[at + 1], &(*entries)[at],
             (*n - at) * sizeof **entries);
    (*entries)[at] = *entry;
    (*n)++;
    return 0;
}

static int
git_cmd_update_index (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git update-index [--add] [--remove] "
                        "[--cacheinfo <mode>,<object>,<path>] [--index-info] "
                        "[--] [<file>...]";
    int add = 0, remove = 0, index_info = 0;
    const char *cacheinfo[3] = { NULL, NULL, NULL };
    int n_cacheinfo = 0;
    const char *files[64];
    int n_files = 0;
    int no_more_options = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more_options && !strcmp (w, "--")) { no_more_options = 1; continue; }
        if (!no_more_options && !strcmp (w, "--add")) add = 1;
        else if (!no_more_options && !strcmp (w, "--remove")) remove = 1;
        else if (!no_more_options && !strcmp (w, "--replace")) { /* implied */ }
        else if (!no_more_options && !strcmp (w, "--index-info")) index_info = 1;
        else if (!no_more_options && !strcmp (w, "--cacheinfo")) {
            /* Either one comma-separated argument or three separate ones. */
            if (p->next && strchr (p->next->word->word, ',')) {
                char copy[4096];
                snprintf (copy, sizeof copy, "%s", p->next->word->word);
                p = p->next;
                char *save = NULL;
                for (char *field = strtok_r (copy, ",", &save);
                     field && n_cacheinfo < 3;
                     field = strtok_r (NULL, ",", &save))
                    cacheinfo[n_cacheinfo++] = strdup (field);
            } else {
                for (int i = 0; i < 3; i++) {
                    if (!p->next) return git_usage (usage);
                    p = p->next;
                    cacheinfo[n_cacheinfo++] = p->word->word;
                }
            }
        }
        else if (!no_more_options && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_files < (int) (sizeof files / sizeof *files)) files[n_files++] = w;
        else return git_fatal ("too many files");
    }
    if (n_cacheinfo && n_cacheinfo != 3) return git_usage (usage);
    if (!n_cacheinfo && !index_info && !n_files) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    bgit_index_entry *entries = NULL;
    size_t n = 0, cap = 0;
    if (git_index_load (ctx, &entries, &n) < 0) return GIT_EXIT_FATAL;
    cap = n;
    int status = 0;

    if (n_cacheinfo == 3) {
        bgit_index_entry entry;
        memset (&entry, 0, sizeof entry);
        if (bgit_index_parse_mode (cacheinfo[0], &entry.mode) < 0 ||
            bgit_hex_to_sha (cacheinfo[1], entry.sha) < 0) {
            status = git_fatal ("git update-index: --cacheinfo cannot add %s",
                                cacheinfo[2]);
            goto done;
        }
        entry.path = strdup (cacheinfo[2]);
        size_t len = strlen (cacheinfo[2]);
        entry.flags = (uint16_t) (len > 0xFFF ? 0xFFF : len);
        if (!entry.path || git_index_put (&entries, &n, &cap, &entry) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
    }

    if (index_info) {
        char *line = NULL;
        size_t line_cap = 0;
        clearerr (stdin);
        while (getline (&line, &line_cap, stdin) > 0) {
            bgit_index_entry entry;
            int is_remove = 0;
            if (bgit_index_info_line_to_entry (line, &entry, &is_remove) < 0) {
                free (line);
                status = git_fatal ("malformed --index-info line");
                goto done;
            }
            if (is_remove) {
                bgit_index_remove_path (&entries, &n, entry.path);
                free (entry.path);
                continue;
            }
            if (git_index_put (&entries, &n, &cap, &entry) < 0) {
                free (line);
                status = GIT_EXIT_FATAL;
                goto done;
            }
        }
        free (line);
    }

    for (int i = 0; i < n_files; i++) {
        struct stat st;
        if (stat (files[i], &st) < 0) {
            if (remove) {
                bgit_index_remove_path (&entries, &n, files[i]);
                continue;
            }
            status = git_fatal ("unable to stat '%s': %s", files[i],
                                strerror (errno));
            goto done;
        }
        unsigned char *content = NULL;
        size_t len = 0;
        if (bgit_slurp_file (files[i], &content, &len) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        char id[41];
        int rc = bgit_write_object (ctx->odb.object_dirs[0], "blob", content,
                                   len, 1, id);
        free (content);
        if (rc < 0) { status = GIT_EXIT_FATAL; goto done; }
        bgit_index_entry entry;
        memset (&entry, 0, sizeof entry);
        bgit_index_entry_set_stat (&entry, &st);
        /* git stores 100644, or 100755 when the file is executable. */
        entry.mode = (st.st_mode & 0111) ? 0100755 : 0100644;
        if (bgit_hex_to_sha (id, entry.sha) < 0) { status = GIT_EXIT_FATAL; goto done; }
        entry.path = strdup (files[i]);
        size_t plen = strlen (files[i]);
        entry.flags = (uint16_t) (plen > 0xFFF ? 0xFFF : plen);
        if (!entry.path || git_index_put (&entries, &n, &cap, &entry) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        (void) add;
    }

    if (git_index_store (ctx, entries, n) < 0) status = GIT_EXIT_FATAL;
done:
    bgit_index_free_entries (entries, n);
    return status;
}

/* Does one of the paths named on the command line cover this one? A
   directory covers everything under it, as git's pathspecs do. */
static int
git_path_named (const char *path, const char *const *patterns, int n)
{
    if (!n) return 1;
    for (int i = 0; i < n; i++) {
        size_t len = strlen (patterns[i]);
        if (!len) continue;
        if (!strcmp (path, patterns[i])) return 1;
        if (!strncmp (path, patterns[i], len) &&
            (patterns[i][len - 1] == '/' || path[len] == '/'))
            return 1;
    }
    return 0;
}

/* One of ls-files' lines: the path, with the index's record of it when a
   stage listing was asked for, behind the letter that says what it is. */
static void
git_ls_line (const git_context *ctx, const bgit_index_entry *entry,
             const char *tag, int stage, char end, int full_name)
{
    char here[8192];
    const char *path = full_name ? entry->path
        : git_path_from_here (ctx, entry->path, here, sizeof here);
    char hex[41];
    bgit_sha_to_hex (entry->sha, hex);
    /* A name is quoted where it needs it, unless the lines end in NUL and
       there is nothing to be confused with. */
    char quoted[8192];
    const char *shown = end == '\0' ? path
        : bgit_quote_path (path, quoted, sizeof quoted);
    if (stage)
        printf ("%s%o %s %d\t%s%c", tag, entry->mode, hex,
                (entry->flags >> 12) & 0x3, shown, end);
    else
        printf ("%s%s%c", tag, shown, end);
}

/* A pathspec as it was written from where the command was run, turned into
   one the repository would know: the place in front of it, and any . or ..
   in it worked out. Returns 0 and fills OUT, or -1. */
static int
git_path_join_prefix (const char *prefix, const char *spec, char *out,
                      size_t size)
{
    char joined[8192];
    if ((size_t) snprintf (joined, sizeof joined, "%s%s", prefix, spec) >=
        sizeof joined)
        return -1;
    char *parts[256];
    int n = 0;
    for (char *at = joined; *at; ) {
        char *slash = strchr (at, '/');
        if (slash) *slash = '\0';
        if (!strcmp (at, "..")) {
            if (n) n--;
        } else if (*at && strcmp (at, ".")) {
            if (n == (int) (sizeof parts / sizeof *parts)) return -1;
            parts[n++] = at;
        }
        if (!slash) break;
        at = slash + 1;
    }
    size_t used = 0;
    out[0] = '\0';
    for (int i = 0; i < n; i++) {
        int wrote = snprintf (out + used, size - used, "%s%s",
                              i ? "/" : "", parts[i]);
        if (wrote < 0 || (size_t) wrote >= size - used) return -1;
        used += (size_t) wrote;
    }
    return 0;
}

/* Every pathspec a command was given, read from where the command was run.
   The rewritten ones live here, since a command reads its paths once. */
static char git_here_specs[64][4096];

static int
git_paths_from_here (const git_context *ctx, const char **paths, int n)
{
    if (!*ctx->prefix) return 0;
    if (n > (int) (sizeof git_here_specs / sizeof git_here_specs[0])) return -1;
    for (int i = 0; i < n; i++) {
        if (git_path_join_prefix (ctx->prefix, paths[i], git_here_specs[i],
                                  sizeof git_here_specs[i]) < 0)
            return -1;
        paths[i] = git_here_specs[i];
    }
    return 0;
}

static int
git_cmd_ls_files (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git ls-files [-c] [-d] [-m] [-o] [-i] [-u] [-t] "
                        "[-s | --stage] [--directory] [--exclude-standard] "
                        "[-z] [--full-name] [--] [<file>...]";
    int stage = 0, zero = 0, no_more_options = 0, full_name = 0;
    int cached = 0, deleted = 0, modified = 0, others = 0, only_ignored = 0;
    int unmerged = 0, tags = 0, directory = 0, exclude = 0;
    const char *patterns[32];
    int n_patterns = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more_options && !strcmp (w, "--")) { no_more_options = 1; continue; }
        if (!no_more_options && w[0] == '-' && w[1] && w[1] != '-') {
            /* git takes these one at a time or run together. */
            for (const char *flag = w + 1; *flag; flag++) {
                switch (*flag) {
                case 'c': cached = 1; break;
                case 'd': deleted = 1; break;
                case 'm': modified = 1; break;
                case 'o': others = 1; break;
                case 'i': only_ignored = 1; break;
                case 'u': unmerged = 1; break;
                case 't': tags = 1; break;
                case 's': stage = 1; break;
                case 'z': zero = 1; break;
                default: return git_usage (usage);
                }
            }
        }
        else if (!no_more_options && !strcmp (w, "--cached")) cached = 1;
        else if (!no_more_options && !strcmp (w, "--deleted")) deleted = 1;
        else if (!no_more_options && !strcmp (w, "--modified")) modified = 1;
        else if (!no_more_options && !strcmp (w, "--others")) others = 1;
        else if (!no_more_options && !strcmp (w, "--ignored")) only_ignored = 1;
        else if (!no_more_options && !strcmp (w, "--unmerged")) unmerged = 1;
        else if (!no_more_options && !strcmp (w, "--stage")) stage = 1;
        else if (!no_more_options && !strcmp (w, "--directory")) directory = 1;
        else if (!no_more_options && !strcmp (w, "--exclude-standard")) exclude = 1;
        else if (!no_more_options && !strcmp (w, "--full-name")) full_name = 1;
        else if (!no_more_options && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_patterns < (int) (sizeof patterns / sizeof *patterns))
            patterns[n_patterns++] = w;
        else return git_fatal ("too many paths");
    }
    /* -i says which of the others to list, so one of them has to have been
       asked for: the default does not count, and is settled after. */
    if (only_ignored) {
        if (!others && !cached)
            return git_fatal ("ls-files -i must be used with either -o or -c");
        if (!exclude)
            return git_fatal ("ls-files --ignored needs some exclude pattern");
    }
    /* -s asks for the index as well as for the form of the line; -u asks
       for the form alone. With nothing named at all, git lists the index. */
    if (stage) cached = 1;
    if (!cached && !deleted && !modified && !others && !unmerged) cached = 1;
    int stage_form = stage || unmerged;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* Run under a directory of the working tree, git lists what is there
       and names it from there: the place stands for a pathspec of its own,
       and a pathspec that was named is read from there too. --full-name
       names everything from the top instead. */
    char held[32][4096];
    for (int i = 0; i < n_patterns && *ctx->prefix; i++)
        if (git_path_join_prefix (ctx->prefix, patterns[i], held[i],
                                  sizeof held[i]) == 0)
            patterns[i] = held[i];
    char under[4096] = "";
    if (*ctx->prefix && !n_patterns) {
        snprintf (under, sizeof under, "%s", ctx->prefix);
        under[strlen (under) - 1] = '\0';     /* without the slash */
        patterns[n_patterns++] = under;
    }


    bgit_index_entry *entries = NULL;
    size_t n = 0;
    if (git_index_load (ctx, &entries, &n) < 0) return GIT_EXIT_FATAL;
    char end = zero ? '\0' : '\n';

    /* git names what it does not track first, then walks the index once. */
    if (others) {
        char **paths = NULL;
        size_t n_others = 0;
        if (bgit_worktree_others (&ctx->repo, &ctx->cfg, entries, n, directory,
                                  exclude, only_ignored, &paths,
                                  &n_others) < 0) {
            bgit_index_free_entries (entries, n);
            return git_fatal ("cannot read the working tree");
        }
        for (size_t i = 0; i < n_others; i++)
            if (git_path_named (paths[i], patterns, n_patterns)) {
                char quoted[8192], here[8192];
                const char *path = full_name ? paths[i]
                    : git_path_from_here (ctx, paths[i], here, sizeof here);
                const char *shown = end == '\0' ? path
                    : bgit_quote_path (path, quoted, sizeof quoted);
                printf ("%s%s%c", tags ? "? " : "", shown, end);
            }
        bgit_others_free (paths, n_others);
    }

    bgit_ignore ignore;
    int have_ignore = only_ignored &&
                      bgit_ignore_load (&ignore, &ctx->repo, &ctx->cfg) == 0;
    if (only_ignored && !have_ignore) {
        bgit_index_free_entries (entries, n);
        return git_fatal ("cannot read the exclude patterns");
    }
    for (size_t i = 0; i < n && (cached || deleted || modified || unmerged); i++) {
        if (!git_path_named (entries[i].path, patterns, n_patterns)) continue;
        int entry_stage = (entries[i].flags >> 12) & 0x3;
        if (unmerged && !entry_stage) continue;
        if (only_ignored) {
            const bgit_ignore_rule *rule = NULL;
            if (!bgit_ignore_match (&ignore, entries[i].path, 0, &rule)) continue;
        }
        /* What the path is, then what has happened to it since: git writes
           the index's own line first, then removal, then change. */
        if (cached || unmerged)
            git_ls_line (ctx, &entries[i],
                         tags ? (entry_stage ? "M " : "H ") : "", stage_form,
                         end, full_name);
        if (!deleted && !modified) continue;
        char full[4096];
        if ((size_t) snprintf (full, sizeof full, "%s/%s",
                               ctx->repo.work_tree ? ctx->repo.work_tree : ".",
                               entries[i].path) >= sizeof full)
            continue;
        struct stat st;
        int gone = lstat (full, &st) < 0;
        if (deleted && gone)
            git_ls_line (ctx, &entries[i], tags ? "R " : "", stage_form, end,
                         full_name);
        if (modified &&
            (gone || !bgit_worktree_matches (&ctx->odb, full, &entries[i], &st)))
            git_ls_line (ctx, &entries[i], tags ? "C " : "", stage_form, end,
                         full_name);
    }
    if (have_ignore) bgit_ignore_release (&ignore);
    bgit_index_free_entries (entries, n);
    return 0;
}

static int
git_cmd_write_tree (git_context *ctx, WORD_LIST *args)
{
    if (args) return git_usage ("git write-tree");
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    bgit_index_entry *entries = NULL;
    size_t n = 0;
    if (git_index_load (ctx, &entries, &n) < 0) return GIT_EXIT_FATAL;
    char tree[41];
    int rc = bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], entries, n, tree);
    bgit_index_free_entries (entries, n);
    if (rc < 0) return GIT_EXIT_FATAL;
    printf ("%s\n", tree);
    return 0;
}

static int
git_cmd_read_tree (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git read-tree <tree-ish>";
    const char *name = NULL;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (w[0] == '-' && w[1]) return git_usage (usage);
        if (name) return git_usage (usage);
        name = w;
    }
    if (!name) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char id[41];
    if (git_resolve (ctx, name, id, NULL) < 0)
        return git_fatal ("Not a valid object name %s", name);
    char tree[41];
    if (bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0)
        return git_fatal ("Not a valid tree object name %s", name);
    bgit_index_entry *entries = NULL;
    size_t n = 0;
    if (bgit_read_tree (&ctx->odb, tree, &entries, &n) < 0)
        return git_fatal ("cannot read tree %s", tree);
    int rc = git_index_store (ctx, entries, n);
    bgit_index_free_entries (entries, n);
    return rc < 0 ? GIT_EXIT_FATAL : 0;
}

static int
git_cmd_commit_tree (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git commit-tree <tree> [(-p <parent>)...] "
                        "[(-m <message>)...] [-F <file>]";
    const char *tree_name = NULL;
    const char *parents[BGIT_MAX_PARENTS];
    int n_parents = 0;
    const char *messages[16];
    int n_messages = 0;
    const char *message_file = NULL;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-p") && p->next) {
            if (n_parents >= BGIT_MAX_PARENTS) return git_fatal ("too many parents");
            parents[n_parents++] = p->next->word->word;
            p = p->next;
        } else if (!strcmp (w, "-m") && p->next) {
            if (n_messages >= (int) (sizeof messages / sizeof *messages))
                return git_fatal ("too many messages");
            messages[n_messages++] = p->next->word->word;
            p = p->next;
        } else if (!strcmp (w, "-F") && p->next) {
            message_file = p->next->word->word;
            p = p->next;
        } else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!tree_name) tree_name = w;
        else return git_usage (usage);
    }
    if (!tree_name) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char tree_id[41], tree[41];
    if (git_resolve (ctx, tree_name, tree_id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, tree_id, BGIT_TREE, tree) < 0)
        return git_fatal ("not a valid object name %s", tree_name);

    char resolved_parents[BGIT_MAX_PARENTS][41];
    for (int i = 0; i < n_parents; i++) {
        char id[41];
        if (git_resolve (ctx, parents[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, resolved_parents[i]) < 0)
            return git_fatal ("not a valid object name %s", parents[i]);
    }

    char author[1024], committer[1024];
    {
        int trouble = git_identities (ctx, author, sizeof author, committer,
                                      sizeof committer);
        if (trouble) return trouble;
    }

    /* Body: headers, a blank line, then the message. */
    size_t cap = 4096, len = 0;
    char *body = malloc (cap);
    if (!body) return GIT_EXIT_FATAL;
#define GIT_APPEND(...) do { \
    for (;;) { \
        int wrote = snprintf (body + len, cap - len, __VA_ARGS__); \
        if (wrote < 0) { free (body); return GIT_EXIT_FATAL; } \
        if ((size_t) wrote < cap - len) { len += (size_t) wrote; break; } \
        cap *= 2; \
        char *grown = realloc (body, cap); \
        if (!grown) { free (body); return GIT_EXIT_FATAL; } \
        body = grown; \
    } \
} while (0)
    GIT_APPEND ("tree %s\n", tree);
    for (int i = 0; i < n_parents; i++) GIT_APPEND ("parent %s\n", resolved_parents[i]);
    GIT_APPEND ("author %s\n", author);
    GIT_APPEND ("committer %s\n", committer);
    GIT_APPEND ("\n");
    if (message_file) {
        unsigned char *text = NULL;
        size_t text_len = 0;
        if (bgit_slurp_file (message_file, &text, &text_len) < 0) {
            free (body);
            return GIT_EXIT_FATAL;
        }
        GIT_APPEND ("%.*s", (int) text_len, (const char *) text);
        free (text);
    } else if (n_messages) {
        for (int i = 0; i < n_messages; i++)
            GIT_APPEND ("%s%s\n", i ? "\n" : "", messages[i]);
    } else {
        unsigned char *text = NULL;
        size_t text_len = 0;
        if (bgit_slurp_fd (STDIN_FILENO, &text, &text_len) < 0) {
            free (body);
            return git_fatal ("cannot read the message: %s", strerror (errno));
        }
        GIT_APPEND ("%.*s", (int) text_len, (const char *) text);
        free (text);
    }
#undef GIT_APPEND
    if (len == 0 || body[len - 1] != '\n') {
        /* git ends a commit message with a newline. */
        if (len + 2 > cap) {
            char *grown = realloc (body, len + 2);
            if (!grown) { free (body); return GIT_EXIT_FATAL; }
            body = grown;
        }
        body[len++] = '\n';
    }

    char commit[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                               (const unsigned char *) body, len, 1, commit);
    free (body);
    if (rc < 0) return GIT_EXIT_FATAL;
    printf ("%s\n", commit);
    return 0;
}

/* ls-tree reads a tree the way git reads it: one level at a time, going
   below only where a path named on the command line leads or -r says to. */
struct git_ls_tree {
    git_context *ctx;
    int recursive, show_trees, dirs_only, name_only, zero, long_form, abbrev;
    int full_name;                /* name everything from the top of the tree */
    const char *shown_prefix;     /* what to put back in front of a name */
    struct { const char *name; int slashed; } specs[32];
    int n_specs;
};

/* Does one of the paths named cover this one? With none named, all of
   them are. */
static int
git_ls_tree_matched (const struct git_ls_tree *ls, const char *path)
{
    if (!ls->n_specs) return 1;
    for (int i = 0; i < ls->n_specs; i++) {
        const char *spec = ls->specs[i].name;
        size_t len = strlen (spec);
        if (!ls->specs[i].slashed && !strcmp (path, spec)) return 1;
        if (!strncmp (path, spec, len) && path[len] == '/') return 1;
    }
    return 0;
}

/* Does one of them name this tree, or something inside it? */
static int
git_ls_tree_toward (const struct git_ls_tree *ls, const char *path)
{
    size_t len = strlen (path);
    for (int i = 0; i < ls->n_specs; i++) {
        const char *spec = ls->specs[i].name;
        if (!strcmp (spec, path)) return 1;
        if (!strncmp (spec, path, len) && spec[len] == '/') return 1;
    }
    return 0;
}

static void
git_ls_tree_show (struct git_ls_tree *ls, const char *mode, const char *type,
                  const char *sha, const char *path)
{
    char end = ls->zero ? '\0' : '\n';
    char quoted[8192], whole[8192];
    if (ls->shown_prefix && *ls->shown_prefix) {
        snprintf (whole, sizeof whole, "%s%s", ls->shown_prefix, path);
        path = whole;
    }
    const char *shown = ls->zero ? path
        : bgit_quote_path (path, quoted, sizeof quoted);
    if (ls->name_only) { printf ("%s%c", shown, end); return; }
    char id[41];
    snprintf (id, sizeof id, "%.*s", ls->abbrev ? ls->abbrev : 40, sha);
    if (ls->long_form) {
        /* The size of what is there, and a dash for what has none. */
        char size[32] = "-";
        if (!strcmp (type, "blob")) {
            enum bgit_type kind;
            unsigned char *data = NULL;
            size_t len = 0;
            if (bgit_odb_read (&ls->ctx->odb, sha, &kind, &data, &len) == 0) {
                snprintf (size, sizeof size, "%zu", len);
                free (data);
            }
        }
        printf ("%06lo %s %s %7s\t%s%c", strtoul (mode, NULL, 8), type, id,
                size, shown, end);
    } else
        printf ("%06lo %s %s\t%s%c", strtoul (mode, NULL, 8), type, id, shown,
                end);
}

static int
git_ls_tree_entry (void *vctx, const char *mode, const char *type,
                   const char *sha, const char *path)
{
    struct git_ls_tree *ls = vctx;
    int matched = git_ls_tree_matched (ls, path);
    if (strcmp (type, "tree")) {
        if (matched && !ls->dirs_only)
            git_ls_tree_show (ls, mode, type, sha, path);
        return 0;
    }
    if (matched) {
        /* A tree that was asked for stands for itself, unless -r says to
           open it. */
        if (!ls->recursive) {
            git_ls_tree_show (ls, mode, type, sha, path);
            return 0;
        }
        if (ls->show_trees || ls->dirs_only)
            git_ls_tree_show (ls, mode, type, sha, path);
    } else if (ls->n_specs && git_ls_tree_toward (ls, path)) {
        /* Only passed through on the way to what was asked for. */
        if (ls->show_trees) git_ls_tree_show (ls, mode, type, sha, path);
    } else
        return 0;
    char prefix[4096];
    if ((size_t) snprintf (prefix, sizeof prefix, "%s/", path) >= sizeof prefix)
        return 0;
    return bgit_tree_walk (&ls->ctx->odb, sha, prefix, 0, 1, git_ls_tree_entry,
                           ls);
}

static int
git_cmd_ls_tree (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git ls-tree [-d] [-r] [-t] [-l] [-z] [--name-only] "
                        "[--full-name] [--abbrev=<n>] <tree-ish> [<path>...]";
    struct git_ls_tree ls;
    memset (&ls, 0, sizeof ls);
    ls.ctx = ctx;
    const char *name = NULL;
    int no_more = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "-r")) ls.recursive = 1;
        else if (!no_more && !strcmp (w, "-t")) ls.show_trees = 1;
        else if (!no_more && !strcmp (w, "-d")) ls.dirs_only = 1;
        else if (!no_more && (!strcmp (w, "-l") || !strcmp (w, "--long")))
            ls.long_form = 1;
        else if (!no_more && !strcmp (w, "-z")) ls.zero = 1;
        else if (!no_more && (!strcmp (w, "--name-only") ||
                              !strcmp (w, "--name-status")))
            ls.name_only = 1;
        else if (!no_more && !strcmp (w, "--full-name")) ls.full_name = 1;
        else if (!no_more && !strncmp (w, "--abbrev=", 9)) {
            ls.abbrev = atoi (w + 9);
            if (ls.abbrev < 4) ls.abbrev = 4;
            if (ls.abbrev > 40) ls.abbrev = 40;
        }
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else if (ls.n_specs < (int) (sizeof ls.specs / sizeof *ls.specs)) {
            /* A path written with a trailing slash names what is inside
               the tree, not the tree itself. */
            size_t len = strlen (w);
            int slashed = len && w[len - 1] == '/';
            char *held = strdup (w);
            if (!held) return GIT_EXIT_FATAL;
            while (len && held[len - 1] == '/') held[--len] = '\0';
            ls.specs[ls.n_specs].name = held;
            ls.specs[ls.n_specs].slashed = slashed;
            ls.n_specs++;
        }
        else return git_fatal ("too many paths");
    }
    if (!name) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char id[41], tree[41];
    if (git_resolve (ctx, name, id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0)
        return git_fatal ("not a tree object");
    /* Run under a directory of the working tree, git lists that part of the
       tree and names what it finds from there — unless --full-name asks for
       the name from the top, which it then puts back in front. */
    if (*ctx->prefix) {
        char spec[8192], inside[41];
        snprintf (spec, sizeof spec, "%s:%.*s", name,
                  (int) (strlen (ctx->prefix) - 1), ctx->prefix);
        if (git_resolve (ctx, spec, inside, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, inside, BGIT_TREE, tree) < 0)
            return 0;                    /* nothing of it is in this tree */
        ls.shown_prefix = ls.full_name ? ctx->prefix : "";
    }
    if (bgit_tree_walk (&ctx->odb, tree, "", 0, 1, git_ls_tree_entry, &ls) < 0)
        return git_fatal ("cannot read tree %s", tree);
    return 0;
}

/* ---- which commits a log shows ----------------------------------------- */

/* git's filters over the commit itself: who wrote it, what it says, how
   many parents it has and when it was made. */
struct git_log_filter {
    const char *patterns[16];    /* --grep */
    const char *authors[8];
    const char *committers[8];
    int n_patterns, n_authors, n_committers;
    int extended;                /* -E: the wider regular expressions */
    int fixed;                   /* -F: the pattern stands for itself */
    int ignore_case;
    int invert;                  /* --invert-grep, over the message alone */
    int all_match;               /* every --grep, not any of them */
    int min_parents, max_parents;
    long long since, until;      /* seconds, or -1 */
    const char *pickaxe;         /* -S: a string whose count has to change */
    const char *diff_grep;       /* -G: a pattern an added or removed line has */
    int pickaxe_regex;           /* -S reads its string as a pattern */
};

static void
git_log_filter_init (struct git_log_filter *filter)
{
    memset (filter, 0, sizeof *filter);
    filter->min_parents = filter->max_parents = -1;
    filter->since = filter->until = -1;
}

static int
git_log_filtering (const struct git_log_filter *filter)
{
    return filter->n_patterns || filter->n_authors || filter->n_committers ||
           filter->min_parents >= 0 || filter->max_parents >= 0 ||
           filter->since >= 0 || filter->until >= 0;
}

/* One pattern against one piece of text, the way git reads the pattern:
   a basic regular expression unless -E or -F says otherwise, over each
   line of the text on its own. */
static int
git_log_matches (const struct git_log_filter *filter, const char *pattern,
                 const char *text)
{
    if (filter->fixed) {
        if (!filter->ignore_case) return strstr (text, pattern) != NULL;
        for (const char *at = text; *at; at++) {
            size_t i = 0;
            while (pattern[i] &&
                   tolower ((unsigned char) at[i]) ==
                   tolower ((unsigned char) pattern[i]))
                i++;
            if (!pattern[i]) return 1;
        }
        return 0;
    }
    regex_t compiled;
    int flags = REG_NOSUB | REG_NEWLINE;
    if (filter->extended) flags |= REG_EXTENDED;
    if (filter->ignore_case) flags |= REG_ICASE;
    if (regcomp (&compiled, pattern, flags) != 0) return 0;
    int hit = regexec (&compiled, text, 0, NULL, 0) == 0;
    regfree (&compiled);
    return hit;
}

/* "<seconds> <zone>" as a number of seconds. */
static long long
git_date_seconds (const char *raw)
{
    return strtoll (raw ? raw : "0", NULL, 10);
}

/* A --since or --until as git reads one: the forms that name a moment
   outright, and the common relative ones. Anything else is taken for the
   present moment, which is what git's own reading of a date it cannot
   place comes to. */
static long long
git_approxidate (const char *text)
{
    long long now = (long long) time (NULL);
    while (*text == ' ') text++;
    if (*text == '@') return strtoll (text + 1, NULL, 10);
    if (!strcmp (text, "now")) return now;
    if (!strcmp (text, "yesterday")) return now - 86400;
    int year = 0, month = 0, day = 0, hour = 0, minute = 0, second = 0;
    char rest[64] = "";
    int read = sscanf (text, "%d-%d-%d%63s", &year, &month, &day, rest);
    if (read >= 3 && year > 1900) {
        const char *at = rest;
        if (*at == 'T' || *at == ' ') at++;
        /* git fills in what the date does not say from the present
           moment, so a bare day means that day at this time of it. */
        struct tm tm;
        time_t this_moment = (time_t) now;
        tzset ();
        if (!localtime_r (&this_moment, &tm)) memset (&tm, 0, sizeof tm);
        tm.tm_year = year - 1900;
        tm.tm_mon = month - 1;
        tm.tm_mday = day;
        if (sscanf (at, "%d:%d:%d", &hour, &minute, &second) >= 2) {
            tm.tm_hour = hour;
            tm.tm_min = minute;
            tm.tm_sec = second;
        }
        tm.tm_isdst = -1;
        const char *zone = strpbrk (at, "Z+");
        if (!zone && at[0] && strchr (at + 1, '-')) zone = strchr (at + 1, '-');
        if (zone) {
            /* A zone of its own: read the time as UTC and shift it. */
            long long stamp = (long long) timegm (&tm);
            if (*zone != 'Z') {
                int zh = 0, zm = 0;
                sscanf (zone + 1, "%2d%*[:]%2d", &zh, &zm);
                long long off = zh * 3600 + zm * 60;
                stamp += *zone == '-' ? off : -off;
            }
            return stamp;
        }
        tzset ();
        return (long long) mktime (&tm);
    }
    /* "<n> <unit> ago", written with spaces or with dots. */
    char held[256];
    snprintf (held, sizeof held, "%s", text);
    for (char *at = held; *at; at++) if (*at == '.') *at = ' ';
    long long count = 0;
    char unit[32] = "";
    if (sscanf (held, "%lld %31s", &count, unit) == 2) {
        size_t len = strlen (unit);
        if (len && unit[len - 1] == 's') unit[--len] = '\0';
        long long span = 0;
        if (!strcmp (unit, "second")) span = 1;
        else if (!strcmp (unit, "minute")) span = 60;
        else if (!strcmp (unit, "hour")) span = 3600;
        else if (!strcmp (unit, "day")) span = 86400;
        else if (!strcmp (unit, "week")) span = 7 * 86400;
        else if (!strcmp (unit, "month")) span = 30 * 86400;
        else if (!strcmp (unit, "year")) span = 365 * 86400;
        if (span) return now - count * span;
    }
    return now;
}

/* The filter options both log and rev-list take. Returns 1 when the word
   was one of them. */
static int
git_log_filter_option (struct git_log_filter *filter, const char *w,
                       const char **next)
{
    if (!strncmp (w, "--grep=", 7)) {
        if (filter->n_patterns < (int) (sizeof filter->patterns /
                                        sizeof *filter->patterns))
            filter->patterns[filter->n_patterns++] = w + 7;
    }
    else if (!strncmp (w, "--author=", 9)) {
        if (filter->n_authors < (int) (sizeof filter->authors /
                                       sizeof *filter->authors))
            filter->authors[filter->n_authors++] = w + 9;
    }
    else if (!strncmp (w, "--committer=", 12)) {
        if (filter->n_committers < (int) (sizeof filter->committers /
                                          sizeof *filter->committers))
            filter->committers[filter->n_committers++] = w + 12;
    }
    else if (!strcmp (w, "-E") || !strcmp (w, "--extended-regexp"))
        filter->extended = 1;
    else if (!strcmp (w, "-F") || !strcmp (w, "--fixed-strings"))
        filter->fixed = 1;
    else if (!strcmp (w, "-i") || !strcmp (w, "--regexp-ignore-case"))
        filter->ignore_case = 1;
    else if (!strcmp (w, "--invert-grep")) filter->invert = 1;
    else if (!strcmp (w, "--all-match")) filter->all_match = 1;
    else if (!strcmp (w, "--merges")) filter->min_parents = 2;
    else if (!strcmp (w, "--no-merges")) filter->max_parents = 1;
    else if (!strncmp (w, "--min-parents=", 14))
        filter->min_parents = atoi (w + 14);
    else if (!strncmp (w, "--max-parents=", 14))
        filter->max_parents = atoi (w + 14);
    else if (!strcmp (w, "--no-min-parents")) filter->min_parents = -1;
    else if (!strcmp (w, "--no-max-parents")) filter->max_parents = -1;
    else if (!strncmp (w, "--since=", 8) || !strncmp (w, "--after=", 8))
        filter->since = git_approxidate (w + 8);
    else if (!strncmp (w, "--until=", 8) || !strncmp (w, "--before=", 9))
        filter->until = git_approxidate (strchr (w, '=') + 1);
    else if (!strncmp (w, "-S", 2) && w[2]) filter->pickaxe = w + 2;
    else if (!strncmp (w, "-G", 2) && w[2]) filter->diff_grep = w + 2;
    else if ((!strcmp (w, "-S") || !strcmp (w, "-G")) && next && *next) {
        if (w[1] == 'S') filter->pickaxe = *next;
        else filter->diff_grep = *next;
        *next = NULL;             /* the word after it has been taken */
    }
    else if (!strcmp (w, "--pickaxe-regex")) filter->pickaxe_regex = 1;
    else return 0;
    return 1;
}

/* Is one of the two diff tests in play? They read the commit's own diff,
   which the filters above never do. */
static int
git_log_pickaxing (const struct git_log_filter *filter)
{
    return filter->pickaxe != NULL || filter->diff_grep != NULL;
}

/* How often the needle appears in the text, without overlapping. */
static size_t
git_pickaxe_count (const struct git_log_filter *filter, const char *text,
                   size_t len)
{
    const char *needle = filter->pickaxe;
    size_t needle_len = strlen (needle), count = 0;
    if (!needle_len || !text) return 0;
    if (filter->pickaxe_regex) {
        /* A pattern counts its matches, one after another. */
        char *held = malloc (len + 1);
        if (!held) return 0;
        if (len) memcpy (held, text, len);
        held[len] = '\0';
        regex_t compiled;
        /* --pickaxe-regex, like -G, is read the extended way. */
        int flags = REG_NEWLINE | REG_EXTENDED |
                    (filter->ignore_case ? REG_ICASE : 0);
        if (regcomp (&compiled, needle, flags) != 0) { free (held); return 0; }
        const char *at = held;
        regmatch_t where;
        while (*at && regexec (&compiled, at, 1, &where, 0) == 0) {
            count++;
            at += where.rm_eo > where.rm_so ? where.rm_eo : where.rm_so + 1;
        }
        regfree (&compiled);
        free (held);
        return count;
    }
    for (size_t at = 0; at + needle_len <= len;) {
        size_t i = 0;
        while (i < needle_len &&
               (filter->ignore_case
                ? tolower ((unsigned char) text[at + i]) ==
                  tolower ((unsigned char) needle[i])
                : text[at + i] == needle[i]))
            i++;
        if (i == needle_len) { count++; at += needle_len; }
        else at++;
    }
    return count;
}

/* Does the commit named by ID pass them? Reading it is what says. */
static int git_log_keeps_id (git_context *ctx,
                             const struct git_log_filter *filter,
                             const char *id);

/* ---- rev-list ---------------------------------------------------------- */

struct git_walk {
    char (*seen)[41];
    size_t n_seen, cap_seen;
    /* Where each seen commit sits, so that asking whether one has been
       seen is a lookup: a history of twenty thousand commits is two
       hundred million comparisons otherwise, and that is all a walk over
       it would do. index+1, with 0 for an empty slot. */
    size_t *slots;
    size_t n_slots;
    struct { char id[41]; long long date; } *pending;
    size_t n_pending, cap_pending;
};

static unsigned long
git_sha_hash (const char *sha)
{
    unsigned long hash = 1469598103934665603UL;      /* FNV-1a */
    for (const unsigned char *p = (const unsigned char *) sha; *p; p++) {
        hash ^= *p;
        hash *= 1099511628211UL;
    }
    return hash;
}

static long long
git_header_date (const char *data, size_t len, const char *field)
{
    size_t flen = strlen (field);
    long long when = 0;
    const char *p = data, *end = data + len;
    while (p < end) {
        const char *nl = memchr (p, '\n', (size_t) (end - p));
        size_t line = nl ? (size_t) (nl - p) : (size_t) (end - p);
        if (!line) break;
        if (line > flen && !memcmp (p, field, flen)) {
            /* "<field> Name <email> <seconds> <zone>" */
            const char *gt = memchr (p, '>', line);
            if (gt) when = strtoll (gt + 1, NULL, 10);
            break;
        }
        if (!nl) break;
        p = nl + 1;
    }
    return when;
}

/* The date on one of an object's header lines: 0 when it has none. */
static long long
git_object_date (git_context *ctx, const char *sha, const char *field)
{
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, sha, &type, &data, &len) < 0) return 0;
    long long when = git_header_date ((const char *) data, len, field);
    free (data);
    return when;
}

static long long
git_commit_date (git_context *ctx, const char *sha)
{
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, sha, &type, &data, &len) < 0) return 0;
    long long when = 0;
    const char *p = (const char *) data;
    const char *end = p + len;
    while (p < end) {
        const char *nl = memchr (p, '\n', (size_t) (end - p));
        size_t line = nl ? (size_t) (nl - p) : (size_t) (end - p);
        if (!line) break;
        if (line > 10 && !memcmp (p, "committer ", 10)) {
            /* "committer Name <email> <seconds> <zone>" */
            const char *gt = memchr (p, '>', line);
            if (gt) when = strtoll (gt + 1, NULL, 10);
            break;
        }
        if (!nl) break;
        p = nl + 1;
    }
    free (data);
    return when;
}

/* 1 when this commit has been seen before, 0 when it is new (and is
   remembered), -1 when there is no memory for it. */
static int
git_walk_seen (struct git_walk *walk, const char *sha)
{
    if (walk->slots) {
        size_t mask = walk->n_slots - 1;
        size_t slot = git_sha_hash (sha) & mask;
        while (walk->slots[slot]) {
            if (!strcmp (walk->seen[walk->slots[slot] - 1], sha)) return 1;
            slot = (slot + 1) & mask;
        }
    } else
        for (size_t i = 0; i < walk->n_seen; i++)
            if (!strcmp (walk->seen[i], sha)) return 1;

    if (walk->n_seen == walk->cap_seen) {
        size_t next = walk->cap_seen ? walk->cap_seen * 2 : 64;
        char (*grown)[41] = realloc (walk->seen, next * sizeof *grown);
        if (!grown) return -1;
        walk->seen = grown;
        walk->cap_seen = next;
    }
    memcpy (walk->seen[walk->n_seen++], sha, 41);

    /* The table is kept at least twice the size of what it holds. */
    if (!walk->slots || walk->n_slots < (walk->n_seen + 1) * 2) {
        size_t want = walk->n_slots ? walk->n_slots * 2 : 256;
        while (want < (walk->n_seen + 1) * 2) want *= 2;
        size_t *grown = calloc (want, sizeof *grown);
        if (grown) {
            free (walk->slots);
            walk->slots = grown;
            walk->n_slots = want;
            for (size_t i = 0; i < walk->n_seen; i++) {
                size_t mask = walk->n_slots - 1;
                size_t slot = git_sha_hash (walk->seen[i]) & mask;
                while (walk->slots[slot]) slot = (slot + 1) & mask;
                walk->slots[slot] = i + 1;
            }
        }
    } else {
        size_t mask = walk->n_slots - 1;
        size_t slot = git_sha_hash (sha) & mask;
        while (walk->slots[slot]) slot = (slot + 1) & mask;
        walk->slots[slot] = walk->n_seen;
    }
    return 0;
}

static int
git_walk_push (git_context *ctx, struct git_walk *walk, const char *sha)
{
    int seen = git_walk_seen (walk, sha);
    if (seen != 0) return seen < 0 ? -1 : 0;
    if (walk->n_pending == walk->cap_pending) {
        size_t next = walk->cap_pending ? walk->cap_pending * 2 : 32;
        void *grown = realloc (walk->pending, next * sizeof *walk->pending);
        if (!grown) return -1;
        walk->pending = grown;
        walk->cap_pending = next;
    }
    memcpy (walk->pending[walk->n_pending].id, sha, 41);
    walk->pending[walk->n_pending].date = git_commit_date (ctx, sha);
    walk->n_pending++;
    return 0;
}

/* Ids already named by --objects, so nothing is named twice. A history
   names an object once per tree that holds it, which is many times over,
   so the set is kept sorted and asked by halves. */
struct git_objects {
    char (*ids)[41];
    size_t n, cap;
};

struct git_objects_ctx { struct git_objects *seen; };

/* Whether an id is in such a set, without putting it there. */
static int
git_objects_held (const struct git_objects *set, const char *sha)
{
    size_t low = 0, high = set->n;
    while (low < high) {
        size_t middle = (low + high) / 2;
        int order = memcmp (set->ids[middle], sha, 40);
        if (!order) return 1;
        if (order < 0) low = middle + 1;
        else high = middle;
    }
    return 0;
}

static int
git_objects_seen (struct git_objects *seen, const char *sha)
{
    size_t low = 0, high = seen->n;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        int cmp = memcmp (seen->ids[mid], sha, 40);
        if (cmp < 0) low = mid + 1;
        else if (cmp > 0) high = mid;
        else return 1;
    }
    if (seen->n == seen->cap) {
        size_t next = seen->cap ? seen->cap * 2 : 128;
        char (*grown)[41] = realloc (seen->ids, next * sizeof *grown);
        if (!grown) return 1;          /* out of room: say it was seen */
        seen->ids = grown;
        seen->cap = next;
    }
    memmove (seen->ids[low + 1], seen->ids[low],
             (seen->n - low) * sizeof *seen->ids);
    memcpy (seen->ids[low], sha, 40);
    seen->ids[low][40] = '\0';
    seen->n++;
    return 0;
}

/* The same, for the objects a range leaves out: they are remembered so
   that nothing inside them is named, and nothing is printed. */
static int
git_objects_mark (void *context, const char *mode, const char *type,
                  const char *sha, const char *path)
{
    (void) type;
    (void) path;
    if (mode && !strcmp (mode, "160000")) return 0;
    struct git_objects_ctx *ctx = context;
    git_objects_seen (ctx->seen, sha);
    return 0;
}

static int
git_objects_visit (void *context, const char *mode, const char *type,
                   const char *sha, const char *path)
{
    (void) type;
    /* A gitlink names a commit of another repository, which this one does
       not have and does not list. */
    if (mode && !strcmp (mode, "160000")) return 0;
    struct git_objects_ctx *ctx = context;
    if (!git_objects_seen (ctx->seen, sha)) printf ("%s %s\n", sha, path);
    return 0;
}

/* Is there a file of this name where the command was run? Deciding whether
   a word is a path is the one thing that needs to know. */
static int
git_path_exists (const char *path)
{
    struct stat st;
    return lstat (path, &st) == 0;
}

static int
git_cmd_rev_list (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git rev-list [--count] [--objects] [--parents] "
                        "[-n <number> | --max-count=<number>] "
                        "[--skip=<number>] [--first-parent] "
                        "[--grep=<pattern>] [--author=<pattern>] "
                        "[--merges | --no-merges] [--since=<date>] "
                        "<commit>... [^<commit>]";
    int count_only = 0, with_objects = 0, with_parents = 0, first_parent = 0;
    struct git_log_filter filter;
    git_log_filter_init (&filter);
    long limit = -1, skip = 0, skipped = 0;
    const char *revs_named[16], *rev_words_named[16];
    const char *excludes[16], *exclude_words[16];
    /* --all can name more revisions than a command line ever would, so the
       list grows onto the heap when it does. */
    const char **revs = revs_named, **rev_words = rev_words_named;
    int n_revs = 0, n_excludes = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        /* A filter option may take the word after it; the helper says so
           by letting go of it. */
        const char *taken = p->next ? p->next->word->word : NULL;
        if (!strcmp (w, "--count")) count_only = 1;
        else if (!strcmp (w, "--objects")) with_objects = 1;
        else if (!strcmp (w, "--parents")) with_parents = 1;
        else if (!strcmp (w, "--first-parent")) first_parent = 1;
        else if (!strncmp (w, "--skip=", 7)) skip = atol (w + 7);
        else if (git_log_filter_option (&filter, w, &taken)) {
            if (!taken && p->next) p = p->next;
        }
        else if (!strcmp (w, "--all")) revs[n_revs++] = "--all";
        else if (!strcmp (w, "-n") && p->next) { limit = atol (p->next->word->word); p = p->next; }
        else if (!strncmp (w, "--max-count=", 12)) limit = atol (w + 12);
        else if (w[0] == '-' && git_all_digits (w + 1)) limit = atol (w + 1);
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (w[0] == '^' && w[1]) {
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes))
                return git_fatal ("too many revisions");
            exclude_words[n_excludes] = w;
            excludes[n_excludes++] = w + 1;
        }
        else if (strstr (w, "...")) return git_fatal ("this build's git rev-list "
                                                      "has no A...B range yet");
        /* Two dots make a range — unless there is a file of that name,
           which is how `git log ../file` reads. */
        else if (strstr (w, "..") && !git_path_exists (w)) {
            char *range = strdup (w);
            if (!range) return GIT_EXIT_FATAL;
            char *dots = strstr (range, "..");
            *dots = '\0';
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes) ||
                n_revs >= (int) (sizeof revs / sizeof *revs)) {
                free (range);
                return git_fatal ("too many revisions");
            }
            exclude_words[n_excludes] = w;
            excludes[n_excludes++] = *range ? range : "HEAD";
            rev_words[n_revs] = w;
            revs[n_revs++] = dots[2] ? dots + 2 : "HEAD";
        }
        else if (n_revs < (int) (sizeof revs / sizeof *revs)) {
            rev_words[n_revs] = w;
            revs[n_revs++] = w;
        }
        else return git_fatal ("too many revisions");
    }
    if (!n_revs) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* --all stands for every ref there is, however many that is. */
    bgit_ref *all_refs = NULL;
    size_t n_all = 0;
    for (int i = 0; i < n_revs; i++) {
        if (strcmp (revs[i], "--all")) continue;
        if (bgit_refs_list (&ctx->repo, "refs/", &all_refs, &n_all) < 0)
            return git_fatal ("cannot read refs");
        const char **grown = malloc ((n_all + (size_t) n_revs) * sizeof *grown);
        const char **grown_words =
            malloc ((n_all + (size_t) n_revs) * sizeof *grown_words);
        if (!grown || !grown_words) {
            free (grown);
            free (grown_words);
            bgit_refs_free (all_refs, n_all);
            return GIT_EXIT_FATAL;
        }
        int kept = 0;
        for (int k = 0; k < n_revs; k++)
            if (strcmp (revs[k], "--all")) {
                grown_words[kept] = rev_words[k];
                grown[kept++] = revs[k];
            }
        for (size_t j = 0; j < n_all; j++) {
            grown_words[kept] = all_refs[j].name;
            grown[kept++] = all_refs[j].name;
        }
        revs = grown;
        rev_words = grown_words;
        n_revs = kept;
        break;
    }

    struct git_walk walk;
    memset (&walk, 0, sizeof walk);
    struct git_objects seen = {0};
    int status = 0;
    /* Mark everything the excluded tips reach, so the walk steps over it. */
    for (int i = 0; i < n_excludes; i++) {
        char id[41], commit[41];
        if (git_resolve (ctx, excludes[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            status = exclude_words[i][0] == '^'
                     ? git_fatal ("bad revision '%s'", exclude_words[i])
                     : git_fatal_ambiguous (exclude_words[i]);
            goto done;
        }
        if (git_walk_push (ctx, &walk, commit) < 0) { status = GIT_EXIT_FATAL; goto done; }
        /* What the far side of a range already holds is not named. Its
           trees are remembered before anything is printed, since an
           object is named the first time it is seen. */
        if (with_objects && !count_only) {
            char older[41];
            struct git_objects_ctx mark_ctx = { &seen };
            if (bgit_commit_tree (&ctx->odb, commit, older) == 0 &&
                !git_objects_seen (&seen, older))
                bgit_tree_walk (&ctx->odb, older, "", 1, 1, git_objects_mark,
                                &mark_ctx);
        }
    }
    struct git_objects left_out = {0};
    while (walk.n_pending) {
        char current[41];
        memcpy (current, walk.pending[--walk.n_pending].id, 41);
        if (with_objects && !count_only) git_objects_seen (&left_out, current);
        char parents[BGIT_MAX_PARENTS][41];
        int count = bgit_commit_parents (&ctx->odb, current, parents,
                                         BGIT_MAX_PARENTS);
        for (int i = 0; i < count; i++)
            if (git_walk_push (ctx, &walk, parents[i]) < 0) {
                status = GIT_EXIT_FATAL;
                goto done;
            }
    }
    for (int i = 0; i < n_revs; i++) {
        if (!revs[i]) continue;
        char id[41], commit[41];
        if (git_resolve (ctx, revs[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            status = git_fatal_ambiguous (rev_words[i]);
            goto done;
        }
        if (git_walk_push (ctx, &walk, commit) < 0) { status = GIT_EXIT_FATAL; goto done; }
    }

    long emitted = 0;
    while (walk.n_pending) {
        /* Newest first, as git's default order does. */
        size_t best = 0;
        for (size_t i = 1; i < walk.n_pending; i++)
            if (walk.pending[i].date > walk.pending[best].date) best = i;
        char current[41];
        memcpy (current, walk.pending[best].id, 41);
        memmove (walk.pending + best, walk.pending + best + 1,
                 (walk.n_pending - best - 1) * sizeof *walk.pending);
        walk.n_pending--;

        if (limit >= 0 && emitted >= limit) break;
        char parents[BGIT_MAX_PARENTS][41];
        int n = bgit_commit_parents (&ctx->odb, current, parents, BGIT_MAX_PARENTS);
        /* --first-parent keeps to the line of descent it started on. */
        if (first_parent && n > 1) n = 1;
        /* A commit the filters leave out is still walked through. */
        if (!git_log_keeps_id (ctx, &filter, current)) {
            for (int i = 0; i < n; i++)
                if (git_walk_push (ctx, &walk, parents[i]) < 0) {
                    status = GIT_EXIT_FATAL;
                    goto done;
                }
            continue;
        }
        /* --skip passes over the first few that would have been named, and
           their parents are still walked. */
        if (skipped < skip) {
            skipped++;
            for (int i = 0; i < n; i++)
                if (git_walk_push (ctx, &walk, parents[i]) < 0) {
                    status = GIT_EXIT_FATAL;
                    goto done;
                }
            continue;
        }
        if (!count_only) {
            /* With --parents each line carries what the commit came from. */
            printf ("%s", current);
            if (with_parents)
                for (int i = 0; i < n; i++) printf (" %s", parents[i]);
            printf ("\n");
        }
        emitted++;

        /* With --objects the tree each commit holds, and everything under
           it, is named too — each with the path it has there. */
        if (with_objects && !count_only) {
            /* What the far side of the range already holds is not named:
               at the edge, the trees it left out are remembered first, so
               that nothing under them is listed as new. */
            for (int i = 0; i < n; i++) {
                if (!git_objects_held (&left_out, parents[i])) continue;
                char older[41];
                if (bgit_commit_tree (&ctx->odb, parents[i], older) != 0)
                    continue;
                struct git_objects_ctx mark_ctx = { &seen };
                if (git_objects_seen (&seen, older)) continue;
                bgit_tree_walk (&ctx->odb, older, "", 1, 1, git_objects_mark,
                                &mark_ctx);
            }
            char tree[41];
            if (bgit_commit_tree (&ctx->odb, current, tree) == 0) {
                struct git_objects_ctx seen_ctx = { &seen };
                if (!git_objects_seen (&seen, tree)) printf ("%s \n", tree);
                bgit_tree_walk (&ctx->odb, tree, "", 1, 1, git_objects_visit,
                                &seen_ctx);
            }
        }

        for (int i = 0; i < n; i++)
            if (git_walk_push (ctx, &walk, parents[i]) < 0) {
                status = GIT_EXIT_FATAL;
                goto done;
            }
    }
    if (count_only) printf ("%ld\n", emitted);
    free (seen.ids);
    free (left_out.ids);
done:
    if (revs != revs_named) {
        free ((void *) revs);
        free ((void *) rev_words);
    }
    bgit_refs_free (all_refs, n_all);
    free (walk.seen); free (walk.slots);
    free (walk.pending);
    return status;
}

static int
git_cmd_var (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git var (GIT_AUTHOR_IDENT | GIT_COMMITTER_IDENT)";
    if (!args || args->next) return git_usage (usage);
    const char *name = args->word->word;
    bgit_repo repo;
    int have_repo = bgit_repo_discover (".", &repo) == 0;
    bgit_config cfg;
    bgit_config_load (&cfg, have_repo ? &repo : NULL, git_overrides,
                      git_n_overrides);
    char ident[1024];
    int status = 0;
    if (!strcmp (name, "GIT_AUTHOR_IDENT") || !strcmp (name, "GIT_COMMITTER_IDENT")) {
        if (bgit_ident (&cfg, !strcmp (name, "GIT_COMMITTER_IDENT"), ident,
                        sizeof ident) < 0)
            status = git_fatal ("cannot determine the identity to use");
        else
            printf ("%s\n", ident);
    } else {
        fflush (stdout);
        fprintf (stderr, "fatal: %s: unknown variable\n", name);
        status = GIT_EXIT_FATAL;
    }
    bgit_config_release (&cfg);
    if (have_repo) bgit_repo_release (&repo);
    (void) ctx;
    return status;
}

/* ---- add, status and commit -------------------------------------------- */

/* The index, the HEAD tree and the status of everything, in one place. */
struct git_state {
    bgit_index_entry *index;
    size_t n_index, cap_index;
    char head[41];
    char head_tree[41];
    int have_head;
    char *branch;           /* the ref HEAD names, or NULL when detached */
};

static void
git_state_release (struct git_state *state)
{
    bgit_index_free_entries (state->index, state->n_index);
    free (state->branch);
    memset (state, 0, sizeof *state);
}

static int
git_state_load (git_context *ctx, struct git_state *state)
{
    memset (state, 0, sizeof *state);
    if (git_index_load (ctx, &state->index, &state->n_index) < 0) return -1;
    state->cap_index = state->n_index;
    char *symref = NULL;
    if (bgit_ref_resolve (&ctx->repo, "HEAD", state->head, &symref) == 0) {
        state->have_head = 1;
        if (bgit_peel_to_type (&ctx->odb, state->head, BGIT_TREE,
                               state->head_tree) < 0) {
            free (symref);
            return -1;
        }
    }
    if (!symref) {
        /* An unborn branch still names where a commit will go. */
        char *target = NULL;
        if (bgit_symref_read (&ctx->repo, "HEAD", &target) == 0) symref = target;
    }
    state->branch = symref;
    return 0;
}

/* Stage one working-tree file, replacing whatever the index held. */
static int
git_stage_file (git_context *ctx, struct git_state *state, const char *path,
                const struct stat *st)
{
    char full[4096];
    if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path) >=
        (int) sizeof full)
        return -1;
    unsigned char *content = NULL;
    size_t len = 0;
    if (S_ISLNK (st->st_mode)) {
        char target[4096];
        ssize_t got = readlink (full, target, sizeof target);
        if (got < 0) return -1;
        content = malloc ((size_t) got);
        if (!content) return -1;
        memcpy (content, target, (size_t) got);
        len = (size_t) got;
    } else {
        if (bgit_slurp_file (full, &content, &len) < 0) return -1;
    }
    char id[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "blob", content, len,
                               1, id);
    free (content);
    if (rc < 0) return -1;

    bgit_index_entry entry;
    memset (&entry, 0, sizeof entry);
    bgit_index_entry_set_stat (&entry, st);
    entry.mode = bgit_worktree_mode (st);
    if (bgit_hex_to_sha (id, entry.sha) < 0) return -1;
    size_t plen = strlen (path);
    entry.flags = (uint16_t) (plen > 0xFFF ? 0xFFF : plen);
    entry.path = strdup (path);
    if (!entry.path) return -1;
    return git_index_put (&state->index, &state->n_index, &state->cap_index,
                          &entry);
}

/* Does the index hold this path, or anything below it? An ignore rule
   says what to take in, and has nothing to say about what is in already. */
static int
git_index_holds_under (const struct git_state *state, const char *path)
{
    size_t len = strlen (path);
    for (size_t i = 0; i < state->n_index; i++)
        if (!strncmp (state->index[i].path, path, len) &&
            (state->index[i].path[len] == '/' || !state->index[i].path[len]))
            return 1;
    return 0;
}

struct git_add_ctx {
    git_context *ctx;
    struct git_state *state;
    const bgit_ignore *ignore;
    const char *pathspec;      /* "" for everything */
    int force;                 /* -f: an ignore rule does not stand in the way */
    int update_only;           /* -u: only what the index already has */
    int dry_run;
    int warn_embedded;         /* say so when a repository is staged as one */
    int *changed;
};

/* Is PATH inside the pathspec (a file, a directory, or everything)? */
static int
git_path_in_spec (const char *path, const char *spec)
{
    if (!*spec || !strcmp (spec, ".")) return 1;
    size_t len = strlen (spec);
    if (!strcmp (path, spec)) return 1;
    return !strncmp (path, spec, len) && path[len] == '/';
}

static int
git_add_visit (void *vctx, const char *path, int is_dir, const struct stat *st)
{
    struct git_add_ctx *add = vctx;
    if (is_dir) {
        /* Skip a directory outside the pathspec, or one that is ignored. */
        size_t len = strlen (path);
        if (*add->pathspec && strcmp (add->pathspec, ".") &&
            strncmp (add->pathspec, path, len) != 0 &&
            !git_path_in_spec (path, add->pathspec))
            return 1;
        const bgit_ignore_rule *rule = NULL;
        if (!add->force && bgit_ignore_match (add->ignore, path, 1, &rule) &&
            !git_index_holds_under (add->state, path))
            return 1;
        /* A submodule is staged as the commit it has checked out, and what
           is inside it belongs to that repository, not to this one. */
        bgit_index_entry *linked = git_index_lookup (add->state->index,
                                                    add->state->n_index, path);
        /* A repository inside this one that nothing knows about yet is
           staged as the commit it stands at, and git says so out loud
           unless it was a submodule being taken in. */
        if (!linked && git_path_in_spec (path, add->pathspec)) {
            char full[4096], head[41];
            if (snprintf (full, sizeof full, "%s/%s", add->ctx->repo.work_tree,
                          path) < (int) sizeof full &&
                bgit_submodule_head (full, head) == 0) {
                *add->changed = 1;
                if (add->warn_embedded) {
                    fflush (stdout);
                    fprintf (stderr, "warning: adding embedded git "
                                     "repository: %s\n", path);
                    fprintf (stderr,
                      "hint: You've added another git repository inside your "
                      "current repository.\n"
                      "hint: Clones of the outer repository will not contain "
                      "the contents of\n"
                      "hint: the embedded repository and will not know how to "
                      "obtain it.\n"
                      "hint: If you meant to add a submodule, use:\n"
                      "hint:\n"
                      "hint: \tgit submodule add <url> %s\n"
                      "hint:\n"
                      "hint: If you added this path by mistake, you can remove "
                      "it from the\n"
                      "hint: index with:\n"
                      "hint:\n"
                      "hint: \tgit rm --cached %s\n"
                      "hint:\n"
                      "hint: See \"git help submodule\" for more "
                      "information.\n"
                      "hint: Disable this message with \"git config "
                      "advice.addEmbeddedRepo false\"\n", path, path);
                }
                if (!add->dry_run) {
                    bgit_index_entry entry;
                    memset (&entry, 0, sizeof entry);
                    entry.path = strdup (path);
                    if (!entry.path) return -1;
                    bgit_index_entry_set_stat (&entry, st);
                    entry.mode = 0160000;
                    entry.size = 0;
                    bgit_hex_to_sha (head, entry.sha);
                    size_t len = strlen (path);
                    entry.flags = (uint16_t) (len > 0xfff ? 0xfff : len);
                    if (git_index_put (&add->state->index,
                                       &add->state->n_index,
                                       &add->state->cap_index, &entry) < 0)
                        return -1;
                }
                return 1;
            }
        }
        if (linked && linked->mode == 0160000) {
            if (!git_path_in_spec (path, add->pathspec)) return 1;
            char full[4096], head[41], stored[41];
            if (snprintf (full, sizeof full, "%s/%s", add->ctx->repo.work_tree,
                          path) < (int) sizeof full &&
                bgit_submodule_head (full, head) == 0) {
                bgit_sha_to_hex (linked->sha, stored);
                if (strcmp (head, stored)) {
                    *add->changed = 1;
                    if (!add->dry_run) {
                        /* The commit, and the directory's stat data with
                           it, which is what git records for a gitlink. */
                        bgit_hex_to_sha (head, linked->sha);
                        bgit_index_entry_set_stat (linked, st);
                        linked->mode = 0160000;
                    }
                }
            }
            return 1;
        }
        return 0;
    }
    if (!git_path_in_spec (path, add->pathspec)) return 0;
    /* What the index already holds is staged whatever the ignore rules
       say. */
    bgit_index_entry *staged = git_index_lookup (add->state->index,
                                                 add->state->n_index, path);
    const bgit_ignore_rule *rule = NULL;
    if (!staged && !add->force &&
        bgit_ignore_match (add->ignore, path, 0, &rule))
        return 0;

    if (staged) {
        char full[4096];
        snprintf (full, sizeof full, "%s/%s", add->ctx->repo.work_tree, path);
        if (bgit_worktree_matches (&add->ctx->odb, full, staged, st))
            return 0;
        *add->changed = 1;
        if (add->dry_run) return 0;
        return git_stage_file (add->ctx, add->state, path, st) < 0 ? -1 : 0;
    }
    if (add->update_only) return 0;      /* -u leaves new files alone */
    *add->changed = 1;
    if (add->dry_run) return 0;
    return git_stage_file (add->ctx, add->state, path, st) < 0 ? -1 : 0;
}

static int
git_cmd_add (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git add [-A | --all] [-u | --update] [-n | --dry-run] "
                        "[-f | --force] [--no-warn-embedded-repo] [--] "
                        "<pathspec>...";
    int all = 0, update_only = 0, dry_run = 0, force = 0, no_more = 0;
    int warn_embedded = 1;
    const char *specs[32];
    int n_specs = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "--no-warn-embedded-repo")) {
            warn_embedded = 0;
            continue;
        }
        if (!no_more && (!strcmp (w, "-A") || !strcmp (w, "--all"))) all = 1;
        else if (!no_more && (!strcmp (w, "-u") || !strcmp (w, "--update"))) update_only = 1;
        else if (!no_more && (!strcmp (w, "-n") || !strcmp (w, "--dry-run"))) dry_run = 1;
        else if (!no_more && (!strcmp (w, "-f") || !strcmp (w, "--force"))) force = 1;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_specs < (int) (sizeof specs / sizeof *specs)) specs[n_specs++] = w;
        else return git_fatal ("too many paths");
    }
    if (!n_specs && !all && !update_only) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, specs, n_specs) < 0)
        return git_fatal ("too many paths");
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    bgit_ignore ignore;
    if (bgit_ignore_load (&ignore, &ctx->repo, &ctx->cfg) < 0) {
        git_state_release (&state);
        return git_fatal ("cannot read the exclude files");
    }

    /* A named file that an ignore rule covers is refused without -f. */
    int status = 0, changed = 0;
    for (int i = 0; i < n_specs && !force; i++) {
        struct stat st;
        char full[4096];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, specs[i]);
        if (lstat (full, &st) < 0 || S_ISDIR (st.st_mode)) continue;
        if (git_index_holds_under (&state, specs[i])) continue;
        const bgit_ignore_rule *rule = NULL;
        if (!bgit_ignore_match (&ignore, specs[i], 0, &rule)) continue;
        fflush (stdout);
        fprintf (stderr, "The following paths are ignored by one of your "
                         ".gitignore files:\n%s\n", specs[i]);
        status = 1;
        break;
    }

    const char *everything[1] = { "" };
    const char *const *spec_list = n_specs ? specs : everything;
    int spec_count = n_specs ? n_specs : 1;
    for (int i = 0; i < spec_count && !status; i++) {
        struct git_add_ctx add = {
            .ctx = ctx, .state = &state, .ignore = &ignore,
            .pathspec = spec_list[i], .force = force,
            .update_only = update_only, .dry_run = dry_run,
            .warn_embedded = warn_embedded, .changed = &changed
        };
        if (bgit_worktree_walk (&ctx->repo, git_add_visit, &add) < 0) {
            status = GIT_EXIT_FATAL;
            break;
        }
        /* A file that has gone is staged as a removal, which is what
           `git add <dir>`, `-A` and `-u` all do. */
        for (size_t j = 0; j < state.n_index;) {
            if (!git_path_in_spec (state.index[j].path, spec_list[i])) { j++; continue; }
            char full[4096];
            snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                      state.index[j].path);
            struct stat st;
            if (lstat (full, &st) == 0) { j++; continue; }
            changed = 1;
            if (dry_run) { j++; continue; }
            char *gone = strdup (state.index[j].path);
            if (!gone) { status = GIT_EXIT_FATAL; break; }
            bgit_index_remove_path (&state.index, &state.n_index, gone);
            free (gone);
        }
    }

    if (!status && changed && !dry_run &&
        git_index_store (ctx, state.index, state.n_index) < 0)
        status = GIT_EXIT_FATAL;
    bgit_ignore_release (&ignore);
    git_state_release (&state);
    return status;
}

/* ---- status ------------------------------------------------------------ */

static void
git_status_letters (const bgit_status_entry *entry, char *x, char *y, char blank)
{
    if (entry->unmerged) {
        /* Which stages survive says what the two sides did. */
        switch (entry->unmerged) {
        case 2 | 4 | 8: *x = 'U'; *y = 'U'; return;   /* both modified */
        case 4 | 8:     *x = 'A'; *y = 'A'; return;   /* both added */
        case 2 | 4:     *x = 'U'; *y = 'D'; return;   /* deleted by them */
        case 2 | 8:     *x = 'D'; *y = 'U'; return;   /* deleted by us */
        case 4:         *x = 'A'; *y = 'U'; return;   /* added by us */
        case 8:         *x = 'U'; *y = 'A'; return;   /* added by them */
        default:        *x = 'D'; *y = 'D'; return;   /* both deleted */
        }
    }
    *x = entry->staged ? (char) entry->staged : blank;
    *y = entry->unstaged ? (char) entry->unstaged : blank;
}

/* What the long format calls an unmerged path. */
static const char *
git_unmerged_label (int stages)
{
    switch (stages) {
    case 2 | 4 | 8: return "both modified:";
    case 4 | 8:     return "both added:";
    case 2 | 4:     return "deleted by them:";
    case 2 | 8:     return "deleted by us:";
    case 4:         return "added by us:";
    case 8:         return "added by them:";
    default:        return "both deleted:";
    }
}

/* The words git puts in front of a path in the long format, in a column
   as wide as the longest of them. */
static const char *
git_status_label (int code)
{
    switch (code) {
    case 'A': return "new file:";
    case 'C': return "copied:";
    case 'D': return "deleted:";
    case 'M': return "modified:";
    case 'R': return "renamed:";
    case 'T': return "typechange:";
    default:  return "unknown:";
    }
}

/* Opening another repository — a submodule's, here — is written down
   further along, where the far ends are. */
static int git_open_remote (const char *url, bgit_repo *repo, bgit_odb *odb);

/* How a submodule stands: whether the commit it points at has moved,
   whether it has changes of its own, and whether it has untracked files.
   Reading the repository over there is the only way to know, so this is
   asked once and read twice — by the short form and by the long one. */
struct git_submodule_state {
    int is_submodule;
    int moved, changed, untracked;
};

static void
git_submodule_state (git_context *ctx, const bgit_status_entry *entry,
                     struct git_submodule_state *out)
{
    memset (out, 0, sizeof *out);
    uint32_t mode = entry->index_mode ? entry->index_mode : entry->head_mode;
    if (mode != 0160000) return;
    out->is_submodule = 1;

    char full[4096], head[41];
    if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                  entry->path) >= (int) sizeof full)
        return;
    if (bgit_submodule_head (full, head) < 0) return;
    if (entry->index_sha[0] && strcmp (head, entry->index_sha))
        out->moved = 1;
    int changed = 0, untracked = 0;
    bgit_submodule_dirt (full, &changed, &untracked);
    out->changed = changed;
    out->untracked = untracked;
}



/* What porcelain v2 puts in a path's third field: a submodule's state, or
   the four dots that say it is not one. */
static void
git_status_kind_field (git_context *ctx, const bgit_status_entry *entry,
                       char out[5])
{
    struct git_submodule_state sub;
    git_submodule_state (ctx, entry, &sub);
    if (!sub.is_submodule) {
        snprintf (out, 5, "N...");
        return;
    }
    snprintf (out, 5, "S%c%c%c", sub.moved ? 'C' : '.',
              sub.changed ? 'M' : '.', sub.untracked ? 'U' : '.');
}

/* What the long form adds after a submodule's name. */
static const char *
git_submodule_note (git_context *ctx, const bgit_status_entry *entry,
                    char *out, size_t outsz)
{
    struct git_submodule_state sub;
    *out = '\0';
    git_submodule_state (ctx, entry, &sub);
    if (!sub.is_submodule) return out;
    const char *parts[3];
    int n = 0;
    if (sub.moved) parts[n++] = "new commits";
    if (sub.changed) parts[n++] = "modified content";
    if (sub.untracked) parts[n++] = "untracked content";
    if (!n) return out;
    size_t at = (size_t) snprintf (out, outsz, " (");
    for (int i = 0; i < n && at < outsz; i++)
        at += (size_t) snprintf (out + at, outsz - at, "%s%s",
                                 i ? ", " : "", parts[i]);
    if (at < outsz) snprintf (out + at, outsz - at, ")");
    return out;
}

/* `git status` with no format option: the report written for a person.
   Sections in git's order, each followed by a blank line, and the closing
   sentence that says what, if anything, is there to commit. */
/* The commits one set of revisions has that another does not, newest
   first. */
static int git_collect_commits (git_context *ctx, const char *const *revs,
                                int n_revs, const char *const *excludes,
                                int n_excludes, int first_parent, long limit,
                                char (**out)[41], size_t *n_out);

/* Is this ref one the listing was narrowed to? */
static int
git_ref_listed (git_context *ctx, const char *sha, const char *merged,
                const char *not_merged, const char *contains,
                const char *points_at)
{
    char commit[41];
    if (*points_at && strcmp (sha, points_at)) {
        char peeled[41];
        if (bgit_peel_to_type (&ctx->odb, sha, BGIT_COMMIT, peeled) < 0 ||
            strcmp (peeled, points_at))
            return 0;
    }
    if (!*merged && !*not_merged && !*contains) return 1;
    if (bgit_peel_to_type (&ctx->odb, sha, BGIT_COMMIT, commit) < 0) return 0;
    if (*merged && bgit_is_ancestor (&ctx->odb, commit, merged) <= 0) return 0;
    if (*not_merged && bgit_is_ancestor (&ctx->odb, commit, not_merged) > 0)
        return 0;
    if (*contains && bgit_is_ancestor (&ctx->odb, contains, commit) <= 0)
        return 0;
    return 1;
}

/* The branch this one follows, and how far apart the two have got.
   Returns 0 when there is no upstream, 1 when there is, and 2 when the
   configuration names one that is not here any more. */
static int
git_status_upstream (git_context *ctx, struct git_state *state,
                     const char *branch, char *name, size_t size,
                     long *ahead, long *behind)
{
    *ahead = *behind = 0;
    if (!branch) return 0;
    char key[4200];
    snprintf (key, sizeof key, "branch.%s.remote", branch);
    const char *remote = bgit_config_get (&ctx->cfg, key);
    snprintf (key, sizeof key, "branch.%s.merge", branch);
    const char *merge = bgit_config_get (&ctx->cfg, key);
    if (!remote || !merge) return 0;
    const char *shortened = merge;
    if (!strncmp (shortened, "refs/heads/", 11)) shortened += 11;
    /* A branch may follow one in this repository, which is what a remote
       of "." means. */
    char ref[4200];
    if (!strcmp (remote, ".")) {
        snprintf (ref, sizeof ref, "%s", merge);
        snprintf (name, size, "%s", shortened);
    } else {
        /* Where the branch it follows is kept here is the remote's own
           business: its fetch refspec says, and without one git has
           nowhere to look and says nothing. */
        char fetch_key[4200];
        snprintf (fetch_key, sizeof fetch_key, "remote.%s.fetch", remote);
        const char **specs = NULL;
        size_t n_specs = bgit_config_get_all (&ctx->cfg, fetch_key, &specs);
        int mapped = 0;
        for (size_t i = 0; i < n_specs && !mapped; i++) {
            const char *spec = specs[i];
            if (*spec == '+') spec++;
            const char *colon = strchr (spec, ':');
            if (!colon) continue;
            size_t from_len = (size_t) (colon - spec);
            const char *to = colon + 1;
            if (from_len && spec[from_len - 1] == '*' && strchr (to, '*')) {
                if (strncmp (merge, spec, from_len - 1)) continue;
                const char *star = strchr (to, '*');
                snprintf (ref, sizeof ref, "%.*s%s%s", (int) (star - to), to,
                          merge + from_len - 1, star + 1);
                mapped = 1;
            } else if (!strncmp (merge, spec, from_len) && !merge[from_len]) {
                snprintf (ref, sizeof ref, "%s", to);
                mapped = 1;
            }
        }
        if (!mapped) return 0;
        snprintf (name, size, "%s/%s", remote, shortened);
        if (strncmp (ref, "refs/remotes/", 13) == 0) {
            const char *rest = ref + 13;
            snprintf (name, size, "%s", rest);
        }
    }
    char id[41];
    if (bgit_ref_read (&ctx->repo, ref, id) != 0) return 2;
    if (!state->have_head) return 1;

    const char *mine[1] = { state->head };
    const char *theirs[1] = { id };
    char (*ordered)[41] = NULL;
    size_t count = 0;
    if (git_collect_commits (ctx, mine, 1, theirs, 1, 0, -1, &ordered,
                             &count) == 0) {
        *ahead = (long) count;
        free (ordered);
    }
    ordered = NULL;
    count = 0;
    if (git_collect_commits (ctx, theirs, 1, mine, 1, 0, -1, &ordered,
                             &count) == 0) {
        *behind = (long) count;
        free (ordered);
    }
    return 1;
}

/* Where a branch stands against the one it follows, in git's words, which
   are different for each of the four ways it can stand. status leaves a
   blank line after it; checkout does not. */
static void
git_upstream_summary (git_context *ctx, struct git_state *state,
                      const char *branch_name, int blank_after)
{
    char upstream[4200];
    long ahead = 0, behind = 0;
    int following = git_status_upstream (ctx, state, branch_name, upstream,
                                         sizeof upstream, &ahead, &behind);
    const char *after = blank_after ? "\n" : "";
    if (following == 2)
        printf ("Your branch is based on '%s', but the upstream is gone.\n"
                "  (use \"git branch --unset-upstream\" to fixup)\n%s",
                upstream, after);
    else if (following && !ahead && !behind)
        printf ("Your branch is up to date with '%s'.\n%s", upstream, after);
    else if (following && ahead && behind)
        printf ("Your branch and '%s' have diverged,\nand have %ld and %ld "
                "different commits each, respectively.\n  (use \"git pull\" "
                "if you want to integrate the remote branch with yours)\n%s",
                upstream, ahead, behind, after);
    else if (following && ahead)
        printf ("Your branch is ahead of '%s' by %ld commit%s.\n  (use "
                "\"git push\" to publish your local commits)\n%s",
                upstream, ahead, ahead == 1 ? "" : "s", after);
    else if (following)
        printf ("Your branch is behind '%s' by %ld commit%s, and can be "
                "fast-forwarded.\n  (use \"git pull\" to update your local "
                "branch)\n%s", upstream, behind, behind == 1 ? "" : "s",
                after);
}

static void
git_status_long (git_context *ctx, struct git_state *state,
                 const bgit_status_entry *entries, size_t n,
                 const char *branch_name, int untracked_mode, int want_ignored)
{
    char quoted[8192], here[8192], here_from[8192];
    /* A rebase in progress speaks for itself, in place of the branch. */
    int rebasing = git_rebase_in_progress (ctx);
    if (rebasing) ;
    else if (branch_name) {
        printf ("On branch %s\n", branch_name);
        git_upstream_summary (ctx, state, branch_name, 1);
    }
    else if (state->have_head) {
        char abbreviated[41];
        git_abbrev (ctx, state->head, 7, abbreviated, sizeof abbreviated);
        printf ("HEAD detached at %s\n", abbreviated);
    } else printf ("Unborn HEAD\n");
    if (!state->have_head) printf ("\nNo commits yet\n\n");

    int staged = 0, unstaged = 0, deleted = 0, untracked = 0, ignored = 0;
    int unmerged = 0;
    for (size_t i = 0; i < n; i++) {
        if (entries[i].ignored) ignored = 1;
        else if (entries[i].untracked) untracked = 1;
        else if (entries[i].unmerged) unmerged = 1;
        else {
            if (entries[i].staged) staged = 1;
            if (entries[i].unstaged) unstaged = 1;
            if (entries[i].unstaged == 'D') deleted = 1;
        }
    }
    if (untracked_mode < 0) untracked = 0;

    /* Whatever is under way is said out loud, before anything else. */
    char in_progress[41];
    int merging = git_read_state_id (ctx, "MERGE_HEAD", in_progress);
    int picking = !merging && git_read_state_id (ctx, "CHERRY_PICK_HEAD", in_progress);
    int reverting = !merging && !picking &&
                    git_read_state_id (ctx, "REVERT_HEAD", in_progress);
    if (merging && unmerged) {
        printf ("You have unmerged paths.\n");
        printf ("  (fix conflicts and run \"git commit\")\n");
        printf ("  (use \"git merge --abort\" to abort the merge)\n\n");
    } else if (merging) {
        printf ("All conflicts fixed but you are still merging.\n");
        printf ("  (use \"git commit\" to conclude merge)\n\n");
    } else if (rebasing) {
        char onto[41] = "", head_name[4096] = "", abbreviated[41] = "";
        git_rebase_read (ctx, "onto", onto, sizeof onto);
        git_rebase_read (ctx, "head-name", head_name, sizeof head_name);
        if (*onto) git_abbrev (ctx, onto, 7, abbreviated, sizeof abbreviated);
        printf ("interactive rebase in progress; onto %s\n", abbreviated);

        /* The last two commands done and the next two to do, as git lists
           them, from the same two files. */
        char lines[64][1200];
        int n = git_rebase_list (ctx, "done", lines, 64);
        if (!n) printf ("No commands done.\n");
        else {
            printf ("Last command%s done (%d command%s done):\n",
                    n == 1 ? "" : "s", n, n == 1 ? "" : "s");
            for (int i = n > 2 ? n - 2 : 0; i < n; i++) {
                char shown[1200];
                git_rebase_line_render (ctx, lines[i], 0, shown, sizeof shown);
                printf ("   %s\n", shown);
            }
            if (n > 2)
                printf ("  (see more in file %s/rebase-merge/done)\n",
                        ctx->repo.git_dir);
        }
        n = git_rebase_list (ctx, "git-rebase-todo", lines, 64);
        if (!n) printf ("No commands remaining.\n");
        else {
            printf ("Next command%s to do (%d remaining command%s):\n",
                    n == 1 ? "" : "s", n, n == 1 ? "" : "s");
            for (int i = 0; i < 2 && i < n; i++) {
                char shown[1200];
                git_rebase_line_render (ctx, lines[i], 0, shown, sizeof shown);
                printf ("   %s\n", shown);
            }
            printf ("  (use \"git rebase --edit-todo\" to view and edit)\n");
        }
        const char *shown = head_name;
        if (!strncmp (shown, "refs/heads/", 11)) shown += 11;
        printf ("You are currently rebasing branch '%s' on '%s'.\n", shown,
                abbreviated);
        printf ("  (fix conflicts and then run \"git rebase --continue\")\n");
        printf ("  (use \"git rebase --skip\" to skip this patch)\n");
        printf ("  (use \"git rebase --abort\" to check out the original "
                "branch)\n\n");
    } else if (picking || reverting) {
        const char *verb = picking ? "cherry-pick" : "revert";
        char abbreviated[41];
        git_abbrev (ctx, in_progress, 7, abbreviated, sizeof abbreviated);
        printf ("You are currently %s commit %s.\n",
                picking ? "cherry-picking" : "reverting", abbreviated);
        if (unmerged)
            printf ("  (fix conflicts and run \"git %s --continue\")\n", verb);
        else
            printf ("  (all conflicts fixed: run \"git %s --continue\")\n", verb);
        printf ("  (use \"git %s --skip\" to skip this patch)\n", verb);
        printf ("  (use \"git %s --abort\" to cancel the %s operation)\n\n",
                verb, verb);
    }
    /* git's hints change when a commit is being made from somewhere other
       than the working tree: during a merge or a cherry-pick there is
       nothing simple to unstage to. */
    int from_commit = !merging && !picking;

    if (staged) {
        printf ("Changes to be committed:\n");
        if (from_commit)
            printf (state->have_head
                    ? "  (use \"git restore --staged <file>...\" to unstage)\n"
                    : "  (use \"git rm --cached <file>...\" to unstage)\n");
        for (size_t i = 0; i < n; i++) {
            if (entries[i].untracked || entries[i].ignored ||
                entries[i].unmerged || !entries[i].staged)
                continue;
            if (entries[i].renamed_from && *entries[i].renamed_from) {
                char from[8192];
                printf ("\t%-12s%s -> %s\n",
                        git_status_label (entries[i].staged),
                        bgit_quote_path (git_path_from_here (ctx,
                                                         entries[i].renamed_from,
                                                         here_from,
                                                         sizeof here_from),
                                     from, sizeof from),
                        bgit_quote_path (git_path_from_here (ctx,
                                                             entries[i].path,
                                                             here, sizeof here),
                                         quoted, sizeof quoted));
                continue;
            }
            printf ("\t%-12s%s\n", git_status_label (entries[i].staged),
                    bgit_quote_path (git_path_from_here (ctx, entries[i].path,
                                                        here, sizeof here),
                                     quoted, sizeof quoted));
        }
        printf ("\n");
    }
    if (unmerged) {
        printf ("Unmerged paths:\n");
        if (from_commit)
            printf (state->have_head
                    ? "  (use \"git restore --staged <file>...\" to unstage)\n"
                    : "  (use \"git rm --cached <file>...\" to unstage)\n");
        printf ("  (use \"git add <file>...\" to mark resolution)\n");
        for (size_t i = 0; i < n; i++) {
            if (!entries[i].unmerged) continue;
            printf ("\t%-17s%s\n", git_unmerged_label (entries[i].unmerged),
                    bgit_quote_path (git_path_from_here (ctx, entries[i].path,
                                                        here, sizeof here),
                                     quoted, sizeof quoted));
        }
        printf ("\n");
    }
    if (unstaged) {
        printf ("Changes not staged for commit:\n");
        printf (deleted
                ? "  (use \"git add/rm <file>...\" to update what will be committed)\n"
                : "  (use \"git add <file>...\" to update what will be committed)\n");
        printf ("  (use \"git restore <file>...\" to discard changes in working directory)\n");
        /* A submodule with work of its own in it gets a line of its own:
           what is in there cannot be committed from here. */
        for (size_t i = 0; i < n; i++) {
            if (entries[i].untracked || entries[i].ignored ||
                entries[i].unmerged || !entries[i].unstaged)
                continue;
            struct git_submodule_state sub;
            git_submodule_state (ctx, &entries[i], &sub);
            if (sub.is_submodule && (sub.changed || sub.untracked)) {
                printf ("  (commit or discard the untracked or modified "
                        "content in submodules)\n");
                break;
            }
        }
        for (size_t i = 0; i < n; i++) {
            if (entries[i].untracked || entries[i].ignored ||
                entries[i].unmerged || !entries[i].unstaged)
                continue;
            char note[128];
            printf ("\t%-12s%s%s\n", git_status_label (entries[i].unstaged),
                    bgit_quote_path (git_path_from_here (ctx, entries[i].path,
                                                        here, sizeof here),
                                     quoted, sizeof quoted),
                    git_submodule_note (ctx, &entries[i], note, sizeof note));
        }
        printf ("\n");
    }
    if (untracked) {
        printf ("Untracked files:\n");
        printf ("  (use \"git add <file>...\" to include in what will be committed)\n");
        for (size_t i = 0; i < n; i++)
            if (entries[i].untracked)
                printf ("\t%s\n",
                        bgit_quote_path (git_path_from_here (ctx, entries[i].path,
                                                        here, sizeof here),
                                     quoted, sizeof quoted));
        printf ("\n");
    }
    if (want_ignored && ignored) {
        printf ("Ignored files:\n");
        printf ("  (use \"git add -f <file>...\" to include in what will be committed)\n");
        for (size_t i = 0; i < n; i++)
            if (entries[i].ignored)
                printf ("\t%s\n",
                        bgit_quote_path (git_path_from_here (ctx, entries[i].path,
                                                        here, sizeof here),
                                     quoted, sizeof quoted));
        printf ("\n");
    }

    if (staged) return;
    if (unstaged || unmerged)
        printf ("no changes added to commit "
                "(use \"git add\" and/or \"git commit -a\")\n");
    else if (untracked)
        printf ("nothing added to commit but untracked files present "
                "(use \"git add\" to track)\n");
    else if (!state->have_head)
        printf ("nothing to commit (create/copy files and use \"git add\" "
                "to track)\n");
    else if (untracked_mode < 0)
        printf ("nothing to commit (use -u to show untracked files)\n");
    else
        printf ("nothing to commit, working tree clean\n");
}

static int
git_cmd_status (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git status [-s | --short | --porcelain[=<version>]] "
                        "[-b | --branch] [-u<mode> | --untracked-files=<mode>] "
                        "[--ignored] [-z]";
    int short_format = 0, porcelain = 0, version = 1, branch = 0, zero = 0;
    int untracked_all = 0, want_ignored = 0, find_renames = 1;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        /* Short options run together, as git takes them: -sb is both. */
        if (w[0] == '-' && w[1] && w[1] != '-' && !strchr (w, 'u') && w[2]) {
            int known = 1;
            for (const char *c = w + 1; *c && known; c++)
                if (*c != 's' && *c != 'b') known = 0;
            if (known) {
                for (const char *c = w + 1; *c; c++) {
                    if (*c == 's') short_format = 1;
                    else branch = 1;
                }
                continue;
            }
        }
        if (!strcmp (w, "-s") || !strcmp (w, "--short")) short_format = 1;
        else if (!strcmp (w, "--porcelain")) { porcelain = 1; version = 1; }
        else if (!strcmp (w, "--porcelain=v1")) { porcelain = 1; version = 1; }
        else if (!strcmp (w, "--porcelain=v2")) { porcelain = 1; version = 2; }
        else if (!strcmp (w, "-b") || !strcmp (w, "--branch")) branch = 1;
        else if (!strcmp (w, "--ignored")) want_ignored = 1;
        else if (!strcmp (w, "--no-renames")) find_renames = 0;
        /* -z ends each record with NUL and asks for the porcelain where
           nothing else has, as git's does. */
        else if (!strcmp (w, "-z")) zero = 1;
        else if (!strcmp (w, "-uall") || !strcmp (w, "--untracked-files=all")) untracked_all = 1;
        else if (!strcmp (w, "-unormal") || !strcmp (w, "--untracked-files=normal")) untracked_all = 0;
        else if (!strcmp (w, "-uno") || !strcmp (w, "--untracked-files=no")) untracked_all = -1;
        else return git_usage (usage);
    }
    if (zero && !short_format && !porcelain) { porcelain = 1; version = 1; }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    bgit_status_entry *entries = NULL;
    size_t n = 0;
    if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, state.index,
                     state.n_index, state.have_head ? state.head_tree : NULL,
                     untracked_all > 0, want_ignored, find_renames,
                     &entries, &n) < 0) {
        git_state_release (&state);
        return git_fatal ("cannot read the working tree");
    }

    const char *branch_name = state.branch;
    if (branch_name && !strncmp (branch_name, "refs/heads/", 11))
        branch_name += 11;
    if (!short_format && !porcelain) {
        git_status_long (ctx, &state, entries, n, branch_name,
                         untracked_all, want_ignored);
        bgit_status_free (entries, n);
        git_state_release (&state);
        return 0;
    }
    char upstream[4200] = "";
    long ahead = 0, behind = 0;
    int following = branch ? git_status_upstream (ctx, &state, branch_name,
                                                  upstream, sizeof upstream,
                                                  &ahead, &behind) : 0;
    char record_end = zero ? '\0' : '\n';
    if (branch && version == 2 && porcelain) {
        printf ("# branch.oid %s\n", state.have_head ? state.head : "(initial)");
        printf ("# branch.head %s\n", branch_name ? branch_name : "(detached)");
        if (following) printf ("# branch.upstream %s\n", upstream);
        if (following == 1) printf ("# branch.ab +%ld -%ld\n", ahead, behind);
    } else if (branch) {
        /* The short format's header, with git's "No commits yet" wording,
           and what the branch it follows has that it has not. */
        printf ("## %s%s", state.have_head ? "" : "No commits yet on ",
                branch_name ? branch_name : "HEAD (no branch)");
        if (following) printf ("...%s", upstream);
        if (following == 2) printf (" [gone]");
        else if (ahead && behind) printf (" [ahead %ld, behind %ld]", ahead, behind);
        else if (ahead) printf (" [ahead %ld]", ahead);
        else if (behind) printf (" [behind %ld]", behind);
        printf ("%c", record_end);
    }

    /* The second version quotes a name that needs it; the short form quotes
       one with a space in it as well, so that its columns can be told
       apart — which is what git does with each. */
    int quote_spaces = !(version == 2 && porcelain);
    /* The first porcelain names a path from the top of the tree, so that a
       script reading it need not know where it was run; every other form
       names it from here, as git does. */
    int from_here = !(porcelain && version == 1);
    for (size_t i = 0; i < n; i++) {
        const bgit_status_entry *entry = &entries[i];
        char shown_buf[8192], from_buf[8192], here_buf[8192], here_from[8192];
        const char *path = from_here
            ? git_path_from_here (ctx, entry->path, here_buf, sizeof here_buf)
            : entry->path;
        const char *older = entry->renamed_from && *entry->renamed_from
            ? (from_here ? git_path_from_here (ctx, entry->renamed_from,
                                               here_from, sizeof here_from)
                         : entry->renamed_from)
            : NULL;
        const char *shown = zero ? path
            : quote_spaces
            ? bgit_quote_path_sp (path, shown_buf, sizeof shown_buf)
            : bgit_quote_path (path, shown_buf, sizeof shown_buf);
        const char *came_from = older
            ? (zero ? older
               : quote_spaces
               ? bgit_quote_path_sp (older, from_buf, sizeof from_buf)
               : bgit_quote_path (older, from_buf, sizeof from_buf))
            : NULL;
        if (entry->ignored) {
            if (version == 2 && porcelain) printf ("! %s%c", shown, record_end);
            else printf ("!! %s%c", shown, record_end);
            continue;
        }
        if (entry->untracked) {
            if (untracked_all < 0) continue;
            if (version == 2 && porcelain) printf ("? %s%c", shown, record_end);
            else printf ("?? %s%c", shown, record_end);
            continue;
        }
        char x, y;
        if (entry->unmerged && version == 2 && porcelain) {
            /* An unmerged path has its own record, listing every stage. */
            git_status_letters (entry, &x, &y, '.');
            const char *zeros = "0000000000000000000000000000000000000000";
            char kind[5];
            git_status_kind_field (ctx, entry, kind);
            printf ("u %c%c %s %06o %06o %06o %06o %s %s %s %s", x, y, kind,
                    entry->head_mode, entry->index_mode, entry->their_mode,
                    entry->worktree_mode,
                    entry->head_sha[0] ? entry->head_sha : zeros,
                    entry->index_sha[0] ? entry->index_sha : zeros,
                    entry->their_sha[0] ? entry->their_sha : zeros,
                    shown);
            printf ("%c", record_end);
            continue;
        }
        if (version == 2 && porcelain && entry->renamed_from &&
            *entry->renamed_from) {
            git_status_letters (entry, &x, &y, '.');
            char kind[5];
            git_status_kind_field (ctx, entry, kind);
            printf ("2 %c%c %s %06o %06o %06o %s %s R%d %s%c%s%c", x, y, kind,
                    entry->head_mode, entry->index_mode,
                    entry->worktree_mode ? entry->worktree_mode
                                         : entry->index_mode,
                    entry->head_sha, entry->index_sha,
                    entry->score * 100 / 60000, shown,
                    zero ? '\0' : '\t', came_from, record_end);
            continue;
        }
        if (version == 2 && porcelain) {
            git_status_letters (entry, &x, &y, '.');
            char kind[5];
            git_status_kind_field (ctx, entry, kind);
            printf ("1 %c%c %s %06o %06o %06o %s %s %s", x, y, kind,
                    entry->head_mode, entry->index_mode,
                    entry->unstaged == 'D' ? 0 : (entry->worktree_mode
                        ? entry->worktree_mode : entry->index_mode),
                    entry->head_sha[0] ? entry->head_sha
                        : "0000000000000000000000000000000000000000",
                    entry->index_sha[0] ? entry->index_sha
                        : "0000000000000000000000000000000000000000",
                    shown);
            printf ("%c", record_end);
        } else {
            git_status_letters (entry, &x, &y, ' ');
            /* A submodule says which kind of change it is: M for a commit
               that moved, m for content of its own that changed, ? for
               nothing but untracked files in it. */
            if (y == 'M') {
                struct git_submodule_state sub;
                git_submodule_state (ctx, entry, &sub);
                if (sub.is_submodule && !sub.moved)
                    y = sub.changed ? 'm' : sub.untracked ? '?' : y;
            }
            /* With NUL between records the new name comes first and the
               old after it, where the arrow would otherwise stand. */
            if (came_from && zero)
                printf ("%c%c %s%c%s%c", x, y, shown, record_end, came_from,
                        record_end);
            else if (came_from)
                printf ("%c%c %s -> %s%c", x, y, came_from, shown, record_end);
            else printf ("%c%c %s%c", x, y, shown, record_end);
        }
    }
    bgit_status_free (entries, n);
    git_state_release (&state);
    return 0;
}

/* How a set of changed paths is shown: as a patch, a stat, or just names.
   commit, log, show and diff all take these, so the shape is declared before
   the first of them; the code is written out below, beside git diff. */
struct git_diff_format {
    int patch, stat, numstat, shortstat, summary, name_only, name_status;
    int raw;                            /* the :<modes> <ids> <status> lines */
    int check;                          /* --check: the whitespace a change brings */
    int exit_code;                      /* say in the status whether anything changed */
    int zero;                           /* -z: names whole, records NUL-ended */
    int relative;                       /* only what is here, named from here */
    const char *relative_to;            /* --relative=<path>, where given */
    int no_patch;
    int no_renames;
    int context;
    int inter_context;                  /* --inter-hunk-context */
    int inter_context_set;              /* command line overrides config */
    int reverse;                        /* -R: the two sides change places */
    int word_diff;                      /* 0 by lines, 1 plain, 2 porcelain */
    int no_prefix;                      /* the paths stand without a/ and b/ */
    int ignore_ws;                      /* whitespace to overlook: xdiff.h */
    int function_context;               /* -W: the whole definition */
    int ignore_blank_lines;             /* blank lines on their own */
    int algorithm;                      /* BGIT_DIFF_ALGORITHM_* */
    int algorithm_set;                  /* command line overrides config */
    bgit_diffstat_layout stat_layout;   /* what --stat=<width> asks for */
};

/* Did --check complain about anything? log and show print their diffs
   through layers with no status to hand back, and say so here instead. */
static int git_check_complained;

static void git_diff_format_init (struct git_diff_format *format);
/* git takes at most one of --name-only, --name-status, --check and -s. */
static int git_diff_format_done (const struct git_diff_format *format);
static int git_diff_format_option (struct git_diff_format *format,
                                   const char *word, const char *next);
static int git_diff_emit (git_context *ctx, FILE *out,
                          const struct git_diff_format *format,
                          const bgit_diff_entry *entries, size_t n,
                          int new_from_worktree, const char *line_prefix);
static void git_find_renames (git_context *ctx,
                              const struct git_diff_format *format,
                              bgit_diff_entry **entries, size_t *n,
                              int from_worktree);

/* What a path was called in the parent, when the change that made this
   commit renamed it — which is what --follow follows. */
static char *git_blame_renamed_from (git_context *ctx, const char *parent,
                                     const char *commit, const char *path);

/* ---- commit ------------------------------------------------------------ */

/* The key a signature is made with: gpg.format says which kind of key,
   and user.signingKey says which one. Returns 0 with the key, or -1 with
   git's message. */
static int
git_signing_key (git_context *ctx, const char *named, bgit_ssh_key *key)
{
    const char *format = bgit_config_get (&ctx->cfg, "gpg.format");
    if (format && strcmp (format, "ssh"))
        return git_fatal ("this build signs with ssh keys; gpg.format is '%s'",
                          format) < 0 ? -1 : -1;
    const char *path = named ? named
                             : bgit_config_get (&ctx->cfg, "user.signingKey");
    if (!path || !*path) {
        git_fatal ("this build needs user.signingKey to name an ssh key");
        return -1;
    }
    if (!format) {
        git_fatal ("this build signs with ssh keys; set gpg.format to ssh");
        return -1;
    }
    return bgit_ssh_key_private (path, key);
}

/* Put a signature into a commit the way git does: a gpgsig header,
   standing after the committer and before the message, whose lines after
   the first are indented by one space. */
static char *
git_commit_signed (const char *body, size_t len, const char *armour,
                   size_t *out_len)
{
    const char *blank = strstr (body, "\n\n");
    if (!blank) return NULL;
    size_t headers = (size_t) (blank - body) + 1;    /* up to the blank line */
    size_t armour_len = strlen (armour);
    char *out = malloc (len + armour_len * 2 + 32);
    if (!out) return NULL;
    size_t at = 0;
    memcpy (out, body, headers);
    at = headers;
    at += (size_t) snprintf (out + at, armour_len + 16, "gpgsig ");
    for (const char *line = armour; *line; ) {
        const char *stop = strchr (line, '\n');
        size_t line_len = stop ? (size_t) (stop - line) : strlen (line);
        memcpy (out + at, line, line_len);
        at += line_len;
        out[at++] = '\n';
        line = stop ? stop + 1 : line + line_len;
        if (*line) out[at++] = ' ';                  /* the header goes on */
    }
    memcpy (out + at, body + headers, len - headers);
    at += len - headers;
    *out_len = at;
    return out;
}


/* The transport ignores SIGPIPE so a closed far end is EPIPE here.
   A program this process execs gets the disposition from before that
   ignore. Save it once: a later open must not record the ignore as
   the caller's action. */
static struct sigaction git_pipe_saved;
static int git_pipe_saved_valid;

static void
git_ignore_pipe (void)
{
    struct sigaction ignore, previous;
    memset (&ignore, 0, sizeof ignore);
    ignore.sa_handler = SIG_IGN;
    sigemptyset (&ignore.sa_mask);
    if (sigaction (SIGPIPE, &ignore, &previous) < 0)
        return;
    if (!git_pipe_saved_valid) {
        git_pipe_saved = previous;
        git_pipe_saved_valid = 1;
    }
}

static void
git_restore_caller_pipe (void)
{
    if (git_pipe_saved_valid)
        sigaction (SIGPIPE, &git_pipe_saved, NULL);
}

/* Run an editor over PATH, the way git runs one: GIT_EDITOR, then
   core.editor, then VISUAL, then EDITOR, and vi when nothing names one.
   What is named is a command line the shell reads, with the file added at
   the end, so "emacs -nw" works as well as a bare name; and ":" does
   nothing at all, which is git's way of leaving a file as it is. With
   SEQUENCE, the todo list's own editor is asked for first. Returns 0 when
   the editor came back happy, and -1 otherwise. */
static int
git_edit_file (git_context *ctx, const char *path, int sequence)
{
    const char *editor = NULL;
    if (sequence) {
        editor = getenv ("GIT_SEQUENCE_EDITOR");
        if (!editor || !*editor)
            editor = bgit_config_get (&ctx->cfg, "sequence.editor");
    }
    if (!editor || !*editor) editor = getenv ("GIT_EDITOR");
    if (!editor || !*editor) editor = bgit_config_get (&ctx->cfg, "core.editor");
    if (!editor || !*editor) editor = getenv ("VISUAL");
    if (!editor || !*editor) editor = getenv ("EDITOR");
    if (!editor || !*editor) editor = "vi";
    if (!strcmp (editor, ":")) return 0;

    fflush (stdout);
    fflush (stderr);
    pid_t child = fork ();
    if (child < 0) return -1;
    if (!child) {
        git_restore_caller_pipe ();
        char script[4096];
        snprintf (script, sizeof script, "%s \"$@\"", editor);
        /* The shell keeps its own table of variables and only builds the
           environment array when it is about to run something outside
           itself, so an assignment standing before this command — the
           editor is often told what to write that way — is not in
           `environ` yet. */
        array_needs_making = 1;
        maybe_make_export_env ();
        const char *argv[8];
        int at = 0;
        argv[at++] = "bash";
        argv[at++] = "--noprofile";
        argv[at++] = "--norc";
        argv[at++] = "-c";
        argv[at++] = script;
        argv[at++] = "git-editor";
        argv[at++] = path;
        argv[at] = NULL;
        execve ("/proc/self/exe", (char *const *) argv, export_env);
        _exit (127);
    }
    int status = 0;
    while (waitpid (child, &status, 0) < 0 && errno == EINTR) ;
    if (!WIFEXITED (status) || WEXITSTATUS (status)) {
        git_fatal ("There was a problem with the editor '%s'.", editor);
        return -1;
    }
    return 0;
}

/* What a message file says once the comment lines are taken out of it,
   with the blank lines around it trimmed the way git trims them. Returns
   the text, for the caller to free, or NULL. */
static char *
git_message_body (const char *path, size_t *out_len)
{
    unsigned char *text = NULL;
    size_t len = 0;
    if (bgit_slurp_file (path, &text, &len) < 0) return NULL;
    char *out = malloc (len + 2);
    if (!out) { free (text); return NULL; }
    size_t at = 0;
    for (size_t i = 0; i < len; ) {
        size_t stop = i;
        while (stop < len && text[stop] != '\n') stop++;
        if (text[i] != '#') {
            memcpy (out + at, text + i, stop - i);
            at += stop - i;
            out[at++] = '\n';
        }
        i = stop < len ? stop + 1 : len;
    }
    free (text);
    /* Leading and trailing blank lines are not part of a message. */
    size_t start = 0;
    while (start < at && (out[start] == '\n' || out[start] == ' ' ||
                          out[start] == '\t'))
        start++;
    while (at > start && (out[at - 1] == '\n' || out[at - 1] == ' ' ||
                          out[at - 1] == '\t'))
        at--;
    if (at > start) out[at++] = '\n';
    memmove (out, out + start, at - start);
    at -= start;
    out[at] = '\0';
    *out_len = at;
    return out;
}

/* The comment block git puts under a commit message in the editor: what
   status would say, with every line behind a '#' and the advice left out,
   since none of it is part of the message. */
static void
git_commit_template (git_context *ctx, FILE *out, struct git_state *state,
                     const char *author, const char *committer, int amend,
                     int editing)
{
    const char *branch = state->branch;
    if (branch && !strncmp (branch, "refs/heads/", 11)) branch += 11;
    /* Committing a merge is worth saying out loud, since the parents come
       from a file rather than from anything typed. */
    char merge_head[41];
    if (!amend && git_read_state_id (ctx, "MERGE_HEAD", merge_head))
        fprintf (out, "#\n# It looks like you may be committing a merge.\n"
                      "# If this is not correct, please run\n"
                      "#\tgit update-ref -d MERGE_HEAD\n"
                      "# and try again.\n\n");
    fprintf (out, "\n# Please enter the commit message for your changes. "
                  "Lines starting\n# with '#' will be ignored, and an empty "
                  "message aborts the commit.\n#\n");
    /* Who wrote it, when it is not whoever is committing it, and when the
       date is one git calls interesting — which is a commit being amended,
       since it keeps the date it had. */
    char author_who[1024], committer_who[1024];
    git_ident_who (author, author_who, sizeof author_who);
    git_ident_who (committer, committer_who, sizeof committer_who);
    int said = 0;
    if (strcmp (author_who, committer_who)) {
        fprintf (out, "# Author:    %s\n", author_who);
        said = 1;
    }
    if (amend) {
        const char *stamp = strrchr (author, '>');
        char shown[128] = "";
        if (stamp) git_format_date (stamp + 2, 0, shown, sizeof shown);
        fprintf (out, "# Date:      %s\n", shown);
        said = 1;
    }
    if (said) fprintf (out, "#\n");
    if (git_rebase_in_progress (ctx)) {
        /* In the middle of a rebase the note says where that is, which is
           what status says about it too. */
        char onto[41] = "", head_name[4096] = "", abbreviated[41] = "";
        git_rebase_read (ctx, "onto", onto, sizeof onto);
        git_rebase_read (ctx, "head-name", head_name, sizeof head_name);
        if (*onto) git_abbrev (ctx, onto, 7, abbreviated, sizeof abbreviated);
        fprintf (out, "# interactive rebase in progress; onto %s\n",
                 abbreviated);
        char lines[64][1200];
        int n = git_rebase_list (ctx, "done", lines, 64);
        if (!n) fprintf (out, "# No commands done.\n");
        else {
            fprintf (out, "# Last command%s done (%d command%s done):\n",
                     n == 1 ? "" : "s", n, n == 1 ? "" : "s");
            for (int i = n > 2 ? n - 2 : 0; i < n; i++) {
                char shown[1200];
                git_rebase_line_render (ctx, lines[i], 0, shown, sizeof shown);
                fprintf (out, "#    %s\n", shown);
            }
        }
        n = git_rebase_list (ctx, "git-rebase-todo", lines, 64);
        if (!n) fprintf (out, "# No commands remaining.\n");
        else {
            fprintf (out, "# Next command%s to do (%d remaining command%s):\n",
                     n == 1 ? "" : "s", n, n == 1 ? "" : "s");
            for (int i = 0; i < 2 && i < n; i++) {
                char rendered[1200];
                git_rebase_line_render (ctx, lines[i], 0, rendered,
                                        sizeof rendered);
                fprintf (out, "#    %s\n", rendered);
            }
        }
        /* A rebase stopped over a merge is still merging, and that is what
           git says about it rather than where the rebase stands. */
        char merging[41];
        if (git_read_state_id (ctx, "MERGE_HEAD", merging))
            fprintf (out, "\n# All conflicts fixed but you are still "
                          "merging.\n#\n");
        else {
            const char *shown = head_name;
            if (!strncmp (shown, "refs/heads/", 11)) shown += 11;
            fprintf (out, "# You are currently %srebasing branch '%s' on "
                          "'%s'.\n#\n",
                     editing ? "editing a commit while " : "", shown,
                     abbreviated);
        }
    } else {
        if (branch) fprintf (out, "# On branch %s\n", branch);
        /* A repository with no commit yet says so, set apart. */
        if (!state->have_head) fprintf (out, "#\n# Initial commit\n#\n");
    }

    /* What the commit will hold: against HEAD normally, and against what
       HEAD stands on when the commit is being amended, since the one
       being replaced is not part of the answer. */
    char base[41] = "";
    int have_base = state->have_head;
    if (have_base) memcpy (base, state->head_tree, 41);
    if (amend && state->have_head) {
        char parents[BGIT_MAX_PARENTS][41];
        int n_parents = bgit_commit_parents (&ctx->odb, state->head, parents,
                                             BGIT_MAX_PARENTS);
        have_base = n_parents > 0 &&
                    bgit_commit_tree (&ctx->odb, parents[0], base) == 0;
    }
    bgit_status_entry *entries = NULL;
    size_t n = 0;
    if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, state->index,
                     state->n_index, have_base ? base : NULL,
                     0, 0, 1, &entries, &n) < 0)
        return;
    char quoted[8192];
    for (int part = 0; part < 3; part++) {
        int any = 0;
        for (size_t i = 0; i < n; i++) {
            const bgit_status_entry *entry = &entries[i];
            int wanted = part == 0 ? (entry->staged || entry->unmerged)
                       : part == 1 ? (entry->unstaged && !entry->unmerged)
                                   : entry->untracked;
            if (!wanted) continue;
            if (!any) {
                fprintf (out, "# %s\n", part == 0 ? "Changes to be committed:"
                              : part == 1 ? "Changes not staged for commit:"
                                          : "Untracked files:");
                any = 1;
            }
            const char *name = bgit_quote_path (entry->path, quoted,
                                                sizeof quoted);
            if (part == 2) fprintf (out, "#\t%s\n", name);
            else if (entry->unmerged)
                fprintf (out, "#\t%-12s%s\n",
                         git_unmerged_label (entry->unmerged), name);
            else
                fprintf (out, "#\t%-12s%s\n",
                         git_status_label (part == 0 ? entry->staged
                                                     : entry->unstaged), name);
        }
        if (any) fprintf (out, "#\n");
    }
    bgit_status_free (entries, n);
}

/* "Name <email> 1750000000 +0000" cut down to "Name <email>". */
static void
git_ident_who (const char *ident, char *out, size_t outsz)
{
    snprintf (out, outsz, "%s", ident);
    char *close = strrchr (out, '>');
    if (close) close[1] = '\0';
}

static int
git_cmd_commit (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git commit [-q] [-m <message> | -F <file>] [-a] "
                        "[-e | --no-edit] [--amend] [--allow-empty] "
                        "[-S[<key>]] [--no-gpg-sign]";
    const char *messages[16];
    int n_messages = 0;
    const char *message_file = NULL, *signing_key = NULL;
    int all = 0, amend = 0, allow_empty = 0, quiet = 0, sign = -1;
    int edit = 0, no_edit = 0, use_editor = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-m") && p->next) {
            if (n_messages >= (int) (sizeof messages / sizeof *messages))
                return git_fatal ("too many messages");
            messages[n_messages++] = p->next->word->word;
            p = p->next;
        } else if (!strcmp (w, "-F") && p->next) { message_file = p->next->word->word; p = p->next; }
        else if (!strcmp (w, "-a") || !strcmp (w, "--all")) all = 1;
        else if (!strcmp (w, "--amend")) amend = 1;
        else if (!strcmp (w, "--allow-empty")) allow_empty = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-S") || !strcmp (w, "--gpg-sign")) sign = 1;
        else if (!strncmp (w, "-S", 2) && w[2]) { sign = 1; signing_key = w + 2; }
        else if (!strncmp (w, "--gpg-sign=", 11)) { sign = 1; signing_key = w + 11; }
        else if (!strcmp (w, "--no-gpg-sign")) sign = 0;
        else if (!strcmp (w, "-e") || !strcmp (w, "--edit")) edit = 1;
        else if (!strcmp (w, "--no-edit")) no_edit = 1;
        else if (!strcmp (w, "-am") && p->next) {
            all = 1;
            messages[n_messages++] = p->next->word->word;
            p = p->next;
        }
        else return git_usage (usage);
    }
    if (!n_messages && !message_file) {
        /* Concluding a merge has a message ready in MERGE_MSG, which the
           editor is then given to start from, as git gives it. */
        char merge_msg[4096];
        struct stat st;
        if (git_context_open (ctx) == 0 &&
            snprintf (merge_msg, sizeof merge_msg, "%s/MERGE_MSG",
                      ctx->repo.git_dir) < (int) sizeof merge_msg &&
            lstat (merge_msg, &st) == 0)
            message_file = strdup (merge_msg);
        use_editor = !no_edit;
    }
    if (edit) use_editor = 1;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    /* A merge that has not settled cannot be committed. */
    for (size_t i = 0; i < state.n_index; i++)
        if ((state.index[i].flags >> 12) & 3) {
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "error: Committing is not possible because you "
                             "have unmerged files.\n");
            fprintf (stderr, "fatal: Exiting because of an unresolved "
                             "conflict.\n");
            return 1;
        }

    /* A merge left in the tree is concluded by this commit. */
    char merging_with[41] = "";
    char merge_head_file[4096];
    if (snprintf (merge_head_file, sizeof merge_head_file, "%s/MERGE_HEAD",
                  ctx->repo.git_dir) < (int) sizeof merge_head_file) {
        struct stat st;
        unsigned char *content = NULL;
        size_t len = 0;
        if (lstat (merge_head_file, &st) == 0 &&
            bgit_slurp_file (merge_head_file, &content, &len) == 0) {
            if (len >= 40) memcpy (merging_with, content, 40);
            merging_with[len >= 40 ? 40 : 0] = '\0';
            free (content);
        }
    }

    int status = 0;
    if (all) {
        /* -a stages every tracked file that changed or went away. */
        bgit_ignore ignore;
        if (bgit_ignore_load (&ignore, &ctx->repo, &ctx->cfg) < 0) {
            git_state_release (&state);
            return git_fatal ("cannot read the exclude files");
        }
        int changed = 0;
        struct git_add_ctx add = {
            .ctx = ctx, .state = &state, .ignore = &ignore, .pathspec = "",
            .update_only = 1, .dry_run = 0, .changed = &changed
        };
        if (bgit_worktree_walk (&ctx->repo, git_add_visit, &add) < 0)
            status = GIT_EXIT_FATAL;
        for (size_t j = 0; j < state.n_index && !status;) {
            char full[4096];
            snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                      state.index[j].path);
            struct stat st;
            if (lstat (full, &st) == 0) { j++; continue; }
            char *gone = strdup (state.index[j].path);
            if (!gone) { status = GIT_EXIT_FATAL; break; }
            bgit_index_remove_path (&state.index, &state.n_index, gone);
            free (gone);
        }
        bgit_ignore_release (&ignore);
        if (!status && git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
    }
    if (status) { git_state_release (&state); return status; }

    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                         state.n_index, tree) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    /* Nothing staged is not a commit, unless it was asked for. */
    if (!allow_empty && !amend && !*merging_with && state.have_head &&
        strcmp (tree, state.head_tree) == 0) {
        git_state_release (&state);
        fflush (stdout);
        fprintf (stderr, "nothing to commit, working tree clean\n");
        return 1;
    }

    char parents[BGIT_MAX_PARENTS][41];
    int n_parents = 0;
    if (*merging_with && state.have_head) {
        memcpy (parents[0], state.head, 41);
        memcpy (parents[1], merging_with, 41);
        n_parents = 2;
    } else if (amend) {
        if (!state.have_head) {
            git_state_release (&state);
            return git_fatal ("You have nothing to amend.");
        }
        int n = bgit_commit_parents (&ctx->odb, state.head, parents,
                                     BGIT_MAX_PARENTS);
        if (n < 0) { git_state_release (&state); return GIT_EXIT_FATAL; }
        n_parents = n;
    } else if (state.have_head) {
        memcpy (parents[0], state.head, 41);
        n_parents = 1;
    }

    char author[1024], committer[1024];
    {
        int trouble = git_identities (ctx, author, sizeof author, committer,
                                      sizeof committer);
        if (trouble) {
            git_state_release (&state);
            return trouble;
        }
    }

    /* With no message given, one is written in the editor, over whatever
       there is to start from: what -m said, what a merge left in
       MERGE_MSG, or the message of the commit being amended. */
    char editmsg[4096];
    if (use_editor) {
        if (snprintf (editmsg, sizeof editmsg, "%s/COMMIT_EDITMSG",
                      ctx->repo.git_dir) >= (int) sizeof editmsg) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        FILE *out = fopen (editmsg, "w");
        if (!out) {
            git_state_release (&state);
            return git_fatal ("could not write '%s'", editmsg);
        }
        if (message_file) {
            unsigned char *text = NULL;
            size_t text_len = 0;
            if (bgit_slurp_file (message_file, &text, &text_len) == 0) {
                fwrite (text, 1, text_len, out);
                free (text);
            }
        } else if (n_messages) {
            for (int i = 0; i < n_messages; i++)
                fprintf (out, "%s%s\n", i ? "\n" : "", messages[i]);
        } else if (amend) {
            /* The message of the commit being amended, which is whatever
               stands after the blank line in it. */
            enum bgit_type type;
            unsigned char *data = NULL;
            size_t len = 0;
            if (bgit_odb_read (&ctx->odb, state.head, &type, &data, &len) == 0) {
                const char *body = (const char *) data;
                for (size_t i = 0; i + 1 < len; i++)
                    if (body[i] == '\n' && body[i + 1] == '\n') {
                        fwrite (body + i + 2, 1, len - i - 2, out);
                        break;
                    }
                free (data);
            }
        }
        git_commit_template (ctx, out, &state, author, committer, amend, 0);
        fclose (out);
        if (git_edit_file (ctx, editmsg, 0) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        size_t edited_len = 0;
        char *edited = git_message_body (editmsg, &edited_len);
        if (!edited || !edited_len) {
            free (edited);
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "Aborting commit due to empty commit message.\n");
            return 1;
        }
        /* What is left is the message, and the file holds only that. */
        out = fopen (editmsg, "w");
        if (out) {
            fwrite (edited, 1, edited_len, out);
            fclose (out);
        }
        free (edited);
        message_file = editmsg;
        n_messages = 0;
    }

    size_t cap = 4096, len = 0;
    char *body = malloc (cap);
    if (!body) { git_state_release (&state); return GIT_EXIT_FATAL; }
#define GIT_APPEND(...) do { \
    for (;;) { \
        int wrote = snprintf (body + len, cap - len, __VA_ARGS__); \
        if (wrote < 0) { free (body); git_state_release (&state); return GIT_EXIT_FATAL; } \
        if ((size_t) wrote < cap - len) { len += (size_t) wrote; break; } \
        cap *= 2; \
        char *grown = realloc (body, cap); \
        if (!grown) { free (body); git_state_release (&state); return GIT_EXIT_FATAL; } \
        body = grown; \
    } \
} while (0)
    GIT_APPEND ("tree %s\n", tree);
    for (int i = 0; i < n_parents; i++) GIT_APPEND ("parent %s\n", parents[i]);
    GIT_APPEND ("author %s\n", author);
    GIT_APPEND ("committer %s\n", committer);
    GIT_APPEND ("\n");
    char subject[1024] = "";
    if (message_file) {
        unsigned char *text = NULL;
        size_t text_len = 0;
        if (bgit_slurp_file (message_file, &text, &text_len) < 0) {
            free (body); git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        GIT_APPEND ("%.*s", (int) text_len, (const char *) text);
        const char *nl = memchr (text, '\n', text_len);
        size_t take = nl ? (size_t) (nl - (const char *) text) : text_len;
        if (take >= sizeof subject) take = sizeof subject - 1;
        memcpy (subject, text, take);
        subject[take] = '\0';
        free (text);
    } else {
        for (int i = 0; i < n_messages; i++)
            GIT_APPEND ("%s%s\n", i ? "\n" : "", messages[i]);
        /* What the reflog says is the message's first line: a reflog
           entry is one line, and git writes no more of it than that. */
        snprintf (subject, sizeof subject, "%s", messages[0]);
        char *nl = strchr (subject, '\n');
        if (nl) *nl = '\0';
    }
    if (len == 0 || body[len - 1] != '\n') GIT_APPEND ("\n");
#undef GIT_APPEND

    /* A signature stands over the commit as it would be without one, so
       it is made from what has been built and then put back into it. */
    if (sign < 0) sign = bgit_config_bool (&ctx->cfg, "commit.gpgsign", 0);
    if (sign) {
        bgit_ssh_key key;
        char *armour = NULL;
        if (git_signing_key (ctx, signing_key, &key) < 0 ||
            bgit_sshsig_sign (&key, "git", (const unsigned char *) body, len,
                              &armour) < 0) {
            free (body);
            git_state_release (&state);
            return git_fatal ("failed to write commit object");
        }
        size_t signed_len = 0;
        char *signed_body = git_commit_signed (body, len, armour, &signed_len);
        free (armour);
        if (!signed_body) {
            free (body);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        free (body);
        body = signed_body;
        len = signed_len;
    }

    char commit[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                               (const unsigned char *) body, len, 1, commit);
    free (body);
    if (rc < 0) { git_state_release (&state); return GIT_EXIT_FATAL; }

    /* The reflog says how the commit was made, as git's does. */
    char reflog[1200];
    snprintf (reflog, sizeof reflog, "commit%s: %s",
              *merging_with ? " (merge)" : amend ? " (amend)"
              : state.have_head ? "" : " (initial)", subject);
    const char *ref = state.branch ? state.branch : "HEAD";
    const char *old = state.have_head ? state.head : "";
    if (bgit_ref_update (&ctx->repo, ref, commit, amend ? NULL : old, reflog) < 0)
        status = GIT_EXIT_FATAL;
    /* HEAD's own reflog follows the branch it names. */
    if (!status && state.branch)
        bgit_reflog_append (&ctx->repo, "HEAD", state.have_head ? state.head : NULL,
                            commit, reflog);
    /* A commit puts away whatever was in progress, as git's does: the merge
       it concludes, and the cherry-pick or revert whose change it is. */
    if (!status) {
        if (*merging_with) {
            git_remove_state_file (ctx, "MERGE_HEAD");
            git_remove_state_file (ctx, "MERGE_MODE");
        }
        git_remove_state_file (ctx, "MERGE_MSG");
        git_remove_state_file (ctx, "SQUASH_MSG");
        git_remove_state_file (ctx, "CHERRY_PICK_HEAD");
        git_remove_state_file (ctx, "REVERT_HEAD");
    }

    /* The summary git prints: where the commit landed, then what it did. */
    if (!status && !quiet) {
        char abbreviated[41];
        git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
        const char *branch = state.branch &&
                             !strncmp (state.branch, "refs/heads/", 11)
                             ? state.branch + 11 : NULL;
        printf ("[%s%s %s] %s\n", branch ? branch : "detached HEAD",
                state.have_head ? "" : " (root-commit)", abbreviated, subject);
        char author_who[1024], committer_who[1024];
        git_ident_who (author, author_who, sizeof author_who);
        git_ident_who (committer, committer_who, sizeof committer_who);
        if (strcmp (author_who, committer_who))
            printf (" Author: %s\n", author_who);

        /* A merge commit gets no stat, just as `git log` shows a merge no
           diff. */
        if (n_parents <= 1) {
            struct git_diff_format format;
            git_diff_format_init (&format);
            format.shortstat = 1;
            format.summary = 1;
            char parent_tree[41] = "";
            int have_parent = n_parents > 0 &&
                              bgit_commit_tree (&ctx->odb, parents[0],
                                                parent_tree) == 0;
            bgit_diff_entry *entries = NULL;
            size_t n_entries = 0;
            if (bgit_diff_trees (&ctx->odb, have_parent ? parent_tree : NULL,
                                 tree, &entries, &n_entries) == 0) {
                git_find_renames (ctx, &format, &entries, &n_entries, 0);
                git_diff_emit (ctx, stdout, &format, entries, n_entries, 0, "");
                bgit_diff_free (entries, n_entries);
            }
        }
    }
    git_state_release (&state);
    return status;
}

/* ---- log and diff ------------------------------------------------------ */

/* One commit, as its object records it. */
struct git_commit {
    char id[41];
    char tree[41];
    char parents[BGIT_MAX_PARENTS][41];
    int n_parents;
    char author_name[256], author_email[256], author_date[64];
    char committer_name[256], committer_email[256], committer_date[64];
    char *message;
};

static void
git_commit_release (struct git_commit *commit)
{
    free (commit->message);
    memset (commit, 0, sizeof *commit);
}

/* "Name <email> 1750000000 +0000" split into its parts. */
static void
git_split_ident (const char *line, size_t len, char *name, size_t name_sz,
                 char *email, size_t email_sz, char *date, size_t date_sz)
{
    const char *open = memchr (line, '<', len);
    const char *close = open ? memchr (open, '>', len - (size_t) (open - line)) : NULL;
    if (!open || !close) return;
    size_t name_len = (size_t) (open - line);
    while (name_len && line[name_len - 1] == ' ') name_len--;
    if (name_len >= name_sz) name_len = name_sz - 1;
    memcpy (name, line, name_len);
    name[name_len] = '\0';
    size_t email_len = (size_t) (close - open - 1);
    if (email_len >= email_sz) email_len = email_sz - 1;
    memcpy (email, open + 1, email_len);
    email[email_len] = '\0';
    const char *rest = close + 1;
    while (rest < line + len && *rest == ' ') rest++;
    size_t date_len = (size_t) (line + len - rest);
    if (date_len >= date_sz) date_len = date_sz - 1;
    memcpy (date, rest, date_len);
    date[date_len] = '\0';
}

static int
git_commit_read (git_context *ctx, const char *id, struct git_commit *commit)
{
    memset (commit, 0, sizeof *commit);
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0 ||
        type != BGIT_COMMIT) {
        free (data);
        return -1;
    }
    memcpy (commit->id, id, 41);
    const char *p = (const char *) data;
    const char *end = p + len;
    while (p < end) {
        const char *nl = memchr (p, '\n', (size_t) (end - p));
        size_t line = nl ? (size_t) (nl - p) : (size_t) (end - p);
        if (!line) { p = nl ? nl + 1 : end; break; }
        if (line > 5 && !memcmp (p, "tree ", 5)) {
            memcpy (commit->tree, p + 5, 40);
            commit->tree[40] = '\0';
        } else if (line > 7 && !memcmp (p, "parent ", 7) &&
                   commit->n_parents < BGIT_MAX_PARENTS) {
            memcpy (commit->parents[commit->n_parents], p + 7, 40);
            commit->parents[commit->n_parents][40] = '\0';
            commit->n_parents++;
        } else if (line > 7 && !memcmp (p, "author ", 7)) {
            git_split_ident (p + 7, line - 7, commit->author_name,
                             sizeof commit->author_name, commit->author_email,
                             sizeof commit->author_email, commit->author_date,
                             sizeof commit->author_date);
        } else if (line > 10 && !memcmp (p, "committer ", 10)) {
            git_split_ident (p + 10, line - 10, commit->committer_name,
                             sizeof commit->committer_name,
                             commit->committer_email,
                             sizeof commit->committer_email,
                             commit->committer_date,
                             sizeof commit->committer_date);
        }
        if (!nl) { p = end; break; }
        p = nl + 1;
    }
    size_t message_len = (size_t) (end - p);
    commit->message = malloc (message_len + 1);
    if (!commit->message) { free (data); return -1; }
    memcpy (commit->message, p, message_len);
    commit->message[message_len] = '\0';
    free (data);
    return 0;
}

/* The ways git can write a date, as --date= names them. */
enum {
    GIT_DATE_DEFAULT, GIT_DATE_RAW, GIT_DATE_ISO, GIT_DATE_ISO_STRICT,
    GIT_DATE_SHORT, GIT_DATE_RELATIVE, GIT_DATE_HUMAN, GIT_DATE_UNIX,
    GIT_DATE_RFC2822,
    GIT_DATE_STRFTIME
};

/* A --date= option in full: the mode, the strftime pattern a "format:"
   mode carries, and whether the reader's own zone stands in for the one
   the commit recorded, which is what the "-local" suffix asks for. */
struct git_date_format {
    int mode;
    const char *pattern;
    int local;
};

static void
git_date_format_init (struct git_date_format *how)
{
    how->mode = GIT_DATE_DEFAULT;
    how->pattern = NULL;
    how->local = 0;
}

/* One --date= name, as far as its first `len` bytes. */
static int
git_date_named (const char *name, size_t len, const char *word)
{
    return strlen (word) == len && !strncmp (name, word, len);
}

/* Read what a --date= option names into `how`, or -1 for a name this
   build does not write. */
static int
git_date_format_set (struct git_date_format *how, const char *name)
{
    git_date_format_init (how);
    if (!strncmp (name, "format:", 7) || !strncmp (name, "format-local:", 13)) {
        how->local = name[6] == '-';
        how->pattern = strchr (name, ':') + 1;
        how->mode = GIT_DATE_STRFTIME;
        return 0;
    }
    size_t len = strlen (name);
    if (!strcmp (name, "local")) { how->local = 1; return 0; }
    if (len > 6 && !strcmp (name + len - 6, "-local")) {
        how->local = 1;
        len -= 6;
    }
    if (git_date_named (name, len, "default")) how->mode = GIT_DATE_DEFAULT;
    else if (git_date_named (name, len, "raw")) how->mode = GIT_DATE_RAW;
    else if (git_date_named (name, len, "iso") ||
             git_date_named (name, len, "iso8601")) how->mode = GIT_DATE_ISO;
    else if (git_date_named (name, len, "iso-strict") ||
             git_date_named (name, len, "iso8601-strict"))
        how->mode = GIT_DATE_ISO_STRICT;
    else if (git_date_named (name, len, "short")) how->mode = GIT_DATE_SHORT;
    else if (git_date_named (name, len, "relative"))
        how->mode = GIT_DATE_RELATIVE;
    else if (git_date_named (name, len, "human")) how->mode = GIT_DATE_HUMAN;
    else if (git_date_named (name, len, "unix")) how->mode = GIT_DATE_UNIX;
    else if (git_date_named (name, len, "rfc") ||
             git_date_named (name, len, "rfc2822")) how->mode = GIT_DATE_RFC2822;
    else return -1;
    return 0;
}

/* Read a --date= option, or say what is wrong with it: 0, or the status
   the complaint carries. */
static int
git_date_format_read (struct git_date_format *how, const char *name)
{
    if (!strncmp (name, "auto:", 5))
        return git_fatal ("this build's git has no --date=%s yet", name);
    if (git_date_format_set (how, name) < 0)
        return git_fatal ("unknown date format %s", name);
    return 0;
}

/* Written out below, beside the modes each placeholder names. */
static void git_format_date_mode (const char *raw, int mode, char *out,
                                  size_t outsz);

/* git's default date: "Sun Jun 15 12:26:40 2025 +0000", in the commit's own
   zone, which is what the raw "<seconds> <zone>" pair records — or in the
   reader's own, for the modes that end in -local. */
static void
git_format_date_as (const char *raw, const struct git_date_format *how,
                    char *out, size_t outsz)
{
    int mode = how->mode;
    long long seconds = 0;
    char zone[8] = "+0000";
    sscanf (raw, "%lld %7s", &seconds, zone);
    if (mode == GIT_DATE_RAW && !how->local) {
        snprintf (out, outsz, "%lld %s", seconds, zone);
        return;
    }
    if (mode == GIT_DATE_UNIX) {
        snprintf (out, outsz, "%lld", seconds);
        return;
    }
    if (mode == GIT_DATE_RELATIVE) {
        /* How long ago, in the units git chooses for the distance. */
        long long now = (long long) time (NULL);
        long long diff = now > seconds ? now - seconds : 0;
        if (diff < 90) {
            snprintf (out, outsz, "%lld second%s ago", diff,
                      diff == 1 ? "" : "s");
            return;
        }
        diff = (diff + 30) / 60;
        if (diff < 90) {
            snprintf (out, outsz, "%lld minute%s ago", diff,
                      diff == 1 ? "" : "s");
            return;
        }
        diff = (diff + 30) / 60;
        if (diff < 36) {
            snprintf (out, outsz, "%lld hour%s ago", diff, diff == 1 ? "" : "s");
            return;
        }
        diff = (diff + 12) / 24;
        if (diff < 14) {
            snprintf (out, outsz, "%lld day%s ago", diff, diff == 1 ? "" : "s");
            return;
        }
        if (diff < 70) {
            long long weeks = (diff + 3) / 7;
            snprintf (out, outsz, "%lld week%s ago", weeks,
                      weeks == 1 ? "" : "s");
            return;
        }
        if (diff < 365) {
            long long months = (diff + 15) / 30;
            snprintf (out, outsz, "%lld month%s ago", months,
                      months == 1 ? "" : "s");
            return;
        }
        if (diff < 1825) {
            long long total = (diff * 12 * 2 + 365) / (365 * 2);
            long long years = total / 12, months = total % 12;
            if (months)
                snprintf (out, outsz, "%lld year%s, %lld month%s ago", years,
                          years == 1 ? "" : "s", months,
                          months == 1 ? "" : "s");
            else
                snprintf (out, outsz, "%lld year%s ago", years,
                          years == 1 ? "" : "s");
            return;
        }
        long long years = (diff + 183) / 365;
        snprintf (out, outsz, "%lld year%s ago", years, years == 1 ? "" : "s");
        return;
    }

    /* The clock the date is read off: the commit's own zone, or the
       reader's when the mode ends in -local. */
    struct tm tm;
    if (how->local) {
        time_t when = (time_t) seconds;
        /* This builtin outlives any one command, and TZ may have been set
           for this one alone, so the zone is read afresh here. */
        tzset ();
        if (!localtime_r (&when, &tm)) { snprintf (out, outsz, "%s", raw); return; }
        long off = tm.tm_gmtoff, away = off < 0 ? -off : off;
        snprintf (zone, sizeof zone, "%c%02ld%02ld", off < 0 ? '-' : '+',
                  away / 3600, (away / 60) % 60);
    } else {
        int sign = zone[0] == '-' ? -1 : 1;
        int hours = (zone[1] - '0') * 10 + (zone[2] - '0');
        int minutes = (zone[3] - '0') * 10 + (zone[4] - '0');
        time_t shifted = (time_t) (seconds + sign * (hours * 3600 + minutes * 60));
        if (!gmtime_r (&shifted, &tm)) { snprintf (out, outsz, "%s", raw); return; }
        /* The commit's own offset, for a pattern that asks for it, and no
           zone name at all, which is what git leaves out here. */
        tm.tm_gmtoff = sign * (hours * 3600 + minutes * 60);
        tm.tm_zone = "";
    }
    static const char *const days[] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    static const char *const months[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
                                          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    if (mode == GIT_DATE_RAW) {
        snprintf (out, outsz, "%lld %s", seconds, zone);
        return;
    }
    if (mode == GIT_DATE_STRFTIME) {
        if (!strftime (out, outsz, how->pattern, &tm)) *out = '\0';
        return;
    }
    if (mode == GIT_DATE_RFC2822) {
        snprintf (out, outsz, "%s, %d %s %d %02d:%02d:%02d %s",
                  days[tm.tm_wday], tm.tm_mday, months[tm.tm_mon],
                  tm.tm_year + 1900, tm.tm_hour, tm.tm_min, tm.tm_sec, zone);
        return;
    }
    if (mode == GIT_DATE_ISO) {
        snprintf (out, outsz, "%d-%02d-%02d %02d:%02d:%02d %s",
                  tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
                  tm.tm_min, tm.tm_sec, zone);
        return;
    }
    if (mode == GIT_DATE_ISO_STRICT) {
        int offset = ((zone[1] - '0') * 10 + (zone[2] - '0')) * 60 +
                     (zone[3] - '0') * 10 + (zone[4] - '0');
        if (!offset)
            snprintf (out, outsz, "%d-%02d-%02dT%02d:%02d:%02dZ",
                      tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
                      tm.tm_min, tm.tm_sec);
        else
            snprintf (out, outsz, "%d-%02d-%02dT%02d:%02d:%02d%c%c%c:%c%c",
                      tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
                      tm.tm_min, tm.tm_sec, zone[0], zone[1], zone[2], zone[3],
                      zone[4]);
        return;
    }
    if (mode == GIT_DATE_SHORT) {
        snprintf (out, outsz, "%d-%02d-%02d", tm.tm_year + 1900, tm.tm_mon + 1,
                  tm.tm_mday);
        return;
    }
    if (mode == GIT_DATE_HUMAN) {
        /* What the reader can work out for himself is left off: the year
           when it is this one, the date when it is within a few days, the
           time when the year has gone, and the zone when it is his own.
           Today, said within the day, is a distance instead. */
        long long now = (long long) time (NULL);
        struct tm today;
        time_t moment = (time_t) now;
        tzset ();
        int same_year = 0, same_day = 0;
        long local_offset = 0;
        if (localtime_r (&moment, &today)) {
            same_year = today.tm_year == tm.tm_year;
            same_day = same_year && today.tm_mon == tm.tm_mon &&
                       today.tm_mday == tm.tm_mday;
            local_offset = today.tm_gmtoff;
        }
        /* How far back it is, counted in days on the calendar rather than
           in seconds: the reader's day against the date's own. */
        long day_apart = 0;
        {
            struct tm *pair[2] = { &today, &tm };
            long number[2];
            for (int i = 0; i < 2; i++) {
                long y = pair[i]->tm_year + 1900, m = pair[i]->tm_mon + 1,
                     d = pair[i]->tm_mday;
                y -= m <= 2;
                long era = (y >= 0 ? y : y - 399) / 400;
                long yoe = y - era * 400;
                long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
                long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
                number[i] = era * 146097 + doe - 719468;
            }
            day_apart = number[0] - number[1];
        }
        if (same_day && now >= seconds && now - seconds < 24 * 3600) {
            git_format_date_mode (raw, GIT_DATE_RELATIVE, out, outsz);
            return;
        }
        const char *shown_zone = "";
        char with_zone[16] = "";
        if (!how->local && tm.tm_gmtoff != local_offset) {
            snprintf (with_zone, sizeof with_zone, " %s", zone);
            shown_zone = with_zone;
        }
        if (same_year && day_apart >= 0 && day_apart < 5)
            snprintf (out, outsz, "%s %02d:%02d%s", days[tm.tm_wday],
                      tm.tm_hour, tm.tm_min, shown_zone);
        else if (same_year)
            /* Once the date is there the zone is not: git leaves it off
               for anything but the last few days. */
            snprintf (out, outsz, "%s %s %d %02d:%02d", days[tm.tm_wday],
                      months[tm.tm_mon], tm.tm_mday, tm.tm_hour, tm.tm_min);
        else
            snprintf (out, outsz, "%s %d %d", months[tm.tm_mon], tm.tm_mday,
                      tm.tm_year + 1900);
        return;
    }

    /* The day of the month is not padded, and a date read off the
       reader's own clock carries no zone at all. */
    snprintf (out, outsz, "%s %s %d %02d:%02d:%02d %d%s%s",
              days[tm.tm_wday], months[tm.tm_mon], tm.tm_mday, tm.tm_hour,
              tm.tm_min, tm.tm_sec, tm.tm_year + 1900,
              how->local ? "" : " ", how->local ? "" : zone);
}

/* One fixed mode, as the %at, %ai, %aI, %as and %ar placeholders each
   name one of their own. */
static void
git_format_date_mode (const char *raw, int mode, char *out, size_t outsz)
{
    struct git_date_format how;
    git_date_format_init (&how);
    how.mode = mode;
    git_format_date_as (raw, &how, out, outsz);
}

static void
git_format_date (const char *raw, int keep_raw, char *out, size_t outsz)
{
    git_format_date_mode (raw, keep_raw ? GIT_DATE_RAW : GIT_DATE_DEFAULT, out,
                          outsz);
}

/* Is this commit one of the ones asked for? */
static int
git_log_keeps (const struct git_log_filter *filter,
               const struct git_commit *commit)
{
    if (filter->min_parents >= 0 && commit->n_parents < filter->min_parents)
        return 0;
    if (filter->max_parents >= 0 && commit->n_parents > filter->max_parents)
        return 0;
    long long when = git_date_seconds (commit->committer_date);
    if (filter->since >= 0 && when < filter->since) return 0;
    if (filter->until >= 0 && when > filter->until) return 0;
    if (filter->n_authors) {
        char who[1024];
        snprintf (who, sizeof who, "%s <%s>", commit->author_name,
                  commit->author_email);
        int hit = 0;
        for (int i = 0; i < filter->n_authors && !hit; i++)
            hit = git_log_matches (filter, filter->authors[i], who);
        if (!hit) return 0;
    }
    if (filter->n_committers) {
        char who[1024];
        snprintf (who, sizeof who, "%s <%s>", commit->committer_name,
                  commit->committer_email);
        int hit = 0;
        for (int i = 0; i < filter->n_committers && !hit; i++)
            hit = git_log_matches (filter, filter->committers[i], who);
        if (!hit) return 0;
    }
    if (filter->n_patterns) {
        int hit = filter->all_match;
        for (int i = 0; i < filter->n_patterns; i++) {
            int one = git_log_matches (filter, filter->patterns[i],
                                       commit->message);
            if (filter->all_match) hit = hit && one;
            else hit = hit || one;
        }
        if (filter->invert) hit = !hit;
        if (!hit) return 0;
    }
    return 1;
}

/* Does the commit's own diff answer to -S or -G? A merge never does:
   git's diff for one is empty unless it is asked for another. */
static int
git_pickaxe_keeps (git_context *ctx, const struct git_log_filter *filter,
                   const struct git_commit *commit,
                   const char *const *paths, int n_paths)
{
    if (commit->n_parents > 1) return 0;
    char parent_tree[41];
    const char *before = NULL;
    if (commit->n_parents &&
        bgit_commit_tree (&ctx->odb, commit->parents[0], parent_tree) == 0)
        before = parent_tree;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (bgit_diff_trees (&ctx->odb, before, commit->tree, &entries, &n) < 0)
        return 0;
    regex_t compiled;
    int have_regex = 0;
    if (filter->diff_grep) {
        /* -G is always a pattern, and git reads one the extended way. */
        int flags = REG_NEWLINE | REG_EXTENDED |
                    (filter->ignore_case ? REG_ICASE : 0);
        have_regex = regcomp (&compiled, filter->diff_grep, flags) == 0;
        if (!have_regex) { bgit_diff_free (entries, n); return 0; }
    }
    int hit = 0;
    for (size_t i = 0; i < n && !hit; i++) {
        if (n_paths && !git_path_named (entries[i].path, paths, n_paths) &&
            (!entries[i].from || !git_path_named (entries[i].from, paths,
                                                  n_paths)))
            continue;
        unsigned char *old_data = NULL, *new_data = NULL;
        size_t old_len = 0, new_len = 0;
        enum bgit_type type;
        if (entries[i].status != 'A' &&
            bgit_odb_read (&ctx->odb, entries[i].old_sha, &type, &old_data,
                           &old_len) < 0)
            old_data = NULL;
        if (entries[i].status != 'D' &&
            bgit_odb_read (&ctx->odb, entries[i].new_sha, &type, &new_data,
                           &new_len) < 0)
            new_data = NULL;
        if (filter->pickaxe)
            hit = git_pickaxe_count (filter, (const char *) old_data, old_len) !=
                  git_pickaxe_count (filter, (const char *) new_data, new_len);
        else {
            /* Every line the change adds or takes away, against the
               pattern. */
            bgit_xdiff_file old_file, new_file;
            /* A file that was added or taken away is the empty side. */
            bgit_xdiff_load (&old_file, old_data ? (const char *) old_data : "",
                             old_len);
            bgit_xdiff_load (&new_file, new_data ? (const char *) new_data : "",
                             new_len);
            bgit_xdiff_result result;
            if (bgit_xdiff_opts (&old_file, &new_file, 0,
                                 BGIT_XDIFF_TRIM_TAIL, &result) == 0) {
                for (size_t line = 0; line < old_file.n && !hit; line++) {
                    if (!result.old_changed[line]) continue;
                    char held[65536];
                    size_t len = old_file.lengths[line];
                    if (len >= sizeof held) len = sizeof held - 1;
                    memcpy (held, old_file.lines[line], len);
                    held[len] = '\0';
                    hit = regexec (&compiled, held, 0, NULL, 0) == 0;
                }
                for (size_t line = 0; line < new_file.n && !hit; line++) {
                    if (!result.new_changed[line]) continue;
                    char held[65536];
                    size_t len = new_file.lengths[line];
                    if (len >= sizeof held) len = sizeof held - 1;
                    memcpy (held, new_file.lines[line], len);
                    held[len] = '\0';
                    hit = regexec (&compiled, held, 0, NULL, 0) == 0;
                }
                bgit_xdiff_result_release (&result);
            }
            bgit_xdiff_release (&old_file);
            bgit_xdiff_release (&new_file);
        }
        free (old_data);
        free (new_data);
    }
    if (have_regex) regfree (&compiled);
    bgit_diff_free (entries, n);
    return hit;
}

/* The same, for a commit that has not been read yet. */
static int
git_log_keeps_id (git_context *ctx, const struct git_log_filter *filter,
                  const char *id)
{
    if (!git_log_filtering (filter)) return 1;
    struct git_commit commit;
    if (git_commit_read (ctx, id, &commit) < 0) return 1;
    int keep = git_log_keeps (filter, &commit);
    git_commit_release (&commit);
    return keep;
}

/* How long a line is without the whitespace at its end. */
static size_t
git_line_trimmed (const char *line, size_t len)
{
    while (len && (line[len - 1] == ' ' || line[len - 1] == '\t' ||
                   line[len - 1] == '\r'))
        len--;
    return len;
}

/* Where a message's subject begins: git passes over the blank lines at
   the top. */
static const char *
git_message_start (const char *message)
{
    for (const char *line = message; *line;) {
        const char *nl = strchr (line, '\n');
        size_t len = nl ? (size_t) (nl - line) : strlen (line);
        if (git_line_trimmed (line, len)) return line;
        if (!nl) return line + len;
        line = nl + 1;
    }
    return message + strlen (message);
}

/* The subject is everything down to the first blank line, with the line
   breaks inside it written as single spaces: git folds one that way. */
static void
git_subject (const struct git_commit *commit, char *out, size_t outsz)
{
    size_t at = 0;
    *out = '\0';
    for (const char *line = git_message_start (commit->message); *line;) {
        const char *nl = strchr (line, '\n');
        size_t len = git_line_trimmed (line, nl ? (size_t) (nl - line)
                                                : strlen (line));
        if (!len) break;
        if (at && at + 1 < outsz) out[at++] = ' ';
        if (at + len >= outsz) len = outsz > at + 1 ? outsz - at - 1 : 0;
        memcpy (out + at, line, len);
        at += len;
        out[at] = '\0';
        if (!nl) break;
        line = nl + 1;
    }
}

/* The body is what follows the blank line that ends the subject. */
static const char *
git_body (const struct git_commit *commit)
{
    const char *line = git_message_start (commit->message);
    while (*line) {
        const char *nl = strchr (line, '\n');
        size_t len = git_line_trimmed (line, nl ? (size_t) (nl - line)
                                                : strlen (line));
        if (!nl) return line + strlen (line);
        line = nl + 1;
        if (!len) break;
    }
    /* Whatever blank lines stand between the two is not part of either. */
    while (*line == '\n') line++;
    return line;
}

/* How much of a ref's name a decoration carries. */
enum { GIT_DECORATE_NO, GIT_DECORATE_SHORT, GIT_DECORATE_FULL };

/* The names that point at a commit, in the order git lists them: what
   HEAD stands on first, then every other ref in the reverse of the order
   they are read in, which is the order git's own list ends up in. With
   `full`, each name is written out whole, as --decorate=full asks. */
static void
git_decorations (git_context *ctx, const char *id, int full, char *out,
                 size_t outsz)
{
    *out = '\0';
    size_t at = 0;
    char head[41];
    char *symref = NULL;
    int detached = 0;
    if (bgit_ref_resolve (&ctx->repo, "HEAD", head, &symref) == 0 &&
        !strcmp (head, id)) {
        if (symref && !strncmp (symref, "refs/heads/", 11))
            at += (size_t) snprintf (out + at, outsz - at, "HEAD -> %s",
                                     full ? symref : symref + 11);
        else {
            at += (size_t) snprintf (out + at, outsz - at, "HEAD");
            detached = 1;
        }
    }
    const char *shown = symref && !strncmp (symref, "refs/heads/", 11)
                        ? symref : NULL;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (bgit_refs_list (&ctx->repo, "refs/", &refs, &n_refs) == 0) {
        for (size_t i = n_refs; i-- > 0 && at + 2 < outsz;) {
            const char *name = refs[i].name;
            /* A tag decorates the commit it names, however many tag
               objects stand between. */
            char pointed[41];
            if (!strcmp (refs[i].sha, id)) ;
            else if (!strncmp (name, "refs/tags/", 10) &&
                     bgit_peel_to_type (&ctx->odb, refs[i].sha, BGIT_COMMIT,
                                        pointed) == 0 &&
                     !strcmp (pointed, id)) ;
            else continue;
            if (shown && !strcmp (name, shown)) continue;
            const char *label = name;
            char held[4096];
            if (full) ;
            else if (!strncmp (name, "refs/heads/", 11)) label = name + 11;
            else if (!strncmp (name, "refs/remotes/", 13)) label = name + 13;
            if (!strncmp (name, "refs/tags/", 10)) {
                snprintf (held, sizeof held, "tag: %s",
                          full ? name : name + 10);
                label = held;
            }
            at += (size_t) snprintf (out + at, outsz - at, "%s%s",
                                     at ? ", " : "", label);
        }
        bgit_refs_free (refs, n_refs);
    }
    (void) detached;
    free (symref);
}

static void
git_format_commit (git_context *ctx, FILE *out, const struct git_commit *commit,
                   const char *format, const struct git_date_format *date,
                   int full)
{
    char buffer[4096];
    for (const char *p = format; *p; p++) {
        if (*p != '%') { fputc (*p, out); continue; }
        p++;
        switch (*p) {
        case 'H': fputs (commit->id, out); break;
        case 'h': {
            char abbreviated[41];
            git_abbrev (ctx, commit->id, 7, abbreviated, sizeof abbreviated);
            fputs (abbreviated, out);
            break;
        }
        case 'N': {
            char *text = NULL;
            size_t len = 0;
            if (*git_notes_showing &&
                git_note_text (ctx, git_notes_showing, commit->id, &text,
                               &len) == 0) {
                fwrite (text, 1, len, out);
                free (text);
            }
            break;
        }
        case 'T': fputs (commit->tree, out); break;
        case 'P':
            for (int i = 0; i < commit->n_parents; i++)
                fprintf (out, "%s%s", i ? " " : "", commit->parents[i]);
            break;
        case 'p':
            for (int i = 0; i < commit->n_parents; i++) {
                char abbreviated[41];
                git_abbrev (ctx, commit->parents[i], 7, abbreviated,
                            sizeof abbreviated);
                fprintf (out, "%s%s", i ? " " : "", abbreviated);
            }
            break;
        case 'a':
        case 'c': {
            const char *who = *p == 'a' ? commit->author_date
                                        : commit->committer_date;
            const char *name = *p == 'a' ? commit->author_name
                                         : commit->committer_name;
            const char *mail = *p == 'a' ? commit->author_email
                                         : commit->committer_email;
            p++;
            if (*p == 'n') fputs (name, out);
            else if (*p == 'e') fputs (mail, out);
            else if (*p == 'd') {
                git_format_date_as (who, date, buffer, sizeof buffer);
                fputs (buffer, out);
            } else if (*p == 't') {
                git_format_date_mode (who, GIT_DATE_UNIX, buffer, sizeof buffer);
                fputs (buffer, out);
            } else if (*p == 'i') {
                git_format_date_mode (who, GIT_DATE_ISO, buffer, sizeof buffer);
                fputs (buffer, out);
            } else if (*p == 'I') {
                git_format_date_mode (who, GIT_DATE_ISO_STRICT, buffer,
                                      sizeof buffer);
                fputs (buffer, out);
            } else if (*p == 's') {
                git_format_date_mode (who, GIT_DATE_SHORT, buffer,
                                      sizeof buffer);
                fputs (buffer, out);
            } else if (*p == 'r') {
                git_format_date_mode (who, GIT_DATE_RELATIVE, buffer,
                                      sizeof buffer);
                fputs (buffer, out);
            }
            break;
        }
        case 's': {
            git_subject (commit, buffer, sizeof buffer);
            fputs (buffer, out);
            break;
        }
        case 'b': fputs (git_body (commit), out); break;
        /* The whole message, subject and body alike, as it was written. */
        case 'B': fputs (git_message_start (commit->message), out); break;
        case 'd':
        case 'D': {
            /* What names point here, the way git decorates a log line. */
            char decoration[4096];
            git_decorations (ctx, commit->id, full, decoration,
                             sizeof decoration);
            if (!*decoration) break;
            if (*p == 'd') fprintf (out, " (%s)", decoration);
            else fputs (decoration, out);
            break;
        }
        case 'n': fputc ('\n', out); break;
        case 'x': {
            /* %xNN is the byte those two hex digits stand for. */
            int high = isxdigit ((unsigned char) p[1]) ? p[1] : 0;
            int low = high && isxdigit ((unsigned char) p[2]) ? p[2] : 0;
            if (!low) { fputc ('%', out); fputc ('x', out); break; }
            char pair[3] = { (char) high, (char) low, '\0' };
            fputc ((int) strtol (pair, NULL, 16), out);
            p += 2;
            break;
        }
        case '%': fputc ('%', out); break;
        case '\0': return;
        default: fputc ('%', out); fputc (*p, out); break;
        }
    }
    fputc ('\n', out);
}

/* One reflog entry written the way --format= asks: the entry's own two
   placeholders, and the commit's for everything else. */
static void
git_reflog_formatted (git_context *ctx, const char *format, const char *ref,
                      size_t number, const char *id, const char *message)
{
    char selector[4096];
    snprintf (selector, sizeof selector, "%s@{%zu}", ref, number);
    struct git_commit commit;
    int have = git_commit_read (ctx, id, &commit) == 0;
    /* The commit's placeholders are written by the same code the log uses,
       into a string of its own, since that code ends a record with a
       newline and this one is a line of its own. */
    char *shown = NULL;
    size_t shown_len = 0;
    if (have) {
        FILE *capture = open_memstream (&shown, &shown_len);
        if (capture) {
            struct git_date_format date;
            git_date_format_init (&date);
            git_format_commit (ctx, capture, &commit, format, &date, 0);
            fclose (capture);
            if (shown_len && shown[shown_len - 1] == '\n')
                shown[--shown_len] = '\0';
        }
    }
    /* Then this entry's own two, over what came back. */
    const char *at = shown ? shown : format;
    for (; *at; at++) {
        if (at[0] == '%' && at[1] == 'g' &&
            (at[2] == 'd' || at[2] == 'D' || at[2] == 's')) {
            fputs (at[2] == 's' ? message : selector, stdout);
            at += 2;
            continue;
        }
        fputc (*at, stdout);
    }
    fputc ('\n', stdout);
    free (shown);
    if (have) git_commit_release (&commit);
}


/* The commits reachable from REVS but not from EXCLUDES, newest first by
   commit date — which is what `git log A..B` asks for. */
static int
git_collect_commits (git_context *ctx, const char *const *revs, int n_revs,
                     const char *const *excludes, int n_excludes,
                     int first_parent, long limit, char (**out)[41], size_t *n_out)
{
    struct git_walk walk;
    memset (&walk, 0, sizeof walk);
    char (*ordered)[41] = NULL;
    size_t n = 0, cap = 0;

    /* Walk what is excluded first, marking it seen; the main walk then
       steps over all of it, however the two histories meet. */
    for (int i = 0; i < n_excludes; i++) {
        char id[41], commit[41];
        if (git_resolve (ctx, excludes[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            free (walk.seen); free (walk.slots); free (walk.pending);
            return -1;
        }
        if (git_walk_push (ctx, &walk, commit) < 0) goto fail;
    }
    while (walk.n_pending) {
        char current[41];
        memcpy (current, walk.pending[--walk.n_pending].id, 41);
        char parents[BGIT_MAX_PARENTS][41];
        int count = bgit_commit_parents (&ctx->odb, current, parents,
                                         BGIT_MAX_PARENTS);
        for (int i = 0; i < count; i++)
            if (git_walk_push (ctx, &walk, parents[i]) < 0) goto fail;
    }

    for (int i = 0; i < n_revs; i++) {
        char id[41], commit[41];
        if (git_resolve (ctx, revs[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            free (walk.seen); free (walk.slots); free (walk.pending); free (ordered);
            return -1;
        }
        if (git_walk_push (ctx, &walk, commit) < 0) goto fail;
    }
    while (walk.n_pending) {
        size_t best = 0;
        for (size_t i = 1; i < walk.n_pending; i++)
            if (walk.pending[i].date > walk.pending[best].date) best = i;
        char current[41];
        memcpy (current, walk.pending[best].id, 41);
        memmove (walk.pending + best, walk.pending + best + 1,
                 (walk.n_pending - best - 1) * sizeof *walk.pending);
        walk.n_pending--;

        if (limit >= 0 && (long) n >= limit) break;
        if (n == cap) {
            size_t next = cap ? cap * 2 : 32;
            char (*grown)[41] = realloc (ordered, next * sizeof *grown);
            if (!grown) goto fail;
            ordered = grown;
            cap = next;
        }
        memcpy (ordered[n++], current, 41);

        char parents[BGIT_MAX_PARENTS][41];
        int count = bgit_commit_parents (&ctx->odb, current, parents,
                                         BGIT_MAX_PARENTS);
        if (first_parent && count > 1) count = 1;
        for (int i = 0; i < count; i++)
            if (git_walk_push (ctx, &walk, parents[i]) < 0) goto fail;
    }
    free (walk.seen); free (walk.slots);
    free (walk.pending);
    *out = ordered;
    *n_out = n;
    return 0;
fail:
    free (walk.seen); free (walk.slots);
    free (walk.pending);
    free (ordered);
    return -1;
}

/* A deletion and an addition of the same content are one rename. The list
   is the caller's, so the pairing happens where the list was built and not
   where it is printed. Renames are looked for in what has been recorded:
   comparing against the working tree has nothing to compare ids with. */
static void
git_find_renames (git_context *ctx, const struct git_diff_format *format,
                  bgit_diff_entry **entries, size_t *n, int from_worktree)
{
    if (format->no_renames) return;
    /* A comparison that ends at the working tree has the new side hashed
       but not written down, so the files themselves are where its content
       is read from. */
    bgit_detect_renames_in (&ctx->odb, from_worktree ? &ctx->repo : NULL,
                            entries, n);
}

/* Was any form of diff asked for? */
static int
git_diff_wanted (const struct git_diff_format *format)
{
    return format->patch || format->stat || format->numstat ||
           format->shortstat || format->summary || format->name_only ||
           format->name_status || format->raw || format->check;
}

/* What a commit changed, against its first parent — or against nothing, for
   a root commit. git shows no diff for a merge unless asked, so nor does
   this. */
static int
git_commit_changes (git_context *ctx, const struct git_commit *commit,
                    const char *const *paths, int n_paths,
                    bgit_diff_entry **out, size_t *n_out)
{
    char parent_tree[41] = "";
    if (commit->n_parents &&
        bgit_commit_tree (&ctx->odb, commit->parents[0], parent_tree) < 0)
        return -1;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (bgit_diff_trees (&ctx->odb, commit->n_parents ? parent_tree : NULL,
                         commit->tree, &entries, &n) < 0)
        return -1;
    if (n_paths) {
        size_t kept = 0;
        for (size_t i = 0; i < n; i++) {
            int matched = 0;
            for (int j = 0; j < n_paths && !matched; j++)
                if (git_path_in_spec (entries[i].path, paths[j])) matched = 1;
            if (matched) entries[kept++] = entries[i];
            else { free (entries[i].path); free (entries[i].from); }
        }
        n = kept;
    }
    *out = entries;
    *n_out = n;
    return 0;
}

static int
git_commit_diff (git_context *ctx, FILE *out, const struct git_commit *commit,
                 const struct git_diff_format *format,
                 const char *const *paths, int n_paths, const char *separator)
{
    if (commit->n_parents > 1) return 0;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (git_commit_changes (ctx, commit, paths, n_paths, &entries, &n) < 0)
        return -1;
    git_find_renames (ctx, format, &entries, &n, 0);
    /* A commit that changed nothing gets no diff and no line set aside for
       one, which is what git leaves out. */
    if (!n) {
        bgit_diff_free (entries, n);
        return 0;
    }
    if (separator) fputs (separator, out);
    int rc = git_diff_emit (ctx, out, format, entries, n, 0, "");
    bgit_diff_free (entries, n);
    return rc < 0 ? rc : 1;
}

/* Did this commit change anything the pathspec names? That is what decides
   whether `git log -- <path>` shows it. A merge follows its first parent
   here, which is all this build can make. */
static int
git_commit_touches (git_context *ctx, const struct git_commit *commit,
                    const char *const *paths, int n_paths)
{
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (git_commit_changes (ctx, commit, paths, n_paths, &entries, &n) < 0)
        return 1;
    bgit_diff_free (entries, n);
    return n > 0;
}

/* ---- checking what a signature says ------------------------------------- */

/* The signature an object carries, taken back out of it: a commit keeps one
   in a gpgsig header, a tag keeps one after the message. Returns 1 with the
   armour and the bytes it was made over, 0 when nothing is signed, and -1
   when what is there is not a kind this build can check. Both strings are
   the caller's to free. */
static int
git_signature_take (enum bgit_type type, const unsigned char *data, size_t len,
                    char **payload_out, size_t *payload_len, char **armour_out)
{
    static const char opening[] = "-----BEGIN SSH SIGNATURE-----";
    const char *body = (const char *) data;
    const char *end = body + len;
    *payload_out = NULL;
    *armour_out = NULL;

    if (type == BGIT_COMMIT) {
        /* Among the headers, before the blank line the message begins at. */
        const char *start = NULL, *stop = NULL;
        for (const char *at = body; at < end; ) {
            const char *nl = memchr (at, '\n', (size_t) (end - at));
            size_t line = nl ? (size_t) (nl - at) : (size_t) (end - at);
            if (!line) break;
            if (line > 7 && !strncmp (at, "gpgsig ", 7)) {
                start = at;
                stop = nl ? nl + 1 : end;
                while (stop < end && *stop == ' ') {  /* the header goes on */
                    const char *next = memchr (stop, '\n',
                                               (size_t) (end - stop));
                    stop = next ? next + 1 : end;
                }
                break;
            }
            at = nl ? nl + 1 : end;
        }
        if (!start) return 0;

        char *armour = malloc ((size_t) (stop - start) + 1);
        char *payload = malloc (len + 1);
        if (!armour || !payload) {
            free (armour);
            free (payload);
            return -1;
        }
        /* The value, with the space that carries each further line taken
           off again. */
        size_t at_armour = 0;
        for (const char *line = start + 7; line < stop; ) {
            const char *nl = memchr (line, '\n', (size_t) (stop - line));
            size_t n = nl ? (size_t) (nl - line) : (size_t) (stop - line);
            memcpy (armour + at_armour, line, n);
            at_armour += n;
            armour[at_armour++] = '\n';
            line = nl ? nl + 1 : stop;
            if (line < stop && *line == ' ') line++;
        }
        armour[at_armour] = '\0';
        size_t head = (size_t) (start - body);
        memcpy (payload, body, head);
        memcpy (payload + head, stop, (size_t) (end - stop));
        size_t size = head + (size_t) (end - stop);
        payload[size] = '\0';
        if (strncmp (armour, opening, strlen (opening))) {
            free (armour);
            free (payload);
            return -1;
        }
        *payload_out = payload;
        *payload_len = size;
        *armour_out = armour;
        return 1;
    }

    /* A tag's signature stands at the end, so the last block is the one
       that signs it: a message may well talk about signatures. */
    const char *found = NULL, *armoured = NULL;
    for (const char *line = body; line < end; ) {
        const char *nl = memchr (line, '\n', (size_t) (end - line));
        size_t n = nl ? (size_t) (nl - line) : (size_t) (end - line);
        if (n >= 11 && !strncmp (line, "-----BEGIN ", 11)) {
            found = line;
            armoured = n == strlen (opening) && !strncmp (line, opening, n)
                       ? line : NULL;
        }
        line = nl ? nl + 1 : end;
    }
    if (!found) return 0;
    if (!armoured) return -1;
    size_t size = (size_t) (armoured - body);
    char *payload = malloc (size + 1);
    char *armour = malloc ((size_t) (end - armoured) + 1);
    if (!payload || !armour) {
        free (payload);
        free (armour);
        return -1;
    }
    memcpy (payload, body, size);
    payload[size] = '\0';
    memcpy (armour, armoured, (size_t) (end - armoured));
    armour[end - armoured] = '\0';
    *payload_out = payload;
    *payload_len = size;
    *armour_out = armour;
    return 1;
}

/* Say about a signature what git says about it, on OUT — stderr for
   verify-commit, stdout for log --show-signature. Returns 0 when the
   signature is good and somebody vouches for the key it was made with, and
   1 otherwise. With PAYLOAD_OUT, what was signed is left there when there
   was a signature at all, which is what -v prints. */
static int
git_verify_signature (git_context *ctx, FILE *out, const unsigned char *data,
                      size_t len, enum bgit_type type, char **payload_out,
                      size_t *payload_len)
{
    char *payload = NULL, *armour = NULL;
    size_t size = 0;
    int have = git_signature_take (type, data, len, &payload, &size, &armour);
    if (payload_out) *payload_out = NULL;
    if (have <= 0) {
        if (have < 0) {
            fflush (stdout);
            fprintf (stderr, "error: this build checks ssh signatures only\n");
        }
        return 1;
    }
    if (out == stderr) fflush (stdout);

    bgit_ssh_key key;
    int checked = bgit_sshsig_check (armour, "git",
                                     (const unsigned char *) payload, size,
                                     &key);
    free (armour);
    if (payload_out) {
        *payload_out = payload;
        *payload_len = size;
    } else
        free (payload);

    if (checked != 0) {
        fprintf (out, "Could not verify signature.\n");
        if (checked > 0)
            fprintf (out, "Signature verification failed: incorrect "
                          "signature\n");
        return 1;
    }

    char fingerprint[128] = "";
    bgit_ssh_key_fingerprint (&key, fingerprint, sizeof fingerprint);

    /* Whom the key belongs to, if gpg.ssh.allowedSignersFile says. */
    char principal[256] = "";
    const char *named = bgit_config_get (&ctx->cfg,
                                         "gpg.ssh.allowedSignersFile");
    int vouched = 0;
    if (named && *named) {
        char path[4096];
        if (named[0] == '~' && named[1] == '/' && getenv ("HOME"))
            snprintf (path, sizeof path, "%s/%s", getenv ("HOME"), named + 2);
        else
            snprintf (path, sizeof path, "%s", named);
        vouched = bgit_ssh_allowed_signer (path, &key, principal,
                                           sizeof principal) == 1;
    }
    if (vouched)
        fprintf (out, "Good \"git\" signature for %s with ED25519 key %s\n",
                 principal, fingerprint);
    else {
        /* git leans on ssh-keygen here and passes on what it said about the
           file it could not match in; this build says only the outcome. */
        fprintf (out, "Good \"git\" signature with ED25519 key %s\n",
                 fingerprint);
        fprintf (out, "No principal matched.\n");
    }
    return vouched ? 0 : 1;
}

/* What `log --show-signature` sets under the commit line. */
static void
git_show_commit_signature (git_context *ctx, FILE *out, const char *id)
{
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0) return;
    if (type == BGIT_COMMIT)
        git_verify_signature (ctx, out, data, len, type, NULL, NULL);
    free (data);
}

/* One commit as `git log` and `git show` print it: the header, the message
   indented by four spaces, then whatever diff was asked for. */
static void
git_print_commit (git_context *ctx, FILE *out, const struct git_commit *commit,
                  int oneline, const char *format,
                  const struct git_date_format *date, int decorate,
                  int show_signature, const struct git_diff_format *diff,
                  const char *const *paths, int n_paths)
{
    /* What the commit is decorated with, where the format does not say
       for itself: the one-line summary and the header line both carry it. */
    char decoration[4096] = "";
    if (decorate != GIT_DECORATE_NO && !format)
        git_decorations (ctx, commit->id, decorate == GIT_DECORATE_FULL,
                         decoration, sizeof decoration);
    if (oneline) {
        char abbreviated[41], subject[4096];
        git_abbrev (ctx, commit->id, 7, abbreviated, sizeof abbreviated);
        git_subject (commit, subject, sizeof subject);
        if (*decoration)
            fprintf (out, "%s (%s) %s\n", abbreviated, decoration, subject);
        else fprintf (out, "%s %s\n", abbreviated, subject);
    } else if (format) {
        git_format_commit (ctx, out, commit, format, date,
                           decorate == GIT_DECORATE_FULL);
    } else {
        char shown[128];
        git_format_date_as (commit->author_date, date, shown, sizeof shown);
        if (*decoration)
            fprintf (out, "commit %s (%s)\n", commit->id, decoration);
        else fprintf (out, "commit %s\n", commit->id);
        if (show_signature) git_show_commit_signature (ctx, out, commit->id);
        if (commit->n_parents > 1) {
            fprintf (out, "Merge:");
            for (int j = 0; j < commit->n_parents; j++) {
                char abbreviated[41];
                git_abbrev (ctx, commit->parents[j], 7, abbreviated,
                            sizeof abbreviated);
                fprintf (out, " %s", abbreviated);
            }
            fputc ('\n', out);
        }
        fprintf (out, "Author: %s <%s>\n", commit->author_name,
                 commit->author_email);
        fprintf (out, "Date:   %s\n\n", shown);
        /* Every line is indented by four spaces, a blank one included. */
        const char *line = commit->message;
        while (*line) {
            const char *nl = strchr (line, '\n');
            size_t len = nl ? (size_t) (nl - line) : strlen (line);
            if (!nl && !len) break;
            fprintf (out, "    %.*s\n", (int) len, line);
            if (!nl) break;
            line = nl + 1;
        }
        /* A note about this commit goes under its message, set off by a
           blank line and indented the same way. */
        char *note = NULL;
        size_t note_len = 0;
        if (*git_notes_showing &&
            git_note_text (ctx, git_notes_showing, commit->id, &note,
                           &note_len) == 0) {
            /* Notes from anywhere but the usual place say where they are
               from. */
            if (!strcmp (git_notes_showing, GIT_NOTES_REF))
                fputs ("\nNotes:\n", out);
            else {
                const char *shown = !strncmp (git_notes_showing, "refs/notes/", 11)
                                        ? git_notes_showing + 11
                                        : git_notes_showing;
                fprintf (out, "\nNotes (%s):\n", shown);
            }
            const char *at = note;
            const char *stop = note + note_len;
            while (at < stop) {
                const char *nl = memchr (at, '\n', (size_t) (stop - at));
                size_t len = nl ? (size_t) (nl - at) : (size_t) (stop - at);
                if (!nl && !len) break;
                fprintf (out, "    %.*s\n", (int) len, at);
                if (!nl) break;
                at = nl + 1;
            }
            free (note);
        }
    }
    if (diff && git_diff_wanted (diff)) {
        /* The long format keeps a blank line between message and diff; the
           one-line format runs straight into it. With a count and a patch
           both asked for, git puts a line of dashes there instead. Either
           way the line belongs to the diff, and a commit that changed
           nothing has neither. */
        const char *separator = oneline ? NULL
                              : (diff->patch && diff->stat) ? "---\n" : "\n";
        git_commit_diff (ctx, out, commit, diff, paths, n_paths, separator);
    }
}

/* One commit's block, with git's graph column down its left: the first line
   carries the commit itself, every other line the strand it sits on. This
   build draws a straight history, which is all it can make. */
static void
git_print_graph (const char *block)
{
    int first = 1;
    for (const char *line = block; *line;) {
        const char *nl = strchr (line, '\n');
        size_t len = nl ? (size_t) (nl - line) : strlen (line);
        printf ("%s%.*s\n", first ? "* " : "| ", (int) len, line);
        first = 0;
        if (!nl) break;
        line = nl + 1;
    }
}

/* Nothing could be walked: say which of the revisions named is to blame,
   in the words it was written in — a range is reported whole, as git
   reports it. */
static int
git_log_start_trouble (git_context *ctx, const char *const *starts,
                       const char *const *start_words, int n_starts,
                       const char *const *excludes,
                       const char *const *exclude_words, int n_excludes)
{
    char id[41];
    for (int i = 0; i < n_excludes; i++)
        if (git_resolve (ctx, excludes[i], id, NULL) < 0)
            return exclude_words[i][0] == '^'
                   ? git_fatal ("bad revision '%s'", exclude_words[i])
                   : git_fatal_ambiguous (exclude_words[i]);
    for (int i = 0; i < n_starts; i++)
        if (strcmp (starts[i], "HEAD") &&
            git_resolve (ctx, starts[i], id, NULL) < 0)
            return git_fatal_ambiguous (start_words[i]);
    char *branch = NULL;
    if (bgit_symref_read (&ctx->repo, "HEAD", &branch) == 0 && branch) {
        const char *name = !strncmp (branch, "refs/heads/", 11) ? branch + 11
                                                                : branch;
        int fatal = git_fatal ("your current branch '%s' does not have any "
                               "commits yet", name);
        free (branch);
        return fatal;
    }
    return git_fatal_ambiguous ("HEAD");
}

static int
git_cmd_log (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git log [--oneline] [--format=<format>] "
                        "[-p] [--stat] [--graph] [-n <number>] [--reverse] "
                        "[--first-parent] [--date=<format>] "
                        "[--decorate[=short|full|auto|no]] [--show-signature] "
                        "[--grep=<pattern>] [--author=<pattern>] "
                        "[--committer=<pattern>] [-i] [-E] [-F] "
                        "[--invert-grep] [--all-match] "
                        "[--merges | --no-merges] [--min-parents=<n>] "
                        "[--max-parents=<n>] [--since=<date>] "
                        "[--until=<date>] [-S<string>] [-G<pattern>] "
                        "[--pickaxe-regex] [<revision>...]";
    const char *format = NULL;
    int oneline = 0, reverse = 0, first_parent = 0, graph = 0;
    int show_signature = 0, decorate = -1, follow = 0;
    int show_notes = 1;
    const char *notes_ref = NULL;
    struct git_date_format date;
    git_date_format_init (&date);
    struct git_log_filter filter;
    git_log_filter_init (&filter);
    long limit = -1, skip = 0;
    const char *revs[16], *rev_words[16], *excludes[16], *exclude_words[16];
    const char *paths[32];
    int n_revs = 0, n_excludes = 0, n_paths = 0, no_more = 0;
    int option_words = 0;
    git_check_complained = 0;
    struct git_diff_format diff;
    git_diff_format_init (&diff);

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (no_more) {
            if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
            else return git_fatal ("too many paths");
            continue;
        }
        /* A filter option may take the word after it; the helper says so
           by letting go of it. */
        const char *taken = p->next ? p->next->word->word : NULL;
        if (!strcmp (w, "--oneline")) oneline = 1;
        else if ((option_words = git_diff_format_option (&diff, w, taken))) {
            if (option_words == 2) p = p->next;
        }
        else if (git_log_filter_option (&filter, w, &taken)) {
            if (!taken && p->next) p = p->next;
        }
        else if (!strncmp (w, "--format=", 9)) format = w + 9;
        else if (!strncmp (w, "--pretty=", 9)) format = w + 9;
        else if (!strcmp (w, "--reverse")) reverse = 1;
        else if (!strcmp (w, "--first-parent")) first_parent = 1;
        else if (!strncmp (w, "--date=", 7) ||
                 (!strcmp (w, "--date") && p->next)) {
            const char *name = w[6] == '=' ? w + 7 : (p = p->next)->word->word;
            int bad = git_date_format_read (&date, name);
            if (bad) return bad;
        }
        else if (!strcmp (w, "--decorate")) decorate = GIT_DECORATE_SHORT;
        else if (!strcmp (w, "--no-decorate")) decorate = GIT_DECORATE_NO;
        else if (!strncmp (w, "--decorate=", 11)) {
            const char *which = w + 11;
            if (!strcmp (which, "short")) decorate = GIT_DECORATE_SHORT;
            else if (!strcmp (which, "full")) decorate = GIT_DECORATE_FULL;
            else if (!strcmp (which, "no")) decorate = GIT_DECORATE_NO;
            else if (!strcmp (which, "auto")) decorate = -1;
            else return git_fatal ("invalid --decorate option: %s", which);
        }
        else if (!strcmp (w, "--show-signature")) show_signature = 1;
        else if (!strcmp (w, "--no-show-signature")) show_signature = 0;
        else if (!strcmp (w, "--no-notes")) show_notes = 0;
        else if (!strcmp (w, "--notes")) { show_notes = 1; notes_ref = NULL; }
        else if (!strncmp (w, "--notes=", 8)) { show_notes = 1; notes_ref = w + 8; }
        else if (!strcmp (w, "--follow")) follow = 1;
        else if (!strcmp (w, "-n") && p->next) { limit = atol (p->next->word->word); p = p->next; }
        else if (!strncmp (w, "--max-count=", 12)) limit = atol (w + 12);
        else if (!strncmp (w, "--skip=", 7)) skip = atol (w + 7);
        else if (w[0] == '-' && git_all_digits (w + 1)) limit = atol (w + 1);
        else if (!strcmp (w, "--all")) {
            rev_words[n_revs] = w;
            revs[n_revs++] = "--all";
        }
        else if (!strcmp (w, "--graph")) graph = 1;
        else if (w[0] == '^' && w[1]) {
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes))
                return git_fatal ("too many revisions");
            exclude_words[n_excludes] = w;
            excludes[n_excludes++] = w + 1;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (strstr (w, "...")) {
            return git_fatal ("this build's git log has no A...B range yet");
        }
        /* Two dots make a range — unless there is a file of that name,
           which is how `git log ../file` reads. */
        else if (strstr (w, "..") && !git_path_exists (w)) {
            /* A..B: what B has and A does not. Either side may be left out,
               and then means HEAD. */
            char *range = strdup (w);
            if (!range) return GIT_EXIT_FATAL;
            char *dots = strstr (range, "..");
            *dots = '\0';
            const char *left = *range ? range : "HEAD";
            const char *right = dots[2] ? dots + 2 : "HEAD";
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes) ||
                n_revs >= (int) (sizeof revs / sizeof *revs)) {
                free (range);
                return git_fatal ("too many revisions");
            }
            /* Both halves point into `range`, which lives as long as the
               command does: the child exits when it is done. A complaint
               about either half names the range as it was written. */
            exclude_words[n_excludes] = w;
            excludes[n_excludes++] = left;
            rev_words[n_revs] = w;
            revs[n_revs++] = right;
        }
        else if (n_revs < (int) (sizeof revs / sizeof *revs)) {
            rev_words[n_revs] = w;
            revs[n_revs++] = w;
        }
        else return git_fatal ("too many revisions");
    }
    if (format && !strcmp (format, "oneline")) { oneline = 1; format = NULL; }
    if (decorate < 0)
        decorate = isatty (STDOUT_FILENO) ? GIT_DECORATE_SHORT : GIT_DECORATE_NO;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    git_notes_showing[0] = '\0';
    if (show_notes)
        git_notes_ref (ctx, notes_ref, git_notes_showing,
                       sizeof git_notes_showing);

    /* A word that is not a revision but names a file is a path, which is
       how git reads `git log <file>`. The file is looked for from where the
       command was run, as git looks for it. */
    for (int i = 0; i < n_revs;) {
        char probe[41];
        if (!strcmp (revs[i], "--all") ||
            git_resolve (ctx, revs[i], probe, NULL) == 0) { i++; continue; }
        struct stat st;
        if (lstat (revs[i], &st) != 0 ||
            n_paths >= (int) (sizeof paths / sizeof *paths)) { i++; continue; }
        paths[n_paths++] = revs[i];
        for (int j = i; j + 1 < n_revs; j++) {
            revs[j] = revs[j + 1];
            rev_words[j] = rev_words[j + 1];
        }
        n_revs--;
    }
    /* Every path, however it was given, is read from where it was written. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    if (follow && n_paths != 1)
        return git_fatal ("--follow requires exactly one pathspec");

    /* --all means every ref there is, however many that is; otherwise HEAD,
       unless revisions were named. */
    int want_all = 0;
    for (int i = 0; i < n_revs; i++)
        if (!strcmp (revs[i], "--all")) want_all = 1;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (want_all && bgit_refs_list (&ctx->repo, "refs/", &refs, &n_refs) < 0)
        return git_fatal ("cannot read refs");
    const char **starts = malloc ((n_refs + (size_t) n_revs + 1) * sizeof *starts);
    const char **start_words =
        malloc ((n_refs + (size_t) n_revs + 1) * sizeof *start_words);
    if (!starts || !start_words) {
        free (starts);
        free (start_words);
        bgit_refs_free (refs, n_refs);
        return GIT_EXIT_FATAL;
    }
    int n_starts = 0;
    for (size_t i = 0; i < n_refs; i++) {
        start_words[n_starts] = refs[i].name;
        starts[n_starts++] = refs[i].name;
    }
    for (int i = 0; i < n_revs; i++)
        if (strcmp (revs[i], "--all")) {
            start_words[n_starts] = rev_words[i];
            starts[n_starts++] = revs[i];
        }
    if (!n_starts) {
        start_words[n_starts] = "HEAD";
        starts[n_starts++] = "HEAD";
    }

    char (*ordered)[41] = NULL;
    size_t n = 0;
    /* With a pathspec the limit counts what is shown, not what is walked. */
    /* With anything to sift through, the limit counts what is shown. */
    int sifting = n_paths || git_log_filtering (&filter) ||
                  git_log_pickaxing (&filter);
    /* What is skipped still has to be walked, so the walk's own limit makes
       room for it. */
    long walk_limit = sifting || limit < 0 ? -1 : limit + skip;
    int rc = git_collect_commits (ctx, starts, n_starts, excludes, n_excludes,
                                  first_parent, walk_limit, &ordered, &n);
    if (rc < 0) {
        int fatal = git_log_start_trouble (ctx, starts, start_words, n_starts,
                                           excludes, exclude_words, n_excludes);
        free (starts);
        free (start_words);
        bgit_refs_free (refs, n_refs);
        return fatal;
    }
    free (starts);
    free (start_words);
    bgit_refs_free (refs, n_refs);

    long shown = 0, skipped = 0;
    int first = 1;
    /* With --follow the path is what the file was called at that point,
       which changes as the walk passes the commit that renamed it. */
    char followed[4096] = "";
    const char *follow_paths[1];
    if (follow) {
        snprintf (followed, sizeof followed, "%s", paths[0]);
        follow_paths[0] = followed;
    }
    /* What --skip passes over, it passes over in the order the walk found
       it, before anything is turned round. Where there is something to sift
       through, only the commits that get through can be counted, so the
       skipping waits for the loop. */
    size_t from = 0;
    if (!sifting) {
        from = (size_t) skip < n ? (size_t) skip : n;
        skip = 0;
    }
    for (size_t k = 0; k + from < n; k++) {
        size_t i = reverse ? n - 1 - k : from + k;
        struct git_commit commit;
        if (git_commit_read (ctx, ordered[i], &commit) < 0) continue;
        const char *const *against = follow ? follow_paths : paths;
        int n_against = n_paths;
        /* A rename cannot be followed through two parents at once, so
           --follow passes a merge by, as git passes it by. */
        if (follow && commit.n_parents > 1) {
            git_commit_release (&commit);
            continue;
        }
        char *renamed = NULL;
        const char *follow_pair[2];
        if (follow && commit.n_parents) {
            renamed = git_blame_renamed_from (ctx, commit.parents[0],
                                              commit.id, followed);
            if (renamed) {
                /* Both names, so that the change reads as the rename it
                   is rather than as a file appearing from nowhere. */
                follow_pair[0] = followed;
                follow_pair[1] = renamed;
                against = follow_pair;
                n_against = 2;
            }
        }
        if (n_paths && !git_commit_touches (ctx, &commit, against, n_against)) {
            git_commit_release (&commit);
            free (renamed);
            continue;
        }
        if (!git_log_keeps (&filter, &commit)) {
            git_commit_release (&commit);
            continue;
        }
        if (git_log_pickaxing (&filter) &&
            !git_pickaxe_keeps (ctx, &filter, &commit, paths, n_paths)) {
            git_commit_release (&commit);
            continue;
        }
        /* whatchanged shows a commit only where there is something to show
           under it. */
        if (git_headers_need_a_diff &&
            !git_commit_touches (ctx, &commit, paths, n_paths)) {
            git_commit_release (&commit);
            continue;
        }
        /* --skip passes over the first few of what would have been shown. */
        if (skipped < skip) {
            skipped++;
            git_commit_release (&commit);
            continue;
        }
        if (limit >= 0 && shown >= limit) { git_commit_release (&commit); break; }
        if (graph && commit.n_parents > 1) {
            git_commit_release (&commit);
            free (ordered);
            return git_fatal ("this build's git log --graph draws a straight "
                              "history only; this one has a merge");
        }
        if (!oneline && !format && !first) printf (graph ? "| \n" : "\n");
        if (graph) {
            /* Capture the block, then set it beside the graph column. */
            char *block = NULL;
            size_t size = 0;
            FILE *capture = open_memstream (&block, &size);
            if (!capture) { git_commit_release (&commit); free (ordered); return GIT_EXIT_FATAL; }
            git_print_commit (ctx, capture, &commit, oneline, format, &date,
                              decorate, show_signature, &diff, against,
                              n_against);
            fclose (capture);
            git_print_graph (block);
            free (block);
        } else
            git_print_commit (ctx, stdout, &commit, oneline, format, &date,
                              decorate, show_signature, &diff, against,
                              n_against);
        first = 0;
        shown++;
        if (renamed) {
            snprintf (followed, sizeof followed, "%s", renamed);
            free (renamed);
        }
        git_commit_release (&commit);
    }
    free (ordered);
    return git_check_complained ? 2 : 0;
}

static void
git_diff_format_init (struct git_diff_format *format)
{
    memset (format, 0, sizeof *format);
    format->context = 3;
}

/* Take W if it selects a format, and say whether it did. */
/* git takes at most one of --name-only, --name-status, --check and -s. */
static int
git_diff_format_done (const struct git_diff_format *format)
{
    int asked = (format->name_only != 0) + (format->name_status != 0) +
                (format->check != 0) + (format->no_patch != 0);
    if (asked < 2) return 0;
    return git_fatal ("options '--name-only', '--name-status', '--check', "
                      "and '-s' cannot be used together");
}

static int
git_diff_format_option (struct git_diff_format *format, const char *w,
                        const char *next)
{
    if (!strcmp (w, "-p") || !strcmp (w, "-u") || !strcmp (w, "--patch"))
        format->patch = 1;
    else if (!strcmp (w, "--stat")) format->stat = 1;
    else if (!strcmp (w, "--word-diff")) { format->patch = 1; format->word_diff = 1; }
    else if (!strncmp (w, "--word-diff=", 12)) {
        const char *mode = w + 12;
        if (!strcmp (mode, "plain")) { format->patch = 1; format->word_diff = 1; }
        else if (!strcmp (mode, "porcelain")) {
            format->patch = 1;
            format->word_diff = 2;
        } else if (!strcmp (mode, "none")) format->word_diff = 0;
        else return 0;
    }
    else if (!strncmp (w, "--stat=", 7)) {
        /* --stat=<width>[,<name-width>[,<count>]] */
        format->stat = 1;
        const char *at = w + 7;
        int *fields[3] = { &format->stat_layout.width,
                           &format->stat_layout.name_width,
                           &format->stat_layout.count };
        for (int i = 0; i < 3 && *at; i++) {
            *fields[i] = atoi (at);
            const char *comma = strchr (at, ',');
            if (!comma) break;
            at = comma + 1;
        }
    }
    else if (!strncmp (w, "--stat-width=", 13)) {
        format->stat = 1;
        format->stat_layout.width = atoi (w + 13);
    }
    else if (!strncmp (w, "--stat-name-width=", 18)) {
        format->stat = 1;
        format->stat_layout.name_width = atoi (w + 18);
    }
    else if (!strncmp (w, "--stat-graph-width=", 19)) {
        format->stat = 1;
        format->stat_layout.graph_width = atoi (w + 19);
    }
    else if (!strncmp (w, "--stat-count=", 13)) {
        format->stat = 1;
        format->stat_layout.count = atoi (w + 13);
    }
    else if (!strcmp (w, "--numstat")) format->numstat = 1;
    else if (!strcmp (w, "--shortstat")) format->shortstat = 1;
    else if (!strcmp (w, "--summary")) format->summary = 1;
    else if (!strcmp (w, "--name-only")) format->name_only = 1;
    else if (!strcmp (w, "--name-status")) format->name_status = 1;
    else if (!strcmp (w, "--raw")) format->raw = 1;
    else if (!strcmp (w, "--check")) format->check = 1;
    else if (!strcmp (w, "--exit-code")) format->exit_code = 1;
    /* -z ends each record with NUL and writes the names as they are. */
    else if (!strcmp (w, "-z")) format->zero = 1;
    /* --relative keeps to what is under here and names it from here. */
    else if (!strcmp (w, "--relative")) format->relative = 1;
    else if (!strncmp (w, "--relative=", 11)) {
        format->relative = 1;
        format->relative_to = w + 11;
    }
    else if (!strcmp (w, "--no-relative")) {
        format->relative = 0;
        format->relative_to = NULL;
    }
    /* --quiet is that and nothing printed at all. */
    else if (!strcmp (w, "--quiet")) {
        format->patch = format->stat = format->numstat = format->shortstat = 0;
        format->summary = format->name_only = format->name_status = 0;
        format->raw = format->check = 0;
        format->no_patch = 1;
        format->exit_code = 1;
    }
    /* -s forgets every output form asked for before it, as git's does. */
    else if (!strcmp (w, "-s") || !strcmp (w, "--no-patch")) {
        format->patch = format->stat = format->numstat = format->shortstat = 0;
        format->summary = format->name_only = format->name_status = 0;
        format->raw = format->check = 0;
        format->no_patch = 1;
    }
    /* Asking for a width of context asks for the patch it belongs to. */
    else if (!strncmp (w, "-U", 2) && w[2] >= '0' && w[2] <= '9') {
        format->context = atoi (w + 2);
        format->patch = 1;
    }
    else if (!strncmp (w, "--unified=", 10)) {
        format->context = atoi (w + 10);
        format->patch = 1;
    }
    /* How much further two nearby hunks may reach to become one. It does
       not itself ask for a patch, and git accepts the value as either the
       next word or the right side of an equals sign. */
    else if (!strncmp (w, "--inter-hunk-context=", 21)) {
        const char *value = w + 21;
        const char *digits = *value == '-' ? value + 1 : value;
        if (!git_all_digits (digits)) return 0;
        format->inter_context = atoi (value);
        format->inter_context_set = 1;
    }
    else if (!strcmp (w, "--inter-hunk-context")) {
        const char *digits = next && *next == '-' ? next + 1 : next;
        if (!digits || !git_all_digits (digits)) return 0;
        format->inter_context = atoi (next);
        format->inter_context_set = 1;
        return 2;
    }
    /* Whitespace a comparison may overlook. git lets several be named and
       uses the widest; the bits are in that order, so this only gathers
       them. */
    else if (!strcmp (w, "-w") || !strcmp (w, "--ignore-all-space"))
        format->ignore_ws |= BGIT_XDIFF_IGNORE_WS;
    else if (!strcmp (w, "-b") || !strcmp (w, "--ignore-space-change"))
        format->ignore_ws |= BGIT_XDIFF_IGNORE_WS_CHANGE;
    else if (!strcmp (w, "--ignore-space-at-eol"))
        format->ignore_ws |= BGIT_XDIFF_IGNORE_WS_AT_EOL;
    else if (!strcmp (w, "--ignore-cr-at-eol"))
        format->ignore_ws |= BGIT_XDIFF_IGNORE_CR_AT_EOL;
    /* The whole of the definition a change sits in, however far it runs. */
    else if (!strcmp (w, "--ignore-blank-lines"))
        format->ignore_blank_lines = 1;
    /* The whole of the definition a change sits in, however far it runs.
       Unlike a width of context, this does not ask for the patch itself. */
    else if (!strcmp (w, "-W") || !strcmp (w, "--function-context"))
        format->function_context = 1;
    else if (!strcmp (w, "-R")) format->reverse = 1;
    else if (!strcmp (w, "--no-prefix")) format->no_prefix = 1;
    else if (!strcmp (w, "--no-renames")) format->no_renames = 1;
    else if (!strcmp (w, "-M") || !strcmp (w, "--find-renames"))
        format->no_renames = 0;
    else if (!strcmp (w, "--no-color") || !strcmp (w, "--no-ext-diff") ||
             !strcmp (w, "--no-textconv")) {
        /* Already how this build behaves. */
    } else if (!strcmp (w, "--minimal") ||
               !strcmp (w, "--diff-algorithm=minimal")) {
        format->algorithm = BGIT_DIFF_ALGORITHM_MINIMAL;
        format->algorithm_set = 1;
    }
    else if (!strcmp (w, "--diff-algorithm=myers") ||
             !strcmp (w, "--diff-algorithm=default")) {
        format->algorithm = BGIT_DIFF_ALGORITHM_DEFAULT;
        format->algorithm_set = 1;
    }
    else if (!strcmp (w, "--patience") ||
             !strcmp (w, "--diff-algorithm=patience")) {
        format->algorithm = BGIT_DIFF_ALGORITHM_PATIENCE;
        format->algorithm_set = 1;
    }
    else if (!strcmp (w, "--histogram") ||
             !strcmp (w, "--diff-algorithm=histogram")) {
        format->algorithm = BGIT_DIFF_ALGORITHM_HISTOGRAM;
        format->algorithm_set = 1;
    }
    else return 0;
    return 1;
}

/* The command line wins over diff.interHunkContext. The configuration uses
   git's scaled integer spelling, so k, m and g are powers of 1024. */
static int
git_diff_inter_context (git_context *ctx,
                        const struct git_diff_format *format, int *result)
{
    *result = format->inter_context;
    if (format->inter_context_set) return 0;
    const char *value = bgit_config_get (&ctx->cfg, "diff.interHunkContext");
    if (!value) return 0;

    char *end = NULL;
    errno = 0;
    long amount = strtol (value, &end, 10);
    long multiplier = 1;
    if (end == value) {
        git_fatal ("bad numeric config value '%s' for "
                   "'diff.interhunkcontext': invalid unit", value);
        return -1;
    }
    if (end && *end) {
        if ((end[0] == 'k' || end[0] == 'K') && !end[1])
            multiplier = 1024;
        else if ((end[0] == 'm' || end[0] == 'M') && !end[1])
            multiplier = 1024L * 1024L;
        else if ((end[0] == 'g' || end[0] == 'G') && !end[1])
            multiplier = 1024L * 1024L * 1024L;
        else {
            git_fatal ("bad numeric config value '%s' for "
                       "'diff.interhunkcontext': invalid unit", value);
            return -1;
        }
    }
    if (amount < 0) {
        git_fatal ("unable to parse 'diff.interhunkcontext' from "
                   "command-line config");
        return -1;
    }
    if (errno == ERANGE || amount > INT_MAX / multiplier) {
        git_fatal ("bad numeric config value '%s' for "
                   "'diff.interhunkcontext': out of range", value);
        return -1;
    }
    *result = (int) (amount * multiplier);
    return 0;
}

/* Show a list of changed paths in whichever forms were asked for. The new
   side comes from the working tree when NEW_FROM_WORKTREE, so `git diff`
   reads files rather than blobs that were never written. */
static int
git_diff_emit (git_context *ctx, FILE *out,
               const struct git_diff_format *format,
               const bgit_diff_entry *entries, size_t n, int new_from_worktree,
               const char *line_prefix)
{
    bgit_patch_options options;
    bgit_patch_options_init (&options);
    options.context = format->context;
    if (git_diff_inter_context (ctx, format, &options.inter_context) < 0)
        return -1;
    options.algorithm = format->algorithm;
    if (!format->algorithm_set) {
        const char *algorithm = bgit_config_get (&ctx->cfg, "diff.algorithm");
        if (algorithm) {
            if (!strcasecmp (algorithm, "minimal"))
                options.algorithm = BGIT_DIFF_ALGORITHM_MINIMAL;
            else if (!strcasecmp (algorithm, "patience"))
                options.algorithm = BGIT_DIFF_ALGORITHM_PATIENCE;
            else if (!strcasecmp (algorithm, "histogram"))
                options.algorithm = BGIT_DIFF_ALGORITHM_HISTOGRAM;
            else if (!strcasecmp (algorithm, "default") ||
                     !strcasecmp (algorithm, "myers"))
                options.algorithm = BGIT_DIFF_ALGORITHM_DEFAULT;
            else {
                git_fatal ("unsupported diff.algorithm: %s", algorithm);
                return -1;
            }
        }
    }
    /* --relative leaves out what is not under the place it names, and names
       the rest from there. */
    char relative[4200] = "";
    bgit_relative_to = NULL;
    bgit_diff_entry *kept = NULL;
    if (format->relative) {
        if (format->relative_to && *format->relative_to)
            snprintf (relative, sizeof relative, "%s%s%s", ctx->prefix,
                      format->relative_to,
                      format->relative_to[strlen (format->relative_to) - 1] == '/'
                      ? "" : "/");
        else snprintf (relative, sizeof relative, "%s", ctx->prefix);
        if (*relative) {
            bgit_relative_to = relative;
            kept = calloc (n ? n : 1, sizeof *kept);
            if (!kept) return -1;
            size_t left = 0;
            size_t under = strlen (relative);
            for (size_t i = 0; i < n; i++)
                if (!strncmp (entries[i].path, relative, under))
                    kept[left++] = entries[i];
            entries = kept;
            n = left;
        }
    }
    options.new_from_worktree = new_from_worktree;
    options.word_diff = format->word_diff;
    options.ignore_ws = format->ignore_ws;
    options.function_context = format->function_context;
    options.ignore_blank_lines = format->ignore_blank_lines;
    options.line_prefix = line_prefix ? line_prefix : "";
    if (format->no_prefix) options.prefix_old = options.prefix_new = "";
    /* -R shows the change as it would be to undo: the sides swap, and so
       do the letters in front of the paths. */
    bgit_diff_entry *turned = NULL;
    if (format->reverse && n) {
        turned = calloc (n, sizeof *turned);
        if (!turned) return -1;
        for (size_t i = 0; i < n; i++) {
            turned[i] = entries[i];
            memcpy (turned[i].old_sha, entries[i].new_sha, 41);
            memcpy (turned[i].new_sha, entries[i].old_sha, 41);
            turned[i].old_mode = entries[i].new_mode;
            turned[i].new_mode = entries[i].old_mode;
            turned[i].status = entries[i].status == 'A' ? 'D'
                             : entries[i].status == 'D' ? 'A'
                             : entries[i].status;
        }
        entries = turned;
        if (!format->no_prefix) {
            options.prefix_old = "b/";
            options.prefix_new = "a/";
        }
        options.new_from_worktree = 0;
    }

    if (format->check) {
        int found = bgit_patch_check (out, &ctx->odb, &ctx->repo, entries, n,
                                      &options);
        free (turned);
        free (kept);
        if (found > 0) git_check_complained = 1;
        return found < 0 ? -1 : found ? 2 : 0;
    }

    int named = format->name_only || format->name_status;
    int stats = format->stat || format->numstat || format->shortstat;
    int patch = format->patch || (!named && !stats && !format->summary &&
                                  !format->raw && !format->no_patch);

    /* With -z a record ends in NUL and a name stands as it is, since there
       is nothing it could be confused with. */
    char record_end = format->zero ? '\0' : '\n';
    if (format->raw) {
        /* What each file was and what it became: the two modes, the two
           ids as far as they are abbreviated, and what happened. */
        for (size_t i = 0; i < n; i++) {
            char quoted[8192], old_id[41], new_id[41];
            const char *shown_path = entries[i].path;
            if (bgit_relative_to &&
                !strncmp (shown_path, bgit_relative_to,
                          strlen (bgit_relative_to)))
                shown_path += strlen (bgit_relative_to);
            const char *name = format->zero ? shown_path
                : bgit_quote_path (shown_path, quoted, sizeof quoted);
            git_abbrev (ctx, entries[i].old_sha, options.abbrev, old_id,
                        sizeof old_id);
            git_abbrev (ctx, entries[i].new_sha, options.abbrev, new_id,
                        sizeof new_id);
            if (entries[i].status == 'A')
                snprintf (old_id, sizeof old_id, "%.*s", options.abbrev,
                          "0000000000000000000000000000000000000000");
            if (entries[i].status == 'D')
                snprintf (new_id, sizeof new_id, "%.*s", options.abbrev,
                          "0000000000000000000000000000000000000000");
            fprintf (out, "%s:%06o %06o %s %s ", options.line_prefix,
                     entries[i].old_mode, entries[i].new_mode, old_id, new_id);
            if (entries[i].status == 'R') {
                char from_quoted[8192];
                const char *from = format->zero ? entries[i].from
                    : bgit_quote_path (entries[i].from, from_quoted,
                                       sizeof from_quoted);
                fprintf (out, "R%d%c%s%c%s%c",
                         entries[i].score * 100 / 60000, record_end, from,
                         record_end, name, record_end);
            } else fprintf (out, "%c%c%s%c", entries[i].status,
                            format->zero ? '\0' : '\t', name, record_end);
        }
    }
    if (named) {
        for (size_t i = 0; i < n; i++) {
            char quoted[8192];
            const char *shown_path = entries[i].path;
            if (bgit_relative_to &&
                !strncmp (shown_path, bgit_relative_to,
                          strlen (bgit_relative_to)))
                shown_path += strlen (bgit_relative_to);
            const char *name = format->zero ? shown_path
                : bgit_quote_path (shown_path, quoted, sizeof quoted);
            if (format->name_status && entries[i].status == 'R') {
                char from_quoted[8192];
                const char *from = format->zero ? entries[i].from
                    : bgit_quote_path (entries[i].from, from_quoted,
                                       sizeof from_quoted);
                fprintf (out, "%sR%d%c%s%c%s%c", options.line_prefix,
                         entries[i].score * 100 / 60000,
                         format->zero ? '\0' : '\t', from,
                         format->zero ? '\0' : '\t', name, record_end);
            } else if (format->name_status)
                fprintf (out, "%s%c%c%s%c", options.line_prefix,
                         entries[i].status, format->zero ? '\0' : '\t', name,
                         record_end);
            else fprintf (out, "%s%s%c", options.line_prefix, name, record_end);
        }
    }
    if (stats || format->summary) {
        bgit_diffstat_entry *counted = NULL;
        if (stats) {
            size_t n_counted = 0;
            if (bgit_diffstat (&ctx->odb, &ctx->repo, entries, n, &options,
                               &counted, &n_counted) < 0) {
                free (turned);
        free (kept);
                return -1;
            }
            if (format->numstat) bgit_numstat_write (out, counted, n_counted);
            if (format->stat) bgit_diffstat_write (out, counted, n_counted,
                                                   options.line_prefix,
                                                   &format->stat_layout);
            if (format->shortstat) bgit_shortstat_write (out, counted, n_counted,
                                                         options.line_prefix);
            free (counted);
        }
        if (format->summary)
            bgit_diff_summary (out, entries, n, options.line_prefix);
    }
    /* git keeps a blank line between what it counted and the patch —
       when there was something to count, which a summary of a change that
       creates and removes nothing has not. */
    int counted_anything = n && (format->stat || format->numstat ||
                                 format->shortstat);
    if (n && format->summary && !counted_anything)
        for (size_t i = 0; i < n && !counted_anything; i++)
            if (entries[i].status != 'M' ||
                entries[i].old_mode != entries[i].new_mode)
                counted_anything = 1;
    if (patch && counted_anything) fputc ('\n', out);
    if (patch &&
        bgit_patch_write (out, &ctx->odb, &ctx->repo, entries, n, &options) < 0) {
        free (turned);
        free (kept);
        return -1;
    }
    free (turned);
    free (kept);
    return 0;
}

static int
git_cmd_diff (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git diff [-p] [--stat] [--name-only | --name-status] "
                        "[--cached] [<commit> [<commit>]] [-- <path>...]";
    struct git_diff_format format;
    git_diff_format_init (&format);
    int cached = 0, no_more = 0, option_words = 0;
    const char *revs[2] = { NULL, NULL };
    int n_revs = 0;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && (!strcmp (w, "--cached") || !strcmp (w, "--staged"))) cached = 1;
        else if (!no_more &&
                 (option_words = git_diff_format_option
                                  (&format, w,
                                   p->next ? p->next->word->word : NULL))) {
            if (option_words == 2) p = p->next;
        }
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (!no_more && n_revs < 2) revs[n_revs++] = w;
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (git_diff_format_done (&format) != 0) return GIT_EXIT_FATAL;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* A word that is not a revision but names a file is a path, which is
       how git reads `git diff <file>`. */
    for (int i = 0; i < n_revs;) {
        char probe[41];
        struct stat here;
        if (git_resolve (ctx, revs[i], probe, NULL) == 0 ||
            lstat (revs[i], &here) != 0) {
            i++;
            continue;
        }
        if (n_paths < (int) (sizeof paths / sizeof *paths))
            paths[n_paths++] = revs[i];
        for (int k = i; k + 1 < n_revs; k++) revs[k] = revs[k + 1];
        n_revs--;
    }
    /* Every path, however it was given, is read from where it was written. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    int rc = 0;
    if (n_revs == 2) {
        char a[41], b[41], tree_a[41], tree_b[41];
        if (git_resolve (ctx, revs[0], a, NULL) < 0 ||
            git_resolve (ctx, revs[1], b, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, a, BGIT_TREE, tree_a) < 0 ||
            bgit_peel_to_type (&ctx->odb, b, BGIT_TREE, tree_b) < 0) {
            git_state_release (&state);
            return git_fatal ("bad revision");
        }
        rc = bgit_diff_trees (&ctx->odb, tree_a, tree_b, &entries, &n);
    } else if (cached) {
        const char *base = n_revs ? revs[0] : (state.have_head ? "HEAD" : NULL);
        char tree[41] = "";
        if (base) {
            char id[41];
            if (git_resolve (ctx, base, id, NULL) < 0 ||
                bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0) {
                git_state_release (&state);
                return git_fatal ("bad revision");
            }
        }
        rc = bgit_diff_tree_index (&ctx->odb, base ? tree : NULL, state.index,
                                   state.n_index, &entries, &n);
    } else if (n_revs == 1) {
        /* A commit against the working tree: through the index, then on. */
        char id[41], tree[41];
        if (git_resolve (ctx, revs[0], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0) {
            git_state_release (&state);
            return git_fatal ("bad revision");
        }
        bgit_index_entry *files = NULL, *working = NULL;
        size_t n_files = 0, n_working = 0;
        if (bgit_read_tree (&ctx->odb, tree, &files, &n_files) < 0 ||
            bgit_worktree_entries (&ctx->repo, &ctx->odb, NULL, state.index,
                                   state.n_index, &working, &n_working) < 0) {
            bgit_index_free_entries (files, n_files);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        rc = bgit_diff_entries (files, n_files, working, n_working, &entries, &n);
        bgit_index_free_entries (files, n_files);
        bgit_index_free_entries (working, n_working);
    } else {
        rc = bgit_diff_index_worktree (&ctx->repo, &ctx->odb, state.index,
                                       state.n_index, &entries, &n);
    }
    if (rc < 0) {
        git_state_release (&state);
        return git_fatal ("cannot compare");
    }

    if (n_paths) {
        size_t kept = 0;
        for (size_t i = 0; i < n; i++) {
            int matched = 0;
            for (int j = 0; j < n_paths && !matched; j++)
                if (git_path_in_spec (entries[i].path, paths[j])) matched = 1;
            if (matched) entries[kept++] = entries[i];
            else { free (entries[i].path); free (entries[i].from); }
        }
        n = kept;
    }
    /* Only a comparison that ends at the working tree reads files. */
    int from_worktree = !cached && n_revs < 2;
    git_find_renames (ctx, &format, &entries, &n, from_worktree);
    /* --check says 2 when it found something, and that is the status. */
    int emitted = git_diff_emit (ctx, stdout, &format, entries, n,
                                 from_worktree, "");
    int status = emitted < 0 ? GIT_EXIT_FATAL : emitted;
    /* --exit-code says in the status whether anything changed. Overlooking
       whitespace can leave a change with nothing to say, and git counts
       only what is left to say. */
    if (status != GIT_EXIT_FATAL && format.exit_code) {
        int changed = n > 0;
        if (changed && (format.ignore_ws || format.ignore_blank_lines)) {
            bgit_patch_options probe;
            bgit_patch_options_init (&probe);
            probe.context = format.context;
            if (git_diff_inter_context (ctx, &format,
                                        &probe.inter_context) < 0) {
                bgit_diff_free (entries, n);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            probe.new_from_worktree = from_worktree;
            probe.ignore_ws = format.ignore_ws;
            probe.ignore_blank_lines = format.ignore_blank_lines;
            bgit_diffstat_entry *counted = NULL;
            size_t n_counted = 0;
            if (bgit_diffstat (&ctx->odb, &ctx->repo, entries, n, &probe,
                               &counted, &n_counted) == 0)
                changed = n_counted > 0;
            free (counted);
        }
        if (changed) status |= 1;
    }
    bgit_diff_free (entries, n);
    git_state_release (&state);
    return status;
}

/* ---- show -------------------------------------------------------------- */

/* `git show <tree>` lists the names in it, a subtree marked with a slash. */
static int
git_show_tree_entry (void *context, const char *mode, const char *type,
                     const char *sha, const char *path)
{
    (void) context;
    (void) mode;
    (void) sha;
    printf ("%s%s\n", path, !strcmp (type, "tree") ? "/" : "");
    return 0;
}

/* The header `git show` prints for an annotated tag, then its message.
   TAGGED comes back holding the id of the object the tag points at. */
static void
git_show_tag (const unsigned char *data, size_t len, char *tagged,
              const struct git_date_format *date)
{
    char name[256] = "", tagger[512] = "", stamp[128] = "";
    const char *body = (const char *) data;
    size_t left = len;
    tagged[0] = '\0';
    while (left) {
        const char *nl = memchr (body, '\n', left);
        size_t line_len = nl ? (size_t) (nl - body) : left;
        if (!line_len) { body = nl ? nl + 1 : body + left; left -= line_len + 1; break; }
        if (!strncmp (body, "object ", 7) && line_len >= 47)
            snprintf (tagged, 41, "%.40s", body + 7);
        else if (!strncmp (body, "tag ", 4))
            snprintf (name, sizeof name, "%.*s", (int) line_len - 4, body + 4);
        else if (!strncmp (body, "tagger ", 7)) {
            char who[256] = "", email[256] = "";
            git_split_ident (body + 7, line_len - 7, who, sizeof who,
                             email, sizeof email, stamp, sizeof stamp);
            snprintf (tagger, sizeof tagger, "%s <%s>", who, email);
        }
        if (!nl) { left = 0; break; }
        left -= line_len + 1;
        body = nl + 1;
    }

    printf ("tag %s\n", name);
    if (*tagger) {
        char shown[128];
        git_format_date_as (stamp, date, shown, sizeof shown);
        printf ("Tagger: %s\n", tagger);
        printf ("Date:   %s\n", shown);
    }
    printf ("\n");
    fwrite (body, 1, left, stdout);
    printf ("\n");
}

/* `git whatchanged` is `git log --raw` under an older name, which git
   keeps for the fingers that still type it. The one difference is that a
   commit with nothing to show is not shown. */
static int
git_cmd_whatchanged (git_context *ctx, WORD_LIST *args)
{
    /* git 2.50 and later want to hear that the command is still in use
       before they will run it. Say what you like; it changes nothing. */
    while (args && !strcmp (args->word->word, "--i-still-use-this"))
        args = args->next;
    WORD_LIST *with_raw = make_word_list (make_word ("--raw"), args);
    git_headers_need_a_diff = 1;
    int rc = git_cmd_log (ctx, with_raw);
    git_headers_need_a_diff = 0;
    /* The list's own cell goes; the words after it belong to the caller. */
    with_raw->next = NULL;
    dispose_words (with_raw);
    return rc;
}

static int
git_cmd_show (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git show [-p | -s | --stat] [--oneline] "
                        "[--format=<format>] [--date=<format>] "
                        "[--decorate[=short|full|auto|no]] [--show-signature] "
                        "[<object>...]";
    git_check_complained = 0;
    struct git_diff_format diff;
    git_diff_format_init (&diff);
    const char *format = NULL;
    int oneline = 0, show_signature = 0, decorate = -1, option_words = 0;
    int show_notes = 1;
    const char *notes_ref = NULL;
    struct git_date_format date;
    git_date_format_init (&date);
    const char *objects[16];
    int n_objects = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--oneline")) oneline = 1;
        else if (!strncmp (w, "--format=", 9)) format = w + 9;
        else if (!strncmp (w, "--pretty=", 9)) format = w + 9;
        else if (!strncmp (w, "--date=", 7) ||
                 (!strcmp (w, "--date") && p->next)) {
            const char *name = w[6] == '=' ? w + 7 : (p = p->next)->word->word;
            int bad = git_date_format_read (&date, name);
            if (bad) return bad;
        }
        else if (!strcmp (w, "--decorate")) decorate = GIT_DECORATE_SHORT;
        else if (!strcmp (w, "--no-decorate")) decorate = GIT_DECORATE_NO;
        else if (!strncmp (w, "--decorate=", 11)) {
            const char *which = w + 11;
            if (!strcmp (which, "short")) decorate = GIT_DECORATE_SHORT;
            else if (!strcmp (which, "full")) decorate = GIT_DECORATE_FULL;
            else if (!strcmp (which, "no")) decorate = GIT_DECORATE_NO;
            else if (!strcmp (which, "auto")) decorate = -1;
            else return git_fatal ("invalid --decorate option: %s", which);
        }
        else if (!strcmp (w, "--show-signature")) show_signature = 1;
        else if (!strcmp (w, "--no-show-signature")) show_signature = 0;
        else if (!strcmp (w, "--no-notes")) show_notes = 0;
        else if (!strcmp (w, "--notes")) { show_notes = 1; notes_ref = NULL; }
        else if (!strncmp (w, "--notes=", 8)) { show_notes = 1; notes_ref = w + 8; }
        else if ((option_words = git_diff_format_option
                                  (&diff, w,
                                   p->next ? p->next->word->word : NULL))) {
            if (option_words == 2) p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_objects < (int) (sizeof objects / sizeof *objects))
            objects[n_objects++] = w;
        else return git_fatal ("too many objects");
    }
    if (format && !strcmp (format, "oneline")) { oneline = 1; format = NULL; }
    if (!n_objects) objects[n_objects++] = "HEAD";
    if (decorate < 0)
        decorate = isatty (STDOUT_FILENO) ? GIT_DECORATE_SHORT : GIT_DECORATE_NO;
    /* A patch is what show is for, unless another form was named. */
    if (!git_diff_wanted (&diff) && !diff.no_patch) diff.patch = 1;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    git_notes_showing[0] = '\0';
    if (show_notes)
        git_notes_ref (ctx, notes_ref, git_notes_showing,
                       sizeof git_notes_showing);

    for (int i = 0; i < n_objects; i++) {
        char id[41];
        if (git_resolve (ctx, objects[i], id, NULL) < 0)
            return git_fatal_ambiguous (objects[i]);
        for (;;) {
            enum bgit_type type;
            unsigned char *data = NULL;
            size_t len = 0;
            if (bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0)
                return git_fatal ("bad object %s", objects[i]);
            if (type == BGIT_TAG) {
                char tagged[41] = "";
                git_show_tag (data, len, tagged, &date);
                free (data);
                if (!tagged[0]) break;
                memcpy (id, tagged, 41);
                continue;               /* on to what the tag points at */
            }
            if (type == BGIT_BLOB) {
                fwrite (data, 1, len, stdout);
                free (data);
                break;
            }
            free (data);
            if (type == BGIT_TREE) {
                printf ("tree %s\n\n", objects[i]);
                bgit_tree_walk (&ctx->odb, id, "", 0, 1, git_show_tree_entry,
                                NULL);
                break;
            }
            if (type != BGIT_COMMIT)
                return git_fatal ("bad object %s", objects[i]);
            struct git_commit commit;
            if (git_commit_read (ctx, id, &commit) < 0)
                return git_fatal ("unable to read %s", id);
            git_print_commit (ctx, stdout, &commit, oneline, format,
                              &date, decorate, show_signature, &diff, NULL, 0);
            git_commit_release (&commit);
            break;
        }
    }
    return git_check_complained ? 2 : 0;
}

/* verify-commit and verify-tag are one walk over two kinds of object. */
static int
git_cmd_verify (git_context *ctx, WORD_LIST *args, enum bgit_type want)
{
    const char *what = want == BGIT_COMMIT ? "commit" : "tag";
    char usage[96];
    snprintf (usage, sizeof usage, "git verify-%s [-v | --verbose] [--raw] "
                                   "<%s>...", what, what);
    int verbose = 0;
    const char *names[32];
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "--raw")) ;   /* an ssh signature says no more */
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names))
            names[n_names++] = w;
        else return git_fatal ("too many %ss", what);
    }
    if (!n_names) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* Every name is looked at, and one bad one settles the status. */
    int worst = 0;
    for (int i = 0; i < n_names; i++) {
        char id[41];
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        if (git_resolve (ctx, names[i], id, NULL) < 0 ||
            bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0) {
            fflush (stdout);
            fprintf (stderr, "error: %s '%s' not found.\n", what, names[i]);
            worst = 1;
            continue;
        }
        if (type != want) {
            fflush (stdout);
            fprintf (stderr, "error: %s: cannot verify a non-%s object of "
                             "type %s.\n", names[i], what,
                     bgit_type_name (type));
            free (data);
            worst = 1;
            continue;
        }
        char *payload = NULL;
        size_t payload_len = 0;
        if (git_verify_signature (ctx, stderr, data, len, type,
                                  verbose ? &payload : NULL, &payload_len))
            worst = 1;
        if (payload) {
            /* What was signed, which is the object without its signature. */
            fwrite (payload, 1, payload_len, stdout);
            free (payload);
        }
        free (data);
    }
    return worst;
}

static int
git_cmd_verify_commit (git_context *ctx, WORD_LIST *args)
{
    return git_cmd_verify (ctx, args, BGIT_COMMIT);
}

static int
git_cmd_verify_tag (git_context *ctx, WORD_LIST *args)
{
    return git_cmd_verify (ctx, args, BGIT_TAG);
}

/* ---- branches, switching, restoring, resetting and tags ----------------- */

/* Where HEAD stands now, for the reflog line that says it moved: the
   branch it is on, or else the commit id whole, which is what git writes
   when HEAD stands on no branch. */
static void
git_head_label (struct git_state *state, char *out, size_t outsz)
{
    if (state->branch && !strncmp (state->branch, "refs/heads/", 11))
        snprintf (out, outsz, "%s", state->branch + 11);
    else if (state->have_head) snprintf (out, outsz, "%s", state->head);
    else snprintf (out, outsz, "(no branch)");
}

/* Does this name match any of the patterns given? No patterns means every
   name does, which is what a listing with none asked for shows. */
static int
git_name_globbed (const char *name, const char *const *patterns, int n)
{
    if (!n) return 1;
    for (int i = 0; i < n; i++)
        if (patterns[i] && fnmatch (patterns[i], name, 0) == 0) return 1;
    return 0;
}

static int
git_cmd_branch (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git branch [-v | -vv] [-a | -r] [--show-current] "
                        "[--merged [<commit>]] [--no-merged [<commit>]] "
                        "[--contains <commit>] [--points-at <object>] "
                        "[--list [<pattern>...]] [<name> [<start>]] "
                        "| (-d | -D) <name> | (-m | -M) <old> <new>";
    int verbose = 0, show_current = 0, delete_branch = 0, move_branch = 0, force = 0;
    int list = 0;
    int show_remotes = 0, only_remotes = 0;
    /* What to leave out of the listing: each is a commit a branch has to
       reach, or be reached by, or stand on. */
    const char *merged = NULL, *not_merged = NULL, *contains = NULL;
    const char *points_at = NULL;
    int want_merged = 0, want_not_merged = 0;
    /* Listing takes as many patterns as are given; making or moving a
       branch takes at most two names. */
    const char *names[16] = { NULL };
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "-l") || !strcmp (w, "--list")) list = 1;
        else if (!strcmp (w, "-vv")) verbose = 2;
        else if (!strcmp (w, "--show-current")) show_current = 1;
        else if (!strcmp (w, "--merged")) {
            want_merged = 1;
            if (p->next && p->next->word->word[0] != '-')
                merged = (p = p->next)->word->word;
        }
        else if (!strncmp (w, "--merged=", 9)) { want_merged = 1; merged = w + 9; }
        else if (!strcmp (w, "--no-merged")) {
            want_not_merged = 1;
            if (p->next && p->next->word->word[0] != '-')
                not_merged = (p = p->next)->word->word;
        }
        else if (!strncmp (w, "--no-merged=", 12)) {
            want_not_merged = 1;
            not_merged = w + 12;
        }
        else if (!strcmp (w, "--contains") && p->next)
            contains = (p = p->next)->word->word;
        else if (!strncmp (w, "--contains=", 11)) contains = w + 11;
        else if (!strcmp (w, "--points-at") && p->next)
            points_at = (p = p->next)->word->word;
        else if (!strncmp (w, "--points-at=", 12)) points_at = w + 12;
        else if (!strcmp (w, "-a") || !strcmp (w, "--all")) show_remotes = 1;
        else if (!strcmp (w, "-r") || !strcmp (w, "--remotes")) {
            show_remotes = 1;
            only_remotes = 1;
        }
        else if (!strcmp (w, "-d") || !strcmp (w, "--delete")) delete_branch = 1;
        else if (!strcmp (w, "-D")) { delete_branch = 1; force = 1; }
        else if (!strcmp (w, "-m") || !strcmp (w, "--move")) move_branch = 1;
        else if (!strcmp (w, "-M")) { move_branch = 1; force = 1; }
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names))
            names[n_names++] = w;
        else return git_usage (usage);
    }
    /* Without --list, a name is a branch to make and a second is where to
       start it; there is no third. */
    if (!list && n_names > 2) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int status = 0;

    if (show_current) {
        if (state.branch && !strncmp (state.branch, "refs/heads/", 11))
            printf ("%s\n", state.branch + 11);
        goto done;
    }
    if (delete_branch) {
        if (!n_names) { status = git_usage (usage); goto done; }
        char ref[4096];
        snprintf (ref, sizeof ref, "refs/heads/%s", names[0]);
        char id[41];
        if (bgit_ref_read (&ctx->repo, ref, id) != 0) {
            status = git_fatal ("branch '%s' not found.", names[0]);
            goto done;
        }
        if (state.branch && !strcmp (state.branch, ref)) {
            status = git_fatal ("Cannot delete branch '%s' checked out at '%s'",
                                names[0], ctx->repo.work_tree);
            goto done;
        }
        if (bgit_ref_delete (&ctx->repo, ref, NULL, NULL) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        char abbreviated[41];
        git_abbrev (ctx, id, 7, abbreviated, sizeof abbreviated);
        printf ("Deleted branch %s (was %s).\n", names[0], abbreviated);
        goto done;
    }
    if (move_branch) {
        const char *from = n_names == 2 ? names[0]
                         : (state.branch && !strncmp (state.branch, "refs/heads/", 11)
                            ? state.branch + 11 : NULL);
        const char *to = n_names == 2 ? names[1] : names[0];
        if (!from || !to) { status = git_usage (usage); goto done; }
        char old_ref[4096], new_ref[4096], id[41];
        snprintf (old_ref, sizeof old_ref, "refs/heads/%s", from);
        snprintf (new_ref, sizeof new_ref, "refs/heads/%s", to);
        if (bgit_ref_read (&ctx->repo, old_ref, id) != 0) {
            status = git_fatal ("branch '%s' not found.", from);
            goto done;
        }
        char existing[41];
        if (!force && bgit_ref_read (&ctx->repo, new_ref, existing) == 0) {
            status = git_fatal ("A branch named '%s' already exists.", to);
            goto done;
        }
        char message[1200];
        snprintf (message, sizeof message, "Branch: renamed %s to %s",
                  old_ref, new_ref);
        if (bgit_ref_update (&ctx->repo, new_ref, id, NULL, message) < 0 ||
            bgit_ref_delete (&ctx->repo, old_ref, NULL, NULL) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        if (state.branch && !strcmp (state.branch, old_ref) &&
            bgit_symref_write (&ctx->repo, "HEAD", new_ref, NULL) < 0)
            status = GIT_EXIT_FATAL;
        goto done;
    }
    /* With --list, whatever was named is a pattern for the listing rather
       than a branch to make. */
    if (n_names && !list) {
        /* Create a branch at a starting point, HEAD by default. */
        char ref[4096], id[41];
        snprintf (ref, sizeof ref, "refs/heads/%s", names[0]);
        if (!bgit_ref_name_ok (ref)) {
            status = git_fatal ("'%s' is not a valid branch name.", names[0]);
            goto done;
        }
        char existing[41];
        if (!force && bgit_ref_read (&ctx->repo, ref, existing) == 0) {
            status = git_fatal ("a branch named '%s' already exists", names[0]);
            goto done;
        }
        const char *start = names[1] ? names[1] : "HEAD";
        char resolved[41];
        if (git_resolve (ctx, start, resolved, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, resolved, BGIT_COMMIT, id) < 0) {
            status = git_fatal ("not a valid object name: '%s'.", start);
            goto done;
        }
        /* git records the start point as it was written; with none given,
           the branch HEAD stands on, or HEAD itself when it stands on no
           branch. It says too whether the branch was made or moved. */
        const char *from = names[1] ? names[1]
                         : (state.branch &&
                            !strncmp (state.branch, "refs/heads/", 11)
                            ? state.branch + 11 : "HEAD");
        char already[41];
        char message[1200];
        snprintf (message, sizeof message, "branch: %s %s",
                  bgit_ref_read (&ctx->repo, ref, already) == 0 ? "Reset to"
                                                                : "Created from",
                  from);
        if (bgit_ref_update (&ctx->repo, ref, id, NULL, message) < 0)
            status = GIT_EXIT_FATAL;
        goto done;
    }

    /* Each of the three tests, resolved once, and any that cannot be
       resolved is git's own complaint. */
    char merged_id[41] = "", not_merged_id[41] = "", contains_id[41] = "";
    char points_id[41] = "";
    if (want_merged &&
        (git_resolve (ctx, merged ? merged : "HEAD", merged_id, NULL) < 0 ||
         bgit_peel_to_type (&ctx->odb, merged_id, BGIT_COMMIT, merged_id) < 0)) {
        status = git_fatal ("malformed object name %s", merged ? merged : "HEAD");
        goto done;
    }
    if (want_not_merged &&
        (git_resolve (ctx, not_merged ? not_merged : "HEAD", not_merged_id,
                      NULL) < 0 ||
         bgit_peel_to_type (&ctx->odb, not_merged_id, BGIT_COMMIT,
                            not_merged_id) < 0)) {
        status = git_fatal ("malformed object name %s",
                            not_merged ? not_merged : "HEAD");
        goto done;
    }
    if (contains &&
        (git_resolve (ctx, contains, contains_id, NULL) < 0 ||
         bgit_peel_to_type (&ctx->odb, contains_id, BGIT_COMMIT,
                            contains_id) < 0)) {
        /* git says this one as an error against the options it was given,
           and leaves with the status a usage mistake carries. */
        fflush (stdout);
        fprintf (stderr, "error: malformed object name %s\n", contains);
        status = GIT_EXIT_USAGE;
        goto done;
    }
    if (points_at && git_resolve (ctx, points_at, points_id, NULL) < 0) {
        fflush (stdout);
        fprintf (stderr, "error: malformed object name '%s'\n", points_at);
        status = GIT_EXIT_USAGE;
        goto done;
    }

    /* A branch checked out in another worktree is marked, as git marks it. */
    struct git_worktree *trees = NULL;
    size_t n_trees = 0;
    git_worktrees (ctx, &trees, &n_trees);

    /* With --list the names given are patterns the branch has to match. */
    int n_glob = list ? n_names : 0;
    /* No arguments: list the branches, and with -a or -r the tracking refs
       that stand for branches at the far end. */
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (!only_remotes && bgit_refs_list (&ctx->repo, "refs/heads/", &refs,
                                         &n_refs) < 0) {
        status = git_fatal ("cannot read refs");
        goto done;
    }
    bgit_ref *tracking = NULL;
    size_t n_tracking = 0;
    if (show_remotes &&
        bgit_refs_list (&ctx->repo, "refs/remotes/", &tracking,
                        &n_tracking) < 0) {
        bgit_refs_free (refs, n_refs);
        status = git_fatal ("cannot read refs");
        goto done;
    }
    /* git pads every name in the listing to one width, so that the ids
       line up down the whole of it. */
    size_t width = 0;
    for (size_t j = 0; j < n_refs; j++) {
        if (!git_ref_listed (ctx, refs[j].sha, merged_id, not_merged_id,
                             contains_id, points_id) ||
            !git_name_globbed (refs[j].name + 11, names, n_glob))
            continue;
        size_t len = strlen (refs[j].name + 11);
        if (len > width) width = len;
    }
    for (size_t j = 0; j < n_tracking; j++) {
        if (!git_ref_listed (ctx, tracking[j].sha, merged_id, not_merged_id,
                             contains_id, points_id) ||
            !git_name_globbed (tracking[j].name + 13, names, n_glob))
            continue;
        size_t len = strlen (tracking[j].name + 13) + (only_remotes ? 0 : 8);
        if (len > width) width = len;
    }
    for (size_t i = 0; i < n_refs; i++) {
        const char *name = refs[i].name + 11;
        if (!git_ref_listed (ctx, refs[i].sha, merged_id, not_merged_id,
                             contains_id, points_id) ||
            !git_name_globbed (name, names, n_glob))
            continue;
        int current = state.branch && !strcmp (state.branch, refs[i].name);
        int elsewhere = 0;
        const char *checked_out_at = NULL;
        for (size_t w = 0; w < n_trees && !elsewhere; w++)
            if (!current && !strcmp (trees[w].branch, refs[i].name)) {
                elsewhere = 1;
                checked_out_at = trees[w].path;
            }
        const char *mark = current ? "*" : elsewhere ? "+" : " ";
        if (!verbose) {
            printf ("%s %s\n", mark, name);
            continue;
        }
        struct git_commit commit;
        char abbreviated[41], subject[4096] = "";
        git_abbrev (ctx, refs[i].sha, 7, abbreviated, sizeof abbreviated);
        if (git_commit_read (ctx, refs[i].sha, &commit) == 0) {
            git_subject (&commit, subject, sizeof subject);
            git_commit_release (&commit);
        }
        /* -v says how far the branch has got from what it follows, and
           -vv says what that is as well. */
        char following[512] = "";
        if (verbose) {
            char upstream[512];
            long ahead = 0, behind = 0;
            /* How far this branch has got, not how far HEAD has: the
                comparison is made from the branch's own tip. */
            struct git_state at_branch = state;
            at_branch.have_head = 1;
            memcpy (at_branch.head, refs[i].sha, 41);
            int tracks = git_status_upstream (ctx, &at_branch, name, upstream,
                                              sizeof upstream, &ahead, &behind);
            char apart[128] = "";
            if (tracks == 2) snprintf (apart, sizeof apart, "gone");
            else if (tracks == 1 && ahead && behind)
                snprintf (apart, sizeof apart, "ahead %ld, behind %ld", ahead,
                          behind);
            else if (tracks == 1 && ahead)
                snprintf (apart, sizeof apart, "ahead %ld", ahead);
            else if (tracks == 1 && behind)
                snprintf (apart, sizeof apart, "behind %ld", behind);
            if (verbose > 1 && tracks && *apart)
                snprintf (following, sizeof following, "[%s: %s] ", upstream,
                          apart);
            else if (verbose > 1 && tracks)
                snprintf (following, sizeof following, "[%s] ", upstream);
            else if (*apart)
                snprintf (following, sizeof following, "[%s] ", apart);
        }
        /* A branch another worktree has checked out says where that is,
           which -vv shows between the id and what it follows. */
        char where[4200] = "";
        if (verbose > 1 && checked_out_at && *checked_out_at)
            snprintf (where, sizeof where, "(%s) ", checked_out_at);
        printf ("%s %-*s %s %s%s%s\n", mark, (int) width, name,
                abbreviated, where, following, subject);
    }
    bgit_refs_free (refs, n_refs);

    for (size_t i = 0; i < n_tracking; i++) {
        const char *name = tracking[i].name + 13;
        if (!git_ref_listed (ctx, tracking[i].sha, merged_id, not_merged_id,
                             contains_id, points_id) ||
            !git_name_globbed (name, names, n_glob))
            continue;
        char shown[4096];
        snprintf (shown, sizeof shown, "%s%s", only_remotes ? "" : "remotes/",
                  name);
        /* A symbolic tracking ref shows what it points at. */
        char *target = NULL;
        if (bgit_symref_read (&ctx->repo, tracking[i].name, &target) == 0 &&
            target) {
            printf ("  %-*s -> %s\n", verbose ? (int) width : 0, shown,
                    target + 13);
            free (target);
            continue;
        }
        free (target);
        if (!verbose) {
            printf ("  %s\n", shown);
            continue;
        }
        struct git_commit commit;
        char abbreviated[41], subject[4096] = "";
        git_abbrev (ctx, tracking[i].sha, 7, abbreviated, sizeof abbreviated);
        if (git_commit_read (ctx, tracking[i].sha, &commit) == 0) {
            git_subject (&commit, subject, sizeof subject);
            git_commit_release (&commit);
        }
        printf ("  %-*s %s %s\n", (int) width, shown, abbreviated, subject);
    }
    bgit_refs_free (tracking, n_tracking);
done:
    git_state_release (&state);
    return status;
}

/* Point HEAD straight at a commit, which is what being detached means. */
static int
git_head_detach (git_context *ctx, struct git_state *state, const char *commit,
                 const char *message)
{
    char path[4096];
    if (bgit_ref_path (&ctx->repo, "HEAD", path, sizeof path) < 0) return -1;
    bgit_lock lock;
    if (bgit_lock_acquire (&lock, path) < 0) return -1;
    char line[42];
    int len = snprintf (line, sizeof line, "%s\n", commit);
    if (bgit_lock_write (&lock, line, (size_t) len) < 0 ||
        bgit_lock_commit (&lock) < 0) {
        bgit_lock_rollback (&lock);
        return -1;
    }
    if (message)
        bgit_reflog_append (&ctx->repo, "HEAD",
                            state->have_head ? state->head : NULL, commit,
                            message);
    return 0;
}

/* What a move says for itself: nothing, or the lines git says about it.
   GIT_SAY_NEW is for a branch this command has just made, and
   GIT_SAY_ADVICE adds the paragraph git puts in front of a detached HEAD
   nobody asked for outright. */
enum { GIT_SAY_NOTHING = 0, GIT_SAY_MOVE = 1, GIT_SAY_NEW = 2,
       GIT_SAY_ADVICE = 4 };

/* The paragraph git sets in front of a detached HEAD, worded as git words
   it, for a checkout that detached without being asked to. */
static void
git_detached_advice (const char *target)
{
    fprintf (stderr,
        "Note: switching to '%s'.\n"
        "\n"
        "You are in 'detached HEAD' state. You can look around, make "
        "experimental\n"
        "changes and commit them, and you can discard any commits you make in "
        "this\n"
        "state without impacting any branches by switching back to a branch.\n"
        "\n"
        "If you want to create a new branch to retain commits you create, you "
        "may\n"
        "do so (now or later) by using -c with the switch command. Example:\n"
        "\n"
        "  git switch -c <new-branch-name>\n"
        "\n"
        "Or undo this operation with:\n"
        "\n"
        "  git switch -\n"
        "\n"
        "Turn off this advice by setting config variable advice.detachedHead "
        "to false\n"
        "\n", target);
}

/* Move HEAD to another branch or commit, updating the working tree. With
   ANNOUNCE, what git says about the move is said as well: where HEAD was
   when it was on nothing but a commit, where it is now, and how the branch
   it lands on stands against the one it follows. */
static int
git_switch_to_saying (git_context *ctx, struct git_state *state,
                      const char *target, int detach, int force, int announce)
{
    char ref[4096] = "", id[41], commit[41];
    int is_branch = 0;
    snprintf (ref, sizeof ref, "refs/heads/%s", target);
    if (bgit_ref_read (&ctx->repo, ref, id) == 0) is_branch = 1;
    if (!is_branch) {
        if (git_resolve (ctx, target, id, NULL) < 0)
            return git_fatal ("invalid reference: %s", target);
    }
    if (bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0)
        return git_fatal ("reference is not a tree: %s", target);
    char tree[41];
    if (bgit_commit_tree (&ctx->odb, commit, tree) < 0)
        return git_fatal ("cannot read %s", commit);

    char *losing = NULL;
    int rc = bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state->index,
                                 &state->n_index, force, &losing);
    if (rc > 0) {
        fflush (stdout);
        fprintf (stderr, "error: Your local changes to the following files "
                         "would be overwritten by checkout:\n\t%s\n"
                         "Please commit your changes or stash them before you "
                         "switch branches.\nAborting\n", losing ? losing : "");
        free (losing);
        return 1;
    }
    if (rc < 0) { free (losing); return GIT_EXIT_FATAL; }
    if (git_index_store (ctx, state->index, state->n_index) < 0)
        return GIT_EXIT_FATAL;

    char from[128], message[1200];
    git_head_label (state, from, sizeof from);
    snprintf (message, sizeof message, "checkout: moving from %s to %s", from,
              target);
    if (is_branch && !detach) {
        if (bgit_symref_write (&ctx->repo, "HEAD", ref, NULL) < 0)
            return GIT_EXIT_FATAL;
        bgit_reflog_append (&ctx->repo, "HEAD", state->have_head ? state->head : NULL,
                            commit, message);
    } else if (git_head_detach (ctx, state, commit, message) < 0)
        return GIT_EXIT_FATAL;
    if (announce & GIT_SAY_MOVE) {
        fflush (stdout);
        /* Where HEAD was, when it was on nothing but a commit and is about
           to be somewhere else. */
        if (state->have_head && !state->branch &&
            strcmp (state->head, commit)) {
            char abbreviated[41], subject[4096] = "";
            git_abbrev (ctx, state->head, 7, abbreviated, sizeof abbreviated);
            struct git_commit was;
            if (git_commit_read (ctx, state->head, &was) == 0) {
                git_subject (&was, subject, sizeof subject);
                git_commit_release (&was);
            }
            fprintf (stderr, "Previous HEAD position was %s %s\n", abbreviated,
                     subject);
        }
        if (is_branch && !detach) {
            if (announce & GIT_SAY_NEW)
                fprintf (stderr, "Switched to a new branch '%s'\n", target);
            else if (state->branch && !strcmp (state->branch, ref))
                fprintf (stderr, "Already on '%s'\n", target);
            else fprintf (stderr, "Switched to branch '%s'\n", target);
            fflush (stderr);
            git_upstream_summary (ctx, state, target, 0);
            fflush (stdout);
        } else {
            char abbreviated[41], subject[4096] = "";
            git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
            struct git_commit now;
            if (git_commit_read (ctx, commit, &now) == 0) {
                git_subject (&now, subject, sizeof subject);
                git_commit_release (&now);
            }
            fprintf (stderr, "HEAD is now at %s %s\n", abbreviated, subject);
        }
    }
    return 0;
}

static int
git_switch_to (git_context *ctx, struct git_state *state, const char *target,
               int detach, int force)
{
    return git_switch_to_saying (ctx, state, target, detach, force, 0);
}

static int
git_cmd_switch (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git switch [-q] [-c <new-branch>] [-C <new-branch>] "
                        "[--detach] [-f] <branch>";
    const char *create = NULL, *target = NULL;
    int detach = 0, force = 0, force_create = 0, quiet = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) { quiet = 1; continue; }
        if ((!strcmp (w, "-c") || !strcmp (w, "--create")) && p->next) {
            create = p->next->word->word; p = p->next;
        } else if (!strcmp (w, "-C") && p->next) {
            create = p->next->word->word; force_create = 1; p = p->next;
        } else if (!strcmp (w, "--detach") || !strcmp (w, "-d")) detach = 1;
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!target) target = w;
        else return git_usage (usage);
    }
    if (!create && !target) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    int status = 0;
    if (create) {
        char ref[4096], id[41], commit[41];
        snprintf (ref, sizeof ref, "refs/heads/%s", create);
        char existing[41];
        if (!force_create && bgit_ref_read (&ctx->repo, ref, existing) == 0) {
            status = git_fatal ("a branch named '%s' already exists", create);
            goto done;
        }
        const char *start = target ? target : "HEAD";
        if (git_resolve (ctx, start, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            status = git_fatal ("invalid reference: %s", start);
            goto done;
        }
        /* switch -c writes the start point as it was typed, so an
           implicit one stays "HEAD"; git branch names the branch instead. */
        /* A branch that was already there is being put back, and git's
           log says so in its own words. */
        char was[41];
        int had_it = bgit_ref_read (&ctx->repo, ref, was) == 0;
        char message[1200];
        snprintf (message, sizeof message, "branch: %s %s",
                  had_it ? "Reset to" : "Created from", start);
        if (bgit_ref_update (&ctx->repo, ref, commit, NULL, message) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        status = git_switch_to_saying (ctx, &state, create, 0, force,
                                       quiet ? GIT_SAY_NOTHING
                                             : GIT_SAY_MOVE | GIT_SAY_NEW);
        goto done;
    }
    if (!target) { status = git_usage (usage); goto done; }
    /* A lone dash is the branch before this one, which is what git makes
       of it here. */
    char previous[4096];
    if (!strcmp (target, "-") &&
        git_previous_branch (ctx, 1, previous, sizeof previous) == 0)
        target = previous;
    status = git_switch_to_saying (ctx, &state, target, detach, force,
                                   quiet ? GIT_SAY_NOTHING : GIT_SAY_MOVE);
done:
    git_state_release (&state);
    return status;
}

static int
git_cmd_checkout (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git checkout [-q] [-b <new-branch>] [--detach] "
                        "[-f] (<branch> | [<tree-ish>] -- <path>...)";
    const char *create = NULL, *target = NULL;
    const char *paths[32];
    int n_paths = 0, detach = 0, force = 0, no_more = 0, quiet = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && (!strcmp (w, "-q") || !strcmp (w, "--quiet"))) {
            quiet = 1;
            continue;
        }
        if (!no_more && (!strcmp (w, "-b") || !strcmp (w, "-B")) && p->next) {
            create = p->next->word->word; p = p->next;
        } else if (!no_more && !strcmp (w, "--detach")) detach = 1;
        else if (!no_more && (!strcmp (w, "-f") || !strcmp (w, "--force"))) force = 1;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (!no_more && !target && !n_paths) target = w;
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int status = 0;

    if (n_paths) {
        /* Restore files from a tree, or from the index. */
        char tree[41] = "";
        int have_tree = 0;
        if (target) {
            char id[41];
            if (git_resolve (ctx, target, id, NULL) < 0 ||
                bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0) {
                status = git_fatal ("invalid reference: %s", target);
                goto done;
            }
            have_tree = 1;
        }
        int rc = bgit_checkout_paths (&ctx->repo, &ctx->odb,
                                      have_tree ? tree : NULL, &state.index,
                                      &state.n_index, paths,
                                      (size_t) n_paths, have_tree, 1);
        if (rc < 0 || git_index_store (ctx, state.index, state.n_index) < 0)
            status = rc == -2 ? 1 : GIT_EXIT_FATAL;
        goto done;
    }
    if (create) {
        WORD_LIST *rest = NULL;
        (void) rest;
        char ref[4096], id[41], commit[41];
        snprintf (ref, sizeof ref, "refs/heads/%s", create);
        const char *start = target ? target : "HEAD";
        if (git_resolve (ctx, start, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
            status = git_fatal ("invalid reference: %s", start);
            goto done;
        }
        char message[1200];
        snprintf (message, sizeof message, "branch: Created from %s", start);
        if (bgit_ref_update (&ctx->repo, ref, commit, NULL, message) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        status = git_switch_to_saying (ctx, &state, create, 0, force,
                                       quiet ? GIT_SAY_NOTHING
                                             : GIT_SAY_MOVE | GIT_SAY_NEW);
        goto done;
    }
    if (!target) { status = git_usage (usage); goto done; }
    char previous[4096];
    if (!strcmp (target, "-") &&
        git_previous_branch (ctx, 1, previous, sizeof previous) == 0)
        target = previous;
    {
        /* A detached HEAD nobody asked for outright gets git's paragraph
           about it in front of the move. */
        int say = quiet ? GIT_SAY_NOTHING : GIT_SAY_MOVE;
        char branch_ref[4096], held[41];
        snprintf (branch_ref, sizeof branch_ref, "refs/heads/%s", target);
        int names_branch = bgit_ref_read (&ctx->repo, branch_ref, held) == 0;
        if ((say & GIT_SAY_MOVE) && !names_branch && !detach)
            git_detached_advice (target);
        status = git_switch_to_saying (ctx, &state, target, detach, force, say);
    }
done:
    git_state_release (&state);
    return status;
}

static int
git_cmd_restore (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git restore [--staged] [--worktree] "
                        "[--source=<tree>] <path>...";
    int staged = 0, worktree = 0, no_more = 0;
    const char *source = NULL;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "--staged")) staged = 1;
        else if (!no_more && !strcmp (w, "--worktree")) worktree = 1;
        else if (!no_more && !strncmp (w, "--source=", 9)) source = w + 9;
        else if (!no_more && (!strcmp (w, "-s") || !strcmp (w, "--source")) && p->next) {
            source = p->next->word->word; p = p->next;
        }
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (!n_paths) return git_usage (usage);
    if (!staged && !worktree) worktree = 1;      /* git's default */
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    int status = 0;
    char tree[41] = "";
    int have_tree = 0;
    const char *from = source ? source : (staged ? "HEAD" : NULL);
    if (from) {
        char id[41];
        if (git_resolve (ctx, from, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0) {
            status = git_fatal ("invalid reference: %s", from);
            goto done;
        }
        have_tree = 1;
    }
    /* Staging a path back means the index follows the tree, and a path the
       tree does not have leaves the index altogether. */
    int rc = staged
        ? bgit_reset_paths (&ctx->repo, &ctx->odb, have_tree ? tree : NULL,
                            &state.index, &state.n_index, paths,
                            (size_t) n_paths, worktree, 1)
        : bgit_checkout_paths (&ctx->repo, &ctx->odb, have_tree ? tree : NULL,
                               &state.index, &state.n_index, paths,
                               (size_t) n_paths, 0, worktree);
    if (rc < 0 || git_index_store (ctx, state.index, state.n_index) < 0)
        status = rc == -2 ? 1 : GIT_EXIT_FATAL;
done:
    git_state_release (&state);
    return status;
}

/* Does this name something the repository knows — a path the index holds,
   or a file that is there? It is how git tells a path from a revision. */
static int
git_path_known (git_context *ctx, struct git_state *state, const char *name)
{
    for (size_t i = 0; i < state->n_index; i++)
        if (git_path_named (state->index[i].path, &name, 1)) return 1;
    char full[4096];
    struct stat st;
    return (size_t) snprintf (full, sizeof full, "%s/%s",
                              ctx->repo.work_tree ? ctx->repo.work_tree : ".",
                              name) < sizeof full && lstat (full, &st) == 0;
}

/* What a mixed reset left between the index and the files, which git lists
   over the whole tree however few paths were named. */
static void
git_reset_report (git_context *ctx, struct git_state *state)
{
    int first = 1;
    for (size_t i = 0; i < state->n_index; i++) {
        char full[4096];
        if ((size_t) snprintf (full, sizeof full, "%s/%s",
                               ctx->repo.work_tree ? ctx->repo.work_tree : ".",
                               state->index[i].path) >= sizeof full)
            continue;
        struct stat st;
        int gone = lstat (full, &st) < 0;
        if (!gone &&
            bgit_worktree_matches (&ctx->odb, full, &state->index[i], &st))
            continue;
        if (first) { printf ("Unstaged changes after reset:\n"); first = 0; }
        printf ("%c\t%s\n", gone ? 'D' : 'M', state->index[i].path);
    }
}

static int
git_cmd_reset (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git reset [--soft | --mixed | --hard] [-q] "
                        "[<commit>] [-- <path>...]";
    int soft = 0, hard = 0, no_more = 0, quiet = 0;
    const char *commit_name = NULL;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "--soft")) soft = 1;
        else if (!no_more && !strcmp (w, "--mixed")) { soft = hard = 0; }
        else if (!no_more && !strcmp (w, "--hard")) hard = 1;
        else if (!no_more && (!strcmp (w, "-q") || !strcmp (w, "--quiet"))) quiet = 1;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (!no_more && !commit_name && !n_paths) commit_name = w;
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* The word before the paths is a commit, unless it is a file: git reads
       `git reset <file>` as a path. */
    if (commit_name) {
        char probe[41];
        if (git_resolve (ctx, commit_name, probe, NULL) < 0 &&
            git_path_exists (commit_name) &&
            n_paths < (int) (sizeof paths / sizeof *paths)) {
            for (int k = n_paths; k > 0; k--) paths[k] = paths[k - 1];
            paths[0] = commit_name;
            n_paths++;
            commit_name = NULL;
        }
    }
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    int status = 0;
    char id[41], commit[41], tree[41];
    /* The first word is a revision when it names one, and a path when it
       does not: git reset <file> is how a staged change is put back. */
    if (commit_name && git_resolve (ctx, commit_name, id, NULL) < 0 &&
        git_path_known (ctx, &state, commit_name) &&
        n_paths < (int) (sizeof paths / sizeof *paths)) {
        memmove (&paths[1], &paths[0], (size_t) n_paths * sizeof *paths);
        paths[0] = commit_name;
        n_paths++;
        commit_name = NULL;
    }
    const char *target = commit_name ? commit_name : "HEAD";
    /* Before the first commit there is nothing to go back to, and git
       takes HEAD to stand for the empty tree: the index is emptied, and
       --hard takes the files with it. */
    if (!commit_name && !state.have_head) {
        for (size_t j = 0; j < state.n_index;) {
            if (n_paths && !git_path_named (state.index[j].path, paths, n_paths)) {
                j++;
                continue;
            }
            char *gone = strdup (state.index[j].path);
            if (!gone) { status = GIT_EXIT_FATAL; goto done; }
            if (hard) {
                char full[4096];
                if ((size_t) snprintf (full, sizeof full, "%s/%s",
                                       ctx->repo.work_tree, gone) < sizeof full)
                    unlink (full);
            }
            bgit_index_remove_path (&state.index, &state.n_index, gone);
            free (gone);
        }
        if (!soft && git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
        if (!status && !soft && !hard && !quiet) git_reset_report (ctx, &state);
        goto done;
    }
    if (git_resolve (ctx, target, id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0 ||
        bgit_commit_tree (&ctx->odb, commit, tree) < 0) {
        status = git_fatal_ambiguous (target);
        goto done;
    }

    if (n_paths) {
        /* Only the index moves: the files are left alone. A pathspec that
           names nothing is not an error here, as it is for restore. */
        if (bgit_reset_paths (&ctx->repo, &ctx->odb, tree, &state.index,
                              &state.n_index, paths, (size_t) n_paths, 0, 0) < 0 ||
            git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
        if (!status && !quiet) git_reset_report (ctx, &state);
        goto done;
    }

    if (hard) {
        char *losing = NULL;
        int rc = bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state.index,
                                     &state.n_index, 1, &losing);
        free (losing);
        if (rc < 0) { status = GIT_EXIT_FATAL; goto done; }
        if (git_index_store (ctx, state.index, state.n_index) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
    } else if (!soft) {
        bgit_index_entry *entries = NULL;
        size_t n = 0;
        if (bgit_read_tree (&ctx->odb, tree, &entries, &n) < 0) {
            status = GIT_EXIT_FATAL;
            goto done;
        }
        /* A mixed reset keeps the files, so an entry the index already
           described this way keeps its stat data with it. One the reset
           moves takes the file's stat only when the file is what the tree
           says; otherwise the entry has to go on looking changed, which is
           what git reports after a reset. */
        for (size_t i = 0; i < n; i++) {
            bgit_index_entry *before = git_index_lookup (state.index,
                                                         state.n_index,
                                                         entries[i].path);
            if (before && before->mode == entries[i].mode &&
                memcmp (before->sha, entries[i].sha, 20) == 0) {
                char *keep = entries[i].path;
                entries[i] = *before;
                entries[i].path = keep;
                continue;
            }
            char full[4096];
            snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, entries[i].path);
            struct stat st;
            if (lstat (full, &st) != 0) continue;
            if (!bgit_worktree_matches (&ctx->odb, full, &entries[i], &st))
                continue;
            uint32_t mode = entries[i].mode;
            bgit_index_entry_set_stat (&entries[i], &st);
            entries[i].mode = mode;
        }
        int rc = git_index_store (ctx, entries, n);
        if (rc < 0) {
            bgit_index_free_entries (entries, n);
            status = GIT_EXIT_FATAL;
            goto done;
        }
        /* What the reset left behind is what is reported below. */
        bgit_index_free_entries (state.index, state.n_index);
        state.index = entries;
        state.n_index = state.cap_index = n;
    }

    const char *ref = state.branch ? state.branch : "HEAD";
    char message[1200];
    snprintf (message, sizeof message, "reset: moving to %s", target);
    /* A reset that does not move the branch leaves its log alone; HEAD's
       log records the reset either way, as git does. */
    int moved = !state.have_head || strcmp (state.head, commit) != 0;
    if (moved && bgit_ref_update (&ctx->repo, ref, commit, NULL, message) < 0)
        status = GIT_EXIT_FATAL;
    if (!status && state.branch)
        bgit_reflog_append (&ctx->repo, "HEAD", state.have_head ? state.head : NULL,
                            commit, message);
    if (!status && !quiet) {
        if (hard) {
            /* Where the branch now stands, in git's words. */
            struct git_commit landed;
            if (git_commit_read (ctx, commit, &landed) == 0) {
                char abbreviated[41], subject[4096];
                git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
                git_subject (&landed, subject, sizeof subject);
                printf ("HEAD is now at %s %s\n", abbreviated, subject);
                git_commit_release (&landed);
            }
        } else if (!soft)
            git_reset_report (ctx, &state);
    }
done:
    git_state_release (&state);
    return status;
}

/* ---- describe ---------------------------------------------------------- */

/* A tag that might name a commit: how it is written, what it stands on,
   and which of two tags on the same commit git keeps. */
struct git_describe_tag {
    char name[512];
    char commit[41];
    int annotated;              /* git prefers one of these */
    int priority;               /* 2 an annotated tag, 1 a tag, 0 any ref */
    long long tagged;           /* when an annotated tag was made */
    int depth;                  /* commits between it and the target */
    int order;                  /* where the walk found it */
};

/* The tags this repository has, peeled to the commits they name. */
static int
git_describe_tags (git_context *ctx, const char *match, int any_ref,
                   struct git_describe_tag **out, size_t *n_out)
{
    *out = NULL;
    *n_out = 0;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (bgit_refs_list (&ctx->repo, any_ref ? "refs/" : "refs/tags/", &refs,
                        &n_refs) < 0)
        return -1;
    struct git_describe_tag *tags = calloc (n_refs ? n_refs : 1, sizeof *tags);
    if (!tags) { bgit_refs_free (refs, n_refs); return -1; }
    size_t n = 0;
    for (size_t i = 0; i < n_refs; i++) {
        /* With every ref in play a name keeps what comes after refs/, which
           is what git prints for one. */
        const char *name = refs[i].name +
                           strlen (any_ref ? "refs/" : "refs/tags/");
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        int annotated = 0;
        long long tagged = 0;
        if (bgit_odb_read (&ctx->odb, refs[i].sha, &type, &data, &len) == 0) {
            annotated = type == BGIT_TAG;
            if (annotated) {
                /* When it was made, which decides between two of them. */
                const char *body = (const char *) data;
                for (size_t at = 0; at < len;) {
                    const char *nl = memchr (body + at, '\n', len - at);
                    size_t line = nl ? (size_t) (nl - (body + at)) : len - at;
                    if (!line) break;
                    if (!strncmp (body + at, "tagger ", 7)) {
                        const char *right = memrchr (body + at, '>', line);
                        if (right) tagged = strtoll (right + 1, NULL, 10);
                    }
                    if (!nl) break;
                    at += line + 1;
                }
            }
            free (data);
        }
        if (match && *match && fnmatch (match, name, 0) != 0) continue;
        char commit[41];
        if (bgit_peel_to_type (&ctx->odb, refs[i].sha, BGIT_COMMIT, commit) < 0)
            continue;
        /* One name per commit, chosen as git chooses: an annotated tag
           beats a light one and either beats a ref that is not a tag; a
           newer annotated tag beats an older; and among equals the first
           read wins, which is git's own order. */
        int is_tag = !any_ref || !strncmp (name, "tags/", 5);
        int priority = is_tag ? (annotated ? 2 : 1) : 0;
        size_t at = n;
        for (size_t j = 0; j < n; j++)
            if (!strcmp (tags[j].commit, commit)) { at = j; break; }
        if (at < n) {
            struct git_describe_tag *held = &tags[at];
            if (held->priority > priority) continue;
            if (held->priority == priority &&
                (!annotated || held->tagged >= tagged))
                continue;
        } else
            n++;
        snprintf (tags[at].name, sizeof tags[at].name, "%s", name);
        snprintf (tags[at].commit, sizeof tags[at].commit, "%s", commit);
        tags[at].annotated = annotated;
        tags[at].priority = priority;
        tags[at].tagged = tagged;
    }
    bgit_refs_free (refs, n_refs);
    *out = tags;
    *n_out = n;
    return 0;
}

/* Is anything the index tracks different from HEAD or from the files? */
static int
git_describe_dirty (git_context *ctx)
{
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return 0;
    bgit_status_entry *entries = NULL;
    size_t n = 0;
    int dirty = 0;
    if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, state.index,
                     state.n_index, state.have_head ? state.head_tree : NULL,
                     0, 0, 0, &entries, &n) == 0) {
        for (size_t i = 0; i < n && !dirty; i++)
            if (entries[i].staged || entries[i].unstaged || entries[i].unmerged)
                dirty = 1;
        bgit_status_free (entries, n);
    }
    git_state_release (&state);
    return dirty;
}

static int
git_cmd_describe (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git describe [--tags] [--long] [--always] "
                        "[--abbrev=<n>] [--exact-match] [--match <pattern>] "
                        "[--candidates=<n>] [--dirty[=<mark>]] "
                        "[<commit-ish>...]";
    int use_all_tags = 0, long_form = 0, always = 0, abbrev = 7;
    int candidates = 10, want_dirty = 0, contains = 0, any_ref = 0;
    const char *match = NULL, *mark = "-dirty";
    const char *named[16];
    int n_named = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--tags")) use_all_tags = 1;
        else if (!strcmp (w, "--long")) long_form = 1;
        else if (!strcmp (w, "--always")) always = 1;
        else if (!strncmp (w, "--abbrev=", 9)) {
            abbrev = atoi (w + 9);
            if (abbrev && abbrev < 4) abbrev = 4;
            if (abbrev > 40) abbrev = 40;
        }
        else if (!strcmp (w, "--exact-match")) candidates = 0;
        else if (!strncmp (w, "--candidates=", 13)) candidates = atoi (w + 13);
        else if (!strcmp (w, "--match") && p->next) {
            match = p->next->word->word;
            p = p->next;
        }
        else if (!strncmp (w, "--match=", 8)) match = w + 8;
        else if (!strcmp (w, "--dirty")) want_dirty = 1;
        else if (!strncmp (w, "--dirty=", 8)) { want_dirty = 1; mark = w + 8; }
        else if (!strcmp (w, "--contains")) contains = 1;
        else if (!strcmp (w, "--all")) any_ref = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_named < (int) (sizeof named / sizeof *named))
            named[n_named++] = w;
        else return git_fatal ("too many arguments");
    }
    if (!n_named) named[n_named++] = "HEAD";
    /* With every ref in play, whether a tag was annotated no longer says
       which ones may be used. */
    if (any_ref) use_all_tags = 1;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* --contains asks the other question: not which tag is behind this
       commit, but which name reaches it, which is what name-rev works
       out. */
    if (contains) {
        struct git_rev_names names;
        if (git_name_revs (ctx, any_ref ? NULL : "refs/tags/*", 0, &names) < 0)
            return GIT_EXIT_FATAL;
        int rc = 0;
        for (int i = 0; i < n_named && !rc; i++) {
            char id[41], target[41];
            if (git_resolve (ctx, named[i], id, NULL) < 0 ||
                bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, target) < 0) {
                rc = git_fatal ("Not a valid object name %s", named[i]);
                break;
            }
            char shown[4096];
            git_rev_name_of (&names, target, !any_ref, shown, sizeof shown);
            if (!strcmp (shown, "undefined")) {
                if (always) {
                    char abbreviated[41];
                    git_abbrev (ctx, target, abbrev ? abbrev : 7, abbreviated,
                                sizeof abbreviated);
                    printf ("%s\n", abbreviated);
                } else rc = git_fatal ("cannot describe '%s'", target);
                continue;
            }
            printf ("%s\n", shown);
        }
        git_rev_names_release (&names);
        return rc;
    }

    if (long_form && !abbrev)
        return git_fatal ("options '--long' and '--abbrev=0' cannot be used "
                          "together");
    struct git_describe_tag *tags = NULL;
    size_t n_tags = 0;
    if (git_describe_tags (ctx, match, any_ref, &tags, &n_tags) < 0)
        return git_fatal ("cannot read refs");
    int saw_lightweight = 0;
    for (size_t i = 0; i < n_tags; i++)
        if (!tags[i].annotated) saw_lightweight = 1;

    int status = 0;
    for (int i = 0; i < n_named && !status; i++) {
        char id[41], target[41];
        if (git_resolve (ctx, named[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, target) < 0) {
            status = git_fatal ("Not a valid object name %s", named[i]);
            break;
        }
        if (!n_tags && !always) {
            status = git_fatal ("No names found, cannot describe anything.");
            break;
        }
        /* The commits behind the target, newest first: a tag on one of
           them is a candidate, and the ones nearest the target come
           first, which is the order git considers them in. */
        char (*walk)[41] = NULL;
        size_t n_walk = 0;
        const char *starts[1] = { target };
        if (git_collect_commits (ctx, starts, 1, NULL, 0, 0, -1, &walk,
                                 &n_walk) < 0) {
            status = git_fatal ("cannot read %s", named[i]);
            break;
        }
        struct git_describe_tag *best = NULL;
        int found = 0;
        for (size_t j = 0; j < n_walk && found < candidates + 1; j++) {
            /* Several names can sit on one commit: an annotated tag is
               taken over a lightweight one, and either over a branch. */
            struct git_describe_tag *tag = NULL;
            for (size_t k = 0; k < n_tags; k++)
                if ((use_all_tags || tags[k].annotated) &&
                    !strcmp (tags[k].commit, walk[j]) &&
                    (!tag || tags[k].priority > tag->priority))
                    tag = &tags[k];
            if (!tag) continue;
            if (j == 0) { tag->depth = 0; best = tag; break; }
            if (found >= candidates) break;
            tag->order = ++found;
            /* How many commits the target has that the tag does not. */
            char (*between)[41] = NULL;
            size_t n_between = 0;
            const char *excludes[1] = { tag->commit };
            if (git_collect_commits (ctx, starts, 1, excludes, 1, 0, -1,
                                     &between, &n_between) < 0)
                continue;
            free (between);
            tag->depth = (int) n_between;
            if (!best || tag->depth < best->depth) best = tag;
        }
        free (walk);
        if (!best) {
            if (always) {
                char abbreviated[41];
                git_abbrev (ctx, target, abbrev ? abbrev : 7, abbreviated,
                            sizeof abbreviated);
                printf ("%s%s\n", abbreviated,
                        want_dirty && git_describe_dirty (ctx) ? mark : "");
                continue;
            }
            if (!candidates)
                status = git_fatal ("no tag exactly matches '%s'", target);
            else if (saw_lightweight && !use_all_tags) {
                fflush (stdout);
                fprintf (stderr, "fatal: No annotated tags can describe '%s'.\n"
                                 "However, there were unannotated tags: try "
                                 "--tags.\n", target);
                status = GIT_EXIT_FATAL;
            } else {
                fflush (stdout);
                fprintf (stderr, "fatal: No tags can describe '%s'.\n"
                                 "Try --always, or create some tags.\n", target);
                status = GIT_EXIT_FATAL;
            }
            break;
        }
        const char *dirt = want_dirty && git_describe_dirty (ctx) ? mark : "";
        /* With no abbreviation asked for, the name stands on its own. */
        if ((!best->depth && !long_form) || !abbrev) {
            printf ("%s%s\n", best->name, dirt);
            continue;
        }
        char abbreviated[41];
        git_abbrev (ctx, target, abbrev ? abbrev : 7, abbreviated,
                    sizeof abbreviated);
        printf ("%s-%d-g%s%s\n", best->name, best->depth, abbreviated, dirt);
    }
    free (tags);
    return status;
}

/* What -n writes beside a tag: an annotated tag's own message, or the
   message of the commit a light one names. The caller frees it. */
static char *
git_tag_note (git_context *ctx, const char *sha)
{
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, sha, &type, &data, &len) < 0) return NULL;
    if (type == BGIT_TAG) {
        /* The message is what follows the blank line after the headers. */
        const char *body = (const char *) data;
        size_t at = 0;
        while (at < len) {
            const char *nl = memchr (body + at, '\n', len - at);
            size_t line = nl ? (size_t) (nl - (body + at)) : len - at;
            at += line + 1;
            if (!line) break;
            if (!nl) { at = len; break; }
        }
        char *note = malloc (len - at + 1);
        if (note) {
            memcpy (note, body + at, len - at);
            note[len - at] = '\0';
        }
        free (data);
        return note;
    }
    free (data);
    char commit[41];
    if (bgit_peel_to_type (&ctx->odb, sha, BGIT_COMMIT, commit) < 0) return NULL;
    struct git_commit read;
    if (git_commit_read (ctx, commit, &read) < 0) return NULL;
    char *note = strdup (read.message);
    git_commit_release (&read);
    return note;
}

/* ---- apply ------------------------------------------------------------- */

/* One hunk of a patch: the lines as written, each keeping the space, plus
   or minus in front of it. */
struct git_apply_hunk {
    long old_start, old_count, new_start, new_count;
    char **lines;
    size_t n_lines;
};

/* One file's worth of a patch. */
struct git_apply_file {
    char *old_path, *new_path;
    int is_new, is_delete, is_rename, is_binary;
    unsigned old_mode, new_mode;
    struct git_apply_hunk *hunks;
    size_t n_hunks;
    size_t added, removed;
};

static void
git_apply_release (struct git_apply_file *files, size_t n)
{
    for (size_t i = 0; i < n; i++) {
        for (size_t j = 0; j < files[i].n_hunks; j++) {
            for (size_t k = 0; k < files[i].hunks[j].n_lines; k++)
                free (files[i].hunks[j].lines[k]);
            free (files[i].hunks[j].lines);
        }
        free (files[i].hunks);
        free (files[i].old_path);
        free (files[i].new_path);
    }
    free (files);
}

/* What a path in a patch is called once <n> leading parts are taken off,
   which is what -p<n> asks for. NULL for /dev/null. */
static char *
git_apply_strip (const char *path, int strip)
{
    if (!strcmp (path, "/dev/null")) return NULL;
    const char *at = path;
    for (int i = 0; i < strip; i++) {
        const char *slash = strchr (at, '/');
        if (!slash) break;
        at = slash + 1;
    }
    return strdup (at);
}

/* Read a patch into the files and hunks it describes. */
static int
git_apply_parse (const char *text, size_t len, int strip,
                 struct git_apply_file **out, size_t *n_out)
{
    struct git_apply_file *files = NULL;
    size_t n = 0, cap = 0;
    struct git_apply_file *file = NULL;
    struct git_apply_hunk *hunk = NULL;
    /* How many lines of each side the hunk still expects: what comes after
       them — a mail's trailer, say — is not part of it. */
    long old_left = 0, new_left = 0;
    /* One line can be longer than any fixed stack buffer. The patch is
       already in memory; keep the whole line so a path or hunk is not
       silently shortened. */
    char *held = NULL;
    size_t held_cap = 0;

    for (size_t at = 0; at < len;) {
        const char *line = text + at;
        const char *nl = memchr (line, '\n', len - at);
        size_t line_len = nl ? (size_t) (nl - line) : len - at;
        at += line_len + (nl ? 1 : 0);
        if (line_len + 1 > held_cap) {
            char *grown = realloc (held, line_len + 1);
            if (!grown) goto oom;
            held = grown;
            held_cap = line_len + 1;
        }
        memcpy (held, line, line_len);
        held[line_len] = '\0';

        if (!strncmp (held, "diff --git ", 11)) {
            if (n == cap) {
                size_t next = cap ? cap * 2 : 16;
                struct git_apply_file *grown = realloc (files,
                                                        next * sizeof *grown);
                if (!grown) goto oom;
                files = grown;
                cap = next;
            }
            file = &files[n++];
            memset (file, 0, sizeof *file);
            hunk = NULL;
            continue;
        }
        if (!file) continue;
        if (!strncmp (held, "new file mode ", 14)) {
            file->is_new = 1;
            file->new_mode = (unsigned) strtoul (held + 14, NULL, 8);
            continue;
        }
        if (!strncmp (held, "deleted file mode ", 18)) {
            file->is_delete = 1;
            file->old_mode = (unsigned) strtoul (held + 18, NULL, 8);
            continue;
        }
        if (!strncmp (held, "old mode ", 9)) {
            file->old_mode = (unsigned) strtoul (held + 9, NULL, 8);
            continue;
        }
        if (!strncmp (held, "new mode ", 9)) {
            file->new_mode = (unsigned) strtoul (held + 9, NULL, 8);
            continue;
        }
        /* rename from/to already omit the a/ and b/ prefix that -p counts,
           so one fewer component is dropped than from ---/+++. -p0 and -p1
           keep the name as written. */
        if (!strncmp (held, "rename from ", 12)) {
            file->is_rename = 1;
            free (file->old_path);
            file->old_path = git_apply_strip (held + 12,
                                              strip > 0 ? strip - 1 : 0);
            continue;
        }
        if (!strncmp (held, "rename to ", 10)) {
            file->is_rename = 1;
            free (file->new_path);
            file->new_path = git_apply_strip (held + 10,
                                              strip > 0 ? strip - 1 : 0);
            continue;
        }
        if (!strncmp (held, "GIT binary patch", 16)) {
            file->is_binary = 1;
            continue;
        }
        if (!strncmp (held, "--- ", 4)) {
            free (file->old_path);
            file->old_path = git_apply_strip (held + 4, strip);
            if (!file->old_path) file->is_new = 1;
            continue;
        }
        if (!strncmp (held, "+++ ", 4)) {
            free (file->new_path);
            file->new_path = git_apply_strip (held + 4, strip);
            if (!file->new_path) file->is_delete = 1;
            continue;
        }
        if (!strncmp (held, "@@ ", 3)) {
            long os = 1, oc = 1, ns = 1, nc = 1;
            const char *p = held + 3;
            if (*p == '-') p++;
            os = strtol (p, (char **) &p, 10);
            if (*p == ',') oc = strtol (p + 1, (char **) &p, 10);
            while (*p == ' ') p++;
            if (*p == '+') p++;
            ns = strtol (p, (char **) &p, 10);
            if (*p == ',') nc = strtol (p + 1, (char **) &p, 10);
            struct git_apply_hunk *grown = realloc (file->hunks,
                                                    (file->n_hunks + 1) *
                                                    sizeof *grown);
            if (!grown) goto oom;
            file->hunks = grown;
            hunk = &file->hunks[file->n_hunks++];
            memset (hunk, 0, sizeof *hunk);
            hunk->old_start = os;
            hunk->old_count = oc;
            hunk->new_start = ns;
            hunk->new_count = nc;
            old_left = oc;
            new_left = nc;
            continue;
        }
        if (!hunk) continue;
        if (held[0] != ' ' && held[0] != '+' && held[0] != '-' &&
            held[0] != '\\' && held[0] != '\0')
            continue;
        if (held[0] != '\\' && old_left <= 0 && new_left <= 0) {
            hunk = NULL;                  /* the hunk is complete */
            continue;
        }
        if (held[0] == ' ') { old_left--; new_left--; }
        else if (held[0] == '-') old_left--;
        else if (held[0] == '+') new_left--;
        else if (!held[0]) { old_left--; new_left--; }
        char **grown = realloc (hunk->lines,
                                (hunk->n_lines + 1) * sizeof *grown);
        if (!grown) goto oom;
        hunk->lines = grown;
        /* A line that is empty in the patch stands for an empty context
           line, which is what git makes of it. */
        hunk->lines[hunk->n_lines] = strdup (held[0] ? held : " ");
        if (!hunk->lines[hunk->n_lines]) goto oom;
        hunk->n_lines++;
        if (held[0] == '+') file->added++;
        else if (held[0] == '-') file->removed++;
    }
    free (held);
    *out = files;
    *n_out = n;
    return 0;
oom:
    free (held);
    git_apply_release (files, n);
    return -1;
}

/* The lines of a file, without their newlines. */
struct git_apply_lines {
    char **line;
    size_t n, cap;
    int missing_newline;
};

static int
git_apply_split (const char *text, size_t len, struct git_apply_lines *out)
{
    memset (out, 0, sizeof *out);
    for (size_t at = 0; at < len;) {
        const char *nl = memchr (text + at, '\n', len - at);
        size_t line_len = nl ? (size_t) (nl - (text + at)) : len - at;
        if (out->n == out->cap) {
            size_t next = out->cap ? out->cap * 2 : 64;
            char **grown = realloc (out->line, next * sizeof *grown);
            if (!grown) return -1;
            out->line = grown;
            out->cap = next;
        }
        out->line[out->n] = malloc (line_len + 1);
        if (!out->line[out->n]) return -1;
        memcpy (out->line[out->n], text + at, line_len);
        out->line[out->n][line_len] = '\0';
        out->n++;
        if (!nl) { out->missing_newline = 1; break; }
        at += line_len + 1;
    }
    return 0;
}

static void
git_apply_lines_release (struct git_apply_lines *lines)
{
    for (size_t i = 0; i < lines->n; i++) free (lines->line[i]);
    free (lines->line);
}

/* Does the hunk's old side sit at this line of the file? */
static int
git_apply_fits (const struct git_apply_hunk *hunk,
                const struct git_apply_lines *lines, size_t at)
{
    size_t i = at;
    for (size_t k = 0; k < hunk->n_lines; k++) {
        const char *line = hunk->lines[k];
        if (line[0] == '+' || line[0] == '\\') continue;
        if (i >= lines->n) return 0;
        if (strcmp (lines->line[i], line + 1)) return 0;
        i++;
    }
    return 1;
}

/* Apply one file's hunks. Returns 0 and the new content, or -1 with the
   line the patch failed at in *FAILED. */
static int
git_apply_hunks (const struct git_apply_file *file,
                 const struct git_apply_lines *lines, char **out, size_t *out_len,
                 long *failed)
{
    char *result = NULL;
    size_t result_len = 0, result_cap = 0;
    size_t pos = 0;
    long offset = 0;
#define GIT_APPLY_PUT(text, text_len, newline)                              \
    do {                                                                    \
        size_t want = result_len + (text_len) + 1;                          \
        if (want > result_cap) {                                            \
            size_t next = result_cap ? result_cap * 2 : 4096;               \
            while (next < want) next *= 2;                                  \
            char *grown = realloc (result, next);                           \
            if (!grown) { free (result); return -1; }                       \
            result = grown;                                                 \
            result_cap = next;                                              \
        }                                                                   \
        memcpy (result + result_len, (text), (text_len));                   \
        result_len += (text_len);                                           \
        if (newline) result[result_len++] = '\n';                           \
    } while (0)

    for (size_t h = 0; h < file->n_hunks; h++) {
        const struct git_apply_hunk *hunk = &file->hunks[h];
        /* A hunk with no leading context must match the start of the
           file, and one with no trailing context its end. */
        int at_start = hunk->old_start <= 1;
        int at_end = 1;
        for (size_t k = hunk->n_lines; k-- > 0;) {
            if (hunk->lines[k][0] == '\\') continue;
            at_end = hunk->lines[k][0] != ' ';
            break;
        }
        size_t want = 0;
        for (size_t k = 0; k < hunk->n_lines; k++)
            if (hunk->lines[k][0] == ' ' || hunk->lines[k][0] == '-') want++;
        long wanted = hunk->old_start - 1 + offset;
        if (wanted < 0) wanted = 0;
        long found = -1;
        for (long spread = 0; found < 0; spread++) {
            long forward = wanted + spread, back = wanted - spread;
            int tried = 0;
            if (forward >= 0 && (size_t) forward + want <= lines->n) {
                tried = 1;
                if ((!at_start || forward == 0) &&
                    (!at_end || (size_t) forward + want == lines->n) &&
                    git_apply_fits (hunk, lines, (size_t) forward))
                    found = forward;
            }
            if (found < 0 && spread && back >= 0 &&
                (size_t) back + want <= lines->n) {
                tried = 1;
                if ((!at_start || back == 0) &&
                    (!at_end || (size_t) back + want == lines->n) &&
                    git_apply_fits (hunk, lines, (size_t) back))
                    found = back;
            }
            if (found < 0 && !tried) break;
        }
        if (found < 0) {
            free (result);
            *failed = hunk->old_start;
            return -1;
        }
        for (size_t i = pos; i < (size_t) found; i++)
            GIT_APPLY_PUT (lines->line[i], strlen (lines->line[i]),
                           i + 1 < lines->n || !lines->missing_newline);
        for (size_t k = 0; k < hunk->n_lines; k++) {
            const char *line = hunk->lines[k];
            if (line[0] == '-' || line[0] == '\\') continue;
            int newline = 1;
            /* "\ No newline at end of file" after a line says it ends
               without one. */
            if (k + 1 < hunk->n_lines && hunk->lines[k + 1][0] == '\\')
                newline = 0;
            GIT_APPLY_PUT (line + 1, strlen (line + 1), newline);
        }
        pos = (size_t) found + want;
        offset = found - (hunk->old_start - 1);
    }
    for (size_t i = pos; i < lines->n; i++)
        GIT_APPLY_PUT (lines->line[i], strlen (lines->line[i]),
                       i + 1 < lines->n || !lines->missing_newline);
#undef GIT_APPLY_PUT
    if (!result) {
        result = malloc (1);
        if (!result) return -1;
    }
    *out = result;
    *out_len = result_len;
    return 0;
}

/* Is this a path a patch may touch? A patch is read from outside, and
   what it names has to stay inside the repository: nothing that climbs
   above it, and nothing in the administrative directory. */
static int
git_apply_path_ok (const char *path)
{
    return bgit_index_path_valid (path);
}

static int
git_apply_full_path (git_context *ctx, const char *path, char *out, size_t size)
{
    int len = snprintf (out, size, "%s/%s",
                         ctx->repo.work_tree ? ctx->repo.work_tree : ".", path);
    if (len < 0 || (size_t) len >= size) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

/* Write the content out, making the directories above it first, since a
   patch may add a file deep in a tree. */
static int
git_apply_write (const char *path, const char *content, size_t len,
                 unsigned mode, int change_mode)
{
    const char *name;
    int parent = bgit_worktree_parent (path, 1, &name);
    if (parent < 0) return -1;
    int fd = openat (parent, name,
                     O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW | O_CLOEXEC,
                     mode == 0100755 ? 0777 : 0666);
    int saved_errno = errno;
    close (parent);
    errno = saved_errno;
    if (fd < 0) return -1;
    size_t at = 0;
    while (at < len) {
        ssize_t wrote = write (fd, content + at, len - at);
        if (wrote <= 0) {
            if (wrote < 0 && errno == EINTR) continue;
            close (fd); return -1;
        }
        at += (size_t) wrote;
    }
    int rc = change_mode ? fchmod (fd, mode == 0100755 ? 0755 : 0644) : 0;
    if (close (fd) < 0) rc = -1;
    return rc;
}

/* What --stat writes, which is not the shape git's diff writes: the name
   in a column of its own, then the count, then the marks. */
static void
git_apply_stat (const struct git_apply_file *files, size_t n)
{
    size_t max_name = 0, max_change = 0, added = 0, removed = 0;
    for (size_t i = 0; i < n; i++) {
        const char *name = files[i].new_path ? files[i].new_path
                                             : files[i].old_path;
        size_t len = name ? strlen (name) : 0;
        if (len > max_name) max_name = len;
        size_t change = files[i].added + files[i].removed;
        if (change > max_change) max_change = change;
        added += files[i].added;
        removed += files[i].removed;
    }
    if (max_name > 50) max_name = 50;
    for (size_t i = 0; i < n; i++) {
        char shown[8192];
        const char *name = files[i].new_path ? files[i].new_path
                                             : files[i].old_path;
        snprintf (shown, sizeof shown, "%s", name ? name : "");
        size_t width = max_name + strlen (shown) > 70 ? 70 - max_name
                                                      : max_change;
        int add = (int) files[i].added, del = (int) files[i].removed;
        if (max_change && (size_t) (add + del) > width) {
            int total = (int) (((size_t) (add + del) * width +
                                max_change / 2) / max_change);
            add = (int) (((size_t) add * width + max_change / 2) / max_change);
            del = total - add;
        }
        printf (" %-*s |%5zu %.*s%.*s\n", (int) max_name, shown,
                files[i].added + files[i].removed, add,
                "++++++++++++++++++++++++++++++++++++++++++++++++++++++++"
                "++++++++++++++", del,
                "------------------------------------------------------"
                "----------------");
    }
    bgit_stat_summary (stdout, n, added, removed);
}

static int
git_cmd_apply (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git apply [--check] [--stat] [--numstat] "
                        "[--summary] [-R] [-p<n>] [--index] [--cached] "
                        "[<patch>...]";
    int check = 0, stat_only = 0, numstat = 0, summary = 0, reverse = 0;
    int strip = 1, with_index = 0, cached = 0;
    const char *names[16];
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--check")) check = 1;
        else if (!strcmp (w, "--stat")) stat_only = 1;
        else if (!strcmp (w, "--numstat")) numstat = 1;
        else if (!strcmp (w, "--summary")) summary = 1;
        else if (!strcmp (w, "-R") || !strcmp (w, "--reverse")) reverse = 1;
        else if (!strncmp (w, "-p", 2) && git_all_digits (w + 2))
            strip = atoi (w + 2);
        else if (!strcmp (w, "--index")) with_index = 1;
        else if (!strcmp (w, "--cached")) cached = with_index = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names))
            names[n_names++] = w;
        else return git_fatal ("too many patches");
    }

    /* The patch, from the files named or from what is feeding us. */
    char *text = NULL;
    size_t len = 0;
    if (!n_names) {
        unsigned char *data = NULL;
        if (bgit_slurp_fd (STDIN_FILENO, &data, &len) < 0)
            return git_fatal ("cannot read the patch");
        text = (char *) data;
    } else {
        for (int i = 0; i < n_names; i++) {
            unsigned char *data = NULL;
            size_t piece = 0;
            if (bgit_slurp_file (names[i], &data, &piece) < 0) {
                free (text);
                return git_fatal ("cannot open patch '%s'", names[i]);
            }
            char *grown = realloc (text, len + piece + 1);
            if (!grown) { free (text); free (data); return GIT_EXIT_FATAL; }
            text = grown;
            memcpy (text + len, data, piece);
            len += piece;
            text[len] = '\0';
            free (data);
        }
    }

    struct git_apply_file *files = NULL;
    size_t n = 0;
    if (git_apply_parse (text ? text : "", len, strip, &files, &n) < 0) {
        free (text);
        return GIT_EXIT_FATAL;
    }
    free (text);
    if (!n) {
        git_apply_release (files, n);
        fflush (stdout);
        fprintf (stderr, "error: No valid patches in input (allow with "
                         "\"--allow-empty\")\n");
        return GIT_EXIT_FATAL;
    }
    if (reverse)
        for (size_t i = 0; i < n; i++) {
            /* The two sides change places, and so does every line. */
            char *swap = files[i].old_path;
            files[i].old_path = files[i].new_path;
            files[i].new_path = swap;
            int was_new = files[i].is_new;
            files[i].is_new = files[i].is_delete;
            files[i].is_delete = was_new;
            unsigned mode = files[i].old_mode;
            files[i].old_mode = files[i].new_mode;
            files[i].new_mode = mode;
            size_t added = files[i].added;
            files[i].added = files[i].removed;
            files[i].removed = added;
            for (size_t h = 0; h < files[i].n_hunks; h++) {
                struct git_apply_hunk *hunk = &files[i].hunks[h];
                long start = hunk->old_start, count = hunk->old_count;
                hunk->old_start = hunk->new_start;
                hunk->old_count = hunk->new_count;
                hunk->new_start = start;
                hunk->new_count = count;
                for (size_t k = 0; k < hunk->n_lines; k++)
                    if (hunk->lines[k][0] == '+') hunk->lines[k][0] = '-';
                    else if (hunk->lines[k][0] == '-') hunk->lines[k][0] = '+';
            }
        }
    if (reverse)
        for (size_t i = 0; i < n / 2; i++) {
            struct git_apply_file swap = files[i];
            files[i] = files[n - 1 - i];
            files[n - 1 - i] = swap;
        }

    if (stat_only || numstat || summary) {
        if (stat_only) git_apply_stat (files, n);
        if (numstat)
            for (size_t i = 0; i < n; i++) {
                const char *name = files[i].new_path ? files[i].new_path
                                                     : files[i].old_path;
                printf ("%zu\t%zu\t%s\n", files[i].added, files[i].removed,
                        name ? name : "");
            }
        if (summary)
            for (size_t i = 0; i < n; i++) {
                if (files[i].is_new)
                    printf (" create mode %06o %s\n",
                            files[i].new_mode ? files[i].new_mode : 0100644,
                            files[i].new_path);
                else if (files[i].is_delete)
                    printf (" delete mode %06o %s\n",
                            files[i].old_mode ? files[i].old_mode : 0100644,
                            files[i].old_path);
                else if (files[i].is_rename)
                    printf (" rename %s => %s (%d%%)\n", files[i].old_path,
                            files[i].new_path, 100);
                if (!files[i].is_new && !files[i].is_delete &&
                    files[i].old_mode && files[i].new_mode &&
                    files[i].old_mode != files[i].new_mode)
                    printf (" mode change %06o => %06o %s\n",
                            files[i].old_mode, files[i].new_mode,
                            files[i].new_path ? files[i].new_path
                                              : files[i].old_path);
            }
        git_apply_release (files, n);
        return 0;
    }
    if (git_context_open (ctx) != 0) { git_apply_release (files, n); return GIT_EXIT_FATAL; }
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) {
        git_apply_release (files, n);
        return GIT_EXIT_FATAL;
    }

    /* Everything is worked out before anything is written, which is what
       makes --check the same run without the writing. */
    char **results = calloc (n ? n : 1, sizeof *results);
    size_t *result_lens = calloc (n ? n : 1, sizeof *result_lens);
    int status = 0;
    if (!results || !result_lens) status = GIT_EXIT_FATAL;
    for (size_t i = 0; i < n && status != GIT_EXIT_FATAL; i++) {
        struct git_apply_file *file = &files[i];
        const char *target = file->new_path ? file->new_path : file->old_path;
        const char *from = file->old_path ? file->old_path : target;
        if (file->is_binary) {
            status = git_fatal ("cannot apply binary patch to '%s' without "
                                "full index line", target);
            break;
        }
        /* A path that does not start at the repository is refused before
           anything at all is read of it. */
        if ((file->old_path && !git_apply_path_ok (file->old_path)) ||
            (file->new_path && !git_apply_path_ok (file->new_path))) {
            fflush (stdout);
            fprintf (stderr, "error: invalid path '%s'\n",
                     file->old_path && !git_apply_path_ok (file->old_path)
                     ? file->old_path : file->new_path);
            status = GIT_EXIT_FATAL;
            break;
        }
        char full[4096], source[4096];
        if (!cached) {
            if (git_apply_full_path (ctx, target, full, sizeof full) < 0) {
                status = git_fatal ("path too long: '%s'", target);
                break;
            }
            if (git_apply_full_path (ctx, from, source, sizeof source) < 0) {
                status = git_fatal ("path too long: '%s'", from);
                break;
            }
            /* A rename has two paths. Check both before reading its source
               or publishing any earlier file from the patch. */
            for (int side = 0; side < 2; side++) {
                const char *name;
                int parent = bgit_worktree_parent (side ? source : full, 0, &name);
                if (parent >= 0) close (parent);
                else if (errno != ENOENT) {
                    status = git_fatal ("cannot access '%s' safely", side ? from : target);
                    break;
                }
            }
            if (status == GIT_EXIT_FATAL) break;
        }
        unsigned char *before = NULL;
        size_t before_len = 0;
        if (!file->is_new) {
            if (cached) {
                bgit_index_entry *entry = git_index_lookup (state.index,
                                                            state.n_index, from);
                char hex[41];
                enum bgit_type type;
                if (!entry) {
                    fflush (stdout);
                    fprintf (stderr, "error: %s: does not exist in index\n", from);
                    status = 1;
                    continue;
                }
                bgit_sha_to_hex (entry->sha, hex);
                if (bgit_odb_read (&ctx->odb, hex, &type, &before,
                                   &before_len) < 0) {
                    status = git_fatal ("cannot read %s", from);
                    break;
                }
            } else {
                /* Whether it is there at all is asked first, so that the
                   complaint is git's one and not the reader's too. */
                struct stat st;
                if (lstat (source, &st) < 0) {
                    fflush (stdout);
                    fprintf (stderr, "error: %s: No such file or directory\n",
                             from);
                    status = 1;
                    continue;
                }
                if (file->old_mode) {
                    unsigned mode = bgit_worktree_mode (&st);
                    if (mode != file->old_mode) {
                        fflush (stdout);
                        fprintf (stderr, "warning: %s has type %o, expected "
                                         "%o\n", from, mode, file->old_mode);
                    }
                }
                const char *source_name;
                int parent = bgit_worktree_parent (source, 0, &source_name);
                int fd = parent < 0 ? -1 :
                    openat (parent, source_name, O_RDONLY | O_NOFOLLOW | O_CLOEXEC);
                if (parent >= 0) close (parent);
                int read_rc = fd < 0 ? -1 : bgit_slurp_fd (fd, &before, &before_len);
                if (fd >= 0) close (fd);
                if (read_rc < 0) {
                    fprintf (stderr, "error: cannot read '%s' safely\n", from);
                    free (before);
                    status = 1;
                    continue;
                }
            }
        }
        if (file->is_rename && file->old_path && file->new_path &&
            strcmp (file->old_path, file->new_path)) {
            struct stat st;
            if (!cached && lstat (full, &st) == 0) {
                fflush (stdout);
                fprintf (stderr, "error: %s: already exists in working "
                                 "directory\n", file->new_path);
                free (before);
                status = 1;
                continue;
            }
        }
        if (file->is_new) {
            struct stat st;
            if (!cached && lstat (full, &st) == 0) {
                fflush (stdout);
                fprintf (stderr, "error: %s: already exists in working "
                                 "directory\n", target);
                free (before);
                status = 1;
                continue;
            }
            if (cached && git_index_lookup (state.index, state.n_index, target)) {
                fflush (stdout);
                fprintf (stderr, "error: %s: already exists in index\n", target);
                free (before);
                status = 1;
                continue;
            }
        }
        struct git_apply_lines lines;
        if (git_apply_split ((const char *) (before ? before : (unsigned char *) ""),
                             before_len, &lines) < 0) {
            free (before);
            status = GIT_EXIT_FATAL;
            break;
        }
        long failed = 0;
        if (git_apply_hunks (file, &lines, &results[i], &result_lens[i],
                             &failed) < 0) {
            fflush (stdout);
            fprintf (stderr, "error: patch failed: %s:%ld\n",
                     file->old_path ? file->old_path : target, failed);
            fprintf (stderr, "error: %s: patch does not apply\n",
                     file->old_path ? file->old_path : target);
            status = 1;
        }
        git_apply_lines_release (&lines);
        free (before);
    }

    if (!status && !check) {
        for (size_t i = 0; i < n && !status; i++) {
            struct git_apply_file *file = &files[i];
            const char *target = file->new_path ? file->new_path
                                                : file->old_path;
            const char *from = file->old_path ? file->old_path : target;
            char full[4096], source[4096];
            if (!cached) {
                /* These same paths passed the planning checks. Keep every
                   construction checked as well, so future callers cannot
                   silently shorten a source, destination or removal. */
                if (git_apply_full_path (ctx, target, full, sizeof full) < 0 ||
                    git_apply_full_path (ctx, from, source, sizeof source) < 0) {
                    status = git_fatal ("path too long while applying '%s'", target);
                    break;
                }
                if (file->is_delete) {
                    if (bgit_worktree_unlink (source) < 0) {
                        status = git_fatal ("cannot remove '%s'", from);
                        break;
                    }
                } else {
                    if (git_apply_write (full, results[i], result_lens[i],
                                         file->new_mode,
                                         file->new_mode &&
                                         file->new_mode != file->old_mode) < 0) {
                        status = git_fatal ("cannot write '%s'", target);
                        break;
                    }
                    if (file->is_rename && strcmp (from, target)) {
                        if (bgit_worktree_unlink (source) < 0) {
                            status = git_fatal ("cannot remove '%s'", from);
                            break;
                        }
                    }
                }
            }
            if (with_index) {
                if (file->is_delete)
                    bgit_index_remove_path (&state.index, &state.n_index,
                                            (char *) from);
                else {
                    char sha[41];
                    if (bgit_write_object (ctx->odb.object_dirs[0], "blob",
                                           (const unsigned char *) results[i],
                                           result_lens[i], 1, sha) < 0) {
                        status = GIT_EXIT_FATAL;
                        break;
                    }
                    if (file->is_rename && strcmp (from, target))
                        bgit_index_remove_path (&state.index, &state.n_index,
                                                (char *) from);
                    bgit_index_entry entry;
                    memset (&entry, 0, sizeof entry);
                    entry.path = strdup (target);
                    if (!entry.path) { status = GIT_EXIT_FATAL; break; }
                    entry.mode = file->new_mode ? file->new_mode : 0100644;
                    bgit_hex_to_sha (sha, entry.sha);
                    size_t plen = strlen (target);
                    entry.flags = (uint16_t) (plen > 0xFFF ? 0xFFF : plen);
                    if (!cached) {
                        struct stat st;
                        if (lstat (full, &st) == 0) {
                            uint32_t mode = entry.mode;
                            bgit_index_entry_set_stat (&entry, &st);
                            entry.mode = mode;
                        }
                    }
                    if (git_index_put (&state.index, &state.n_index,
                                       &state.cap_index, &entry) < 0) {
                        status = GIT_EXIT_FATAL;
                        break;
                    }
                }
            }
        }
        if (!status && with_index &&
            git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
    }

    if (results)
        for (size_t i = 0; i < n; i++) free (results[i]);
    free (results);
    free (result_lens);
    git_state_release (&state);
    git_apply_release (files, n);
    return status;
}

/* ---- am ---------------------------------------------------------------- */

/* "Sun, 15 Jun 2025 15:06:40 +0000" as git writes a date: the seconds and
   the zone the mail carried. */
static int
git_am_date (const char *text, char *out, size_t outsz)
{
    static const char *const months[] = { "Jan", "Feb", "Mar", "Apr", "May",
                                          "Jun", "Jul", "Aug", "Sep", "Oct",
                                          "Nov", "Dec" };
    const char *at = text;
    while (*at == ' ') at++;
    /* The day name, if it is there, is of no use. */
    const char *comma = strchr (at, ',');
    if (comma && comma - at <= 4) at = comma + 1;
    while (*at == ' ') at++;
    int day = 0, year = 0, hour = 0, minute = 0, second = 0;
    char month_name[16] = "", zone[16] = "+0000";
    if (sscanf (at, "%d %15s %d %d:%d:%d %15s", &day, month_name, &year, &hour,
                &minute, &second, zone) < 6)
        return -1;
    int month = -1;
    for (int i = 0; i < 12; i++)
        if (!strncasecmp (month_name, months[i], 3)) month = i;
    if (month < 0) return -1;
    struct tm tm;
    memset (&tm, 0, sizeof tm);
    tm.tm_year = year - 1900;
    tm.tm_mon = month;
    tm.tm_mday = day;
    tm.tm_hour = hour;
    tm.tm_min = minute;
    tm.tm_sec = second;
    long long seconds = (long long) timegm (&tm);
    if (zone[0] == '+' || zone[0] == '-') {
        int zh = 0, zm = 0;
        sscanf (zone + 1, "%2d%2d", &zh, &zm);
        long long off = zh * 3600 + zm * 60;
        seconds += zone[0] == '-' ? off : -off;
    } else snprintf (zone, sizeof zone, "+0000");
    snprintf (out, outsz, "%lld %s", seconds, zone);
    return 0;
}

/* One message: who wrote it, what it says, and the patch under the "---". */
struct git_am_mail {
    char author[1200];
    char subject[4096];
    char *message;
    const char *patch;
    size_t patch_len;
};

static int
git_am_read (const char *text, size_t len, struct git_am_mail *out)
{
    memset (out, 0, sizeof *out);
    char name[512] = "", mail[512] = "", date[128] = "";
    size_t at = 0;
    /* The line git puts at the top of each message is not a header. */
    if (!strncmp (text, "From ", 5)) {
        const char *nl = memchr (text, '\n', len);
        at = nl ? (size_t) (nl - text) + 1 : len;
    }
    /* The headers, down to the blank line. */
    while (at < len) {
        const char *line = text + at;
        const char *nl = memchr (line, '\n', len - at);
        size_t line_len = nl ? (size_t) (nl - line) : len - at;
        at += line_len + (nl ? 1 : 0);
        if (!line_len) break;
        char held[8192];
        size_t keep = line_len < sizeof held - 1 ? line_len : sizeof held - 1;
        memcpy (held, line, keep);
        held[keep] = '\0';
        if (!strncasecmp (held, "From: ", 6)) {
            const char *who = held + 6;
            const char *open = strrchr (who, '<');
            const char *close = open ? strchr (open, '>') : NULL;
            if (open && close) {
                snprintf (mail, sizeof mail, "%.*s", (int) (close - open - 1),
                          open + 1);
                size_t plain = (size_t) (open - who);
                while (plain && who[plain - 1] == ' ') plain--;
                snprintf (name, sizeof name, "%.*s", (int) plain, who);
            } else snprintf (name, sizeof name, "%s", who);
        } else if (!strncasecmp (held, "Date: ", 6))
            snprintf (date, sizeof date, "%s", held + 6);
        else if (!strncasecmp (held, "Subject: ", 9)) {
            const char *subject = held + 9;
            /* "[PATCH n/m] " in front of it is not part of the subject. */
            while (*subject == '[') {
                const char *close = strchr (subject, ']');
                if (!close) break;
                subject = close + 1;
                while (*subject == ' ') subject++;
            }
            snprintf (out->subject, sizeof out->subject, "%s", subject);
        }
    }
    /* The body, down to the line of dashes that starts the patch. */
    char *message = NULL;
    size_t message_len = 0;
    FILE *builder = open_memstream (&message, &message_len);
    if (!builder) return -1;
    fprintf (builder, "%s\n", out->subject);
    int wrote_body = 0;
    while (at < len) {
        const char *line = text + at;
        const char *nl = memchr (line, '\n', len - at);
        size_t line_len = nl ? (size_t) (nl - line) : len - at;
        if (line_len == 3 && !memcmp (line, "---", 3)) {
            at += line_len + (nl ? 1 : 0);
            break;
        }
        if (line_len || wrote_body) {
            if (!wrote_body) fprintf (builder, "\n");
            wrote_body = 1;
            fprintf (builder, "%.*s\n", (int) line_len, line);
        }
        at += line_len + (nl ? 1 : 0);
    }
    fclose (builder);
    /* What the mail leaves at its end, trailer and all, is the patch. */
    out->message = message;
    out->patch = text + at;
    out->patch_len = len - at;
    char stamp[128] = "";
    if (!*date || git_am_date (date, stamp, sizeof stamp) < 0) {
        time_t now = time (NULL);
        snprintf (stamp, sizeof stamp, "%lld +0000", (long long) now);
    }
    snprintf (out->author, sizeof out->author, "%s <%s> %s",
              *name ? name : "bash-os", *mail ? mail : "bash-os@localhost",
              stamp);
    return 0;
}

/* Put a commit on the branch HEAD stands on, as am does for each patch. */
static int
git_am_commit (git_context *ctx, const char *author, const char *message,
               const char *subject)
{
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return -1;
    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                         state.n_index, tree) < 0) {
        git_state_release (&state);
        return -1;
    }
    char committer[1024];
    if (git_identity (ctx, 1, committer, sizeof committer)) {
        git_state_release (&state);
        return -1;
    }
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) { git_state_release (&state); return -1; }
    fprintf (builder, "tree %s\n", tree);
    if (state.have_head) fprintf (builder, "parent %s\n", state.head);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    fprintf (builder, "\n%s", message);
    size_t at = strlen (message);
    if (!at || message[at - 1] != '\n') fprintf (builder, "\n");
    fclose (builder);
    char written[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1,
                                written);
    free (body);
    if (rc < 0) { git_state_release (&state); return -1; }
    char reflog[1200];
    snprintf (reflog, sizeof reflog, "am: %s", subject);
    const char *ref = state.branch ? state.branch : "HEAD";
    if (bgit_ref_update (&ctx->repo, ref, written,
                         state.have_head ? state.head : NULL, reflog) < 0) {
        git_state_release (&state);
        return -1;
    }
    if (state.branch)
        bgit_reflog_append (&ctx->repo, "HEAD",
                            state.have_head ? state.head : NULL, written,
                            reflog);
    git_state_release (&state);
    return 0;
}

/* Where am keeps what it is in the middle of. */
static void
git_am_state_path (git_context *ctx, const char *name, char *out, size_t outsz)
{
    snprintf (out, outsz, "%s/rebase-apply%s%s", ctx->repo.git_dir,
              name && *name ? "/" : "", name ? name : "");
}

/* The same directory as git names it in a message: relative, where the
   reader is standing at the top of the worktree. */
static void
git_am_state_shown (git_context *ctx, char *out, size_t outsz)
{
    char cwd[4096], top[4096];
    if (ctx->repo.work_tree && getcwd (cwd, sizeof cwd) &&
        !strcmp (cwd, ctx->repo.work_tree) &&
        (size_t) snprintf (top, sizeof top, "%s/.git",
                           ctx->repo.work_tree) < sizeof top &&
        !strcmp (top, ctx->repo.git_dir)) {
        snprintf (out, outsz, ".git/rebase-apply");
        return;
    }
    snprintf (out, outsz, "%s/rebase-apply", ctx->repo.git_dir);
}

static int
git_am_state_write (git_context *ctx, const char *name, const char *text)
{
    char path[4096];
    git_am_state_path (ctx, name, path, sizeof path);
    FILE *f = fopen (path, "w");
    if (!f) return -1;
    fputs (text, f);
    return fclose (f) == 0 ? 0 : -1;
}

static int
git_am_state_read (git_context *ctx, const char *name, char *out, size_t outsz)
{
    char path[4096];
    git_am_state_path (ctx, name, path, sizeof path);
    FILE *f = fopen (path, "r");
    if (!f) return -1;
    if (!fgets (out, (int) outsz, f)) { fclose (f); return -1; }
    fclose (f);
    size_t at = strlen (out);
    while (at && (out[at - 1] == '\n' || out[at - 1] == '\r')) out[--at] = '\0';
    return 0;
}

static void
git_am_state_clear (git_context *ctx)
{
    char path[4096];
    git_am_state_path (ctx, "", path, sizeof path);
    DIR *handle = opendir (path);
    if (handle) {
        struct dirent *entry;
        while ((entry = readdir (handle))) {
            if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, ".."))
                continue;
            char one[4096];
            snprintf (one, sizeof one, "%s/%s", path, entry->d_name);
            unlink (one);
        }
        closedir (handle);
    }
    rmdir (path);
}

static int
git_cmd_am (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git am [-q] [--continue | --skip | --abort] "
                        "[<mbox>...]";
    int quiet = 0, do_continue = 0, skip = 0, abort_am = 0;
    const char *names[16];
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "--continue") || !strcmp (w, "-r") ||
                 !strcmp (w, "--resolved")) do_continue = 1;
        else if (!strcmp (w, "--skip")) skip = 1;
        else if (!strcmp (w, "--abort")) abort_am = 1;
        else if (!strcmp (w, "-3") || !strcmp (w, "--3way") ||
                 !strcmp (w, "--no-3way")) ;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names))
            names[n_names++] = w;
        else return git_fatal ("too many mailboxes");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char state_dir[4096];
    git_am_state_path (ctx, "", state_dir, sizeof state_dir);
    struct stat st;
    int in_progress = stat (state_dir, &st) == 0;

    if (abort_am) {
        if (!in_progress)
            return git_fatal ("Resolve operation not in progress, we are not "
                              "resuming.");
        char safety[41] = "";
        git_am_state_read (ctx, "abort-safety", safety, sizeof safety);
        git_am_state_clear (ctx);
        if (*safety) {
            WORD_LIST *reset = make_word_list (make_word ((char *) safety),
                                               NULL);
            reset = make_word_list (make_word ("--hard"), reset);
            reset = make_word_list (make_word ("-q"), reset);
            int status = git_cmd_reset (ctx, reset);
            dispose_words (reset);
            return status;
        }
        return 0;
    }
    if ((do_continue || skip) && !in_progress)
        return git_fatal ("Resolve operation not in progress, we are not "
                          "resuming.");
    if (!do_continue && !skip && in_progress) {
        char shown[4096];
        git_am_state_shown (ctx, shown, sizeof shown);
        return git_fatal ("previous rebase directory %s still exists but mbox "
                          "given.", shown);
    }

    long first = 1, last = 0;
    if (do_continue || skip) {
        char held[64];
        if (git_am_state_read (ctx, "next", held, sizeof held) == 0)
            first = atol (held);
        if (git_am_state_read (ctx, "last", held, sizeof held) == 0)
            last = atol (held);
        if (do_continue) {
            /* What was settled by hand is committed as the mail said. */
            char author[1200] = "", subject[4096] = "";
            char path[4096];
            git_am_state_path (ctx, "message", path, sizeof path);
            unsigned char *message = NULL;
            size_t message_len = 0;
            git_am_state_read (ctx, "author", author, sizeof author);
            git_am_state_read (ctx, "subject", subject, sizeof subject);
            if (bgit_slurp_file (path, &message, &message_len) < 0)
                return git_fatal ("cannot read what was being applied");
            char *text = malloc (message_len + 1);
            if (!text) { free (message); return GIT_EXIT_FATAL; }
            memcpy (text, message, message_len);
            text[message_len] = '\0';
            free (message);
            /* git names the patch again as it takes it up. */
            if (!quiet) printf ("Applying: %s\n", subject);
            int rc = git_am_commit (ctx, author, text, subject);
            free (text);
            if (rc < 0) return GIT_EXIT_FATAL;
        }
        first++;
    } else {
        /* A fresh run: every message is written down first, so that what
           is left can be gone on with. */
        char *text = NULL;
        size_t len = 0;
        if (!n_names) {
            unsigned char *data = NULL;
            if (bgit_slurp_fd (STDIN_FILENO, &data, &len) < 0)
                return git_fatal ("cannot read the mailbox");
            text = (char *) data;
        } else
            for (int i = 0; i < n_names; i++) {
                unsigned char *data = NULL;
                size_t piece = 0;
                if (bgit_slurp_file (names[i], &data, &piece) < 0) {
                    free (text);
                    return GIT_EXIT_FATAL;
                }
                char *grown = realloc (text, len + piece + 1);
                if (!grown) { free (text); free (data); return GIT_EXIT_FATAL; }
                text = grown;
                memcpy (text + len, data, piece);
                len += piece;
                text[len] = '\0';
                free (data);
            }
        if (mkdir (state_dir, 0777) < 0 && errno != EEXIST) {
            free (text);
            return git_fatal ("cannot make %s", state_dir);
        }
        /* Split on the line each message begins with. */
        size_t start = 0;
        for (size_t at = 0; at <= len; at++) {
            int boundary = at == len ||
                           ((at == 0 || text[at - 1] == '\n') &&
                            at + 5 <= len && !memcmp (text + at, "From ", 5));
            if (!boundary || at == start) continue;
            char name[64];
            snprintf (name, sizeof name, "%04ld", last + 1);
            char path[4096];
            git_am_state_path (ctx, name, path, sizeof path);
            FILE *f = fopen (path, "w");
            if (!f) { free (text); return GIT_EXIT_FATAL; }
            fwrite (text + start, 1, at - start, f);
            fclose (f);
            last++;
            start = at;
        }
        free (text);
        if (!last) {
            git_am_state_clear (ctx);
            fflush (stdout);
            fprintf (stderr, "error: empty mbox\n");
            return GIT_EXIT_FATAL;
        }
        char held[64];
        snprintf (held, sizeof held, "%ld\n", last);
        git_am_state_write (ctx, "last", held);
        struct git_state state;
        if (git_state_load (ctx, &state) == 0) {
            if (state.have_head) {
                char line[64];
                snprintf (line, sizeof line, "%s\n", state.head);
                git_am_state_write (ctx, "abort-safety", line);
                char orig[4096];
                snprintf (orig, sizeof orig, "%s/ORIG_HEAD", ctx->repo.git_dir);
                FILE *f = fopen (orig, "w");
                if (f) { fputs (line, f); fclose (f); }
            }
            git_state_release (&state);
        }
    }

    for (long number = first; number <= last; number++) {
        char name[64], held[64];
        snprintf (name, sizeof name, "%04ld", number);
        char path[4096];
        git_am_state_path (ctx, name, path, sizeof path);
        unsigned char *raw = NULL;
        size_t raw_len = 0;
        if (bgit_slurp_file (path, &raw, &raw_len) < 0)
            return git_fatal ("cannot read %s", path);
        struct git_am_mail mail;
        if (git_am_read ((const char *) raw, raw_len, &mail) < 0) {
            free (raw);
            return git_fatal ("cannot read the mail in %s", path);
        }
        if (!quiet) printf ("Applying: %s\n", mail.subject);
        fflush (stdout);
        /* The patch itself, put where apply can be handed it. */
        char patch_path[4096];
        git_am_state_path (ctx, "patch", patch_path, sizeof patch_path);
        FILE *f = fopen (patch_path, "w");
        if (!f) { free (mail.message); free (raw); return GIT_EXIT_FATAL; }
        fwrite (mail.patch, 1, mail.patch_len, f);
        fclose (f);
        WORD_LIST *apply = make_word_list (make_word (patch_path), NULL);
        apply = make_word_list (make_word ("--index"), apply);
        int rc = git_cmd_apply (ctx, apply);
        dispose_words (apply);
        if (rc) {
            snprintf (held, sizeof held, "%ld\n", number);
            git_am_state_write (ctx, "next", held);
            git_am_state_write (ctx, "author", mail.author);
            git_am_state_write (ctx, "subject", mail.subject);
            git_am_state_write (ctx, "message", mail.message);
            printf ("Patch failed at %04ld %s\n", number, mail.subject);
            fflush (stdout);
            fprintf (stderr, "hint: Use 'git am --show-current-patch=diff' to "
                             "see the failed patch\n");
            fprintf (stderr, "hint: When you have resolved this problem, run "
                             "\"git am --continue\".\n");
            fprintf (stderr, "hint: If you prefer to skip this patch, run "
                             "\"git am --skip\" instead.\n");
            fprintf (stderr, "hint: To restore the original branch and stop "
                             "patching, run \"git am --abort\".\n");
            fprintf (stderr, "hint: Disable this message with \"git config "
                             "advice.mergeConflict false\"\n");
            free (mail.message);
            free (raw);
            return 128;
        }
        int committed = git_am_commit (ctx, mail.author, mail.message,
                                       mail.subject);
        free (mail.message);
        free (raw);
        if (committed < 0) return GIT_EXIT_FATAL;
    }
    git_am_state_clear (ctx);
    return 0;
}

/* Is a piece of git's advice still wanted? Each hint has a name under
   advice., and setting it false turns that hint off. */
static int
git_advice_wanted (git_context *ctx, const char *name)
{
    char key[256];
    snprintf (key, sizeof key, "advice.%s", name);
    return bgit_config_bool (&ctx->cfg, key, 1);
}

/* One identity for a new object, or git's own complaint about it. Returns 0,
   or the status the command should end with. */
static int
git_identity (git_context *ctx, int committer, char *out, size_t size)
{
    int rc = bgit_ident (&ctx->cfg, committer, out, size);
    if (rc == 0) return 0;
    if (rc == -2) {
        char held[256];
        const char *date = bgit_env (committer ? "GIT_COMMITTER_DATE"
                                               : "GIT_AUTHOR_DATE",
                                     held, sizeof held);
        return git_fatal ("invalid date format: %s", date ? date : "");
    }
    return git_fatal ("cannot determine the identity to use");
}

/* The author and committer lines for a new object, or git's own complaint
   about them. Returns 0, or the status the command should end with. */
static int
git_identities (git_context *ctx, char *author, size_t author_size,
                char *committer, size_t committer_size)
{
    for (int who = 0; who < 2; who++) {
        char *out = who ? committer : author;
        size_t size = who ? committer_size : author_size;
        int rc = bgit_ident (&ctx->cfg, who, out, size);
        if (rc == 0) continue;
        if (rc == -2) {
            char held[256];
            const char *date = bgit_env (who ? "GIT_COMMITTER_DATE"
                                             : "GIT_AUTHOR_DATE",
                                         held, sizeof held);
            return git_fatal ("invalid date format: %s", date ? date : "");
        }
        return git_fatal ("cannot determine the identity to use");
    }
    return 0;
}

/* ---- patch ids --------------------------------------------------------- */

/* git hashes a path with its whitespace taken out. */
static void
git_patch_id_path (FILE *out, const char *path)
{
    for (const char *p = path; *p; p++)
        if (!isspace ((unsigned char) *p)) fputc (*p, out);
}

/* What a commit changes, written the way git hashes it for a patch id: the
   two paths with no whitespace in them, the modes where they differ, the
   names again, and then the lines of the diff with three of context. The
   point of it is a name for the change that does not depend on where in the
   file it landed or on what the commit before it was. */
static int
git_patch_id_text (git_context *ctx, FILE *out, const bgit_diff_entry *entry)
{
    fputs ("diff--git", out);
    fputs ("a/", out);
    git_patch_id_path (out, entry->from ? entry->from : entry->path);
    fputs ("b/", out);
    git_patch_id_path (out, entry->path);
    if (entry->status == 'A') fprintf (out, "newfilemode%06o", entry->new_mode);
    else if (entry->status == 'D')
        fprintf (out, "deletedfilemode%06o", entry->old_mode);
    else if (entry->old_mode != entry->new_mode)
        fprintf (out, "oldmode%06onewmode%06o", entry->old_mode,
                 entry->new_mode);

    bgit_patch_options options;
    bgit_patch_options_init (&options);
    char *old_data = NULL, *new_data = NULL;
    size_t old_len = 0, new_len = 0;
    if (bgit_patch_content (&ctx->odb, &ctx->repo, entry, 0, &options,
                            &old_data, &old_len) < 0 ||
        bgit_patch_content (&ctx->odb, &ctx->repo, entry, 1, &options,
                            &new_data, &new_len) < 0) {
        free (old_data);
        return -1;
    }
    bgit_xdiff_file old_file, new_file;
    bgit_xdiff_load (&old_file, old_data, old_len);
    bgit_xdiff_load (&new_file, new_data, new_len);
    if (old_file.binary || new_file.binary) {
        /* Two binary files are known apart by their ids alone. */
        fputs (entry->old_sha, out);
        fputs (entry->new_sha, out);
        goto done;
    }
    if (entry->status == 'A') {
        fputs ("---/dev/null", out);
        fputs ("+++b/", out);
        git_patch_id_path (out, entry->path);
    } else if (entry->status == 'D') {
        fputs ("---a/", out);
        git_patch_id_path (out, entry->from ? entry->from : entry->path);
        fputs ("+++/dev/null", out);
    } else {
        fputs ("---a/", out);
        git_patch_id_path (out, entry->from ? entry->from : entry->path);
        fputs ("+++b/", out);
        git_patch_id_path (out, entry->path);
    }

    bgit_xdiff_result result;
    if (bgit_xdiff_opts (&old_file, &new_file, 3, BGIT_XDIFF_INDENT_HEURISTIC,
                         &result) == 0) {
        /* The lines themselves, as a patch would show them but with no
           header over them: that is what makes the id the same wherever the
           change sits in the file. */
        for (size_t h = 0; h < result.n_hunks; h++) {
            const bgit_xdiff_hunk *hunk = &result.hunks[h];
            size_t i = hunk->old_start, j = hunk->new_start;
            size_t end_old = i + hunk->old_count, end_new = j + hunk->new_count;
            while (i < end_old || j < end_new) {
                int changed = (i < end_old && result.old_changed[i]) ||
                              (j < end_new && result.new_changed[j]);
                if (!changed) {
                    fputc (' ', out);
                    fwrite (new_file.lines[j], 1, new_file.lengths[j], out);
                    fputc ('\n', out);
                    i++;
                    j++;
                    continue;
                }
                while (i < end_old && result.old_changed[i]) {
                    fputc ('-', out);
                    fwrite (old_file.lines[i], 1, old_file.lengths[i], out);
                    fputc ('\n', out);
                    i++;
                }
                while (j < end_new && result.new_changed[j]) {
                    fputc ('+', out);
                    fwrite (new_file.lines[j], 1, new_file.lengths[j], out);
                    fputc ('\n', out);
                    j++;
                }
            }
        }
        bgit_xdiff_result_release (&result);
    }

done:
    bgit_xdiff_release (&old_file);
    bgit_xdiff_release (&new_file);
    free (old_data);
    free (new_data);
    return 0;
}

/* The patch id of one commit, as forty hex digits. A merge has none, and
   nor has a commit that changed nothing. Returns 0, or -1. */
static int
git_commit_patch_id (git_context *ctx, const char *id, char out[41])
{
    struct git_commit commit;
    if (git_commit_read (ctx, id, &commit) < 0) return -1;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    int rc = git_commit_changes (ctx, &commit, NULL, 0, &entries, &n);
    git_commit_release (&commit);
    if (rc < 0) return -1;

    char *text = NULL;
    size_t len = 0;
    FILE *builder = open_memstream (&text, &len);
    if (!builder) { bgit_diff_free (entries, n); return -1; }
    for (size_t i = 0; i < n; i++)
        if (git_patch_id_text (ctx, builder, &entries[i]) < 0) {
            fclose (builder);
            free (text);
            bgit_diff_free (entries, n);
            return -1;
        }
    fclose (builder);
    bgit_diff_free (entries, n);
    unsigned char digest[20];
    bgit_sha1 ((const unsigned char *) (text ? text : ""), len, digest);
    bgit_sha_to_hex (digest, out);
    free (text);
    return 0;
}

/* `git patch-id` names patches arriving on standard input. The unstable
   form hashes every file as one stream; the stable form hashes one file at
   a time and adds the twenty-byte values, so file order no longer matters. */
struct git_patch_id_stream {
    unsigned char *text;
    size_t len, cap;
    unsigned char sum[20];
    size_t patch_len;
    int before, after, binary;
    char pre[65], post[65];
};

static void
git_patch_id_stream_init (struct git_patch_id_stream *stream)
{
    memset (stream, 0, sizeof *stream);
    stream->before = stream->after = -1;
}

static int
git_patch_id_append (struct git_patch_id_stream *stream, const char *line,
                     size_t len, int verbatim, int counts)
{
    size_t add = 0;
    if (verbatim) add = len;
    else
        for (size_t i = 0; i < len; i++)
            if (!isspace ((unsigned char) line[i])) add++;
    if (stream->len + add > stream->cap) {
        size_t next = stream->cap ? stream->cap * 2 : 4096;
        while (next < stream->len + add) next *= 2;
        unsigned char *grown = realloc (stream->text, next);
        if (!grown) return -1;
        stream->text = grown;
        stream->cap = next;
    }
    if (verbatim) {
        memcpy (stream->text + stream->len, line, len);
        stream->len += len;
    } else {
        for (size_t i = 0; i < len; i++)
            if (!isspace ((unsigned char) line[i]))
                stream->text[stream->len++] = (unsigned char) line[i];
    }
    if (counts) stream->patch_len += add;
    return 0;
}

static int
git_patch_id_finish_file (struct git_patch_id_stream *stream)
{
    unsigned char digest[20];
    if (bgit_sha1 (stream->text, stream->len, digest) < 0) return -1;
    unsigned int carry = 0;
    for (int i = 0; i < 20; i++) {
        carry += stream->sum[i] + digest[i];
        stream->sum[i] = (unsigned char) carry;
        carry >>= 8;
    }
    stream->len = 0;
    return 0;
}

static int
git_patch_id_hunk (const char *line, int *before, int *after)
{
    if (strncmp (line, "@@ -", 4)) return 0;
    char *end = NULL;
    (void) strtol (line + 4, &end, 10);
    if (end == line + 4) return 0;
    *before = 1;
    if (*end == ',') {
        long count = strtol (end + 1, &end, 10);
        if (count < 0) return 0;
        *before = (int) count;
    }
    if (end[0] != ' ' || end[1] != '+') return 0;
    const char *new_start = end + 2;
    (void) strtol (new_start, &end, 10);
    if (end == new_start) return 0;
    *after = 1;
    if (*end == ',') {
        long count = strtol (end + 1, &end, 10);
        if (count < 0) return 0;
        *after = (int) count;
    }
    return 1;
}

static int
git_patch_id_boundary (const char *line, char id[41])
{
    const char *hex = !strncmp (line, "commit ", 7) ? line + 7
                    : !strncmp (line, "From ", 5) ? line + 5 : line;
    if (strlen (hex) < 40) return 0;
    char candidate[41];
    memcpy (candidate, hex, 40);
    candidate[40] = '\0';
    unsigned char raw[20];
    if (bgit_hex_to_sha (candidate, raw) < 0) return 0;
    bgit_sha_to_hex (raw, id);
    return 1;
}

static void
git_patch_id_print (struct git_patch_id_stream *stream, const char id[41])
{
    if (!stream->patch_len) return;
    char result[41];
    bgit_sha_to_hex (stream->sum, result);
    printf ("%s %s\n", result, id);
}

/* These two settings are booleans in git's command-specific parser.  Unlike
   the general config reader, it rejects a word that is not a boolean. */
static int
git_patch_id_config_bool (const bgit_config *cfg, const char *key,
                          int fallback, int *out)
{
    const char *value = bgit_config_get (cfg, key);
    if (!value) {
        *out = fallback;
        return 0;
    }
    static const char *const yes[] = { "true", "yes", "on", "1", NULL };
    static const char *const no[] = { "false", "no", "off", "0", "", NULL };
    for (int i = 0; yes[i]; i++)
        if (!strcasecmp (value, yes[i])) { *out = 1; return 0; }
    for (int i = 0; no[i]; i++)
        if (!strcasecmp (value, no[i])) { *out = 0; return 0; }
    git_fatal ("bad boolean config value '%s' for '%s'", value, key);
    return -1;
}

static int
git_cmd_patch_id (git_context *ctx, WORD_LIST *args)
{
    (void) ctx;
    const char *usage = "git patch-id [--stable | --unstable | --verbatim]";
    int mode = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--unstable")) mode = 1;
        else if (!strcmp (w, "--stable")) mode = 2;
        else if (!strcmp (w, "--verbatim")) mode = 3;
        else return git_usage (usage);
    }

    bgit_repo repo;
    int have_repo = bgit_repo_discover (".", &repo) == 0;
    bgit_config cfg;
    bgit_config_load (&cfg, have_repo ? &repo : NULL,
                      git_overrides, git_n_overrides);
    int configured_verbatim, configured_stable;
    if (git_patch_id_config_bool (&cfg, "patchid.verbatim", 0,
                                  &configured_verbatim) < 0 ||
        git_patch_id_config_bool (&cfg, "patchid.stable", 0,
                                  &configured_stable) < 0) {
        bgit_config_release (&cfg);
        if (have_repo) bgit_repo_release (&repo);
        return GIT_EXIT_FATAL;
    }
    int stable = mode ? mode > 1
                      : configured_verbatim || configured_stable;
    int verbatim = mode ? mode == 3 : configured_verbatim;

    static const char zero_id[] = "0000000000000000000000000000000000000000";
    char id[41], next_id[41];
    memcpy (id, zero_id, 41);
    struct git_patch_id_stream stream;
    git_patch_id_stream_init (&stream);
    char *line = NULL;
    size_t capacity = 0;
    ssize_t got;
    int status = 0;
    clearerr (stdin);
    while ((got = getline (&line, &capacity, stdin)) >= 0) {
        size_t len = (size_t) got;
        if ((!strncmp (line, "commit ", 7) || !strncmp (line, "From ", 5) ||
             strncmp (line, "\\ ", 2)) &&
            git_patch_id_boundary (line, next_id)) {
            if (git_patch_id_finish_file (&stream) < 0) { status = 1; break; }
            git_patch_id_print (&stream, id);
            free (stream.text);
            git_patch_id_stream_init (&stream);
            memcpy (id, next_id, 41);
            continue;
        }
        if (!strncmp (line, "\\ ", 2) && len > 12) {
            if (verbatim && git_patch_id_append (&stream, line, len, 1, 0) < 0)
                { status = 1; break; }
            continue;
        }
        if (!stream.patch_len && strncmp (line, "diff ", 5)) continue;

        if (stream.before == -1) {
            if (!strncmp (line, "GIT binary patch", 16) ||
                !strncmp (line, "Binary files", 12)) {
                stream.binary = 1;
                stream.before = 0;
                if (git_patch_id_append (&stream, stream.pre,
                                         strlen (stream.pre), 1, 0) < 0 ||
                    git_patch_id_append (&stream, stream.post,
                                         strlen (stream.post), 1, 0) < 0 ||
                    (stable && git_patch_id_finish_file (&stream) < 0))
                    { status = 1; break; }
                continue;
            }
            if (!strncmp (line, "index ", 6)) {
                char *between = strstr (line + 6, "..");
                char *after = between ? strchr (between + 2, ' ') : NULL;
                if (!after && len) after = line + len - 1;
                if (between && after) {
                    size_t first = (size_t) (between - (line + 6));
                    size_t second = (size_t) (after - (between + 2));
                    if (first > 64) first = 64;
                    if (second > 64) second = 64;
                    memcpy (stream.pre, line + 6, first); stream.pre[first] = '\0';
                    memcpy (stream.post, between + 2, second);
                    stream.post[second] = '\0';
                }
                continue;
            }
            if (!strncmp (line, "--- ", 4)) stream.before = stream.after = 1;
            else if (!isalpha ((unsigned char) line[0])) {
                if (git_patch_id_finish_file (&stream) < 0)
                    { status = 1; break; }
                git_patch_id_print (&stream, id);
                free (stream.text);
                git_patch_id_stream_init (&stream);
                memcpy (id, zero_id, 41);
                continue;
            }
        }
        if (stream.binary) {
            if (!strncmp (line, "diff ", 5)) {
                stream.binary = 0;
                stream.before = stream.after = -1;
            }
            continue;
        }
        if (stream.before == 0 && stream.after == 0) {
            if (git_patch_id_hunk (line, &stream.before, &stream.after))
                continue;
            if (strncmp (line, "diff ", 5)) {
                if (git_patch_id_finish_file (&stream) < 0)
                    { status = 1; break; }
                git_patch_id_print (&stream, id);
                free (stream.text);
                git_patch_id_stream_init (&stream);
                memcpy (id, zero_id, 41);
                continue;
            }
            if (stable && git_patch_id_finish_file (&stream) < 0)
                { status = 1; break; }
            stream.before = stream.after = -1;
        }
        if (line[0] == '-' || line[0] == ' ') stream.before--;
        if (line[0] == '+' || line[0] == ' ') stream.after--;
        if (git_patch_id_append (&stream, line, len, verbatim, 1) < 0)
            { status = 1; break; }
    }
    if (!status && ferror (stdin)) status = git_fatal ("cannot read standard input");
    if (!status) {
        if (git_patch_id_finish_file (&stream) < 0) status = 1;
        else git_patch_id_print (&stream, id);
    }
    free (stream.text);
    free (line);
    bgit_config_release (&cfg);
    if (have_repo) bgit_repo_release (&repo);
    return status;
}

/* ---- cherry ------------------------------------------------------------ */

/* Which of this side's commits the other side already has, by the name of
   the change rather than the name of the commit: a patch applied over there
   in a commit of its own is the same patch, and git marks it with a minus. */
static int
git_cmd_cherry (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git cherry [-v] [<upstream> [<head> [<limit>]]]";
    int verbose = 0, abbrev = 40;
    const char *names[3] = { NULL, NULL, NULL };
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "--abbrev")) abbrev = 7;
        else if (!strncmp (w, "--abbrev=", 9)) {
            abbrev = atoi (w + 9);
            if (abbrev < 4) abbrev = 4;
            if (abbrev > 40) abbrev = 40;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < 3) names[n_names++] = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    const char *upstream = names[0];
    const char *head = names[1] ? names[1] : "HEAD";
    const char *limit = names[2];
    char followed[4200] = "";
    if (!upstream) {
        /* Nothing named: the branch this one follows, if it follows one. */
        struct git_state state;
        if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
        long ahead = 0, behind = 0;
        const char *branch = state.branch &&
                             !strncmp (state.branch, "refs/heads/", 11)
                             ? state.branch + 11 : NULL;
        int have = branch && git_status_upstream (ctx, &state, branch, followed,
                                                  sizeof followed, &ahead,
                                                  &behind);
        git_state_release (&state);
        if (!have || !*followed) {
            fflush (stdout);
            fprintf (stderr, "Could not find a tracked remote branch, please "
                             "specify <upstream> manually.\n");
            return git_usage (usage);
        }
        upstream = followed;
    }

    char up_id[41], head_id[41], limit_id[41];
    if (git_resolve (ctx, upstream, up_id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, up_id, BGIT_COMMIT, up_id) < 0)
        return git_fatal ("unknown commit %s", upstream);
    if (git_resolve (ctx, head, head_id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, head_id, BGIT_COMMIT, head_id) < 0)
        return git_fatal ("unknown commit %s", head);
    /* Nothing to say when the two are the same commit. */
    if (!strcmp (up_id, head_id)) return 0;
    if (limit && (git_resolve (ctx, limit, limit_id, NULL) < 0 ||
                  bgit_peel_to_type (&ctx->odb, limit_id, BGIT_COMMIT,
                                     limit_id) < 0))
        return git_fatal ("unknown commit %s", limit);

    /* The patches the other side has and this one does not. A merge brings
       in no patch of its own, and is passed over on both sides. */
    const char *theirs[1] = { up_id };
    const char *mine[1] = { head_id };
    char (*over_there)[41] = NULL;
    size_t n_there = 0;
    if (git_collect_commits (ctx, theirs, 1, mine, 1, 0, -1, &over_there,
                             &n_there) < 0)
        return GIT_EXIT_FATAL;
    char (*ids)[41] = calloc (n_there ? n_there : 1, 41);
    size_t n_ids = 0;
    if (!ids) { free (over_there); return GIT_EXIT_FATAL; }
    for (size_t i = 0; i < n_there; i++) {
        char parents[BGIT_MAX_PARENTS][41];
        if (bgit_commit_parents (&ctx->odb, over_there[i], parents,
                                 BGIT_MAX_PARENTS) > 1)
            continue;
        if (git_commit_patch_id (ctx, over_there[i], ids[n_ids]) == 0) n_ids++;
    }
    free (over_there);

    const char *excludes[2] = { up_id, NULL };
    int n_excludes = 1;
    if (limit) excludes[n_excludes++] = limit_id;
    char (*over_here)[41] = NULL;
    size_t n_here = 0;
    if (git_collect_commits (ctx, mine, 1, excludes, n_excludes, 0, -1,
                             &over_here, &n_here) < 0) {
        free (ids);
        return GIT_EXIT_FATAL;
    }
    /* Oldest first, which is the order git lists them in. */
    for (size_t k = 0; k < n_here; k++) {
        const char *sha = over_here[n_here - 1 - k];
        char parents[BGIT_MAX_PARENTS][41];
        if (bgit_commit_parents (&ctx->odb, sha, parents, BGIT_MAX_PARENTS) > 1)
            continue;
        char id[41];
        char sign = '+';
        if (git_commit_patch_id (ctx, sha, id) == 0)
            for (size_t j = 0; j < n_ids; j++)
                if (!memcmp (ids[j], id, 41)) { sign = '-'; break; }
        char shown[41];
        git_abbrev (ctx, sha, abbrev, shown, sizeof shown);
        if (!verbose) {
            printf ("%c %s\n", sign, shown);
            continue;
        }
        struct git_commit commit;
        char subject[4096] = "";
        if (git_commit_read (ctx, sha, &commit) == 0) {
            git_subject (&commit, subject, sizeof subject);
            git_commit_release (&commit);
        }
        printf ("%c %s %s\n", sign, shown, subject);
    }
    free (over_here);
    free (ids);
    return 0;
}

/* ---- blame ------------------------------------------------------------- */

/* Where one line of the file is thought to have come from, until a commit
   is found that changed it. */
struct git_blame_line {
    char commit[41];     /* the commit still suspected of it */
    char *path;          /* what the file was called there */
    long at;             /* which line of that commit's file it is */
    int settled;         /* the suspect changed it: the answer */
    int boundary;        /* and had nothing before it, as git's ^ says */
};

/* The id git shows for a line that is in the working tree and in no commit,
   and the name it puts where an author would go. */
#define GIT_BLAME_WORKTREE "0000000000000000000000000000000000000000"
#define GIT_BLAME_NOT_YET "Not Committed Yet"

/* Is this path in the commit, or at least in the index? git will blame the
   working tree's copy of it if either. */
static int
git_blame_known (git_context *ctx, const char *commit, const char *path)
{
    char spec[8192], id[41];
    if ((size_t) snprintf (spec, sizeof spec, "%s:%s", commit, path) <
        sizeof spec &&
        bgit_rev_parse (&ctx->repo, &ctx->odb, spec, id, NULL) == 0)
        return 1;
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return 0;
    int found = 0;
    for (size_t i = 0; i < state.n_index && !found; i++)
        found = state.index[i].path && !strcmp (state.index[i].path, path);
    git_state_release (&state);
    return found;
}

/* The copy of a path one commit holds, split into lines — or the working
   tree's own copy, which is where a blame with no revision named begins.
   Returns 0, or -1 when there is no such path. */
static int
git_blame_content (git_context *ctx, const char *commit, const char *path,
                   struct git_apply_lines *out)
{
    if (!strcmp (commit, GIT_BLAME_WORKTREE)) {
        char *data = NULL;
        size_t len = 0;
        if (bgit_read_worktree_file (&ctx->repo, path, &data, &len) < 0)
            return -1;
        int rc = git_apply_split (data, len, out);
        free (data);
        return rc;
    }
    char spec[8192];
    if ((size_t) snprintf (spec, sizeof spec, "%s:%s", commit, path) >=
        sizeof spec)
        return -1;
    char id[41];
    if (bgit_rev_parse (&ctx->repo, &ctx->odb, spec, id, NULL) < 0) return -1;
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0) return -1;
    if (type != BGIT_BLOB) { free (data); return -1; }
    int rc = git_apply_split ((const char *) data, len, out);
    free (data);
    return rc;
}

/* What the path was called in the parent, when the change that made this
   commit renamed it. The caller frees the result. */
static char *
git_blame_renamed_from (git_context *ctx, const char *parent,
                        const char *commit, const char *path)
{
    char old_tree[41], new_tree[41];
    if (bgit_commit_tree (&ctx->odb, parent, old_tree) < 0 ||
        bgit_commit_tree (&ctx->odb, commit, new_tree) < 0)
        return NULL;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (bgit_diff_trees (&ctx->odb, old_tree, new_tree, &entries, &n) < 0)
        return NULL;
    struct git_diff_format format;
    git_diff_format_init (&format);
    git_find_renames (ctx, &format, &entries, &n, 0);
    char *from = NULL;
    for (size_t i = 0; i < n; i++)
        if (entries[i].from && !strcmp (entries[i].path, path)) {
            from = strdup (entries[i].from);
            break;
        }
    bgit_diff_free (entries, n);
    return from;
}

/* Lines that the parent has in the same shape pass to it; the rest stay
   with the commit under suspicion. Returns 1 when the parent had the file
   at all. */
static int
git_blame_pass (git_context *ctx, struct git_blame_line *lines, size_t n_lines,
                const char *commit, const char *path, const char *parent,
                const struct git_apply_lines *now, int ignore_ws)
{
    char *from = NULL;
    struct git_apply_lines before;
    if (git_blame_content (ctx, parent, path, &before) < 0) {
        from = git_blame_renamed_from (ctx, parent, commit, path);
        if (!from) return 0;
        if (git_blame_content (ctx, parent, from, &before) < 0) {
            free (from);
            return 0;
        }
    }
    /* The two versions, line by line. */
    char *old_text = NULL, *new_text = NULL;
    size_t old_len = 0, new_len = 0;
    FILE *builder = open_memstream (&old_text, &old_len);
    if (builder) {
        for (size_t i = 0; i < before.n; i++)
            fprintf (builder, "%s\n", before.line[i]);
        fclose (builder);
    }
    builder = open_memstream (&new_text, &new_len);
    if (builder) {
        for (size_t i = 0; i < now->n; i++)
            fprintf (builder, "%s\n", now->line[i]);
        fclose (builder);
    }
    bgit_xdiff_file old_file, new_file;
    bgit_xdiff_load (&old_file, old_text ? old_text : "", old_len);
    bgit_xdiff_load (&new_file, new_text ? new_text : "", new_len);
    bgit_xdiff_result result;
    long *to_parent = calloc (now->n ? now->n : 1, sizeof *to_parent);
    /* git's blame takes the indent heuristic from the diff options, where
       it is on unless turned off. */
    int ok = to_parent &&
             bgit_xdiff_opts (&old_file, &new_file, 0,
                              BGIT_XDIFF_INDENT_HEURISTIC |
                              BGIT_XDIFF_TRIM_TAIL | ignore_ws, &result) == 0;
    if (ok) {
        size_t oi = 0;
        for (size_t ni = 0; ni < now->n; ni++) {
            if (result.new_changed[ni]) { to_parent[ni] = -1; continue; }
            while (oi < before.n && result.old_changed[oi]) oi++;
            to_parent[ni] = (long) oi++;
        }
        for (size_t i = 0; i < n_lines; i++) {
            struct git_blame_line *line = &lines[i];
            if (line->settled || strcmp (line->commit, commit)) continue;
            if (strcmp (line->path, path)) continue;
            if (line->at < 0 || (size_t) line->at >= now->n) continue;
            long there = to_parent[line->at];
            if (there < 0) continue;      /* this commit changed it */
            memcpy (line->commit, parent, 41);
            free (line->path);
            line->path = strdup (from ? from : path);
            line->at = there;
        }
        bgit_xdiff_result_release (&result);
    }
    free (to_parent);
    bgit_xdiff_release (&old_file);
    bgit_xdiff_release (&new_file);
    free (old_text);
    free (new_text);
    git_apply_lines_release (&before);
    free (from);
    return 1;
}

static int
git_cmd_blame (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git blame [-s] [-l] [-c] [-w] "
                        "[-L <start>[,<end>]] [<rev>] [--] <file>";
    int short_form = 0, long_ids = 0, no_more = 0, annotating = 0;
    int ignore_ws = 0;
    long first = 1, last = -1;
    const char *path = NULL, *rev = NULL;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "-s")) short_form = 1;
        else if (!no_more && !strcmp (w, "-l")) long_ids = 1;
        /* -c is the older layout, which is all `git annotate` is. */
        else if (!no_more && !strcmp (w, "-c")) annotating = 1;
        /* Whose line it is, overlooking whitespace: a line that only had
           its spacing changed stays with the commit that wrote it. This is
           the only one of the whitespace options git's blame takes. */
        else if (!no_more && !strcmp (w, "-w"))
            ignore_ws |= BGIT_XDIFF_IGNORE_WS;
        else if (!no_more && !strcmp (w, "-L") && p->next) {
            /* Without an end, the range runs to the end of the file. */
            const char *range = (p = p->next)->word->word;
            first = atol (range);
            const char *comma = strchr (range, ',');
            last = comma ? atol (comma + 1) : -1;
        }
        else if (!no_more && !strncmp (w, "-L", 2) && w[2]) {
            first = atol (w + 2);
            const char *comma = strchr (w + 2, ',');
            last = comma ? atol (comma + 1) : -1;
        }
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (!path) path = w;
        else if (!rev) { rev = path; path = w; }
        else return git_usage (usage);
    }
    if (!path) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char start[41], head[41] = "";
    if (git_resolve (ctx, rev ? rev : "HEAD", head, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, head, BGIT_COMMIT, head) < 0)
        return rev ? git_fatal_ambiguous (rev)
                   : git_fatal ("no such ref: HEAD");
    memcpy (start, head, 41);

    /* With no revision named, the file to blame is the one in the working
       tree, and the lines of it that are in no commit are held against no
       commit — which is what the id of nothing but zeros means. */
    if (!rev && ctx->repo.work_tree) {
        /* git asks whether it has ever heard of the path before it asks
           whether there is a file there. */
        if (!git_blame_known (ctx, head, path))
            return git_fatal ("no such path '%s' in HEAD", path);
        char full[4096];
        struct stat st;
        if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path) >=
            (int) sizeof full || lstat (full, &st) < 0)
            return git_fatal ("Cannot lstat '%s': %s", path, strerror (errno));
        memcpy (start, GIT_BLAME_WORKTREE, 41);
    }

    struct git_apply_lines text;
    if (git_blame_content (ctx, start, path, &text) < 0)
        return git_fatal ("no such path '%s' in %s", path, rev ? rev : "HEAD");

    struct git_blame_line *lines = calloc (text.n ? text.n : 1, sizeof *lines);
    if (!lines) { git_apply_lines_release (&text); return GIT_EXIT_FATAL; }
    for (size_t i = 0; i < text.n; i++) {
        memcpy (lines[i].commit, start, 41);
        lines[i].path = strdup (path);
        lines[i].at = (long) i;
        if (!lines[i].path) {
            for (size_t j = 0; j < i; j++) free (lines[j].path);
            free (lines);
            git_apply_lines_release (&text);
            return GIT_EXIT_FATAL;
        }
    }

    /* Take the newest suspect each time round, so that a line is held
       against the commits that could have changed it in order. */
    for (;;) {
        long long newest = -1;
        char suspect[41] = "";
        const char *suspect_path = NULL;
        for (size_t i = 0; i < text.n; i++) {
            if (lines[i].settled) continue;
            long long when =
                !strcmp (lines[i].commit, GIT_BLAME_WORKTREE)
                ? ((long long) 1 << 62) : git_commit_date (ctx, lines[i].commit);
            if (when > newest) {
                newest = when;
                memcpy (suspect, lines[i].commit, 41);
                suspect_path = lines[i].path;
            }
        }
        if (!*suspect) break;
        char held_path[4096];
        snprintf (held_path, sizeof held_path, "%s", suspect_path);
        struct git_apply_lines now;
        if (git_blame_content (ctx, suspect, held_path, &now) < 0) {
            for (size_t i = 0; i < text.n; i++)
                if (!lines[i].settled && !strcmp (lines[i].commit, suspect))
                    lines[i].settled = 1;
            continue;
        }
        char parents[BGIT_MAX_PARENTS][41];
        int n_parents;
        if (!strcmp (suspect, GIT_BLAME_WORKTREE)) {
            memcpy (parents[0], head, 41);
            n_parents = 1;
        } else
            n_parents = bgit_commit_parents (&ctx->odb, suspect, parents,
                                             BGIT_MAX_PARENTS);
        for (int i = 0; i < n_parents; i++)
            git_blame_pass (ctx, lines, text.n, suspect, held_path,
                            parents[i], &now, ignore_ws);
        /* Whatever is still held against it, it is answerable for — and a
           commit with nothing before it at all is the one git marks. */
        for (size_t i = 0; i < text.n; i++)
            if (!lines[i].settled && !strcmp (lines[i].commit, suspect) &&
                !strcmp (lines[i].path, held_path)) {
                lines[i].settled = 1;
                lines[i].boundary = n_parents <= 0;
            }
        git_apply_lines_release (&now);
    }

    /* What each of them says about itself, and how wide the columns are. */
    if (last < 0 || (size_t) last > text.n) last = (long) text.n;
    if (first < 1) first = 1;
    size_t name_width = 0, number_width = 1, path_width = 0;
    int show_path = 0;
    for (long i = first; i <= last; i++) {
        struct git_commit commit;
        if (!strcmp (lines[i - 1].commit, GIT_BLAME_WORKTREE)) {
            size_t len = strlen (GIT_BLAME_NOT_YET);
            if (len > name_width) name_width = len;
        } else if (git_commit_read (ctx, lines[i - 1].commit, &commit) == 0) {
            size_t len = strlen (commit.author_name);
            if (len > name_width) name_width = len;
            git_commit_release (&commit);
        }
        if (strcmp (lines[i - 1].path, path)) show_path = 1;
        size_t len = strlen (lines[i - 1].path);
        if (len > path_width) path_width = len;
        size_t digits = 1;
        for (long n = i; n >= 10; n /= 10) digits++;
        if (digits > number_width) number_width = digits;
    }
    for (long i = first; i <= last; i++) {
        struct git_blame_line *line = &lines[i - 1];
        int not_yet = !strcmp (line->commit, GIT_BLAME_WORKTREE);
        char id[64];
        if (long_ids)
            /* The caret takes the place of a digit, so the column stays
               as wide as an id. */
            snprintf (id, sizeof id, "%s%.*s", line->boundary ? "^" : "",
                      line->boundary ? 39 : 40, line->commit);
        else {
            char abbreviated[41];
            /* Nothing but zeros stands for no commit at all, and there is
               nothing to look up: it is shortened where it stands. */
            if (not_yet)
                snprintf (abbreviated, sizeof abbreviated, "%.*s", 8,
                          line->commit);
            else
                git_abbrev (ctx, line->commit, line->boundary ? 7 : 8,
                            abbreviated, sizeof abbreviated);
            snprintf (id, sizeof id, "%s%s", line->boundary ? "^" : "",
                      abbreviated);
        }
        if (short_form) {
            if (show_path)
                printf ("%s %-*s %*ld) %s\n", id, (int) path_width, line->path,
                        (int) number_width, i, text.line[i - 1]);
            else printf ("%s %*ld) %s\n", id, (int) number_width, i,
                         text.line[i - 1]);
            continue;
        }
        struct git_commit commit;
        char who[1024] = "", when[128] = "";
        if (not_yet) {
            /* No commit wrote it, and the time it says is now. */
            snprintf (who, sizeof who, "%s", GIT_BLAME_NOT_YET);
            time_t moment = time (NULL);
            struct tm local;
            long offset = 0;
            if (localtime_r (&moment, &local)) offset = local.tm_gmtoff;
            long away = offset < 0 ? -offset : offset;
            char raw[64];
            snprintf (raw, sizeof raw, "%lld %c%02ld%02ld", (long long) moment,
                      offset < 0 ? '-' : '+', away / 3600, (away % 3600) / 60);
            git_format_date_mode (raw, GIT_DATE_ISO, when, sizeof when);
        } else if (git_commit_read (ctx, line->commit, &commit) == 0) {
            snprintf (who, sizeof who, "%s", commit.author_name);
            git_format_date_mode (commit.author_date, GIT_DATE_ISO, when,
                                  sizeof when);
            git_commit_release (&commit);
        }
        /* The older layout sets the parts apart with tabs, lets each stand
           at its own width, and writes a boundary commit's id whole rather
           than marking it with a caret. */
        if (annotating) {
            if (line->boundary) {
                char abbreviated[41];
                git_abbrev (ctx, line->commit, long_ids ? 40 : 8, abbreviated,
                            sizeof abbreviated);
                snprintf (id, sizeof id, "%s", abbreviated);
            }
            if (show_path)
                printf ("%s\t(%10s\t%10s\t%s\t%ld)%s\n", id, who, when,
                        line->path, i, text.line[i - 1]);
            else printf ("%s\t(%10s\t%10s\t%ld)%s\n", id, who, when, i,
                         text.line[i - 1]);
            continue;
        }
        /* Where the file has been called something else, git says so
           between the id and the author. */
        if (show_path)
            printf ("%s %-*s (%-*s %s %*ld) %s\n", id, (int) path_width,
                    line->path, (int) name_width, who, when,
                    (int) number_width, i, text.line[i - 1]);
        else
            printf ("%s (%-*s %s %*ld) %s\n", id, (int) name_width, who, when,
                    (int) number_width, i, text.line[i - 1]);
    }
    for (size_t i = 0; i < text.n; i++) free (lines[i].path);
    free (lines);
    git_apply_lines_release (&text);
    return 0;
}

/* ---- count-objects ----------------------------------------------------- */

/* A size in kibibytes as git says it out loud, which it does by turning
   it back into bytes first. */
static void
git_count_human (unsigned long long kb, char *out, size_t outsz)
{
    unsigned long long bytes = kb;
    if (bytes > 1024ULL * 1024 * 1024)
        snprintf (out, outsz, "%llu.%02llu GiB", bytes >> 30,
                  (bytes & ((1ULL << 30) - 1)) / 10737419);
    else if (bytes > 1024ULL * 1024)
        snprintf (out, outsz, "%llu.%02llu MiB", bytes >> 20,
                  (bytes & ((1ULL << 20) - 1)) / 10486);
    else if (bytes > 1024)
        snprintf (out, outsz, "%llu.%02llu KiB", bytes >> 10,
                  (bytes & 1023) / 10);
    else snprintf (out, outsz, "%llu byte%s", bytes, bytes == 1 ? "" : "s");
}

/* What one pack index says it holds: the last of its fanout counters. */
static unsigned long
git_count_pack_objects (const char *path)
{
    FILE *f = fopen (path, "rb");
    if (!f) return 0;
    unsigned char head[8];
    if (fread (head, 1, 8, f) != 8) { fclose (f); return 0; }
    unsigned char fanout[4];
    long at = head[0] == 0xff && head[1] == 't' && head[2] == 'O' &&
              head[3] == 'c' ? 8 + 255 * 4 : 255 * 4;
    if (fseek (f, at, SEEK_SET) != 0 || fread (fanout, 1, 4, f) != 4) {
        fclose (f);
        return 0;
    }
    fclose (f);
    return ((unsigned long) fanout[0] << 24) | ((unsigned long) fanout[1] << 16) |
           ((unsigned long) fanout[2] << 8) | fanout[3];
}

/* `git annotate` is `git blame -c`: the same work in the older layout. */
static int
git_cmd_annotate (git_context *ctx, WORD_LIST *args)
{
    WORD_LIST *older = make_word_list (make_word ("-c"), args);
    int rc = git_cmd_blame (ctx, older);
    older->next = NULL;
    dispose_words (older);
    return rc;
}

static int
git_cmd_count_objects (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git count-objects [-v] [-H | --human-readable]";
    int verbose = 0, human = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "-H") || !strcmp (w, "--human-readable")) human = 1;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* The loose objects, in the store this repository writes to. */
    const char *objects = ctx->odb.n_object_dirs ? ctx->odb.object_dirs[0] : NULL;
    unsigned long long count = 0, size = 0, garbage = 0, garbage_size = 0;
    unsigned long long packable = 0;
    if (objects) {
        DIR *top = opendir (objects);
        if (top) {
            struct dirent *entry;
            while ((entry = readdir (top))) {
                if (strlen (entry->d_name) != 2 ||
                    !isxdigit ((unsigned char) entry->d_name[0]) ||
                    !isxdigit ((unsigned char) entry->d_name[1]))
                    continue;
                char dir[4096];
                if ((size_t) snprintf (dir, sizeof dir, "%s/%s", objects,
                                       entry->d_name) >= sizeof dir)
                    continue;
                DIR *inner = opendir (dir);
                if (!inner) continue;
                struct dirent *one;
                while ((one = readdir (inner))) {
                    if (one->d_name[0] == '.') continue;
                    char path[4096];
                    if ((size_t) snprintf (path, sizeof path, "%s/%s", dir,
                                           one->d_name) >= sizeof path)
                        continue;
                    struct stat st;
                    if (lstat (path, &st) < 0 || !S_ISREG (st.st_mode)) continue;
                    unsigned long long kb =
                        (unsigned long long) st.st_blocks * 512;
                    int named = strlen (one->d_name) == 38;
                    for (const char *c = one->d_name; named && *c; c++)
                        if (!isxdigit ((unsigned char) *c)) named = 0;
                    if (named) {
                        count++;
                        size += kb;
                        char sha[41];
                        sha[0] = entry->d_name[0];
                        sha[1] = entry->d_name[1];
                        memcpy (sha + 2, one->d_name, 38);
                        sha[40] = '\0';
                        /* A loose object a pack already holds is one prune
                           could take away without losing anything. */
                        if (bgit_odb_packed (&ctx->odb, sha)) packable++;
                    } else { garbage++; garbage_size += kb; }
                }
                closedir (inner);
            }
            closedir (top);
        }
    }

    /* And the packs beside them. */
    unsigned long long packs = 0, in_pack = 0, pack_size = 0;
    char pack_dir[4096] = "";
    if (objects &&
        (size_t) snprintf (pack_dir, sizeof pack_dir, "%s/pack",
                           objects) < sizeof pack_dir) {
        DIR *handle = opendir (pack_dir);
        if (handle) {
            struct dirent *entry;
            while ((entry = readdir (handle))) {
                size_t len = strlen (entry->d_name);
                if (len < 5 || strcmp (entry->d_name + len - 4, ".idx")) continue;
                char path[4096];
                if ((size_t) snprintf (path, sizeof path, "%s/%s", pack_dir,
                                       entry->d_name) >= sizeof path)
                    continue;
                packs++;
                in_pack += git_count_pack_objects (path);
                struct stat index_st;
                /* git counts the index beside the pack it belongs to. */
                if (lstat (path, &index_st) == 0)
                    pack_size += (unsigned long long) index_st.st_size;
                char pack[4096];
                snprintf (pack, sizeof pack, "%.*s.pack", (int) (len - 4),
                          entry->d_name);
                char full[4096];
                if ((size_t) snprintf (full, sizeof full, "%s/%s", pack_dir,
                                       pack) >= sizeof full)
                    continue;
                struct stat st;
                /* A pack is counted by what it says it is, not by what it
                   takes up, which is what git counts here. */
                if (lstat (full, &st) == 0)
                    pack_size += (unsigned long long) st.st_size;
            }
            closedir (handle);
        }
    }

    if (!verbose) {
        if (human) {
            char shown[64];
            git_count_human (size, shown, sizeof shown);
            printf ("%llu objects, %s\n", count, shown);
        } else printf ("%llu objects, %llu kilobytes\n", count, size / 1024);
        return 0;
    }
    char size_shown[64], pack_shown[64], garbage_shown[64];
    git_count_human (size, size_shown, sizeof size_shown);
    git_count_human (pack_size, pack_shown, sizeof pack_shown);
    git_count_human (garbage_size, garbage_shown, sizeof garbage_shown);
    printf ("count: %llu\n", count);
    if (human) printf ("size: %s\n", size_shown);
    else printf ("size: %llu\n", size / 1024);
    printf ("in-pack: %llu\n", in_pack);
    printf ("packs: %llu\n", packs);
    if (human) printf ("size-pack: %s\n", pack_shown);
    else printf ("size-pack: %llu\n", pack_size / 1024);
    printf ("prune-packable: %llu\n", packable);
    printf ("garbage: %llu\n", garbage);
    if (human) printf ("size-garbage: %s\n", garbage_shown);
    else printf ("size-garbage: %llu\n", garbage_size / 1024);
    return 0;
}

/* ---- fsck --------------------------------------------------------------- */

/* What fsck comes to know about one object: what it is, whether anything at
   all points at it, and whether a root reaches it. The array is sorted by
   id, so a link is looked up by bisection. */
struct git_fsck_object {
    char sha[41];
    unsigned char type;        /* enum bgit_type */
    unsigned char present;     /* readable, and named by what it holds */
    unsigned char used;        /* something points at it */
    unsigned char reachable;   /* a root reaches it */
};

/* Referenced by something reachable but not in the store. */
struct git_fsck_absent {
    char sha[41];
    unsigned char type;        /* what the reference expected it to be */
};

struct git_fsck {
    git_context *ctx;
    struct git_fsck_object *objects;
    size_t n;
    struct git_fsck_absent *absent;
    size_t n_absent, cap_absent;
    int show_unreachable, show_dangling, show_roots, show_tags;
    int verbose, connectivity_only;
    int errors;                /* git's bitmask: 1 an object, 2 reachability */
};

/* git names a loose object by the path it opened, which inside a working
   tree is the relative one. */
static const char *
git_fsck_shown_path (const struct git_fsck *f, const char *path)
{
    const char *root = f->ctx->repo.work_tree;
    if (!root || !*root) return path;
    size_t n = strlen (root);
    while (n && root[n - 1] == '/') n--;
    if (!strncmp (path, root, n) && path[n] == '/') return path + n + 1;
    return path;
}

/* What git's decompression layer says before fsck says anything: the
   message zlib gives for the object's first bytes, then the file it could
   not unpack. */
static void
git_fsck_unpack_error (struct git_fsck *f, const char *path)
{
    int fd = open (path, O_RDONLY);
    unsigned char raw[64], out[64];
    ssize_t got = fd >= 0 ? read (fd, raw, sizeof raw) : -1;
    if (fd >= 0) close (fd);
    if (got > 0) {
        z_stream stream;
        memset (&stream, 0, sizeof stream);
        stream.next_in = raw;
        stream.avail_in = (uInt) got;
        stream.next_out = out;
        stream.avail_out = sizeof out;
        int rc = inflateInit (&stream);
        if (rc == Z_OK) rc = inflate (&stream, Z_SYNC_FLUSH);
        if (rc != Z_OK && rc != Z_STREAM_END && rc != Z_BUF_ERROR)
            fprintf (stderr, "error: inflate: data stream error (%s)\n",
                     stream.msg ? stream.msg : "unknown error");
        inflateEnd (&stream);
    }
    fprintf (stderr, "error: unable to unpack header of %s\n",
             git_fsck_shown_path (f, path));
}

static long
git_fsck_find (const struct git_fsck *f, const char *sha)
{
    size_t low = 0, high = f->n;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        int order = strcmp (f->objects[mid].sha, sha);
        if (order < 0) low = mid + 1;
        else if (order > 0) high = mid;
        else return (long) mid;
    }
    return -1;
}

/* Every object one object points at: a commit's tree and its parents, a
   tag's object, a tree's entries. A gitlink names a commit another
   repository keeps, so it is not one of ours to miss. */
typedef void (*git_fsck_link_fn) (struct git_fsck *f, void *arg,
                                  const char *child, enum bgit_type expected);

static void
git_fsck_links (struct git_fsck *f, enum bgit_type type,
                const unsigned char *data, size_t len,
                git_fsck_link_fn fn, void *arg)
{
    if (type == BGIT_COMMIT || type == BGIT_TAG) {
        const char *text = (const char *) data;
        size_t at = 0;
        enum bgit_type points_to = type == BGIT_TAG ? BGIT_COMMIT : BGIT_TREE;
        while (at < len) {
            size_t end = at;
            while (end < len && text[end] != '\n') end++;
            size_t line = end - at;
            if (line == 0) break;          /* the message starts here */
            if (type == BGIT_TAG && line > 5 && !strncmp (text + at, "type ", 5)) {
                char name[16];
                size_t n = line - 5 < sizeof name - 1 ? line - 5 : sizeof name - 1;
                memcpy (name, text + at + 5, n);
                name[n] = '\0';
                if (!strcmp (name, "tree")) points_to = BGIT_TREE;
                else if (!strcmp (name, "blob")) points_to = BGIT_BLOB;
                else if (!strcmp (name, "tag")) points_to = BGIT_TAG;
            }
            at = end + 1;
        }
        at = 0;
        while (at < len) {
            size_t end = at;
            while (end < len && text[end] != '\n') end++;
            size_t line = end - at;
            if (line == 0) break;
            const char *label = type == BGIT_TAG ? "object " : "tree ";
            size_t label_len = strlen (label);
            if (line == label_len + 40 && !strncmp (text + at, label, label_len)) {
                char sha[41];
                memcpy (sha, text + at + label_len, 40);
                sha[40] = '\0';
                if (bgit_all_hex (sha))
                    fn (f, arg, sha, type == BGIT_TAG ? points_to : BGIT_TREE);
            } else if (type == BGIT_COMMIT && line == 47 &&
                       !strncmp (text + at, "parent ", 7)) {
                char sha[41];
                memcpy (sha, text + at + 7, 40);
                sha[40] = '\0';
                if (bgit_all_hex (sha)) fn (f, arg, sha, BGIT_COMMIT);
            }
            at = end + 1;
        }
        return;
    }
    if (type != BGIT_TREE) return;
    size_t at = 0;
    while (at < len) {
        size_t space = at;
        while (space < len && data[space] != ' ') space++;
        if (space >= len) return;
        char mode[8];
        size_t mode_len = space - at;
        if (mode_len >= sizeof mode) return;
        memcpy (mode, data + at, mode_len);
        mode[mode_len] = '\0';
        size_t nul = space;
        while (nul < len && data[nul] != '\0') nul++;
        if (nul + 21 > len) return;
        char sha[41];
        bgit_sha_to_hex (data + nul + 1, sha);
        unsigned long value = strtoul (mode, NULL, 8);
        if ((value & 0170000) == 0160000) {
            /* a gitlink */
        } else if ((value & 0170000) == 0040000 || !strcmp (mode, "40000")) {
            fn (f, arg, sha, BGIT_TREE);
        } else {
            fn (f, arg, sha, BGIT_BLOB);
        }
        at = nul + 21;
    }
}

/* Pass one marks what is pointed at, whoever points at it. */
static void
git_fsck_mark_used (struct git_fsck *f, void *arg, const char *child,
                    enum bgit_type expected)
{
    (void) arg;
    (void) expected;
    long at = git_fsck_find (f, child);
    if (at >= 0) f->objects[at].used = 1;
}

/* An object's own checks: that it is named by what it holds, and that a
   commit says the things a commit has to say. */
static void
git_fsck_check_object (struct git_fsck *f, struct git_fsck_object *o)
{
    enum bgit_type type = BGIT_UNKNOWN;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&f->ctx->odb, o->sha, &type, &data, &len) < 0) {
        if (!f->connectivity_only) {
            char path[4096];
            if (bgit_odb_loose_path (&f->ctx->odb, o->sha, path, sizeof path) == 0) {
                git_fsck_unpack_error (f, path);
                fprintf (stderr, "error: %s: object corrupt or missing: %s\n",
                         o->sha, git_fsck_shown_path (f, path));
            }
            else
                fprintf (stderr, "error: %s: object corrupt or missing\n", o->sha);
            f->errors |= 1;
        }
        o->present = f->connectivity_only ? 1 : 0;
        return;
    }
    o->type = (unsigned char) type;
    o->present = 1;
    if (f->verbose)
        fprintf (stderr, "Checking %s %s\n", bgit_type_name (type), o->sha);

    if (!f->connectivity_only) {
        char header[64];
        int header_len = snprintf (header, sizeof header, "%s %zu",
                                   bgit_type_name (type), len);
        unsigned char *whole = malloc ((size_t) header_len + 1 + len);
        if (whole) {
            memcpy (whole, header, (size_t) header_len + 1);
            if (len) memcpy (whole + header_len + 1, data, len);
            unsigned char digest[20];
            char hex[41];
            bgit_sha1 (whole, (size_t) header_len + 1 + len, digest);
            bgit_sha_to_hex (digest, hex);
            free (whole);
            char path[4096];
            if (strcmp (hex, o->sha) != 0 &&
                bgit_odb_loose_path (&f->ctx->odb, o->sha, path,
                                     sizeof path) == 0) {
                fprintf (stderr,
                         "error: %s: hash-path mismatch, found at: %s\n",
                         hex, git_fsck_shown_path (f, path));
                f->errors |= 1;
                o->present = 0;
                free (data);
                return;
            }
        }
        if (type == BGIT_COMMIT) {
            /* git reads a commit's header from the top, the tree first. One
               that does not start that way is not a commit it can parse, and
               it says that rather than naming the field that is missing. */
            int parsed = len > 45 && !memcmp (data, "tree ", 5) &&
                         data[45] == '\n';
            if (parsed) {
                char tree[41];
                memcpy (tree, data + 5, 40);
                tree[40] = '\0';
                parsed = bgit_all_hex (tree);
            }
            if (!parsed) {
                char path[4096];
                fprintf (stderr, "error: bogus commit object %s\n", o->sha);
                if (bgit_odb_loose_path (&f->ctx->odb, o->sha, path,
                                         sizeof path) == 0)
                    fprintf (stderr, "error: %s: object could not be parsed: "
                                     "%s\n", o->sha,
                             git_fsck_shown_path (f, path));
                else
                    fprintf (stderr, "error: %s: object could not be parsed\n",
                             o->sha);
                f->errors |= 1;
                o->present = 0;
                free (data);
                return;
            }
            static const struct { const char *label, *id; } wanted[] = {
                { "author ", "missingAuthor" },
                { "committer ", "missingCommitter" },
            };
            for (size_t i = 0; i < sizeof wanted / sizeof wanted[0]; i++) {
                size_t label_len = strlen (wanted[i].label);
                int found = 0;
                size_t at = 0;
                while (at < len) {
                    size_t end = at;
                    while (end < len && data[end] != '\n') end++;
                    if (end == at) break;
                    if (end - at > label_len &&
                        !strncmp ((const char *) data + at, wanted[i].label,
                                  label_len)) {
                        found = 1;
                        break;
                    }
                    at = end + 1;
                }
                if (!found) {
                    char name[32];
                    snprintf (name, sizeof name, "%.*s",
                              (int) label_len - 1, wanted[i].label);
                    fprintf (stderr,
                             "error in commit %s: %s: invalid format - "
                             "expected '%s' line\n", o->sha, wanted[i].id, name);
                    f->errors |= 1;
                    /* git stops at the first thing wrong with an object: it
                       neither calls it a root nor follows what it points
                       at, though the object itself is still there. */
                    free (data);
                    return;
                }
            }
        }
    }
    if (f->show_roots && type == BGIT_COMMIT) {
        int parents = 0;
        size_t seek = 0;
        while (seek < len) {
            size_t end = seek;
            while (end < len && data[end] != '\n') end++;
            if (end == seek) break;
            if (end - seek > 7 &&
                !strncmp ((const char *) data + seek, "parent ", 7))
                parents++;
            seek = end + 1;
        }
        if (!parents) printf ("root %s\n", o->sha);
    }
    git_fsck_links (f, type, data, len, git_fsck_mark_used, NULL);
    free (data);
}

/* Pass two walks out from the roots. What it cannot follow it says so
   about, once, in git's two-line wording. */
struct git_fsck_walk {
    char (*pending)[41];
    size_t n, cap;
};

/* An object referenced but not in the store, remembered once. Returns the
   entry, or NULL when there is no memory for another. */
static struct git_fsck_absent *
git_fsck_absent_note (struct git_fsck *f, const char *sha, enum bgit_type type,
                      int *first)
{
    *first = 0;
    for (size_t i = 0; i < f->n_absent; i++)
        if (!strcmp (f->absent[i].sha, sha)) {
            if (f->absent[i].type == BGIT_UNKNOWN)
                f->absent[i].type = (unsigned char) type;
            return &f->absent[i];
        }
    if (f->n_absent == f->cap_absent) {
        size_t next = f->cap_absent ? f->cap_absent * 2 : 16;
        struct git_fsck_absent *grown =
            realloc (f->absent, next * sizeof *grown);
        if (!grown) return NULL;
        f->absent = grown;
        f->cap_absent = next;
    }
    memcpy (f->absent[f->n_absent].sha, sha, 41);
    f->absent[f->n_absent].type = (unsigned char) type;
    f->errors |= 2;
    *first = 1;
    return &f->absent[f->n_absent++];
}

static void
git_fsck_push (struct git_fsck *f, struct git_fsck_walk *walk, const char *sha)
{
    long at = git_fsck_find (f, sha);
    /* A head that names an object the store does not have is where fsck
       first hears of it, and it is missing rather than linked to badly. */
    if (at < 0) {
        int first;
        git_fsck_absent_note (f, sha, BGIT_UNKNOWN, &first);
        return;
    }
    if (!f->objects[at].present || f->objects[at].reachable) return;
    if (walk->n == walk->cap) {
        size_t next = walk->cap ? walk->cap * 2 : 64;
        char (*grown)[41] = realloc (walk->pending, next * sizeof *grown);
        if (!grown) return;
        walk->pending = grown;
        walk->cap = next;
    }
    memcpy (walk->pending[walk->n++], sha, 41);
}

/* A link out of a reachable object: followed if it is there, reported if
   it is not. */
struct git_fsck_from {
    struct git_fsck_walk *walk;
    const char *sha;
    enum bgit_type type;
};

static void
git_fsck_follow (struct git_fsck *f, void *arg, const char *child,
                 enum bgit_type expected)
{
    struct git_fsck_from *from = arg;
    long at = git_fsck_find (f, child);
    if (at >= 0 && f->objects[at].present) {
        git_fsck_push (f, from->walk, child);
        return;
    }
    /* An object whose file is there but unreadable has been complained
       about already: git calls it missing without calling the link broken,
       and so is one a head named before anything pointed at it. */
    int first = 0;
    if (!git_fsck_absent_note (f, child, expected, &first)) return;
    if (first && at < 0) {
        printf ("broken link from %7s %s\n", bgit_type_name (from->type),
                from->sha);
        printf ("              to %7s %s\n", bgit_type_name (expected), child);
    }
}

static void
git_fsck_reach (struct git_fsck *f, struct git_fsck_walk *walk)
{
    while (walk->n) {
        char sha[41];
        memcpy (sha, walk->pending[--walk->n], 41);
        long at = git_fsck_find (f, sha);
        if (at < 0 || !f->objects[at].present || f->objects[at].reachable)
            continue;
        f->objects[at].reachable = 1;
        f->objects[at].used = 1;
        if (f->verbose) fprintf (stderr, "Checking %s\n", sha);
        enum bgit_type type = BGIT_UNKNOWN;
        unsigned char *data = NULL;
        size_t len = 0;
        if (bgit_odb_read (&f->ctx->odb, sha, &type, &data, &len) < 0) continue;
        struct git_fsck_from from = { walk, f->objects[at].sha, type };
        git_fsck_links (f, type, data, len, git_fsck_follow, &from);
        free (data);
    }
}

/* Every reflog under the git directory, whatever it is a log of. */
static void
git_fsck_reflog_roots (struct git_fsck *f, struct git_fsck_walk *walk,
                       const char *dir)
{
    DIR *handle = opendir (dir);
    if (!handle) return;
    struct dirent *entry;
    while ((entry = readdir (handle))) {
        if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, ".."))
            continue;
        char path[4096];
        if ((size_t) snprintf (path, sizeof path, "%s/%s", dir,
                               entry->d_name) >= sizeof path)
            continue;
        struct stat st;
        if (lstat (path, &st) < 0) continue;
        if (S_ISDIR (st.st_mode)) {
            git_fsck_reflog_roots (f, walk, path);
            continue;
        }
        FILE *log = fopen (path, "r");
        if (!log) continue;
        char line[8192];
        while (fgets (line, sizeof line, log)) {
            if (strlen (line) < 82) continue;
            char old_sha[41], new_sha[41];
            memcpy (old_sha, line, 40);
            old_sha[40] = '\0';
            memcpy (new_sha, line + 41, 40);
            new_sha[40] = '\0';
            if (!bgit_all_hex (old_sha) || !bgit_all_hex (new_sha)) continue;
            if (f->verbose)
                fprintf (stderr, "Checking reflog %s->%s\n", old_sha, new_sha);
            static const char zeros[41] =
                "0000000000000000000000000000000000000000";
            if (strcmp (old_sha, zeros)) git_fsck_push (f, walk, old_sha);
            if (strcmp (new_sha, zeros)) git_fsck_push (f, walk, new_sha);
        }
        fclose (log);
    }
    closedir (handle);
}

/* The store's objects, in a list fsck and prune can look one up in.
   Returns 0, or -1 with git's wording. */
static int
git_fsck_collect (struct git_fsck *f)
{
    char (*names)[41] = NULL;
    size_t n = 0;
    if (bgit_odb_list (&f->ctx->odb, &names, &n) < 0) {
        fflush (stdout);
        fprintf (stderr, "fatal: out of memory\n");
        return -1;
    }
    f->objects = calloc (n ? n : 1, sizeof *f->objects);
    if (!f->objects) {
        free (names);
        fflush (stdout);
        fprintf (stderr, "fatal: out of memory\n");
        return -1;
    }
    f->n = n;
    for (size_t i = 0; i < n; i++) {
        memcpy (f->objects[i].sha, names[i], 41);
        f->objects[i].type = BGIT_UNKNOWN;
    }
    free (names);
    return 0;
}

/* The heads a walk starts from: every ref, HEAD, what the index holds, and
   unless told otherwise the reflogs. WITH_UNDO adds the sides of a conflict
   the index kept, which fsck counts as held and prune does not. NOTICES
   lets fsck say what it says about a repository with no commit in it. */
static void
git_fsck_heads (struct git_fsck *f, struct git_fsck_walk *walk, int reflogs,
                int with_undo, int notices)
{
    git_context *ctx = f->ctx;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    int have_refs = 0;
    if (bgit_refs_list (&ctx->repo, "", &refs, &n_refs) == 0) {
        have_refs = n_refs > 0;
        for (size_t i = 0; i < n_refs; i++)
            git_fsck_push (f, walk, refs[i].sha);
        bgit_refs_free (refs, n_refs);
    }
    char head[41];
    if (bgit_ref_resolve (&ctx->repo, "HEAD", head, NULL) == 0 &&
        bgit_all_hex (head)) {
        git_fsck_push (f, walk, head);
        have_refs = 1;
    } else if (notices) {
        char *target = NULL;
        if (bgit_symref_read (&ctx->repo, "HEAD", &target) == 0 && target) {
            const char *shown = !strncmp (target, "refs/heads/", 11)
                                    ? target + 11 : target;
            fprintf (stderr, "notice: HEAD points to an unborn branch (%s)\n",
                     shown);
            free (target);
        }
    }
    if (notices && !have_refs) fprintf (stderr, "notice: No default references\n");

    char index_path[4096];
    struct stat index_st;
    if (git_index_path (ctx, index_path, sizeof index_path) == 0 &&
        stat (index_path, &index_st) == 0) {
        bgit_index_entry *entries = NULL;
        size_t n_entries = 0;
        if (bgit_index_read (index_path, &entries, &n_entries) == 0) {
            for (size_t i = 0; i < n_entries; i++) {
                char sha[41];
                bgit_sha_to_hex (entries[i].sha, sha);
                git_fsck_push (f, walk, sha);
            }
            bgit_index_free_entries (entries, n_entries);
        }
        char (*held)[41] = NULL;
        size_t n_held = 0;
        if (with_undo &&
            bgit_index_resolve_undo (index_path, &held, &n_held) == 0) {
            for (size_t i = 0; i < n_held; i++)
                git_fsck_push (f, walk, held[i]);
            free (held);
        }
        if (bgit_index_cache_tree (index_path, &held, &n_held) == 0) {
            for (size_t i = 0; i < n_held; i++)
                git_fsck_push (f, walk, held[i]);
            free (held);
        }
    }

    if (reflogs) {
        char logs[4096];
        if ((size_t) snprintf (logs, sizeof logs, "%s/logs",
                               ctx->repo.common_dir) < sizeof logs)
            git_fsck_reflog_roots (f, walk, logs);
    }
}

static int
git_cmd_fsck (git_context *ctx, WORD_LIST *args)
{
    const char *usage =
        "git fsck [--tags] [--root] [--unreachable] [--cache] [--no-reflogs] "
        "[--strict] [--verbose] [--[no-]dangling] [--connectivity-only] "
        "[<object>...]";
    struct git_fsck fsck;
    memset (&fsck, 0, sizeof fsck);
    fsck.ctx = ctx;
    fsck.show_dangling = 1;
    int reflogs = 1;
    const char *heads[64];
    size_t n_heads = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--unreachable")) fsck.show_unreachable = 1;
        else if (!strcmp (w, "--dangling")) fsck.show_dangling = 1;
        else if (!strcmp (w, "--no-dangling")) fsck.show_dangling = 0;
        else if (!strcmp (w, "--root")) fsck.show_roots = 1;
        else if (!strcmp (w, "--tags")) fsck.show_tags = 1;
        else if (!strcmp (w, "--verbose") || !strcmp (w, "-v")) fsck.verbose = 1;
        else if (!strcmp (w, "--connectivity-only")) fsck.connectivity_only = 1;
        else if (!strcmp (w, "--no-reflogs")) reflogs = 0;
        else if (!strcmp (w, "--reflogs")) reflogs = 1;
        /* Accepted and no more than that: this store always reads its packs
           and alternates, always treats the index as a head, and checks what
           it checks. */
        else if (!strcmp (w, "--cache") || !strcmp (w, "--no-cache") ||
                 !strcmp (w, "--full") || !strcmp (w, "--no-full") ||
                 !strcmp (w, "--strict") || !strcmp (w, "--no-strict") ||
                 !strcmp (w, "--progress") || !strcmp (w, "--no-progress"))
            ;
        else if (w[0] == '-') return git_usage (usage);
        else if (n_heads < sizeof heads / sizeof heads[0]) heads[n_heads++] = w;
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (git_fsck_collect (&fsck) < 0) return GIT_EXIT_FATAL;

    if (fsck.verbose)
        for (size_t i = 0; i < ctx->odb.n_object_dirs; i++)
            fprintf (stderr, "Checking object directory\n");
    for (size_t i = 0; i < fsck.n; i++)
        git_fsck_check_object (&fsck, &fsck.objects[i]);

    struct git_fsck_walk walk;
    memset (&walk, 0, sizeof walk);

    /* Objects named on the command line stand in for the refs, the index
       and the reflogs: git walks out from those and nothing else. */
    int default_heads = n_heads == 0;
    if (fsck.verbose && default_heads) fprintf (stderr, "Checking HEAD link\n");
    if (default_heads) git_fsck_heads (&fsck, &walk, reflogs, 1, 1);

    /* --tags says what each annotated tag points at, whether or not the
       refs are what the walk started from. */
    if (fsck.show_tags) {
        bgit_ref *refs = NULL;
        size_t n_refs = 0;
        if (bgit_refs_list (&ctx->repo, "refs/tags/", &refs, &n_refs) == 0) {
            for (size_t i = 0; i < n_refs; i++) {
                enum bgit_type type = BGIT_UNKNOWN;
                unsigned char *data = NULL;
                size_t len = 0;
                if (bgit_odb_read (&ctx->odb, refs[i].sha, &type, &data,
                                   &len) < 0)
                    continue;
                if (type == BGIT_TAG) {
                    char target[41] = "";
                    char kind[16] = "";
                    size_t at = 0;
                    while (at < len) {
                        size_t stop = at;
                        while (stop < len && data[stop] != '\n') stop++;
                        if (stop == at) break;
                        if (stop - at == 47 &&
                            !strncmp ((const char *) data + at, "object ", 7)) {
                            memcpy (target, data + at + 7, 40);
                            target[40] = '\0';
                        } else if (stop - at > 5 &&
                                   !strncmp ((const char *) data + at,
                                             "type ", 5)) {
                            size_t take = stop - at - 5;
                            if (take >= sizeof kind) take = sizeof kind - 1;
                            memcpy (kind, data + at + 5, take);
                            kind[take] = '\0';
                        }
                        at = stop + 1;
                    }
                    if (*target)
                        printf ("tagged %s %s (%s) in %s\n",
                                *kind ? kind : "commit", target,
                                refs[i].name + 10, refs[i].sha);
                }
                free (data);
            }
            bgit_refs_free (refs, n_refs);
        }
    }

    for (size_t i = 0; i < n_heads; i++) {
        char full[41];
        if (git_resolve (ctx, heads[i], full, NULL) == 0)
            git_fsck_push (&fsck, &walk, full);
        else {
            fflush (stdout);
            fprintf (stderr, "error: invalid parameter: expected sha1, got "
                             "'%s'\n", heads[i]);
            fsck.errors |= 1;
        }
    }

    git_fsck_reach (&fsck, &walk);

    for (size_t i = 0; i < fsck.n_absent; i++)
        printf ("missing %s %s\n", bgit_type_name (fsck.absent[i].type),
                fsck.absent[i].sha);
    for (size_t i = 0; i < fsck.n; i++) {
        struct git_fsck_object *o = &fsck.objects[i];
        if (!o->present || o->reachable) continue;
        if (fsck.show_unreachable)
            printf ("unreachable %s %s\n", bgit_type_name (o->type), o->sha);
        else if (!o->used && fsck.show_dangling)
            printf ("dangling %s %s\n", bgit_type_name (o->type), o->sha);
    }

    free (walk.pending);
    free (fsck.objects);
    free (fsck.absent);
    return fsck.errors;
}

/* ---- archive ------------------------------------------------------------ */

/* A tar as git writes one: ustar headers, everything owned by root, every
   file dated by the commit the archive was made from, and the whole thing
   padded out to a twenty-block boundary. */
struct git_archive {
    git_context *ctx;
    FILE *out;
    const char *prefix;
    time_t when;
    const char *const *paths;
    int n_paths;
    unsigned long long written;
    int failed;
};

static void
git_tar_octal (char *field, size_t n, unsigned long long value)
{
    snprintf (field, n, "%0*llo", (int) n - 1, value);
}

static void
git_tar_put (struct git_archive *ar, const void *data, size_t len)
{
    if (ar->failed) return;
    if (fwrite (data, 1, len, ar->out) != len) ar->failed = 1;
    ar->written += len;
}

/* Pad what has just been written out to the next 512-byte block. */
static void
git_tar_pad (struct git_archive *ar, size_t len)
{
    static const char zeros[512];
    size_t over = len % 512;
    if (over) git_tar_put (ar, zeros, 512 - over);
}

/* One header block. NAME may be split across the prefix field, as ustar
   allows, and the checksum is over the block with its own field blank. */
static void
git_tar_header (struct git_archive *ar, const char *name, const char *prefix,
                unsigned mode, unsigned long long size, char type,
                const char *link)
{
    char block[512];
    memset (block, 0, sizeof block);
    /* A name that fills the field exactly is not terminated, which is what
       the format allows and what git writes. */
    size_t name_len = strlen (name);
    memcpy (block, name, name_len < 100 ? name_len : 100);
    git_tar_octal (block + 100, 8, mode & 07777);   /* permissions only */
    git_tar_octal (block + 108, 8, 0);
    git_tar_octal (block + 116, 8, 0);
    git_tar_octal (block + 124, 12, size);
    git_tar_octal (block + 136, 12, (unsigned long long) ar->when);
    memset (block + 148, ' ', 8);
    block[156] = type;
    if (link) {
        size_t link_len = strlen (link);
        memcpy (block + 157, link, link_len < 100 ? link_len : 100);
    }
    memcpy (block + 257, "ustar", 6);
    memcpy (block + 263, "00", 2);
    snprintf (block + 265, 32, "root");
    snprintf (block + 297, 32, "root");
    git_tar_octal (block + 329, 8, 0);
    git_tar_octal (block + 337, 8, 0);
    if (prefix) {
        size_t prefix_len = strlen (prefix);
        memcpy (block + 345, prefix, prefix_len < 155 ? prefix_len : 155);
    }
    unsigned long sum = 0;
    for (size_t i = 0; i < sizeof block; i++)
        sum += (unsigned char) block[i];
    snprintf (block + 148, 8, "%07lo", sum);
    git_tar_put (ar, block, sizeof block);
}

/* A path that does not fit in a header goes in as far as it will, with the
   whole of it in an extended header of its own in front. */
static void
git_tar_entry (struct git_archive *ar, const char *path, const char *id,
               unsigned mode, unsigned long long size, char type,
               const char *link)
{
    size_t len = strlen (path);
    if (len <= 100) {
        git_tar_header (ar, path, NULL, mode, size, type, link);
        return;
    }
    /* ustar splits a long path at a slash: at most 155 bytes before it and
       fewer than 100 after. */
    if (len <= 255) {
        /* As much as will go in the prefix, so the search runs back from
           the last slash that is not the one a directory ends with. */
        size_t at = len - 2 < 155 ? len - 2 : 155;
        for (; at > 0; at--) {
            if (path[at] != '/') continue;
            if (len - at - 1 > 100) continue;
            char prefix[156];
            memcpy (prefix, path, at);
            prefix[at] = '\0';
            git_tar_header (ar, path + at + 1, prefix, mode, size, type, link);
            return;
        }
    }
    /* Nowhere to split it: git writes the path as a pax record instead,
       under a header named after the object itself. */
    char record[8192];
    /* The record counts itself: the length, a space, "path=", the path and
       a newline. */
    size_t body = strlen (" path=") + len + 1;
    size_t digits = 1;
    for (size_t total = body + digits; ; ) {
        size_t count = 1;
        for (size_t value = total; value >= 10; value /= 10) count++;
        if (count == digits) break;
        digits = count;
        total = body + digits;
    }
    int wrote = snprintf (record, sizeof record, "%zu path=%s\n",
                          body + digits, path);
    if (wrote < 0 || (size_t) wrote >= sizeof record) { ar->failed = 1; return; }
    char header_name[128];
    snprintf (header_name, sizeof header_name, "%s.paxheader", id);
    git_tar_header (ar, header_name, NULL, 0100666, (unsigned long long) wrote,
                    'x', NULL);
    git_tar_put (ar, record, (size_t) wrote);
    git_tar_pad (ar, (size_t) wrote);
    /* The entry itself is named after the object, the path being in the
       header in front of it. */
    snprintf (header_name, sizeof header_name, "%s.data", id);
    git_tar_header (ar, header_name, NULL, mode, size, type, link);
}

/* Does one of the paths named cover this one? With none named, all are. A
   directory is also wanted when a named path lies inside it, since the way
   to that path is written out before the path itself. */
static int
git_archive_wanted (const struct git_archive *ar, const char *path, int tree)
{
    if (!ar->n_paths) return 1;
    size_t path_len = strlen (path);
    for (int i = 0; i < ar->n_paths; i++) {
        size_t len = strlen (ar->paths[i]);
        while (len && ar->paths[i][len - 1] == '/') len--;
        if (!strncmp (path, ar->paths[i], len) &&
            (!path[len] || path[len] == '/'))
            return 1;
        if (tree && !strncmp (ar->paths[i], path, path_len) &&
            ar->paths[i][path_len] == '/')
            return 1;
    }
    return 0;
}

static int
git_archive_entry (void *data, const char *mode, const char *type,
                   const char *sha, const char *path)
{
    struct git_archive *ar = data;
    if (ar->failed) return -1;
    unsigned long value = strtoul (mode, NULL, 8);
    char full[8192];
    if ((size_t) snprintf (full, sizeof full, "%s%s", ar->prefix ? ar->prefix : "",
                           path) >= sizeof full)
        return -1;
    if (!strcmp (type, "commit")) return 0;    /* a gitlink holds nothing */
    if (!strcmp (type, "tree")) {
        if (!git_archive_wanted (ar, path, 1)) return 0;
        char directory[8192];
        if ((size_t) snprintf (directory, sizeof directory, "%s/", full) >=
            sizeof directory)
            return -1;
        /* git hands a directory 0777 and takes the umask off it. */
        git_tar_entry (ar, directory, sha, 0775, 0, '5', NULL);
        return 0;
    }
    if (!git_archive_wanted (ar, path, 0)) return 0;
    enum bgit_type kind;
    unsigned char *content = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ar->ctx->odb, sha, &kind, &content, &len) < 0)
        return -1;
    if ((value & 0170000) == 0120000) {
        char target[4096];
        size_t take = len < sizeof target - 1 ? len : sizeof target - 1;
        memcpy (target, content, take);
        target[take] = '\0';
        git_tar_entry (ar, full, sha, 0777, 0, '2', target);
    } else {
        /* A file comes out 0666 or 0777 by its executable bit, less the
           umask, which is git's own reading of it. */
        unsigned out_mode = ((value & 0111) ? 0777 : 0666) & ~0002u;
        git_tar_entry (ar, full, sha, out_mode, len, '0', NULL);
        git_tar_put (ar, content, len);
        git_tar_pad (ar, len);
    }
    free (content);
    return ar->failed ? -1 : 0;
}

static int
git_cmd_archive (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git archive [--format=tar] [--prefix=<prefix>] "
                        "[-o <file>] [-l | --list] <tree-ish> [<path>...]";
    const char *format = NULL, *prefix = NULL, *output = NULL, *name = NULL;
    const char *paths[64];
    int n_paths = 0, list = 0, after_dashes = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (after_dashes) {
            if (n_paths < (int) (sizeof paths / sizeof paths[0]))
                paths[n_paths++] = w;
            continue;
        }
        if (!strcmp (w, "--")) after_dashes = 1;
        else if (!strcmp (w, "-l") || !strcmp (w, "--list")) list = 1;
        else if (!strncmp (w, "--format=", 9)) format = w + 9;
        else if (!strcmp (w, "--format") && p->next) { format = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "--prefix=", 9)) prefix = w + 9;
        else if (!strcmp (w, "-o") && p->next) { output = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "--output=", 9)) output = w + 9;
        else if (!strcmp (w, "-v") || !strcmp (w, "--verbose") ||
                 !strcmp (w, "--worktree-attributes")) ;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else if (n_paths < (int) (sizeof paths / sizeof paths[0]))
            paths[n_paths++] = w;
    }
    if (list) {
        printf ("tar\n");
        return 0;
    }
    if (!name) return git_usage (usage);
    if (format && strcmp (format, "tar")) {
        if (!strcmp (format, "zip") || !strcmp (format, "tgz") ||
            !strcmp (format, "tar.gz"))
            return git_fatal ("this build's git archive writes tar, not %s",
                              format);
        return git_fatal ("Unknown archive format '%s'", format);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");

    char id[41], tree[41];
    if (git_resolve (ctx, name, id, NULL) < 0)
        return git_fatal ("not a valid object name: %s", name);
    enum bgit_type type;
    unsigned char *data = NULL;
    size_t len = 0;
    if (bgit_odb_read (&ctx->odb, id, &type, &data, &len) < 0)
        return git_fatal ("not a valid object name: %s", name);
    free (data);
    struct git_archive ar;
    memset (&ar, 0, sizeof ar);
    ar.ctx = ctx;
    ar.prefix = prefix;
    ar.paths = paths;
    ar.n_paths = n_paths;
    ar.when = time (NULL);
    char commit[41] = "";
    if (type == BGIT_COMMIT || type == BGIT_TAG) {
        if (bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0 ||
            bgit_commit_tree (&ctx->odb, commit, tree) < 0)
            return git_fatal ("not a valid object name: %s", name);
        struct git_commit read;
        if (git_commit_read (ctx, commit, &read) == 0) {
            ar.when = (time_t) strtoll (read.committer_date, NULL, 10);
            git_commit_release (&read);
        }
    } else if (type == BGIT_TREE) memcpy (tree, id, 41);
    else return git_fatal ("not a tree object: %s", name);

    ar.out = stdout;
    if (output) {
        ar.out = fopen (output, "w");
        if (!ar.out) return git_fatal ("cannot create %s", output);
    }
    /* A commit says which one it was, in a header the whole archive
       carries. */
    if (*commit) {
        char record[128];
        int wrote = snprintf (record, sizeof record, "52 comment=%s\n", commit);
        git_tar_header (&ar, "pax_global_header", NULL, 0100666,
                        (unsigned long long) wrote, 'g', NULL);
        git_tar_put (&ar, record, (size_t) wrote);
        git_tar_pad (&ar, (size_t) wrote);
    }
    /* A prefix that ends in a slash is a directory of its own, ahead of
       everything; one that does not is only a string in front of each
       name. */
    if (prefix && *prefix && prefix[strlen (prefix) - 1] == '/')
        git_tar_entry (&ar, prefix, tree, 0775, 0, '5', NULL);
    int rc = bgit_tree_walk (&ctx->odb, tree, "", 1, 1, git_archive_entry, &ar);
    /* Two empty blocks end it, and the whole is rounded to twenty. */
    static const char zeros[512];
    git_tar_put (&ar, zeros, 512);
    git_tar_put (&ar, zeros, 512);
    while (ar.written % 10240) git_tar_put (&ar, zeros, 512);
    if (output) fclose (ar.out);
    else fflush (stdout);
    if (rc < 0 || ar.failed) return git_fatal ("cannot write the archive");
    return 0;
}

/* ---- bisect ------------------------------------------------------------- */

/* While a transcript is being replayed the verdicts are only recorded: git
   works out where to go once, at the end, rather than after every line. */
static int git_bisect_replaying;

/* A bisection is kept in the git directory: where to go back to, what the
   two ends are called, what has been said so far, and which commit is out
   for testing. The verdicts themselves are refs — refs/bisect/bad and one
   refs/bisect/good-<id> for each — which is what makes a bisection survive
   anything that reads the repository between two runs. */
struct git_bisect {
    git_context *ctx;
    char bad_term[64], good_term[64];
    char bad[41];                   /* "" while none is known */
    char (*good)[41];
    size_t n_good;
    char (*skipped)[41];
    size_t n_skipped;
};

static void
git_bisect_release (struct git_bisect *state)
{
    free (state->good);
    free (state->skipped);
    memset (state, 0, sizeof *state);
}

/* One of the bisection's own files, by name. */
static int
git_bisect_path (git_context *ctx, const char *name, char *out, size_t outsz)
{
    return snprintf (out, outsz, "%s/%s", ctx->repo.git_dir, name) <
           (int) outsz ? 0 : -1;
}

static int
git_bisect_write (git_context *ctx, const char *name, const char *text)
{
    char path[4096];
    if (git_bisect_path (ctx, name, path, sizeof path) < 0) return -1;
    return git_write_file (path, text);
}

static int
git_bisect_read_line (git_context *ctx, const char *name, char *out,
                      size_t outsz)
{
    char path[4096];
    if (git_bisect_path (ctx, name, path, sizeof path) < 0) return -1;
    FILE *f = fopen (path, "r");
    if (!f) return -1;
    if (!fgets (out, (int) outsz, f)) { fclose (f); return -1; }
    fclose (f);
    size_t len = strlen (out);
    while (len && (out[len - 1] == '\n' || out[len - 1] == '\r')) out[--len] = '\0';
    return 0;
}

static void
git_bisect_remove (git_context *ctx, const char *name)
{
    char path[4096];
    if (git_bisect_path (ctx, name, path, sizeof path) == 0) unlink (path);
}

/* Add a line to the transcript, which `git bisect log` prints and
   `git bisect replay` reads back. */
static void
git_bisect_note (git_context *ctx, const char *format, ...)
{
    char path[4096];
    if (git_bisect_path (ctx, "BISECT_LOG", path, sizeof path) < 0) return;
    FILE *f = fopen (path, "a");
    if (!f) return;
    va_list args;
    va_start (args, format);
    vfprintf (f, format, args);
    va_end (args);
    fclose (f);
}

/* 1 while a bisection is under way. */
static int
git_bisect_running (git_context *ctx)
{
    char path[4096];
    struct stat st;
    return git_bisect_path (ctx, "BISECT_START", path, sizeof path) == 0 &&
           stat (path, &st) == 0;
}

/* What the two ends are called, which --term-old and --term-new can
   change. */
static void
git_bisect_terms (git_context *ctx, struct git_bisect *state)
{
    snprintf (state->bad_term, sizeof state->bad_term, "bad");
    snprintf (state->good_term, sizeof state->good_term, "good");
    char path[4096];
    if (git_bisect_path (ctx, "BISECT_TERMS", path, sizeof path) < 0) return;
    FILE *f = fopen (path, "r");
    if (!f) return;
    char line[64];
    if (fgets (line, sizeof line, f)) {
        line[strcspn (line, "\r\n")] = '\0';
        if (*line) snprintf (state->bad_term, sizeof state->bad_term, "%s", line);
    }
    if (fgets (line, sizeof line, f)) {
        line[strcspn (line, "\r\n")] = '\0';
        if (*line) snprintf (state->good_term, sizeof state->good_term, "%s", line);
    }
    fclose (f);
}

/* The verdicts so far, read from the refs that hold them. */
static int
git_bisect_load (git_context *ctx, struct git_bisect *state)
{
    memset (state, 0, sizeof *state);
    state->ctx = ctx;
    git_bisect_terms (ctx, state);
    bgit_ref *refs = NULL;
    size_t n = 0;
    if (bgit_refs_list (&ctx->repo, "refs/bisect/", &refs, &n) != 0) return 0;
    for (size_t i = 0; i < n; i++) {
        const char *name = refs[i].name + strlen ("refs/bisect/");
        if (!strcmp (name, "bad")) memcpy (state->bad, refs[i].sha, 41);
        else if (!strncmp (name, "good-", 5)) {
            char (*grown)[41] = realloc (state->good,
                                         (state->n_good + 1) * sizeof *grown);
            if (!grown) break;
            state->good = grown;
            memcpy (state->good[state->n_good++], refs[i].sha, 41);
        } else if (!strncmp (name, "skip-", 5)) {
            char (*grown)[41] = realloc (state->skipped,
                                         (state->n_skipped + 1) * sizeof *grown);
            if (!grown) break;
            state->skipped = grown;
            memcpy (state->skipped[state->n_skipped++], refs[i].sha, 41);
        }
    }
    bgit_refs_free (refs, n);
    return 0;
}

/* How many steps git says are roughly left, which is its own estimate over
   the size of the set rather than a logarithm outright. */
static int
git_bisect_steps (int all)
{
    if (all < 3) return 0;
    int n = 0;
    while ((1 << (n + 1)) <= all) n++;
    int e = 1 << n;
    int x = all - e;
    return e < 3 * x ? n : n - 1;
}

/* The commits still in question: reachable from the bad one, not reachable
   from any good one. Sorted newest first, as the walk gives them. */
static int
git_bisect_candidates (struct git_bisect *state, char (**out)[41],
                       size_t *n_out)
{
    *out = NULL;
    *n_out = 0;
    if (!*state->bad) return 0;
    char (*ids)[41] = NULL;
    size_t n = 0, cap = 0;
    char (*pending)[41] = NULL;
    size_t n_pending = 0, cap_pending = 0;

#define GIT_BISECT_PUSH(list, count, room, value) do { \
    if ((count) == (room)) { \
        size_t next = (room) ? (room) * 2 : 64; \
        char (*grown)[41] = realloc ((list), next * sizeof *grown); \
        if (!grown) goto done; \
        (list) = grown; \
        (room) = next; \
    } \
    memcpy ((list)[(count)++], (value), 41); \
} while (0)

    GIT_BISECT_PUSH (pending, n_pending, cap_pending, state->bad);
    while (n_pending) {
        char id[41];
        memcpy (id, pending[--n_pending], 41);
        int seen = 0;
        for (size_t i = 0; i < n; i++)
            if (!strcmp (ids[i], id)) { seen = 1; break; }
        if (seen) continue;
        int excluded = 0;
        for (size_t i = 0; i < state->n_good && !excluded; i++)
            if (bgit_is_ancestor (&state->ctx->odb, id, state->good[i]) > 0 ||
                !strcmp (id, state->good[i]))
                excluded = 1;
        if (excluded) continue;
        GIT_BISECT_PUSH (ids, n, cap, id);
        char parents[BGIT_MAX_PARENTS][41];
        int count = bgit_commit_parents (&state->ctx->odb, id, parents,
                                         BGIT_MAX_PARENTS);
        for (int i = 0; i < count; i++)
            GIT_BISECT_PUSH (pending, n_pending, cap_pending, parents[i]);
    }
#undef GIT_BISECT_PUSH
 done:
    free (pending);
    *out = ids;
    *n_out = n;
    return 0;
}

/* Which of the candidates to test next: the one that halves the set best.

   Each commit's weight is how many of the set it reaches, itself included.
   Worked out parents first, a commit with a single parent in the set takes
   its parent's weight and one more; only where two lines of history meet
   does the count have to be made by walking, so that what they share is
   not counted twice. Ties go to the oldest, as git's own scan does. */
static long
git_bisect_choose (struct git_bisect *state, char (*ids)[41], size_t n,
                   int *weight_out)
{
    *weight_out = 0;
    if (!n) return -1;
    int *weights = calloc (n, sizeof *weights);
    int *waiting = calloc (n, sizeof *waiting);
    long *order = calloc (n, sizeof *order);
    char (*parents)[BGIT_MAX_PARENTS][41] =
        calloc (n, sizeof (char[BGIT_MAX_PARENTS][41]));
    int *n_parents = calloc (n, sizeof *n_parents);
    long (*inside)[BGIT_MAX_PARENTS] = calloc (n, sizeof *inside);
    if (!weights || !waiting || !order || !parents || !n_parents || !inside) {
        free (weights); free (waiting); free (order);
        free (parents); free (n_parents); free (inside);
        return -1;
    }
    for (size_t k = 0; k < n; k++) {
        n_parents[k] = bgit_commit_parents (&state->ctx->odb, ids[k],
                                            parents[k], BGIT_MAX_PARENTS);
        for (int i = 0; i < n_parents[k]; i++) {
            inside[k][i] = -1;
            for (size_t j = 0; j < n; j++)
                if (!strcmp (ids[j], parents[k][i])) { inside[k][i] = (long) j; break; }
            if (inside[k][i] >= 0) waiting[k]++;
        }
    }
    /* Parents before children, so that a weight is never asked for before
       it has been worked out. */
    size_t n_order = 0;
    for (size_t k = 0; k < n; k++) if (!waiting[k]) order[n_order++] = (long) k;
    for (size_t at = 0; at < n_order; at++) {
        long done = order[at];
        for (size_t k = 0; k < n; k++)
            for (int i = 0; i < n_parents[k]; i++)
                if (inside[k][i] == done && --waiting[k] == 0)
                    order[n_order++] = (long) k;
    }
    for (size_t at = 0; at < n_order; at++) {
        long k = order[at];
        int held = 0;
        long only = -1;
        for (int i = 0; i < n_parents[k]; i++)
            if (inside[k][i] >= 0) { held++; only = inside[k][i]; }
        if (!held) weights[k] = 1;
        else if (held == 1) weights[k] = weights[only] + 1;
        else {
            /* Two histories joined here: walk what this commit reaches,
               within the set, so that what they share is counted once. */
            char (*pending)[41] = malloc (n * sizeof *pending);
            char *seen = calloc (n, 1);
            size_t n_pending = 0, reached = 0;
            if (!pending || !seen) { free (pending); free (seen); break; }
            memcpy (pending[n_pending++], ids[k], 41);
            while (n_pending) {
                char id[41];
                memcpy (id, pending[--n_pending], 41);
                size_t at_id = n;
                for (size_t j = 0; j < n; j++)
                    if (!strcmp (ids[j], id)) { at_id = j; break; }
                if (at_id == n || seen[at_id]) continue;
                seen[at_id] = 1;
                reached++;
                for (int i = 0; i < n_parents[at_id] && n_pending < n; i++)
                    memcpy (pending[n_pending++], parents[at_id][i], 41);
            }
            weights[k] = (int) reached;
            free (pending);
            free (seen);
        }
    }
    long best = -1;
    int best_distance = -1;
    for (size_t k = n; k-- > 0;) {          /* oldest first */
        int skipped = 0;
        for (size_t i = 0; i < state->n_skipped && !skipped; i++)
            if (!strcmp (ids[k], state->skipped[i])) skipped = 1;
        if (skipped || !strcmp (ids[k], state->bad)) continue;
        int distance = weights[k];
        if ((int) n - distance < distance) distance = (int) n - distance;
        if (distance > best_distance) {
            best_distance = distance;
            best = (long) k;
            *weight_out = weights[k];
        }
    }
    free (weights);
    free (waiting);
    free (order);
    free (parents);
    free (n_parents);
    free (inside);
    return best;
}

/* Put the working tree on a commit without saying anything about it, which
   is what bisect does between one verdict and the next. */
static int
git_bisect_checkout (git_context *ctx, const char *commit)
{
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return -1;
    int rc = git_switch_to (ctx, &state, commit, 1, 0);
    git_state_release (&state);
    return rc ? -1 : 0;
}

/* The subject line of a commit, for the lines bisect prints about one. */
static int
git_bisect_subject (git_context *ctx, const char *id, char *out, size_t outsz)
{
    struct git_commit commit;
    if (git_commit_read (ctx, id, &commit) < 0) return -1;
    git_subject (&commit, out, outsz);
    git_commit_release (&commit);
    return 0;
}

/* Say where the bisection stands, and either put the next commit out for
   testing or name the first bad one. */
static int
git_bisect_step (struct git_bisect *state)
{
    git_context *ctx = state->ctx;
    if (!*state->bad || !state->n_good) {
        /* These say good and bad whatever the two ends have been called,
           which is what git says. */
        if (!*state->bad && !state->n_good)
            printf ("status: waiting for both good and bad commits\n");
        else if (!*state->bad)
            printf ("status: waiting for bad commit, %zu good commit%s known\n",
                    state->n_good, state->n_good == 1 ? "" : "s");
        else
            printf ("status: waiting for good commit(s), bad commit known\n");
        return 0;
    }
    /* Every good commit has to be behind the bad one, or the answer the
       bisection would give means nothing. */
    for (size_t i = 0; i < state->n_good; i++)
        if (bgit_is_ancestor (&ctx->odb, state->good[i], state->bad) <= 0) {
            fflush (stdout);
            fprintf (stderr, "Some %s revs are not ancestors of the %s rev.\n"
                             "git bisect cannot work properly in this case.\n"
                             "Maybe you mistook %s and %s revs?\n",
                     state->good_term, state->bad_term, state->good_term,
                     state->bad_term);
            return 1;
        }
    git_bisect_write (ctx, "BISECT_ANCESTORS_OK", "");

    char (*ids)[41] = NULL;
    size_t n = 0;
    if (git_bisect_candidates (state, &ids, &n) < 0) return GIT_EXIT_FATAL;
    int weight = 0;
    long best = git_bisect_choose (state, ids, n, &weight);
    if (best < 0) {
        /* Nothing left to try: the bad commit is the first one. */
        char subject[4096] = "";
        git_bisect_subject (ctx, state->bad, subject, sizeof subject);
        printf ("%s is the first %s commit\n", state->bad, state->bad_term);
        git_bisect_note (ctx, "# first %s commit: [%s] %s\n",
                         state->bad_term,
                         state->bad, subject);
        free (ids);
        struct git_commit commit;
        if (git_commit_read (ctx, state->bad, &commit) == 0) {
            struct git_diff_format diff;
            git_diff_format_init (&diff);
            diff.stat = 1;
            struct git_date_format date;
            git_date_format_set (&date, "default");
            git_print_commit (ctx, stdout, &commit, 0, NULL, &date,
                              GIT_DECORATE_NO, 0, &diff, NULL, 0);
            git_commit_release (&commit);
        }
        return 0;
    }
    char chosen[41];
    memcpy (chosen, ids[best], 41);
    free (ids);
    int left = (int) n - weight - 1;
    if (left < 0) left = 0;
    int steps = git_bisect_steps ((int) n);
    printf ("Bisecting: %d revision%s left to test after this (roughly %d "
            "step%s)\n", left, left == 1 ? "" : "s", steps,
            steps == 1 ? "" : "s");
    char subject[4096] = "";
    git_bisect_subject (ctx, chosen, subject, sizeof subject);
    printf ("[%s] %s\n", chosen, subject);
    char text[64];
    snprintf (text, sizeof text, "%s\n", chosen);
    git_bisect_write (ctx, "BISECT_EXPECTED_REV", text);
    return git_bisect_checkout (ctx, chosen) < 0 ? GIT_EXIT_FATAL : 0;
}

/* What `git bisect run` runs. git hands the words to the system; here they
   go through this shell, so that a builtin can be the test — which is the
   only kind of command there is in a tree with nothing else in it. */
static int
git_bisect_run_words (WORD_LIST *words)
{
    char script[8192];
    size_t at = 0;
    for (WORD_LIST *p = words; p; p = p->next) {
        if (at + 4 >= sizeof script) return -1;
        if (at) script[at++] = ' ';
        script[at++] = '\'';
        for (const char *c = p->word->word; *c; c++) {
            if (at + 8 >= sizeof script) return -1;
            if (*c == '\'') {
                memcpy (script + at, "'\\''", 4);
                at += 4;
            } else script[at++] = *c;
        }
        script[at++] = '\'';
    }
    script[at] = '\0';
    fflush (stdout);
    fflush (stderr);
    pid_t child = fork ();
    if (child < 0) return -1;
    if (!child) {
        git_restore_caller_pipe ();
        array_needs_making = 1;
        maybe_make_export_env ();
        const char *argv[6];
        int n = 0;
        argv[n++] = "bash";
        argv[n++] = "--noprofile";
        argv[n++] = "--norc";
        argv[n++] = "-c";
        argv[n++] = script;
        argv[n] = NULL;
        execve ("/proc/self/exe", (char *const *) argv, export_env);
        _exit (127);
    }
    int status = 0;
    while (waitpid (child, &status, 0) < 0 && errno == EINTR) ;
    if (!WIFEXITED (status)) return -1;
    return WEXITSTATUS (status);
}

/* Record a verdict as the ref that holds it, and say so in the log. */
static int
git_bisect_verdict (struct git_bisect *state, const char *kind,
                    const char *name, const char *id, int note)
{
    /* The refs are named bad, good-<id> and skip-<id> whatever the two ends
       are called, which is how git names them. */
    char ref[4096], subject[4096] = "";
    if (!strcmp (kind, "bad")) snprintf (ref, sizeof ref, "refs/bisect/bad");
    else snprintf (ref, sizeof ref, "refs/bisect/%s-%s", kind, id);
    if (bgit_ref_set (&state->ctx->repo, ref, id, NULL) < 0) return -1;
    (void) name;
    git_bisect_subject (state->ctx, id, subject, sizeof subject);
    const char *term = !strcmp (kind, "bad") ? state->bad_term
                     : !strcmp (kind, "good") ? state->good_term : "skip";
    git_bisect_note (state->ctx, "# %s: [%s] %s\n", term, id, subject);
    /* An end given to `git bisect start` is in the start line already; one
       given on its own is a command of its own in the transcript. */
    if (note) git_bisect_note (state->ctx, "git bisect %s %s\n", term, id);
    return 0;
}

/* Take the bisection down: the refs, the files, and back to where it
   started. */
static int
git_bisect_reset (git_context *ctx, const char *target)
{
    char where[4096] = "";
    if (!target && git_bisect_read_line (ctx, "BISECT_START", where,
                                         sizeof where) == 0 && *where)
        target = where;
    bgit_ref *refs = NULL;
    size_t n = 0;
    if (bgit_refs_list (&ctx->repo, "refs/bisect/", &refs, &n) == 0) {
        for (size_t i = 0; i < n; i++)
            bgit_ref_delete (&ctx->repo, refs[i].name, NULL, NULL);
        bgit_refs_free (refs, n);
    }
    int rc = 0;
    if (target && *target) {
        struct git_state state;
        if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
        rc = git_switch_to_saying (ctx, &state, target, 0, 0, 1);
        git_state_release (&state);
    }
    git_bisect_remove (ctx, "BISECT_START");
    git_bisect_remove (ctx, "BISECT_TERMS");
    git_bisect_remove (ctx, "BISECT_NAMES");
    git_bisect_remove (ctx, "BISECT_LOG");
    git_bisect_remove (ctx, "BISECT_EXPECTED_REV");
    git_bisect_remove (ctx, "BISECT_ANCESTORS_OK");
    git_bisect_remove (ctx, "BISECT_HEAD");
    return rc;
}

static int
git_cmd_bisect (git_context *ctx, WORD_LIST *args)
{
    const char *usage =
        "git bisect (start [<bad> [<good>...]] | bad [<rev>] | good [<rev>] | "
        "skip [<rev>...] | terms | log | replay <file> | run <cmd>... | "
        "reset [<commit>])";
    if (!args) {
        fflush (stdout);
        fprintf (stderr, "fatal: need a command\n\nusage: %s\n", usage);
        return GIT_EXIT_USAGE;
    }
    const char *verb = args->word->word;
    WORD_LIST *rest = args->next;
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (!strcmp (verb, "start")) {
        const char *bad = NULL;
        const char *good[64];
        size_t n_good = 0;
        char bad_term[64] = "bad", good_term[64] = "good";
        for (WORD_LIST *p = rest; p; p = p->next) {
            const char *w = p->word->word;
            if (!strncmp (w, "--term-new=", 11) || !strncmp (w, "--term-bad=", 11))
                snprintf (bad_term, sizeof bad_term, "%s", strchr (w, '=') + 1);
            else if (!strncmp (w, "--term-old=", 11) ||
                     !strncmp (w, "--term-good=", 12))
                snprintf (good_term, sizeof good_term, "%s",
                          strchr (w, '=') + 1);
            else if (!strcmp (w, "--no-checkout") || !strcmp (w, "--first-parent"))
                return git_fatal ("this build's git bisect does not have %s", w);
            else if (!strcmp (w, "--")) break;
            else if (w[0] == '-' && w[1]) return git_usage (usage);
            else if (!bad) bad = w;
            else if (n_good < sizeof good / sizeof good[0]) good[n_good++] = w;
        }
        if (git_bisect_running (ctx)) git_bisect_reset (ctx, NULL);
        /* Where to go back to: the branch that is checked out, or the
           commit if HEAD is detached. */
        char *symref = NULL, head[41];
        char where[4096] = "";
        if (bgit_ref_resolve (&ctx->repo, "HEAD", head, &symref) == 0) {
            if (symref && !strncmp (symref, "refs/heads/", 11))
                snprintf (where, sizeof where, "%s", symref + 11);
            else snprintf (where, sizeof where, "%s", head);
        }
        free (symref);
        char text[4096];
        snprintf (text, sizeof text, "%s\n", where);
        git_bisect_write (ctx, "BISECT_START", text);
        snprintf (text, sizeof text, "%s\n%s\n", bad_term, good_term);
        git_bisect_write (ctx, "BISECT_TERMS", text);
        git_bisect_write (ctx, "BISECT_NAMES", "");
        git_bisect_write (ctx, "BISECT_LOG", "");

        struct git_bisect state;
        git_bisect_load (ctx, &state);
        int rc = 0;
        if (bad) {
            char id[41];
            if (git_resolve (ctx, bad, id, NULL) < 0)
                rc = git_fatal ("Not a valid object name: '%s'.", bad);
            else {
                memcpy (state.bad, id, 41);
                git_bisect_verdict (&state, "bad", bad, id, 0);
            }
        }
        for (size_t i = 0; i < n_good && !rc; i++) {
            char id[41];
            if (git_resolve (ctx, good[i], id, NULL) < 0) {
                rc = git_fatal ("Not a valid object name: '%s'.", good[i]);
                break;
            }
            char (*grown)[41] = realloc (state.good,
                                         (state.n_good + 1) * sizeof *grown);
            if (!grown) { rc = GIT_EXIT_FATAL; break; }
            state.good = grown;
            memcpy (state.good[state.n_good++], id, 41);
            git_bisect_verdict (&state, "good", good[i], id, 0);
        }
        if (!rc) {
            /* The transcript keeps the command as it was given, arguments
               and all, so that a replay does the same thing again. */
            char line[4096];
            size_t at = (size_t) snprintf (line, sizeof line, "git bisect start");
            for (WORD_LIST *w = rest; w && at < sizeof line; w = w->next)
                at += (size_t) snprintf (line + at, sizeof line - at, " '%s'",
                                         w->word->word);
            git_bisect_note (ctx, "%s\n", line);
            if (!bad && !n_good)
                git_bisect_note (ctx, "# status: waiting for both good and bad "
                                 "commits\n");
            else if (!n_good)
                git_bisect_note (ctx, "# status: waiting for good commit(s), "
                                 "bad commit known\n");
            rc = git_bisect_step (&state);
        }
        git_bisect_release (&state);
        return rc;
    }

    if (!strcmp (verb, "reset")) {
        if (!git_bisect_running (ctx)) return 0;
        return git_bisect_reset (ctx, rest ? rest->word->word : NULL);
    }

    if (!strcmp (verb, "log")) {
        if (!git_bisect_running (ctx)) {
            fflush (stdout);
            fprintf (stderr, "error: We are not bisecting.\n");
            return 1;
        }
        char path[4096];
        if (git_bisect_path (ctx, "BISECT_LOG", path, sizeof path) < 0)
            return GIT_EXIT_FATAL;
        unsigned char *text = NULL;
        size_t len = 0;
        if (bgit_slurp_file (path, &text, &len) == 0) {
            fwrite (text, 1, len, stdout);
            free (text);
        }
        return 0;
    }

    /* A replay starts a bisection of its own, so it does not need one
       already under way; the verdicts do. */
    if (!git_bisect_running (ctx) && strcmp (verb, "terms") &&
        strcmp (verb, "replay")) {
        fflush (stdout);
        fprintf (stderr, "You need to start by \"git bisect start\"\n\n");
        return 1;
    }

    struct git_bisect state;
    git_bisect_load (ctx, &state);

    if (!strcmp (verb, "terms")) {
        int rc = 0;
        if (!git_bisect_running (ctx)) {
            fflush (stdout);
            fprintf (stderr, "error: no terms defined\n");
            rc = 1;
        } else if (rest && !strcmp (rest->word->word, "--term-good"))
            printf ("%s\n", state.good_term);
        else if (rest && !strcmp (rest->word->word, "--term-bad"))
            printf ("%s\n", state.bad_term);
        else
            printf ("Your current terms are %s for the old state\nand %s for "
                    "the new state.\n", state.good_term, state.bad_term);
        git_bisect_release (&state);
        return rc;
    }

    int is_bad = !strcmp (verb, state.bad_term) || !strcmp (verb, "new");
    int is_good = !strcmp (verb, state.good_term) || !strcmp (verb, "old");
    if (is_bad || is_good || !strcmp (verb, "skip")) {
        int rc = 0;
        const char *names[64];
        size_t n_names = 0;
        for (WORD_LIST *p = rest; p; p = p->next)
            if (n_names < sizeof names / sizeof names[0])
                names[n_names++] = p->word->word;
        if (!n_names) { names[0] = "HEAD"; n_names = 1; }
        for (size_t i = 0; i < n_names && !rc; i++) {
            char id[41];
            if (git_resolve (ctx, names[i], id, NULL) < 0) {
                rc = git_fatal ("Bad rev input: %s", names[i]);
                break;
            }
            if (is_bad) {
                memcpy (state.bad, id, 41);
                git_bisect_verdict (&state, "bad", names[i], id, 1);
            } else if (is_good) {
                char (*grown)[41] = realloc (state.good,
                                             (state.n_good + 1) * sizeof *grown);
                if (!grown) { rc = GIT_EXIT_FATAL; break; }
                state.good = grown;
                memcpy (state.good[state.n_good++], id, 41);
                git_bisect_verdict (&state, "good", names[i], id, 1);
            } else {
                char (*grown)[41] = realloc (state.skipped,
                                             (state.n_skipped + 1) * sizeof *grown);
                if (!grown) { rc = GIT_EXIT_FATAL; break; }
                state.skipped = grown;
                memcpy (state.skipped[state.n_skipped++], id, 41);
                git_bisect_verdict (&state, "skip", names[i], id, 1);
            }
        }
        if (!rc) {
            if (!*state.bad)
                git_bisect_note (ctx, "# status: waiting for bad commit, %zu "
                                 "good commit%s known\n", state.n_good,
                                 state.n_good == 1 ? "" : "s");
            else if (!state.n_good)
                git_bisect_note (ctx, "# status: waiting for good commit(s), "
                                 "bad commit known\n");
            if (!git_bisect_replaying) rc = git_bisect_step (&state);
        }
        git_bisect_release (&state);
        return rc;
    }

    if (!strcmp (verb, "replay")) {
        int rc = 0;
        if (!rest) rc = git_usage (usage);
        else {
            unsigned char *text = NULL;
            size_t len = 0;
            if (bgit_slurp_file (rest->word->word, &text, &len) < 0)
                rc = GIT_EXIT_FATAL;
            else {
                git_bisect_release (&state);
                git_bisect_reset (ctx, NULL);
                size_t at = 0;
                while (at < len && !rc) {
                    size_t end = at;
                    while (end < len && text[end] != '\n') end++;
                    char line[4096];
                    size_t take = end - at < sizeof line - 1 ? end - at
                                                             : sizeof line - 1;
                    memcpy (line, text + at, take);
                    line[take] = '\0';
                    at = end + 1;
                    if (line[0] == '#' || !*line) continue;
                    if (strncmp (line, "git bisect ", 11)) continue;
                    /* Each line is a command of its own, given again. */
                    WORD_LIST *words = NULL, *tail = NULL;
                    char *saved = NULL;
                    for (char *word = strtok_r (line + 11, " \t", &saved); word;
                         word = strtok_r (NULL, " \t", &saved)) {
                        /* The transcript quotes what was given; the quotes
                           are the transcript's, not part of the word. */
                        size_t len = strlen (word);
                        if (len > 1 && word[0] == '\'' && word[len - 1] == '\'') {
                            word[len - 1] = '\0';
                            word++;
                        }
                        WORD_LIST *one = make_word_list (make_word (word), NULL);
                        if (!words) words = tail = one;
                        else { tail->next = one; tail = one; }
                    }
                    if (words) {
                        git_bisect_replaying = 1;
                        rc = git_cmd_bisect (ctx, words);
                        git_bisect_replaying = 0;
                        dispose_words (words);
                    }
                }
                free (text);
                if (!rc) {
                    struct git_bisect after;
                    git_bisect_load (ctx, &after);
                    rc = git_bisect_step (&after);
                    git_bisect_release (&after);
                }
                return rc;
            }
        }
        git_bisect_release (&state);
        return rc;
    }

    if (!strcmp (verb, "run")) {
        int rc = 0;
        if (!rest) { git_bisect_release (&state); return git_usage (usage); }
        for (;;) {
            char shown[4096] = "";
            size_t at = 0;
            for (WORD_LIST *p = rest; p; p = p->next)
                at += (size_t) snprintf (shown + at, sizeof shown - at, "%s'%s'",
                                         at ? " " : "", p->word->word);
            printf ("running %s\n", shown);
            fflush (stdout);
            int status = git_bisect_run_words (rest);
            if (status < 0 || status == 125) {
                /* 125 says the commit cannot be tested. */
                WORD_LIST *skip = make_word_list (make_word ("skip"), NULL);
                rc = git_cmd_bisect (ctx, skip);
                dispose_words (skip);
            } else {
                WORD_LIST *verdict =
                    make_word_list (make_word (status ? (char *) "bad"
                                                      : (char *) "good"), NULL);
                rc = git_cmd_bisect (ctx, verdict);
                dispose_words (verdict);
            }
            if (rc) break;
            char expected[64];
            if (git_bisect_read_line (ctx, "BISECT_EXPECTED_REV", expected,
                                      sizeof expected) < 0) break;
            struct git_bisect again;
            git_bisect_load (ctx, &again);
            char (*ids)[41] = NULL;
            size_t n = 0;
            git_bisect_candidates (&again, &ids, &n);
            int weight = 0;
            long best = git_bisect_choose (&again, ids, n, &weight);
            free (ids);
            git_bisect_release (&again);
            if (best < 0) break;
        }
        if (!rc) printf ("bisect found first %s commit\n", state.bad_term);
        git_bisect_release (&state);
        return rc;
    }

    git_bisect_release (&state);
    fflush (stdout);
    fprintf (stderr, "fatal: unknown command: %s\n", verb);
    return GIT_EXIT_USAGE;
}

/* ---- bundle ------------------------------------------------------------- */

/* Both written out further down, beside the pack reading and writing that
   a fetch does; a bundle is the same pack in a file. */
static int git_pack_build_deltas (bgit_odb *odb, char (*ids)[41], size_t n,
                                  int ofs_ok, unsigned char **out,
                                  size_t *out_len,
                                  struct bgit_pack_idx_entry **entries_out,
                                  unsigned char checksum[20], char hex[41]);
static int git_store_pack (git_context *ctx, unsigned char *pack, size_t len);

/* A bundle is a header and a pack in one file: a line saying what it is,
   then a line for each commit it takes for granted, then a line for each
   ref it carries, then a blank line, then the pack. */
#define GIT_BUNDLE_SIGNATURE "# v2 git bundle\n"

struct git_bundle {
    char (*ids)[41];
    char **names;               /* NULL for a prerequisite */
    size_t n;
    size_t n_prerequisites;
    unsigned char *pack;
    size_t pack_len;
    unsigned char *raw;
};

static void
git_bundle_release (struct git_bundle *bundle)
{
    for (size_t i = 0; i < bundle->n; i++) free (bundle->names[i]);
    free (bundle->names);
    free (bundle->ids);
    free (bundle->raw);
    memset (bundle, 0, sizeof *bundle);
}

/* Read one, header and all. The pack is left pointing into the file's own
   bytes, which the caller frees with the rest. */
static int
git_bundle_read (const char *path, struct git_bundle *bundle)
{
    memset (bundle, 0, sizeof *bundle);
    int fd = open (path, O_RDONLY);
    unsigned char *raw = NULL;
    size_t len = 0;
    if (fd < 0 || bgit_slurp_fd (fd, &raw, &len) < 0) {
        if (fd >= 0) close (fd);
        fflush (stdout);
        fprintf (stderr, "error: could not open '%s'\n", path);
        return -1;
    }
    close (fd);
    bundle->raw = raw;
    size_t signature = strlen (GIT_BUNDLE_SIGNATURE);
    int version = 0;
    if (len >= signature &&
        !memcmp (raw, GIT_BUNDLE_SIGNATURE, signature)) version = 2;
    else if (len >= signature && !memcmp (raw, "# v3 git bundle\n", signature))
        version = 3;
    if (!version) {
        fflush (stdout);
        fprintf (stderr, "error: '%s' does not look like a v2 or v3 bundle "
                         "file\n", path);
        git_bundle_release (bundle);
        return -1;
    }
    size_t at = signature;
    /* A v3 bundle says what it needs before it says what it holds. Only
       one of those is understood here. */
    while (version == 3 && at < len && raw[at] == '@') {
        size_t end = at;
        while (end < len && raw[end] != '\n') end++;
        char capability[256];
        size_t take = end - at - 1 < sizeof capability - 1 ? end - at - 1
                                                           : sizeof capability - 1;
        memcpy (capability, raw + at + 1, take);
        capability[take] = '\0';
        if (strcmp (capability, "object-format=sha1")) {
            fflush (stdout);
            fprintf (stderr, "error: unknown capability '%s'\n", capability);
            git_bundle_release (bundle);
            return -1;
        }
        at = end + 1;
    }
    while (at < len) {
        size_t end = at;
        while (end < len && raw[end] != '\n') end++;
        size_t line = end - at;
        if (!line) { at = end + 1; break; }     /* the blank line ends it */
        const char *text = (const char *) raw + at;
        int prerequisite = text[0] == '-';
        const char *id = prerequisite ? text + 1 : text;
        if (line < 40u + (size_t) prerequisite) break;
        char (*grown)[41] = realloc (bundle->ids, (bundle->n + 1) * sizeof *grown);
        if (!grown) { git_bundle_release (bundle); return -1; }
        bundle->ids = grown;
        char **names = realloc (bundle->names, (bundle->n + 1) * sizeof *names);
        if (!names) { git_bundle_release (bundle); return -1; }
        bundle->names = names;
        memcpy (bundle->ids[bundle->n], id, 40);
        bundle->ids[bundle->n][40] = '\0';
        const char *rest = id + 40;
        size_t rest_len = (size_t) (text + line - rest);
        if (rest_len && *rest == ' ') { rest++; rest_len--; }
        bundle->names[bundle->n] = NULL;
        if (!prerequisite) {
            bundle->names[bundle->n] = strndup (rest, rest_len);
            if (!bundle->names[bundle->n]) {
                git_bundle_release (bundle);
                return -1;
            }
        } else bundle->n_prerequisites++;
        bundle->n++;
        at = end + 1;
    }
    bundle->pack = raw + at;
    bundle->pack_len = len > at ? len - at : 0;
    return 0;
}

/* What a bundle takes for granted must already be here, or the pack in it
   cannot be understood. git says which commits are wanting and refuses. */
static int
git_bundle_prerequisites (git_context *ctx, const struct git_bundle *bundle)
{
    int missing = 0;
    for (size_t i = 0; i < bundle->n; i++) {
        if (bundle->names[i]) continue;
        if (bgit_odb_has (&ctx->odb, bundle->ids[i])) continue;
        if (!missing) {
            fflush (stdout);
            fprintf (stderr, "error: Repository lacks these prerequisite "
                             "commits:\n");
        }
        fprintf (stderr, "error: %s \n", bundle->ids[i]);
        missing = 1;
    }
    return missing ? -1 : 0;
}

/* The refs a bundle carries, printed as git prints them. */
static void
git_bundle_heads (const struct git_bundle *bundle)
{
    for (size_t i = 0; i < bundle->n; i++)
        if (bundle->names[i])
            printf ("%s %s\n", bundle->ids[i], bundle->names[i]);
}

static int
git_cmd_bundle (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git bundle (create <file> <rev>... | verify <file> | "
                        "list-heads <file> | unbundle <file>)";
    if (!args) return git_usage (usage);
    const char *verb = args->word->word;
    WORD_LIST *rest = args->next;
    const char *file = NULL;
    const char *revs[64];
    size_t n_revs = 0;
    int all = 0;
    for (WORD_LIST *p = rest; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet") ||
            !strcmp (w, "--progress") || !strcmp (w, "--no-progress") ||
            !strcmp (w, "--version=2") || !strcmp (w, "--all-progress") ||
            !strcmp (w, "--all-progress-implied"))
            continue;
        if (!strcmp (w, "--all")) { all = 1; continue; }
        if (w[0] == '-' && w[1] && strcmp (w, "--")) return git_usage (usage);
        if (!file) file = w;
        else if (n_revs < sizeof revs / sizeof revs[0]) revs[n_revs++] = w;
    }
    if (!file) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (!strcmp (verb, "list-heads") || !strcmp (verb, "verify") ||
        !strcmp (verb, "unbundle")) {
        struct git_bundle bundle;
        /* A file that cannot be read or is not a bundle is answered for
           with a 1, as git answers for it. */
        if (git_bundle_read (file, &bundle) < 0) return 1;
        int rc = 0;
        if (!strcmp (verb, "list-heads")) git_bundle_heads (&bundle);
        else if (!strcmp (verb, "verify")) {
            size_t n_refs = bundle.n - bundle.n_prerequisites;
            fflush (stdout);
            fprintf (stderr, "%s is okay\n", file);
            fflush (stderr);
            if (n_refs == 1) printf ("The bundle contains this ref:\n");
            else printf ("The bundle contains these %zu refs:\n", n_refs);
            git_bundle_heads (&bundle);
            if (!bundle.n_prerequisites)
                printf ("The bundle records a complete history.\n");
            else {
                if (bundle.n_prerequisites == 1)
                    printf ("The bundle requires this ref:\n");
                else printf ("The bundle requires these %zu refs:\n",
                             bundle.n_prerequisites);
                for (size_t i = 0; i < bundle.n; i++)
                    if (!bundle.names[i]) printf ("%s \n", bundle.ids[i]);
            }
            printf ("The bundle uses this hash algorithm: sha1\n");
        } else {
            /* unbundle: the objects go in, the refs are the caller's to
               make, which is what git leaves to whoever asked. */
            /* git answers for a bundle it cannot use with a 1, not a
               fatal. */
            if (git_bundle_prerequisites (ctx, &bundle) < 0) rc = 1;
            else if (bundle.pack_len &&
                     git_store_pack (ctx, bundle.pack, bundle.pack_len) < 0)
                rc = GIT_EXIT_FATAL;
            if (!rc) git_bundle_heads (&bundle);
        }
        git_bundle_release (&bundle);
        return rc;
    }

    if (strcmp (verb, "create")) return git_usage (usage);
    if (!all && !n_revs) {
        fflush (stdout);
        fprintf (stderr, "fatal: Refusing to create empty bundle.\n");
        return GIT_EXIT_FATAL;
    }

    /* What the bundle carries, and what it takes for granted. */
    char (*tips)[41] = NULL;
    char **names = NULL;
    size_t n_tips = 0;
    char (*stops)[41] = NULL;
    char **stop_names = NULL;
    size_t n_stops = 0;
    int rc = 0;

#define GIT_BUNDLE_ADD(list, list_names, count, id, name) do { \
    char (*grown)[41] = realloc ((list), ((count) + 1) * sizeof *grown); \
    char **grown_names = realloc ((list_names), ((count) + 1) * sizeof *grown_names); \
    if (grown) (list) = grown; \
    if (grown_names) (list_names) = grown_names; \
    if (!grown || !grown_names) { rc = GIT_EXIT_FATAL; break; } \
    memcpy ((list)[(count)], (id), 41); \
    (list_names)[(count)] = (name) ? strdup (name) : NULL; \
    (count)++; \
} while (0)

    if (all) {
        bgit_ref *refs = NULL;
        size_t n = 0;
        if (bgit_refs_list (&ctx->repo, "", &refs, &n) == 0) {
            for (size_t i = 0; i < n && !rc; i++)
                GIT_BUNDLE_ADD (tips, names, n_tips, refs[i].sha, refs[i].name);
            bgit_refs_free (refs, n);
        }
        char head[41];
        if (!rc && bgit_ref_resolve (&ctx->repo, "HEAD", head, NULL) == 0 &&
            bgit_all_hex (head))
            GIT_BUNDLE_ADD (tips, names, n_tips, head, "HEAD");
    }
    for (size_t i = 0; i < n_revs && !rc; i++) {
        const char *range = strstr (revs[i], "..");
        if (range) {
            char older[512];
            size_t take = (size_t) (range - revs[i]);
            if (take >= sizeof older) { rc = GIT_EXIT_FATAL; break; }
            memcpy (older, revs[i], take);
            older[take] = '\0';
            char from[41], to[41];
            if (git_resolve (ctx, older, from, NULL) < 0 ||
                git_resolve (ctx, range + 2, to, NULL) < 0) {
                rc = git_fatal ("bad revision '%s'", revs[i]);
                break;
            }
            /* A commit the far end must already have is named with a
               summary of it, as git names one. */
            char subject[4096] = "";
            git_bisect_subject (ctx, from, subject, sizeof subject);
            GIT_BUNDLE_ADD (stops, stop_names, n_stops, from, subject);
            char full[4096] = "";
            char peeled[41];
            if (bgit_ref_read (&ctx->repo, range + 2, peeled) == 0)
                snprintf (full, sizeof full, "%s", range + 2);
            else {
                char ref[4096];
                snprintf (ref, sizeof ref, "refs/heads/%s", range + 2);
                if (bgit_ref_read (&ctx->repo, ref, peeled) == 0)
                    snprintf (full, sizeof full, "%s", ref);
            }
            GIT_BUNDLE_ADD (tips, names, n_tips, to, *full ? full : "HEAD");
        } else {
            char id[41], full[4096] = "";
            char peeled[41];
            if (git_resolve (ctx, revs[i], id, NULL) < 0) {
                rc = git_fatal ("bad revision '%s'", revs[i]);
                break;
            }
            if (bgit_ref_read (&ctx->repo, revs[i], peeled) == 0)
                snprintf (full, sizeof full, "%s", revs[i]);
            else {
                static const char *const places[] = { "refs/heads/%s",
                                                      "refs/tags/%s",
                                                      "refs/remotes/%s" };
                for (size_t k = 0; k < sizeof places / sizeof places[0]; k++) {
                    char ref[4096];
                    snprintf (ref, sizeof ref, places[k], revs[i]);
                    if (bgit_ref_read (&ctx->repo, ref, peeled) == 0) {
                        snprintf (full, sizeof full, "%s", ref);
                        break;
                    }
                }
            }
            GIT_BUNDLE_ADD (tips, names, n_tips, id, *full ? full : "HEAD");
        }
    }
#undef GIT_BUNDLE_ADD

    if (!rc && !n_tips) {
        fflush (stdout);
        fprintf (stderr, "fatal: Refusing to create empty bundle.\n");
        rc = GIT_EXIT_FATAL;
    }

    unsigned char *pack = NULL;
    size_t pack_len = 0;
    if (!rc) {
        const char **roots = calloc (n_tips ? n_tips : 1, sizeof *roots);
        const char **stop = calloc (n_stops ? n_stops : 1, sizeof *stop);
        char (*send)[41] = NULL;
        size_t n_send = 0;
        if (!roots || !stop) rc = GIT_EXIT_FATAL;
        for (size_t i = 0; !rc && i < n_tips; i++) roots[i] = tips[i];
        for (size_t i = 0; !rc && i < n_stops; i++) stop[i] = stops[i];
        if (!rc && bgit_reachable_objects (&ctx->odb, roots, n_tips, stop,
                                           n_stops, &send, &n_send) < 0)
            rc = GIT_EXIT_FATAL;
        struct bgit_pack_idx_entry *entries = NULL;
        unsigned char checksum[20];
        char checksum_hex[41] = "";
        if (!rc && git_pack_build_deltas (&ctx->odb, send, n_send, 1, &pack,
                                          &pack_len, &entries, checksum,
                                          checksum_hex) < 0)
            rc = GIT_EXIT_FATAL;
        free (entries);
        free (send);
        free (roots);
        free (stop);
    }

    if (!rc) {
        FILE *out = fopen (file, "w");
        if (!out) rc = git_fatal ("cannot create '%s'", file);
        else {
            fputs (GIT_BUNDLE_SIGNATURE, out);
            for (size_t i = 0; i < n_stops; i++)
                fprintf (out, "-%s %s\n", stops[i],
                         stop_names[i] ? stop_names[i] : "");
            for (size_t i = 0; i < n_tips; i++)
                fprintf (out, "%s %s\n", tips[i], names[i] ? names[i] : "HEAD");
            fputc ('\n', out);
            if (pack_len && fwrite (pack, 1, pack_len, out) != pack_len)
                rc = git_fatal ("cannot write '%s'", file);
            if (fclose (out) != 0) rc = git_fatal ("cannot write '%s'", file);
        }
    }
    free (pack);
    for (size_t i = 0; i < n_tips; i++) free (names[i]);
    for (size_t i = 0; i < n_stops; i++) free (stop_names[i]);
    free (tips);
    free (names);
    free (stops);
    free (stop_names);
    return rc;
}

/* ---- name-rev ----------------------------------------------------------- */

static void
git_rev_names_release (struct git_rev_names *names)
{
    for (size_t i = 0; i < names->n_slots; i++)
        if (names->slots[i].used) free (names->slots[i].tip);
    free (names->slots);
    memset (names, 0, sizeof *names);
}

/* The slot for an id, made if it is not there yet. */
static struct git_rev_name *
git_rev_name_slot (struct git_rev_names *names, const char *sha, int make)
{
    if (!names->n_slots) {
        if (!make) return NULL;
        names->n_slots = 1024;
        names->slots = calloc (names->n_slots, sizeof *names->slots);
        if (!names->slots) { names->n_slots = 0; return NULL; }
    }
    for (;;) {
        unsigned long hash = 5381;
        for (const char *c = sha; *c; c++) hash = hash * 33 + (unsigned char) *c;
        size_t at = hash % names->n_slots;
        for (size_t step = 0; step < names->n_slots; step++) {
            struct git_rev_name *slot = &names->slots[(at + step) % names->n_slots];
            if (!slot->used) {
                if (!make) return NULL;
                if ((names->n + 1) * 2 > names->n_slots) break;   /* grow first */
                memcpy (slot->sha, sha, 41);
                slot->used = 1;
                slot->tip = NULL;
                slot->generation = 0;
                slot->distance = 0;
                slot->from_tag = 0;
                slot->taggerdate = 0;
                names->n++;
                return slot;
            }
            if (!strcmp (slot->sha, sha)) return slot;
        }
        /* Full, or nearly: take a bigger table and put everything back. */
        if (!make) return NULL;
        size_t bigger = names->n_slots * 4;
        struct git_rev_name *grown = calloc (bigger, sizeof *grown);
        if (!grown) return NULL;
        struct git_rev_name *old = names->slots;
        size_t old_slots = names->n_slots;
        names->slots = grown;
        names->n_slots = bigger;
        names->n = 0;
        for (size_t i = 0; i < old_slots; i++) {
            if (!old[i].used) continue;
            struct git_rev_name *slot = git_rev_name_slot (names, old[i].sha, 1);
            if (slot) {
                slot->tip = old[i].tip;
                slot->generation = old[i].generation;
                slot->distance = old[i].distance;
                slot->from_tag = old[i].from_tag;
                slot->taggerdate = old[i].taggerdate;
            }
        }
        free (old);
    }
}

/* git's own comparison, kept in its own words: an older tag is preferred
   even when it is farther off. */
static int
git_rev_name_better (const struct git_rev_name *held, long long taggerdate,
                     long generation, long distance, int from_tag)
{
    if (!held->tip) return 1;
    if (from_tag && held->from_tag)
        return held->taggerdate > taggerdate ||
               (held->taggerdate == taggerdate && held->distance > distance);
    if (held->from_tag != from_tag) return from_tag;
    if (held->distance != distance) return held->distance > distance;
    return held->generation > generation;
}

/* Walk down from every ref, naming what it reaches. A name that turns out
   better than the one a commit already had replaces it, and the commit is
   looked at again, so the order of the walk does not decide the answer. */
static int
git_name_revs (git_context *ctx, const char *pattern, int only_tags,
               struct git_rev_names *names)
{
    memset (names, 0, sizeof *names);
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (bgit_refs_list (&ctx->repo, only_tags ? "refs/tags/" : "refs/",
                        &refs, &n_refs) < 0)
        return -1;
    char (*pending)[41] = NULL;
    size_t n_pending = 0, cap_pending = 0;

#define GIT_NAME_PUSH(id) do { \
    if (n_pending == cap_pending) { \
        size_t next = cap_pending ? cap_pending * 2 : 256; \
        char (*grown)[41] = realloc (pending, next * sizeof *grown); \
        if (!grown) goto done; \
        pending = grown; \
        cap_pending = next; \
    } \
    memcpy (pending[n_pending++], (id), 41); \
} while (0)

    for (size_t i = 0; i < n_refs; i++) {
        const char *full = refs[i].name;
        if (pattern && fnmatch (pattern, full, 0) != 0) continue;
        /* A branch is named by itself; anything else keeps whatever comes
           after refs/, which is how git shortens them here. */
        const char *shown = full;
        if (!strncmp (shown, "refs/heads/", 11)) shown += 11;
        else if (!strncmp (shown, "refs/", 5)) shown += 5;
        int from_tag = !strncmp (shown, "tags/", 5);
        /* An annotated tag names the commit under it, and says when it was
           made, which is what decides between two tags. */
        char commit[41];
        long long taggerdate = 0;
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        memcpy (commit, refs[i].sha, 41);
        if (bgit_odb_read (&ctx->odb, refs[i].sha, &type, &data, &len) == 0) {
            if (type == BGIT_TAG) {
                const char *body = (const char *) data;
                for (size_t at = 0; at < len;) {
                    const char *nl = memchr (body + at, '\n', len - at);
                    size_t line = nl ? (size_t) (nl - (body + at)) : len - at;
                    if (!line) break;
                    if (!strncmp (body + at, "tagger ", 7)) {
                        const char *right = memrchr (body + at, '>', line);
                        if (right) taggerdate = strtoll (right + 1, NULL, 10);
                    }
                    if (!nl) break;
                    at += line + 1;
                }
            }
            free (data);
        }
        if (bgit_peel_to_type (&ctx->odb, refs[i].sha, BGIT_COMMIT, commit) < 0)
            continue;
        /* A ref that is not an annotated tag is dated by the commit it
           names, which is what decides between two of them; and one that
           had to be peeled names the commit as <tag>^0, since the tag's own
           name is the tag object. */
        int peeled = strcmp (refs[i].sha, commit) != 0;
        char named[4200];
        snprintf (named, sizeof named, "%s%s", shown, peeled ? "^0" : "");
        if (!taggerdate) {
            struct git_commit read;
            if (git_commit_read (ctx, commit, &read) == 0) {
                taggerdate = strtoll (read.committer_date, NULL, 10);
                git_commit_release (&read);
            }
        }
        struct git_rev_name *slot = git_rev_name_slot (names, commit, 1);
        if (!slot) continue;
        if (!git_rev_name_better (slot, taggerdate, 0, 0, from_tag)) continue;
        free (slot->tip);
        slot->tip = strdup (named);
        slot->generation = 0;
        slot->distance = 0;
        slot->from_tag = from_tag;
        slot->taggerdate = taggerdate;
        if (!slot->tip) continue;
        GIT_NAME_PUSH (commit);
    }

    while (n_pending) {
        char sha[41];
        memcpy (sha, pending[--n_pending], 41);
        struct git_rev_name *held = git_rev_name_slot (names, sha, 0);
        if (!held || !held->tip) continue;
        char tip[4096];
        snprintf (tip, sizeof tip, "%s", held->tip);
        long generation = held->generation, distance = held->distance;
        int from_tag = held->from_tag;
        long long taggerdate = held->taggerdate;
        char parents[BGIT_MAX_PARENTS][41];
        int count = bgit_commit_parents (&ctx->odb, sha, parents,
                                        BGIT_MAX_PARENTS);
        for (int i = 0; i < count; i++) {
            char next_tip[4096];
            long next_generation, next_distance;
            if (i == 0) {
                snprintf (next_tip, sizeof next_tip, "%s", tip);
                next_generation = generation + 1;
                next_distance = distance + 1;
            } else {
                /* Off the first-parent line the name says which parent it
                   went down, and counting starts again from there. */
                char written[4096];
                git_rev_name_written (tip, generation, 0, written,
                                      sizeof written);
                snprintf (next_tip, sizeof next_tip, "%s^%d", written, i + 1);
                next_generation = 0;
                next_distance = distance + GIT_MERGE_WEIGHT;
            }
            struct git_rev_name *slot = git_rev_name_slot (names, parents[i], 1);
            if (!slot) continue;
            if (!git_rev_name_better (slot, taggerdate, next_generation,
                                      next_distance, from_tag))
                continue;
            char *kept = strdup (next_tip);
            if (!kept) continue;
            free (slot->tip);
            slot->tip = kept;
            slot->generation = next_generation;
            slot->distance = next_distance;
            slot->from_tag = from_tag;
            slot->taggerdate = taggerdate;
            GIT_NAME_PUSH (parents[i]);
        }
    }
#undef GIT_NAME_PUSH
 done:
    free (pending);
    bgit_refs_free (refs, n_refs);
    return 0;
}

/* A tip and the steps down from it, written out: with steps to add, a
   trailing ^0 on the tip goes, since <tag>^0~1 and <tag>~1 name the same
   commit and git writes the shorter. */
static void
git_rev_name_written (const char *tip, long generation, int strip, char *out,
                      size_t outsz)
{
    if (strip && !strncmp (tip, "tags/", 5)) tip += 5;
    if (!generation) {
        snprintf (out, outsz, "%s", tip);
        return;
    }
    size_t len = strlen (tip);
    if (len > 2 && !strcmp (tip + len - 2, "^0")) len -= 2;
    snprintf (out, outsz, "%.*s~%ld", (int) len, tip, generation);
}

/* What a commit is called, for `name-rev` to print: the ref's name with the
   steps down from it, or "undefined" when no ref reaches it. */
static void
git_rev_name_of (const struct git_rev_names *names, const char *sha, int strip,
                 char *out, size_t outsz)
{
    const struct git_rev_name *held =
        git_rev_name_slot ((struct git_rev_names *) names, sha, 0);
    if (!held || !held->tip) {
        snprintf (out, outsz, "undefined");
        return;
    }
    git_rev_name_written (held->tip, held->generation, strip, out, outsz);
}

static int
git_cmd_name_rev (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git name-rev [--name-only] [--tags] "
                        "[--refs=<pattern>] [--all] [--annotate-stdin] "
                        "<commit>...";
    int name_only = 0, only_tags = 0, all = 0, from_stdin = 0, deprecated = 0;
    const char *pattern = NULL;
    const char *revs[64];
    size_t n_revs = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--name-only")) name_only = 1;
        else if (!strcmp (w, "--tags")) only_tags = 1;
        else if (!strncmp (w, "--refs=", 7)) pattern = w + 7;
        else if (!strcmp (w, "--all")) all = 1;
        else if (!strcmp (w, "--annotate-stdin")) from_stdin = 1;
        else if (!strcmp (w, "--stdin")) { from_stdin = 1; deprecated = 1; }
        else if (!strcmp (w, "--no-undefined") || !strcmp (w, "--always")) ;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_revs < sizeof revs / sizeof revs[0]) revs[n_revs++] = w;
    }
    if (deprecated)
        fprintf (stderr, "warning: --stdin is deprecated. Please use "
                         "--annotate-stdin instead, which is functionally "
                         "equivalent.\nThis option will be removed in a future "
                         "release.\n");
    if (!all && !from_stdin && !n_revs) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    struct git_rev_names names;
    if (git_name_revs (ctx, pattern, only_tags, &names) < 0)
        return GIT_EXIT_FATAL;
    int rc = 0;
    char shown[4096];
    if (all) {
        /* Every commit the store holds that a ref reaches. */
        char (*ids)[41] = NULL;
        size_t n = 0;
        if (bgit_odb_list (&ctx->odb, &ids, &n) == 0) {
            for (size_t i = 0; i < n; i++) {
                struct git_rev_name *held = git_rev_name_slot (&names, ids[i], 0);
                if (!held || !held->tip) continue;
                git_rev_name_of (&names, ids[i], only_tags, shown, sizeof shown);
                printf ("%s %s\n", ids[i], shown);
            }
            free (ids);
        }
    }
    for (size_t i = 0; i < n_revs; i++) {
        char id[41];
        if (git_resolve (ctx, revs[i], id, NULL) < 0) {
            rc = git_fatal ("Could not get sha1 for %s. Skipping.", revs[i]);
            continue;
        }
        char commit[41];
        if (bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0)
            memcpy (commit, id, 41);
        git_rev_name_of (&names, commit, only_tags, shown, sizeof shown);
        if (name_only) printf ("%s\n", shown);
        else printf ("%s %s\n", revs[i], shown);
    }
    if (from_stdin) {
        char line[8192];
        clearerr (stdin);
        while (fgets (line, sizeof line, stdin)) {
            /* Every id in the line is named where it stands, which is what
               annotating a stream means. */
            size_t at = 0;
            while (line[at]) {
                size_t run = 0;
                while (isxdigit ((unsigned char) line[at + run])) run++;
                if (run >= 40) {
                    char id[41];
                    memcpy (id, line + at, 40);
                    id[40] = '\0';
                    char commit[41];
                    if (bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT,
                                           commit) < 0)
                        memcpy (commit, id, 41);
                    struct git_rev_name *held =
                        git_rev_name_slot (&names, commit, 0);
                    fwrite (line + at, 1, 40, stdout);
                    if (held && held->tip) {
                        git_rev_name_of (&names, commit, only_tags, shown,
                                         sizeof shown);
                        printf (" (%s)", shown);
                    }
                    at += 40;
                    continue;
                }
                if (run) { fwrite (line + at, 1, run, stdout); at += run; continue; }
                fputc (line[at++], stdout);
            }
        }
    }
    git_rev_names_release (&names);
    return rc;
}

/* ---- notes -------------------------------------------------------------- */

/* A note is a blob in a tree under refs/notes/commits, named by the id of
   the object it is about. git fans that name out into directories once a
   tree grows large; up to that size, and that is every repository a person
   reads notes in by hand, the name is the whole forty digits. */
/* One note: the object it is about and the blob that holds the text. */
struct git_note {
    char object[41];
    char blob[41];
};

struct git_notes {
    struct git_note *held;
    size_t n, cap;
};

static int
git_notes_add_held (struct git_notes *notes, const char *object,
                    const char *blob)
{
    if (notes->n == notes->cap) {
        size_t next = notes->cap ? notes->cap * 2 : 32;
        struct git_note *grown = realloc (notes->held, next * sizeof *grown);
        if (!grown) return -1;
        notes->held = grown;
        notes->cap = next;
    }
    memcpy (notes->held[notes->n].object, object, 41);
    memcpy (notes->held[notes->n].blob, blob, 41);
    notes->n++;
    return 0;
}

/* A path in a notes tree is the annotated object's id, with the slashes of
   whatever fanout it was written at taken back out. */
static int
git_notes_collect (void *data, const char *mode, const char *type,
                   const char *sha, const char *path)
{
    struct git_notes *notes = data;
    if (strcmp (type, "blob")) return 0;
    (void) mode;
    char name[64];
    size_t at = 0;
    for (const char *c = path; *c && at < sizeof name - 1; c++)
        if (*c != '/') name[at++] = *c;
    name[at] = '\0';
    if (at != 40 || !bgit_all_hex (name)) return 0;
    return git_notes_add_held (notes, name, sha) < 0 ? -1 : 0;
}

/* What the notes ref holds now, sorted by the object each note is about,
   which is the order the tree keeps them in. */
static int
git_notes_read (git_context *ctx, const char *ref, struct git_notes *notes)
{
    memset (notes, 0, sizeof *notes);
    char commit[41];
    if (bgit_ref_read (&ctx->repo, ref, commit) != 0) return 0;  /* none yet */
    char tree[41];
    if (bgit_commit_tree (&ctx->odb, commit, tree) != 0) return 0;
    if (bgit_tree_walk (&ctx->odb, tree, "", 1, 0, git_notes_collect,
                        notes) < 0) {
        free (notes->held);
        memset (notes, 0, sizeof *notes);
        return -1;
    }
    return 0;
}

static const char *
git_notes_find (const struct git_notes *notes, const char *object)
{
    for (size_t i = 0; i < notes->n; i++)
        if (!strcmp (notes->held[i].object, object)) return notes->held[i].blob;
    return NULL;
}

static int
git_notes_order (const void *a, const void *b)
{
    return strcmp (((const struct git_note *) a)->object,
                   ((const struct git_note *) b)->object);
}

/* Write the notes out as a tree and put a commit on the notes ref, with the
   message git gives that kind of change. */
static int
git_notes_commit (git_context *ctx, const char *ref, struct git_notes *notes,
                  const char *reason)
{
    qsort (notes->held, notes->n, sizeof *notes->held, git_notes_order);
    bgit_index_entry *entries = calloc (notes->n ? notes->n : 1,
                                        sizeof *entries);
    if (!entries) return -1;
    for (size_t i = 0; i < notes->n; i++) {
        entries[i].mode = 0100644;
        bgit_hex_to_sha (notes->held[i].blob, entries[i].sha);
        entries[i].path = strdup (notes->held[i].object);
        entries[i].flags = (uint16_t) strlen (notes->held[i].object);
        if (!entries[i].path) {
            bgit_index_free_entries (entries, notes->n);
            return -1;
        }
    }
    char tree[41];
    int rc = bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], entries,
                              notes->n, tree);
    bgit_index_free_entries (entries, notes->n);
    if (rc < 0) return -1;

    char parent[41];
    int have_parent = bgit_ref_read (&ctx->repo, ref, parent) == 0;
    char author[1024], committer[1024];
    if (git_identities (ctx, author, sizeof author, committer,
                        sizeof committer))
        return -1;
    char body[4096];
    int len = snprintf (body, sizeof body,
                        "tree %s\n%s%s%sauthor %s\ncommitter %s\n\n%s\n",
                        tree, have_parent ? "parent " : "",
                        have_parent ? parent : "", have_parent ? "\n" : "",
                        author, committer, reason);
    if (len < 0 || (size_t) len >= sizeof body) return -1;
    char commit[41];
    if (bgit_write_object (ctx->odb.object_dirs[0], "commit",
                           (const unsigned char *) body, (size_t) len, 1,
                           commit) < 0)
        return -1;
    /* The reflog entry says what kind of change it was, with git's prefix. */
    char logged[256];
    snprintf (logged, sizeof logged, "notes: %s", reason);
    return bgit_ref_update (&ctx->repo, ref, commit,
                            have_parent ? parent : "", logged);
}

/* The text of a note, as `git notes show` prints it and `%N` gives it. */
static int
git_note_text (git_context *ctx, const char *ref, const char *object,
               char **out, size_t *len)
{
    *out = NULL;
    *len = 0;
    struct git_notes notes;
    if (git_notes_read (ctx, ref, &notes) < 0) return -1;
    const char *blob = git_notes_find (&notes, object);
    int rc = -1;
    if (blob) {
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t n = 0;
        if (bgit_odb_read (&ctx->odb, blob, &type, &data, &n) == 0 &&
            type == BGIT_BLOB) {
            *out = (char *) data;
            *len = n;
            rc = 0;
        } else free (data);
    }
    free (notes.held);
    return rc;
}

/* Which notes ref is in play: --ref, then GIT_NOTES_REF, then the
   configured core.notesRef, then refs/notes/commits. A short name is
   taken to be under refs/notes/. */
static void
git_notes_ref (git_context *ctx, const char *named, char *out, size_t outsz)
{
    char held[512];
    const char *value = named;
    if (!value) value = bgit_env ("GIT_NOTES_REF", held, sizeof held);
    if (!value) value = bgit_config_get (&ctx->cfg, "core.notesref");
    if (!value || !*value) value = GIT_NOTES_REF;
    if (!strncmp (value, "refs/", 5)) snprintf (out, outsz, "%s", value);
    else snprintf (out, outsz, "refs/notes/%s", value);
}

/* The text a -m or -F gave, joined the way git joins several of them. */
struct git_note_message {
    char *text;
    size_t len, cap;
};

static int
git_note_message_add (struct git_note_message *message, const char *text,
                      size_t len)
{
    size_t want = message->len + len + 2;
    if (want > message->cap) {
        size_t next = message->cap ? message->cap : 256;
        while (next < want) next *= 2;
        char *grown = realloc (message->text, next);
        if (!grown) return -1;
        message->text = grown;
        message->cap = next;
    }
    if (message->len) message->text[message->len++] = '\n';
    memcpy (message->text + message->len, text, len);
    message->len += len;
    if (!message->len || message->text[message->len - 1] != '\n')
        message->text[message->len++] = '\n';
    message->text[message->len] = '\0';
    return 0;
}

static int
git_cmd_notes (git_context *ctx, WORD_LIST *args)
{
    const char *usage =
        "git notes [--ref <ref>] (list [<object>] | add [-f] [-m <msg>] "
        "[-F <file>] [<object>] | append [-m <msg>] [<object>] | "
        "copy [-f] <from> <to> | show [<object>] | remove [<object>...] | "
        "prune [-n] | get-ref)";
    const char *named_ref = NULL, *verb = NULL;
    const char *objects[64];
    size_t n_objects = 0;
    int force = 0, dry_run = 0, ignore_missing = 0;
    struct git_note_message message = { NULL, 0, 0 };
    int have_message = 0;
    int status = 0;

    for (WORD_LIST *p = args; p && !status; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--ref") && p->next) { named_ref = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "--ref=", 6)) named_ref = w + 6;
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (!strcmp (w, "-n") || !strcmp (w, "--dry-run")) dry_run = 1;
        else if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) ;
        else if (!strcmp (w, "--ignore-missing")) ignore_missing = 1;
        else if ((!strcmp (w, "-m") || !strcmp (w, "--message")) && p->next) {
            p = p->next;
            have_message = 1;
            if (git_note_message_add (&message, p->word->word,
                                      strlen (p->word->word)) < 0)
                status = GIT_EXIT_FATAL;
        } else if ((!strcmp (w, "-F") || !strcmp (w, "--file")) && p->next) {
            p = p->next;
            unsigned char *text = NULL;
            size_t len = 0;
            if (bgit_slurp_file (p->word->word, &text, &len) < 0)
                status = GIT_EXIT_FATAL;
            else {
                have_message = 1;
                if (git_note_message_add (&message, (const char *) text,
                                          len) < 0)
                    status = GIT_EXIT_FATAL;
                free (text);
            }
        } else if (w[0] == '-' && w[1]) { free (message.text); return git_usage (usage); }
        else if (!verb) verb = w;
        else if (n_objects < sizeof objects / sizeof objects[0])
            objects[n_objects++] = w;
    }
    if (status) { free (message.text); return status; }
    if (!verb) verb = "list";
    if (git_context_open (ctx) != 0) { free (message.text); return GIT_EXIT_FATAL; }

    char ref[512];
    git_notes_ref (ctx, named_ref, ref, sizeof ref);
    if (!strcmp (verb, "get-ref")) {
        free (message.text);
        printf ("%s\n", ref);
        return 0;
    }

    struct git_notes notes;
    if (git_notes_read (ctx, ref, &notes) < 0) {
        free (message.text);
        return GIT_EXIT_FATAL;
    }

    if (!strcmp (verb, "list") || !strcmp (verb, "show")) {
        int rc = 0;
        if (!n_objects && !strcmp (verb, "list")) {
            qsort (notes.held, notes.n, sizeof *notes.held, git_notes_order);
            for (size_t i = 0; i < notes.n; i++)
                printf ("%s %s\n", notes.held[i].blob, notes.held[i].object);
        } else {
            const char *name = n_objects ? objects[0] : "HEAD";
            char id[41];
            if (git_resolve (ctx, name, id, NULL) < 0)
                rc = git_fatal ("Failed to resolve '%s' as a valid ref.", name);
            else {
                const char *blob = git_notes_find (&notes, id);
                if (!blob) {
                    fflush (stdout);
                    fprintf (stderr, "error: no note found for object %s.\n", id);
                    rc = 1;
                } else if (!strcmp (verb, "list")) printf ("%s\n", blob);
                else {
                    enum bgit_type type;
                    unsigned char *data = NULL;
                    size_t len = 0;
                    if (bgit_odb_read (&ctx->odb, blob, &type, &data, &len) < 0)
                        rc = GIT_EXIT_FATAL;
                    else {
                        fwrite (data, 1, len, stdout);
                        free (data);
                    }
                }
            }
        }
        free (notes.held);
        free (message.text);
        return rc;
    }

    if (!strcmp (verb, "prune")) {
        struct git_notes kept;
        memset (&kept, 0, sizeof kept);
        int changed = 0, rc = 0;
        for (size_t i = 0; i < notes.n; i++) {
            if (bgit_odb_has (&ctx->odb, notes.held[i].object)) {
                if (git_notes_add_held (&kept, notes.held[i].object,
                                        notes.held[i].blob) < 0)
                    rc = GIT_EXIT_FATAL;
                continue;
            }
            changed = 1;
            if (dry_run) printf ("%s\n", notes.held[i].object);
        }
        if (!rc && changed && !dry_run &&
            git_notes_commit (ctx, ref, &kept,
                              "Notes removed by 'git notes prune'") < 0)
            rc = GIT_EXIT_FATAL;
        free (kept.held);
        free (notes.held);
        free (message.text);
        return rc;
    }

    /* The rest change a note, so they need the object it is about. */
    int rc = 0;
    if (!strcmp (verb, "add") || !strcmp (verb, "append") ||
        !strcmp (verb, "edit")) {
        const char *name = n_objects ? objects[0] : "HEAD";
        char id[41];
        if (git_resolve (ctx, name, id, NULL) < 0)
            rc = git_fatal ("Failed to resolve '%s' as a valid ref.", name);
        else if (!have_message)
            rc = git_fatal ("this build's git notes needs -m or -F; it does "
                            "not open an editor");
        else {
            const char *existing = git_notes_find (&notes, id);
            if (existing && !strcmp (verb, "add") && !force) {
                fflush (stdout);
                fprintf (stderr,
                         "error: Cannot add notes. Found existing notes for "
                         "object %s. Use '-f' to overwrite existing notes\n",
                         id);
                rc = 1;
            } else {
                if (existing && strcmp (verb, "append")) {
                    fflush (stdout);
                    fprintf (stderr,
                             "Overwriting existing notes for object %s\n", id);
                }
                char *text = NULL;
                size_t len = 0;
                if (existing && !strcmp (verb, "append")) {
                    enum bgit_type type;
                    unsigned char *data = NULL;
                    size_t n = 0;
                    if (bgit_odb_read (&ctx->odb, existing, &type, &data,
                                       &n) == 0) {
                        /* git puts a blank line between what was there and
                           what is being added. */
                        len = n + 1 + message.len;
                        text = malloc (len + 1);
                        if (text) {
                            memcpy (text, data, n);
                            text[n] = '\n';
                            memcpy (text + n + 1, message.text, message.len);
                            text[len] = '\0';
                        }
                        free (data);
                    }
                }
                if (!text) {
                    len = message.len;
                    text = malloc (len + 1);
                    if (text) memcpy (text, message.text, len + 1);
                }
                char blob[41];
                if (!text ||
                    bgit_write_object (ctx->odb.object_dirs[0], "blob",
                                       (const unsigned char *) text, len, 1,
                                       blob) < 0)
                    rc = GIT_EXIT_FATAL;
                else {
                    for (size_t i = 0; i < notes.n; i++)
                        if (!strcmp (notes.held[i].object, id))
                            memcpy (notes.held[i].blob, blob, 41);
                    if (!existing && git_notes_add_held (&notes, id, blob) < 0)
                        rc = GIT_EXIT_FATAL;
                    char reason[128];
                    snprintf (reason, sizeof reason, "Notes added by 'git notes %s'",
                              verb);
                    if (!rc && git_notes_commit (ctx, ref, &notes, reason) < 0)
                        rc = GIT_EXIT_FATAL;
                }
                free (text);
            }
        }
    } else if (!strcmp (verb, "copy")) {
        if (n_objects < 2) rc = git_usage (usage);
        else {
            char from[41], to[41];
            if (git_resolve (ctx, objects[0], from, NULL) < 0)
                rc = git_fatal ("Failed to resolve '%s' as a valid ref.",
                                objects[0]);
            else if (git_resolve (ctx, objects[1], to, NULL) < 0)
                rc = git_fatal ("Failed to resolve '%s' as a valid ref.",
                                objects[1]);
            else {
                const char *source = git_notes_find (&notes, from);
                const char *existing = git_notes_find (&notes, to);
                if (!source) {
                    fflush (stdout);
                    fprintf (stderr, "error: missing notes on source object "
                                     "%s. Cannot copy.\n", from);
                    rc = 1;
                } else if (existing && !force) {
                    fflush (stdout);
                    fprintf (stderr,
                             "error: Cannot copy notes. Found existing notes "
                             "for object %s. Use '-f' to overwrite existing "
                             "notes\n", to);
                    rc = 1;
                } else {
                    if (existing) {
                        fflush (stdout);
                        fprintf (stderr,
                                 "Overwriting existing notes for object %s\n",
                                 to);
                    }
                    char blob[41];
                    memcpy (blob, source, 41);
                    for (size_t i = 0; i < notes.n; i++)
                        if (!strcmp (notes.held[i].object, to))
                            memcpy (notes.held[i].blob, blob, 41);
                    if (!existing && git_notes_add_held (&notes, to, blob) < 0)
                        rc = GIT_EXIT_FATAL;
                    if (!rc &&
                        git_notes_commit (ctx, ref, &notes,
                                          "Notes added by 'git notes copy'") < 0)
                        rc = GIT_EXIT_FATAL;
                }
            }
        }
    } else if (!strcmp (verb, "remove")) {
        if (!n_objects) { objects[0] = "HEAD"; n_objects = 1; }
        int changed = 0;
        for (size_t k = 0; k < n_objects && !rc; k++) {
            char id[41];
            if (git_resolve (ctx, objects[k], id, NULL) < 0) {
                if (ignore_missing) continue;
                rc = git_fatal ("Failed to resolve '%s' as a valid ref.",
                                objects[k]);
                break;
            }
            size_t at = notes.n;
            for (size_t i = 0; i < notes.n; i++)
                if (!strcmp (notes.held[i].object, id)) { at = i; break; }
            if (at == notes.n) {
                fflush (stdout);
                if (ignore_missing) {
                    fprintf (stderr, "Object %s has no note\n", objects[k]);
                    continue;
                }
                fprintf (stderr, "error: no note found for object %s.\n", id);
                rc = 1;
                break;
            }
            fflush (stdout);
            fprintf (stderr, "Removing note for object %s\n", objects[k]);
            memmove (&notes.held[at], &notes.held[at + 1],
                     (notes.n - at - 1) * sizeof *notes.held);
            notes.n--;
            changed = 1;
        }
        if (!rc && changed &&
            git_notes_commit (ctx, ref, &notes,
                              "Notes removed by 'git notes remove'") < 0)
            rc = GIT_EXIT_FATAL;
    } else {
        rc = git_usage (usage);
    }
    free (notes.held);
    free (message.text);
    return rc;
}

/* ---- prune -------------------------------------------------------------- */

/* Written out below git prune, which is what asks for it; git gc asks too. */
static int git_prune_run (git_context *ctx, int dry_run, int verbose,
                          time_t expire, const char **heads, size_t n_heads);

/* A loose object file older than EXPIRE and reached by nothing goes; the
   fanout directory goes with it once it is empty, and so does a temporary
   file left behind by a write that did not finish. */
static int
git_cmd_prune (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git prune [-n | --dry-run] [-v | --verbose] "
                        "[--expire <time>] [--] [<head>...]";
    int dry_run = 0, verbose = 0;
    time_t expire = (time_t) -1;        /* -1: whatever its age */
    const char *heads[64];
    size_t n_heads = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-n") || !strcmp (w, "--dry-run")) dry_run = 1;
        else if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "--progress") || !strcmp (w, "--no-progress")) ;
        else if (!strcmp (w, "--expire")) {
            if (!p->next) return git_usage (usage);
            p = p->next;
            expire = (time_t) git_approxidate (p->word->word);
        } else if (!strncmp (w, "--expire=", 9)) {
            expire = (time_t) git_approxidate (w + 9);
        } else if (!strcmp (w, "--")) ;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_heads < sizeof heads / sizeof heads[0]) heads[n_heads++] = w;
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    return git_prune_run (ctx, dry_run, verbose, expire, heads, n_heads);
}

static int
git_prune_run (git_context *ctx, int dry_run, int verbose, time_t expire,
               const char **heads, size_t n_heads)
{
    struct git_fsck walk_state;
    memset (&walk_state, 0, sizeof walk_state);
    walk_state.ctx = ctx;
    if (git_fsck_collect (&walk_state) < 0) return GIT_EXIT_FATAL;
    /* Nothing is read for its own sake here: the walk reads what it reaches
       and the rest is only asked what it is on the way out. */
    for (size_t i = 0; i < walk_state.n; i++) walk_state.objects[i].present = 1;

    struct git_fsck_walk walk;
    memset (&walk, 0, sizeof walk);
    git_fsck_heads (&walk_state, &walk, 1, 0, 0);
    for (size_t i = 0; i < n_heads; i++) {
        char full[41];
        if (git_resolve (ctx, heads[i], full, NULL) == 0)
            git_fsck_push (&walk_state, &walk, full);
        else {
            free (walk.pending);
            free (walk_state.objects);
            free (walk_state.absent);
            return git_fatal ("bad object %s", heads[i]);
        }
    }
    git_fsck_reach (&walk_state, &walk);

    /* Only the objects this repository writes, loose and in its own
       directory: an alternate's are not ours to remove, and a packed object
       is not removed one at a time. */
    const char *objects = ctx->odb.n_object_dirs ? ctx->odb.object_dirs[0] : NULL;
    int rc = 0;
    if (objects) {
        DIR *top = opendir (objects);
        if (top) {
            struct dirent *entry;
            while ((entry = readdir (top))) {
                char path[4096];
                if (!strncmp (entry->d_name, "tmp_obj_", 8)) {
                    if ((size_t) snprintf (path, sizeof path, "%s/%s", objects,
                                           entry->d_name) >= sizeof path)
                        continue;
                    struct stat st;
                    if (lstat (path, &st) < 0 || !S_ISREG (st.st_mode)) continue;
                    if (expire != (time_t) -1 && st.st_mtime > expire) continue;
                    if (dry_run || verbose)
                        printf ("Removing stale temporary file %s\n",
                                git_fsck_shown_path (&walk_state, path));
                    if (!dry_run) unlink (path);
                    continue;
                }
                if (strlen (entry->d_name) != 2 ||
                    !isxdigit ((unsigned char) entry->d_name[0]) ||
                    !isxdigit ((unsigned char) entry->d_name[1]))
                    continue;
                char dir[4096];
                if ((size_t) snprintf (dir, sizeof dir, "%s/%s", objects,
                                       entry->d_name) >= sizeof dir)
                    continue;
                DIR *inner = opendir (dir);
                if (!inner) continue;
                struct dirent *one;
                while ((one = readdir (inner))) {
                    if (strlen (one->d_name) != 38) continue;
                    char sha[41];
                    sha[0] = entry->d_name[0];
                    sha[1] = entry->d_name[1];
                    memcpy (sha + 2, one->d_name, 38);
                    sha[40] = '\0';
                    if (!bgit_all_hex (sha)) continue;
                    long at = git_fsck_find (&walk_state, sha);
                    if (at >= 0 && walk_state.objects[at].reachable) continue;
                    if ((size_t) snprintf (path, sizeof path, "%s/%s", dir,
                                           one->d_name) >= sizeof path)
                        continue;
                    struct stat st;
                    if (lstat (path, &st) < 0 || !S_ISREG (st.st_mode)) continue;
                    if (expire != (time_t) -1 && st.st_mtime > expire) continue;
                    if (dry_run || verbose) {
                        enum bgit_type type = BGIT_UNKNOWN;
                        unsigned char *data = NULL;
                        size_t len = 0;
                        if (bgit_odb_read (&ctx->odb, sha, &type, &data,
                                           &len) == 0)
                            free (data);
                        printf ("%s %s\n", sha, bgit_type_name (type));
                    }
                    if (!dry_run && unlink (path) < 0) {
                        fflush (stdout);
                        fprintf (stderr, "error: unable to unlink %s: %s\n",
                                 path, strerror (errno));
                        rc = 1;
                    }
                }
                closedir (inner);
                if (!dry_run) rmdir (dir);   /* only when it is empty */
            }
            closedir (top);
        }
    }
    free (walk.pending);
    free (walk_state.objects);
    free (walk_state.absent);
    return rc;
}

/* ---- format-patch ------------------------------------------------------ */

/* A subject as a file name: what git keeps of it is letters, digits, dots
   and underscores, with a single dash for every run of anything else. */
static void
git_patch_name (const char *subject, char *out, size_t outsz)
{
    size_t at = 0;
    int gap = 0;
    for (const char *p = subject; *p && at + 1 < outsz; p++) {
        unsigned char c = (unsigned char) *p;
        if (isalnum (c) || c == '.' || c == '_') {
            if (gap && at + 1 < outsz) out[at++] = '-';
            gap = 0;
            if (at + 1 < outsz) out[at++] = (char) c;
        } else
            gap = 1;
    }
    while (at && out[at - 1] == '.') at--;
    out[at] = '\0';
}

static int
git_cmd_format_patch (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git format-patch [--stdout] [-o <dir>] [-<n>] "
                        "[--numbered | --no-numbered] [<since> | <range>]";
    int to_stdout = 0, numbered = -1;
    const char *directory = NULL;
    long limit = -1;
    const char *revs[8], *excludes[8];
    int n_revs = 0, n_excludes = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--stdout")) to_stdout = 1;
        else if ((!strcmp (w, "-o") || !strcmp (w, "--output-directory")) &&
                 p->next)
            directory = (p = p->next)->word->word;
        else if (!strncmp (w, "--output-directory=", 19)) directory = w + 19;
        else if (!strcmp (w, "--numbered") || !strcmp (w, "-n")) numbered = 1;
        else if (!strcmp (w, "--no-numbered") || !strcmp (w, "-N")) numbered = 0;
        else if (w[0] == '-' && git_all_digits (w + 1)) limit = atol (w + 1);
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (strstr (w, "..")) {
            char *range = strdup (w);
            if (!range) return GIT_EXIT_FATAL;
            char *dots = strstr (range, "..");
            *dots = '\0';
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes) ||
                n_revs >= (int) (sizeof revs / sizeof *revs)) {
                free (range);
                return git_fatal ("too many revisions");
            }
            excludes[n_excludes++] = *range ? range : "HEAD";
            revs[n_revs++] = dots[2] ? dots + 2 : "HEAD";
        }
        else if (n_revs < (int) (sizeof revs / sizeof *revs)) {
            /* A revision on its own is where to start after, as git reads
               it here. */
            if (limit < 0 && n_excludes < (int) (sizeof excludes / sizeof *excludes))
                excludes[n_excludes++] = w;
            else revs[n_revs++] = w;
        }
        else return git_fatal ("too many revisions");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!n_revs) revs[n_revs++] = "HEAD";

    char (*walk)[41] = NULL;
    size_t n_walk = 0;
    if (git_collect_commits (ctx, revs, n_revs, excludes, n_excludes, 0, limit,
                             &walk, &n_walk) < 0)
        return git_fatal ("cannot read the history");
    if (numbered < 0) numbered = n_walk > 1;

    int status = 0;
    for (size_t i = 0; i < n_walk && !status; i++) {
        /* Oldest first, which is the other way round from the walk. */
        struct git_commit commit;
        if (git_commit_read (ctx, walk[n_walk - 1 - i], &commit) < 0) continue;
        char subject[4096], date[128];
        git_subject (&commit, subject, sizeof subject);
        git_format_date_mode (commit.author_date, GIT_DATE_RFC2822, date,
                              sizeof date);
        FILE *out = stdout;
        char path[4096] = "";
        /* One stream of mail has a blank line between its messages. */
        if (to_stdout && i) fputc ('\n', stdout);
        if (!to_stdout) {
            char name[512];
            git_patch_name (subject, name, sizeof name);
            snprintf (path, sizeof path, "%s%s%04zu-%.52s.patch",
                      directory ? directory : "", directory ? "/" : "", i + 1,
                      name);
            if (directory) mkdir (directory, 0777);
            out = fopen (path, "w");
            if (!out) {
                git_commit_release (&commit);
                status = git_fatal ("cannot open %s", path);
                break;
            }
        }
        fprintf (out, "From %s Mon Sep 17 00:00:00 2001\n", commit.id);
        fprintf (out, "From: %s <%s>\n", commit.author_name,
                 commit.author_email);
        fprintf (out, "Date: %s\n", date);
        if (numbered)
            fprintf (out, "Subject: [PATCH %zu/%zu] %s\n\n", i + 1, n_walk,
                     subject);
        else fprintf (out, "Subject: [PATCH] %s\n\n", subject);
        const char *body = git_body (&commit);
        if (*body) {
            fputs (body, out);
            if (body[strlen (body) - 1] != '\n') fputc ('\n', out);
        }
        fprintf (out, "---\n");
        struct git_diff_format diff;
        git_diff_format_init (&diff);
        diff.stat = 1;
        diff.summary = 1;
        diff.patch = 1;
        git_commit_diff (ctx, out, &commit, &diff, NULL, 0, NULL);
        fprintf (out, "-- \n%s\n\n", GIT_VERSION_STRING + strlen ("git version "));
        if (out != stdout) {
            fclose (out);
            printf ("%s\n", path);
        }
        git_commit_release (&commit);
    }
    free (walk);
    return status;
}

/* ---- grep -------------------------------------------------------------- */

struct git_grep {
    regex_t *patterns;
    const char **fixed;          /* the same patterns, when they stand for
                                    themselves */
    int n_patterns;
    int ignore_case, line_numbers, names_only, count_only, no_name;
    int word, invert;
};

/* Is the match at [start, end) a whole word? */
static int
git_grep_word (const char *line, size_t len, size_t start, size_t end)
{
    if (start && (isalnum ((unsigned char) line[start - 1]) ||
                  line[start - 1] == '_'))
        return 0;
    if (end < len && (isalnum ((unsigned char) line[end]) ||
                      line[end] == '_'))
        return 0;
    return 1;
}

/* Does one run of text — a line, or a piece of one between NUL bytes —
   answer to any of the patterns? */
static int
git_grep_piece (const struct git_grep *grep, const char *line, size_t len,
                int at_start, int at_end)
{
    char held[65536];
    if (len >= sizeof held) len = sizeof held - 1;
    memcpy (held, line, len);
    held[len] = '\0';
    for (int i = 0; i < grep->n_patterns; i++) {
        if (grep->fixed[i]) {
            size_t needle = strlen (grep->fixed[i]);
            if (!needle) return 1;
            for (size_t at = 0; at + needle <= len; at++) {
                size_t j = 0;
                while (j < needle &&
                       (grep->ignore_case
                        ? tolower ((unsigned char) held[at + j]) ==
                          tolower ((unsigned char) grep->fixed[i][j])
                        : held[at + j] == grep->fixed[i][j]))
                    j++;
                if (j < needle) continue;
                if (!grep->word || git_grep_word (held, len, at, at + needle))
                    return 1;
            }
            continue;
        }
        regmatch_t where;
        size_t from = 0;
        /* A piece that does not start the line cannot answer to ^, and
           one that does not end it cannot answer to $. */
        int edges = (at_end ? 0 : REG_NOTEOL);
        while (from <= len &&
               regexec (&grep->patterns[i], held + from, 1, &where,
                        edges | (from || !at_start ? REG_NOTBOL : 0)) == 0) {
            size_t start = from + (size_t) where.rm_so;
            size_t end = from + (size_t) where.rm_eo;
            if (!grep->word || git_grep_word (held, len, start, end)) return 1;
            from = end > start ? end : start + 1;
        }
    }
    return 0;
}

/* A line of a binary file has NUL bytes in it, and a pattern is matched
   against text, so each run between them is searched on its own. */
static int
git_grep_line (const struct git_grep *grep, const char *line, size_t len)
{
    size_t at = 0;
    while (at <= len) {
        size_t piece = 0;
        while (at + piece < len && line[at + piece]) piece++;
        if (piece && git_grep_piece (grep, line + at, piece, at == 0,
                                     at + piece >= len))
            return 1;
        if (at + piece >= len) break;
        at += piece + 1;
    }
    return 0;
}

/* One file's content, however it was reached. */
static int
git_grep_file (const struct git_grep *grep, const char *shown,
               const char *text, size_t len, int *matched_any)
{
    /* git calls a file binary when a NUL turns up near the start of it,
       and then says so instead of writing its lines out. */
    int binary = 0;
    size_t look = len < 8000 ? len : 8000;
    for (size_t i = 0; i < look && !binary; i++) if (!text[i]) binary = 1;

    size_t hits = 0, line_no = 0;
    char **lines = NULL;
    size_t *lengths = NULL;
    size_t n_lines = 0;
    /* Walk the lines once, printing as they match unless only counts or
       names are wanted. */
    for (size_t at = 0; at <= len;) {
        if (at == len && len) break;
        const char *nl = memchr (text + at, '\n', len - at);
        size_t line_len = nl ? (size_t) (nl - (text + at)) : len - at;
        if (!nl && !line_len) break;
        line_no++;
        int hit = git_grep_line (grep, text + at, line_len);
        if (grep->invert) hit = !hit;
        if (hit) {
            hits++;
            *matched_any = 1;
            if (!grep->names_only && !grep->count_only && !binary) {
                if (grep->no_name) {
                    if (grep->line_numbers) printf ("%zu:", line_no);
                } else if (grep->line_numbers)
                    printf ("%s:%zu:", shown, line_no);
                else printf ("%s:", shown);
                printf ("%.*s\n", (int) line_len, text + at);
            }
        }
        if (!nl) break;
        at += line_len + 1;
    }
    free (lines);
    free (lengths);
    if (!hits) return 0;
    if (grep->names_only) printf ("%s\n", shown);
    else if (grep->count_only) {
        if (grep->no_name) printf ("%zu\n", hits);
        else printf ("%s:%zu\n", shown, hits);
    }
    else if (binary && !grep->invert) printf ("Binary file %s matches\n", shown);
    return 0;
}

static int
git_cmd_grep (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git grep [-i] [-n] [-l] [-c] [-h] [-w] [-v] "
                        "[-E | -F] [-e <pattern>] [--cached] [<pattern>] "
                        "[<tree-ish>] [-- <path>...]";
    struct git_grep grep;
    memset (&grep, 0, sizeof grep);
    int extended = 0, fixed = 0, cached = 0, no_more = 0;
    const char *patterns[16];
    int n_patterns = 0;
    const char *tree_ish = NULL;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (no_more) {
            if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
            else return git_fatal ("too many paths");
            continue;
        }
        if (!strcmp (w, "-e") && p->next) {
            if (n_patterns < (int) (sizeof patterns / sizeof *patterns))
                patterns[n_patterns++] = (p = p->next)->word->word;
            continue;
        }
        if (w[0] == '-' && w[1] && w[1] != '-') {
            int known = 1;
            for (const char *flag = w + 1; *flag && known; flag++)
                switch (*flag) {
                case 'i': grep.ignore_case = 1; break;
                case 'n': grep.line_numbers = 1; break;
                case 'l': grep.names_only = 1; break;
                case 'c': grep.count_only = 1; break;
                case 'h': grep.no_name = 1; break;
                case 'w': grep.word = 1; break;
                case 'v': grep.invert = 1; break;
                case 'E': extended = 1; break;
                case 'F': fixed = 1; break;
                default: known = 0; break;
                }
            if (known) continue;
            return git_usage (usage);
        }
        if (!strcmp (w, "--cached")) { cached = 1; continue; }
        if (!strcmp (w, "--ignore-case")) { grep.ignore_case = 1; continue; }
        if (!strcmp (w, "--line-number")) { grep.line_numbers = 1; continue; }
        if (!strcmp (w, "--files-with-matches") || !strcmp (w, "--name-only")) {
            grep.names_only = 1;
            continue;
        }
        if (!strcmp (w, "--count")) { grep.count_only = 1; continue; }
        if (!strcmp (w, "--word-regexp")) { grep.word = 1; continue; }
        if (!strcmp (w, "--invert-match")) { grep.invert = 1; continue; }
        if (!strcmp (w, "--extended-regexp")) { extended = 1; continue; }
        if (!strcmp (w, "--fixed-strings")) { fixed = 1; continue; }
        if (w[0] == '-' && w[1]) return git_usage (usage);
        if (!n_patterns) { patterns[n_patterns++] = w; continue; }
        if (!tree_ish) { tree_ish = w; continue; }
        if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (!n_patterns) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* The word after the pattern is what to search, if it names something
       that can be searched; otherwise it is a path, as git reads it. */
    if (tree_ish && !no_more) {
        char probe[41];
        if (git_resolve (ctx, tree_ish, probe, NULL) < 0 &&
            n_paths < (int) (sizeof paths / sizeof *paths)) {
            for (int k = n_paths; k > 0; k--) paths[k] = paths[k - 1];
            paths[0] = tree_ish;
            n_paths++;
            tree_ish = NULL;
        }
    }
    /* A path was written from where the command was run, and where none was
       written the place itself stands for one: git looks under the
       directory it was run in and names what it finds from there. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    char under[4096] = "";
    if (*ctx->prefix && !n_paths) {
        snprintf (under, sizeof under, "%.*s",
                  (int) (strlen (ctx->prefix) - 1), ctx->prefix);
        paths[n_paths++] = under;
    }

    grep.n_patterns = n_patterns;
    grep.patterns = calloc ((size_t) n_patterns, sizeof *grep.patterns);
    grep.fixed = calloc ((size_t) n_patterns, sizeof *grep.fixed);
    if (!grep.patterns || !grep.fixed) {
        free (grep.patterns);
        free (grep.fixed);
        return GIT_EXIT_FATAL;
    }
    for (int i = 0; i < n_patterns; i++) {
        if (fixed) { grep.fixed[i] = patterns[i]; continue; }
        int flags = (extended ? REG_EXTENDED : 0) |
                    (grep.ignore_case ? REG_ICASE : 0);
        if (regcomp (&grep.patterns[i], patterns[i], flags) != 0) {
            free (grep.patterns);
            free (grep.fixed);
            return git_fatal ("invalid pattern: %s", patterns[i]);
        }
    }

    int status = 0, matched = 0;
    bgit_index_entry *entries = NULL;
    size_t n = 0;
    char tree[41];
    if (tree_ish) {
        char id[41];
        if (git_resolve (ctx, tree_ish, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0)
            status = git_fatal ("bad object %s", tree_ish);
        else if (bgit_read_tree (&ctx->odb, tree, &entries, &n) < 0)
            status = git_fatal ("cannot read %s", tree_ish);
    } else if (git_index_load (ctx, &entries, &n) < 0)
        status = GIT_EXIT_FATAL;

    for (size_t i = 0; i < n && !status; i++) {
        if (n_paths && !git_path_named (entries[i].path, paths, n_paths))
            continue;
        if (entries[i].mode == 0160000) continue;   /* a repository of its own */
        char shown[8192], here[8192];
        const char *named = git_path_from_here (ctx, entries[i].path, here,
                                                sizeof here);
        if (tree_ish)
            snprintf (shown, sizeof shown, "%s:%s", tree_ish, named);
        else snprintf (shown, sizeof shown, "%s", named);
        unsigned char *data = NULL;
        size_t len = 0;
        if (tree_ish || cached) {
            char hex[41];
            enum bgit_type type;
            bgit_sha_to_hex (entries[i].sha, hex);
            if (bgit_odb_read (&ctx->odb, hex, &type, &data, &len) < 0) continue;
        } else {
            char full[4096];
            if ((size_t) snprintf (full, sizeof full, "%s/%s",
                                   ctx->repo.work_tree ? ctx->repo.work_tree : ".",
                                   entries[i].path) >= sizeof full)
                continue;
            struct stat st;
            if (lstat (full, &st) < 0 || !S_ISREG (st.st_mode)) continue;
            if (bgit_slurp_file (full, &data, &len) < 0) continue;
        }
        git_grep_file (&grep, shown, (const char *) data, len, &matched);
        free (data);
    }
    bgit_index_free_entries (entries, n);
    if (!fixed)
        for (int i = 0; i < n_patterns; i++) regfree (&grep.patterns[i]);
    free (grep.patterns);
    free (grep.fixed);
    return status ? status : (matched ? 0 : 1);
}

/* ---- shortlog ---------------------------------------------------------- */

/* Who wrote what, gathered by author. */
struct git_shortlog_author {
    char who[1024];              /* "Name", or "Name <mail>" with -e */
    char **subjects;
    size_t n, cap;
};

struct git_shortlog {
    struct git_shortlog_author *authors;
    size_t n, cap;
};

static int
git_shortlog_add (struct git_shortlog *log, const char *who,
                  const char *subject)
{
    struct git_shortlog_author *at = NULL;
    for (size_t i = 0; i < log->n; i++)
        if (!strcmp (log->authors[i].who, who)) { at = &log->authors[i]; break; }
    if (!at) {
        if (log->n == log->cap) {
            size_t next = log->cap ? log->cap * 2 : 16;
            struct git_shortlog_author *grown = realloc (log->authors,
                                                         next * sizeof *grown);
            if (!grown) return -1;
            log->authors = grown;
            log->cap = next;
        }
        at = &log->authors[log->n++];
        memset (at, 0, sizeof *at);
        snprintf (at->who, sizeof at->who, "%s", who);
    }
    if (at->n == at->cap) {
        size_t next = at->cap ? at->cap * 2 : 8;
        char **grown = realloc (at->subjects, next * sizeof *grown);
        if (!grown) return -1;
        at->subjects = grown;
        at->cap = next;
    }
    at->subjects[at->n] = strdup (subject);
    if (!at->subjects[at->n]) return -1;
    at->n++;
    return 0;
}

static void
git_shortlog_release (struct git_shortlog *log)
{
    for (size_t i = 0; i < log->n; i++) {
        for (size_t j = 0; j < log->authors[i].n; j++)
            free (log->authors[i].subjects[j]);
        free (log->authors[i].subjects);
    }
    free (log->authors);
}

static int
git_shortlog_by_name (const void *a, const void *b)
{
    return strcmp (((const struct git_shortlog_author *) a)->who,
                   ((const struct git_shortlog_author *) b)->who);
}

static int
git_shortlog_by_count (const void *a, const void *b)
{
    const struct git_shortlog_author *x = a, *y = b;
    if (x->n != y->n) return x->n < y->n ? 1 : -1;
    return strcmp (x->who, y->who);
}

/* git's own log, read back: what it wrote about who wrote each commit. */
static int
git_shortlog_read (struct git_shortlog *log, int email)
{
    char line[65536];
    char who[1024] = "";
    int want_subject = 0;
    char subject[4096] = "";
    while (fgets (line, sizeof line, stdin)) {
        size_t len = strlen (line);
        while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (!strncmp (line, "Author: ", 8)) {
            snprintf (who, sizeof who, "%s", line + 8);
            if (!email) {
                char *bracket = strrchr (who, '<');
                if (bracket) {
                    while (bracket > who && bracket[-1] == ' ') bracket--;
                    *bracket = '\0';
                }
            }
            want_subject = 1;
            *subject = '\0';
            continue;
        }
        if (!want_subject || !*who) continue;
        if (line[0] == ' ' && line[1] == ' ' && line[2] == ' ' &&
            line[3] == ' ') {
            const char *text = line + 4;
            if (!*text) {
                /* The blank line after the subject ends it. */
                if (*subject) {
                    if (git_shortlog_add (log, who, subject) < 0) return -1;
                    want_subject = 0;
                }
                continue;
            }
            /* git folds the subject's lines into one, as it does elsewhere. */
            size_t at = strlen (subject);
            snprintf (subject + at, sizeof subject - at, "%s%s",
                      at ? " " : "", text);
            continue;
        }
        if (*subject) {
            if (git_shortlog_add (log, who, subject) < 0) return -1;
            want_subject = 0;
            *subject = '\0';
        }
    }
    if (*subject && *who && git_shortlog_add (log, who, subject) < 0) return -1;
    return 0;
}

static int
git_cmd_shortlog (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git shortlog [-n] [-s] [-e] [--no-merges] "
                        "[<revision range>]";
    int summary = 0, numbered = 0, email = 0;
    struct git_log_filter filter;
    git_log_filter_init (&filter);
    const char *revs[16], *excludes[16];
    int n_revs = 0, n_excludes = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        const char *taken = p->next ? p->next->word->word : NULL;
        if (w[0] == '-' && w[1] && w[1] != '-' && !git_all_digits (w + 1) &&
            strcmp (w, "-S") && strcmp (w, "-G") && strncmp (w, "-S", 2) &&
            strncmp (w, "-G", 2)) {
            /* git takes these run together, as -sne. */
            int known = 1;
            for (const char *flag = w + 1; *flag && known; flag++)
                switch (*flag) {
                case 's': summary = 1; break;
                case 'n': numbered = 1; break;
                case 'e': email = 1; break;
                default: known = 0; break;
                }
            if (known) continue;
        }
        if (!strcmp (w, "--summary")) summary = 1;
        else if (!strcmp (w, "--numbered")) numbered = 1;
        else if (!strcmp (w, "--email")) email = 1;
        else if (git_log_filter_option (&filter, w, &taken)) {
            if (!taken && p->next) p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (strstr (w, "..") && !strstr (w, "...")) {
            char *range = strdup (w);
            if (!range) return GIT_EXIT_FATAL;
            char *dots = strstr (range, "..");
            *dots = '\0';
            if (n_excludes >= (int) (sizeof excludes / sizeof *excludes) ||
                n_revs >= (int) (sizeof revs / sizeof *revs)) {
                free (range);
                return git_fatal ("too many revisions");
            }
            excludes[n_excludes++] = *range ? range : "HEAD";
            revs[n_revs++] = dots[2] ? dots + 2 : "HEAD";
        }
        else if (n_revs < (int) (sizeof revs / sizeof *revs)) revs[n_revs++] = w;
        else return git_fatal ("too many revisions");
    }

    struct git_shortlog log;
    memset (&log, 0, sizeof log);
    int status = 0;
    if (!n_revs && !isatty (STDIN_FILENO)) {
        /* With nothing named and something to read, git reads its own log
           from whatever is feeding it. */
        if (git_shortlog_read (&log, email) < 0) {
            git_shortlog_release (&log);
            return GIT_EXIT_FATAL;
        }
    } else {
        if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
        if (!n_revs) revs[n_revs++] = "HEAD";
        char (*walk)[41] = NULL;
        size_t n_walk = 0;
        if (git_collect_commits (ctx, revs, n_revs, excludes, n_excludes, 0, -1,
                                 &walk, &n_walk) < 0)
            return git_fatal ("cannot read the history");
        for (size_t i = 0; i < n_walk; i++) {
            struct git_commit commit;
            if (git_commit_read (ctx, walk[i], &commit) < 0) continue;
            if (git_log_keeps (&filter, &commit)) {
                char who[1024], subject[4096];
                if (email)
                    snprintf (who, sizeof who, "%s <%s>", commit.author_name,
                              commit.author_email);
                else snprintf (who, sizeof who, "%s", commit.author_name);
                git_subject (&commit, subject, sizeof subject);
                if (git_shortlog_add (&log, who, subject) < 0) status = GIT_EXIT_FATAL;
            }
            git_commit_release (&commit);
            if (status) break;
        }
        free (walk);
    }

    if (!status) {
        qsort (log.authors, log.n, sizeof *log.authors,
               numbered ? git_shortlog_by_count : git_shortlog_by_name);
        for (size_t i = 0; i < log.n; i++) {
            struct git_shortlog_author *who = &log.authors[i];
            if (summary) {
                printf ("%6zu\t%s\n", who->n, who->who);
                continue;
            }
            printf ("%s (%zu):\n", who->who, who->n);
            /* Oldest first, which is the other way round from the walk. */
            for (size_t j = who->n; j-- > 0;)
                printf ("      %s\n", who->subjects[j]);
            printf ("\n");
        }
    }
    git_shortlog_release (&log);
    return status;
}

static int
git_cmd_tag (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git tag [-a] [-s] [-u <key>] [-m <message>] [-f] "
                        "<name> [<commit>] | -d <name>... "
                        "| [-l] [-n[<num>]] [--contains <commit>] "
                        "[--merged <commit>] [--no-merged <commit>] "
                        "[--points-at <object>] [<pattern>]";
    int annotate = 0, delete_tag = 0, list = 0, force = 0, sign = 0, lines = 0;
    struct git_ref_key keys[8];
    int n_keys = 0;
    const char *merged = NULL, *not_merged = NULL, *contains = NULL;
    const char *points_at = NULL;
    int want_merged = 0, want_not_merged = 0;
    const char *message = NULL, *signing_key = NULL;
    /* Two for making one tag, and as many as are given for deleting. */
    const char *names[64] = { NULL };
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-a") || !strcmp (w, "--annotate")) annotate = 1;
        else if (!strcmp (w, "-s") || !strcmp (w, "--sign")) sign = annotate = 1;
        else if (!strcmp (w, "--no-sign")) sign = 0;
        else if ((!strcmp (w, "-u") || !strcmp (w, "--local-user")) && p->next) {
            signing_key = p->next->word->word;
            sign = annotate = 1;
            p = p->next;
        }
        else if (!strncmp (w, "--local-user=", 13)) {
            signing_key = w + 13;
            sign = annotate = 1;
        }
        else if (!strcmp (w, "-d") || !strcmp (w, "--delete")) delete_tag = 1;
        else if (!strcmp (w, "-l") || !strcmp (w, "--list")) list = 1;
        else if (!strncmp (w, "--sort=", 7) || (!strcmp (w, "--sort") && p->next)) {
            const char *key = w[6] == '=' ? w + 7 : (p = p->next)->word->word;
            if (n_keys >= (int) (sizeof keys / sizeof *keys))
                return git_fatal ("too many sort keys");
            keys[n_keys].reverse = *key == '-';
            if (keys[n_keys].reverse) key++;
            if (!git_ref_key_known (key))
                return git_fatal ("unknown field name: %s", key);
            keys[n_keys++].name = key;
            list = 1;
        }
        else if (!strcmp (w, "-n")) { lines = 1; list = 1; }
        else if (w[0] == '-' && w[1] == 'n' && git_all_digits (w + 2)) {
            lines = atoi (w + 2);
            if (lines < 1) lines = 1;
            list = 1;
        }
        else if (!strcmp (w, "--contains") && p->next) {
            contains = (p = p->next)->word->word;
            list = 1;
        }
        else if (!strncmp (w, "--contains=", 11)) { contains = w + 11; list = 1; }
        else if (!strcmp (w, "--points-at") && p->next) {
            points_at = (p = p->next)->word->word;
            list = 1;
        }
        else if (!strncmp (w, "--points-at=", 12)) { points_at = w + 12; list = 1; }
        else if (!strcmp (w, "--merged")) {
            want_merged = list = 1;
            if (p->next && p->next->word->word[0] != '-')
                merged = (p = p->next)->word->word;
        }
        else if (!strncmp (w, "--merged=", 9)) {
            want_merged = list = 1;
            merged = w + 9;
        }
        else if (!strcmp (w, "--no-merged")) {
            want_not_merged = list = 1;
            if (p->next && p->next->word->word[0] != '-')
                not_merged = (p = p->next)->word->word;
        }
        else if (!strncmp (w, "--no-merged=", 12)) {
            want_not_merged = list = 1;
            not_merged = w + 12;
        }
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (!strcmp (w, "-m") && p->next) {
            message = p->next->word->word; annotate = 1; p = p->next;
        } else if (!strcmp (w, "-am") && p->next) {
            message = p->next->word->word; annotate = 1; p = p->next;
        } else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names))
            names[n_names++] = w;
        else return git_usage (usage);
    }
    if (!delete_tag && n_names > 2) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (delete_tag) {
        if (!n_names) return git_usage (usage);
        /* git deletes as many as it is given, says so for each, and a
           name it does not know is an error that does not stop it. */
        int status = 0;
        for (int i = 0; i < n_names; i++) {
            char ref[4096], id[41];
            snprintf (ref, sizeof ref, "refs/tags/%s", names[i]);
            if (bgit_ref_read (&ctx->repo, ref, id) != 0) {
                fflush (stdout);
                fprintf (stderr, "error: tag '%s' not found.\n", names[i]);
                status = 1;
                continue;
            }
            if (bgit_ref_delete (&ctx->repo, ref, NULL, NULL) < 0)
                return GIT_EXIT_FATAL;
            char abbreviated[41];
            git_abbrev (ctx, id, 7, abbreviated, sizeof abbreviated);
            printf ("Deleted tag '%s' (was %s)\n", names[i], abbreviated);
        }
        return status;
    }
    if (list || !n_names) {
        char merged_id[41] = "", not_merged_id[41] = "", contains_id[41] = "";
        char points_id[41] = "";
        if (want_merged &&
            (git_resolve (ctx, merged ? merged : "HEAD", merged_id, NULL) < 0 ||
             bgit_peel_to_type (&ctx->odb, merged_id, BGIT_COMMIT,
                                merged_id) < 0))
            return git_fatal ("malformed object name %s",
                              merged ? merged : "HEAD");
        if (want_not_merged &&
            (git_resolve (ctx, not_merged ? not_merged : "HEAD", not_merged_id,
                          NULL) < 0 ||
             bgit_peel_to_type (&ctx->odb, not_merged_id, BGIT_COMMIT,
                                not_merged_id) < 0))
            return git_fatal ("malformed object name %s",
                              not_merged ? not_merged : "HEAD");
        if (contains &&
            (git_resolve (ctx, contains, contains_id, NULL) < 0 ||
             bgit_peel_to_type (&ctx->odb, contains_id, BGIT_COMMIT,
                                contains_id) < 0)) {
            fflush (stdout);
            fprintf (stderr, "error: malformed object name %s\n", contains);
            return GIT_EXIT_USAGE;
        }
        if (points_at && git_resolve (ctx, points_at, points_id, NULL) < 0) {
            fflush (stdout);
            fprintf (stderr, "error: malformed object name '%s'\n", points_at);
            return GIT_EXIT_USAGE;
        }
        bgit_ref *refs = NULL;
        size_t n = 0;
        if (bgit_refs_list (&ctx->repo, "refs/tags/", &refs, &n) < 0)
            return git_fatal ("cannot read refs");
        if (git_sort_refs (ctx, refs, n, keys, n_keys) < 0) {
            bgit_refs_free (refs, n);
            return GIT_EXIT_FATAL;
        }
        for (size_t i = 0; i < n; i++) {
            const char *name = refs[i].name + 10;
            if (names[0] && fnmatch (names[0], name, 0) != 0) continue;
            if (!git_ref_listed (ctx, refs[i].sha, merged_id, not_merged_id,
                                 contains_id, points_id))
                continue;
            if (!lines) {
                printf ("%s\n", name);
                continue;
            }
            /* -n writes what the tag says, or what the commit it names
               says when the tag is a light one, a line at a time. */
            char *message = git_tag_note (ctx, refs[i].sha);
            const char *at = message ? message : "";
            for (int shown = 0; shown < lines; shown++) {
                const char *nl = strchr (at, '\n');
                size_t len = nl ? (size_t) (nl - at) : strlen (at);
                if (!len && !nl) break;
                if (!shown) printf ("%-15s %.*s\n", name, (int) len, at);
                else printf ("    %.*s\n", (int) len, at);
                if (!nl) break;
                at = nl + 1;
            }
            if (!*at && !message) printf ("%-15s\n", name);
            free (message);
        }
        bgit_refs_free (refs, n);
        return 0;
    }

    char ref[4096];
    snprintf (ref, sizeof ref, "refs/tags/%s", names[0]);
    char existing[41];
    if (!force && bgit_ref_read (&ctx->repo, ref, existing) == 0)
        return git_fatal ("tag '%s' already exists", names[0]);
    char id[41], commit[41];
    const char *target = names[1] ? names[1] : "HEAD";
    if (git_resolve (ctx, target, id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0)
        return git_fatal ("Failed to resolve '%s' as a valid ref.", target);

    char pointed[41];
    memcpy (pointed, commit, 41);
    if (annotate) {
        char tagger[1024];
        {
            int trouble = git_identity (ctx, 1, tagger, sizeof tagger);
            if (trouble) return trouble;
        }
        /* With nothing said on the command line, the message is written in
           the editor, over the note git leaves there. */
        char written[8192];
        if (!message) {
            char editmsg[4096];
            if (snprintf (editmsg, sizeof editmsg, "%s/TAG_EDITMSG",
                          ctx->repo.git_dir) >= (int) sizeof editmsg)
                return GIT_EXIT_FATAL;
            FILE *out = fopen (editmsg, "w");
            if (!out) return git_fatal ("could not write '%s'", editmsg);
            fprintf (out, "\n#\n# Write a message for tag:\n#   %s\n"
                          "# Lines starting with '#' will be ignored.\n",
                     names[0]);
            fclose (out);
            if (git_edit_file (ctx, editmsg, 0) < 0) return GIT_EXIT_FATAL;
            size_t edited_len = 0;
            char *edited = git_message_body (editmsg, &edited_len);
            if (!edited || !edited_len) {
                free (edited);
                return git_fatal ("no tag message?");
            }
            snprintf (written, sizeof written, "%s", edited);
            free (edited);
            message = written;
        }
        char body[8192];
        int len = snprintf (body, sizeof body,
                            "object %s\ntype commit\ntag %s\ntagger %s\n\n%s%s",
                            commit, names[0], tagger, message ? message : "",
                            (message && *message &&
                             message[strlen (message) - 1] == '\n') ? "" : "\n");
        if (len < 0 || len >= (int) sizeof body)
            return git_fatal ("tag message too long");
        /* A signed tag carries its signature after the message, over
           everything that stands before it. */
        char *signed_body = NULL;
        if (!sign) sign = bgit_config_bool (&ctx->cfg, "tag.gpgSign", 0);
        if (sign) {
            bgit_ssh_key key;
            char *armour = NULL;
            if (git_signing_key (ctx, signing_key, &key) < 0 ||
                bgit_sshsig_sign (&key, "git", (const unsigned char *) body,
                                  (size_t) len, &armour) < 0)
                return git_fatal ("failed to write tag object");
            size_t room = (size_t) len + strlen (armour) + 1;
            signed_body = malloc (room);
            if (!signed_body) { free (armour); return GIT_EXIT_FATAL; }
            int whole = snprintf (signed_body, room, "%s%s", body, armour);
            free (armour);
            if (whole < 0) { free (signed_body); return GIT_EXIT_FATAL; }
            len = whole;
        }
        int wrote = bgit_write_object (ctx->odb.object_dirs[0], "tag",
                                       (const unsigned char *)
                                       (signed_body ? signed_body : body),
                                       (size_t) len, 1, pointed);
        free (signed_body);
        if (wrote < 0) return GIT_EXIT_FATAL;
    }
    if (bgit_ref_update (&ctx->repo, ref, pointed, NULL, NULL) < 0)
        return GIT_EXIT_FATAL;
    return 0;
}

static int
git_cmd_rm (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git rm [--cached] [-r] [-f] [-q] [--] <path>...";
    int cached = 0, no_more = 0, quiet = 0;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && !strcmp (w, "--cached")) cached = 1;
        else if (!no_more && (!strcmp (w, "-q") || !strcmp (w, "--quiet"))) quiet = 1;
        else if (!no_more && (!strcmp (w, "-r") || !strcmp (w, "-f") ||
                              !strcmp (w, "--force"))) continue;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (!n_paths) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    int status = 0, removed = 0;
    for (int i = 0; i < n_paths; i++) {
        size_t len = strlen (paths[i]);
        for (size_t j = 0; j < state.n_index;) {
            const char *path = state.index[j].path;
            if (strcmp (path, paths[i]) &&
                !(!strncmp (path, paths[i], len) && path[len] == '/')) {
                j++;
                continue;
            }
            if (!quiet) printf ("rm '%s'\n", path);
            if (!cached) {
                char full[4096];
                snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path);
                unlink (full);
            }
            char *gone = strdup (path);
            if (!gone) { status = GIT_EXIT_FATAL; break; }
            bgit_index_remove_path (&state.index, &state.n_index, gone);
            free (gone);
            removed = 1;
        }
    }
    if (!removed && !status)
        status = git_fatal ("pathspec '%s' did not match any files", paths[0]);
    if (!status && git_index_store (ctx, state.index, state.n_index) < 0)
        status = GIT_EXIT_FATAL;
    git_state_release (&state);
    return status;
}

/* ---- merge-base -------------------------------------------------------- */

static int
git_cmd_merge_base (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git merge-base [--all] <commit> <commit>... | "
                        "--is-ancestor <commit> <commit> | "
                        "(--independent | --octopus) [--all] <commit>...";
    int all = 0, is_ancestor = 0, independent = 0, octopus = 0;
    const char *names[32];
    int n_names = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-a") || !strcmp (w, "--all")) all = 1;
        else if (!strcmp (w, "--is-ancestor")) is_ancestor = 1;
        else if (!strcmp (w, "--independent")) independent = 1;
        else if (!strcmp (w, "--octopus")) octopus = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_names < (int) (sizeof names / sizeof *names)) names[n_names++] = w;
        else return git_fatal ("too many commits");
    }
    if (!n_names || (!independent && n_names < 2)) return git_usage (usage);
    if (is_ancestor && n_names != 2) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    char (*ids)[41] = calloc ((size_t) n_names, sizeof *ids);
    const char **commits = calloc ((size_t) n_names, sizeof *commits);
    if (!ids || !commits) {
        free (ids);
        free (commits);
        return GIT_EXIT_FATAL;
    }
    for (int i = 0; i < n_names; i++) {
        char id[41];
        if (git_resolve (ctx, names[i], id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, ids[i]) < 0) {
            free (ids);
            free (commits);
            return git_fatal ("Not a valid object name %s", names[i]);
        }
        commits[i] = ids[i];
    }

    if (is_ancestor) {
        int reaches = bgit_is_ancestor (&ctx->odb, ids[0], ids[1]);
        free (ids);
        free (commits);
        return reaches < 0 ? GIT_EXIT_FATAL : (reaches ? 0 : 1);
    }

    char (*bases)[41] = NULL;
    size_t n_bases = 0;
    int rc;
    if (independent)
        rc = bgit_independent (&ctx->odb, commits, n_names, &bases, &n_bases);
    else if (octopus)
        rc = bgit_merge_bases_octopus (&ctx->odb, commits, n_names, &bases,
                                       &n_bases);
    else
        rc = bgit_merge_bases_many (&ctx->odb, commits[0], commits + 1,
                                    n_names - 1, &bases, &n_bases);
    free (ids);
    free (commits);
    if (rc < 0) {
        free (bases);
        return GIT_EXIT_FATAL;
    }
    /* Only --all asks for more than the first, and --independent is a list
       by its nature. */
    for (size_t i = 0; i < n_bases; i++) {
        printf ("%s\n", bases[i]);
        if (!all && !independent) break;
    }
    int found = n_bases > 0;
    free (bases);
    return found ? 0 : 1;
}

/* ---- merge ------------------------------------------------------------- */

/* Write CONTENT into the working tree at FULL, as MODE says. */
static int
git_write_worktree_file (const char *full, const char *content, size_t len,
                         uint32_t mode)
{
    unlink (full);
    if (mode == 0120000) {
        char *target = malloc (len + 1);
        if (!target) return -1;
        memcpy (target, content, len);
        target[len] = '\0';
        int rc = symlink (target, full);
        free (target);
        return rc;
    }
    /* The file is created with git's permissions, which the umask then
       narrows, exactly as a checkout does. */
    int fd = open (full, O_WRONLY | O_CREAT | O_TRUNC,
                   mode == 0100755 ? 0777 : 0666);
    if (fd < 0) return -1;
    size_t at = 0;
    while (at < len) {
        ssize_t wrote = write (fd, content + at, len - at);
        if (wrote < 0) {
            if (errno == EINTR) continue;
            close (fd);
            return -1;
        }
        at += (size_t) wrote;
    }
    return close (fd) == 0 ? 0 : -1;
}

/* A file inside the git directory, such as MERGE_HEAD. */
static int
git_state_file (git_context *ctx, const char *name, char *out, size_t outsz)
{
    return snprintf (out, outsz, "%s/%s", ctx->repo.git_dir, name) >= (int) outsz
           ? -1 : 0;
}

static int
git_write_state_file (git_context *ctx, const char *name, const char *content)
{
    char path[4096];
    if (git_state_file (ctx, name, path, sizeof path) < 0) return -1;
    FILE *file = fopen (path, "w");
    if (!file) return -1;
    fputs (content, file);
    return fclose (file) == 0 ? 0 : -1;
}

static void
git_remove_state_file (git_context *ctx, const char *name)
{
    char path[4096];
    if (git_state_file (ctx, name, path, sizeof path) == 0) unlink (path);
}

static int
git_read_state_id (git_context *ctx, const char *name, char out[41])
{
    char path[4096];
    struct stat st;
    if (git_state_file (ctx, name, path, sizeof path) < 0 ||
        lstat (path, &st) < 0)
        return 0;
    unsigned char *content = NULL;
    size_t len = 0;
    if (bgit_slurp_file (path, &content, &len) < 0) return 0;
    int ok = len >= 40;
    if (ok) {
        memcpy (out, content, 40);
        out[40] = '\0';
    }
    free (content);
    return ok;
}

/* The name a merge records for what was merged, as git words it. A merge
   into anything but the branch a repository starts on says so — git names
   master and main and nothing else. */
static void
git_merge_label (git_context *ctx, const char *name, const char *id,
                 char *label, size_t label_size, char *subject,
                 size_t subject_size, const char *into)
{
    char resolved[41];
    char *symref = NULL;
    (void) git_resolve (ctx, name, resolved, &symref);
    /* FETCH_HEAD says for itself what was fetched and where from — a
       branch of a URL, a tag of one — and git's merge message is that
       line with "Merge " in front of it. */
    if (!strcmp (name, "FETCH_HEAD")) {
        char path[4096];
        char line[8192] = "";
        if (snprintf (path, sizeof path, "%s/FETCH_HEAD", ctx->repo.git_dir) <
            (int) sizeof path) {
            FILE *file = fopen (path, "r");
            if (file) {
                char held[8192];
                while (fgets (held, sizeof held, file)) {
                    char *first = strchr (held, '\t');
                    if (!first || strncmp (first + 1, "\t", 1)) continue;
                    snprintf (line, sizeof line, "%s", first + 2);
                    char *end = strchr (line, '\n');
                    if (end) *end = '\0';
                    break;                 /* the first one for merging */
                }
                fclose (file);
            }
        }
        if (*line) {
            snprintf (label, label_size, "%s", line);
            snprintf (subject, subject_size, "Merge %s", line);
            if (into && !strncmp (into, "refs/heads/", 11)) into += 11;
            if (into && *into && strcmp (into, "master") &&
                strcmp (into, "main")) {
                size_t at = strlen (subject);
                snprintf (subject + at, subject_size - at, " into %s", into);
            }
            free (symref);
            return;
        }
    }
    if (symref && !strncmp (symref, "refs/heads/", 11)) {
        snprintf (label, label_size, "%s", symref + 11);
        snprintf (subject, subject_size, "Merge branch '%s'", symref + 11);
    } else if (symref && !strncmp (symref, "refs/remotes/", 13)) {
        snprintf (label, label_size, "%s", symref + 13);
        snprintf (subject, subject_size, "Merge remote-tracking branch '%s'",
                  symref + 13);
    } else {
        snprintf (label, label_size, "%s", name);
        snprintf (subject, subject_size, "Merge commit '%s'", id);
    }
    if (into && !strncmp (into, "refs/heads/", 11)) into += 11;
    if (into && *into && strcmp (into, "master") && strcmp (into, "main")) {
        size_t at = strlen (subject);
        snprintf (subject + at, subject_size - at, " into %s", into);
    }
    free (symref);
}

/* Nothing is written until every change is known to be safe, which is what
   lets a refused merge leave the working tree as it was. */
static int
git_merge_safe (git_context *ctx, struct git_state *state,
                const bgit_merge_path *paths, size_t n)
{
    for (size_t i = 0; i < n; i++) {
        const bgit_merge_path *path = &paths[i];
        int unchanged = path->kind == BGIT_MERGE_CLEAN &&
                        path->mode == path->our_mode &&
                        !strcmp (path->sha, path->our_sha);
        if (unchanged) continue;
        char full[4096];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path->path);
        struct stat st;
        if (lstat (full, &st) < 0) continue;
        const bgit_index_entry *staged = NULL;
        for (size_t j = 0; j < state->n_index; j++)
            if (!strcmp (state->index[j].path, path->path)) staged = &state->index[j];
        if (!staged) {
            fflush (stdout);
            fprintf (stderr, "error: The following untracked working tree files "
                             "would be overwritten by merge:\n\t%s\nPlease move "
                             "or remove them before you merge.\nAborting\n",
                     path->path);
            return -1;
        }
        if (!bgit_worktree_matches (&ctx->odb, full, staged, &st)) {
            fflush (stdout);
            fprintf (stderr, "error: Your local changes to the following files "
                             "would be overwritten by merge:\n\t%s\nPlease commit "
                             "your changes or stash them before you merge.\n"
                             "Aborting\n", path->path);
            return -1;
        }
    }
    return 0;
}

/* Put the merged tree into the working tree and the index. */
static int
git_merge_apply (git_context *ctx, struct git_state *state,
                 const bgit_merge_path *paths, size_t n)
{
    bgit_index_entry *entries = NULL;
    size_t n_entries = 0, capacity = 0;
    for (size_t i = 0; i < n; i++) {
        const bgit_merge_path *path = &paths[i];
        char full[4096];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path->path);

        if (!path->mode && path->kind == BGIT_MERGE_CLEAN) {
            unlink (full);
            continue;
        }
        if (path->text) {
            /* A conflict: the working tree gets the marked-up text. */
            if (git_write_worktree_file (full, path->text, path->len,
                                         path->mode) < 0) {
                bgit_index_free_entries (entries, n_entries);
                return -1;
            }
        } else if (path->mode &&
                   (path->mode != path->our_mode ||
                    strcmp (path->sha, path->our_sha))) {
            if (bgit_checkout_file (&ctx->odb, full, path->sha, path->mode) < 0) {
                bgit_index_free_entries (entries, n_entries);
                return -1;
            }
        }

        /* The index gets one entry, or three when the path is in dispute. */
        struct { uint32_t mode; const char *sha; int stage; } sides[3];
        int n_sides = 0;
        if (path->kind == BGIT_MERGE_CLEAN || path->kind == BGIT_MERGE_AUTO) {
            if (!path->mode) continue;
            sides[n_sides].mode = path->mode;
            sides[n_sides].sha = path->sha;
            sides[n_sides].stage = 0;
            n_sides++;
        } else {
            if (path->base_mode) {
                sides[n_sides].mode = path->base_mode;
                sides[n_sides].sha = path->base_sha;
                sides[n_sides].stage = 1;
                n_sides++;
            }
            if (path->our_mode) {
                sides[n_sides].mode = path->our_mode;
                sides[n_sides].sha = path->our_sha;
                sides[n_sides].stage = 2;
                n_sides++;
            }
            if (path->their_mode) {
                sides[n_sides].mode = path->their_mode;
                sides[n_sides].sha = path->their_sha;
                sides[n_sides].stage = 3;
                n_sides++;
            }
        }
        for (int s = 0; s < n_sides; s++) {
            if (n_entries == capacity) {
                size_t next = capacity ? capacity * 2 : 32;
                bgit_index_entry *grown = realloc (entries, next * sizeof *grown);
                if (!grown) {
                    bgit_index_free_entries (entries, n_entries);
                    return -1;
                }
                entries = grown;
                capacity = next;
            }
            bgit_index_entry *entry = &entries[n_entries];
            memset (entry, 0, sizeof *entry);
            entry->path = strdup (path->path);
            if (!entry->path) {
                bgit_index_free_entries (entries, n_entries);
                return -1;
            }
            entry->mode = sides[s].mode;
            bgit_hex_to_sha (sides[s].sha, entry->sha);
            size_t length = strlen (path->path);
            entry->flags = (uint16_t) ((sides[s].stage << 12) |
                                       (length > 0xFFF ? 0xFFF : length));
            if (!sides[s].stage) {
                struct stat st;
                if (lstat (full, &st) == 0) {
                    uint32_t mode = entry->mode;
                    bgit_index_entry_set_stat (entry, &st);
                    entry->mode = mode;
                }
            }
            n_entries++;
        }
    }
    int rc = git_index_store (ctx, entries, n_entries);
    bgit_index_free_entries (state->index, state->n_index);
    state->index = entries;
    state->n_index = n_entries;
    state->cap_index = capacity;
    return rc;
}

/* The stat of a merge, as git prints it after one. */
static int
git_merge_summary (git_context *ctx, const char *old_tree, const char *new_tree)
{
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (bgit_diff_trees (&ctx->odb, old_tree, new_tree, &entries, &n) < 0)
        return -1;
    struct git_diff_format format;
    git_diff_format_init (&format);
    format.stat = 1;
    format.summary = 1;
    int rc = git_diff_emit (ctx, stdout, &format, entries, n, 0, "");
    bgit_diff_free (entries, n);
    return rc;
}

static int
git_cmd_merge (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git merge [-m <message>] [--no-ff] [--ff-only] "
                        "[--no-commit] [-e | --no-edit] [-q] <commit> "
                        "| --abort";
    const char *message = NULL, *name = NULL;
    int no_ff = 0, ff_only = 0, no_commit = 0, abort_merge = 0, quiet = 0;
    int edit = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-m") && p->next) { message = p->next->word->word; p = p->next; }
        else if (!strcmp (w, "--no-ff")) no_ff = 1;
        else if (!strcmp (w, "--ff")) no_ff = 0;
        else if (!strcmp (w, "--ff-only")) ff_only = 1;
        else if (!strcmp (w, "--no-commit")) no_commit = 1;
        else if (!strcmp (w, "--abort")) abort_merge = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        /* A merge that settles is committed without asking, as git's is
           when it is not asked; -e says to write the message after all. */
        else if (!strcmp (w, "--no-edit")) edit = 0;
        else if (!strcmp (w, "-e") || !strcmp (w, "--edit")) edit = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else return git_fatal ("this build's git merge takes one commit");
    }
    if (!abort_merge && !name) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    char merge_head_path[4096];
    if (git_state_file (ctx, "MERGE_HEAD", merge_head_path,
                        sizeof merge_head_path) < 0)
        return GIT_EXIT_FATAL;
    struct stat merging;
    int in_merge = lstat (merge_head_path, &merging) == 0;

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int status = 0;

    if (abort_merge) {
        if (!in_merge) {
            git_state_release (&state);
            return git_fatal ("There is no merge to abort (MERGE_HEAD missing).");
        }
        /* Put the working tree and index back to HEAD. */
        if (bgit_checkout_tree (&ctx->repo, &ctx->odb, state.head_tree,
                                &state.index, &state.n_index, 1, NULL) < 0 ||
            git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
        /* git aborts a merge by resetting hard to HEAD, and the reflog
           says so. */
        if (!status)
            bgit_reflog_append (&ctx->repo, "HEAD", state.head, state.head,
                                "reset: moving to HEAD");
        git_remove_state_file (ctx, "MERGE_HEAD");
        git_remove_state_file (ctx, "MERGE_MSG");
        git_state_release (&state);
        return status;
    }
    if (in_merge) {
        git_state_release (&state);
        return git_fatal ("You have not concluded your merge (MERGE_HEAD exists).");
    }
    if (!state.have_head) {
        git_state_release (&state);
        return git_fatal ("Non-fast-forward commit does not make sense into an "
                          "empty head");
    }
    for (size_t i = 0; i < state.n_index; i++)
        if ((state.index[i].flags >> 12) & 3) {
            git_state_release (&state);
            return git_fatal ("You have not concluded your merge (MERGE_HEAD "
                              "exists).");
        }

    char their_id[41], their_commit[41];
    if (git_resolve (ctx, name, their_id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, their_id, BGIT_COMMIT, their_commit) < 0) {
        git_state_release (&state);
        return git_fatal ("%s - not something we can merge", name);
    }
    char label[256], subject[1024];
    git_merge_label (ctx, name, their_commit, label, sizeof label,
                     subject, sizeof subject, state.branch);
    if (message) snprintf (subject, sizeof subject, "%s", message);

    char (*bases)[41] = NULL;
    size_t n_bases = 0;
    const char *twos[1] = { their_commit };
    if (bgit_merge_bases_many (&ctx->odb, state.head, twos, 1, &bases,
                               &n_bases) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (!n_bases) {
        free (bases);
        git_state_release (&state);
        return git_fatal ("refusing to merge unrelated histories");
    }
    /* Two branches that have merged each other have more than one base,
       and neither on its own is what the merge should be held against. */
    char made_up_base[41] = "";
    if (n_bases > 1 && git_base_tree (ctx, bases, n_bases, made_up_base) < 0) {
        free (bases);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    char base[41];
    memcpy (base, bases[0], 41);
    free (bases);

    if (!strcmp (base, their_commit)) {
        git_state_release (&state);
        printf ("Already up to date.\n");
        return 0;
    }
    int fast_forward = !strcmp (base, state.head);
    if (ff_only && !fast_forward) {
        git_state_release (&state);
        return git_fatal ("Not possible to fast-forward, aborting.");
    }

    char their_tree[41];
    if (bgit_commit_tree (&ctx->odb, their_commit, their_tree) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    if (fast_forward && !no_ff) {
        char old_short[41], new_short[41];
        git_abbrev (ctx, state.head, 7, old_short, sizeof old_short);
        git_abbrev (ctx, their_commit, 7, new_short, sizeof new_short);
        if (!quiet) printf ("Updating %s..%s\n", old_short, new_short);
        char *lost = NULL;
        int rc = bgit_checkout_tree (&ctx->repo, &ctx->odb, their_tree,
                                     &state.index, &state.n_index, 0, &lost);
        if (rc > 0) {
            /* Which complaint depends on whether the file in the way is one
               git knows about. */
            int tracked = 0;
            for (size_t i = 0; i < state.n_index && lost; i++)
                if (!strcmp (state.index[i].path, lost)) tracked = 1;
            fflush (stdout);
            if (tracked)
                fprintf (stderr, "error: Your local changes to the following "
                                 "files would be overwritten by merge:\n\t%s\n"
                                 "Please commit your changes or stash them "
                                 "before you merge.\nAborting\n", lost);
            else
                fprintf (stderr, "error: The following untracked working tree "
                                 "files would be overwritten by merge:\n\t%s\n"
                                 "Please move or remove them before you merge.\n"
                                 "Aborting\n", lost ? lost : "");
            free (lost);
            git_state_release (&state);
            return 1;
        }
        if (rc < 0 || git_index_store (ctx, state.index, state.n_index) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        char reflog[1200];
        snprintf (reflog, sizeof reflog, "merge %s: Fast-forward", label);
        const char *ref = state.branch ? state.branch : "HEAD";
        if (bgit_ref_update (&ctx->repo, ref, their_commit, state.head, reflog) < 0)
            status = GIT_EXIT_FATAL;
        if (!status && state.branch)
            bgit_reflog_append (&ctx->repo, "HEAD", state.head, their_commit, reflog);
        if (!status && !quiet) {
            printf ("Fast-forward\n");
            git_merge_summary (ctx, state.head_tree, their_tree);
        }
        git_state_release (&state);
        return status;
    }

    char base_tree[41];
    if (*made_up_base) memcpy (base_tree, made_up_base, 41);
    else if (bgit_commit_tree (&ctx->odb, base, base_tree) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0], base_tree,
                          state.head_tree, their_tree, "HEAD", label,
                          &paths, &n_paths) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (git_merge_safe (ctx, &state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        fprintf (stderr, "Merge with strategy ort failed.\n");
        return 2;
    }

    int conflicts = 0;
    for (size_t i = 0; i < n_paths; i++) {
        const bgit_merge_path *path = &paths[i];
        if (path->kind == BGIT_MERGE_AUTO || path->kind == BGIT_MERGE_CONTENT ||
            path->kind == BGIT_MERGE_ADD_ADD)
            printf ("Auto-merging %s\n", path->path);
        switch (path->kind) {
        case BGIT_MERGE_CONTENT:
            conflicts++;
            printf ("CONFLICT (content): Merge conflict in %s\n", path->path);
            break;
        case BGIT_MERGE_ADD_ADD:
            conflicts++;
            printf ("CONFLICT (add/add): Merge conflict in %s\n", path->path);
            break;
        case BGIT_MERGE_MODIFY_DELETE:
            conflicts++;
            printf ("CONFLICT (modify/delete): %s deleted in %s and modified in "
                    "%s.  Version %s of %s left in tree.\n", path->path,
                    path->deleted_in_ours ? "HEAD" : label,
                    path->deleted_in_ours ? label : "HEAD",
                    path->deleted_in_ours ? label : "HEAD", path->path);
            break;
        default:
            break;
        }
    }

    if (git_merge_apply (ctx, &state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    if (conflicts) {
        char content[8192];
        snprintf (content, sizeof content, "%s\n", their_commit);
        git_write_state_file (ctx, "MERGE_HEAD", content);
        size_t at = (size_t) snprintf (content, sizeof content,
                                       "%s\n\n# Conflicts:\n", subject);
        for (size_t i = 0; i < n_paths && at < sizeof content; i++)
            if (paths[i].kind != BGIT_MERGE_CLEAN && paths[i].kind != BGIT_MERGE_AUTO)
                at += (size_t) snprintf (content + at, sizeof content - at,
                                         "#\t%s\n", paths[i].path);
        git_write_state_file (ctx, "MERGE_MSG", content);
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        printf ("Automatic merge failed; fix conflicts and then commit the "
                "result.\n");
        return 1;
    }

    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                         state.n_index, tree) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (no_commit) {
        char content[128];
        snprintf (content, sizeof content, "%s\n", their_commit);
        git_write_state_file (ctx, "MERGE_HEAD", content);
        snprintf (content, sizeof content, "%s\n", subject);
        git_write_state_file (ctx, "MERGE_MSG", content);
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        printf ("Automatic merge went well; stopped before committing as "
                "requested\n");
        return 0;
    }

    char author[1024], committer[1024];
    {
        int trouble = git_identities (ctx, author, sizeof author, committer,
                                      sizeof committer);
        if (trouble) {
            bgit_merge_paths_free (paths, n_paths);
            git_state_release (&state);
            return trouble;
        }
    }
    /* With -e the message is written in the editor over what the merge
       would have said by itself. */
    char written[8192];
    if (edit) {
        char editmsg[4096];
        snprintf (editmsg, sizeof editmsg, "%s/MERGE_MSG", ctx->repo.git_dir);
        FILE *out = fopen (editmsg, "w");
        if (!out) {
            bgit_merge_paths_free (paths, n_paths);
            git_state_release (&state);
            return git_fatal ("could not write '%s'", editmsg);
        }
        fprintf (out, "%s\n", subject);
        git_commit_template (ctx, out, &state, author, committer, 0, 0);
        fclose (out);
        if (git_edit_file (ctx, editmsg, 0) < 0) {
            bgit_merge_paths_free (paths, n_paths);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        size_t len = 0;
        char *edited = git_message_body (editmsg, &len);
        if (!edited || !len) {
            free (edited);
            bgit_merge_paths_free (paths, n_paths);
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "Aborting commit due to empty commit message.\n");
            return 1;
        }
        snprintf (written, sizeof written, "%s", edited);
        free (edited);
        size_t at = strlen (written);
        while (at && written[at - 1] == '\n') written[--at] = '\0';
        snprintf (subject, sizeof subject, "%s", written);
    }
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) {
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    fprintf (builder, "tree %s\n", tree);
    fprintf (builder, "parent %s\n", state.head);
    fprintf (builder, "parent %s\n", their_commit);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    fprintf (builder, "\n%s\n", subject);
    fclose (builder);

    char commit[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1, commit);
    free (body);
    if (rc < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    char reflog[1200];
    snprintf (reflog, sizeof reflog, "merge %s: Merge made by the 'ort' strategy.",
              label);
    const char *ref = state.branch ? state.branch : "HEAD";
    if (bgit_ref_update (&ctx->repo, ref, commit, state.head, reflog) < 0)
        status = GIT_EXIT_FATAL;
    if (!status && state.branch)
        bgit_reflog_append (&ctx->repo, "HEAD", state.head, commit, reflog);
    if (!status && !quiet) {
        printf ("Merge made by the 'ort' strategy.\n");
        git_merge_summary (ctx, state.head_tree, tree);
    }
    bgit_merge_paths_free (paths, n_paths);
    git_state_release (&state);
    return status;
}

/* ---- packs -------------------------------------------------------------- */

/* One object of a pack being read through: where it starts, what it is,
   and what it turns out to be once any delta is applied. */
struct git_pack_entry {
    uint64_t offset;
    uint64_t data_offset;       /* where the deflated bytes begin */
    uint64_t base_offset;       /* an offset delta's base */
    unsigned char base_sha[20]; /* a reference delta's base */
    int type;                   /* the pack's own numbering */
    int real_type;              /* what a delta turns out to hold */
    uint64_t size;              /* the size the header claims */
    uint64_t end;               /* where this object's bytes stop */
    unsigned char sha[20];
    uint32_t crc;
    int resolved;
};

/* The entry a pack offset names. The scan records them in the order the
   pack holds them, so their offsets are already in order. */
static struct git_pack_entry *
git_pack_at (struct git_pack_entry *entries, size_t n, uint64_t offset)
{
    size_t low = 0, high = n;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (entries[mid].offset < offset) low = mid + 1;
        else if (entries[mid].offset > offset) high = mid;
        else return &entries[mid];
    }
    return NULL;
}

/* What a delta is a delta against, whichever way it names it; NULL for an
   object that stands on its own. */
static struct git_pack_entry *
git_pack_base (struct git_pack_entry *entries, size_t n,
               const struct git_pack_entry *entry)
{
    if (entry->type == BGIT_PACK_OFS_DELTA)
        return git_pack_at (entries, n, entry->base_offset);
    if (entry->type == BGIT_PACK_REF_DELTA)
        for (size_t i = 0; i < n; i++)
            if (entries[i].resolved &&
                !memcmp (entries[i].sha, entry->base_sha, 20))
                return &entries[i];
    return NULL;
}

/* A varint the way a pack writes a delta's base offset: seven bits at a
   time, most significant first, each continuation adding one. */
static int
git_pack_base_offset (const unsigned char *pack, size_t plen, uint64_t at,
                      uint64_t *delta, uint64_t *next)
{
    uint64_t value = 0;
    while (at < plen) {
        unsigned char c = pack[at++];
        if (value > (UINT64_MAX >> 7)) return -1;
        value = (value << 7) | (c & 0x7f);
        if (!(c & 0x80)) {
            *delta = value;
            *next = at;
            return 0;
        }
        if (value == UINT64_MAX) return -1;
        value += 1;
    }
    return -1;
}

/* Walk the pack once, noting where each object starts and ends. */
static int
git_pack_scan (const unsigned char *pack, size_t plen,
               struct git_pack_entry **out, size_t *n_out)
{
    if (plen < 32 || memcmp (pack, "PACK", 4)) {
        git_fatal ("not a packfile");
        return -1;
    }
    if (bgit_pack_be32 (pack + 4) != 2) {
        git_fatal ("unsupported pack version %u", bgit_pack_be32 (pack + 4));
        return -1;
    }
    size_t n = bgit_pack_be32 (pack + 8);
    if (n > plen - 32) {
        git_fatal ("impossible object count in packfile");
        return -1;
    }
    struct git_pack_entry *entries = calloc (n ? n : 1, sizeof *entries);
    if (!entries) return -1;

    uint64_t at = 12;
    for (size_t i = 0; i < n; i++) {
        struct git_pack_entry *entry = &entries[i];
        entry->offset = at;
        int type;
        uint64_t size, next;
        if (bgit_pack_read_obj_header (pack, plen - 20, at, &type, &size,
                                       &next) < 0) {
            free (entries);
            git_fatal ("malformed object header at %llu",
                       (unsigned long long) at);
            return -1;
        }
        entry->type = type;
        entry->size = size;
        if (type < BGIT_PACK_COMMIT || type > BGIT_PACK_REF_DELTA || type == 5) {
            free (entries);
            git_fatal ("invalid object type at %llu", (unsigned long long) at);
            return -1;
        }
        if (type == BGIT_PACK_OFS_DELTA) {
            uint64_t back = 0, after = 0;
            if (git_pack_base_offset (pack, plen - 20, next, &back, &after) < 0 ||
                back == 0 || back > at) {
                free (entries);
                git_fatal ("malformed delta offset at %llu",
                           (unsigned long long) at);
                return -1;
            }
            entry->base_offset = at - back;
            next = after;
        } else if (type == BGIT_PACK_REF_DELTA) {
            if (next + 20 > plen - 20) {
                free (entries);
                git_fatal ("truncated delta base at %llu",
                           (unsigned long long) at);
                return -1;
            }
            memcpy (entry->base_sha, pack + next, 20);
            next += 20;
        }
        entry->data_offset = next;
        unsigned char *data = NULL;
        size_t len = 0, used = 0;
        if (bgit_pack_inflate (pack + next, (size_t) (plen - 20 - next),
                               (size_t) size, &data, &len, &used) < 0) {
            free (entries);
            git_fatal ("cannot read the object at %llu",
                       (unsigned long long) at);
            return -1;
        }
        free (data);
        if (len != size) {
            free (entries);
            git_fatal ("object size mismatch at %llu", (unsigned long long) at);
            return -1;
        }
        entry->end = next + used;
        entry->crc = bgit_pack_crc32 (pack + at, (size_t) (entry->end - at));
        at = entry->end;
    }
    if (at != plen - 20) {
        free (entries);
        git_fatal ("trailing data in packfile");
        return -1;
    }
    *out = entries;
    *n_out = n;
    return 0;
}

/* The content of one object in the pack, with any delta applied. A pack
   sent over the wire may be thin: a delta in it can lean on an object the
   pack does not carry, which this end is expected to have already. ODB,
   when given, is where those are looked for; THIN, when given, is set if
   one was. */
static int
git_pack_content (const unsigned char *pack, size_t plen,
                  struct git_pack_entry *entries, size_t n, uint64_t offset,
                  int *type_out, unsigned char **out, size_t *len_out, int depth,
                  bgit_odb *odb, int *thin)
{
    if (depth > BGIT_PACK_MAX_DELTA_DEPTH) return -1;
    struct git_pack_entry *entry = git_pack_at (entries, n, offset);
    if (!entry) return -1;

    unsigned char *data = NULL;
    size_t len = 0, used = 0;
    if (bgit_pack_inflate (pack + entry->data_offset,
                           (size_t) (plen - 20 - entry->data_offset),
                           (size_t) entry->size, &data, &len, &used) < 0)
        return -1;
    if (entry->type != BGIT_PACK_OFS_DELTA && entry->type != BGIT_PACK_REF_DELTA) {
        *type_out = entry->type;
        *out = data;
        *len_out = len;
        return 0;
    }

    /* A delta: find its base, then apply. */
    struct git_pack_entry *base_entry = git_pack_base (entries, n, entry);
    unsigned char *base = NULL;
    size_t base_len = 0;
    int base_type = 0;
    if (!base_entry) {
        /* Not in the pack: the far end left it out because this end has
           it. Only a delta that names its base by id can be completed
           that way; one that names an offset has nothing to look up. */
        char hex[41];
        enum bgit_type type;
        if (!odb || entry->type != BGIT_PACK_REF_DELTA) { free (data); return -1; }
        bgit_sha_to_hex (entry->base_sha, hex);
        if (bgit_odb_read (odb, hex, &type, &base, &base_len) < 0) {
            free (data);
            return -1;
        }
        base_type = type == BGIT_COMMIT ? BGIT_PACK_COMMIT
                  : type == BGIT_TREE ? BGIT_PACK_TREE
                  : type == BGIT_BLOB ? BGIT_PACK_BLOB : BGIT_PACK_TAG;
        if (thin) *thin = 1;
    } else if (git_pack_content (pack, plen, entries, n, base_entry->offset,
                                 &base_type, &base, &base_len, depth + 1, odb,
                                 thin) < 0) {
        free (data);
        return -1;
    }
    unsigned char *applied = NULL;
    size_t applied_len = 0;
    int rc = bgit_pack_apply_delta (base, base_len, data, len, &applied,
                                    &applied_len);
    free (base);
    free (data);
    if (rc < 0) return -1;
    *type_out = base_type;
    *out = applied;
    *len_out = applied_len;
    return 0;
}

/* What leans on an object whose id is not known until it is settled: a
   delta that names its base by id waits under that id until the base
   comes out of the pack. */
struct git_pack_waiting {
    unsigned char sha[20];
    size_t head;                 /* the first waiting entry, plus one */
};

static struct git_pack_waiting *
git_pack_waiting_at (struct git_pack_waiting *table, size_t mask,
                     const unsigned char sha[20])
{
    size_t slot = 0;
    for (int i = 0; i < 8; i++) slot = (slot << 8) | sha[i];
    slot &= mask;
    while (table[slot].head && memcmp (table[slot].sha, sha, 20))
        slot = (slot + 1) & mask;
    return &table[slot];
}

/* Name one object, write it out, and settle everything that leans on it
   while it is still in hand — which is what makes this linear: an object
   is built once, however many deltas stand on it. */
static int
git_pack_settle (const unsigned char *pack, size_t plen,
                 struct git_pack_entry *entries, size_t n, size_t at,
                 int type, const unsigned char *content, size_t len,
                 size_t *first, size_t *sibling,
                 struct git_pack_waiting *table, size_t mask, int depth)
{
    char hex[41];
    if (bgit_write_object (NULL, bgit_pack_type_name (type), content, len, 0,
                           hex) < 0)
        return -1;
    bgit_hex_to_sha (hex, entries[at].sha);
    entries[at].real_type = type;
    entries[at].resolved = 1;
    if (depth >= BGIT_PACK_MAX_DELTA_DEPTH) return 0;

    size_t lists[2] = { first[at], 0 };
    if (mask) {
        struct git_pack_waiting *waiting = git_pack_waiting_at (table, mask,
                                                                entries[at].sha);
        if (waiting->head) lists[1] = waiting->head;
    }
    for (int which = 0; which < 2; which++)
        for (size_t child = lists[which]; child; child = sibling[child - 1]) {
            struct git_pack_entry *entry = &entries[child - 1];
            if (entry->resolved) continue;
            unsigned char *delta = NULL;
            size_t delta_len = 0, used = 0;
            if (bgit_pack_inflate (pack + entry->data_offset,
                                   (size_t) (plen - 20 - entry->data_offset),
                                   (size_t) entry->size, &delta, &delta_len,
                                   &used) < 0)
                return -1;
            unsigned char *applied = NULL;
            size_t applied_len = 0;
            int rc = bgit_pack_apply_delta (content, len, delta, delta_len,
                                            &applied, &applied_len);
            free (delta);
            if (rc < 0) return -1;
            rc = git_pack_settle (pack, plen, entries, n, child - 1, type,
                                  applied, applied_len, first, sibling, table,
                                  mask, depth + 1);
            free (applied);
            if (rc < 0) return -1;
        }
    return 0;
}

/* Name every object in the pack, from the ones that lean on nothing
   outwards. */
static int
git_pack_resolve (const unsigned char *pack, size_t plen,
                  struct git_pack_entry *entries, size_t n, bgit_odb *odb,
                  int *thin)
{
    size_t *first = calloc (n ? n : 1, sizeof *first);
    size_t *sibling = calloc (n ? n : 1, sizeof *sibling);
    size_t mask = 0, n_waiting = 0;
    for (size_t i = 0; i < n; i++)
        if (entries[i].type == BGIT_PACK_REF_DELTA) n_waiting++;
    if (n_waiting) {
        mask = 4;
        while (mask < n_waiting * 2) mask <<= 1;
        mask -= 1;
    }
    struct git_pack_waiting *table = mask
        ? calloc (mask + 1, sizeof *table) : NULL;
    if (!first || !sibling || (mask && !table)) {
        free (first); free (sibling); free (table);
        return -1;
    }

    /* Every delta hung under the object it leans on, by position for the
       kind that names an offset and by id for the kind that names one. */
    for (size_t i = n; i-- > 0; ) {
        struct git_pack_entry *entry = &entries[i];
        if (entry->type == BGIT_PACK_OFS_DELTA) {
            struct git_pack_entry *base = git_pack_at (entries, n,
                                                       entry->base_offset);
            if (!base) continue;
            size_t at = (size_t) (base - entries);
            sibling[i] = first[at];
            first[at] = i + 1;
        } else if (entry->type == BGIT_PACK_REF_DELTA && table) {
            struct git_pack_waiting *waiting =
                git_pack_waiting_at (table, mask, entry->base_sha);
            if (!waiting->head) memcpy (waiting->sha, entry->base_sha, 20);
            sibling[i] = waiting->head;
            waiting->head = i + 1;
        }
    }

    int failed = 0;
    for (size_t i = 0; i < n && !failed; i++) {
        struct git_pack_entry *entry = &entries[i];
        if (entry->resolved || entry->type == BGIT_PACK_OFS_DELTA ||
            entry->type == BGIT_PACK_REF_DELTA)
            continue;
        unsigned char *content = NULL;
        size_t len = 0, used = 0;
        if (bgit_pack_inflate (pack + entry->data_offset,
                               (size_t) (plen - 20 - entry->data_offset),
                               (size_t) entry->size, &content, &len, &used) < 0) {
            failed = 1;
            break;
        }
        if (git_pack_settle (pack, plen, entries, n, i, entry->type, content,
                             len, first, sibling, table, mask, 0) < 0)
            failed = 1;
        free (content);
    }

    /* What is left leans on something this pack does not carry, which only
       what is already here can answer: a thin pack, completed from it. */
    int more = !failed;
    while (more) {
        more = 0;
        for (size_t i = 0; i < n && !failed; i++) {
            if (entries[i].resolved) continue;
            int type = 0;
            unsigned char *content = NULL;
            size_t len = 0;
            if (git_pack_content (pack, plen, entries, n, entries[i].offset,
                                  &type, &content, &len, 0, odb, thin) < 0)
                continue;
            if (git_pack_settle (pack, plen, entries, n, i, type, content, len,
                                 first, sibling, table, mask, 0) < 0)
                failed = 1;
            free (content);
            more = 1;
        }
    }
    for (size_t i = 0; i < n && !failed; i++)
        if (!entries[i].resolved) {
            git_fatal ("the pack has deltas whose bases it does not carry");
            failed = 1;
        }

    free (first);
    free (sibling);
    free (table);
    return failed ? -1 : 0;
}

/* How many of the objects written before it a new one is held against,
   and how long a chain of deltas may grow: git's own defaults. */
#define GIT_PACK_WINDOW 10
#define GIT_PACK_DEPTH 50

/* One object on its way into a pack. */
struct git_pack_item {
    char id[41];
    int type;                 /* as the pack numbers the four kinds */
    size_t size;
    size_t at;                /* which index entry is this object's */
    uint32_t named;           /* the path it was found at, hashed */
    size_t parent;            /* the tree that named it, or none */
    char name[64];            /* what that tree called it */
};

/* The path an object was found at, as git hashes one for packing: the last
   characters count most, so things whose names end alike sort together —
   which is what puts one revision of a file next to another. */
static uint32_t
git_pack_name_hash (const char *name)
{
    uint32_t hash = 0;
    for (; *name; name++) {
        unsigned char ch = (unsigned char) *name;
        if (isspace (ch)) continue;
        hash = (hash >> 2) + ((uint32_t) ch << 24);
    }
    return hash;
}

/* One of the objects already written, kept to hold the next ones against.
   The index over its bytes is made once and asked many times. */
struct git_pack_held {
    unsigned char sha[20];
    unsigned char *content;
    size_t len;
    uint64_t off;
    int type;
    int depth;
    bgit_delta_index *index;
};

/* Like with like, then by name, then the larger first: two objects of a
   kind that are nearly the same are then near each other, which is what
   gives a window of ten anything to find. git orders a pack this way for
   the same reason. */
static int
git_pack_order (const void *one, const void *two)
{
    const struct git_pack_item *a = one, *b = two;
    if (a->type != b->type) return a->type > b->type ? -1 : 1;
    if (a->named != b->named) return a->named > b->named ? -1 : 1;
    if (a->size != b->size) return a->size > b->size ? -1 : 1;
    /* Everything else equal, the order they were gathered in, which walks
       a history from its tip: one revision of a tree then the one before
       it, which is where the good deltas are. */
    return a->at < b->at ? -1 : 1;
}

static void
git_pack_held_release (struct git_pack_held *held, size_t n)
{
    for (size_t i = 0; i < n; i++) {
        free (held[i].content);
        bgit_delta_index_free (held[i].index);
    }
}

/* Build a pack holding exactly the objects named. Each one goes in whole
   or as a delta against one of the ten written before it, whichever is
   smaller, which is how git packs. With OFS_OK a delta names its base by
   how far back it is, which is shorter and what git writes into a pack of
   its own; without it the base is named by its id, which every reader
   takes however the two ends agreed to talk. Gives back the bytes, the
   entries an index is made from, and the pack's own checksum. Returns 0,
   or -1 with git's message already said. */
static int
git_pack_build_deltas (bgit_odb *odb, char (*ids)[41], size_t n, int ofs_ok,
                       unsigned char **out, size_t *out_len,
                       struct bgit_pack_idx_entry **entries_out,
                       unsigned char checksum[20], char hex[41])
{
    unsigned char *body = NULL;
    size_t body_len = 0, body_cap = 0;
    struct bgit_pack_idx_entry *entries = calloc (n ? n : 1, sizeof *entries);
    struct git_pack_item *items = calloc (n ? n : 1, sizeof *items);
    if (!entries || !items) {
        free (entries);
        free (items);
        return -1;
    }

    /* Where each object is in this list, so that a tree can say what its
       entries are called. */
    size_t table = 4;
    while (table < n * 2) table <<= 1;
    size_t *slots = calloc (table, sizeof *slots);
    if (!slots) {
        free (entries);
        free (items);
        return -1;
    }
    for (size_t i = 0; i < n; i++) {
        items[i].parent = SIZE_MAX;
        snprintf (items[i].id, sizeof items[i].id, "%s", ids[i]);
        size_t slot = (size_t) (git_sha_hash (ids[i]) & (table - 1));
        while (slots[slot] && strcmp (items[slots[slot] - 1].id, ids[i]))
            slot = (slot + 1) & (table - 1);
        if (!slots[slot]) slots[slot] = i + 1;
    }

    /* What each object is and how big, so that like can be put with like,
       and what the trees call the objects under them. The content is read
       again when its turn comes: holding all of it at once would cost as
       much memory as the repository. */
    int failed = 0;
    for (size_t i = 0; i < n && !failed; i++) {
        enum bgit_type type;
        unsigned char *content = NULL;
        size_t len = 0;
        if (bgit_odb_read (odb, ids[i], &type, &content, &len) < 0) {
            git_fatal ("cannot read %s", ids[i]);
            failed = 1;
            break;
        }
        items[i].type = type == BGIT_COMMIT ? BGIT_PACK_COMMIT
                      : type == BGIT_TREE ? BGIT_PACK_TREE
                      : type == BGIT_BLOB ? BGIT_PACK_BLOB : BGIT_PACK_TAG;
        items[i].size = len;
        items[i].at = i;

        if (type == BGIT_TREE) {
            const unsigned char *at = content, *end = content + len;
            while (at < end) {
                const unsigned char *space = memchr (at, ' ', (size_t) (end - at));
                if (!space) break;
                const unsigned char *nul = memchr (space, '\0',
                                                  (size_t) (end - space));
                if (!nul || end - nul < 21) break;
                char child[41];
                bgit_sha_to_hex (nul + 1, child);
                size_t slot = (size_t) (git_sha_hash (child) & (table - 1));
                while (slots[slot] && strcmp (items[slots[slot] - 1].id, child))
                    slot = (slot + 1) & (table - 1);
                if (slots[slot]) {
                    struct git_pack_item *held = &items[slots[slot] - 1];
                    if (held->parent == SIZE_MAX && !*held->name) {
                        held->parent = i;
                        snprintf (held->name, sizeof held->name, "%.*s",
                                  (int) (nul - space - 1),
                                  (const char *) space + 1);
                    }
                }
                at = nul + 21;
            }
        }
        free (content);
    }
    free (slots);

    /* The whole path, put back together from the trees above it, is what
       git hashes to decide what sits next to what. */
    for (size_t i = 0; i < n && !failed; i++) {
        const char *parts[64];
        size_t n_parts = 0, cursor = i;
        while (cursor != SIZE_MAX && n_parts < 64 && *items[cursor].name) {
            parts[n_parts++] = items[cursor].name;
            cursor = items[cursor].parent;
        }
        char path[4096];
        size_t at = 0;
        path[0] = '\0';
        for (size_t part = n_parts; part-- > 0 && at < sizeof path; )
            at += (size_t) snprintf (path + at, sizeof path - at, "%s%s",
                                     at ? "/" : "", parts[part]);
        items[i].named = git_pack_name_hash (path);
    }
    if (!failed) qsort (items, n, sizeof *items, git_pack_order);

    unsigned char header[12] = { 'P', 'A', 'C', 'K', 0, 0, 0, 2 };
    header[8] = (unsigned char) ((n >> 24) & 0xff);
    header[9] = (unsigned char) ((n >> 16) & 0xff);
    header[10] = (unsigned char) ((n >> 8) & 0xff);
    header[11] = (unsigned char) (n & 0xff);
    if (!failed)
        failed = bgit_pack_buf_append (&body, &body_len, &body_cap, header,
                                       12) < 0;

    struct git_pack_held window[GIT_PACK_WINDOW];
    memset (window, 0, sizeof window);
    size_t n_window = 0;

    for (size_t i = 0; i < n && !failed; i++) {
        struct git_pack_item *item = &items[i];
        enum bgit_type type;
        unsigned char *content = NULL;
        size_t len = 0;
        if (bgit_odb_read (odb, item->id, &type, &content, &len) < 0) {
            git_fatal ("cannot read %s", item->id);
            failed = 1;
            break;
        }

        /* Held against the ones written before it, newest first, keeping
           whichever delta comes out smallest. A delta has to be half the
           object or better to be worth the base it drags along. */
        unsigned char *delta = NULL;
        size_t delta_len = 0;
        size_t against = 0;
        for (size_t j = n_window; j-- > 0; ) {
            if (window[j].type != item->type || !window[j].index ||
                window[j].depth >= GIT_PACK_DEPTH)
                continue;
            /* What a delta has to beat: half the object, less the twenty
               bytes a base costs to name, and less again for a base that
               already stands deep in a chain — which is how git keeps the
               chains from growing without end. A base far smaller than
               the object cannot get there, and is not tried. */
            size_t max = delta ? delta_len - 1 : (len > 20 ? len / 2 - 20 : 0);
            max = max * (size_t) (GIT_PACK_DEPTH - window[j].depth) /
                  GIT_PACK_DEPTH;
            if (!max) continue;
            if (window[j].len < len && len - window[j].len >= max) continue;
            unsigned char *tried = NULL;
            size_t tried_len = 0;
            if (bgit_delta_create (window[j].index, content, len, max, &tried,
                                   &tried_len) < 0)
                continue;
            free (delta);
            delta = tried;
            delta_len = tried_len;
            against = j;
        }

        uint64_t offset = body_len;
        unsigned char object_header[16];
        size_t header_len = 0;
        bgit_pack_encode_obj_header (delta ? (ofs_ok ? BGIT_PACK_OFS_DELTA
                                                    : BGIT_PACK_REF_DELTA)
                                           : item->type,
                                     delta ? delta_len : len, object_header,
                                     &header_len);
        if (bgit_pack_buf_append (&body, &body_len, &body_cap, object_header,
                                  header_len) < 0)
            failed = 1;
        if (!failed && delta && ofs_ok) {
            /* How far back the base is, seven bits to a byte, high bits
               first, each byte after the first standing for one more. */
            unsigned char back[16];
            size_t at = sizeof back - 1;
            uint64_t distance = offset - window[against].off;
            back[at] = (unsigned char) (distance & 127);
            while ((distance >>= 7))
                back[--at] = (unsigned char) (128 | (--distance & 127));
            if (bgit_pack_buf_append (&body, &body_len, &body_cap, back + at,
                                      sizeof back - at) < 0)
                failed = 1;
        } else if (!failed && delta &&
                   bgit_pack_buf_append (&body, &body_len, &body_cap,
                                         window[against].sha, 20) < 0)
            failed = 1;

        unsigned char *deflated = NULL;
        size_t deflated_len = 0;
        if (!failed && bgit_deflate (delta ? delta : content,
                                     delta ? delta_len : len, &deflated,
                                     &deflated_len) < 0)
            failed = 1;
        if (!failed && bgit_pack_buf_append (&body, &body_len, &body_cap,
                                            deflated, deflated_len) < 0)
            failed = 1;
        free (deflated);
        if (failed) {
            free (delta);
            free (content);
            break;
        }

        struct bgit_pack_idx_entry *entry = &entries[item->at];
        bgit_hex_to_sha (item->id, entry->sha);
        entry->off = offset;
        entry->crc = bgit_pack_crc32 (body + offset,
                                      (size_t) (body_len - offset));

        /* This object now stands as a base for the next ones. */
        int depth = delta ? window[against].depth + 1 : 0;
        free (delta);
        if (n_window == GIT_PACK_WINDOW) {
            free (window[0].content);
            bgit_delta_index_free (window[0].index);
            memmove (window, window + 1, (GIT_PACK_WINDOW - 1) * sizeof *window);
            n_window--;
        }
        struct git_pack_held *held = &window[n_window++];
        memset (held, 0, sizeof *held);
        memcpy (held->sha, entry->sha, 20);
        held->content = content;
        held->len = len;
        held->off = offset;
        held->type = item->type;
        held->depth = depth;
        held->index = bgit_delta_index_create (content, len);
    }

    git_pack_held_release (window, n_window);
    free (items);

    if (!failed) {
        bgit_sha1 (body, body_len, checksum);
        bgit_sha_to_hex (checksum, hex);
        if (bgit_pack_buf_append (&body, &body_len, &body_cap, checksum, 20) < 0)
            failed = 1;
    }
    if (failed) {
        free (body);
        free (entries);
        return -1;
    }
    *out = body;
    *out_len = body_len;
    *entries_out = entries;
    return 0;
}

/* A pack for the far end of a connection, where the two sides have not
   said whether a delta may name its base by position. */
static int
git_pack_build (bgit_odb *odb, char (*ids)[41], size_t n, unsigned char **out,
                size_t *out_len, struct bgit_pack_idx_entry **entries_out,
                unsigned char checksum[20], char hex[41])
{
    return git_pack_build_deltas (odb, ids, n, 0, out, out_len, entries_out,
                                  checksum, hex);
}

/* git pack-objects: the ids arrive on the input, and the pack is written
   beside its index, named for its own checksum as git names one. */
static int
git_cmd_pack_objects (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git pack-objects [-q] <base-name> < <object-list>";
    const char *base = NULL;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) ;
        else if (!strcmp (w, "--stdout"))
            return git_fatal ("this build's git pack-objects writes files, "
                              "not a stream");
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!base) base = w;
        else return git_usage (usage);
    }
    if (!base) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    /* The ids to pack arrive on the input, one to a line; anything after
       the id on a line is a path, which pack-objects ignores. A builtin
       that read the input before this one leaves the end-of-file mark on
       the stream, so clear it before reading a word of the new input. */
    char (*ids)[41] = NULL;
    size_t n = 0, cap = 0;
    char line[4096];
    clearerr (stdin);
    while (fgets (line, sizeof line, stdin)) {
        char *space = strpbrk (line, " \t\n\r");
        if (space) *space = '\0';
        if (strlen (line) != 40) continue;
        if (n == cap) {
            size_t next = cap ? cap * 2 : 64;
            char (*grown)[41] = realloc (ids, next * sizeof *grown);
            if (!grown) { free (ids); return GIT_EXIT_FATAL; }
            ids = grown;
            cap = next;
        }
        memcpy (ids[n], line, 41);
        n++;
    }

    unsigned char *body = NULL;
    size_t body_len = 0;
    struct bgit_pack_idx_entry *entries = NULL;
    unsigned char checksum[20];
    char checksum_hex[41] = "";
    int status = git_pack_build_deltas (&ctx->odb, ids, n, 1, &body, &body_len,
                                        &entries, checksum,
                                        checksum_hex) < 0 ? GIT_EXIT_FATAL : 0;
    char pack_path[4096], idx_path[4096];
    if (!status) {
        snprintf (pack_path, sizeof pack_path, "%s-%s.pack", base, checksum_hex);
        snprintf (idx_path, sizeof idx_path, "%s-%s.idx", base, checksum_hex);
        FILE *out = fopen (pack_path, "w");
        if (!out || fwrite (body, 1, body_len, out) != body_len ||
            fclose (out) != 0)
            status = git_fatal ("cannot write %s", pack_path);
    }
    if (!status && bgit_pack_write_idx_v2 (idx_path, entries, n, checksum) < 0)
        status = GIT_EXIT_FATAL;
    if (!status) printf ("%s\n", checksum_hex);
    free (body);
    free (entries);
    free (ids);
    return status;
}

/* ---- repack ------------------------------------------------------------- */

/* Every object a repack should hold: what the refs, the index and the
   reflogs reach. UNPACKED_ONLY leaves out what a pack already holds, which
   is what an incremental repack packs. Caller frees *out. */
static int
git_repack_objects (git_context *ctx, int unpacked_only, char (**out)[41],
                    size_t *n_out)
{
    *out = NULL;
    *n_out = 0;
    struct git_fsck state;
    memset (&state, 0, sizeof state);
    state.ctx = ctx;
    if (git_fsck_collect (&state) < 0) return -1;
    for (size_t i = 0; i < state.n; i++) state.objects[i].present = 1;

    struct git_fsck_walk walk;
    memset (&walk, 0, sizeof walk);
    git_fsck_heads (&state, &walk, 1, 1, 0);
    git_fsck_reach (&state, &walk);
    free (walk.pending);

    char (*ids)[41] = malloc ((state.n ? state.n : 1) * sizeof *ids);
    size_t n = 0;
    if (!ids) {
        free (state.objects);
        free (state.absent);
        return -1;
    }
    for (size_t i = 0; i < state.n; i++) {
        if (!state.objects[i].reachable) continue;
        if (unpacked_only && bgit_odb_packed (&ctx->odb, state.objects[i].sha))
            continue;
        memcpy (ids[n++], state.objects[i].sha, 41);
    }
    free (state.objects);
    free (state.absent);
    *out = ids;
    *n_out = n;
    return 0;
}

static int git_repack_run (git_context *ctx, int all, int remove_redundant);

/* Put what is reachable into one pack, and with -d take away what that
   makes redundant: the packs it replaces and the loose copies it holds. */
static int
git_cmd_repack (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git repack [-a] [-d] [-q] [-l] [-f] "
                        "[--window=<n>] [--depth=<n>]";
    int all = 0, remove_redundant = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-a") || !strcmp (w, "-A")) all = 1;
        else if (!strcmp (w, "-d")) remove_redundant = 1;
        else if (!strcmp (w, "-ad") || !strcmp (w, "-da")) { all = 1; remove_redundant = 1; }
        /* Accepted and no more than that: this build packs from scratch
           every time, in one thread, without bitmaps or a cruft pack. */
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet") ||
                 !strcmp (w, "-l") || !strcmp (w, "--local") ||
                 !strcmp (w, "-f") || !strcmp (w, "-F") ||
                 !strcmp (w, "-n") || !strcmp (w, "--no-update-server-info") ||
                 !strcmp (w, "--honor-pack-keep") ||
                 !strcmp (w, "--write-bitmap-index") ||
                 !strcmp (w, "--no-write-bitmap-index") ||
                 !strncmp (w, "--window=", 9) || !strncmp (w, "--depth=", 8) ||
                 !strncmp (w, "--threads=", 10) ||
                 !strncmp (w, "--max-pack-size=", 16) ||
                 !strncmp (w, "--unpack-unreachable=", 21) ||
                 !strcmp (w, "--keep-unreachable") || !strcmp (w, "--cruft"))
            ;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    return git_repack_run (ctx, all, remove_redundant);
}

/* Written out below git repack, which is what asks for it; git gc asks too. */
static int
git_repack_run (git_context *ctx, int all, int remove_redundant)
{
    if (!ctx->odb.n_object_dirs) return git_fatal ("no object directory");
    const char *objects = ctx->odb.object_dirs[0];

    char (*ids)[41] = NULL;
    size_t n = 0;
    if (git_repack_objects (ctx, !all, &ids, &n) < 0)
        return git_fatal ("out of memory");
    int packed_now = n > 0;
    if (!packed_now && !all) printf ("Nothing new to pack.\n");

    unsigned char *body = NULL;
    size_t body_len = 0;
    struct bgit_pack_idx_entry *entries = NULL;
    unsigned char checksum[20];
    char checksum_hex[41] = "";
    if (packed_now &&
        git_pack_build_deltas (&ctx->odb, ids, n, 1, &body, &body_len, &entries,
                               checksum, checksum_hex) < 0) {
        free (ids);
        return GIT_EXIT_FATAL;
    }

    char pack_dir[4096], pack_path[4096], idx_path[4096], base[4096];
    int status = 0;
    if ((size_t) snprintf (pack_dir, sizeof pack_dir, "%s/pack",
                           objects) >= sizeof pack_dir)
        status = git_fatal ("path too long");
    if (!status && packed_now) {
        mkdir (pack_dir, 0777);   /* objects/ is already there */
        snprintf (base, sizeof base, "%s/pack-%s", pack_dir, checksum_hex);
        snprintf (pack_path, sizeof pack_path, "%s.pack", base);
        snprintf (idx_path, sizeof idx_path, "%s.idx", base);
        /* Written beside its final name and moved onto it, so a reader
           never sees half a pack. */
        char temp[4096];
        snprintf (temp, sizeof temp, "%s.tmp-%ld", base, (long) getpid ());
        FILE *out = fopen (temp, "w");
        if (!out || fwrite (body, 1, body_len, out) != body_len ||
            fclose (out) != 0) {
            if (out) fclose (out);
            unlink (temp);
            status = git_fatal ("cannot write %s", pack_path);
        } else if (rename (temp, pack_path) != 0) {
            unlink (temp);
            status = git_fatal ("cannot write %s", pack_path);
        }
    }
    if (!status && packed_now &&
        bgit_pack_write_idx_v2 (idx_path, entries, n, checksum) < 0)
        status = GIT_EXIT_FATAL;
    free (body);
    free (entries);

    if (!status && remove_redundant) {
        /* The packs this one replaces. A pack someone asked to keep stays,
           and so does everything in it. */
        if (all && packed_now) {
            DIR *handle = opendir (pack_dir);
            if (handle) {
                struct dirent *entry;
                while ((entry = readdir (handle))) {
                    size_t len = strlen (entry->d_name);
                    if (len < 6 || strncmp (entry->d_name, "pack-", 5)) continue;
                    const char *dot = strrchr (entry->d_name, '.');
                    if (!dot) continue;
                    if (strcmp (dot, ".pack") && strcmp (dot, ".idx") &&
                        strcmp (dot, ".rev") && strcmp (dot, ".bitmap") &&
                        strcmp (dot, ".mtimes"))
                        continue;
                    char stem[4096];
                    snprintf (stem, sizeof stem, "%.*s",
                              (int) (dot - entry->d_name), entry->d_name);
                    if (!strcmp (stem + 5, checksum_hex)) continue;
                    char keep[4096];
                    if ((size_t) snprintf (keep, sizeof keep, "%s/%s.keep",
                                           pack_dir, stem) >= sizeof keep)
                        continue;
                    struct stat st;
                    if (stat (keep, &st) == 0) continue;
                    char path[4096];
                    if ((size_t) snprintf (path, sizeof path, "%s/%s", pack_dir,
                                           entry->d_name) >= sizeof path)
                        continue;
                    unlink (path);
                }
                closedir (handle);
            }
        }
        /* And every loose object a pack holds, the new one or an older
           one: keeping both copies is what -d is there to stop. */
        for (size_t i = 0; i < n; i++) {
            char path[4096];
            if (bgit_odb_loose_path (&ctx->odb, ids[i], path, sizeof path) == 0)
                unlink (path);
        }
        DIR *top = opendir (objects);
        if (top) {
            struct dirent *entry;
            while ((entry = readdir (top))) {
                if (strlen (entry->d_name) != 2 ||
                    !isxdigit ((unsigned char) entry->d_name[0]) ||
                    !isxdigit ((unsigned char) entry->d_name[1]))
                    continue;
                char dir[4096];
                if ((size_t) snprintf (dir, sizeof dir, "%s/%s", objects,
                                       entry->d_name) >= sizeof dir)
                    continue;
                DIR *inner = opendir (dir);
                if (inner) {
                    struct dirent *one;
                    while ((one = readdir (inner))) {
                        if (strlen (one->d_name) != 38) continue;
                        char sha[41];
                        sha[0] = entry->d_name[0];
                        sha[1] = entry->d_name[1];
                        memcpy (sha + 2, one->d_name, 38);
                        sha[40] = '\0';
                        if (!bgit_all_hex (sha)) continue;
                        if (!bgit_odb_packed (&ctx->odb, sha)) continue;
                        char path[4096];
                        if ((size_t) snprintf (path, sizeof path, "%s/%s", dir,
                                               one->d_name) >= sizeof path)
                            continue;
                        unlink (path);
                    }
                    closedir (inner);
                }
                rmdir (dir);            /* only when it is empty */
            }
            closedir (top);
        }
    }
    free (ids);
    return status;
}

/* ---- gc ----------------------------------------------------------------- */

/* Both written out beside git worktree, which is what makes them. */
static int git_remove_path (const char *full);

/* How many loose objects there are, which is what --auto looks at before
   deciding there is anything to do. It stops counting at LIMIT, since the
   answer past that is only "enough". */
static unsigned long
git_loose_count (git_context *ctx, unsigned long limit)
{
    if (!ctx->odb.n_object_dirs) return 0;
    const char *objects = ctx->odb.object_dirs[0];
    unsigned long count = 0;
    DIR *top = opendir (objects);
    if (!top) return 0;
    struct dirent *entry;
    while ((entry = readdir (top)) && count < limit) {
        if (strlen (entry->d_name) != 2 ||
            !isxdigit ((unsigned char) entry->d_name[0]) ||
            !isxdigit ((unsigned char) entry->d_name[1]))
            continue;
        char dir[4096];
        if ((size_t) snprintf (dir, sizeof dir, "%s/%s", objects,
                               entry->d_name) >= sizeof dir)
            continue;
        DIR *inner = opendir (dir);
        if (!inner) continue;
        struct dirent *one;
        while ((one = readdir (inner)) && count < limit)
            if (strlen (one->d_name) == 38) count++;
        closedir (inner);
    }
    closedir (top);
    return count;
}

/* How many packs there are, which --auto looks at as well. */
static unsigned long
git_pack_count (git_context *ctx)
{
    if (!ctx->odb.n_object_dirs) return 0;
    char dir[4096];
    if ((size_t) snprintf (dir, sizeof dir, "%s/pack",
                           ctx->odb.object_dirs[0]) >= sizeof dir)
        return 0;
    DIR *handle = opendir (dir);
    if (!handle) return 0;
    unsigned long count = 0;
    struct dirent *entry;
    while ((entry = readdir (handle))) {
        size_t len = strlen (entry->d_name);
        if (len > 5 && !strcmp (entry->d_name + len - 5, ".pack")) count++;
    }
    closedir (handle);
    return count;
}

/* One reflog, with the entries that have been there long enough taken out.
   An entry the ref can still be walked back to is kept longer than one it
   cannot, which is the difference between gc's two cutoffs. The file stays
   even when nothing is left in it, as git leaves it. */
static void
git_gc_expire_log (git_context *ctx, const char *path, const char *refname,
                   time_t keep_after, time_t keep_unreachable_after)
{
    unsigned char *raw = NULL;
    size_t len = 0;
    if (bgit_slurp_file (path, &raw, &len) < 0) return;
    char tip[41] = "";
    if (bgit_ref_resolve (&ctx->repo, refname, tip, NULL) != 0 ||
        !bgit_all_hex (tip))
        tip[0] = '\0';

    char *kept = malloc (len + 1);
    size_t kept_len = 0;
    if (!kept) { free (raw); return; }
    size_t at = 0;
    while (at < len) {
        size_t end = at;
        while (end < len && raw[end] != '\n') end++;
        size_t line_len = end - at;
        const char *line = (const char *) raw + at;
        /* "<old> <new> <who> <time> <tz>[\t<message>]" */
        const char *tab = memchr (line, '\t', line_len);
        size_t head_len = tab ? (size_t) (tab - line) : line_len;
        long long when = 0;
        const char *scan = line + head_len;
        int fields = 0;
        while (scan > line && fields < 2) {
            const char *space = memrchr (line, ' ', (size_t) (scan - line));
            if (!space) break;
            fields++;
            if (fields == 2) when = strtoll (space + 1, NULL, 10);
            scan = space;
        }
        int keep = 1;
        if (line_len && fields == 2) {
            if (when <= (long long) keep_after) keep = 0;
            else if (when <= (long long) keep_unreachable_after &&
                     line_len > 81 && *tip) {
                char id[41];
                memcpy (id, line + 41, 40);
                id[40] = '\0';
                if (bgit_all_hex (id) &&
                    bgit_is_ancestor (&ctx->odb, id, tip) <= 0)
                    keep = 0;
            }
        }
        if (keep && line_len) {
            memcpy (kept + kept_len, line, line_len);
            kept_len += line_len;
            kept[kept_len++] = '\n';
        }
        at = end + 1;
    }
    if (kept_len != len) {
        char temp[4096];
        if ((size_t) snprintf (temp, sizeof temp, "%s.gc-%ld", path,
                               (long) getpid ()) < sizeof temp) {
            FILE *out = fopen (temp, "w");
            if (out) {
                int ok = kept_len == 0 ||
                         fwrite (kept, 1, kept_len, out) == kept_len;
                if (fclose (out) != 0) ok = 0;
                if (!ok || rename (temp, path) != 0) unlink (temp);
            }
        }
    }
    free (kept);
    free (raw);
}

/* Every reflog under the git directory, except the stash's: git leaves
   that one alone however old it is, and what it holds is only there. */
static void
git_gc_expire_reflogs (git_context *ctx, const char *dir, const char *prefix,
                       time_t keep_after, time_t keep_unreachable_after)
{
    DIR *handle = opendir (dir);
    if (!handle) return;
    struct dirent *entry;
    while ((entry = readdir (handle))) {
        if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, ".."))
            continue;
        char path[4096], name[4096];
        if ((size_t) snprintf (path, sizeof path, "%s/%s", dir,
                               entry->d_name) >= sizeof path)
            continue;
        if ((size_t) snprintf (name, sizeof name, "%s%s%s", prefix,
                               *prefix ? "/" : "", entry->d_name) >= sizeof name)
            continue;
        struct stat st;
        if (lstat (path, &st) < 0) continue;
        if (S_ISDIR (st.st_mode)) {
            git_gc_expire_reflogs (ctx, path, name, keep_after,
                                   keep_unreachable_after);
            continue;
        }
        if (!strcmp (name, "refs/stash")) continue;
        git_gc_expire_log (ctx, path, name, keep_after, keep_unreachable_after);
    }
    closedir (handle);
}

/* The housekeeping, in git's order: everything reachable into one pack,
   the loose copies away with it, then what is unreachable and old enough
   to go, and the administrative directories of worktrees that are gone. */
static int
git_cmd_gc (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git gc [-q | --quiet] [--aggressive] [--auto] "
                        "[--force] [--prune=<date> | --no-prune]";
    int auto_only = 0, prune = 1;
    time_t expire = 0;
    int have_expire = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--auto")) auto_only = 1;
        else if (!strcmp (w, "--no-prune")) prune = 0;
        else if (!strncmp (w, "--prune=", 8)) {
            prune = 1;
            expire = (time_t) git_approxidate (w + 8);
            have_expire = 1;
        } else if (!strcmp (w, "--prune")) { prune = 1; have_expire = 0; }
        /* Accepted and no more than that: this build packs the same way
           however hard it is asked to try, and says nothing as it goes. */
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet") ||
                 !strcmp (w, "--aggressive") || !strcmp (w, "--force") ||
                 !strcmp (w, "--cruft") || !strcmp (w, "--no-cruft") ||
                 !strcmp (w, "--keep-largest-pack") ||
                 !strncmp (w, "--max-cruft-size=", 17))
            ;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (auto_only) {
        /* git's own thresholds: enough loose objects to be worth packing,
           or enough packs to be worth joining. */
        unsigned long loose_limit = 6700, pack_limit = 50;
        const char *value = bgit_config_get (&ctx->cfg, "gc.auto");
        if (value && *value) loose_limit = strtoul (value, NULL, 10);
        value = bgit_config_get (&ctx->cfg, "gc.autopacklimit");
        if (value && *value) pack_limit = strtoul (value, NULL, 10);
        int enough = (loose_limit &&
                      git_loose_count (ctx, loose_limit) >= loose_limit) ||
                     (pack_limit && git_pack_count (ctx) > pack_limit);
        if (!enough) return 0;
    }

    /* First, since an entry that goes may be the only thing holding a
       commit, and the pack that follows should not take it in. */
    char logs[4096];
    if ((size_t) snprintf (logs, sizeof logs, "%s/logs",
                           ctx->repo.common_dir) < sizeof logs) {
        time_t keep_after = (time_t) git_approxidate ("90.days.ago");
        time_t keep_unreachable_after = (time_t) git_approxidate ("30.days.ago");
        const char *value = bgit_config_get (&ctx->cfg, "gc.reflogexpire");
        if (value && *value) keep_after = (time_t) git_approxidate (value);
        value = bgit_config_get (&ctx->cfg, "gc.reflogexpireunreachable");
        if (value && *value)
            keep_unreachable_after = (time_t) git_approxidate (value);
        git_gc_expire_reflogs (ctx, logs, "", keep_after,
                               keep_unreachable_after);
        /* A linked worktree keeps its own HEAD and its own log of it. */
        char worktrees[4096];
        if ((size_t) snprintf (worktrees, sizeof worktrees, "%s/worktrees",
                               ctx->repo.common_dir) < sizeof worktrees) {
            DIR *handle = opendir (worktrees);
            if (handle) {
                struct dirent *entry;
                while ((entry = readdir (handle))) {
                    if (entry->d_name[0] == '.') continue;
                    char dir[4096], name[4096];
                    if ((size_t) snprintf (dir, sizeof dir, "%s/%s/logs",
                                           worktrees,
                                           entry->d_name) >= sizeof dir)
                        continue;
                    if ((size_t) snprintf (name, sizeof name, "worktrees/%s",
                                           entry->d_name) >= sizeof name)
                        continue;
                    git_gc_expire_reflogs (ctx, dir, name, keep_after,
                                           keep_unreachable_after);
                }
                closedir (handle);
            }
        }
    }

    int status = git_repack_run (ctx, 1, 1);
    if (status) return status;
    /* The pack that was just written is not one the store knows about yet,
       and prune is about to ask what is where. */
    bgit_odb_release (&ctx->odb);
    if (bgit_odb_open (&ctx->repo, &ctx->odb) < 0)
        return git_fatal ("cannot reopen the object store");
    ctx->odb.quiet = 1;
    if (prune) {
        if (!have_expire) expire = (time_t) git_approxidate ("2.weeks.ago");
        status = git_prune_run (ctx, 0, 0, expire, NULL, 0);
        if (status) return status;
    }
    /* An administrative directory whose worktree is gone goes too — but not
       as soon as `git worktree prune` would take it: gc leaves one alone
       until it has been gone a while, in case the worktree is on a disk
       that is not mounted at the moment. */
    time_t worktree_expire = (time_t) git_approxidate ("3.months.ago");
    struct git_worktree *trees = NULL;
    size_t n = 0;
    if (git_worktrees (ctx, &trees, &n) == 0) {
        for (size_t i = 1; i < n; i++) {
            struct stat st;
            if (lstat (trees[i].path, &st) == 0) continue;
            char marker[4096];
            if ((size_t) snprintf (marker, sizeof marker, "%s/gitdir",
                                   trees[i].admin) >= sizeof marker)
                continue;
            if (stat (marker, &st) == 0 && st.st_mtime > worktree_expire)
                continue;
            git_remove_path (trees[i].admin);
        }
        free (trees);
    }
    return 0;
}

static int
git_cmd_index_pack (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git index-pack [-v] [-o <index-file>] <pack-file>";
    const char *pack_path = NULL, *idx_path = NULL;
    (void) ctx;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        /* -v asks for progress, which is for a person watching. */
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) ;
        else if (!strcmp (w, "-o") && p->next) { idx_path = p->next->word->word; p = p->next; }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!pack_path) pack_path = w;
        else return git_usage (usage);
    }
    if (!pack_path) return git_usage (usage);

    size_t plen = 0;
    unsigned char *pack = bgit_pack_slurp (pack_path, &plen);
    if (!pack) return git_fatal ("cannot read %s: %s", pack_path,
                                 strerror (errno));
    struct git_pack_entry *entries = NULL;
    size_t n = 0;
    if (git_pack_scan (pack, plen, &entries, &n) < 0) {
        free (pack);
        return GIT_EXIT_FATAL;
    }
    /* A pack on disk must carry everything it needs; git's index-pack
       completes one only when it is told to. */
    if (git_pack_resolve (pack, plen, entries, n, NULL, NULL) < 0) {
        free (entries);
        free (pack);
        return GIT_EXIT_FATAL;
    }

    struct bgit_pack_idx_entry *idx_entries = calloc (n ? n : 1,
                                                      sizeof *idx_entries);
    if (!idx_entries) {
        free (entries);
        free (pack);
        return GIT_EXIT_FATAL;
    }
    for (size_t i = 0; i < n; i++) {
        memcpy (idx_entries[i].sha, entries[i].sha, 20);
        idx_entries[i].crc = entries[i].crc;
        idx_entries[i].off = entries[i].offset;
    }
    char chosen[4096];
    if (!idx_path) {
        size_t len = strlen (pack_path);
        if (len > 5 && !strcmp (pack_path + len - 5, ".pack"))
            snprintf (chosen, sizeof chosen, "%.*s.idx", (int) (len - 5), pack_path);
        else snprintf (chosen, sizeof chosen, "%s.idx", pack_path);
        idx_path = chosen;
    }
    int status = bgit_pack_write_idx_v2 (idx_path, idx_entries, n,
                                         pack + plen - 20) < 0
                 ? GIT_EXIT_FATAL : 0;
    if (!status) {
        char hex[41];
        bgit_sha_to_hex (pack + plen - 20, hex);
        printf ("%s\n", hex);
    }
    free (idx_entries);
    free (entries);
    free (pack);
    return status;
}

static int
git_cmd_unpack_objects (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git unpack-objects [-q] < <pack-file>";
    const char *pack_path = NULL;
    int quiet = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!pack_path) pack_path = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    unsigned char *pack = NULL;
    size_t plen = 0;
    if (pack_path) {
        pack = bgit_pack_slurp (pack_path, &plen);
        if (!pack) return git_fatal ("cannot read %s: %s", pack_path,
                                     strerror (errno));
    } else if (bgit_slurp_fd (0, &pack, &plen) < 0)
        return git_fatal ("cannot read the pack from the input");

    struct git_pack_entry *entries = NULL;
    size_t n = 0;
    if (git_pack_scan (pack, plen, &entries, &n) < 0 ||
        git_pack_resolve (pack, plen, entries, n, &ctx->odb, NULL) < 0) {
        free (entries);
        free (pack);
        return GIT_EXIT_FATAL;
    }
    int status = 0;
    for (size_t i = 0; i < n && !status; i++) {
        int type = 0;
        unsigned char *content = NULL;
        size_t len = 0;
        if (git_pack_content (pack, plen, entries, n, entries[i].offset, &type,
                              &content, &len, 0, &ctx->odb, NULL) < 0) {
            status = GIT_EXIT_FATAL;
            break;
        }
        char hex[41];
        if (bgit_write_object (ctx->odb.object_dirs[0],
                               bgit_pack_type_name (type), content, len, 1,
                               hex) < 0)
            status = GIT_EXIT_FATAL;
        free (content);
    }
    /* Progress is for a person watching: git keeps it off a pipe. */
    if (!status && !quiet && isatty (STDERR_FILENO))
        fprintf (stderr, "Unpacking objects: 100%% (%zu/%zu), done.\n", n, n);
    free (entries);
    free (pack);
    return status;
}

static int
git_cmd_verify_pack (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git verify-pack [-v] [-s] <idx-file>";
    const char *idx_path = NULL;
    int verbose = 0, stat_only = 0;
    (void) ctx;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "-s") || !strcmp (w, "--stat-only")) stat_only = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!idx_path) idx_path = w;
        else return git_usage (usage);
    }
    if (!idx_path) return git_usage (usage);

    /* The name can be the index, the pack, or neither suffix. */
    char idx_buf[4096], pack_buf[4096];
    size_t len = strlen (idx_path);
    if (len > 4 && !strcmp (idx_path + len - 4, ".idx")) len -= 4;
    else if (len > 5 && !strcmp (idx_path + len - 5, ".pack")) len -= 5;
    snprintf (idx_buf, sizeof idx_buf, "%.*s.idx", (int) len, idx_path);
    snprintf (pack_buf, sizeof pack_buf, "%.*s.pack", (int) len, idx_path);
    idx_path = idx_buf;
    const char *pack_path = pack_buf;

    /* A pack that cannot be read is a failed verification, which git
       reports with 1, not the 128 a broken invocation gets. */
    size_t ilen = 0, plen = 0;
    unsigned char *idx = bgit_pack_slurp (idx_path, &ilen);
    unsigned char *pack = idx ? bgit_pack_slurp (pack_path, &plen) : NULL;
    if (!idx || !pack) {
        free (idx);
        fprintf (stderr, "fatal: Cannot open existing pack file '%s'\n",
                 idx_path);
        /* And then the verdict on the pack itself, which is what a caller
           reading the output is looking for. */
        fflush (stderr);
        printf ("%s: bad\n", pack_path);
        return 1;
    }
    int status = 0;
    if (bgit_pack_verify_idx (idx, ilen, NULL) < 0 ||
        bgit_pack_verify_idx_crc32 (idx, ilen, pack, plen) < 0)
        status = 1;

    /* Without an option git says nothing: the status is the answer. */
    if (!status && (verbose || stat_only)) {
        struct git_pack_entry *entries = NULL;
        size_t n = 0;
        size_t *chains = NULL;
        if (git_pack_scan (pack, plen, &entries, &n) < 0 ||
            git_pack_resolve (pack, plen, entries, n, NULL, NULL) < 0)
            status = 1;
        if (!status && !(chains = calloc (n + 1, sizeof *chains)))
            status = GIT_EXIT_FATAL;
        for (size_t i = 0; !status && i < n; i++) {
            /* How many deltas stand between this object and one held
               whole: none for an object that is held whole itself. */
            struct git_pack_entry *base = git_pack_base (entries, n, &entries[i]);
            size_t depth = 0;
            for (struct git_pack_entry *up = base; up;
                 up = git_pack_base (entries, n, up))
                depth++;
            chains[depth]++;
            if (!verbose) continue;
            /* Objects are listed in the order the pack holds them, with
               the size the pack holds — for a delta, that is the delta. */
            char hex[41];
            bgit_sha_to_hex (entries[i].sha, hex);
            printf ("%s %-6s %llu %llu %llu", hex,
                    bgit_pack_type_name (entries[i].real_type),
                    (unsigned long long) entries[i].size,
                    (unsigned long long) (entries[i].end - entries[i].offset),
                    (unsigned long long) entries[i].offset);
            if (depth) {
                char base_hex[41];
                bgit_sha_to_hex (base->sha, base_hex);
                printf (" %zu %s", depth, base_hex);
            }
            printf ("\n");
        }
        if (!status) {
            printf ("non delta: %zu object%s\n", chains[0],
                    chains[0] == 1 ? "" : "s");
            for (size_t d = 1; d <= n; d++)
                if (chains[d])
                    printf ("chain length = %zu: %zu object%s\n", d, chains[d],
                            chains[d] == 1 ? "" : "s");
        }
        free (chains);
        free (entries);
    }
    if (!status && verbose) printf ("%s: ok\n", pack_path);
    free (pack);
    free (idx);
    return status;
}

/* ---- remotes ------------------------------------------------------------ */

/* Write one setting into this repository's own configuration file. */
static int
git_config_write (git_context *ctx, const char *key, const char *value)
{
    char path[4096];
    bgit_config_repo_file (&ctx->repo, path, sizeof path);
    return bgit_config_set_file (path, key, value, 0);
}

/* Where a remote points, as its configuration says. */
static const char *
git_remote_url (git_context *ctx, const char *remote)
{
    char key[4096];
    snprintf (key, sizeof key, "remote.%s.url", remote);
    return bgit_config_get (&ctx->cfg, key);
}

/* http:// and https:// are the URLs this build can reach. */
static int
git_url_is_http (const char *url)
{
    return !strncmp (url, "http://", 7) || !strncmp (url, "https://", 8);
}

/* ssh://[user@]host[:port]/path, and the scp-style [user@]host:path that
   git reads the same way: a colon that stands before any slash. An address
   in brackets keeps its own colons — [::1]:repo.git. */
static int
git_url_is_ssh (const char *url)
{
    if (!strncmp (url, "ssh://", 6)) return 1;
    if (strstr (url, "://")) return 0;
    if (*url == '[') {
        const char *close = strstr (url, "]:");
        return close != NULL;
    }
    const char *colon = strchr (url, ':');
    const char *slash = strchr (url, '/');
    return colon && (!slash || colon < slash);
}

/* A path with no protocol in front of it. */
static int
git_local_only (const char *url)
{
    return !strstr (url, "://") && !git_url_is_ssh (url);
}

/* Somewhere this build can reach: a path, an address over HTTP, or a host
   to run the far end on over ssh. git's own port is not done. */
static int
git_can_reach (const char *url)
{
    return git_local_only (url) || git_url_is_http (url) ||
           git_url_is_ssh (url);
}

static int
git_cmd_remote (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git remote [-v] | add <name> <url> | remove <name> "
                        "| set-url <name> <url> | get-url <name> "
                        "| show [-n] <name> | prune [-n] <name>";
    const char *verb = NULL, *name = NULL, *url = NULL;
    int verbose = 0, no_query = 0, dry_run = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        /* -n means one thing to show and another to prune, which is how
           git reads it in each place. */
        else if (!strcmp (w, "-n") || !strcmp (w, "--dry-run")) {
            no_query = 1;
            dry_run = 1;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!verb) verb = w;
        else if (!name) name = w;
        else if (!url) url = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (!verb) {
        /* Every remote the configuration names, once each, in order. */
        char seen[64][256];
        size_t n_seen = 0;
        for (size_t i = 0; i < ctx->cfg.n; i++) {
            const char *key = ctx->cfg.entries[i].key;
            if (strncmp (key, "remote.", 7)) continue;
            const char *dot = strrchr (key, '.');
            if (!dot || dot <= key + 7) continue;
            char remote[256];
            size_t len = (size_t) (dot - key - 7);
            if (len >= sizeof remote) continue;
            memcpy (remote, key + 7, len);
            remote[len] = '\0';
            int known = 0;
            for (size_t j = 0; j < n_seen; j++)
                if (!strcmp (seen[j], remote)) known = 1;
            if (known || n_seen >= 64) continue;
            snprintf (seen[n_seen++], sizeof seen[0], "%s", remote);
        }
        /* git lists them by name, whatever order the file holds them in. */
        if (n_seen > 1) qsort (seen, n_seen, sizeof seen[0],
                               (int (*) (const void *, const void *)) strcmp);
        for (size_t i = 0; i < n_seen; i++) {
            if (!verbose) { printf ("%s\n", seen[i]); continue; }
            const char *where = git_remote_url (ctx, seen[i]);
            printf ("%s\t%s (fetch)\n", seen[i], where ? where : "");
            printf ("%s\t%s (push)\n", seen[i], where ? where : "");
        }
        return 0;
    }
    if (!strcmp (verb, "add")) {
        if (!name || !url) return git_usage (usage);
        if (git_remote_url (ctx, name))
            return git_fatal ("remote %s already exists.", name);
        char key[4096], value[4096];
        snprintf (key, sizeof key, "remote.%s.url", name);
        if (git_config_write (ctx, key, url) < 0) return GIT_EXIT_FATAL;
        snprintf (key, sizeof key, "remote.%s.fetch", name);
        snprintf (value, sizeof value, "+refs/heads/*:refs/remotes/%s/*", name);
        return git_config_write (ctx, key, value) < 0 ? GIT_EXIT_FATAL : 0;
    }
    if (!strcmp (verb, "set-url")) {
        if (!name || !url) return git_usage (usage);
        if (!git_remote_url (ctx, name))
            return git_fatal ("No such remote '%s'", name);
        char key[4096];
        snprintf (key, sizeof key, "remote.%s.url", name);
        return git_config_write (ctx, key, url) < 0 ? GIT_EXIT_FATAL : 0;
    }
    if (!strcmp (verb, "get-url")) {
        if (!name) return git_usage (usage);
        const char *where = git_remote_url (ctx, name);
        if (!where) return git_fatal ("No such remote '%s'", name);
        printf ("%s\n", where);
        return 0;
    }
    if (!strcmp (verb, "show")) {
        if (!name) return git_usage (usage);
        const char *where = git_remote_url (ctx, name);
        if (!where) return git_fatal ("No such remote '%s'", name);
        char key[4096];
        snprintf (key, sizeof key, "remote.%s.pushurl", name);
        const char *push_url = bgit_config_get (&ctx->cfg, key);
        printf ("* remote %s\n", name);
        printf ("  Fetch URL: %s\n", where);
        printf ("  Push  URL: %s\n", push_url ? push_url : where);

        /* What the far end has, unless -n says not to ask. */
        bgit_proto_ref *theirs = NULL;
        size_t n_theirs = 0;
        char head_branch[4096] = "";
        if (!no_query) {
            git_conn conn;
            if (git_far_end_open (&conn, ctx, where, NULL, 1) < 0)
                return GIT_EXIT_FATAL;
            const char *prefixes[2] = { "refs/heads/", "HEAD" };
            if (bgit_proto_ls_refs (&conn.io, prefixes, 2, 1, 0, &theirs,
                                    &n_theirs) < 0) {
                git_far_end_gone ();
                git_conn_close (&conn);
                return GIT_EXIT_FATAL;
            }
            git_conn_close (&conn);
            for (size_t i = 0; i < n_theirs; i++)
                if (!strcmp (theirs[i].name, "HEAD") && theirs[i].symref &&
                    !strncmp (theirs[i].symref, "refs/heads/", 11))
                    snprintf (head_branch, sizeof head_branch, "%s",
                              theirs[i].symref + 11);
            printf ("  HEAD branch: %s\n", *head_branch ? head_branch : "(unknown)");
        } else printf ("  HEAD branch: (not queried)\n");

        /* The branches: theirs, ours, and the ones only one side has. */
        char prefix[4096];
        snprintf (prefix, sizeof prefix, "refs/remotes/%s/", name);
        bgit_ref *mine = NULL;
        size_t n_mine = 0;
        bgit_refs_list (&ctx->repo, prefix, &mine, &n_mine);
        struct { char shown[4096]; const char *state; } listed[256];
        size_t n_listed = 0;
        for (size_t i = 0; i < n_theirs && n_listed < 256; i++) {
            if (strncmp (theirs[i].name, "refs/heads/", 11)) continue;
            const char *short_name = theirs[i].name + 11;
            int tracked = 0;
            for (size_t j = 0; j < n_mine; j++)
                if (!strcmp (mine[j].name + strlen (prefix), short_name))
                    tracked = 1;
            snprintf (listed[n_listed].shown, sizeof listed[n_listed].shown,
                      "%s", short_name);
            listed[n_listed].state = tracked ? "tracked"
                : "new (next fetch will store in remotes/" ;
            n_listed++;
        }
        /* One we have that they no longer do is stale, and shows under the
           whole name of the ref that holds it. */
        for (size_t j = 0; j < n_mine && n_listed < 256; j++) {
            const char *short_name = mine[j].name + strlen (prefix);
            if (!strcmp (short_name, "HEAD")) continue;
            int still_there = no_query;
            for (size_t i = 0; i < n_theirs && !still_there; i++)
                if (!strncmp (theirs[i].name, "refs/heads/", 11) &&
                    !strcmp (theirs[i].name + 11, short_name))
                    still_there = 1;
            if (still_there) {
                if (no_query) {
                    snprintf (listed[n_listed].shown,
                              sizeof listed[n_listed].shown, "%s", short_name);
                    listed[n_listed].state = "";
                    n_listed++;
                }
                continue;
            }
            snprintf (listed[n_listed].shown, sizeof listed[n_listed].shown,
                      "%s", mine[j].name);
            listed[n_listed].state = "stale (use 'git remote prune' to remove)";
            n_listed++;
        }
        /* git lists them by the name it shows, and lines the states up. */
        for (size_t i = 0; i + 1 < n_listed; i++)
            for (size_t j = 0; j + 1 < n_listed - i; j++)
                if (strcmp (listed[j].shown, listed[j + 1].shown) > 0) {
                    char held[4096];
                    const char *state = listed[j].state;
                    snprintf (held, sizeof held, "%s", listed[j].shown);
                    snprintf (listed[j].shown, sizeof listed[j].shown, "%s",
                              listed[j + 1].shown);
                    listed[j].state = listed[j + 1].state;
                    snprintf (listed[j + 1].shown, sizeof listed[j + 1].shown,
                              "%s", held);
                    listed[j + 1].state = state;
                }
        size_t width = 0;
        for (size_t i = 0; i < n_listed; i++) {
            size_t len = strlen (listed[i].shown);
            if (*listed[i].state && len > width) width = len;
        }
        printf ("  Remote branch%s:%s\n", n_listed == 1 ? "" : "es",
                no_query ? " (status not queried)" : "");
        for (size_t i = 0; i < n_listed; i++) {
            if (!*listed[i].state) { printf ("    %s\n", listed[i].shown); continue; }
            if (!strncmp (listed[i].state, "new (next", 9))
                printf ("    %-*s new (next fetch will store in remotes/%s)\n",
                        (int) width, listed[i].shown, name);
            else printf ("    %-*s %s\n", (int) width, listed[i].shown,
                         listed[i].state);
        }
        bgit_refs_free (mine, n_mine);
        bgit_proto_refs_release (theirs, n_theirs);

        /* Which of our branches follow one of theirs, and which push where. */
        bgit_ref *branches = NULL;
        size_t n_branches = 0;
        bgit_refs_list (&ctx->repo, "refs/heads/", &branches, &n_branches);
        struct { char local[4096]; char remote[4096]; } pulls[256];
        size_t n_pulls = 0;
        for (size_t i = 0; i < n_branches && n_pulls < 256; i++) {
            const char *short_name = branches[i].name + strlen ("refs/heads/");
            snprintf (key, sizeof key, "branch.%s.remote", short_name);
            const char *its_remote = bgit_config_get (&ctx->cfg, key);
            snprintf (key, sizeof key, "branch.%s.merge", short_name);
            const char *merge = bgit_config_get (&ctx->cfg, key);
            if (!its_remote || !merge || strcmp (its_remote, name)) continue;
            snprintf (pulls[n_pulls].local, sizeof pulls[n_pulls].local, "%s",
                      short_name);
            snprintf (pulls[n_pulls].remote, sizeof pulls[n_pulls].remote, "%s",
                      !strncmp (merge, "refs/heads/", 11) ? merge + 11 : merge);
            n_pulls++;
        }
        if (n_pulls) {
            size_t pull_width = 0;
            for (size_t i = 0; i < n_pulls; i++)
                if (strlen (pulls[i].local) > pull_width)
                    pull_width = strlen (pulls[i].local);
            printf ("  Local branch%s configured for 'git pull':\n",
                    n_pulls == 1 ? "" : "es");
            for (size_t i = 0; i < n_pulls; i++)
                printf ("    %-*s merges with remote %s\n", (int) pull_width,
                        pulls[i].local, pulls[i].remote);
        }
        if (n_pulls) {
            /* Without asking the far end there is one line to write,
               whatever the branches are, so git says "ref" and not
               "refs". */
            printf ("  Local ref%s configured for 'git push'%s:\n",
                    (no_query || n_pulls == 1) ? "" : "s",
                    no_query ? " (status not queried)" : "");
            if (no_query) printf ("    (matching) pushes to (matching)\n");
            else {
                size_t push_width = 0, to_width = 0;
                for (size_t i = 0; i < n_pulls; i++) {
                    if (strlen (pulls[i].local) > push_width)
                        push_width = strlen (pulls[i].local);
                    if (strlen (pulls[i].remote) > to_width)
                        to_width = strlen (pulls[i].remote);
                }
                for (size_t i = 0; i < n_pulls; i++) {
                    /* Where the two stand, which is what git says in the
                       brackets. */
                    char local_id[41] = "", remote_id[41] = "";
                    char local_ref[4096], remote_ref[4096];
                    snprintf (local_ref, sizeof local_ref, "refs/heads/%s",
                              pulls[i].local);
                    snprintf (remote_ref, sizeof remote_ref, "%s%s", prefix,
                              pulls[i].remote);
                    bgit_ref_read (&ctx->repo, local_ref, local_id);
                    bgit_ref_read (&ctx->repo, remote_ref, remote_id);
                    const char *state = "";
                    if (!*remote_id) state = "create";
                    else if (!strcmp (local_id, remote_id)) state = "up to date";
                    else if (bgit_is_ancestor (&ctx->odb, remote_id,
                                               local_id) > 0)
                        state = "fast-forwardable";
                    else
                        /* Behind, or gone off on its own: either way the
                           push would not go, which is what git says. */
                        state = "local out of date";
                    printf ("    %-*s pushes to %-*s (%s)\n", (int) push_width,
                            pulls[i].local, (int) to_width, pulls[i].remote,
                            state);
                }
            }
        }
        bgit_refs_free (branches, n_branches);
        return 0;
    }
    if (!strcmp (verb, "prune")) {
        if (!name) return git_usage (usage);
        const char *where = git_remote_url (ctx, name);
        if (!where) return git_fatal ("No such remote '%s'", name);
        git_conn conn;
        if (git_far_end_open (&conn, ctx, where, NULL, 1) < 0)
            return GIT_EXIT_FATAL;
        bgit_proto_ref *theirs = NULL;
        size_t n_theirs = 0;
        const char *prefixes[1] = { "refs/heads/" };
        if (bgit_proto_ls_refs (&conn.io, prefixes, 1, 0, 0, &theirs,
                                &n_theirs) < 0) {
            git_far_end_gone ();
            git_conn_close (&conn);
            return GIT_EXIT_FATAL;
        }
        git_conn_close (&conn);
        char prefix[4096];
        snprintf (prefix, sizeof prefix, "refs/remotes/%s/", name);
        bgit_ref *mine = NULL;
        size_t n_mine = 0;
        bgit_refs_list (&ctx->repo, prefix, &mine, &n_mine);
        int said = 0;
        for (size_t j = 0; j < n_mine; j++) {
            const char *short_name = mine[j].name + strlen (prefix);
            if (!strcmp (short_name, "HEAD")) continue;
            int still_there = 0;
            for (size_t i = 0; i < n_theirs && !still_there; i++)
                if (!strncmp (theirs[i].name, "refs/heads/", 11) &&
                    !strcmp (theirs[i].name + 11, short_name))
                    still_there = 1;
            if (still_there) continue;
            if (!said) {
                printf ("Pruning %s\n", name);
                printf ("URL: %s\n", where);
                said = 1;
            }
            /* git names it the way a person would: the remote and the
               branch, not the whole ref. */
            printf (" * [%s] %s/%s\n", dry_run ? "would prune" : "pruned",
                    name, short_name);
            if (!dry_run) bgit_ref_delete (&ctx->repo, mine[j].name, NULL, NULL);
        }
        bgit_refs_free (mine, n_mine);
        bgit_proto_refs_release (theirs, n_theirs);
        return 0;
    }
    if (!strcmp (verb, "remove") || !strcmp (verb, "rm")) {
        if (!name) return git_usage (usage);
        if (!git_remote_url (ctx, name)) {
            fflush (stdout);
            fprintf (stderr, "error: No such remote: '%s'\n", name);
            return 2;
        }
        char path[4096], key[4096];
        bgit_config_repo_file (&ctx->repo, path, sizeof path);
        snprintf (key, sizeof key, "remote.%s.url", name);
        bgit_config_unset_file (path, key);
        snprintf (key, sizeof key, "remote.%s.fetch", name);
        bgit_config_unset_file (path, key);
        /* The tracking refs the remote left behind go with it. */
        char prefix[4096];
        snprintf (prefix, sizeof prefix, "refs/remotes/%s/", name);
        bgit_ref *refs = NULL;
        size_t n = 0;
        if (bgit_refs_list (&ctx->repo, prefix, &refs, &n) == 0) {
            for (size_t i = 0; i < n; i++)
                bgit_ref_delete (&ctx->repo, refs[i].name, NULL, NULL);
            bgit_refs_free (refs, n);
        }
        return 0;
    }
    return git_usage (usage);
}

/* Open the repository at the far end of a local remote.
   The path names that repository. Walking upward from a subdirectory,
   or from a directory that is not a repository, answered with some
   other repository's refs — including an empty .git left elsewhere on
   the machine. "." is the exception: it means the repository that
   contains the current directory, including from one of its subdirectories. */
static int
git_open_remote (const char *url, bgit_repo *repo, bgit_odb *odb)
{
    int rc = url && !strcmp (url, ".") ? bgit_repo_discover (".", repo)
                                       : bgit_repo_open (url, repo);
    if (rc < 0) return -1;
    if (bgit_odb_open (repo, odb) < 0) {
        bgit_repo_release (repo);
        return -1;
    }
    odb->quiet = 1;
    return 0;
}

/* ---- speaking the protocol ---------------------------------------------- */

/* What the server side of this build can do. A client reads this first
   and asks only for what it names. */
static int
git_v2_advertise (void)
{
    if (bgit_pkt_writef (1, "version 2\n") < 0 ||
        bgit_pkt_writef (1, "agent=%s\n", GIT_AGENT_STRING) < 0 ||
        bgit_pkt_writef (1, "ls-refs\n") < 0 ||
        bgit_pkt_writef (1, "fetch\n") < 0 ||
        bgit_pkt_writef (1, "object-format=sha1\n") < 0 ||
        bgit_pkt_flush (1) < 0)
        return -1;
    return 0;
}

/* 1 when the client asked about this ref; asking for no prefix at all
   asks for every ref there is. */
static int
git_v2_wanted (const char *name, char **prefixes, size_t n_prefixes)
{
    if (!n_prefixes) return 1;
    for (size_t i = 0; i < n_prefixes; i++)
        if (!strncmp (name, prefixes[i], strlen (prefixes[i]))) return 1;
    return 0;
}

/* What a tag points at, following tags until it reaches something that is
   not one. Returns 0 with OUT set, 1 when SHA is not a tag, or -1. */
static int
git_peel_fully (bgit_odb *odb, const char *sha, char out[41])
{
    char at[41];
    memcpy (at, sha, 41);
    for (int depth = 0; depth < 16; depth++) {
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t len = 0;
        if (bgit_odb_read (odb, at, &type, &data, &len) < 0) return -1;
        free (data);
        if (type != BGIT_TAG) {
            if (!depth) return 1;
            memcpy (out, at, 41);
            return 0;
        }
        char next[41];
        if (bgit_peel_to_type (odb, at, BGIT_UNKNOWN, next) < 0) return -1;
        memcpy (at, next, 41);
    }
    return -1;
}

/* Answer one ls-refs: every ref asked for, in git's order, HEAD first,
   with what HEAD points at and what a tag points at when those were
   asked for. */
static int
git_v2_ls_refs (bgit_repo *repo, bgit_odb *odb, char **prefixes,
                size_t n_prefixes, int want_symrefs, int want_peeled)
{
    char id[41];
    char *symref = NULL;
    if (bgit_ref_resolve (repo, "HEAD", id, &symref) == 0 &&
        git_v2_wanted ("HEAD", prefixes, n_prefixes)) {
        if (want_symrefs && symref) {
            if (bgit_pkt_writef (1, "%s HEAD symref-target:%s\n", id, symref) < 0)
                { free (symref); return -1; }
        } else if (bgit_pkt_writef (1, "%s HEAD\n", id) < 0) {
            free (symref);
            return -1;
        }
    }
    free (symref);

    bgit_ref *refs = NULL;
    size_t n = 0;
    if (bgit_refs_list (repo, "refs/", &refs, &n) < 0) return -1;
    int status = 0;
    for (size_t i = 0; i < n && !status; i++) {
        if (!git_v2_wanted (refs[i].name, prefixes, n_prefixes)) continue;
        char peeled[41];
        if (want_peeled && git_peel_fully (odb, refs[i].sha, peeled) == 0)
            status = bgit_pkt_writef (1, "%s %s peeled:%s\n", refs[i].sha,
                                      refs[i].name, peeled);
        else
            status = bgit_pkt_writef (1, "%s %s\n", refs[i].sha, refs[i].name);
    }
    bgit_refs_free (refs, n);
    if (status < 0) return -1;
    return bgit_pkt_flush (1);
}

/* What one request asked for. A v2 request names a command, then its
   arguments, and every command reads the ones it knows. */
struct git_v2_request {
    char **prefixes;             /* ls-refs: which refs to list */
    size_t n_prefixes;
    int symrefs, peel;
    char (*ids)[41];             /* fetch: wants first, then haves */
    size_t n_wants, n_haves;
    int done;
    int include_tag;             /* send the tags of what is being sent */
};

static void
git_v2_request_release (struct git_v2_request *request)
{
    for (size_t i = 0; i < request->n_prefixes; i++) free (request->prefixes[i]);
    free (request->prefixes);
    free (request->ids);
    memset (request, 0, sizeof *request);
}

/* Keep one more id. Wants are kept before haves, and a want cannot
   arrive after a have, so both lists grow from the same array. */
static int
git_v2_keep_id (struct git_v2_request *request, const char *id)
{
    size_t n = request->n_wants + request->n_haves;
    char (*grown)[41] = realloc (request->ids, (n + 1) * sizeof *grown);
    if (!grown) return -1;
    request->ids = grown;
    memcpy (request->ids[n], id, 40);
    request->ids[n][40] = '\0';
    return 0;
}

/* Answer one fetch: the objects the client asked for, less everything it
   says it already has, in a pack sent down the first side-band channel. */
static int
git_v2_fetch (bgit_repo *repo, bgit_odb *odb, struct git_v2_request *request)
{
    char (*ids)[41] = request->ids;
    const char **wants = calloc (request->n_wants ? request->n_wants : 1,
                                 sizeof *wants);
    const char **haves = calloc (request->n_haves ? request->n_haves : 1,
                                 sizeof *haves);
    if (!wants || !haves) {
        free (wants);
        free (haves);
        return -1;
    }
    for (size_t i = 0; i < request->n_wants; i++) wants[i] = ids[i];
    for (size_t i = 0; i < request->n_haves; i++)
        haves[i] = ids[request->n_wants + i];

    /* Still negotiating: say which of its haves are here, and that this
       end is ready to send. With nothing in common there is nothing to
       be ready about, and the client asks again with more. */
    int status = 0;
    if (!request->done) {
        size_t common = 0;
        if (bgit_pkt_writef (1, "acknowledgments\n") < 0) status = -1;
        for (size_t i = 0; !status && i < request->n_haves; i++)
            if (bgit_odb_has (odb, haves[i])) {
                common++;
                if (bgit_pkt_writef (1, "ACK %s\n", haves[i]) < 0) status = -1;
            }
        if (!status && !common) {
            if (bgit_pkt_writef (1, "NAK\n") < 0 || bgit_pkt_flush (1) < 0)
                status = -1;
            free (wants);
            free (haves);
            return status;
        }
        if (!status && (bgit_pkt_writef (1, "ready\n") < 0 ||
                        bgit_pkt_delim (1) < 0))
            status = -1;
    }

    char (*send)[41] = NULL;
    size_t n_send = 0;
    if (!status && bgit_reachable_objects (odb, wants, request->n_wants, haves,
                                           request->n_haves, &send, &n_send) < 0)
        status = -1;
    free (wants);
    free (haves);

    /* include-tag: a tag that points at something being sent goes with
       it, which is how a fetch picks up the tags of what it fetched. */
    if (!status && request->include_tag) {
        bgit_ref *tags = NULL;
        size_t n_tags = 0;
        if (bgit_refs_list (repo, "refs/tags/", &tags, &n_tags) == 0) {
            for (size_t i = 0; i < n_tags; i++) {
                char peeled[41];
                if (git_peel_fully (odb, tags[i].sha, peeled) != 0) continue;
                int wanted = 0;
                for (size_t k = 0; k < n_send && !wanted; k++)
                    if (!memcmp (send[k], peeled, 40)) wanted = 1;
                if (!wanted) continue;
                char (*grown)[41] = realloc (send, (n_send + 1) * sizeof *grown);
                if (!grown) break;
                send = grown;
                memcpy (send[n_send], tags[i].sha, 41);
                n_send++;
            }
            bgit_refs_free (tags, n_tags);
        }
    }

    unsigned char *body = NULL;
    size_t body_len = 0;
    struct bgit_pack_idx_entry *entries = NULL;
    unsigned char checksum[20];
    char checksum_hex[41] = "";
    if (!status && git_pack_build (odb, send, n_send, &body, &body_len, &entries,
                                   checksum, checksum_hex) < 0)
        status = -1;
    free (send);
    free (entries);

    if (!status && (bgit_pkt_writef (1, "packfile\n") < 0 ||
                    bgit_pkt_write_band (1, 1, body, body_len) < 0 ||
                    bgit_pkt_flush (1) < 0))
        status = -1;
    free (body);
    return status;
}

/* git upload-pack: the far end of a fetch, over protocol v2. git has
   asked for v2 by default since 2.26, and it is all this build speaks, so
   a caller that does not ask for it is told rather than answered wrongly. */
static int
git_cmd_upload_pack (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git upload-pack [--stateless-rpc] [--advertise-refs] "
                        "<directory>";
    const char *dir = NULL;
    int stateless = 0, advertise_only = 0;
    (void) ctx;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--stateless-rpc")) stateless = 1;
        else if (!strcmp (w, "--advertise-refs")) advertise_only = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!dir) dir = w;
        else return git_usage (usage);
    }
    if (!dir) return git_usage (usage);

    const char *protocol = getenv ("GIT_PROTOCOL");
    if (!protocol || !strstr (protocol, "version=2"))
        return git_fatal ("this build's git upload-pack speaks protocol "
                          "version 2 only");

    bgit_repo repo;
    bgit_odb odb;
    if (git_open_remote (dir, &repo, &odb) < 0)
        return git_fatal ("'%s' does not appear to be a git repository", dir);

    int status = 0;
    if ((!stateless || advertise_only) && git_v2_advertise () < 0)
        status = GIT_EXIT_FATAL;
    if (!advertise_only && !status) {
        bgit_pkt_reader reader;
        bgit_pkt_from_fd (&reader, 0);
        /* A request is the command, then the client's own capabilities, a
           divider, the arguments, and a flush. A flush where the command
           would be ends the conversation. */
        for (;;) {
            char *line = NULL;
            int got = bgit_pkt_read_line (&reader, &line);
            if (got == BGIT_PKT_FLUSH || got == BGIT_PKT_EOF) break;
            if (got < 0) {
                status = git_fatal ("the request is not a pkt-line stream");
                break;
            }
            char command[64] = "";
            if (!strncmp (line, "command=", 8))
                snprintf (command, sizeof command, "%s", line + 8);
            free (line);

            struct git_v2_request request;
            memset (&request, 0, sizeof request);
            int bad = 0;
            for (;;) {
                got = bgit_pkt_read_line (&reader, &line);
                if (got == BGIT_PKT_FLUSH || got == BGIT_PKT_EOF) break;
                if (got == BGIT_PKT_DELIM) continue;
                if (got < 0) { bad = 1; break; }
                if (!strcmp (line, "include-tag")) request.include_tag = 1;
                else if (!strcmp (line, "symrefs")) request.symrefs = 1;
                else if (!strcmp (line, "peel")) request.peel = 1;
                else if (!strcmp (line, "done")) request.done = 1;
                else if (!strncmp (line, "ref-prefix ", 11)) {
                    char **grown = realloc (request.prefixes,
                                            (request.n_prefixes + 1) * sizeof *grown);
                    if (grown) {
                        request.prefixes = grown;
                        grown[request.n_prefixes] = strdup (line + 11);
                        if (grown[request.n_prefixes]) request.n_prefixes++;
                    }
                }
                else if (!strncmp (line, "want ", 5) && strlen (line + 5) >= 40) {
                    if (git_v2_keep_id (&request, line + 5) < 0) bad = 1;
                    else request.n_wants++;
                }
                else if (!strncmp (line, "have ", 5) && strlen (line + 5) >= 40) {
                    if (git_v2_keep_id (&request, line + 5) < 0) bad = 1;
                    else request.n_haves++;
                }
                free (line);
                line = NULL;
                if (bad) break;
            }
            free (line);
            if (!bad && !strcmp (command, "ls-refs"))
                bad = git_v2_ls_refs (&repo, &odb, request.prefixes,
                                      request.n_prefixes, request.symrefs,
                                      request.peel) < 0;
            else if (!bad && !strcmp (command, "fetch"))
                bad = git_v2_fetch (&repo, &odb, &request) < 0;
            else if (!bad)
                status = git_fatal ("this build's git upload-pack does not "
                                    "have the '%s' command", command);
            git_v2_request_release (&request);
            if (bad && !status) status = GIT_EXIT_FATAL;
            if (status) break;
            if (got == BGIT_PKT_EOF) break;
        }
    }
    bgit_odb_release (&odb);
    bgit_repo_release (&repo);
    return status;
}



/* The scheme and host part of a URL, which is what a stored credential
   is matched on. */
static void
git_url_host (const char *url, char *out, size_t outsz)
{
    const char *after = strstr (url, "://");
    after = after ? after + 3 : url;
    const char *at = strchr (after, '@');
    const char *host = at ? at + 1 : after;
    size_t scheme = (size_t) (after - url);
    size_t len = strcspn (host, "/");
    if (scheme + len >= outsz) len = outsz - scheme - 1;
    memcpy (out, url, scheme);
    memcpy (out + scheme, host, len);
    out[scheme + len] = '\0';
}

/* A name and secret for URL, out of the file `credential.helper store`
   keeps them in: a URL to a line, name and secret inside it. Returns 1
   when one was found, and leaves it in OUT. */
static int
git_http_credentials (git_context *ctx, const char *url, char *out, size_t outsz)
{
    const char *helper = bgit_config_get (&ctx->cfg, "credential.helper");
    if (!helper || strncmp (helper, "store", 5)) return 0;
    char path[4096] = "";
    const char *named = strstr (helper, "--file=");
    if (named) snprintf (path, sizeof path, "%s", named + 7);
    else {
        const char *home = getenv ("HOME");
        if (!home) return 0;
        snprintf (path, sizeof path, "%s/.git-credentials", home);
    }
    unsigned char *content = NULL;
    size_t len = 0;
    if (bgit_slurp_file (path, &content, &len) < 0) return 0;

    char want[1024];
    git_url_host (url, want, sizeof want);
    int found = 0;
    char *line = (char *) content;
    char *end = (char *) content + len;
    while (!found && line < end) {
        char *stop = memchr (line, '\n', (size_t) (end - line));
        size_t line_len = stop ? (size_t) (stop - line) : (size_t) (end - line);
        char entry[2048];
        if (line_len && line_len < sizeof entry) {
            memcpy (entry, line, line_len);
            entry[line_len] = '\0';
            /* "<scheme>://<name>:<secret>@<host>" */
            char *at = strrchr (entry, '@');
            const char *after = strstr (entry, "://");
            if (at && after) {
                char host[1024];
                git_url_host (entry, host, sizeof host);
                *at = '\0';
                if (!strcmp (host, want) &&
                    snprintf (out, outsz, "%s", after + 3) < (int) outsz)
                    found = 1;
            }
        }
        line = stop ? stop + 1 : end;
    }
    free (content);
    return found;
}

/* Ask the far end for something over HTTP, with curl doing the talking:
   the builtin when this build has it, and the command otherwise, which
   is how pkg fetches. The answer, and the three digits of status curl
   is asked to add after it, come back through a pipe. */
static int
git_http_ask (git_conn *conn, const char *method, const char *url,
              const char *content_type, const unsigned char *body,
              size_t body_len)
{
    int into[2], back[2];
    if (pipe (into) < 0) return -1;
    if (pipe (back) < 0) {
        close (into[0]);
        close (into[1]);
        return -1;
    }
    char type_header[256] = "", protocol_header[64];
    snprintf (protocol_header, sizeof protocol_header, "Git-Protocol: version=2");
    if (content_type)
        snprintf (type_header, sizeof type_header, "Content-Type: %s",
                  content_type);

    pid_t child = fork ();
    if (child < 0) {
        close (into[0]); close (into[1]);
        close (back[0]); close (back[1]);
        return -1;
    }
    if (!child) {
        git_restore_caller_pipe ();
        close (into[1]);
        close (back[0]);
        if (dup2 (into[0], 0) < 0 || dup2 (back[1], 1) < 0) _exit (127);
        close (into[0]);
        close (back[1]);
        char *argv[64];
        int argc = 0;
        argv[argc++] = "curl";
        argv[argc++] = "-sS";
        argv[argc++] = "-w";
        argv[argc++] = "%{http_code}";
        argv[argc++] = "-H";
        argv[argc++] = protocol_header;
        if (*type_header) {
            argv[argc++] = "-H";
            argv[argc++] = type_header;
        }
        for (size_t i = 0; i < conn->n_headers &&
                           argc + 8 < (int) (sizeof argv / sizeof *argv); i++) {
            argv[argc++] = "-H";
            argv[argc++] = (char *) conn->headers[i];
        }
        /* git follows a redirect on the first request and no other, which
           is what http.followRedirects means by "initial". */
        if (conn->follow) argv[argc++] = "-L";
        if (*conn->secret) {
            argv[argc++] = "-u";
            argv[argc++] = conn->secret;
        }
        if (body) {
            argv[argc++] = "--data-binary";
            argv[argc++] = "@-";
        }
        argv[argc++] = "-X";
        argv[argc++] = (char *) method;
        argv[argc++] = (char *) url;
        argv[argc] = NULL;
        bos_prepare_child ();
        bos_run_builtin ("curl", argv, NULL);
        /* A secret must not reach the command line of another program;
           with the builtin it stays in this process's own memory. */
        if (*conn->secret) _exit (127);
        execvp ("curl", argv);
        _exit (127);
    }
    close (into[0]);
    close (back[1]);
    if (body && body_len) {
        /* curl reads the whole body before it answers, so writing it all
           and then reading cannot deadlock. */
        size_t at = 0;
        while (at < body_len) {
            ssize_t put = write (into[1], body + at, body_len - at);
            if (put < 0) {
                if (errno == EINTR) continue;
                break;
            }
            at += (size_t) put;
        }
    }
    close (into[1]);

    unsigned char *answer = NULL;
    size_t len = 0, cap = 0;
    if (bgit_slurp_fd (back[0], &answer, &len) < 0) {
        close (back[0]);
        waitpid (child, NULL, 0);
        return -1;
    }
    (void) cap;
    close (back[0]);
    int wait_status = 0;
    waitpid (child, &wait_status, 0);
    if (!WIFEXITED (wait_status) || WEXITSTATUS (wait_status)) {
        free (answer);
        git_fatal ("unable to access '%s'", conn->url);
        return -1;
    }
    /* The last three bytes are the status curl was asked to add. */
    if (len < 3) {
        free (answer);
        git_fatal ("unable to access '%s': nothing came back", conn->url);
        return -1;
    }
    int status = (answer[len - 3] - '0') * 100 + (answer[len - 2] - '0') * 10 +
                 (answer[len - 1] - '0');
    len -= 3;
    if (status == 401) {
        free (answer);
        return 401;
    }
    if (status != 200) {
        free (answer);
        git_fatal ("unable to access '%s': the far end said %d", conn->url,
                   status);
        return -1;
    }
    free (conn->response);
    conn->response = answer;
    conn->response_len = len;
    bgit_pkt_from_memory (&conn->reader, conn->response, conn->response_len);
    conn->io.reader = &conn->reader;
    return 0;
}

/* Ask, and if the far end wants a name and secret, find one and ask
   again. The first ask carries none, which is what a far end that wants
   none expects. */
static int
git_http_request (git_conn *conn, const char *method, const char *url,
                  const char *content_type, const unsigned char *body,
                  size_t body_len)
{
    int rc = git_http_ask (conn, method, url, content_type, body, body_len);
    if (rc != 401) return rc;
    if (!*conn->secret && conn->ctx &&
        git_http_credentials (conn->ctx, conn->url, conn->secret,
                              sizeof conn->secret))
        rc = git_http_ask (conn, method, url, content_type, body, body_len);
    if (rc != 401) return rc;
    if (*conn->secret)
        git_fatal ("Authentication failed for '%s'", conn->url);
    else
        git_fatal ("could not read Username for '%s': terminal prompts "
                   "disabled", conn->url);
    return -1;
}

static int
git_http_write (bgit_proto_io *io, const void *data, size_t len)
{
    git_conn *conn = io->context;
    return bgit_pack_buf_append (&conn->request, &conn->request_len,
                                 &conn->request_cap, data, len);
}

static int
git_http_done (bgit_proto_io *io)
{
    git_conn *conn = io->context;
    char url[4200], type[128];
    snprintf (url, sizeof url, "%s/%s", conn->url, conn->service);
    snprintf (type, sizeof type, "application/x-%s-request", conn->service);
    int rc = git_http_request (conn, "POST", url, type, conn->request,
                               conn->request_len);
    conn->request_len = 0;
    return rc < 0 ? -1 : 0;
}

/* What git says when the far end stops without answering. Whatever it
   said for itself has already gone to the same place. */
static int
git_far_end_gone (void)
{
    fflush (stdout);
    fputs ("fatal: Could not read from remote repository.\n\n"
           "Please make sure you have the correct access rights\n"
           "and the repository exists.\n", stderr);
    return GIT_EXIT_FATAL;
}

/* The environment the far end gets: this one, without the variables that
   name this repository's files, plus the protocol to speak. Returns the
   array, or this process's own environment if there is no room for it. */
static char **
git_far_environ (void)
{
    /* Built from the shell's own table, which is where an assignment
       standing before this command is until something outside the shell
       is run. */
    array_needs_making = 1;
    maybe_make_export_env ();
    char **environ = export_env;
    static const char *const leave_behind[] = {
        "GIT_PROTOCOL=", "GIT_DIR=", "GIT_WORK_TREE=", "GIT_INDEX_FILE=",
        "GIT_OBJECT_DIRECTORY=", "GIT_ALTERNATE_OBJECT_DIRECTORIES=", NULL
    };
    size_t n = 0;
    while (environ[n]) n++;
    char **env = malloc ((n + 2) * sizeof *env);
    if (!env) return environ;
    size_t at = 0;
    for (size_t i = 0; i < n; i++) {
        int drop = 0;
        for (int k = 0; leave_behind[k] && !drop; k++)
            if (!strncmp (environ[i], leave_behind[k], strlen (leave_behind[k])))
                drop = 1;
        if (!drop) env[at++] = environ[i];
    }
    env[at++] = (char *) "GIT_PROTOCOL=version=2";
    env[at] = NULL;
    return env;
}

/* Start the far end and hold both ends of the conversation: what is
   written to *TO_FAR arrives on its input, and what it answers is read
   from *FROM_FAR. PROGRAM is what to run, or NULL for this build's own
   COMMAND, which is how git runs its own for a path. */
static pid_t
git_start_argv (const char *script, const char *const *args, int n_args,
                int *to_far, int *from_far)
{
    int down[2], up[2];
    if (pipe (down) < 0) return -1;
    if (pipe (up) < 0) {
        close (down[0]);
        close (down[1]);
        return -1;
    }
    pid_t child = fork ();
    if (child < 0) {
        close (down[0]); close (down[1]);
        close (up[0]); close (up[1]);
        return -1;
    }
    if (!child) {
        git_restore_caller_pipe ();
        close (down[1]);
        close (up[0]);
        if (dup2 (down[0], 0) < 0 || dup2 (up[1], 1) < 0) _exit (127);
        close (down[0]);
        close (up[1]);
        /* The far end must be told which protocol to speak, and must not
           inherit what points this end at its own files. The shell keeps
           its own table of variables, so the environment is handed over
           whole rather than changed here. */
        char **env = git_far_environ ();
        /* The shell running it is the one we are inside: a bash-os machine
           need not have another. */
        const char *argv[16];
        int at = 0;
        argv[at++] = "bash";
        argv[at++] = "--noprofile";
        argv[at++] = "--norc";
        argv[at++] = "-c";
        argv[at++] = script;
        argv[at++] = "git-far-end";
        for (int i = 0; i < n_args && at < 15; i++) argv[at++] = args[i];
        argv[at] = NULL;
        execve ("/proc/self/exe", (char *const *) argv, env);
        _exit (127);
    }
    close (down[0]);
    close (up[1]);
    *to_far = down[1];
    *from_far = up[0];
    return child;
}

/* The far end this build runs itself, for a repository on this machine. */
static pid_t
git_start_far_end (const char *program, const char *command, const char *path,
                   int *to_far, int *from_far)
{
    char script[4096];
    snprintf (script, sizeof script, "%s \"$@\"", program ? program : command);
    const char *args[1] = { path };
    return git_start_argv (script, args, 1, to_far, from_far);
}

/* ---- the far end on another machine ------------------------------------ */

/* What ssh is told to reach, taken out of the URL. */
struct git_ssh_far {
    char host[512];        /* [user@]host, as ssh takes it */
    char port[16];
    char path[4096];       /* the repository over there */
};

/* Read ssh://[user@]host[:port]/path, or [user@]host:path. Returns 0. */
static int
git_ssh_parse (const char *url, struct git_ssh_far *far)
{
    memset (far, 0, sizeof *far);
    const char *at = url, *path = NULL;
    if (!strncmp (url, "ssh://", 6)) {
        at = url + 6;
        path = strchr (at, '/');
        size_t host_len = path ? (size_t) (path - at) : strlen (at);
        if (host_len >= sizeof far->host) return -1;
        memcpy (far->host, at, host_len);
        far->host[host_len] = '\0';
        /* A port stands after the last colon, outside any brackets. */
        char *close = strchr (far->host, ']');
        char *colon = strrchr (close ? close : far->host, ':');
        if (colon) {
            snprintf (far->port, sizeof far->port, "%s", colon + 1);
            *colon = '\0';
        }
        /* ssh://host/~/repo means the path is under the home directory,
           which is what the far end makes of a leading tilde. */
        const char *where = path ? path : "/";
        if (where[0] == '/' && where[1] == '~') where++;
        snprintf (far->path, sizeof far->path, "%s", where);
    } else {
        const char *colon = *url == '[' ? strstr (url, "]:") + 1
                                        : strchr (url, ':');
        if (!colon) return -1;
        size_t host_len = (size_t) (colon - url);
        if (host_len >= sizeof far->host) return -1;
        memcpy (far->host, url, host_len);
        far->host[host_len] = '\0';
        snprintf (far->path, sizeof far->path, "%s", colon + 1);
    }
    /* Brackets are the URL's way of holding an address together; ssh takes
       the address itself. */
    if (far->host[0] == '[') {
        char *close = strchr (far->host, ']');
        if (close) {
            *close = '\0';
            memmove (far->host, far->host + 1, strlen (far->host + 1) + 1);
        }
    }
    return far->host[0] ? 0 : -1;
}

/* A word for the far end's shell, quoted the way git quotes one. */
static int
git_sq_quote (const char *word, char *out, size_t outsz)
{
    size_t at = 0;
    if (at + 1 >= outsz) return -1;
    out[at++] = '\'';
    for (const char *p = word; *p; p++) {
        if (*p == '\'') {
            if (at + 4 >= outsz) return -1;
            memcpy (out + at, "'\\''", 4);
            at += 4;
        } else {
            if (at + 1 >= outsz) return -1;
            out[at++] = *p;
        }
    }
    if (at + 2 > outsz) return -1;
    out[at++] = '\'';
    out[at] = '\0';
    return 0;
}

/* What runs ssh: what the environment names, then what the configuration
   names, which is the order git asks in. With neither, NULL — and then
   this build's own ssh runs it, which wants no PATH and no other program
   on the machine. */
static const char *
git_ssh_command (git_context *ctx)
{
    const char *named = getenv ("GIT_SSH_COMMAND");
    if (named && *named) return named;
    named = bgit_config_get (&ctx->cfg, "core.sshCommand");
    if (named && *named) return named;
    return NULL;
}

/* git tells one ssh from another by what it is called: the one called ssh
   takes -p for a port and can be asked to carry GIT_PROTOCOL along, and
   anything else is handed the host and the command and nothing besides. */
static int
git_ssh_is_openssh (const char *command)
{
    size_t len = strcspn (command, " \t");
    const char *word = command, *end = command + len;
    for (const char *p = end; p > word; p--)
        if (p[-1] == '/') { word = p; break; }
    size_t name = (size_t) (end - word);
    return name == 3 && !strncmp (word, "ssh", 3);
}

/* Open a conversation with the far end named by URL, and leave it where
   its advertisement starts. SERVICE is the half being asked for, which
   over HTTP is part of the address and over a pipe is the command to
   run. Returns 0, or -1 with git's message said. */
static int
git_conn_open (git_conn *conn, git_context *ctx, const char *url,
               const char *program, const char *service)
{
    memset (conn, 0, sizeof *conn);
    conn->to_far = conn->from_far = -1;
    conn->service = service;
    conn->ctx = ctx;
    /* A far end that stops leaves a pipe with no reader; the write that
       finds out must not take the shell's child with it. The programs
       this process execs restore the disposition from before this ignore. */
    git_ignore_pipe ();

    if (git_url_is_http (url)) {
        conn->over_http = 1;
        snprintf (conn->url, sizeof conn->url, "%s", url);
        size_t len = strlen (conn->url);
        while (len && conn->url[len - 1] == '/') conn->url[--len] = '\0';
        conn->io.context = conn;
        conn->io.write = git_http_write;
        conn->io.done = git_http_done;
        conn->io.reader = &conn->reader;
        /* Whatever the configuration wants said with every request. */
        conn->n_headers = bgit_config_get_all (&ctx->cfg, "http.extraHeader",
                                               &conn->headers);
        char ask[4300];
        snprintf (ask, sizeof ask, "%s/info/refs?service=%s", conn->url, service);
        conn->follow = 1;
        int rc = git_http_request (conn, "GET", ask, NULL, NULL, 0);
        conn->follow = 0;
        return rc < 0 ? -1 : 0;
    }

    if (git_url_is_ssh (url)) {
        struct git_ssh_far far;
        if (git_ssh_parse (url, &far) < 0) {
            git_fatal ("bad ssh address '%s'", url);
            return -1;
        }
        const char *ssh = git_ssh_command (ctx);
        int openssh = ssh && git_ssh_is_openssh (ssh);
        /* What the far end's shell is asked to run, quoted for it. */
        char quoted[4200], far_command[4400];
        if (git_sq_quote (far.path, quoted, sizeof quoted) < 0) {
            git_fatal ("the path is too long for the far end");
            return -1;
        }
        snprintf (far_command, sizeof far_command, "%s %s",
                  program ? program : service, quoted);
        const char *args[8];
        int n_args = 0;
        if (!ssh) {
            /* This build's own ssh: it takes the environment to carry as an
               option rather than by name, since it sends what it is given
               rather than what the machine happens to have. */
            args[n_args++] = "--setenv";
            args[n_args++] = "GIT_PROTOCOL=version=2";
        } else if (openssh) {
            args[n_args++] = "-o";
            args[n_args++] = "SendEnv=GIT_PROTOCOL";
        }
        if (far.port[0]) {
            if (ssh && !openssh) {
                git_fatal ("ssh variant 'simple' does not support setting "
                           "port");
                return -1;
            }
            args[n_args++] = "-p";
            args[n_args++] = far.port;
        }
        args[n_args++] = far.host;
        args[n_args++] = far_command;
        char script[4096];
        snprintf (script, sizeof script, "%s \"$@\"",
                  ssh ? ssh : "builtin ssh run");
        conn->child = git_start_argv (script, args, n_args, &conn->to_far,
                                      &conn->from_far);
        if (conn->child < 0) {
            git_fatal ("cannot start the far end: %s", strerror (errno));
            return -1;
        }
        bgit_pkt_from_fd (&conn->reader, conn->from_far);
        bgit_proto_io_fd (&conn->io, &conn->reader, conn->to_far);
        return 0;
    }

    char command[64];
    snprintf (command, sizeof command, "builtin git %s", service + 4);
    conn->child = git_start_far_end (program, command, url, &conn->to_far,
                                     &conn->from_far);
    if (conn->child < 0) {
        git_fatal ("cannot start the far end: %s", strerror (errno));
        return -1;
    }
    bgit_pkt_from_fd (&conn->reader, conn->from_far);
    bgit_proto_io_fd (&conn->io, &conn->reader, conn->to_far);
    return 0;
}

/* End the conversation, and say whether the far end was content.
   Returns 0, or -1. */
static int
git_conn_close (git_conn *conn)
{
    int rc = 0;
    if (conn->over_http) {
        free (conn->request);
        free (conn->response);
        conn->request = conn->response = NULL;
        return 0;
    }
    bgit_pkt_flush (conn->to_far);
    bgit_pkt_release (&conn->reader);
    if (conn->to_far >= 0) close (conn->to_far);
    if (conn->from_far >= 0) close (conn->from_far);
    int wait_status = 0;
    if (conn->child > 0) {
        waitpid (conn->child, &wait_status, 0);
        rc = WIFEXITED (wait_status) && !WEXITSTATUS (wait_status) ? 0 : -1;
    }
    return rc;
}

/* Open a conversation with the half of the far end that sends objects,
   and check it can do what is about to be asked of it. */
static int
git_far_end_open (git_conn *conn, git_context *ctx, const char *url,
                  const char *program, int want_fetch)
{
    if (git_conn_open (conn, ctx, url, program, "git-upload-pack") < 0)
        return -1;
    bgit_proto_caps caps;
    if (bgit_proto_read_caps (conn->io.reader, &caps) < 0) {
        git_far_end_gone ();
        git_conn_close (conn);
        return -1;
    }
    int can = bgit_proto_cap (&caps, "ls-refs") != NULL &&
              (!want_fetch || bgit_proto_cap (&caps, "fetch") != NULL);
    bgit_proto_caps_release (&caps);
    if (!can) {
        git_fatal ("the far end cannot %s", want_fetch ? "send objects"
                                                       : "list refs");
        git_conn_close (conn);
        return -1;
    }
    return 0;
}

/* Keep what a fetch brought back. git explodes a small pack into loose
   objects and keeps a large one as a pack beside a generated index; the
   line between the two is fetch.unpackLimit, a hundred objects. */
static int
git_store_pack_into (bgit_repo *repo, bgit_odb *odb, unsigned char *pack,
                     size_t len)
{
    if (len < 32) return 0;                    /* nothing came back */
    struct git_pack_entry *entries = NULL;
    size_t n = 0;
    int thin = 0;
    if (git_pack_scan (pack, len, &entries, &n) < 0 ||
        git_pack_resolve (pack, len, entries, n, odb, &thin) < 0) {
        free (entries);
        return -1;
    }
    /* A thin pack is not a pack this repository could keep: what its
       deltas lean on is outside it. Written out object by object, every
       one of them is whole. */
    int status = 0;
    if (n < 100 || thin) {
        for (size_t i = 0; !status && i < n; i++) {
            int type = 0;
            unsigned char *content = NULL;
            size_t content_len = 0;
            if (git_pack_content (pack, len, entries, n, entries[i].offset,
                                  &type, &content, &content_len, 0, odb,
                                  NULL) < 0) {
                status = -1;
                break;
            }
            char hex[41];
            if (bgit_write_object (odb->object_dirs[0],
                                   bgit_pack_type_name (type), content,
                                   content_len, 1, hex) < 0)
                status = -1;
            free (content);
        }
        free (entries);
        return status;
    }

    /* Big enough to keep whole: write it where git keeps packs, with the
       index that makes it readable, and let the store see it. */
    struct bgit_pack_idx_entry *idx_entries = calloc (n, sizeof *idx_entries);
    if (!idx_entries) {
        free (entries);
        return -1;
    }
    for (size_t i = 0; i < n; i++) {
        memcpy (idx_entries[i].sha, entries[i].sha, 20);
        idx_entries[i].crc = entries[i].crc;
        idx_entries[i].off = entries[i].offset;
    }
    char hex[41];
    bgit_sha_to_hex (pack + len - 20, hex);
    char dir[4096], pack_path[4096], idx_path[4096];
    snprintf (dir, sizeof dir, "%s/pack", odb->object_dirs[0]);
    mkdir (dir, 0777);
    snprintf (pack_path, sizeof pack_path, "%s/pack-%s.pack", dir, hex);
    snprintf (idx_path, sizeof idx_path, "%s/pack-%s.idx", dir, hex);
    FILE *out = fopen (pack_path, "w");
    if (!out || fwrite (pack, 1, len, out) != len || fclose (out) != 0)
        status = -1;
    if (!status &&
        bgit_pack_write_idx_v2 (idx_path, idx_entries, n, pack + len - 20) < 0)
        status = -1;
    free (idx_entries);
    free (entries);
    /* The store listed the packs when it opened; this is a new one. */
    if (!status) {
        bgit_odb_release (odb);
        if (bgit_odb_open (repo, odb) < 0) return -1;
        odb->quiet = 1;
    }
    return status;
}

static int
git_store_pack (git_context *ctx, unsigned char *pack, size_t len)
{
    return git_store_pack_into (&ctx->repo, &ctx->odb, pack, len);
}

/* The ids of every ref here, which is what the far end is told this end
   already has. */
static int
git_local_haves (git_context *ctx, char (**out)[41], size_t *n_out)
{
    bgit_ref *refs = NULL;
    size_t n = 0;
    if (bgit_refs_list (&ctx->repo, "refs/", &refs, &n) < 0) return -1;
    char (*ids)[41] = calloc (n ? n : 1, sizeof *ids);
    if (!ids) {
        bgit_refs_free (refs, n);
        return -1;
    }
    size_t kept = 0;
    for (size_t i = 0; i < n; i++)
        if (bgit_odb_has (&ctx->odb, refs[i].sha)) {
            memcpy (ids[kept], refs[i].sha, 41);
            kept++;
        }
    bgit_refs_free (refs, n);
    *out = ids;
    *n_out = kept;
    return 0;
}

/* One change a push asks for. */
struct git_push_command {
    char old_id[41], new_id[41];
    char name[4096];
    const char *refused;         /* git's reason, when it is */
};

/* An id of nothing at all: what a push puts where a ref is being made or
   unmade. */
#define GIT_NULL_ID "0000000000000000000000000000000000000000"

/* The first line of a push carries the client's capabilities after a NUL;
   the rest are plain. */
static int
git_push_wants (const unsigned char *line, size_t len, const char *name)
{
    const unsigned char *nul = memchr (line, '\0', len);
    if (!nul) return 0;
    const char *caps = (const char *) nul + 1;
    size_t caps_len = len - (size_t) ((const unsigned char *) caps - line);
    size_t want = strlen (name);
    for (size_t i = 0; i + want <= caps_len; i++)
        if (!memcmp (caps + i, name, want) &&
            (i == 0 || caps[i - 1] == ' ') &&
            (i + want == caps_len || caps[i + want] == ' ' ||
             caps[i + want] == '=' || caps[i + want] == '\n'))
            return 1;
    return 0;
}

/* Put one pkt-line into a buffer, which is how a report is built: the
   report itself is packets, inside the side-band packet that carries it. */
static size_t
git_pkt_into (unsigned char *buf, size_t at, size_t room, const char *text)
{
    size_t len = strlen (text);
    if (at + len + 4 >= room) return at;
    char header[5];
    snprintf (header, sizeof header, "%04x", (unsigned) (len + 4));
    memcpy (buf + at, header, 4);
    memcpy (buf + at + 4, text, len);
    return at + len + 4;
}

/* One thing a push asks the far end to do. */
struct git_push_want {
    char src[4096];          /* the ref here, once it was worked out */
    char dst[4096];          /* the ref over there */
    char id[41];             /* what it is to become; zeros to unmake it */
    char old[41];            /* what the far end says it is now */
    int forced;              /* the refspec said +, or --force did */
    int is_new;
    int forced_update;       /* it was not a fast-forward */
    int remote_refused;      /* the far end said no, rather than this end */
    int sent;
    const char *refused;
};

/* A ref by the name a person would use for it. */
static const char *
git_ref_short (const char *ref)
{
    if (!strncmp (ref, "refs/heads/", 11)) return ref + 11;
    if (!strncmp (ref, "refs/tags/", 10)) return ref + 10;
    if (!strncmp (ref, "refs/remotes/", 13)) return ref + 13;
    return ref;
}

/* The full name of a ref this repository has, for a name as it was
   given: a branch, a tag, or a name that is already full. Returns 1 when
   one was found. */
static int
git_push_source (git_context *ctx, const char *name, char *out, size_t outsz,
                 char id[41])
{
    const char *shapes[] = { "%s", "refs/heads/%s", "refs/tags/%s", NULL };
    for (int i = 0; shapes[i]; i++) {
        char full[4096];
        snprintf (full, sizeof full, shapes[i], name);
        if (strncmp (full, "refs/", 5)) continue;
        if (bgit_ref_read (&ctx->repo, full, id) == 0) {
            snprintf (out, outsz, "%s", full);
            return 1;
        }
    }
    /* Not a ref: a revision may still name something to push. */
    if (git_resolve (ctx, name, id, NULL) == 0) {
        snprintf (out, outsz, "%s", name);
        return 1;
    }
    return 0;
}

static int
git_push_want (git_context *ctx, struct git_push_want **wants, size_t *n,
               size_t *cap, const char *spec, int force, int deleting)
{
    if (*n == *cap) {
        size_t next = *cap ? *cap * 2 : 8;
        struct git_push_want *grown = realloc (*wants, next * sizeof *grown);
        if (!grown) return -1;
        *wants = grown;
        *cap = next;
    }
    struct git_push_want *want = &(*wants)[*n];
    memset (want, 0, sizeof *want);
    want->forced = force;
    if (*spec == '+') {
        want->forced = 1;
        spec++;
    }
    const char *colon = strchr (spec, ':');
    char source[4096] = "", target[4096] = "";
    if (deleting) snprintf (target, sizeof target, "%s", spec);
    else if (!colon) snprintf (source, sizeof source, "%s", spec);
    else {
        snprintf (source, sizeof source, "%.*s", (int) (colon - spec), spec);
        snprintf (target, sizeof target, "%s", colon + 1);
    }

    if (!*source) {
        /* Nothing on the near side: the ref over there is to be unmade. */
        memcpy (want->id, GIT_NULL_ID, 41);
        if (!*target) return git_fatal ("this build's git push needs a ref to "
                                        "delete") < 0 ? -1 : -1;
        snprintf (want->src, sizeof want->src, "%s", target);
    } else if (!git_push_source (ctx, source, want->src, sizeof want->src,
                                 want->id)) {
        git_fatal ("src refspec %s does not match any", source);
        return -1;
    }
    if (!*target) snprintf (target, sizeof target, "%s", want->src);
    if (!strncmp (target, "refs/", 5))
        snprintf (want->dst, sizeof want->dst, "%s", target);
    else
        snprintf (want->dst, sizeof want->dst, "refs/%s/%s",
                  !strncmp (want->src, "refs/tags/", 10) ? "tags" : "heads",
                  target);
    (*n)++;
    return 0;
}

/* git receive-pack: the far end of a push. This is git's first protocol,
   and the one it still uses for a push: the refs this repository has,
   then the changes the other end wants, then a pack, then what became of
   each change. */
static int
git_cmd_receive_pack (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git receive-pack <directory>";
    const char *dir = NULL;
    (void) ctx;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--stateless-rpc")) ;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!dir) dir = w;
        else return git_usage (usage);
    }
    if (!dir) return git_usage (usage);

    bgit_repo repo;
    bgit_odb odb;
    if (git_open_remote (dir, &repo, &odb) < 0)
        return git_fatal ("'%s' does not appear to be a git repository", dir);

    /* What this repository has, and what it can do. The capabilities ride
       on the first ref after a NUL; a repository with no refs at all says
       so under a name no ref could have. */
    static const char capabilities[] =
        "report-status delete-refs side-band-64k ofs-delta "
        "object-format=sha1 agent=" GIT_AGENT_STRING;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    int status = 0;
    if (bgit_refs_list (&repo, "refs/", &refs, &n_refs) < 0)
        status = GIT_EXIT_FATAL;
    for (size_t i = 0; !status && i < n_refs + (n_refs ? 0 : 1); i++) {
        char line[8192];
        size_t len = (size_t) snprintf (line, sizeof line, "%s %s",
                                        n_refs ? refs[i].sha : GIT_NULL_ID,
                                        n_refs ? refs[i].name : "capabilities^{}");
        if (!i) {
            line[len++] = '\0';
            memcpy (line + len, capabilities, sizeof capabilities - 1);
            len += sizeof capabilities - 1;
        }
        line[len++] = '\n';
        if (bgit_pkt_write (1, line, len) < 0) status = GIT_EXIT_FATAL;
    }
    if (!status && bgit_pkt_flush (1) < 0) status = GIT_EXIT_FATAL;
    bgit_refs_free (refs, n_refs);

    /* What the other end wants changed: "<old> <new> <ref>" each. */
    bgit_pkt_reader reader;
    bgit_pkt_from_fd (&reader, 0);
    struct git_push_command *commands = NULL;
    size_t n_commands = 0, cap = 0;
    int side_band = 0, wants_report = 0, sending_objects = 0;
    while (!status) {
        const unsigned char *data = NULL;
        int got = bgit_pkt_read (&reader, &data);
        if (got == BGIT_PKT_FLUSH || got == BGIT_PKT_EOF) break;
        if (got < 0) { status = GIT_EXIT_FATAL; break; }
        if (!n_commands) {
            side_band = git_push_wants (data, (size_t) got, "side-band-64k");
            wants_report = git_push_wants (data, (size_t) got, "report-status") ||
                           git_push_wants (data, (size_t) got, "report-status-v2");
        }
        if (got < 82 || data[40] != ' ' || data[81] != ' ') continue;
        if (n_commands == cap) {
            size_t next = cap ? cap * 2 : 8;
            struct git_push_command *grown = realloc (commands,
                                                      next * sizeof *grown);
            if (!grown) { status = GIT_EXIT_FATAL; break; }
            commands = grown;
            cap = next;
        }
        struct git_push_command *command = &commands[n_commands];
        memset (command, 0, sizeof *command);
        memcpy (command->old_id, data, 40);
        memcpy (command->new_id, data + 41, 40);
        const unsigned char *end = memchr (data, '\0', (size_t) got);
        size_t name_len = (end ? (size_t) (end - data) : (size_t) got) - 82;
        while (name_len && (data[82 + name_len - 1] == '\n' ||
                            data[82 + name_len - 1] == '\r'))
            name_len--;
        if (name_len >= sizeof command->name) name_len = sizeof command->name - 1;
        memcpy (command->name, data + 82, name_len);
        if (strcmp (command->new_id, GIT_NULL_ID)) sending_objects = 1;
        n_commands++;
    }

    /* Then the pack, which comes only when something is being added. */
    if (!status && n_commands && sending_objects) {
        unsigned char *pack = NULL;
        size_t pack_len = 0;
        /* The packets were read in chunks, so the front of the pack is
           already in hand rather than still on the descriptor. */
        const unsigned char *pending = NULL;
        size_t pending_len = 0;
        bgit_pkt_pending (&reader, &pending, &pending_len);
        if (bgit_pack_read_stream (0, pending, pending_len, &pack, &pack_len) < 0 ||
            git_store_pack_into (&repo, &odb, pack, pack_len) < 0)
            status = GIT_EXIT_FATAL;
        free (pack);
    }

    /* What each change may do. A branch this repository has checked out
       is refused, and so is one that would lose commits. What the far end
       should be told beyond the refusal itself goes down the second
       side-band channel, which is where git puts its "remote:" lines. */
    char aside[8192];
    size_t aside_len = 0;
    char *head = NULL;
    if (!repo.bare) bgit_symref_read (&repo, "HEAD", &head);
    /* A push that would lose commits is the pushing end's to refuse: git
       lets one through here unless it has been told not to. */
    bgit_config far_config;
    bgit_config_load (&far_config, &repo, NULL, 0);
    int deny_non_fast_forwards = bgit_config_bool (&far_config,
                                                   "receive.denyNonFastForwards", 0);
    bgit_config_release (&far_config);
    for (size_t i = 0; !status && i < n_commands; i++) {
        struct git_push_command *command = &commands[i];
        int unmaking = !strcmp (command->new_id, GIT_NULL_ID);
        char current[41] = "";
        int have = bgit_ref_read (&repo, command->name, current) == 0;
        if (head && !strcmp (head, command->name)) {
            command->refused = "branch is currently checked out";
            aside_len += (size_t) snprintf (aside + aside_len,
                                            sizeof aside - aside_len,
                                            "error: refusing to update checked "
                                            "out branch: %s\n", command->name);
        }
        else if (have && strcmp (current, command->old_id))
            command->refused = "fetch first";
        else if (!have && strcmp (command->old_id, GIT_NULL_ID))
            command->refused = "fetch first";
        else if (!unmaking && !bgit_odb_has (&odb, command->new_id))
            command->refused = "missing necessary objects";
        else if (!unmaking && have && deny_non_fast_forwards &&
                 strcmp (current, command->new_id) &&
                 bgit_is_ancestor (&odb, current, command->new_id) <= 0)
            command->refused = "non-fast-forward";
        if (command->refused) continue;
        int wrote = unmaking
            ? bgit_ref_delete (&repo, command->name, have ? current : NULL, NULL)
            : bgit_ref_update (&repo, command->name, command->new_id,
                               have ? current : "", "push");
        if (wrote < 0) command->refused = "failed to update ref";
    }
    free (head);

    /* And what became of each: the report is packets of its own, sent
       down the first side-band channel when one was asked for. */
    if (!status && aside_len && side_band &&
        bgit_pkt_write_band (1, 2, aside, aside_len) < 0)
        status = GIT_EXIT_FATAL;
    if (!status && wants_report) {
        unsigned char report[65000];
        size_t len = git_pkt_into (report, 0, sizeof report, "unpack ok\n");
        for (size_t i = 0; i < n_commands; i++) {
            char line[4300];
            if (commands[i].refused)
                snprintf (line, sizeof line, "ng %s %s\n", commands[i].name,
                          commands[i].refused);
            else snprintf (line, sizeof line, "ok %s\n", commands[i].name);
            len = git_pkt_into (report, len, sizeof report, line);
        }
        if (len + 4 < sizeof report) {
            memcpy (report + len, "0000", 4);
            len += 4;
        }
        if (side_band) {
            if (bgit_pkt_write_band (1, 1, report, len) < 0 ||
                bgit_pkt_flush (1) < 0)
                status = GIT_EXIT_FATAL;
        } else if (write (1, report, len) != (ssize_t) len)
            status = GIT_EXIT_FATAL;
    }
    free (commands);
    bgit_odb_release (&odb);
    bgit_repo_release (&repo);
    return status;
}

/* git ls-remote: what refs the far end has, without fetching anything. */
static int
git_cmd_ls_remote (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git ls-remote [--heads] [--tags] [--symref] "
                        "[--upload-pack=<command>] [<repository>]";
    int heads = 0, tags = 0, symrefs = 0, quiet = 0;
    const char *program = NULL, *where = NULL;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--heads") || !strcmp (w, "-h")) heads = 1;
        else if (!strcmp (w, "--tags") || !strcmp (w, "-t")) tags = 1;
        else if (!strcmp (w, "--symref")) symrefs = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strncmp (w, "--upload-pack=", 14)) program = w + 14;
        else if ((!strcmp (w, "-u") || !strcmp (w, "--upload-pack")) && p->next) {
            program = p->next->word->word;
            p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!where) where = w;
        else return git_fatal ("this build's git ls-remote does not take "
                               "patterns yet");
    }

    /* Inside a repository a name stands for the URL configured for it,
       as it does for fetch; outside one, only a path can be listed. */
    bgit_repo here;
    const char *url = NULL;
    if (bgit_repo_discover (".", &here) == 0) {
        bgit_repo_release (&here);
        if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
        url = git_remote_url (ctx, where ? where : "origin");
    } else
        /* Outside a repository there is still a configuration: what the
           far end wants said, and where a credential is kept. */
        bgit_config_load (&ctx->cfg, NULL, git_overrides, git_n_overrides);
    /* Without a repository named on the command line, git says which one
       it went to. */
    int named = where != NULL;
    if (url) where = url;
    else if (!where)
        return git_fatal ("No remote configured to list refs from.");

    if (!git_can_reach (where))
        return git_fatal ("this build's git ls-remote takes a path, an ssh "
                          "address or an http URL; git:// is not done");
    if (!named && !quiet) fprintf (stderr, "From %s\n", where);

    git_conn conn;
    if (git_far_end_open (&conn, ctx, where, program, 0) < 0) return GIT_EXIT_FATAL;
    int status = 0;

    bgit_proto_ref *refs = NULL;
    size_t n_refs = 0;
    if (!status) {
        const char *prefixes[2];
        size_t n_prefixes = 0;
        if (heads) prefixes[n_prefixes++] = "refs/heads/";
        if (tags) prefixes[n_prefixes++] = "refs/tags/";
        if (bgit_proto_ls_refs (&conn.io, prefixes, n_prefixes, 1, 1,
                                &refs, &n_refs) < 0)
            status = git_far_end_gone ();
    }
    if (!status)
        for (size_t i = 0; i < n_refs; i++) {
            if (symrefs && refs[i].symref)
                printf ("ref: %s\t%s\n", refs[i].symref, refs[i].name);
            printf ("%s\t%s\n", refs[i].id, refs[i].name);
            if (refs[i].peeled[0])
                printf ("%s\t%s^{}\n", refs[i].peeled, refs[i].name);
        }
    bgit_proto_refs_release (refs, n_refs);
    if (git_conn_close (&conn) < 0 && !status) status = git_far_end_gone ();
    return status;
}

/* ---- clone, fetch and push --------------------------------------------- */

/* One branch the far end has. */
struct git_remote_ref {
    char name[4096];      /* refs/heads/... over there */
    char local[4096];     /* refs/remotes/<remote>/... over here */
    char id[41];
    char old[41];
    int updated;
    int is_new;
};

static int
git_remote_heads (bgit_repo *remote, const char *name,
                  struct git_remote_ref **out, size_t *n_out)
{
    bgit_ref *refs = NULL;
    size_t n = 0;
    if (bgit_refs_list (remote, "refs/heads/", &refs, &n) < 0) return -1;
    struct git_remote_ref *list = calloc (n ? n : 1, sizeof *list);
    if (!list) { bgit_refs_free (refs, n); return -1; }
    for (size_t i = 0; i < n; i++) {
        snprintf (list[i].name, sizeof list[i].name, "%s", refs[i].name);
        snprintf (list[i].local, sizeof list[i].local, "refs/remotes/%s/%s",
                  name, refs[i].name + 11);
        memcpy (list[i].id, refs[i].sha, 41);
    }
    bgit_refs_free (refs, n);
    *out = list;
    *n_out = n;
    return 0;
}

/* One ref a fetch brings over, and where it lands. */
struct git_fetch_want {
    char src[4096];          /* the ref over there */
    char dst[4096];          /* the ref here, empty for one only recorded */
    char id[41];
    char old[41];
    int forced;              /* the refspec had a + in front of it */
    int asked;               /* a refspec named it, rather than a tag that came along */
    int is_new, updated, unmade, forced_update, refused;
};

/* The summary line a fetch or a push prints for one ref. */
static void
git_report_ref (git_context *ctx, const char *old, const char *id,
                const char *from, const char *to, int width)
{
    char old_short[41], new_short[41];
    git_abbrev (ctx, id, 7, new_short, sizeof new_short);
    if (!old || !*old) {
        fprintf (stderr, " * [new branch]      %-*s -> %s\n", width, from, to);
        return;
    }
    git_abbrev (ctx, old, 7, old_short, sizeof old_short);
    fprintf (stderr, "   %s..%s  %-*s -> %s\n", old_short, new_short, width,
             from, to);
}

/* The line a fetch prints for one ref: the same shapes a push prints,
   with the left column lined up, which is how git prints a fetch. */
static void
git_report_fetch (git_context *ctx, const char *name,
                  const struct git_fetch_want *want, int width)
{
    const char *from = want->unmade ? "(none)" : git_ref_short (want->src);
    char to[4096];
    if (!strncmp (want->dst, "refs/remotes/", 13))
        snprintf (to, sizeof to, "%s", want->dst + 13);
    else snprintf (to, sizeof to, "%s", git_ref_short (want->dst));
    (void) name;
    char what[32];
    /* A ref with nowhere to land was only written down, and git says so
       plainly: what it is, and that FETCH_HEAD is where it went. */
    if (!*want->dst) {
        fprintf (stderr, " * %-18s%-*s -> FETCH_HEAD\n",
                 strncmp (want->src, "refs/tags/", 10) ? "branch" : "tag",
                 width, from);
        return;
    }
    if (want->refused) {
        fprintf (stderr, " ! %-18s%-*s -> %s  (non-fast-forward)\n",
                 "[rejected]", width, from, to);
        return;
    }
    if (want->unmade) {
        fprintf (stderr, " - %-18s%-*s -> %s\n", "[deleted]", width, from, to);
        return;
    }
    if (want->is_new) {
        snprintf (what, sizeof what, "[new %s]",
                  strncmp (want->src, "refs/tags/", 10) ? "branch" : "tag");
        fprintf (stderr, " * %-18s%-*s -> %s\n", what, width, from, to);
        return;
    }
    char old_short[41], new_short[41];
    git_abbrev (ctx, want->old, 7, old_short, sizeof old_short);
    git_abbrev (ctx, want->id, 7, new_short, sizeof new_short);
    if (want->forced_update)
        fprintf (stderr, " + %s...%s %-*s -> %s  (forced update)\n", old_short,
                 new_short, width, from, to);
    else
        fprintf (stderr, "   %s..%s  %-*s -> %s\n", old_short, new_short, width,
                 from, to);
}

/* The same for a push, which has more to say: a tag is not a branch, a
   ref can be unmade, and an update that is not a fast-forward says that
   it was forced. */
static void
git_report_push (git_context *ctx, const struct git_push_want *want)
{
    const char *from = git_ref_short (want->src);
    const char *to = git_ref_short (want->dst);
    /* git pads what stands in brackets to the same eighteen columns,
       whichever of them it is. */
    char what[32];
    if (want->refused) {
        snprintf (what, sizeof what, "[%s]",
                  want->remote_refused ? "remote rejected" : "rejected");
        fprintf (stderr, " ! %-18s%s -> %s (%s)\n", what, from, to,
                 want->refused);
        return;
    }
    if (!strcmp (want->id, GIT_NULL_ID)) {
        fprintf (stderr, " - %-18s%s\n", "[deleted]", to);
        return;
    }
    if (want->is_new) {
        snprintf (what, sizeof what, "[new %s]",
                  strncmp (want->dst, "refs/tags/", 10) ? "branch" : "tag");
        fprintf (stderr, " * %-18s%s -> %s\n", what, from, to);
        return;
    }
    char old_short[41], new_short[41];
    git_abbrev (ctx, want->old, 7, old_short, sizeof old_short);
    git_abbrev (ctx, want->id, 7, new_short, sizeof new_short);
    if (want->forced_update)
        fprintf (stderr, " + %s...%s %s -> %s (forced update)\n", old_short,
                 new_short, from, to);
    else
        fprintf (stderr, "   %s..%s  %s -> %s\n", old_short, new_short, from, to);
}

/* One side of a refspec, with the star that stands for the rest. A
   refspec is "<src>:<dst>", either side possibly ending in "*", and a +
   in front says an update need not be a fast-forward. */
struct git_refspec {
    char src[4096];
    char dst[4096];
    int forced;
};

/* Does NAME match PATTERN, which may end in a star? What the star stood
   for is left in REST. */
static int
git_refspec_matches (const char *pattern, const char *name, char *rest,
                     size_t restsz)
{
    size_t len = strlen (pattern);
    if (len && pattern[len - 1] == '*') {
        if (strncmp (name, pattern, len - 1)) return 0;
        snprintf (rest, restsz, "%s", name + len - 1);
        return 1;
    }
    if (strcmp (pattern, name)) return 0;
    *rest = '\0';
    return 1;
}

/* The name a matched ref lands under here. */
static void
git_refspec_target (const struct git_refspec *spec, const char *rest, char *out,
                    size_t outsz)
{
    size_t len = strlen (spec->dst);
    if (len && spec->dst[len - 1] == '*')
        snprintf (out, outsz, "%.*s%s", (int) (len - 1), spec->dst, rest);
    else snprintf (out, outsz, "%s", spec->dst);
}

/* Read one refspec as it was written. */
static void
git_refspec_read (const char *text, const char *name, struct git_refspec *out)
{
    memset (out, 0, sizeof *out);
    if (*text == '+') {
        out->forced = 1;
        text++;
    }
    const char *colon = strchr (text, ':');
    if (colon) {
        snprintf (out->src, sizeof out->src, "%.*s", (int) (colon - text), text);
        snprintf (out->dst, sizeof out->dst, "%s", colon + 1);
    } else {
        snprintf (out->src, sizeof out->src, "%s", text);
        out->dst[0] = '\0';           /* recorded, but not landed anywhere */
    }
    /* A short name on either side means the branch of that name. */
    if (*out->src && strncmp (out->src, "refs/", 5) && !strchr (out->src, '*')) {
        char full[4096];
        snprintf (full, sizeof full, "refs/heads/%s", out->src);
        snprintf (out->src, sizeof out->src, "%s", full);
    }
    if (*out->dst && strncmp (out->dst, "refs/", 5) && !strchr (out->dst, '*')) {
        char full[4096];
        snprintf (full, sizeof full, "refs/remotes/%s/%s", name, out->dst);
        snprintf (out->dst, sizeof out->dst, "%s", full);
    }
}

static int
git_cmd_fetch (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git fetch [-q] [-p|--prune] [-t|--tags] "
                        "[--upload-pack=<command>] [<remote> [<refspec>...]]";
    const char *name = NULL, *program = NULL;
    const char *given[32];
    size_t n_given = 0;
    int quiet = 0, prune = 0, with_tags = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-p") || !strcmp (w, "--prune")) prune = 1;
        else if (!strcmp (w, "-t") || !strcmp (w, "--tags")) with_tags = 1;
        else if (!strncmp (w, "--upload-pack=", 14)) program = w + 14;
        else if ((!strcmp (w, "-u") || !strcmp (w, "--upload-pack")) && p->next) {
            program = p->next->word->word;
            p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else if (n_given < sizeof given / sizeof *given) given[n_given++] = w;
        else return git_fatal ("this build's git fetch takes fewer refspecs "
                               "than that");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!name) name = "origin";
    /* A name from the configuration stands for its URL; anything else is
       the path itself, which is what git accepts too. A fetch like that
       has nowhere to put what it brings — there are no remote-tracking
       refs for a URL that is not a remote — so what it brings is written
       down in FETCH_HEAD and nowhere else, which is what git does. */
    const char *url = git_remote_url (ctx, name);
    int anonymous = !url;
    if (!url) url = name;
    if (!git_can_reach (url))
        return git_fatal ("this build's git fetch takes a path, an ssh "
                          "address or an http URL; git:// is not done");

    /* What to ask for: the refspecs given, or the one the remote is
       configured with, and the tags when they were asked for. */
    struct git_refspec specs[34];
    size_t n_specs = 0;
    for (size_t i = 0; i < n_given; i++)
        git_refspec_read (given[i], name, &specs[n_specs++]);
    if (!n_specs && anonymous) {
        /* Whatever the far end has checked out, and only into
           FETCH_HEAD. */
        memset (&specs[n_specs], 0, sizeof specs[0]);
        snprintf (specs[n_specs].src, sizeof specs[0].src, "HEAD");
        n_specs++;
    } else if (!n_specs) {
        char key[4096];
        snprintf (key, sizeof key, "remote.%s.fetch", name);
        const char *configured = bgit_config_get (&ctx->cfg, key);
        char standing[4096];
        if (!configured) {
            snprintf (standing, sizeof standing,
                      "+refs/heads/*:refs/remotes/%s/*", name);
            configured = standing;
        }
        git_refspec_read (configured, name, &specs[n_specs++]);
    }
    if (with_tags) git_refspec_read ("+refs/tags/*:refs/tags/*", name,
                                     &specs[n_specs++]);

    /* The far end is asked over the protocol, the way git asks it, even
       when it is a directory on this machine. */
    git_conn conn;
    if (git_far_end_open (&conn, ctx, url, program, 1) < 0) return GIT_EXIT_FATAL;

    const char *prefixes[36];
    size_t n_prefixes = 0;
    for (size_t i = 0; i < n_specs && n_prefixes < 34; i++) {
        static char held[34][4096];
        snprintf (held[n_prefixes], sizeof held[0], "%s", specs[i].src);
        char *star = strchr (held[n_prefixes], '*');
        if (star) *star = '\0';
        prefixes[n_prefixes] = held[n_prefixes];
        n_prefixes++;
    }
    /* The tags are listed as well: a fetch takes the ones that point at
       what it fetched, which is what include-tag asks the far end for.
       A fetch from a URL takes none of them, as git's does not. */
    if (!anonymous) prefixes[n_prefixes++] = "refs/tags/";

    bgit_proto_ref *refs = NULL;
    size_t n_refs = 0;
    int status = 0;
    if (bgit_proto_ls_refs (&conn.io, prefixes, n_prefixes, 0, 0, &refs,
                            &n_refs) < 0)
        status = git_far_end_gone ();

    /* Which of them each refspec asks for, and where each lands. */
    struct git_fetch_want *wants = NULL;
    size_t n_wants = 0;
    if (!status) {
        wants = calloc (n_refs ? n_refs : 1, sizeof *wants);
        if (!wants) status = GIT_EXIT_FATAL;
    }
    for (size_t i = 0; !status && i < n_refs; i++) {
        for (size_t k = 0; k < n_specs; k++) {
            char rest[4096];
            if (!git_refspec_matches (specs[k].src, refs[i].name, rest,
                                      sizeof rest))
                continue;
            struct git_fetch_want *want = &wants[n_wants];
            memset (want, 0, sizeof *want);
            snprintf (want->src, sizeof want->src, "%s", refs[i].name);
            if (*specs[k].dst)
                git_refspec_target (&specs[k], rest, want->dst, sizeof want->dst);
            memcpy (want->id, refs[i].id, 41);
            if (*want->dst && bgit_ref_read (&ctx->repo, want->dst, want->old) != 0)
                want->old[0] = '\0';
            want->is_new = *want->dst && !*want->old;
            want->updated = *want->dst &&
                            (want->is_new || strcmp (want->old, want->id));
            want->forced = specs[k].forced;
            want->asked = 1;
            n_wants++;
            break;
        }
    }

    /* Ask for what is missing here, saying what is already here so the
       far end sends no more than it must. */
    if (!status && n_wants) {
        const char **asked = calloc (n_wants, sizeof *asked);
        char (*have_ids)[41] = NULL;
        size_t n_asked = 0, n_haves = 0;
        if (!asked || git_local_haves (ctx, &have_ids, &n_haves) < 0)
            status = GIT_EXIT_FATAL;
        for (size_t i = 0; !status && i < n_wants; i++)
            if (!bgit_odb_has (&ctx->odb, wants[i].id))
                asked[n_asked++] = wants[i].id;
        if (!status && n_asked) {
            const char **haves = calloc (n_haves ? n_haves : 1, sizeof *haves);
            if (!haves) status = GIT_EXIT_FATAL;
            for (size_t i = 0; !status && i < n_haves; i++) haves[i] = have_ids[i];
            unsigned char *pack = NULL;
            size_t pack_len = 0;
            if (!status && bgit_proto_fetch (&conn.io, asked, n_asked, haves,
                                             n_haves, &pack, &pack_len) < 0)
                status = git_far_end_gone ();
            if (!status && git_store_pack (ctx, pack, pack_len) < 0)
                status = git_fatal ("cannot store what the far end sent");
            free (pack);
            free (haves);
        }
        free (have_ids);
        free (asked);
    }

    /* A tag that came with the objects is written down here, which is
       what git does with the tags of what it fetched. */
    for (size_t i = 0; !status && !anonymous && i < n_refs; i++) {
        if (strncmp (refs[i].name, "refs/tags/", 10)) continue;
        int already = 0;
        for (size_t k = 0; k < n_wants && !already; k++)
            if (!strcmp (wants[k].src, refs[i].name)) already = 1;
        char here[41];
        if (already || !bgit_odb_has (&ctx->odb, refs[i].id)) continue;
        if (bgit_ref_read (&ctx->repo, refs[i].name, here) == 0) continue;
        struct git_fetch_want *want = &wants[n_wants++];
        memset (want, 0, sizeof *want);
        snprintf (want->src, sizeof want->src, "%s", refs[i].name);
        snprintf (want->dst, sizeof want->dst, "%s", refs[i].name);
        memcpy (want->id, refs[i].id, 41);
        want->is_new = want->updated = 1;
    }

    /* Whether an update is a fast-forward can only be told once the
       objects are here, so it is told now rather than before. An update
       that is not one needs the + that git writes in front of a
       refspec, or it is refused. */
    for (size_t i = 0; !status && i < n_wants; i++) {
        struct git_fetch_want *want = &wants[i];
        if (!want->updated || want->is_new) continue;
        if (bgit_is_ancestor (&ctx->odb, want->old, want->id) > 0) continue;
        if (want->forced) want->forced_update = 1;
        else {
            want->refused = 1;
            want->updated = 0;
        }
    }

    /* What is no longer over there goes from here, when asked. */
    struct git_fetch_want *gone = NULL;
    size_t n_gone = 0;
    if (!status && prune) {
        for (size_t k = 0; k < n_specs; k++) {
            size_t len = strlen (specs[k].dst);
            if (!len || specs[k].dst[len - 1] != '*') continue;
            char prefix[4096];
            snprintf (prefix, sizeof prefix, "%.*s", (int) (len - 1), specs[k].dst);
            bgit_ref *here = NULL;
            size_t n_here = 0;
            if (bgit_refs_list (&ctx->repo, prefix, &here, &n_here) < 0) continue;
            struct git_fetch_want *grown = realloc (gone, (n_gone + n_here) *
                                                    sizeof *grown);
            if (!grown) { bgit_refs_free (here, n_here); break; }
            gone = grown;
            for (size_t i = 0; i < n_here; i++) {
                int still = 0;
                for (size_t w = 0; w < n_wants && !still; w++)
                    if (!strcmp (wants[w].dst, here[i].name)) still = 1;
                /* origin/HEAD is not a branch the far end lists. */
                if (still || !strcmp (here[i].name + strlen (prefix), "HEAD"))
                    continue;
                struct git_fetch_want *want = &gone[n_gone];
                memset (want, 0, sizeof *want);
                snprintf (want->dst, sizeof want->dst, "%s", here[i].name);
                memcpy (want->old, here[i].sha, 41);
                want->unmade = want->updated = 1;
                n_gone++;
            }
            bgit_refs_free (here, n_here);
        }
    }

    /* The refs themselves, then what a merge would use. */
    int width = 10, any = 0;        /* git's own minimum for this column */
    for (size_t i = 0; !status && i < n_wants + n_gone; i++) {
        struct git_fetch_want *want = i < n_wants ? &wants[i] : &gone[i - n_wants];
        if (!want->updated && !want->refused && *want->dst) continue;
        any = 1;
        int len = (int) strlen (want->unmade ? "(none)" : git_ref_short (want->src));
        if (len > width) width = len;
    }
    /* git records the command as it was given, so a reflog says which
       fetch it was. */
    char action[4096];
    size_t action_len = (size_t) snprintf (action, sizeof action, "fetch");
    for (WORD_LIST *p = args; p && action_len < sizeof action; p = p->next)
        action_len += (size_t) snprintf (action + action_len,
                                        sizeof action - action_len, " %s",
                                        p->word->word);
    for (size_t i = 0; !status && i < n_wants; i++) {
        if (!wants[i].updated) continue;
        char message[4200];
        snprintf (message, sizeof message, "%s: %s", action,
                  wants[i].is_new ? "storing head" : "fast-forward");
        if (bgit_ref_update (&ctx->repo, wants[i].dst, wants[i].id, NULL,
                             message) < 0)
            status = GIT_EXIT_FATAL;
    }
    for (size_t i = 0; !status && i < n_gone; i++)
        if (bgit_ref_delete (&ctx->repo, gone[i].dst, NULL, NULL) < 0)
            status = GIT_EXIT_FATAL;

    /* FETCH_HEAD is what a fetch leaves for a merge to read: every ref
       it brought, and which one of them the current branch follows. */
    if (!status) {
        char upstream[4096] = "";
        struct git_state state;
        if (git_state_load (ctx, &state) == 0) {
            if (state.branch) {
                char key[4096];
                snprintf (key, sizeof key, "branch.%s.merge", state.branch + 11);
                const char *merge = bgit_config_get (&ctx->cfg, key);
                if (merge) snprintf (upstream, sizeof upstream, "%s", merge);
            }
            git_state_release (&state);
        }
        if (!*upstream && n_wants) snprintf (upstream, sizeof upstream, "%s",
                                             wants[0].src);
        char *record = NULL;
        size_t record_len = 0, record_cap = 0;
        for (size_t i = 0; i < n_wants; i++) {
            char line[8192];
            /* A ref asked for by name from a URL is what the fetch was
               for, and git leaves it for a merge to take. */
            int for_merge = !strcmp (wants[i].src, upstream) ||
                            (anonymous && wants[i].asked);
            int len;
            if (anonymous && !strcmp (wants[i].src, "HEAD"))
                len = snprintf (line, sizeof line, "%s\t%s\t%s\n",
                                wants[i].id, for_merge ? "" : "not-for-merge",
                                url);
            else
                len = snprintf (line, sizeof line, "%s\t%s\t%s '%s' of %s\n",
                                wants[i].id, for_merge ? "" : "not-for-merge",
                                strncmp (wants[i].src, "refs/tags/", 10) ? "branch"
                                                                        : "tag",
                                git_ref_short (wants[i].src), url);
            if (bgit_pack_buf_append ((unsigned char **) &record, &record_len,
                                      &record_cap, line, (size_t) len) < 0) {
                status = GIT_EXIT_FATAL;
                break;
            }
        }
        if (!status) {
            char path[4096];
            snprintf (path, sizeof path, "%s/FETCH_HEAD", ctx->repo.git_dir);
            FILE *out = fopen (path, "w");
            if (!out || (record_len &&
                         fwrite (record, 1, record_len, out) != record_len) ||
                fclose (out) != 0)
                status = git_fatal ("cannot write FETCH_HEAD");
        }
        free (record);
    }

    if (!status && any && !quiet) {
        fprintf (stderr, "From %s\n", url);
        for (size_t i = 0; i < n_wants + n_gone; i++) {
            struct git_fetch_want *want = i < n_wants ? &wants[i]
                                                      : &gone[i - n_wants];
            if (!want->updated && !want->refused && *want->dst) continue;
            git_report_fetch (ctx, name, want, width);
        }
    }
    bgit_proto_refs_release (refs, n_refs);
    free (wants);
    free (gone);
    if (git_conn_close (&conn) < 0 && !status) status = git_far_end_gone ();
    return status;
}

/* Cloning from a bundle: there is no far end to ask, so the refs come from
   the header and the objects from the pack behind it. What is made is a
   clone like any other — tracking refs, a branch to stand on, and the
   bundle's own path as the remote. */
static int
git_clone_bundle (git_context *ctx, const char *absolute, const char *source,
                  const char *target, const char *remote_name,
                  const char *wanted, int quiet, int bare, int no_checkout)
{
    struct git_bundle bundle;
    if (git_bundle_read (absolute, &bundle) < 0) return 1;
    if (!quiet)
        fprintf (stderr, bare ? "Cloning into bare repository '%s'...\n"
                              : "Cloning into '%s'...\n", target);
    /* A bundle that takes something for granted cannot start a clone, since
       a clone starts with nothing, and nothing is left behind when it will
       not go. */
    if (bundle.n_prerequisites) {
        git_bundle_prerequisites (ctx, &bundle);
        fprintf (stderr, "fatal: remote transport reported error\n");
        git_bundle_release (&bundle);
        return GIT_EXIT_FATAL;
    }

    WORD_LIST *init = make_word_list (make_word ((char *) target), NULL);
    if (bare) init = make_word_list (make_word ("--bare"), init);
    init = make_word_list (make_word ("-q"), init);
    git_context fresh;
    memset (&fresh, 0, sizeof fresh);
    int status = git_cmd_init (&fresh, init);
    dispose_words (init);
    if (!status && chdir (target) < 0)
        status = git_fatal ("cannot enter '%s': %s", target, strerror (errno));
    bgit_config_release (&ctx->cfg);
    if (!status && git_context_open (ctx) != 0) status = GIT_EXIT_FATAL;
    if (status) { git_bundle_release (&bundle); return status; }

    if (bundle.pack_len &&
        git_store_pack (ctx, bundle.pack, bundle.pack_len) < 0)
        status = GIT_EXIT_FATAL;

    /* What the bundle says HEAD was, so that the clone stands where the
       bundle was made. */
    char head_id[41] = "";
    for (size_t i = 0; !status && i < bundle.n; i++)
        if (bundle.names[i] && !strcmp (bundle.names[i], "HEAD"))
            memcpy (head_id, bundle.ids[i], 41);

    char on_branch[4096] = "";
    for (size_t i = 0; !status && i < bundle.n; i++) {
        const char *name = bundle.names[i];
        if (!name) continue;                       /* a prerequisite */
        if (!strncmp (name, "refs/heads/", 11)) {
            const char *branch = name + 11;
            char local[4096];
            if (bare) snprintf (local, sizeof local, "%s", name);
            else snprintf (local, sizeof local, "refs/remotes/%s/%s",
                           remote_name, branch);
            if (bgit_ref_set (&ctx->repo, local, bundle.ids[i], NULL) < 0)
                status = GIT_EXIT_FATAL;
            /* The branch to stand on: the one asked for, or the one the
               bundle's HEAD was on. */
            int take = wanted ? !strcmp (branch, wanted)
                              : (*head_id && !strcmp (bundle.ids[i], head_id) &&
                                 !*on_branch);
            if (take) snprintf (on_branch, sizeof on_branch, "%s", branch);
        } else if (!strncmp (name, "refs/tags/", 10)) {
            if (bgit_ref_set (&ctx->repo, name, bundle.ids[i], NULL) < 0)
                status = GIT_EXIT_FATAL;
        }
    }
    if (!status && wanted && !*on_branch)
        status = git_fatal ("Remote branch %s not found in upstream %s",
                            wanted, remote_name);

    if (!status && !bare) {
        char key[4096];
        snprintf (key, sizeof key, "remote.%s.url", remote_name);
        /* Where the bundle is, not how it was named on the command line,
           which is what a clone from a path records too. */
        if (git_config_write (ctx, key, absolute) < 0) status = GIT_EXIT_FATAL;
        char value[4096];
        snprintf (key, sizeof key, "remote.%s.fetch", remote_name);
        snprintf (value, sizeof value, "+refs/heads/*:refs/remotes/%s/*",
                  remote_name);
        if (!status && git_config_write (ctx, key, value) < 0)
            status = GIT_EXIT_FATAL;
    }

    if (!status && *on_branch) {
        char local[4096], remote_ref[4096], id[41];
        snprintf (local, sizeof local, "refs/heads/%s", on_branch);
        if (bare) snprintf (remote_ref, sizeof remote_ref, "%s", local);
        else snprintf (remote_ref, sizeof remote_ref, "refs/remotes/%s/%s",
                       remote_name, on_branch);
        if (bgit_ref_read (&ctx->repo, remote_ref, id) == 0 &&
            bgit_ref_update (&ctx->repo, local, id, NULL,
                             "clone: from bundle") < 0)
            status = GIT_EXIT_FATAL;
        if (!status && bgit_symref_write (&ctx->repo, "HEAD", local, NULL) < 0)
            status = GIT_EXIT_FATAL;
        /* And the remote's own HEAD, which stands for the branch a clone
           without a name would take. */
        if (!status && !bare) {
            char remote_head[4096];
            snprintf (remote_head, sizeof remote_head, "refs/remotes/%s/HEAD",
                      remote_name);
            if (bgit_symref_write (&ctx->repo, remote_head, remote_ref, NULL) < 0)
                status = GIT_EXIT_FATAL;
        }
        if (!status && !bare) {
            char key[4096], value[4096];
            snprintf (key, sizeof key, "branch.%s.remote", on_branch);
            if (git_config_write (ctx, key, remote_name) < 0)
                status = GIT_EXIT_FATAL;
            snprintf (key, sizeof key, "branch.%s.merge", on_branch);
            snprintf (value, sizeof value, "refs/heads/%s", on_branch);
            if (!status && git_config_write (ctx, key, value) < 0)
                status = GIT_EXIT_FATAL;
        }
        /* And what is in that branch, on disk. */
        if (!status && !bare && !no_checkout) {
            struct git_state state;
            if (git_state_load (ctx, &state) < 0) status = GIT_EXIT_FATAL;
            else {
                if (git_switch_to (ctx, &state, on_branch, 0, 1) != 0)
                    status = GIT_EXIT_FATAL;
                git_state_release (&state);
            }
        }
    }
    git_bundle_release (&bundle);
    return status;
}

static int
git_cmd_clone (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git clone [-q] [--bare] [-n|--no-checkout] "
                        "[-b|--branch <name>] [-o|--origin <name>] "
                        "<path> | <http url> [<directory>]";
    const char *source = NULL, *where = NULL;
    const char *wanted = NULL, *remote_name = "origin";
    int quiet = 0, bare = 0, no_checkout = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "--bare")) bare = 1;
        else if (!strcmp (w, "-n") || !strcmp (w, "--no-checkout")) no_checkout = 1;
        else if (!strncmp (w, "--branch=", 9)) wanted = w + 9;
        else if ((!strcmp (w, "-b") || !strcmp (w, "--branch")) && p->next) {
            wanted = p->next->word->word;
            p = p->next;
        }
        else if (!strncmp (w, "--origin=", 9)) remote_name = w + 9;
        else if ((!strcmp (w, "-o") || !strcmp (w, "--origin")) && p->next) {
            remote_name = p->next->word->word;
            p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!source) source = w;
        else if (!where) where = w;
        else return git_usage (usage);
    }
    if (!source) return git_usage (usage);
    if (!git_can_reach (source))
        return git_fatal ("this build's git clone takes a path, an ssh "
                          "address or an http URL; git:// is not done");

    /* A file that is a bundle is cloned from the bundle itself: its header
       says what refs it carries and the rest of it is the pack. */
    int from_bundle = 0;
    {
        struct stat st;
        if (stat (source, &st) == 0 && S_ISREG (st.st_mode)) {
            FILE *probe = fopen (source, "rb");
            if (probe) {
                char first[32] = "";
                size_t got = fread (first, 1, strlen (GIT_BUNDLE_SIGNATURE),
                                    probe);
                fclose (probe);
                if (got == strlen (GIT_BUNDLE_SIGNATURE) &&
                    (!memcmp (first, GIT_BUNDLE_SIGNATURE, got) ||
                     !memcmp (first, "# v3 git bundle\n", got)))
                    from_bundle = 1;
            }
        }
    }

    /* Where it lands: the last part of the source, without any .git. */
    char target[4096];
    if (where) snprintf (target, sizeof target, "%s", where);
    else {
        char copy[4096];
        snprintf (copy, sizeof copy, "%s", source);
        size_t len = strlen (copy);
        while (len && copy[len - 1] == '/') copy[--len] = '\0';
        if (len > 4 && !strcmp (copy + len - 4, ".git")) copy[len - 4] = '\0';
        len = strlen (copy);
        while (len && copy[len - 1] == '/') copy[--len] = '\0';
        const char *base = strrchr (copy, '/');
        if (!base && git_url_is_ssh (copy)) base = strrchr (copy, ':');
        snprintf (target, sizeof target, "%s", base ? base + 1 : copy);
    }
    if (!*target) return git_fatal ("cannot work out a directory name");

    char absolute[4096];
    if (from_bundle) {
        if (git_absolute (source, absolute, sizeof absolute) < 0)
            return git_fatal ("cannot work out where '%s' is", source);
        return git_clone_bundle (ctx, absolute, source, target, remote_name,
                                 wanted, quiet, bare, no_checkout);
    }
    if (git_url_is_http (source) || git_url_is_ssh (source))
        snprintf (absolute, sizeof absolute, "%s", source);
    else {
        if (git_absolute (source, absolute, sizeof absolute) < 0)
            return git_fatal ("cannot work out where '%s' is", source);

        /* git looks at a local path itself before starting anything, so
           that a missing one is its own message rather than the far
           end's. A URL has no such shortcut: the far end answers. */
        bgit_repo check;
        bgit_odb check_odb;
        if (git_open_remote (absolute, &check, &check_odb) < 0)
            return git_fatal ("repository '%s' does not exist", source);
        bgit_odb_release (&check_odb);
        bgit_repo_release (&check);
    }

    /* A clone has no repository of its own yet, but there is still a
       configuration to read: what the far end wants said, and where a
       credential for it is kept. */
    bgit_config_load (&ctx->cfg, NULL, git_overrides, git_n_overrides);
    git_conn conn;
    if (git_far_end_open (&conn, ctx, absolute, NULL, 1) < 0) return GIT_EXIT_FATAL;

    /* What the far end has: its branches, its tags, and what its HEAD
       points at, which is the branch a clone checks out. */
    bgit_proto_ref *refs = NULL;
    size_t n_refs = 0;
    const char *prefixes[3] = { "refs/heads/", "refs/tags/", "HEAD" };
    if (bgit_proto_ls_refs (&conn.io, prefixes, 3, 1, 0, &refs, &n_refs) < 0) {
        git_far_end_gone ();
        git_conn_close (&conn);
        return GIT_EXIT_FATAL;
    }

    if (!quiet)
        fprintf (stderr, bare ? "Cloning into bare repository '%s'...\n"
                              : "Cloning into '%s'...\n", target);

    /* A fresh repository, then everything the far end has. */
    WORD_LIST *init = make_word_list (make_word ((char *) target), NULL);
    if (bare) init = make_word_list (make_word ("--bare"), init);
    init = make_word_list (make_word ("-q"), init);
    git_context fresh;
    memset (&fresh, 0, sizeof fresh);
    int status = git_cmd_init (&fresh, init);
    dispose_words (init);
    if (!status && chdir (target) < 0)
        status = git_fatal ("cannot enter '%s': %s", target, strerror (errno));
    bgit_config_release (&ctx->cfg);      /* the new repository has its own */
    if (!status && git_context_open (ctx) != 0) status = GIT_EXIT_FATAL;
    if (status) {
        bgit_proto_refs_release (refs, n_refs);
        git_conn_close (&conn);
        return status;
    }

    /* The branches the far end has, and where each lands here. */
    struct git_remote_ref *heads = calloc (n_refs ? n_refs : 1, sizeof *heads);
    size_t n_heads = 0;
    if (!heads) status = GIT_EXIT_FATAL;
    for (size_t i = 0; !status && i < n_refs; i++) {
        if (strncmp (refs[i].name, "refs/heads/", 11)) continue;
        snprintf (heads[n_heads].name, sizeof heads[n_heads].name, "%s",
                  refs[i].name);
        snprintf (heads[n_heads].local, sizeof heads[n_heads].local,
                  "refs/remotes/%s/%s", remote_name, refs[i].name + 11);
        memcpy (heads[n_heads].id, refs[i].id, 41);
        n_heads++;
    }
    /* A bare clone is where the branches live, not a copy of somewhere
       else's: git writes them as branches and keeps no tracking refs. */
    if (bare)
        for (size_t i = 0; i < n_heads; i++)
            snprintf (heads[i].local, sizeof heads[i].local, "%s", heads[i].name);

    bgit_ref *tags = calloc (n_refs ? n_refs : 1, sizeof *tags);
    size_t n_tags = 0;
    if (!tags) status = GIT_EXIT_FATAL;
    for (size_t i = 0; !status && i < n_refs; i++) {
        if (strncmp (refs[i].name, "refs/tags/", 10)) continue;
        tags[n_tags].name = strdup (refs[i].name);
        if (!tags[n_tags].name) { status = GIT_EXIT_FATAL; break; }
        memcpy (tags[n_tags].sha, refs[i].id, 41);
        n_tags++;
    }

    /* Everything those refs reach, asked for over the connection. A
       clone has nothing yet, so it tells the far end of no haves. */
    const char **roots = calloc (n_heads + n_tags + 1, sizeof *roots);
    if (!status && !roots) status = GIT_EXIT_FATAL;
    size_t n_roots = 0;
    for (size_t i = 0; !status && i < n_heads; i++) roots[n_roots++] = heads[i].id;
    for (size_t i = 0; !status && i < n_tags; i++) roots[n_roots++] = tags[i].sha;
    if (!status && n_roots) {
        unsigned char *pack = NULL;
        size_t pack_len = 0;
        if (bgit_proto_fetch (&conn.io, roots, n_roots, NULL, 0, &pack,
                              &pack_len) < 0)
            status = git_far_end_gone ();
        if (!status && git_store_pack (ctx, pack, pack_len) < 0)
            status = git_fatal ("cannot store what the far end sent");
        free (pack);
    }
    free (roots);

    /* What the far end's HEAD names is what gets checked out, unless a
       branch was asked for by name. */
    char *head_ref = NULL;
    char head_id[41] = "";
    for (size_t i = 0; i < n_refs; i++) {
        if (strcmp (refs[i].name, "HEAD")) continue;
        if (refs[i].symref) head_ref = strdup (refs[i].symref);
        memcpy (head_id, refs[i].id, 41);
        break;
    }
    if (!status && wanted) {
        char asked[4096];
        snprintf (asked, sizeof asked, "refs/heads/%s", wanted);
        int found = 0;
        for (size_t i = 0; i < n_refs && !found; i++) {
            if (strcmp (refs[i].name, asked)) continue;
            free (head_ref);
            head_ref = strdup (asked);
            memcpy (head_id, refs[i].id, 41);
            found = 1;
        }
        if (!found)
            status = git_fatal ("Remote branch %s not found in upstream %s",
                                wanted, remote_name);
    }
    bgit_proto_refs_release (refs, n_refs);
    refs = NULL;
    n_refs = 0;

    char message[4096];
    snprintf (message, sizeof message, "clone: from %s", absolute);
    for (size_t i = 0; !status && i < n_heads; i++)
        if (bgit_ref_set (&ctx->repo, heads[i].local, heads[i].id, NULL) < 0)
            status = GIT_EXIT_FATAL;
    for (size_t i = 0; !status && i < n_tags; i++)
        if (bgit_ref_set (&ctx->repo, tags[i].name, tags[i].sha, NULL) < 0)
            status = GIT_EXIT_FATAL;

    char key[4096], value[4096];
    if (!status) {
        snprintf (key, sizeof key, "remote.%s.url", remote_name);
        if (git_config_write (ctx, key, absolute) < 0)
            status = GIT_EXIT_FATAL;
        snprintf (key, sizeof key, "remote.%s.fetch", remote_name);
        snprintf (value, sizeof value, "+refs/heads/*:refs/remotes/%s/*",
                  remote_name);
        if (!status && !bare && git_config_write (ctx, key, value) < 0)
            status = GIT_EXIT_FATAL;
    }
    if (!status && head_ref && !strncmp (head_ref, "refs/heads/", 11)) {
        const char *branch = head_ref + 11;
        char tracking[4096];
        char head_tracking[4096];
        snprintf (tracking, sizeof tracking, "refs/remotes/%s/%s", remote_name,
                  branch);
        snprintf (head_tracking, sizeof head_tracking, "refs/remotes/%s/HEAD",
                  remote_name);
        if (!bare && bgit_symref_write (&ctx->repo, head_tracking, tracking,
                                        message) < 0)
            status = GIT_EXIT_FATAL;
        snprintf (key, sizeof key, "branch.%s.remote", branch);
        if (!status && !bare && git_config_write (ctx, key, remote_name) < 0)
            status = GIT_EXIT_FATAL;
        snprintf (key, sizeof key, "branch.%s.merge", branch);
        if (!status && !bare && git_config_write (ctx, key, head_ref) < 0)
            status = GIT_EXIT_FATAL;

        if (!status && *head_id) {
            char local[4096];
            snprintf (local, sizeof local, "refs/heads/%s", branch);
            /* The branch is already written where a bare clone keeps it,
               and a bare repository logs no ref updates. */
            if (!bare &&
                bgit_ref_update (&ctx->repo, local, head_id, NULL, message) < 0)
                status = GIT_EXIT_FATAL;
            if (!status && bgit_symref_write (&ctx->repo, "HEAD", local, NULL) < 0)
                status = GIT_EXIT_FATAL;
            if (!status && !bare && !no_checkout) {
                /* The working tree and index follow. */
                struct git_state state;
                if (git_state_load (ctx, &state) < 0) status = GIT_EXIT_FATAL;
                else {
                    char tree[41];
                    if (bgit_commit_tree (&ctx->odb, head_id, tree) < 0 ||
                        bgit_checkout_tree (&ctx->repo, &ctx->odb, tree,
                                            &state.index, &state.n_index, 1,
                                            NULL) < 0 ||
                        git_index_store (ctx, state.index, state.n_index) < 0)
                        status = GIT_EXIT_FATAL;
                    bgit_reflog_append (&ctx->repo, "HEAD", NULL, head_id,
                                        message);
                    git_state_release (&state);
                }
            }
        }
    }
    free (head_ref);
    free (heads);
    bgit_refs_free (tags, n_tags);
    bgit_proto_refs_release (refs, n_refs);
    if (git_conn_close (&conn) < 0 && !status) status = git_far_end_gone ();
    if (!status && !quiet) fprintf (stderr, "done.\n");
    return status;
}

static int
git_cmd_push (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git push [-q] [-f|--force] [--delete] [--tags] "
                        "[-n|--dry-run] [-u|--set-upstream] "
                        "[--receive-pack=<command>] [<remote> | <path> "
                        "[<refspec>...]]";
    const char *name = NULL, *program = NULL;
    const char *specs[64];
    size_t n_specs = 0;
    int quiet = 0, force = 0, deleting = 0, with_tags = 0, dry_run = 0;
    int set_upstream = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (!strcmp (w, "--delete") || !strcmp (w, "-d")) deleting = 1;
        else if (!strcmp (w, "--tags")) with_tags = 1;
        else if (!strcmp (w, "-n") || !strcmp (w, "--dry-run")) dry_run = 1;
        else if (!strcmp (w, "-u") || !strcmp (w, "--set-upstream")) set_upstream = 1;
        else if (!strncmp (w, "--receive-pack=", 15)) program = w + 15;
        else if (!strcmp (w, "--receive-pack") && p->next) {
            program = p->next->word->word;
            p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else if (n_specs < sizeof specs / sizeof *specs) specs[n_specs++] = w;
        else return git_fatal ("this build's git push takes fewer refspecs "
                               "than that");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    if (!name) {
        if (!state.have_head || !state.branch) {
            git_state_release (&state);
            return git_fatal ("You are not currently on a branch.");
        }
        char key[4096];
        snprintf (key, sizeof key, "branch.%s.remote", state.branch + 11);
        const char *configured = bgit_config_get (&ctx->cfg, key);
        name = configured ? configured : "origin";
    }

    /* A name from the configuration stands for its URL; anything else is
       the path itself, which is what git accepts too. */
    const char *url = git_remote_url (ctx, name);
    int by_name = url != NULL;
    if (!url) url = name;
    if (!git_can_reach (url)) {
        git_state_release (&state);
        return git_fatal ("this build's git push takes a path, an ssh address "
                          "or an http URL; git:// is not done");
    }

    /* What to ask for: a refspec each, the tags if they were asked for,
       and the branch this end is on when nothing was named. */
    struct git_push_want *wants = NULL;
    size_t n_wants = 0, cap = 0;
    int status = 0;
    for (size_t i = 0; !status && i < n_specs; i++)
        if (git_push_want (ctx, &wants, &n_wants, &cap, specs[i], force,
                           deleting) < 0)
            status = GIT_EXIT_FATAL;
    if (!status && with_tags) {
        bgit_ref *tags = NULL;
        size_t n_tags = 0;
        if (bgit_refs_list (&ctx->repo, "refs/tags/", &tags, &n_tags) == 0) {
            for (size_t i = 0; !status && i < n_tags; i++)
                if (git_push_want (ctx, &wants, &n_wants, &cap, tags[i].name,
                                   force, 0) < 0)
                    status = GIT_EXIT_FATAL;
            bgit_refs_free (tags, n_tags);
        }
    }
    if (!status && !n_wants && !n_specs) {
        if (!state.have_head || !state.branch) {
            free (wants);
            git_state_release (&state);
            return git_fatal ("You are not currently on a branch.");
        }
        if (git_push_want (ctx, &wants, &n_wants, &cap, state.branch, force, 0) < 0)
            status = GIT_EXIT_FATAL;
    }
    if (status || !n_wants) {
        free (wants);
        git_state_release (&state);
        return status;
    }

    /* The far end is asked over the protocol, which for a push is the
       first one git spoke and the one it still uses. */
    git_conn conn;
    if (git_conn_open (&conn, ctx, url, program, "git-receive-pack") < 0) {
        free (wants);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    bgit_proto_ref *theirs = NULL;
    size_t n_theirs = 0;
    char *capabilities = NULL;
    if (bgit_proto_read_refs_v0 (conn.io.reader, &theirs, &n_theirs,
                                 &capabilities) < 0)
        status = git_far_end_gone ();

    /* What the far end holds for each of them now, which is what the push
       says it is replacing. */
    int refused_any = 0, anything = 0;
    for (size_t i = 0; !status && i < n_wants; i++) {
        struct git_push_want *want = &wants[i];
        for (size_t k = 0; k < n_theirs; k++)
            if (!strcmp (theirs[k].name, want->dst)) {
                memcpy (want->old, theirs[k].id, 41);
                break;
            }
        want->is_new = !*want->old;
        int unmaking = !strcmp (want->id, GIT_NULL_ID);
        if (unmaking && want->is_new) want->refused = "remote ref does not exist";
        else if (!unmaking && !want->is_new && !strcmp (want->old, want->id))
            continue;                              /* already where it goes */
        else if (!unmaking && !want->is_new && !want->forced) {
            /* A push may only move a ref forward unless it is forced, and
               git tells apart a tip this end has never seen from one it
               has seen but not built on. */
            if (!bgit_odb_has (&ctx->odb, want->old))
                want->refused = "fetch first";
            else if (bgit_is_ancestor (&ctx->odb, want->old, want->id) <= 0)
                want->refused = "non-fast-forward";
        }
        if (!unmaking && !want->is_new && !want->refused &&
            bgit_is_ancestor (&ctx->odb, want->old, want->id) <= 0)
            want->forced_update = 1;
        if (want->refused) refused_any = 1;
        anything = 1;
    }
    if (!status && !anything) {
        if (!quiet) fprintf (stderr, "Everything up-to-date\n");
        bgit_proto_refs_release (theirs, n_theirs);
        free (capabilities);
        free (wants);
        if (git_conn_close (&conn) < 0) status = git_far_end_gone ();
        git_state_release (&state);
        return status;
    }

    /* Saying what it would do and doing it are the same up to here. */
    if (!status && dry_run) {
        fflush (stdout);
        fprintf (stderr, "To %s\n", url);
        for (size_t i = 0; i < n_wants; i++)
            if (wants[i].refused || !wants[i].is_new || *wants[i].id)
                git_report_push (ctx, &wants[i]);
        if (refused_any)
            fprintf (stderr, "error: failed to push some refs to '%s'\n", url);
        bgit_proto_refs_release (theirs, n_theirs);
        free (capabilities);
        free (wants);
        if (git_conn_close (&conn) < 0) status = git_far_end_gone ();
        git_state_release (&state);
        return refused_any ? 1 : status;
    }

    /* The changes, with what this end can do, and then a pack holding
       everything the far end does not have yet. */
    int first = 1;
    for (size_t i = 0; !status && i < n_wants; i++) {
        struct git_push_want *want = &wants[i];
        if (want->refused) continue;
        char line[8192];
        size_t len = (size_t) snprintf (line, sizeof line, "%s %s %s",
                                        want->is_new ? GIT_NULL_ID : want->old,
                                        want->id, want->dst);
        if (first) {
            line[len++] = '\0';
            len += (size_t) snprintf (line + len, sizeof line - len,
                                      "report-status side-band-64k agent=%s",
                                      GIT_AGENT_STRING);
            first = 0;
        }
        if (bgit_proto_write (&conn.io, line, len) < 0)
            status = git_far_end_gone ();
        want->sent = 1;
    }
    if (!status && first) {
        /* Everything was refused before it was sent. */
        fflush (stdout);
        fprintf (stderr, "To %s\n", url);
        for (size_t i = 0; i < n_wants; i++)
            if (wants[i].refused) git_report_push (ctx, &wants[i]);
        fprintf (stderr, "error: failed to push some refs to '%s'\n", url);
        bgit_proto_refs_release (theirs, n_theirs);
        free (capabilities);
        free (wants);
        git_conn_close (&conn);
        git_state_release (&state);
        return 1;
    }
    if (!status && bgit_proto_flush (&conn.io) < 0) status = git_far_end_gone ();

    if (!status) {
        const char **stop = calloc (n_theirs ? n_theirs : 1, sizeof *stop);
        const char **roots = calloc (n_wants, sizeof *roots);
        size_t n_roots = 0;
        if (!stop || !roots) status = GIT_EXIT_FATAL;
        for (size_t i = 0; !status && i < n_theirs; i++) stop[i] = theirs[i].id;
        for (size_t i = 0; !status && i < n_wants; i++)
            if (wants[i].sent && strcmp (wants[i].id, GIT_NULL_ID))
                roots[n_roots++] = wants[i].id;
        char (*send)[41] = NULL;
        size_t n_send = 0;
        if (!status && bgit_reachable_objects (&ctx->odb, roots, n_roots, stop,
                                               n_theirs, &send, &n_send) < 0)
            status = GIT_EXIT_FATAL;
        free (stop);
        free (roots);
        unsigned char *pack = NULL;
        size_t pack_len = 0;
        struct bgit_pack_idx_entry *entries = NULL;
        unsigned char checksum[20];
        char checksum_hex[41] = "";
        if (!status && git_pack_build (&ctx->odb, send, n_send, &pack, &pack_len,
                                       &entries, checksum, checksum_hex) < 0)
            status = GIT_EXIT_FATAL;
        free (send);
        free (entries);
        /* The pack goes over as it is, after the commands; over HTTP the
           two together are the one request, which is sent now. */
        if (!status && (bgit_proto_raw (&conn.io, pack, pack_len) < 0 ||
                        bgit_proto_done (&conn.io) < 0))
            status = git_far_end_gone ();
        free (pack);
    }

    /* What the far end made of it: the report arrives as packets inside
       the first side-band channel, and anything it wants said goes to
       the second. */
    int unpacked = 0;
    bgit_proto_aside aside;
    memset (&aside, 0, sizeof aside);
    if (!status) {
        unsigned char *report = NULL;
        size_t report_len = 0, report_cap = 0;
        for (;;) {
            const unsigned char *data = NULL;
            int got = bgit_pkt_read (conn.io.reader, &data);
            if (got == BGIT_PKT_FLUSH || got == BGIT_PKT_EOF) break;
            if (got < 0) { status = git_far_end_gone (); break; }
            if (got < 1) continue;
            if (data[0] == 2 || data[0] == 3) {
                bgit_proto_aside_say (&aside, data + 1, (size_t) got - 1);
                continue;
            }
            if (bgit_pack_buf_append (&report, &report_len, &report_cap,
                                      data + 1, (size_t) got - 1) < 0) {
                status = GIT_EXIT_FATAL;
                break;
            }
        }
        bgit_pkt_reader inside;
        bgit_pkt_from_memory (&inside, report, report_len);
        for (; !status;) {
            char *line = NULL;
            int got = bgit_pkt_read_line (&inside, &line);
            if (got < 0) break;
            if (!strncmp (line, "unpack ok", 9)) unpacked = 1;
            else if (!strncmp (line, "unpack ", 7)) {
                fflush (stdout);
                fprintf (stderr, "error: remote unpack failed: %s\n", line + 7);
            }
            else if (!strncmp (line, "ng ", 3)) {
                char *why = strchr (line + 3, ' ');
                if (why) {
                    *why = '\0';
                    for (size_t i = 0; i < n_wants; i++)
                        if (!strcmp (wants[i].dst, line + 3)) {
                            wants[i].refused = strdup (why + 1);
                            wants[i].remote_refused = 1;
                            refused_any = 1;
                        }
                }
            }
            free (line);
        }
        bgit_pkt_release (&inside);
        free (report);
        bgit_proto_aside_flush (&aside);
    }
    if (!status && !unpacked)
        status = git_fatal ("the far end did not say what it did");

    if (!status && !quiet) {
        fflush (stdout);
        fprintf (stderr, "To %s\n", url);
        for (size_t i = 0; i < n_wants; i++)
            git_report_push (ctx, &wants[i]);
    }
    if (!status && refused_any) {
        fprintf (stderr, "error: failed to push some refs to '%s'\n", url);
        status = 1;
    }

    /* What went over is now what the far end has, which is worth
       recording for a remote that has a name to record it under. */
    for (size_t i = 0; status <= 1 && i < n_wants; i++) {
        struct git_push_want *want = &wants[i];
        if (want->refused || !want->sent) continue;
        if (by_name && !strncmp (want->dst, "refs/heads/", 11)) {
            char tracking[4096];
            snprintf (tracking, sizeof tracking, "refs/remotes/%s/%s", name,
                      want->dst + 11);
            if (strcmp (want->id, GIT_NULL_ID))
                bgit_ref_set (&ctx->repo, tracking, want->id, NULL);
            else bgit_ref_delete (&ctx->repo, tracking, NULL, NULL);
        }
        /* -u makes the branch follow where it was just pushed. */
        if (set_upstream && by_name && !strncmp (want->src, "refs/heads/", 11) &&
            strcmp (want->id, GIT_NULL_ID)) {
            char key[4096];
            snprintf (key, sizeof key, "branch.%s.remote", want->src + 11);
            git_config_write (ctx, key, name);
            snprintf (key, sizeof key, "branch.%s.merge", want->src + 11);
            git_config_write (ctx, key, want->dst);
            if (!quiet)
                fprintf (stderr, "branch '%s' set up to track '%s/%s'.\n",
                         want->src + 11, name, git_ref_short (want->dst));
        }
    }
    bgit_proto_refs_release (theirs, n_theirs);
    free (capabilities);
    free (wants);
    if (git_conn_close (&conn) < 0 && !status) status = git_far_end_gone ();
    git_state_release (&state);
    return status;
}

static int
git_cmd_pull (git_context *ctx, WORD_LIST *args)
{
    /* Fetch, then join what was fetched to this branch — by merging it,
       or by replaying this branch on top of it. */
    const char *usage = "git pull [-q] [--ff-only] [--no-ff] [--rebase] "
                        "[<remote> [<refspec>...]]";
    const char *name = NULL;
    const char *given[32];
    size_t n_given = 0;
    int ff_only = 0, no_ff = 0, rebase = -1, quiet = 0;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) { quiet = 1; continue; }
        if (!strcmp (w, "--ff-only")) { ff_only = 1; continue; }
        if (!strcmp (w, "--no-ff")) { no_ff = 1; continue; }
        if (!strcmp (w, "--ff")) continue;
        if (!strcmp (w, "-r") || !strcmp (w, "--rebase")) { rebase = 1; continue; }
        if (!strcmp (w, "--no-rebase")) { rebase = 0; continue; }
        if (w[0] == '-' && w[1]) return git_usage (usage);
        if (!name) name = w;
        else if (n_given < sizeof given / sizeof *given) given[n_given++] = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* What was not said on the command line the configuration may say —
       and when neither says anything, a pull that cannot simply catch up
       is one git refuses to guess about. */
    int said = rebase >= 0 || ff_only || no_ff;
    const char *configured_rebase = bgit_config_get (&ctx->cfg, "pull.rebase");
    if (rebase < 0)
        rebase = configured_rebase
                 ? bgit_config_bool (&ctx->cfg, "pull.rebase", 0) : 0;
    if (configured_rebase) said = 1;
    if (!ff_only && !no_ff) {
        const char *ff = bgit_config_get (&ctx->cfg, "pull.ff");
        if (ff) said = 1;
        if (ff && !strcmp (ff, "only")) ff_only = 1;
        else if (ff && !strcmp (ff, "false")) no_ff = 1;
    }

    WORD_LIST *fetch_args = NULL;
    for (size_t i = n_given; i-- > 0; )
        fetch_args = make_word_list (make_word ((char *) given[i]), fetch_args);
    if (name) fetch_args = make_word_list (make_word ((char *) name), fetch_args);
    if (quiet) fetch_args = make_word_list (make_word ("-q"), fetch_args);
    int status = git_cmd_fetch (ctx, fetch_args);
    dispose_words (fetch_args);
    if (status) return status;

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    if (!state.branch) {
        git_state_release (&state);
        return git_fatal ("You are not currently on a branch.");
    }
    char key[4096];
    const char *branch = state.branch + 11;
    snprintf (key, sizeof key, "branch.%s.remote", branch);
    const char *remote = bgit_config_get (&ctx->cfg, key);
    if (!remote) remote = name ? name : "origin";
    char tracking[4096];
    snprintf (tracking, sizeof tracking, "%s/%s", remote, branch);
    char head[41] = "";
    if (state.have_head) memcpy (head, state.head, 41);
    git_state_release (&state);

    /* A rebase replays this branch on what was fetched; a merge joins
       them. Either way the argument is where the far end got to: the
       branch this one follows, when the pull was of a remote and asked
       for nothing in particular, and otherwise what the fetch wrote down
       in FETCH_HEAD — which is what git takes as well. */
    const char *target = tracking;
    if (n_given || (name && !git_remote_url (ctx, name)) || !rebase)
        target = "FETCH_HEAD";

    /* Two branches that have each gone their own way can be joined by a
       merge or by a replay, and git will not choose for you. */
    char fetched[41];
    if (!said && *head && git_resolve (ctx, target, fetched, NULL) == 0 &&
        bgit_is_ancestor (&ctx->odb, head, fetched) <= 0 &&
        bgit_is_ancestor (&ctx->odb, fetched, head) <= 0) {
        fflush (stdout);
        fprintf (stderr,
          "hint: You have divergent branches and need to specify how to "
          "reconcile them.\n"
          "hint: You can do so by running one of the following commands "
          "sometime before\n"
          "hint: your next pull:\n"
          "hint:\n"
          "hint:   git config pull.rebase false  # merge\n"
          "hint:   git config pull.rebase true   # rebase\n"
          "hint:   git config pull.ff only       # fast-forward only\n"
          "hint:\n"
          "hint: You can replace \"git config\" with \"git config --global\" "
          "to set a default\n"
          "hint: preference for all repositories. You can also pass --rebase, "
          "--no-rebase,\n"
          "hint: or --ff-only on the command line to override the configured "
          "default per\n"
          "hint: invocation.\n");
        return git_fatal ("Need to specify how to reconcile divergent "
                          "branches.");
    }

    WORD_LIST *onto = make_word_list (make_word ((char *) target), NULL);
    if (rebase) status = git_cmd_rebase (ctx, onto);
    else {
        if (no_ff) onto = make_word_list (make_word ("--no-ff"), onto);
        if (ff_only) onto = make_word_list (make_word ("--ff-only"), onto);
        if (quiet) onto = make_word_list (make_word ("-q"), onto);
        status = git_cmd_merge (ctx, onto);
    }
    dispose_words (onto);
    return status;
}

/* ---- worktree ----------------------------------------------------------- */

/* What a worktree's HEAD file says. */
static void
git_worktree_head (git_context *ctx, const char *git_dir, struct git_worktree *out)
{
    char path[4096], line[4096];
    out->head[0] = out->branch[0] = '\0';
    if (snprintf (path, sizeof path, "%s/HEAD", git_dir) >= (int) sizeof path)
        return;
    FILE *file = fopen (path, "r");
    if (!file) return;
    if (fgets (line, sizeof line, file)) {
        size_t len = strlen (line);
        while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (!strncmp (line, "ref: ", 5)) {
            snprintf (out->branch, sizeof out->branch, "%s", line + 5);
            char id[41];
            if (bgit_ref_read (&ctx->repo, out->branch, id) == 0)
                memcpy (out->head, id, 41);
        } else if (strlen (line) >= 40) {
            memcpy (out->head, line, 40);
            out->head[40] = '\0';
        }
    }
    fclose (file);
}

/* Every worktree of this repository: the main one first, then the linked
   ones in name order, as git lists them. */
static int
git_worktrees (git_context *ctx, struct git_worktree **out, size_t *n_out)
{
    struct git_worktree *list = calloc (64, sizeof *list);
    if (!list) return -1;
    size_t n = 0;

    /* The main worktree is the one whose git directory is the common one. */
    struct git_worktree *main_tree = &list[n++];
    main_tree->admin[0] = '\0';
    snprintf (main_tree->name, sizeof main_tree->name, "%s", "");
    char main_work[4096] = "";
    if (ctx->repo.work_tree && !strcmp (ctx->repo.git_dir, ctx->repo.common_dir))
        snprintf (main_work, sizeof main_work, "%s", ctx->repo.work_tree);
    else {
        /* Started from a linked worktree: the main one is beside the common
           directory. */
        snprintf (main_work, sizeof main_work, "%s", ctx->repo.common_dir);
        char *slash = strrchr (main_work, '/');
        if (slash) *slash = '\0';
    }
    snprintf (main_tree->path, sizeof main_tree->path, "%s", main_work);
    git_worktree_head (ctx, ctx->repo.common_dir, main_tree);

    char dir[4096];
    if (snprintf (dir, sizeof dir, "%s/worktrees", ctx->repo.common_dir) <
        (int) sizeof dir) {
        DIR *handle = opendir (dir);
        if (handle) {
            char names[64][256];
            size_t n_names = 0;
            struct dirent *entry;
            while ((entry = readdir (handle)) && n_names < 64) {
                if (entry->d_name[0] == '.') continue;
                snprintf (names[n_names++], sizeof names[0], "%s", entry->d_name);
            }
            closedir (handle);
            qsort (names, n_names, sizeof names[0], (int (*) (const void *,
                   const void *)) strcmp);
            for (size_t i = 0; i < n_names && n < 64; i++) {
                struct git_worktree *tree = &list[n];
                snprintf (tree->name, sizeof tree->name, "%s", names[i]);
                snprintf (tree->admin, sizeof tree->admin, "%s/%s", dir, names[i]);
                char gitdir[4096], line[4096];
                snprintf (gitdir, sizeof gitdir, "%s/gitdir", tree->admin);
                FILE *file = fopen (gitdir, "r");
                if (!file) continue;
                if (!fgets (line, sizeof line, file)) { fclose (file); continue; }
                fclose (file);
                size_t len = strlen (line);
                while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
                    line[--len] = '\0';
                /* The file names the worktree's .git; the tree is above it. */
                char *slash = strrchr (line, '/');
                if (slash) *slash = '\0';
                snprintf (tree->path, sizeof tree->path, "%s", line);
                git_worktree_head (ctx, tree->admin, tree);
                n++;
            }
        }
    }
    *out = list;
    *n_out = n;
    return 0;
}

/* Which worktree, if any, has this branch checked out. */
static const struct git_worktree *
git_worktree_holding (const struct git_worktree *list, size_t n, const char *ref)
{
    for (size_t i = 0; i < n; i++)
        if (!strcmp (list[i].branch, ref)) return &list[i];
    return NULL;
}

/* An absolute path for one that may not exist yet. */
static int
git_absolute (const char *path, char *out, size_t outsz)
{
    if (*path == '/') {
        snprintf (out, outsz, "%s", path);
        return 0;
    }
    char here[4096];
    if (!getcwd (here, sizeof here)) return -1;
    if (snprintf (out, outsz, "%s/%s", here, path) >= (int) outsz) return -1;
    /* Fold away "." and ".." so the path reads as git writes it. */
    char parts[64][256];
    size_t n = 0;
    char copy[4096];
    snprintf (copy, sizeof copy, "%s", out);
    for (char *token = strtok (copy, "/"); token; token = strtok (NULL, "/")) {
        if (!strcmp (token, ".")) continue;
        if (!strcmp (token, "..")) { if (n) n--; continue; }
        if (n < 64) snprintf (parts[n++], sizeof parts[0], "%s", token);
    }
    size_t at = 0;
    out[0] = '\0';
    for (size_t i = 0; i < n; i++)
        at += (size_t) snprintf (out + at, outsz - at, "/%s", parts[i]);
    if (!at) snprintf (out, outsz, "/");
    return 0;
}

static int
git_worktree_add (git_context *ctx, const char *where, const char *start,
                  const char *new_branch, int detach, int force)
{
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    char path[4096];
    if (git_absolute (where, path, sizeof path) < 0) {
        git_state_release (&state);
        return git_fatal ("cannot work out where '%s' is", where);
    }
    const char *base = strrchr (path, '/');
    base = base ? base + 1 : path;
    char name[256];
    snprintf (name, sizeof name, "%s", base);

    /* What will be checked out, and under what name. */
    char branch_ref[4096] = "", id[41], commit[41];
    int creating = 0;
    if (new_branch) {
        snprintf (branch_ref, sizeof branch_ref, "refs/heads/%s", new_branch);
        creating = 1;
    } else if (start) {
        char candidate[4096];
        snprintf (candidate, sizeof candidate, "refs/heads/%s", start);
        if (!detach && bgit_ref_read (&ctx->repo, candidate, id) == 0)
            snprintf (branch_ref, sizeof branch_ref, "%s", candidate);
    } else if (!detach) {
        snprintf (branch_ref, sizeof branch_ref, "refs/heads/%s", name);
        creating = 1;
    }
    const char *from = start ? start : "HEAD";
    if (git_resolve (ctx, from, id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, commit) < 0) {
        git_state_release (&state);
        return git_fatal ("invalid reference: %s", from);
    }

    /* git says what it is preparing on stderr, and where HEAD landed on
       stdout. */
    fflush (stdout);
    if (*branch_ref) {
        const char *shown = branch_ref + 11;
        fprintf (stderr, "Preparing worktree (%s '%s')\n",
                 creating ? "new branch" : "checking out", shown);
    } else {
        char abbreviated[41];
        git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
        fprintf (stderr, "Preparing worktree (detached HEAD %s)\n", abbreviated);
    }

    struct git_worktree *trees = NULL;
    size_t n_trees = 0;
    if (git_worktrees (ctx, &trees, &n_trees) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    const struct git_worktree *holder = *branch_ref
        ? git_worktree_holding (trees, n_trees, branch_ref) : NULL;
    if (holder && !force) {
        char held[4096];
        snprintf (held, sizeof held, "%s", holder->path);
        free (trees);
        git_state_release (&state);
        return git_fatal ("'%s' is already used by worktree at '%s'",
                          branch_ref + 11, held);
    }
    for (size_t i = 0; i < n_trees; i++)
        if (!strcmp (trees[i].path, path)) {
            free (trees);
            git_state_release (&state);
            return git_fatal ("'%s' already exists", where);
        }
    free (trees);

    /* The administrative directory, then the worktree itself. */
    char admin[4096];
    if (snprintf (admin, sizeof admin, "%s/worktrees/%s", ctx->repo.common_dir,
                  name) >= (int) sizeof admin) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    char worktrees_dir[4096];
    snprintf (worktrees_dir, sizeof worktrees_dir, "%s/worktrees",
              ctx->repo.common_dir);
    if ((mkdir (worktrees_dir, 0777) < 0 && errno != EEXIST) ||
        (mkdir (admin, 0777) < 0 && errno != EEXIST) ||
        (mkdir (path, 0777) < 0 && errno != EEXIST)) {
        git_state_release (&state);
        return git_fatal ("cannot create '%s': %s", where, strerror (errno));
    }

    char file[4096], content[8192];
    FILE *out;
    snprintf (file, sizeof file, "%s/.git", path);
    out = fopen (file, "w");
    if (!out) { git_state_release (&state); return GIT_EXIT_FATAL; }
    fprintf (out, "gitdir: %s\n", admin);
    fclose (out);

    snprintf (file, sizeof file, "%s/gitdir", admin);
    out = fopen (file, "w");
    if (!out) { git_state_release (&state); return GIT_EXIT_FATAL; }
    fprintf (out, "%s/.git\n", path);
    fclose (out);

    snprintf (file, sizeof file, "%s/commondir", admin);
    out = fopen (file, "w");
    if (!out) { git_state_release (&state); return GIT_EXIT_FATAL; }
    fprintf (out, "../..\n");
    fclose (out);

    if (creating) {
        char message[1200];
        snprintf (message, sizeof message, "branch: Created from %s", from);
        if (bgit_ref_update (&ctx->repo, branch_ref, commit, "", message) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
    }
    snprintf (file, sizeof file, "%s/HEAD", admin);
    out = fopen (file, "w");
    if (!out) { git_state_release (&state); return GIT_EXIT_FATAL; }
    if (*branch_ref) fprintf (out, "ref: %s\n", branch_ref);
    else fprintf (out, "%s\n", commit);
    fclose (out);

    snprintf (file, sizeof file, "%s/ORIG_HEAD", admin);
    out = fopen (file, "w");
    if (out) { fprintf (out, "%s\n", commit); fclose (out); }

    /* Check the tree out into the new worktree, and write its index. */
    bgit_repo linked;
    memset (&linked, 0, sizeof linked);
    linked.git_dir = strdup (admin);
    linked.common_dir = strdup (ctx->repo.common_dir);
    linked.work_tree = strdup (path);
    if (!linked.git_dir || !linked.common_dir || !linked.work_tree) {
        bgit_repo_release (&linked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    /* The new worktree's own HEAD log starts the way git starts it: the
       entry that created HEAD, then the checkout that filled the tree. */
    bgit_reflog_append (&linked, "HEAD", NULL, commit, "");
    bgit_reflog_append (&linked, "HEAD", commit, commit, "reset: moving to HEAD");

    char tree[41];
    bgit_index_entry *entries = NULL;
    size_t n_entries = 0;
    int status = 0;
    if (bgit_commit_tree (&ctx->odb, commit, tree) < 0 ||
        bgit_checkout_tree (&linked, &ctx->odb, tree, &entries, &n_entries, 1,
                            NULL) < 0)
        status = GIT_EXIT_FATAL;
    if (!status) {
        char index_path[4096];
        snprintf (index_path, sizeof index_path, "%s/index", admin);
        if (n_entries > 1)
            qsort (entries, n_entries, sizeof *entries, bgit_index_path_cmp);
        if (bgit_index_write (index_path, entries, n_entries) < 0)
            status = GIT_EXIT_FATAL;
    }
    bgit_index_free_entries (entries, n_entries);
    bgit_repo_release (&linked);

    if (!status) {
        char abbreviated[41], subject[1024] = "";
        git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
        struct git_commit parsed;
        if (git_commit_read (ctx, commit, &parsed) == 0) {
            git_subject (&parsed, subject, sizeof subject);
            git_commit_release (&parsed);
        }
        printf ("HEAD is now at %s %s\n", abbreviated, subject);
    }
    (void) content;
    git_state_release (&state);
    return status;
}

static int
git_worktree_remove (git_context *ctx, const char *where, int force)
{
    char path[4096];
    if (git_absolute (where, path, sizeof path) < 0)
        return git_fatal ("cannot work out where '%s' is", where);
    struct git_worktree *trees = NULL;
    size_t n_trees = 0;
    if (git_worktrees (ctx, &trees, &n_trees) < 0) return GIT_EXIT_FATAL;
    const struct git_worktree *found = NULL;
    for (size_t i = 1; i < n_trees; i++)
        if (!strcmp (trees[i].path, path)) found = &trees[i];
    if (!found) {
        free (trees);
        return git_fatal ("'%s' is not a working tree", where);
    }
    char admin[4096];
    snprintf (admin, sizeof admin, "%s", found->admin);
    free (trees);
    (void) force;
    if (git_remove_path (path) < 0 || git_remove_path (admin) < 0)
        return git_fatal ("cannot remove '%s'", where);
    return 0;
}

static int
git_cmd_worktree (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git worktree add [-b <branch>] [--detach] [-f] "
                        "<path> [<commit>] | list [--porcelain] | "
                        "remove [-f] <path> | prune";
    const char *verb = NULL, *where = NULL, *start = NULL, *new_branch = NULL;
    int porcelain = 0, detach = 0, force = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!verb) { verb = w; continue; }
        if (!strcmp (w, "--porcelain")) porcelain = 1;
        else if (!strcmp (w, "--detach")) detach = 1;
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (!strcmp (w, "-b") && p->next) { new_branch = p->next->word->word; p = p->next; }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!where) where = w;
        else if (!start) start = w;
        else return git_usage (usage);
    }
    if (!verb) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;

    if (!strcmp (verb, "list")) {
        struct git_worktree *trees = NULL;
        size_t n = 0;
        if (git_worktrees (ctx, &trees, &n) < 0) return GIT_EXIT_FATAL;
        size_t width = 0;
        for (size_t i = 0; i < n; i++) {
            size_t len = strlen (trees[i].path);
            if (len > width) width = len;
        }
        for (size_t i = 0; i < n; i++) {
            char abbreviated[41];
            git_abbrev (ctx, trees[i].head, 7, abbreviated, sizeof abbreviated);
            if (porcelain) {
                printf ("worktree %s\n", trees[i].path);
                printf ("HEAD %s\n", trees[i].head);
                if (*trees[i].branch) printf ("branch %s\n", trees[i].branch);
                else printf ("detached\n");
                printf ("\n");
            } else if (*trees[i].branch) {
                const char *shown = trees[i].branch;
                if (!strncmp (shown, "refs/heads/", 11)) shown += 11;
                printf ("%-*s  %s [%s]\n", (int) width, trees[i].path,
                        abbreviated, shown);
            } else {
                printf ("%-*s  %s (detached HEAD)\n", (int) width,
                        trees[i].path, abbreviated);
            }
        }
        free (trees);
        return 0;
    }
    if (!strcmp (verb, "add")) {
        if (!where) return git_usage (usage);
        return git_worktree_add (ctx, where, start, new_branch, detach, force);
    }
    if (!strcmp (verb, "remove")) {
        if (!where) return git_usage (usage);
        return git_worktree_remove (ctx, where, force);
    }
    if (!strcmp (verb, "prune")) {
        /* An administrative directory whose worktree is gone goes too. */
        struct git_worktree *trees = NULL;
        size_t n = 0;
        if (git_worktrees (ctx, &trees, &n) < 0) return GIT_EXIT_FATAL;
        for (size_t i = 1; i < n; i++) {
            struct stat st;
            if (lstat (trees[i].path, &st) == 0) continue;
            git_remove_path (trees[i].admin);
        }
        free (trees);
        return 0;
    }
    return git_usage (usage);
}

/* ---- rebase ------------------------------------------------------------ */

/* A rebase that stops keeps its state in .git/rebase-merge, in the files
   git keeps it in and under the same names, so `git status` reads it back
   the same way whichever implementation wrote it. */
static int
git_rebase_path (git_context *ctx, const char *name, char *out, size_t outsz)
{
    return snprintf (out, outsz, "%s/rebase-merge%s%s", ctx->repo.git_dir,
                     *name ? "/" : "", name) >= (int) outsz ? -1 : 0;
}

static int
git_rebase_write (git_context *ctx, const char *name, const char *content)
{
    char path[4096];
    if (git_rebase_path (ctx, name, path, sizeof path) < 0) return -1;
    FILE *file = fopen (path, "w");
    if (!file) return -1;
    fputs (content, file);
    return fclose (file) == 0 ? 0 : -1;
}

/* One line of a state file, without its newline. */
static int
git_rebase_read (git_context *ctx, const char *name, char *out, size_t outsz)
{
    char path[4096];
    if (git_rebase_path (ctx, name, path, sizeof path) < 0) return -1;
    FILE *file = fopen (path, "r");
    if (!file) return -1;
    out[0] = '\0';
    if (!fgets (out, (int) outsz, file)) { fclose (file); return -1; }
    fclose (file);
    size_t len = strlen (out);
    while (len && (out[len - 1] == '\n' || out[len - 1] == '\r')) out[--len] = '\0';
    return 0;
}

/* Every line of one of the todo files, comments and blanks left out. */
static int
git_rebase_list (git_context *ctx, const char *name, char lines[][1200], int max)
{
    char path[4096];
    if (git_rebase_path (ctx, name, path, sizeof path) < 0) return 0;
    FILE *file = fopen (path, "r");
    if (!file) return 0;
    int n = 0;
    char line[1200];
    while (n < max && fgets (line, sizeof line, file)) {
        size_t len = strlen (line);
        while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (!*line || *line == '#') continue;
        snprintf (lines[n++], 1200, "%s", line);
    }
    fclose (file);
    return n;
}

static int
git_rebase_in_progress (git_context *ctx)
{
    char path[4096];
    struct stat st;
    return git_rebase_path (ctx, "", path, sizeof path) == 0 &&
           lstat (path, &st) == 0 && S_ISDIR (st.st_mode);
}

static void
git_rebase_clear (git_context *ctx)
{
    static const char *const names[] = {
        "head-name", "onto", "orig-head", "msgnum", "end", "done",
        "git-rebase-todo", "interactive", "message", "stopped-sha", "amend",
        "update-refs", NULL
    };
    char path[4096];
    for (int i = 0; names[i]; i++)
        if (git_rebase_path (ctx, names[i], path, sizeof path) == 0)
            unlink (path);
    if (git_rebase_path (ctx, "", path, sizeof path) == 0) rmdir (path);
    git_remove_state_file (ctx, "REBASE_HEAD");
}

/* Write a message for a commit a rebase is making: the one it has to
   start from, and with COMBINING the message of what is being melded into
   it, under git's note about the two. Returns the message the editor left,
   for the caller to free, or NULL when it came back empty. */
static char *
git_rebase_message_edit (git_context *ctx, struct git_state *state,
                         const char *first, const char *second, int combining,
                         const char *author)
{
    char path[4096];
    if (snprintf (path, sizeof path, "%s/COMMIT_EDITMSG", ctx->repo.git_dir) >=
        (int) sizeof path)
        return NULL;
    FILE *out = fopen (path, "w");
    if (!out) return NULL;
    if (combining) {
        fprintf (out, "# This is a combination of 2 commits.\n"
                      "# This is the 1st commit message:\n\n%s", first);
        if (*first && first[strlen (first) - 1] != '\n') fprintf (out, "\n");
        fprintf (out, "\n# This is the commit message #2:\n\n%s", second);
        if (*second && second[strlen (second) - 1] != '\n') fprintf (out, "\n");
    } else {
        fprintf (out, "%s", first);
        if (*first && first[strlen (first) - 1] != '\n') fprintf (out, "\n");
    }
    char committer[1024] = "";
    bgit_ident (&ctx->cfg, 1, committer, sizeof committer);
    git_commit_template (ctx, out, state, author, committer, 1, !combining);
    fclose (out);
    if (git_edit_file (ctx, path, 0) < 0) return NULL;
    size_t len = 0;
    char *written = git_message_body (path, &len);
    if (!written || !len) {
        free (written);
        return NULL;
    }
    return written;
}

/* Put the commit HEAD points at back with a different message, or with a
   different parent, which is what reword and a melded commit both end in.
   The tree is whatever the index holds now. Returns 0, or -1. */
static int
git_rebase_replace_head (git_context *ctx, struct git_state *state,
                         const char *parent, const char *author,
                         const char *message, const char *reflog, int quiet)
{
    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state->index,
                         state->n_index, tree) < 0)
        return -1;
    char committer[1024];
    if (bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0)
        return -1;
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) return -1;
    fprintf (builder, "tree %s\n", tree);
    if (parent && *parent) fprintf (builder, "parent %s\n", parent);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    fprintf (builder, "\n%s", message);
    size_t message_len = strlen (message);
    if (!message_len || message[message_len - 1] != '\n')
        fprintf (builder, "\n");
    fclose (builder);
    char written[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1,
                                written);
    free (body);
    if (rc < 0) return -1;

    char subject[1024] = "";
    const char *nl = strchr (message, '\n');
    snprintf (subject, nl ? (size_t) (nl - message) + 1 : sizeof subject, "%s",
              message);
    char before[41] = "";
    if (parent && *parent) bgit_commit_tree (&ctx->odb, parent, before);
    if (git_head_detach (ctx, state, written, reflog) < 0) return -1;
    memcpy (state->head, written, 41);
    memcpy (state->head_tree, tree, 41);
    if (!quiet) {
        char abbreviated[41];
        git_abbrev (ctx, written, 7, abbreviated, sizeof abbreviated);
        printf ("[detached HEAD %s] %s\n", abbreviated, subject);
        char author_who[1024], committer_who[1024];
        git_ident_who (author, author_who, sizeof author_who);
        git_ident_who (committer, committer_who, sizeof committer_who);
        if (strcmp (author_who, committer_who))
            printf (" Author: %s\n", author_who);
        const char *stamp = strrchr (author, '>');
        if (stamp) {
            char shown[128];
            git_format_date (stamp + 2, 0, shown, sizeof shown);
            printf (" Date: %s\n", shown);
        }
        struct git_diff_format format;
        git_diff_format_init (&format);
        format.shortstat = 1;
        format.summary = 1;
        bgit_diff_entry *entries = NULL;
        size_t n_entries = 0;
        if (bgit_diff_trees (&ctx->odb, *before ? before : NULL, tree,
                             &entries, &n_entries) == 0) {
            git_diff_emit (ctx, stdout, &format, entries, n_entries, 0, "");
            bgit_diff_free (entries, n_entries);
        }
    }
    return 0;
}

/* Where a label points: a rebase keeps them as refs, and deletes them
   when it is done. */
static int
git_rebase_label_read (git_context *ctx, const char *name, char out[41])
{
    char ref[4096];
    if (snprintf (ref, sizeof ref, "refs/rewritten/%s", name) >=
        (int) sizeof ref)
        return -1;
    /* A ref that is not there is answered with 1, not with a failure. */
    return bgit_ref_read (&ctx->repo, ref, out) == 0 ? 0 : -1;
}

static int git_merge_report (FILE *out, const bgit_merge_path *paths,
                             size_t n_paths, const char *label);

static void
git_rebase_labels_clear (git_context *ctx)
{
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    if (bgit_refs_list (&ctx->repo, "refs/rewritten/", &refs, &n_refs) < 0)
        return;
    for (size_t i = 0; i < n_refs; i++)
        bgit_ref_delete (&ctx->repo, refs[i].name, NULL, NULL);
    bgit_refs_free (refs, n_refs);
}

/* label, reset and merge: the three a rebase that keeps its merges is
   written with. Returns 0 when it settled, 1 when it stopped, -1 on
   failure. */
static int
git_rebase_marked (git_context *ctx, struct git_state *state, const char *verb,
                   const char *name, const char *rest, char *action,
                   size_t action_size, char stopped[41], char *arg,
                   size_t arg_size)
{
    if (!strcmp (verb, "label")) {
        char ref[4096];
        if (!*name ||
            snprintf (ref, sizeof ref, "refs/rewritten/%s", name) >=
            (int) sizeof ref)
            return git_fatal ("cannot read the rebase todo list") < 0 ? -1 : -1;
        return bgit_ref_update (&ctx->repo, ref, state->head, NULL, NULL) < 0
               ? -1 : 0;
    }

    if (!strcmp (verb, "reset")) {
        char target[41];
        if (!*name) return -1;
        if (git_rebase_label_read (ctx, name, target) < 0 &&
            git_resolve (ctx, name, target, NULL) < 0) {
            git_fatal ("could not resolve '%s'", name);
            return -1;
        }
        /* Coming back to where HEAD already stands is nothing at all, and
           git leaves no line in the reflog for it. */
        snprintf (action, action_size, "rebase (reset): '%s'", name);
        if (!strcmp (target, state->head)) return 0;
        char tree[41];
        char reflog[1200];
        snprintf (reflog, sizeof reflog, "rebase (reset): '%s'", name);
        if (bgit_commit_tree (&ctx->odb, target, tree) < 0 ||
            bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state->index,
                                &state->n_index, 1, NULL) < 0 ||
            git_index_store (ctx, state->index, state->n_index) < 0 ||
            git_head_detach (ctx, state, target, reflog) < 0)
            return -1;
        memcpy (state->head, target, 41);
        memcpy (state->head_tree, tree, 41);
        return 0;
    }

    /* merge [-C <commit>] <label> [# <oneline>] — the commit named by -C is
       where the message comes from, and the label is what is merged in. */
    char original[41] = "", label[256] = "";
    const char *at = rest;
    while (*at) {
        while (*at == ' ' || *at == '\t') at++;
        if (!*at || *at == '#') break;
        size_t len = strcspn (at, " \t");
        char word[256];
        if (len >= sizeof word) return -1;
        memcpy (word, at, len);
        word[len] = '\0';
        at += len;
        if ((!strcmp (word, "-C") || !strcmp (word, "-c")) && *at) {
            while (*at == ' ' || *at == '\t') at++;
            size_t id_len = strcspn (at, " \t");
            char id[256];
            if (id_len >= sizeof id) return -1;
            memcpy (id, at, id_len);
            id[id_len] = '\0';
            at += id_len;
            if (git_resolve (ctx, id, original, NULL) < 0) {
                git_fatal ("could not resolve '%s'", id);
                return -1;
            }
            continue;
        }
        snprintf (label, sizeof label, "%s", word);
    }
    if (!*label) {
        git_fatal ("cannot read the rebase todo list");
        return -1;
    }
    char theirs[41], shown_label[320];
    snprintf (shown_label, sizeof shown_label, "%s", label);
    if (git_rebase_label_read (ctx, label, theirs) == 0)
        snprintf (shown_label, sizeof shown_label, "refs/rewritten/%s", label);
    else if (git_resolve (ctx, label, theirs, NULL) < 0) {
        git_fatal ("could not resolve '%s'", label);
        return -1;
    }

    /* A merge that would come out as the one it is replaying is that one:
       git moves to it rather than making another. */
    if (*original) {
        char parents[BGIT_MAX_PARENTS][41];
        int n_parents = bgit_commit_parents (&ctx->odb, original, parents,
                                             BGIT_MAX_PARENTS);
        if (n_parents == 2 && !strcmp (parents[0], state->head) &&
            !strcmp (parents[1], theirs)) {
            char tree[41];
            if (bgit_commit_tree (&ctx->odb, original, tree) < 0 ||
                bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state->index,
                                    &state->n_index, 0, NULL) < 0 ||
                git_index_store (ctx, state->index, state->n_index) < 0 ||
                git_head_detach (ctx, state, original,
                                 "rebase: fast-forward") < 0)
                return -1;
            memcpy (state->head, original, 41);
            memcpy (state->head_tree, tree, 41);
            return 0;
        }
    }

    /* Otherwise it is a merge like any other, held against whatever base
       the two sides have — made up from several, where there are several. */
    char (*bases)[41] = NULL;
    size_t n_bases = 0;
    const char *twos[1] = { theirs };
    if (bgit_merge_bases_many (&ctx->odb, state->head, twos, 1, &bases,
                               &n_bases) < 0)
        return -1;
    char base_tree[41] = "";
    int have_base = n_bases && git_base_tree (ctx, bases, n_bases,
                                              base_tree) == 0;
    free (bases);
    char our_tree[41], their_tree[41];
    if (bgit_commit_tree (&ctx->odb, state->head, our_tree) < 0 ||
        bgit_commit_tree (&ctx->odb, theirs, their_tree) < 0)
        return -1;
    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0],
                          have_base ? base_tree : NULL, our_tree, their_tree,
                          "HEAD", shown_label, &paths, &n_paths) < 0)
        return -1;
    char *said = NULL;
    size_t said_len = 0;
    FILE *saying = open_memstream (&said, &said_len);
    if (!saying) {
        bgit_merge_paths_free (paths, n_paths);
        return -1;
    }
    int conflicts = git_merge_report (saying, paths, n_paths, shown_label);
    fclose (saying);
    if (conflicts) fputs (said, stdout);
    free (said);
    if (git_merge_apply (ctx, state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        return -1;
    }
    bgit_merge_paths_free (paths, n_paths);
    /* The message, and who wrote it, are the merge's own: a replayed merge
       keeps its author and is only committed again. */
    char message[8192] = "", author[1024] = "";
    if (*original) {
        struct git_commit merging;
        if (git_commit_read (ctx, original, &merging) == 0) {
            snprintf (message, sizeof message, "%s", merging.message);
            snprintf (author, sizeof author, "%s <%s> %s", merging.author_name,
                      merging.author_email, merging.author_date);
            git_commit_release (&merging);
        }
    }
    if (!*message) snprintf (message, sizeof message, "Merge %s\n", label);
    char subject[1024];
    {
        const char *end = strchr (message, '\n');
        snprintf (subject, end ? (size_t) (end - message) + 1 : sizeof subject,
                  "%s", message);
    }

    if (conflicts) {
        /* Where it stopped, so that taking it up again can finish the
           merge rather than make a plain commit of it. */
        char content[8192];
        snprintf (content, sizeof content, "%s\n", theirs);
        git_write_state_file (ctx, "MERGE_HEAD", content);
        git_write_state_file (ctx, "MERGE_MODE", "no-ff\n");
        snprintf (content, sizeof content, "%s", message);
        git_write_state_file (ctx, "MERGE_MSG", content);
        git_rebase_write (ctx, "message", content);
        if (*original) memcpy (stopped, original, 41);
        /* git says what could not be applied in the words of the todo line
           itself, with what stands after the commit it named. */
        const char *shown = rest;
        if (!strncmp (shown, "-C ", 3) || !strncmp (shown, "-c ", 3)) {
            shown += 3;
            while (*shown == ' ') shown++;
            shown += strcspn (shown, " \t");
            while (*shown == ' ') shown++;
        }
        snprintf (arg, arg_size, "%s", shown);
        return 1;
    }

    char tree[41], committer[1024];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state->index,
                         state->n_index, tree) < 0 ||
        (!*author && bgit_ident (&ctx->cfg, 0, author, sizeof author) < 0) ||
        bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0)
        return -1;
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) return -1;
    fprintf (builder, "tree %s\nparent %s\nparent %s\nauthor %s\n"
                      "committer %s\n\n%s", tree, state->head, theirs, author,
             committer, message);
    if (!*message || message[strlen (message) - 1] != '\n')
        fprintf (builder, "\n");
    fclose (builder);
    char written[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1,
                                written);
    free (body);
    if (rc < 0) return -1;
    /* A merge is committed like any other commit, under whatever the last
       command left as the reason — which is what git's reflog shows. */
    char reflog[1400];
    snprintf (reflog, sizeof reflog, "%s: %s", action, subject);
    if (git_head_detach (ctx, state, written, reflog) < 0) return -1;
    memcpy (state->head, written, 41);
    memcpy (state->head_tree, tree, 41);
    return 0;
}

static int git_rebase_todo_parse (const char *line, char *command,
                                  size_t command_size, char *name,
                                  size_t name_size, const char **rest);
static const char *git_rebase_command (const char *word);

/* A todo line names commits, and the two readers of it want different
   names: what is written down for taking the rebase up again names them in
   full, while what is shown names them short. FULL says which. */
static void
git_rebase_line_render (git_context *ctx, const char *line, int full,
                        char *out, size_t size)
{
    char command[32], name[64];
    const char *rest = "";
    snprintf (out, size, "%s", line);
    if (!git_rebase_todo_parse (line, command, sizeof command, name,
                                sizeof name, &rest))
        return;
    const char *verb = git_rebase_command (command);
    if (!verb) return;
    char id[41], shown[41];

    /* A merge names the commit it is replaying after -C, and that one is
       written in full either way. */
    if (!strcmp (verb, "merge")) {
        if (!full || (strncmp (rest, "-C ", 3) && strncmp (rest, "-c ", 3)))
            return;
        const char *at = rest + 3;
        while (*at == ' ') at++;
        size_t len = strcspn (at, " \t");
        char named[128];
        if (len >= sizeof named) return;
        memcpy (named, at, len);
        named[len] = '\0';
        if (git_resolve (ctx, named, id, NULL) == 0)
            snprintf (out, size, "%s %.2s %s%s", command, rest, id, at + len);
        return;
    }

    if (strcmp (verb, "pick") && strcmp (verb, "reword") &&
        strcmp (verb, "edit") && strcmp (verb, "squash") &&
        strcmp (verb, "fixup"))
        return;
    if (!*name || git_resolve (ctx, name, id, NULL) < 0) return;
    if (!full) git_abbrev (ctx, id, 7, shown, sizeof shown);
    snprintf (out, size, "%s %s%s", command, full ? id : shown,
              rest + strlen (name));
}

/* The branches a rebase is carrying along, written down as it goes: a
   name, where it was, and where it has got to — nothing until the command
   for it runs, and applied when the rebase is done. git keeps the same
   three lines for each in .git/rebase-merge/update-refs. */
static int
git_rebase_refs_read (git_context *ctx, char (*names)[4096], char (*was)[41],
                      char (*now)[41], int max)
{
    char path[4096];
    if (git_rebase_path (ctx, "update-refs", path, sizeof path) < 0) return 0;
    FILE *file = fopen (path, "r");
    if (!file) return 0;
    int n = 0;
    char line[4096];
    while (n < max && fgets (line, sizeof line, file)) {
        size_t len = strlen (line);
        while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (!*line) continue;
        snprintf (names[n], 4096, "%s", line);
        if (!fgets (line, sizeof line, file)) break;
        snprintf (was[n], 41, "%.40s", line);
        if (!fgets (line, sizeof line, file)) break;
        snprintf (now[n], 41, "%.40s", line);
        n++;
    }
    fclose (file);
    return n;
}

static void
git_rebase_refs_write (git_context *ctx, char (*names)[4096], char (*was)[41],
                       char (*now)[41], int n)
{
    /* By name, which is the order git keeps them in and lists them in. */
    for (int i = 1; i < n; i++)
        for (int k = i; k > 0 && strcmp (names[k - 1], names[k]) > 0; k--) {
            char name[4096], one[41], two[41];
            memcpy (name, names[k - 1], sizeof name);
            memcpy (names[k - 1], names[k], sizeof name);
            memcpy (names[k], name, sizeof name);
            memcpy (one, was[k - 1], 41);
            memcpy (was[k - 1], was[k], 41);
            memcpy (was[k], one, 41);
            memcpy (two, now[k - 1], 41);
            memcpy (now[k - 1], now[k], 41);
            memcpy (now[k], two, 41);
        }
    char content[65536];
    size_t at = 0;
    content[0] = '\0';
    for (int i = 0; i < n && at < sizeof content; i++)
        at += (size_t) snprintf (content + at, sizeof content - at,
                                 "%s\n%s\n%s\n", names[i], was[i], now[i]);
    git_rebase_write (ctx, "update-refs", content);
}

/* Every branch a todo list says to carry along, written down before the
   rebase starts so that a stop and a later continue still know them. */
static void
git_rebase_refs_start (git_context *ctx, char todo[][1200], int n_todo)
{
    char (*names)[4096] = calloc (n_todo ? n_todo : 1, sizeof *names);
    char (*was)[41] = calloc (n_todo ? n_todo : 1, sizeof *was);
    char (*now)[41] = calloc (n_todo ? n_todo : 1, sizeof *now);
    if (!names || !was || !now) {
        free (names); free (was); free (now);
        return;
    }
    int n = 0;
    for (int i = 0; i < n_todo; i++) {
        char command[32], name[64];
        const char *rest = "";
        if (!git_rebase_todo_parse (todo[i], command, sizeof command, name,
                                    sizeof name, &rest))
            continue;
        const char *verb = git_rebase_command (command);
        if (!verb || strcmp (verb, "update-ref") || !*name) continue;
        char full[41];
        snprintf (names[n], sizeof names[0], "%s", name);
        snprintf (was[n], 41, "%s",
                  bgit_ref_read (&ctx->repo, name, full) == 0 ? full : "");
        if (!*was[n])
            snprintf (was[n], 41, "%040d", 0);
        snprintf (now[n], 41, "%040d", 0);
        n++;
    }
    if (n) git_rebase_refs_write (ctx, names, was, now, n);
    free (names); free (was); free (now);
}

/* One such branch reaching the place it will end up at. */
static void
git_rebase_refs_mark (git_context *ctx, const char *name, const char *id)
{
    char (*names)[4096] = calloc (64, sizeof *names);
    char (*was)[41] = calloc (64, sizeof *was);
    char (*now)[41] = calloc (64, sizeof *now);
    if (!names || !was || !now) {
        free (names); free (was); free (now);
        return;
    }
    int n = git_rebase_refs_read (ctx, names, was, now, 64);
    int found = 0;
    for (int i = 0; i < n; i++)
        if (!strcmp (names[i], name)) {
            snprintf (now[i], 41, "%s", id);
            found = 1;
        }
    if (!found && n < 64) {
        snprintf (names[n], sizeof names[0], "%s", name);
        char full[41];
        snprintf (was[n], 41, "%s",
                  bgit_ref_read (&ctx->repo, name, full) == 0 ? full : "");
        if (!*was[n]) snprintf (was[n], 41, "%040d", 0);
        snprintf (now[n], 41, "%s", id);
        n++;
    }
    git_rebase_refs_write (ctx, names, was, now, n);
    free (names); free (was); free (now);
}

/* And all of them at the end, which is when git moves them. */
static void
git_rebase_refs_apply (git_context *ctx, int quiet)
{
    char (*names)[4096] = calloc (64, sizeof *names);
    char (*was)[41] = calloc (64, sizeof *was);
    char (*now)[41] = calloc (64, sizeof *now);
    if (!names || !was || !now) {
        free (names); free (was); free (now);
        return;
    }
    int n = git_rebase_refs_read (ctx, names, was, now, 64);
    int said = 0;
    for (int i = 0; i < n; i++) {
        if (!strcmp (now[i], "0000000000000000000000000000000000000000"))
            continue;
        if (bgit_ref_update (&ctx->repo, names[i], now[i], NULL,
                             "rewritten during rebase") < 0)
            continue;
        if (quiet) continue;
        if (!said) {
            fflush (stdout);
            fprintf (stderr, "Updated the following refs with "
                             "--update-refs:\n");
            said = 1;
        }
        fprintf (stderr, "\t%s\n", names[i]);
    }
    free (names); free (was); free (now);
}

/* What has been done and what is left, written down after every command,/* What has been done and what is left, written down after every command,/* What has been done and what is left, written down after every command,
   so that a rebase which stops can be taken up where it left off. */
static void
git_rebase_record (git_context *ctx, char done_lines[][1200], int *done_count,
                   char todo[][1200], int n_todo, int at_command,
                   char *content, size_t size)
{
    size_t at = 0;
    char written[1200];
    content[0] = '\0';
    for (int j = 0; j < *done_count && at < size; j++)
        at += (size_t) snprintf (content + at, size - at, "%s\n", done_lines[j]);
    git_rebase_line_render (ctx, todo[at_command], 1, written, sizeof written);
    at += (size_t) snprintf (content + at, size - at, "%s\n", written);
    git_rebase_write (ctx, "done", content);
    if (*done_count < 128)
        snprintf (done_lines[(*done_count)++], 1200, "%s", written);
    at = 0;
    content[0] = '\0';
    for (int j = at_command + 1; j < n_todo && at < size; j++) {
        git_rebase_line_render (ctx, todo[j], 1, written, sizeof written);
        at += (size_t) snprintf (content + at, size - at, "%s\n", written);
    }
    git_rebase_write (ctx, "git-rebase-todo", content);
}

/* Where the rebase is going and how far along it is: what --continue and
   status read to find their way back. */
static void
git_rebase_state_files (git_context *ctx, const char *head_name,
                        const char *onto, const char *orig, int done_count,
                        int total, char *content, size_t size)
{
    snprintf (content, size, "%s\n", head_name);
    git_rebase_write (ctx, "head-name", content);
    snprintf (content, size, "%s\n", onto);
    git_rebase_write (ctx, "onto", content);
    snprintf (content, size, "%s\n", orig);
    git_rebase_write (ctx, "orig-head", content);
    snprintf (content, size, "%d\n", done_count);
    git_rebase_write (ctx, "msgnum", content);
    snprintf (content, size, "%d\n", total);
    git_rebase_write (ctx, "end", content);
}

/* Run a command the way a todo list's `exec` asks for: through this
   build's own shell, so a machine with no other one can still rebase.
   Returns the command's status, or -1. */
static int
git_run_shell (const char *command)
{
    fflush (stdout);
    fflush (stderr);
    pid_t child = fork ();
    if (child < 0) return -1;
    if (!child) {
        git_restore_caller_pipe ();
        array_needs_making = 1;
        maybe_make_export_env ();
        const char *argv[6];
        int at = 0;
        argv[at++] = "bash";
        argv[at++] = "--noprofile";
        argv[at++] = "--norc";
        argv[at++] = "-c";
        argv[at++] = command;
        argv[at] = NULL;
        execve ("/proc/self/exe", (char *const *) argv, export_env);
        _exit (127);
    }
    int status = 0;
    while (waitpid (child, &status, 0) < 0 && errno == EINTR) ;
    return WIFEXITED (status) ? WEXITSTATUS (status) : -1;
}

/* The note git leaves under an interactive rebase's todo list. It is
   written out in full, since somebody is about to read it. */
static void
git_rebase_todo_note (FILE *out, git_context *ctx, const char *orig,
                      const char *last, const char *onto, int n_commands)
{
    char from[41], to[41], base[41];
    git_abbrev (ctx, orig, 7, from, sizeof from);
    git_abbrev (ctx, last, 7, to, sizeof to);
    git_abbrev (ctx, onto, 7, base, sizeof base);
    fprintf (out,
      "\n# Rebase %s..%s onto %s (%d command%s)\n"
      "#\n"
      "# Commands:\n"
      "# p, pick <commit> = use commit\n"
      "# r, reword <commit> = use commit, but edit the commit message\n"
      "# e, edit <commit> = use commit, but stop for amending\n"
      "# s, squash <commit> = use commit, but meld into previous commit\n"
      "# f, fixup [-C | -c] <commit> = like \"squash\" but keep only the previous\n"
      "#                    commit's log message, unless -C is used, in which case\n"
      "#                    keep only this commit's message; -c is same as -C but\n"
      "#                    opens the editor\n"
      "# x, exec <command> = run command (the rest of the line) using shell\n"
      "# b, break = stop here (continue rebase later with 'git rebase --continue')\n"
      "# d, drop <commit> = remove commit\n"
      "# l, label <label> = label current HEAD with a name\n"
      "# t, reset <label> = reset HEAD to a label\n"
      "# m, merge [-C <commit> | -c <commit>] <label> [# <oneline>]\n"
      "#         create a merge commit using the original merge commit's\n"
      "#         message (or the oneline, if no original merge commit was\n"
      "#         specified); use -c <commit> to reword the commit message\n"
      "# u, update-ref <ref> = track a placeholder for the <ref> to be updated\n"
      "#                       to this position in the new commits. The <ref> is\n"
      "#                       updated at the end of the rebase\n"
      "#\n"
      "# These lines can be re-ordered; they are executed from top to bottom.\n"
      "#\n"
      "# If you remove a line here THAT COMMIT WILL BE LOST.\n"
      "#\n"
      "# However, if you remove everything, the rebase will be aborted.\n"
      "#\n",
      from, to, base, n_commands, n_commands == 1 ? "" : "s");
}

/* What a todo line says: the command, the commit it names, and whatever
   else is on the line. Returns 0 for a line with nothing on it. */
static int
git_rebase_todo_parse (const char *line, char *command, size_t command_size,
                       char *name, size_t name_size, const char **rest)
{
    *command = '\0';
    *name = '\0';
    *rest = "";
    while (*line == ' ' || *line == '\t') line++;
    if (!*line || *line == '#') return 0;
    size_t len = strcspn (line, " \t");
    if (len >= command_size) len = command_size - 1;
    memcpy (command, line, len);
    command[len] = '\0';
    const char *after = line + strcspn (line, " \t");
    while (*after == ' ' || *after == '\t') after++;
    *rest = after;
    len = strcspn (after, " \t");
    if (len && len < name_size) {
        memcpy (name, after, len);
        name[len] = '\0';
    }
    return 1;
}

/* The full name of a todo command, whichever way it was written. */
static const char *
git_rebase_command (const char *word)
{
    static const char *const names[][2] = {
        { "p", "pick" }, { "r", "reword" }, { "e", "edit" },
        { "s", "squash" }, { "f", "fixup" }, { "x", "exec" },
        { "b", "break" }, { "d", "drop" },
        /* What a rebase that keeps the merges is written with. */
        { "l", "label" }, { "t", "reset" }, { "m", "merge" },
        /* And what one that carries the other branches along is. */
        { "u", "update-ref" },
        { NULL, NULL }
    };
    for (int i = 0; names[i][0]; i++)
        if (!strcmp (word, names[i][0]) || !strcmp (word, names[i][1]))
            return names[i][1];
    return NULL;
}

/* The line a rebase's todo list holds for one commit. */
static void
git_rebase_line (git_context *ctx, const char *commit, char *out, size_t outsz)
{
    char abbreviated[41], subject[1024] = "";
    git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
    struct git_commit parsed;
    if (git_commit_read (ctx, commit, &parsed) == 0) {
        git_subject (&parsed, subject, sizeof subject);
        git_commit_release (&parsed);
    }
    snprintf (out, outsz, "pick %s %s", abbreviated, subject);
}

/* git collects a history by date and then sets it in topological order, so
   that nothing stands before a commit it descends from. Reordered in
   place, newest first, the way git's own sort works it out: a stack of the
   commits nothing left in hand points at any more. Returns 0, or -1. */
static int
git_topo_order (git_context *ctx, char (*ids)[41], size_t n)
{
    if (n < 2) return 0;
    int *degree = calloc (n, sizeof *degree);
    size_t *stack = malloc (n * sizeof *stack);
    char (*sorted)[41] = malloc (n * sizeof *sorted);
    int *counts = calloc (n, sizeof *counts);
    char (*parents)[BGIT_MAX_PARENTS][41] =
        malloc (n * sizeof (char[BGIT_MAX_PARENTS][41]));
    if (!degree || !stack || !sorted || !counts || !parents) {
        free (degree); free (stack); free (sorted); free (counts);
        free (parents);
        return -1;
    }
    for (size_t i = 0; i < n; i++) {
        degree[i] = 1;
        counts[i] = bgit_commit_parents (&ctx->odb, ids[i], parents[i],
                                         BGIT_MAX_PARENTS);
    }
    /* How many of the commits in hand point at each one. */
    for (size_t i = 0; i < n; i++)
        for (int p = 0; p < counts[i]; p++)
            for (size_t j = 0; j < n; j++)
                if (!strcmp (ids[j], parents[i][p])) {
                    degree[j]++;
                    break;
                }
    size_t n_stack = 0, at = 0;
    for (size_t i = 0; i < n; i++)
        if (degree[i] == 1) stack[n_stack++] = i;
    while (n_stack) {
        size_t i = stack[--n_stack];
        memcpy (sorted[at++], ids[i], 41);
        for (int p = 0; p < counts[i]; p++)
            for (size_t j = 0; j < n; j++)
                if (!strcmp (ids[j], parents[i][p])) {
                    if (degree[j] && --degree[j] == 1 && n_stack < n)
                        stack[n_stack++] = j;
                    break;
                }
        degree[i] = 0;
    }
    if (at == n) memcpy (ids, sorted, n * sizeof *sorted);
    free (degree); free (stack); free (sorted); free (counts); free (parents);
    return 0;
}

/* A rebase that keeps its merges has to name things: the tip of a branch
   it will merge back in, and the commit a branch grew out of. The names
   become refs under refs/rewritten while the rebase runs, so what a todo
   list says can be pointed at before it has been made. */
typedef struct {
    char id[41];
    char name[256];
} git_rebase_label;

/* One commit on the way, and the line it was written on. */
typedef struct {
    char id[41];
    char parents[BGIT_MAX_PARENTS][41];
    int n_parents;
    char subject[1024];
    char line[1200];
    int emitted;
    int labelled;
    int at;
} git_rebase_step;

typedef struct {
    git_context *ctx;
    git_rebase_step *steps;
    size_t n_steps;
    git_rebase_label *labels;
    size_t n_labels, cap_labels;
    char (*lines)[1200];
    size_t n_lines, cap_lines;
    char onto[41];
    char (*forks)[41];      /* where the branch and its new base parted */
    size_t n_forks;
    int cousins;
    bgit_ref *heads;        /* the branches that may be carried along */
    size_t n_heads;
    const char *head_name;  /* the one being rebased, which is not */
} git_rebase_plan;

/* A name that can be a file, and so a ref: everything that is not a letter
   or a digit becomes a dash, and dashes do not double up or lead. Bytes
   above ASCII are left alone — they are as good in a file name as any. */
static void
git_label_clean (const char *from, char *out, size_t size)
{
    size_t len = 0;
    for (; *from && len + 1 < size; from++) {
        unsigned char ch = (unsigned char) *from;
        if ((ch & 0x80) || isalnum (ch)) out[len++] = (char) ch;
        else if (len && out[len - 1] != '-') out[len++] = '-';
    }
    out[len] = '\0';
}

/* The branch a merge commit's message names, which is what git calls the
   branch it replays. */
static void
git_label_from_subject (const char *subject, char *out, size_t size)
{
    const char *p1, *p2;
    if (!strncmp (subject, "Merge ", 6) && (p1 = strchr (subject + 6, '\'')) &&
        (p2 = strchr (p1 + 1, '\''))) {
        snprintf (out, size, "%.*s", (int) (p2 - p1 - 1), p1 + 1);
        return;
    }
    if (!strncmp (subject, "Merge pull request ", 19) &&
        (p1 = strstr (subject + 19, " from "))) {
        snprintf (out, size, "%s", p1 + 6);
        return;
    }
    snprintf (out, size, "%s", subject);
}

static const char *
git_label_of (git_rebase_plan *plan, const char *id)
{
    for (size_t i = 0; i < plan->n_labels; i++)
        if (!strcmp (plan->labels[i].id, id)) return plan->labels[i].name;
    return NULL;
}

static int
git_label_taken (git_rebase_plan *plan, const char *name)
{
    for (size_t i = 0; i < plan->n_labels; i++)
        if (!strcmp (plan->labels[i].name, name)) return 1;
    return 0;
}

/* Give a commit a name, or hand back the one it already has. WANT is what
   it should be called; without one — a commit this rebase does not touch —
   the short name of the commit itself will do. Two things cannot share a
   name, so a second comer gets a number. */
static const char *
git_label_take (git_rebase_plan *plan, const char *id, const char *want)
{
    const char *had = git_label_of (plan, id);
    if (had) return had;

    char base[256], name[256];
    if (want) git_label_clean (want, base, sizeof base);
    else git_abbrev (plan->ctx, id, 7, base, sizeof base);
    if (!*base) git_abbrev (plan->ctx, id, 7, base, sizeof base);
    snprintf (name, sizeof name, "%s", base);
    for (int n = 2; git_label_taken (plan, name); n++)
        snprintf (name, sizeof name, "%s-%d", base, n);

    if (plan->n_labels == plan->cap_labels) {
        size_t next = plan->cap_labels ? plan->cap_labels * 2 : 16;
        git_rebase_label *grown = realloc (plan->labels, next * sizeof *grown);
        if (!grown) return NULL;
        plan->labels = grown;
        plan->cap_labels = next;
    }
    memcpy (plan->labels[plan->n_labels].id, id, 41);
    snprintf (plan->labels[plan->n_labels].name, sizeof plan->labels[0].name,
              "%s", name);
    return plan->labels[plan->n_labels++].name;
}

static git_rebase_step *
git_plan_find (git_rebase_plan *plan, const char *id)
{
    for (size_t i = 0; i < plan->n_steps; i++)
        if (!strcmp (plan->steps[i].id, id)) return &plan->steps[i];
    return NULL;
}

/* Put a line in the list. AT is where it goes; below zero it goes at the
   end. A line pushed in among the others moves what is already written,
   so the commits keep track of where they have gone. */
static int
git_plan_write (git_rebase_plan *plan, int at, const char *text)
{
    if (plan->n_lines == plan->cap_lines) {
        size_t next = plan->cap_lines ? plan->cap_lines * 2 : 32;
        char (*grown)[1200] = realloc (plan->lines, next * sizeof *grown);
        if (!grown) return -1;
        plan->lines = grown;
        plan->cap_lines = next;
    }
    if (at < 0 || (size_t) at >= plan->n_lines) {
        snprintf (plan->lines[plan->n_lines], sizeof plan->lines[0], "%s", text);
        plan->n_lines++;
        return (int) plan->n_lines - 1;
    }
    memmove (plan->lines + at + 1, plan->lines + at,
             (plan->n_lines - at) * sizeof *plan->lines);
    snprintf (plan->lines[at], sizeof plan->lines[0], "%s", text);
    plan->n_lines++;
    for (size_t i = 0; i < plan->n_steps; i++)
        if (plan->steps[i].emitted && plan->steps[i].at >= at)
            plan->steps[i].at++;
    return at;
}

/* The run of commits a section is made of: from its tip back along first
   parents, as far as this rebase reaches and as far as no other section
   has taken them already. Newest first; BASE is left holding where it
   starts from, empty for a commit with no parent at all. */
static size_t
git_plan_chain (git_rebase_plan *plan, const char *tip,
                git_rebase_step **chain, char base[41])
{
    size_t n = 0;
    char at[41];
    memcpy (at, tip, 41);
    for (;;) {
        git_rebase_step *step = git_plan_find (plan, at);
        if (!step || step->emitted) break;
        chain[n++] = step;
        if (!step->n_parents) {
            *base = '\0';
            return n;
        }
        memcpy (at, step->parents[0], 41);
    }
    memcpy (base, at, 41);
    return n;
}

static void
git_plan_subject (git_rebase_plan *plan, const char *id, char *out, size_t size)
{
    git_rebase_step *step = git_plan_find (plan, id);
    if (step) {
        snprintf (out, size, "%s", step->subject);
        return;
    }
    struct git_commit parsed;
    *out = '\0';
    if (git_commit_read (plan->ctx, id, &parsed) == 0) {
        git_subject (&parsed, out, size);
        git_commit_release (&parsed);
    }
}

/* Write out one branch: what it merges in goes first, then where it starts
   from, then its own commits, then the name it will be known by. */
static int
git_plan_section (git_rebase_plan *plan, const char *tip, const char *label)
{
    git_rebase_step **chain = calloc (plan->n_steps ? plan->n_steps : 1,
                                      sizeof *chain);
    if (!chain) return -1;
    char base[41] = "";
    size_t n = 0;

    /* Whatever this branch merges in has to stand before it can be merged,
       so those branches are written out first — and the commits they take
       with them are no longer this one's to write. */
    for (;;) {
        n = git_plan_chain (plan, tip, chain, base);
        git_rebase_step *waiting = NULL;
        int which = 0;
        for (size_t i = n; i-- > 0; ) {
            for (int side = 1; side < chain[i]->n_parents; side++) {
                git_rebase_step *parent = git_plan_find (plan,
                                                         chain[i]->parents[side]);
                if (parent && !parent->emitted) {
                    waiting = chain[i];
                    which = side;
                    break;
                }
            }
            if (waiting) break;
        }
        if (!waiting) break;
        const char *name = git_label_of (plan, waiting->parents[which]);
        if (git_plan_section (plan, waiting->parents[which], name) < 0) {
            free (chain);
            return -1;
        }
    }
    if (!n) {
        free (chain);
        return 0;
    }

    /* Where it starts from: the rebase's own base, a commit another branch
       has already written out, or one this rebase does not touch at all. */
    char line[1200];
    if (!*base)
        snprintf (line, sizeof line, "reset [new root]");
    else {
        git_rebase_step *from = git_plan_find (plan, base);
        const char *name = git_label_of (plan, base);
        /* A branch that grew from where this rebase itself parts from its
           new base moves with it: that is what the rebase is for. One that
           grew from further back keeps where it was, unless the cousins
           are to be moved as well. */
        if (!from && !name) {
            if (plan->cousins) name = "onto";
            for (size_t i = 0; !name && i < plan->n_forks; i++)
                if (!strcmp (plan->forks[i], base)) name = "onto";
        }
        if (!name) name = git_label_take (plan, base, from ? "branch-point" : NULL);
        if (!name) {
            free (chain);
            return -1;
        }
        if (from && !from->labelled) {
            /* After whatever already follows that commit: a branch being
               carried along is written down with it, and git puts the
               name after all of that. */
            int at = from->at + 1;
            while (at < (int) plan->n_lines &&
                   (!strncmp (plan->lines[at], "update-ref ", 11) ||
                    !*plan->lines[at]))
                at++;
            char label_line[1200];
            snprintf (label_line, sizeof label_line, "label %s", name);
            if (git_plan_write (plan, at, label_line) < 0) {
                free (chain);
                return -1;
            }
            from->labelled = 1;
        }
        if (!strcmp (name, "onto"))
            snprintf (line, sizeof line, "reset onto");
        else {
            char subject[1024];
            git_plan_subject (plan, base, subject, sizeof subject);
            snprintf (line, sizeof line, "reset %s # %s", name, subject);
        }
    }

    if (label) {
        char branch[1200];
        snprintf (branch, sizeof branch, "# Branch %s", label);
        if (git_plan_write (plan, -1, branch) < 0) goto fail;
    }
    if (git_plan_write (plan, -1, line) < 0) goto fail;
    for (size_t i = n; i-- > 0; ) {
        int at = git_plan_write (plan, -1, chain[i]->line);
        if (at < 0) goto fail;
        chain[i]->emitted = 1;
        chain[i]->at = at;
        /* A branch standing where this commit does is carried along with
           it, which is what --update-refs asks for. */
        int carried = 0;
        for (size_t k = 0; k < plan->n_heads; k++) {
            if (strcmp (plan->heads[k].sha, chain[i]->id) ||
                (plan->head_name && !strcmp (plan->heads[k].name,
                                             plan->head_name)))
                continue;
            char line[1200];
            snprintf (line, sizeof line, "update-ref %s", plan->heads[k].name);
            if (git_plan_write (plan, -1, line) < 0) goto fail;
            carried = 1;
        }
        if (carried && git_plan_write (plan, -1, "") < 0) goto fail;
    }
    if (label) {
        char end[1200];
        snprintf (end, sizeof end, "label %s", label);
        if (git_plan_write (plan, -1, end) < 0) goto fail;
        chain[0]->labelled = 1;
        if (git_plan_write (plan, -1, "") < 0) goto fail;
    }
    free (chain);
    return 0;

fail:
    free (chain);
    return -1;
}

/* The todo list for a rebase that keeps its merges. Returns the number of
   commands in it, or -1. */
static int
git_rebase_merges_script (git_context *ctx, const char *head, const char *onto,
                          int cousins, int update_refs, const char *head_name,
                          FILE *out)
{
    git_rebase_plan plan;
    memset (&plan, 0, sizeof plan);
    plan.ctx = ctx;
    plan.cousins = cousins;
    plan.head_name = head_name;
    memcpy (plan.onto, onto, 41);
    if (update_refs)
        bgit_refs_list (&ctx->repo, "refs/heads/", &plan.heads, &plan.n_heads);

    const char *starts[1] = { head };
    const char *excludes[1] = { onto };
    char (*ordered)[41] = NULL;
    size_t n = 0;
    if (git_collect_commits (ctx, starts, 1, excludes, 1, 0, -1, &ordered,
                             &n) < 0)
        return -1;
    if (git_topo_order (ctx, ordered, n) < 0) {
        free (ordered);
        return -1;
    }
    const char *against[1] = { onto };
    bgit_merge_bases_many (&ctx->odb, head, against, 1, &plan.forks,
                           &plan.n_forks);

    plan.steps = calloc (n ? n : 1, sizeof *plan.steps);
    if (!plan.steps) {
        free (ordered);
        return -1;
    }
    plan.n_steps = n;
    /* Oldest first, which is the order they will be replayed in. */
    for (size_t i = 0; i < n; i++) {
        git_rebase_step *step = &plan.steps[i];
        memcpy (step->id, ordered[n - 1 - i], 41);
        step->n_parents = bgit_commit_parents (&ctx->odb, step->id,
                                               step->parents, BGIT_MAX_PARENTS);
        struct git_commit parsed;
        if (git_commit_read (ctx, step->id, &parsed) == 0) {
            git_subject (&parsed, step->subject, sizeof step->subject);
            git_commit_release (&parsed);
        }
    }
    free (ordered);

    /* The base of the rebase is the one name that is there from the start. */
    if (!git_label_take (&plan, onto, "onto")) goto fail;

    /* Every branch that is merged back in gets its name here, from the
       message of the merge that brought it in. */
    for (size_t i = 0; i < plan.n_steps; i++) {
        git_rebase_step *step = &plan.steps[i];
        char abbreviated[41];
        git_abbrev (ctx, step->id, 7, abbreviated, sizeof abbreviated);
        if (step->n_parents < 2) {
            snprintf (step->line, sizeof step->line, "pick %s %s", abbreviated,
                      step->subject);
            continue;
        }
        char wanted[1024];
        git_label_from_subject (step->subject, wanted, sizeof wanted);
        size_t len = snprintf (step->line, sizeof step->line, "merge -C %s",
                               abbreviated);
        for (int side = 1; side < step->n_parents; side++) {
            git_rebase_step *parent = git_plan_find (&plan, step->parents[side]);
            const char *name = git_label_take (&plan, step->parents[side],
                                               parent ? wanted : NULL);
            if (!name) goto fail;
            len += snprintf (step->line + len, sizeof step->line - len, " %s",
                             name);
        }
        snprintf (step->line + len, sizeof step->line - len, " # %s",
                  step->subject);
    }

    if (git_plan_write (&plan, -1, "label onto") < 0) goto fail;
    if (git_plan_write (&plan, -1, "") < 0) goto fail;
    if (git_plan_section (&plan, head, NULL) < 0) goto fail;

    int commands = 0;
    for (size_t i = 0; i < plan.n_lines; i++) {
        fprintf (out, "%s\n", plan.lines[i]);
        if (*plan.lines[i] && *plan.lines[i] != '#') commands++;
    }
    free (plan.steps);
    free (plan.labels);
    free (plan.lines);
    free (plan.forks);
    bgit_refs_free (plan.heads, plan.n_heads);
    return commands;

fail:
    free (plan.steps);
    free (plan.labels);
    free (plan.lines);
    free (plan.forks);
    bgit_refs_free (plan.heads, plan.n_heads);
    return -1;
}

/* What a merge has to say for itself, and how much of it did not settle.
   A rebase holds this back unless something did not settle — git buffers
   the same words and throws them away when the merge came out clean. */
static int
git_merge_report (FILE *out, const bgit_merge_path *paths, size_t n_paths,
                  const char *label)
{
    int conflicts = 0;
    for (size_t i = 0; i < n_paths; i++) {
        const bgit_merge_path *path = &paths[i];
        if (path->kind == BGIT_MERGE_AUTO || path->kind == BGIT_MERGE_CONTENT ||
            path->kind == BGIT_MERGE_ADD_ADD)
            fprintf (out, "Auto-merging %s\n", path->path);
        if (path->kind == BGIT_MERGE_CONTENT) {
            conflicts++;
            fprintf (out, "CONFLICT (content): Merge conflict in %s\n",
                     path->path);
        } else if (path->kind == BGIT_MERGE_ADD_ADD) {
            conflicts++;
            fprintf (out, "CONFLICT (add/add): Merge conflict in %s\n",
                     path->path);
        } else if (path->kind == BGIT_MERGE_MODIFY_DELETE) {
            conflicts++;
            fprintf (out, "CONFLICT (modify/delete): %s deleted in %s and "
                          "modified in %s.  Version %s of %s left in tree.\n",
                     path->path, path->deleted_in_ours ? "HEAD" : label,
                     path->deleted_in_ours ? label : "HEAD",
                     path->deleted_in_ours ? label : "HEAD", path->path);
        }
    }
    return conflicts;
}

/* Apply one commit onto HEAD, the way cherry-pick does. Returns 0 when it
   settled, 1 when it did not, -1 on failure. With SILENT the step leaves
   no line in the reflog: a commit about to be melded into the one before
   it was never really there, and git's log does not say it was. */
static int
git_rebase_apply (git_context *ctx, struct git_state *state, const char *commit,
                  int *empty, int silent)
{
    *empty = 0;
    struct git_commit picked;
    if (git_commit_read (ctx, commit, &picked) < 0) return -1;
    if (!picked.n_parents) {
        git_commit_release (&picked);
        return -1;
    }
    char parent_tree[41];
    if (bgit_commit_tree (&ctx->odb, picked.parents[0], parent_tree) < 0) {
        git_commit_release (&picked);
        return -1;
    }
    char abbreviated[41], subject[1024];
    git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
    git_subject (&picked, subject, sizeof subject);
    char label[1200];
    snprintf (label, sizeof label, "%s (%s)", abbreviated, subject);

    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0], parent_tree,
                          state->head_tree, picked.tree, "HEAD", label,
                          &paths, &n_paths) < 0) {
        git_commit_release (&picked);
        return -1;
    }
    if (git_merge_safe (ctx, state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        return -1;
    }
    char *said = NULL;
    size_t said_len = 0;
    FILE *saying = open_memstream (&said, &said_len);
    if (!saying) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        return -1;
    }
    int conflicts = git_merge_report (saying, paths, n_paths, label);
    fclose (saying);
    if (conflicts) fputs (said, stdout);
    free (said);
    if (git_merge_apply (ctx, state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        return -1;
    }
    bgit_merge_paths_free (paths, n_paths);
    if (conflicts) {
        git_commit_release (&picked);
        return 1;
    }

    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state->index,
                         state->n_index, tree) < 0) {
        git_commit_release (&picked);
        return -1;
    }
    if (!strcmp (tree, state->head_tree)) {
        /* Everything this commit did is already here: git drops it. */
        *empty = 1;
        git_commit_release (&picked);
        return 0;
    }
    char author[1024];
    snprintf (author, sizeof author, "%s <%s> %s", picked.author_name,
              picked.author_email, picked.author_date);
    char reflog[1200];
    snprintf (reflog, sizeof reflog, "rebase (pick): %s", subject);

    char committer[1024];
    if (bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0) {
        git_commit_release (&picked);
        return -1;
    }
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) { git_commit_release (&picked); return -1; }
    fprintf (builder, "tree %s\n", tree);
    fprintf (builder, "parent %s\n", state->head);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    fprintf (builder, "\n%s", picked.message);
    fclose (builder);
    char written[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1,
                                written);
    free (body);
    git_commit_release (&picked);
    if (rc < 0) return -1;
    if (git_head_detach (ctx, state, written, silent ? NULL : reflog) < 0) return -1;
    /* HEAD has moved, so the state follows it. */
    memcpy (state->head, written, 41);
    memcpy (state->head_tree, tree, 41);
    state->have_head = 1;
    return 0;
}

/* Put the branch back where HEAD now is, and attach HEAD to it again. */
static int
git_rebase_finish (git_context *ctx, struct git_state *state,
                   const char *head_name, const char *onto, int quiet)
{
    char message[1200], branch_message[1200];
    snprintf (message, sizeof message, "rebase (finish): returning to %s",
              head_name);
    snprintf (branch_message, sizeof branch_message, "rebase (finish): %s onto %s",
              head_name, onto);
    /* A branch that ends where it started has not moved, and git's log
       does not say it has. */
    char was[41];
    int moved = bgit_ref_read (&ctx->repo, head_name, was) < 0 ||
                strcmp (was, state->head);
    if ((moved && bgit_ref_update (&ctx->repo, head_name, state->head, NULL,
                                   branch_message) < 0) ||
        bgit_symref_write (&ctx->repo, "HEAD", head_name, NULL) < 0)
        return GIT_EXIT_FATAL;
    bgit_reflog_append (&ctx->repo, "HEAD", state->head, state->head, message);
    git_rebase_labels_clear (ctx);
    if (!quiet) {
        fflush (stdout);
        fprintf (stderr, "Successfully rebased and updated %s.\n", head_name);
    }
    git_rebase_refs_apply (ctx, quiet);
    git_rebase_clear (ctx);
    return 0;
}

static int
git_cmd_rebase (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git rebase [-i] [-r] [--update-refs] "
                        "[--reapply-cherry-picks] <upstream> [<branch>] "
                        "| --continue | --abort | --skip";
    const char *upstream = NULL, *branch = NULL;
    int continue_it = 0, abort_it = 0, skip_it = 0, quiet = 0, interactive = 0;
    int rebase_merges = 0, cousins = 0, update_refs = -1, reapply = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--continue")) continue_it = 1;
        else if (!strcmp (w, "--abort")) abort_it = 1;
        else if (!strcmp (w, "--skip")) skip_it = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-i") || !strcmp (w, "--interactive"))
            interactive = 1;
        else if (!strcmp (w, "-r") || !strcmp (w, "--rebase-merges"))
            rebase_merges = 1;
        else if (!strcmp (w, "--update-refs")) update_refs = 1;
        else if (!strcmp (w, "--no-update-refs")) update_refs = 0;
        else if (!strcmp (w, "--reapply-cherry-picks")) reapply = 1;
        else if (!strcmp (w, "--no-reapply-cherry-picks")) reapply = 0;
        else if (!strncmp (w, "--rebase-merges=", 16)) {
            rebase_merges = 1;
            if (!strcmp (w + 16, "rebase-cousins")) cousins = 1;
            else if (strcmp (w + 16, "no-rebase-cousins"))
                return git_fatal ("Unknown mode: %s", w + 16);
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!upstream) upstream = w;
        else if (!branch) branch = w;
        else return git_usage (usage);
    }
    if (!upstream && !continue_it && !abort_it && !skip_it)
        return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");
    if (update_refs < 0)
        update_refs = bgit_config_bool (&ctx->cfg, "rebase.updateRefs", 0);

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int running = git_rebase_in_progress (ctx);
    int status = 0;

    if (abort_it) {
        if (!running) {
            git_state_release (&state);
            return git_fatal ("No rebase in progress?");
        }
        char head_name[4096], orig[41];
        if (git_rebase_read (ctx, "head-name", head_name, sizeof head_name) < 0 ||
            git_rebase_read (ctx, "orig-head", orig, sizeof orig) < 0) {
            git_state_release (&state);
            return git_fatal ("cannot read the rebase state");
        }
        char tree[41];
        if (bgit_commit_tree (&ctx->odb, orig, tree) < 0 ||
            bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state.index,
                                &state.n_index, 1, NULL) < 0 ||
            git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
        if (!status) {
            /* The branch never moved — HEAD was detached for the replay —
               so only HEAD goes back. */
            char message[1200];
            snprintf (message, sizeof message,
                      "rebase (abort): returning to %s", head_name);
            if (bgit_symref_write (&ctx->repo, "HEAD", head_name, NULL) < 0)
                status = GIT_EXIT_FATAL;
            else
                bgit_reflog_append (&ctx->repo, "HEAD", state.head, orig, message);
        }
        git_remove_state_file (ctx, "MERGE_HEAD");
        git_remove_state_file (ctx, "MERGE_MODE");
        git_remove_state_file (ctx, "MERGE_MSG");
        git_rebase_labels_clear (ctx);
        git_rebase_clear (ctx);
        git_state_release (&state);
        return status;
    }

    static char todo[128][1200];
    int n_todo = 0, done_count = 0, leading = 0;
    char start_at[41] = "";
    char head_name[4096] = "", onto[41] = "", orig[41] = "";
    static char done_lines[128][1200];

    if (continue_it || skip_it) {
        if (!running) {
            git_state_release (&state);
            return git_fatal ("No rebase in progress?");
        }
        if (git_rebase_read (ctx, "head-name", head_name, sizeof head_name) < 0 ||
            git_rebase_read (ctx, "onto", onto, sizeof onto) < 0 ||
            git_rebase_read (ctx, "orig-head", orig, sizeof orig) < 0) {
            git_state_release (&state);
            return git_fatal ("cannot read the rebase state");
        }
        for (size_t i = 0; i < state.n_index; i++)
            if ((state.index[i].flags >> 12) & 3) {
                git_state_release (&state);
                fflush (stdout);
                fprintf (stderr, "error: Committing is not possible because "
                                 "you have unmerged files.\n");
                fprintf (stderr, "fatal: Exiting because of an unresolved "
                                 "conflict.\n");
                return 1;
            }
        /* A stop for amending leaves the commit already made: what was
           staged since goes into it, which is what git does when a rebase
           told to edit is taken up again. */
        char amend_marker[64];
        if (!skip_it && git_rebase_read (ctx, "stopped-sha", amend_marker,
                                         sizeof amend_marker) < 0 &&
            git_rebase_read (ctx, "amend", amend_marker,
                             sizeof amend_marker) == 0 && state.have_head) {
            char tree[41];
            if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0],
                                 state.index, state.n_index, tree) < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            if (strcmp (tree, state.head_tree)) {
                struct git_commit editing;
                if (git_commit_read (ctx, state.head, &editing) < 0) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
                char author[1024], parent[41] = "", subject[1024];
                snprintf (author, sizeof author, "%s <%s> %s",
                          editing.author_name, editing.author_email,
                          editing.author_date);
                if (editing.n_parents) memcpy (parent, editing.parents[0], 41);
                git_subject (&editing, subject, sizeof subject);
                char *message = strdup (editing.message);
                git_commit_release (&editing);
                if (!message) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
                /* git asks for the message again here, as it does for any
                   amendment; an editor that leaves the file alone keeps
                   what was there. */
                char *written = git_rebase_message_edit (ctx, &state, message,
                                                         NULL, 0, author);
                free (message);
                if (!written) {
                    git_state_release (&state);
                    fflush (stdout);
                    fprintf (stderr, "Aborting commit due to empty commit "
                                     "message.\n");
                    fprintf (stderr, "error: could not commit staged "
                                     "changes.\n");
                    return 1;
                }
                const char *nl = strchr (written, '\n');
                snprintf (subject, nl ? (size_t) (nl - written) + 1
                                      : sizeof subject, "%s", written);
                char reflog[1200];
                snprintf (reflog, sizeof reflog, "rebase (continue): %s",
                          subject);
                int replaced = git_rebase_replace_head (ctx, &state, parent,
                                                        author, written,
                                                        reflog, quiet);
                free (written);
                if (replaced < 0) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
            }
            char path[4096];
            if (git_rebase_path (ctx, "amend", path, sizeof path) == 0)
                unlink (path);
        }

        /* Finish the commit that stopped, unless it is being skipped. */
        char stopped[41];
        if (!skip_it && git_rebase_read (ctx, "stopped-sha", stopped,
                                         sizeof stopped) == 0) {
            struct git_commit picked;
            if (git_commit_read (ctx, stopped, &picked) < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            char tree[41];
            if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                                 state.n_index, tree) < 0) {
                git_commit_release (&picked);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            char author[1024], committer[1024], subject[1024];
            git_subject (&picked, subject, sizeof subject);
            snprintf (author, sizeof author, "%s <%s> %s", picked.author_name,
                      picked.author_email, picked.author_date);
            if (bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0) {
                git_commit_release (&picked);
                git_state_release (&state);
                return git_fatal ("cannot determine the identity to use");
            }
            /* A merge that stopped over a conflict is still a merge: what
               it was merging waits in MERGE_HEAD, and git asks for the
               message once the conflict has been settled. */
            char merge_head[41] = "";
            char *edited = NULL;
            if (git_read_state_id (ctx, "MERGE_HEAD", merge_head)) {
                char path[4096];
                if (snprintf (path, sizeof path, "%s/COMMIT_EDITMSG",
                              ctx->repo.git_dir) < (int) sizeof path) {
                    FILE *asking = fopen (path, "w");
                    if (asking) {
                        size_t len = strlen (picked.message);
                        fprintf (asking, "%s", picked.message);
                        if (len && picked.message[len - 1] != '\n')
                            fprintf (asking, "\n");
                        git_commit_template (ctx, asking, &state, author,
                                             committer, 0, 0);
                        fclose (asking);
                        if (git_edit_file (ctx, path, 0) == 0) {
                            size_t kept = 0;
                            edited = git_message_body (path, &kept);
                            if (edited && !kept) {
                                free (edited);
                                edited = NULL;
                            }
                        }
                    }
                }
                if (!edited) {
                    git_commit_release (&picked);
                    git_state_release (&state);
                    fflush (stdout);
                    fprintf (stderr, "error: empty commit message\n");
                    return 1;
                }
                const char *first = strchr (edited, '\n');
                snprintf (subject,
                          first ? (size_t) (first - edited) + 1
                                : sizeof subject, "%s", edited);
            }
            char *body = NULL;
            size_t body_len = 0;
            FILE *builder = open_memstream (&body, &body_len);
            if (!builder) {
                git_commit_release (&picked);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            fprintf (builder, "tree %s\n", tree);
            fprintf (builder, "parent %s\n", state.head);
            if (*merge_head) fprintf (builder, "parent %s\n", merge_head);
            fprintf (builder, "author %s\n", author);
            fprintf (builder, "committer %s\n", committer);
            fprintf (builder, "\n%s", edited ? edited : picked.message);
            if (edited) {
                size_t len = strlen (edited);
                if (!len || edited[len - 1] != '\n') fprintf (builder, "\n");
            }
            fclose (builder);
            free (edited);
            char written[41];
            int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                        (const unsigned char *) body, body_len,
                                        1, written);
            free (body);
            git_commit_release (&picked);
            if (rc < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            git_remove_state_file (ctx, "MERGE_HEAD");
            git_remove_state_file (ctx, "MERGE_MODE");
            git_remove_state_file (ctx, "MERGE_MSG");
            char reflog[1200];
            snprintf (reflog, sizeof reflog, "rebase (continue): %s", subject);
            char old_tree[41];
            memcpy (old_tree, state.head_tree, 41);
            if (git_head_detach (ctx, &state, written, reflog) < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            memcpy (state.head, written, 41);
            memcpy (state.head_tree, tree, 41);
            if (!quiet) {
                char abbreviated[41];
                git_abbrev (ctx, written, 7, abbreviated, sizeof abbreviated);
                printf ("[detached HEAD %s] %s\n", abbreviated, subject);
                char author_who[1024], committer_who[1024];
                git_ident_who (author, author_who, sizeof author_who);
                git_ident_who (committer, committer_who, sizeof committer_who);
                if (strcmp (author_who, committer_who))
                    printf (" Author: %s\n", author_who);
                struct git_diff_format format;
                git_diff_format_init (&format);
                format.shortstat = 1;
                format.summary = 1;
                bgit_diff_entry *entries = NULL;
                size_t n_entries = 0;
                /* git says nothing about what a merge changed. */
                if (!*merge_head &&
                    bgit_diff_trees (&ctx->odb, old_tree, tree, &entries,
                                     &n_entries) == 0) {
                    git_diff_emit (ctx, stdout, &format, entries, n_entries, 0, "");
                    bgit_diff_free (entries, n_entries);
                }
            }
        }
        /* What is left to do. */
        char path[4096];
        if (git_rebase_path (ctx, "git-rebase-todo", path, sizeof path) == 0) {
            FILE *file = fopen (path, "r");
            if (file) {
                char line[1200];
                while (n_todo < 128 && fgets (line, sizeof line, file)) {
                    size_t len = strlen (line);
                    while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
                        line[--len] = '\0';
                    if (*line) snprintf (todo[n_todo++], sizeof todo[0], "%s", line);
                }
                fclose (file);
            }
        }
        if (git_rebase_path (ctx, "done", path, sizeof path) == 0) {
            FILE *file = fopen (path, "r");
            if (file) {
                char line[1200];
                while (done_count < 128 && fgets (line, sizeof line, file)) {
                    size_t len = strlen (line);
                    while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
                        line[--len] = '\0';
                    if (*line)
                        snprintf (done_lines[done_count++], sizeof done_lines[0],
                                  "%s", line);
                }
                fclose (file);
            }
        }
    } else {
        if (running) {
            git_state_release (&state);
            return git_fatal ("It seems that there is already a rebase-merge "
                              "directory");
        }
        if (branch) {
            if (git_switch_to (ctx, &state, branch, 0, 0) != 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            git_state_release (&state);
            if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
        }
        if (!state.have_head || !state.branch) {
            git_state_release (&state);
            return git_fatal ("You are not currently on a branch");
        }
        snprintf (head_name, sizeof head_name, "%s", state.branch);
        memcpy (orig, state.head, 41);

        char id[41];
        if (git_resolve (ctx, upstream, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, onto) < 0) {
            git_state_release (&state);
            return git_fatal ("invalid upstream '%s'", upstream);
        }

        /* What this branch has that the upstream does not, oldest first. */
        const char *starts[1] = { state.head };
        const char *excludes[1] = { onto };
        char (*ordered)[41] = NULL;
        size_t n = 0;
        if (git_collect_commits (ctx, starts, 1, excludes, 1, 0, -1, &ordered,
                                 &n) < 0 ||
            git_topo_order (ctx, ordered, n) < 0) {
            free (ordered);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        /* A commit whose patch the upstream already has, under a name of
           its own, is passed over: what makes it the same patch is its
           patch id, which is what git compares here too. */
        char (*applied)[41] = NULL;
        size_t n_applied = 0;
        if (!reapply) {
            const char *theirs[1] = { onto };
            const char *mine[1] = { state.head };
            char (*over_there)[41] = NULL;
            size_t n_there = 0;
            if (git_collect_commits (ctx, theirs, 1, mine, 1, 0, -1,
                                     &over_there, &n_there) == 0) {
                applied = calloc (n_there ? n_there : 1, 41);
                for (size_t i = 0; applied && i < n_there; i++) {
                    char parents[BGIT_MAX_PARENTS][41];
                    if (bgit_commit_parents (&ctx->odb, over_there[i], parents,
                                             BGIT_MAX_PARENTS) > 1)
                        continue;
                    if (git_commit_patch_id (ctx, over_there[i],
                                             applied[n_applied]) == 0)
                        n_applied++;
                }
                free (over_there);
            }
        }
        int passed_over = 0;
        for (size_t i = 0; i < n && n_todo < (int) (sizeof todo / sizeof todo[0]);
             i++) {
            const char *commit = ordered[n - 1 - i];
            /* A rebase replays what one branch did, and a merge did none
               of it: unless the merges are the point, they are left out
               and what they brought in is replayed on its own. */
            if (!rebase_merges) {
                char parents[BGIT_MAX_PARENTS][41];
                if (bgit_commit_parents (&ctx->odb, commit, parents,
                                         BGIT_MAX_PARENTS) > 1)
                    continue;
            }
            if (n_applied) {
                char id[41];
                int seen = 0;
                if (git_commit_patch_id (ctx, commit, id) == 0)
                    for (size_t j = 0; j < n_applied && !seen; j++)
                        if (!memcmp (applied[j], id, 41)) seen = 1;
                if (seen) {
                    char shown[41];
                    git_abbrev (ctx, commit, 7, shown, sizeof shown);
                    fflush (stdout);
                    fprintf (stderr, "warning: skipped previously applied "
                                     "commit %s\n", shown);
                    passed_over = 1;
                    continue;
                }
            }
            git_rebase_line (ctx, commit, todo[n_todo++], sizeof todo[0]);
            /* A branch standing where this commit does is carried along
               with it, which is what --update-refs asks for. */
            if (update_refs) {
                bgit_ref *heads = NULL;
                size_t n_heads = 0;
                if (bgit_refs_list (&ctx->repo, "refs/heads/", &heads,
                                    &n_heads) == 0) {
                    for (size_t k = 0; k < n_heads &&
                         n_todo < (int) (sizeof todo / sizeof todo[0]); k++) {
                        if (strcmp (heads[k].sha, commit) ||
                            !strcmp (heads[k].name, head_name))
                            continue;
                        snprintf (todo[n_todo++], sizeof todo[0],
                                  "update-ref %s", heads[k].name);
                    }
                    bgit_refs_free (heads, n_heads);
                }
            }
        }
        free (applied);
        if (passed_over && git_advice_wanted (ctx, "skippedCherryPicks")) {
            fprintf (stderr, "hint: use --reapply-cherry-picks to include "
                             "skipped commits\n");
            fprintf (stderr, "hint: Disable this message with \"git config "
                             "advice.skippedCherryPicks false\"\n");
        }
        free (ordered);

        /* A branch already sitting on its upstream has nothing to replay —
           unless the point is to go over what it has, which is what -i is
           for, or to put its merges back together, which goes through the
           list either way. */
        if (!interactive && !rebase_merges &&
            bgit_is_ancestor (&ctx->odb, onto, state.head) > 0) {
            const char *shown = head_name;
            if (!strncmp (shown, "refs/heads/", 11)) shown += 11;
            printf ("Current branch %s is up to date.\n", shown);
            git_state_release (&state);
            return 0;
        }
        if (!n_todo) {
            /* Only behind: the branch moves up, reported like any rebase. */
            char tree[41];
            if (bgit_commit_tree (&ctx->odb, onto, tree) < 0 ||
                bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state.index,
                                    &state.n_index, 0, NULL) < 0 ||
                git_index_store (ctx, state.index, state.n_index) < 0)
                status = GIT_EXIT_FATAL;
            if (!status) {
                char start_message[1200];
                snprintf (start_message, sizeof start_message,
                          "rebase (start): checkout %s", upstream);
                bgit_reflog_append (&ctx->repo, "HEAD", state.head, onto,
                                    start_message);
                memcpy (state.head, onto, 41);
                memcpy (state.head_tree, tree, 41);
                status = git_rebase_finish (ctx, &state, head_name, onto, quiet);
            }
            git_state_release (&state);
            return status;
        }

        /* With -i the list is written down and handed to an editor, and
           what comes back is what will be replayed. A rebase that keeps
           its merges writes a list of another shape, and writes it down
           whether or not anyone will look at it. */
        if (interactive || rebase_merges) {
            char path[4096];
            if (git_rebase_path (ctx, "", path, sizeof path) < 0 ||
                (mkdir (path, 0777) < 0 && errno != EEXIST) ||
                git_rebase_path (ctx, "git-rebase-todo", path,
                                 sizeof path) < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            FILE *out = fopen (path, "w");
            if (!out) {
                git_state_release (&state);
                return git_fatal ("could not write '%s'", path);
            }
            int commands = n_todo;
            if (rebase_merges) {
                commands = git_rebase_merges_script (ctx, state.head, onto,
                                                     cousins, update_refs,
                                                     head_name, out);
                if (commands < 0) {
                    fclose (out);
                    git_rebase_clear (ctx);
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
            } else
                for (int i = 0; i < n_todo; i++) {
                    fprintf (out, "%s\n", todo[i]);
                    /* git sets a branch it is carrying along apart from
                       what comes after it. */
                    if (strncmp (todo[i], "update-ref ", 11)) continue;
                    if (i + 1 < n_todo &&
                        !strncmp (todo[i + 1], "update-ref ", 11))
                        continue;
                    fprintf (out, "\n");
                }
            git_rebase_todo_note (out, ctx, onto, state.head, onto, commands);
            fclose (out);
            if (interactive && git_edit_file (ctx, path, 1) < 0) {
                git_rebase_clear (ctx);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            n_todo = 0;
            FILE *file = fopen (path, "r");
            if (file) {
                char line[1200];
                while (n_todo < (int) (sizeof todo / sizeof todo[0]) &&
                       fgets (line, sizeof line, file)) {
                    size_t len = strlen (line);
                    while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
                        line[--len] = '\0';
                    const char *at = line;
                    while (*at == ' ' || *at == '\t') at++;
                    if (!*at || *at == '#') continue;
                    snprintf (todo[n_todo++], sizeof todo[0], "%s", line);
                }
                fclose (file);
            }
            if (!n_todo) {
                /* Everything struck out means the rebase is called off, and
                   nothing has been touched yet. */
                git_rebase_clear (ctx);
                git_state_release (&state);
                fflush (stdout);
                fprintf (stderr, "error: nothing to do\n");
                return 1;
            }
        }

        /* The leading run of picks that are already standing where they
           would land is stepped over in one go: git's start checkout goes
           to the last of them and says nothing more about them. A commit
           about to be melded into another is not one of them. */
        {
            char at[41];
            memcpy (at, onto, 41);
            while (leading < n_todo) {
                char command[32], name[64], id[41];
                const char *rest = "";
                if (!git_rebase_todo_parse (todo[leading], command,
                                            sizeof command, name, sizeof name,
                                            &rest))
                    break;
                const char *verb = git_rebase_command (command);
                if (!verb || strcmp (verb, "pick") || !*name) break;
                char parents[BGIT_MAX_PARENTS][41];
                if (git_resolve (ctx, name, id, NULL) < 0) break;
                int n_parents = bgit_commit_parents (&ctx->odb, id, parents,
                                                     BGIT_MAX_PARENTS);
                if (n_parents != 1 || strcmp (parents[0], at)) break;
                memcpy (at, id, 41);
                leading++;
            }
            memcpy (start_at, at, 41);
        }

        /* Start from the upstream — or from the end of that run — with
           HEAD detached, as git does. */
        char tree[41];
        if (bgit_commit_tree (&ctx->odb, start_at, tree) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        char *losing = NULL;
        int rc = bgit_checkout_tree (&ctx->repo, &ctx->odb, tree, &state.index,
                                     &state.n_index, 0, &losing);
        if (rc != 0) {
            fflush (stdout);
            fprintf (stderr, "error: cannot rebase: You have unstaged "
                             "changes.\n");
            free (losing);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        char start_message[1200];
        snprintf (start_message, sizeof start_message, "rebase (start): checkout %s",
                  upstream);
        if (git_index_store (ctx, state.index, state.n_index) < 0 ||
            git_head_detach (ctx, &state, start_at, start_message) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        memcpy (state.head, start_at, 41);
        memcpy (state.head_tree, tree, 41);

        char path[4096];
        if (git_rebase_path (ctx, "", path, sizeof path) < 0 ||
            (mkdir (path, 0777) < 0 && errno != EEXIST)) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        /* Where this rebase is going, written down before it starts, so
           that anything asking — status, or an editor's note — can say. */
        {
            char state_content[8192];
            git_rebase_state_files (ctx, head_name, onto, orig, 0,
                                    n_todo, state_content,
                                    sizeof state_content);
        }
        git_rebase_write (ctx, "interactive", "");
        /* The branches this list says to carry along, so that a stop and
           a later continue still know about them. */
        git_rebase_refs_start (ctx, todo, n_todo);
        /* What was stepped over is written down as done, so that the
           numbering and a later --continue both count it. */
        {
            char stepped[8192];
            for (int i = 0; i < leading; i++)
                git_rebase_record (ctx, done_lines, &done_count, todo, n_todo,
                                   i, stepped, sizeof stepped);
        }
    }

    /* Replay what is left, stopping at the first thing that does not settle. */
    char content[8192];
    int started_with = done_count - leading;
    int total = started_with + n_todo;
    char action[1200];
    snprintf (action, sizeof action, "rebase (%s)",
              continue_it ? "continue" : "start");

    for (int i = leading; i < n_todo; i++) {
        char id[41], command[32], name[64];
        const char *rest = "";
        if (!git_rebase_todo_parse (todo[i], command, sizeof command, name,
                                    sizeof name, &rest))
            continue;                     /* a comment, or nothing at all */
        const char *verb = git_rebase_command (command);
        if (!verb) {
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "error: invalid command '%s'\n", command);
            return GIT_EXIT_FATAL;
        }

        fflush (stdout);
        fprintf (stderr, "Rebasing (%d/%d)\r", started_with + i + 1, total);

        /* Each commit command says what it is doing, and what it says
           stands until the next one: a merge is committed under it. */
        if (!strcmp (verb, "pick") || !strcmp (verb, "reword") ||
            !strcmp (verb, "edit") || !strcmp (verb, "squash") ||
            !strcmp (verb, "fixup"))
            snprintf (action, sizeof action, "rebase (%s)", verb);

        /* A commit already standing on HEAD is moved to rather than
           replayed, which is what git does. What is about to be melded
           into another is never moved to: it has to be made as part of
           that. */
        int melding = !strcmp (verb, "squash") || !strcmp (verb, "fixup");
        int moved_to = 0;
        if (!melding && strcmp (verb, "exec") && strcmp (verb, "break") &&
            strcmp (verb, "drop") && strcmp (verb, "label") &&
            strcmp (verb, "reset") && strcmp (verb, "merge") &&
            strcmp (verb, "update-ref") && *name &&
            git_resolve (ctx, name, id, NULL) == 0) {
            char parents[BGIT_MAX_PARENTS][41], tree[41];
            int n_parents = bgit_commit_parents (&ctx->odb, id, parents,
                                                 BGIT_MAX_PARENTS);
            if (n_parents == 1 && !strcmp (parents[0], state.head) &&
                bgit_commit_tree (&ctx->odb, id, tree) == 0) {
                if (bgit_checkout_tree (&ctx->repo, &ctx->odb, tree,
                                        &state.index, &state.n_index, 0,
                                        NULL) < 0 ||
                    git_index_store (ctx, state.index, state.n_index) < 0 ||
                    git_head_detach (ctx, &state, id,
                                     "rebase: fast-forward") < 0) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
                memcpy (state.head, id, 41);
                memcpy (state.head_tree, tree, 41);
                moved_to = 1;
                if (!strcmp (verb, "pick")) {
                    git_rebase_record (ctx, done_lines, &done_count, todo,
                                       n_todo, i, content, sizeof content);
                    continue;
                }
            }
        }

        /* A branch carried along reaches its place here; it is moved
           when the whole rebase is done, as git moves it. */
        if (!strcmp (verb, "update-ref")) {
            git_rebase_record (ctx, done_lines, &done_count, todo, n_todo, i,
                               content, sizeof content);
            if (*name) git_rebase_refs_mark (ctx, name, state.head);
            continue;
        }

        /* A rebase that keeps its merges works with labels: a name for
           where HEAD stands, something to come back to later. */
        if (!strcmp (verb, "label") || !strcmp (verb, "reset") ||
            !strcmp (verb, "merge")) {
            git_rebase_record (ctx, done_lines, &done_count, todo, n_todo, i,
                               content, sizeof content);
            char stopped_at[41] = "", stopped_arg[1200] = "";
            int rc = git_rebase_marked (ctx, &state, verb, name, rest, action,
                                        sizeof action, stopped_at, stopped_arg,
                                        sizeof stopped_arg);
            if (rc < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            if (rc > 0) {
                /* A merge that did not settle stops the rebase here, and
                   leaves behind what taking it up again will need. */
                snprintf (content, sizeof content, "%s\n", stopped_at);
                git_rebase_write (ctx, "stopped-sha", content);
                git_write_state_file (ctx, "REBASE_HEAD", content);
                git_rebase_state_files (ctx, head_name, onto, orig, done_count,
                                        total, content, sizeof content);
                git_state_release (&state);
                fflush (stdout);
                char short_id[41];
                git_abbrev (ctx, stopped_at, 7, short_id, sizeof short_id);
                fprintf (stderr, "Could not apply %s... %s\n", short_id,
                         stopped_arg);
                return 1;
            }
            continue;
        }

        /* The commands that do not replay a commit are answered here, and
           each one writes down what has been done before it acts, so that
           what stops can be taken up again. */
        if (!strcmp (verb, "exec") || !strcmp (verb, "break") ||
            !strcmp (verb, "drop")) {
            git_rebase_record (ctx, done_lines, &done_count, todo, n_todo, i,
                               content, sizeof content);
            if (!strcmp (verb, "drop")) continue;
            if (!strcmp (verb, "exec")) {
                fflush (stdout);
                fprintf (stderr, "Executing: %s\n", rest);
                int ran = git_run_shell (rest);
                if (ran == 0) continue;
                git_rebase_state_files (ctx, head_name, onto, orig, done_count,
                                        total, content, sizeof content);
                git_state_release (&state);
                fflush (stdout);
                fprintf (stderr, "warning: execution failed: %s\n", rest);
                fprintf (stderr, "You can fix the problem, and then run\n\n"
                                 "  git rebase --continue\n\n\n");
                return 1;
            }
            /* break: stop where this leaves off, and say where that is. */
            git_rebase_state_files (ctx, head_name, onto, orig, done_count,
                                    total, content, sizeof content);
            char short_id[41], subject[1024] = "";
            git_abbrev (ctx, state.head, 7, short_id, sizeof short_id);
            struct git_commit stopped_at;
            if (git_commit_read (ctx, state.head, &stopped_at) == 0) {
                git_subject (&stopped_at, subject, sizeof subject);
                git_commit_release (&stopped_at);
            }
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "Stopped at %s (%s)\n", short_id, subject);
            return 0;
        }

        if (!*name || git_resolve (ctx, name, id, NULL) < 0) {
            git_state_release (&state);
            return git_fatal ("cannot read the rebase todo list");
        }

        int empty = 0;
        int rc = moved_to ? 0 : git_rebase_apply (ctx, &state, id, &empty,
                                                  melding);
        if (rc < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        /* A commit that turned out to do nothing is dropped, and git says
           which one and why. */
        if (!rc && empty && !strcmp (verb, "pick")) {
            struct git_commit dropped;
            char subject[1024] = "";
            if (git_commit_read (ctx, id, &dropped) == 0) {
                git_subject (&dropped, subject, sizeof subject);
                git_commit_release (&dropped);
            }
            fflush (stdout);
            fprintf (stderr, "dropping %s %s -- patch contents already "
                             "upstream\n", id, subject);
        }

        /* Whatever happened, this command is done. */
        git_rebase_record (ctx, done_lines, &done_count, todo, n_todo, i,
                           content, sizeof content);

        /* A commit that went in cleanly may still have something asked of
           it: a message to write, a stop for amending, or being melded
           into the one before it. */
        if (!rc && strcmp (verb, "pick")) {
            char short_id[41], subject[1024] = "";
            git_abbrev (ctx, id, 7, short_id, sizeof short_id);
            struct git_commit applied;
            if (git_commit_read (ctx, state.head, &applied) < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            git_subject (&applied, subject, sizeof subject);
            char author[1024];
            snprintf (author, sizeof author, "%s <%s> %s", applied.author_name,
                      applied.author_email, applied.author_date);
            char parent[41] = "";
            if (applied.n_parents) memcpy (parent, applied.parents[0], 41);
            char *message = strdup (applied.message);
            git_commit_release (&applied);
            if (!message) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }

            if (!strcmp (verb, "edit")) {
                git_rebase_state_files (ctx, head_name, onto, orig, done_count,
                                        total, content, sizeof content);
                snprintf (content, sizeof content, "%s\n", state.head);
                git_rebase_write (ctx, "amend", content);
                free (message);
                git_state_release (&state);
                fflush (stdout);
                fprintf (stderr, "Stopped at %s...  %s\n", short_id, subject);
                fprintf (stderr, "You can amend the commit now, with\n\n"
                                 "  git commit --amend \n\n"
                                 "Once you are satisfied with your changes, "
                                 "run\n\n  git rebase --continue\n");
                return 0;
            }

            if (!strcmp (verb, "reword")) {
                char *written = git_rebase_message_edit (ctx, &state, message,
                                                         NULL, 0, author);
                free (message);
                if (!written) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
                char reflog[1200];
                snprintf (reflog, sizeof reflog, "rebase (reword): %.200s",
                          written);
                int replaced = git_rebase_replace_head (ctx, &state, parent,
                                                        author, written,
                                                        reflog, quiet);
                free (written);
                if (replaced < 0) {
                    git_state_release (&state);
                    return GIT_EXIT_FATAL;
                }
                continue;
            }

            /* squash and fixup: the commit just applied goes into the one
               before it, and the two become one. */
            struct git_commit before;
            char base[41] = "", base_author[1024] = "";
            char *kept = NULL;
            if (!*parent || git_commit_read (ctx, parent, &before) < 0) {
                free (message);
                git_state_release (&state);
                return git_fatal ("cannot %s without a commit to meld into",
                                  verb);
            }
            if (before.n_parents) memcpy (base, before.parents[0], 41);
            snprintf (base_author, sizeof base_author, "%s <%s> %s",
                      before.author_name, before.author_email,
                      before.author_date);
            kept = strdup (before.message);
            git_commit_release (&before);
            if (!kept) {
                free (message);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            char *written = NULL;
            if (!strcmp (verb, "fixup"))
                written = strdup (kept);
            else
                written = git_rebase_message_edit (ctx, &state, kept, message,
                                                   1, base_author);
            free (kept);
            free (message);
            if (!written) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            char reflog[1200];
            snprintf (reflog, sizeof reflog, "rebase (%s): %.200s", verb,
                      written);
            int replaced = git_rebase_replace_head (ctx, &state, base,
                                                    base_author, written,
                                                    reflog,
                                                    quiet || !strcmp (verb, "fixup"));
            free (written);
            if (replaced < 0) {
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
            continue;
        }

        if (rc == 1) {
            char short_id[41], subject[1024] = "";
            git_abbrev (ctx, id, 7, short_id, sizeof short_id);
            struct git_commit picked;
            if (git_commit_read (ctx, id, &picked) == 0) {
                git_subject (&picked, subject, sizeof subject);
                snprintf (content, sizeof content, "%s", picked.message);
                git_rebase_write (ctx, "message", content);
                git_commit_release (&picked);
            }
            snprintf (content, sizeof content, "%s\n", id);
            git_rebase_write (ctx, "stopped-sha", content);
            git_write_state_file (ctx, "REBASE_HEAD", content);
            git_rebase_state_files (ctx, head_name, onto, orig, done_count,
                                    total, content, sizeof content);
            git_state_release (&state);
            fflush (stdout);
            fprintf (stderr, "error: could not apply %s... %s\n", short_id,
                     subject);
            fprintf (stderr, "hint: Resolve all conflicts manually, mark them "
                             "as resolved with\n");
            fprintf (stderr, "hint: \"git add/rm <conflicted_files>\", then run "
                             "\"git rebase --continue\".\n");
            fprintf (stderr, "hint: You can instead skip this commit: run "
                             "\"git rebase --skip\".\n");
            fprintf (stderr, "hint: To abort and get back to the state before "
                             "\"git rebase\", run \"git rebase --abort\".\n");
            fprintf (stderr, "Could not apply %s... %s\n", short_id, subject);
            return 1;
        }
    }

    /* Everything replayed: the branch follows HEAD and HEAD follows it. */
    if (!*head_name &&
        git_rebase_read (ctx, "head-name", head_name, sizeof head_name) < 0) {
        git_state_release (&state);
        return git_fatal ("cannot read the rebase state");
    }
    status = git_rebase_finish (ctx, &state, head_name, onto, quiet);
    git_state_release (&state);
    return status;
}

/* ---- merging over more than one base ------------------------------------ */

/* The tree two commits merge into, over their own base — which may itself
   have to be worked out this way. Two branches that have merged each other
   have two bases, and neither is the right one to compare against: git
   merges them into a base of its own making, conflicts and all, and the
   real merge is then held against that. Returns 0 with the tree. */
static int git_merge_to_tree (git_context *ctx, const char *ours,
                              const char *theirs, char out_tree[41]);

/* What a set of bases stands for: one tree, made by merging them. */
static int
git_base_tree (git_context *ctx, char (*bases)[41], size_t n_bases,
               char out_tree[41])
{
    if (!n_bases) return -1;
    if (n_bases == 1) return bgit_commit_tree (&ctx->odb, bases[0], out_tree);
    /* More than two are folded in one at a time, each fold standing as a
       commit of its own so that the next base has something to be held
       against. Such a commit is reachable from nothing and is left where
       it lies, as git leaves its own. */
    char carried[41];
    memcpy (carried, bases[0], 41);
    for (size_t i = 1; i < n_bases; i++) {
        char tree[41];
        if (git_merge_to_tree (ctx, carried, bases[i], tree) < 0) return -1;
        if (i + 1 == n_bases) {
            memcpy (out_tree, tree, 41);
            return 0;
        }
        char author[1024], committer[1024];
        if (bgit_ident (&ctx->cfg, 0, author, sizeof author) < 0 ||
            bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0)
            return -1;
        char *body = NULL;
        size_t body_len = 0;
        FILE *builder = open_memstream (&body, &body_len);
        if (!builder) return -1;
        fprintf (builder, "tree %s\nparent %s\nparent %s\nauthor %s\n"
                          "committer %s\n\nmerged common ancestors\n",
                 tree, carried, bases[i], author, committer);
        fclose (builder);
        int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                    (const unsigned char *) body, body_len, 1,
                                    carried);
        free (body);
        if (rc < 0) return -1;
    }
    return -1;
}

static int
git_merge_to_tree (git_context *ctx, const char *ours, const char *theirs,
                   char out_tree[41])
{
    char (*bases)[41] = NULL;
    size_t n_bases = 0;
    const char *twos[1] = { theirs };
    if (bgit_merge_bases_many (&ctx->odb, ours, twos, 1, &bases, &n_bases) < 0)
        return -1;
    char base_tree[41] = "";
    int have_base = n_bases && git_base_tree (ctx, bases, n_bases,
                                              base_tree) == 0;
    free (bases);

    char our_tree[41], their_tree[41];
    if (bgit_commit_tree (&ctx->odb, ours, our_tree) < 0 ||
        bgit_commit_tree (&ctx->odb, theirs, their_tree) < 0)
        return -1;
    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0],
                          have_base ? base_tree : NULL, our_tree, their_tree,
                          "ours", "theirs", &paths, &n_paths) < 0)
        return -1;

    /* Our side, with what the merge settled written over it. A path that
       did not settle keeps the text with the markers in it, which is what
       git's own made-up base holds. */
    bgit_index_entry *entries = NULL;
    size_t n_entries = 0, cap = 0;
    if (bgit_read_tree (&ctx->odb, our_tree, &entries, &n_entries) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        return -1;
    }
    cap = n_entries;
    int failed = 0;
    for (size_t i = 0; i < n_paths && !failed; i++) {
        bgit_merge_path *path = &paths[i];
        char sha[41];
        uint32_t mode = path->mode;
        if (path->kind == BGIT_MERGE_CLEAN && !path->mode) {
            bgit_index_remove_path (&entries, &n_entries, path->path);
            continue;
        }
        if (path->text) {
            if (bgit_write_object (ctx->odb.object_dirs[0], "blob",
                                   (const unsigned char *) path->text,
                                   path->len, 1, sha) < 0) {
                failed = 1;
                break;
            }
            if (!mode) mode = path->our_mode ? path->our_mode
                                             : path->their_mode;
        } else if (path->sha[0])
            memcpy (sha, path->sha, 41);
        else {
            bgit_index_remove_path (&entries, &n_entries, path->path);
            continue;
        }
        bgit_index_entry entry;
        memset (&entry, 0, sizeof entry);
        entry.mode = mode ? mode : 0100644;
        if (bgit_hex_to_sha (sha, entry.sha) < 0) { failed = 1; break; }
        size_t len = strlen (path->path);
        entry.flags = (uint16_t) (len > 0xFFF ? 0xFFF : len);
        entry.path = strdup (path->path);
        if (!entry.path ||
            git_index_put (&entries, &n_entries, &cap, &entry) < 0)
            failed = 1;
    }
    bgit_merge_paths_free (paths, n_paths);
    if (!failed && n_entries > 1)
        qsort (entries, n_entries, sizeof *entries, bgit_index_path_cmp);
    if (!failed)
        failed = bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], entries,
                                  n_entries, out_tree) < 0;
    bgit_index_free_entries (entries, n_entries);
    return failed ? -1 : 0;
}

/* ---- stash ------------------------------------------------------------- */

/* The untracked files a stash keeps with -u: what status would call
   untracked, each one written into the object store so that a tree can
   hold them. An ignored file is not one of them, as it is not for git. */
static int
git_stash_untracked (git_context *ctx, struct git_state *state,
                     bgit_index_entry **out, size_t *n_out)
{
    *out = NULL;
    *n_out = 0;
    bgit_status_entry *entries = NULL;
    size_t n = 0;
    if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, state->index,
                     state->n_index,
                     state->have_head ? state->head_tree : NULL,
                     1, 0, 0, &entries, &n) < 0)
        return -1;
    bgit_index_entry *kept = NULL;
    size_t n_kept = 0;
    for (size_t i = 0; i < n; i++) {
        if (!entries[i].untracked) continue;
        char full[4096];
        struct stat st;
        if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                      entries[i].path) >= (int) sizeof full ||
            lstat (full, &st) < 0 || S_ISDIR (st.st_mode))
            continue;
        unsigned char *content = NULL;
        size_t len = 0;
        if (S_ISLNK (st.st_mode)) {
            char target[4096];
            ssize_t got = readlink (full, target, sizeof target);
            if (got < 0) continue;
            content = malloc ((size_t) got ? (size_t) got : 1);
            if (!content) break;
            memcpy (content, target, (size_t) got);
            len = (size_t) got;
        } else if (bgit_slurp_file (full, &content, &len) < 0)
            continue;
        char id[41];
        int rc = bgit_write_object (ctx->odb.object_dirs[0], "blob", content,
                                    len, 1, id);
        free (content);
        if (rc < 0) continue;
        bgit_index_entry *grown = realloc (kept, (n_kept + 1) * sizeof *grown);
        if (!grown) break;
        kept = grown;
        bgit_index_entry *entry = &kept[n_kept];
        memset (entry, 0, sizeof *entry);
        entry->mode = bgit_worktree_mode (&st);
        if (bgit_hex_to_sha (id, entry->sha) < 0) continue;
        size_t plen = strlen (entries[i].path);
        entry->flags = (uint16_t) (plen > 0xFFF ? 0xFFF : plen);
        entry->path = strdup (entries[i].path);
        if (!entry->path) break;
        n_kept++;
    }
    bgit_status_free (entries, n);
    *out = kept;
    *n_out = n_kept;
    return 0;
}

/* Take a stashed untracked file out of the working tree, and the
   directory it left behind if nothing else is in it. */
static void
git_stash_sweep (git_context *ctx, const char *path)
{
    char full[4096];
    if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path) >=
        (int) sizeof full)
        return;
    unlink (full);
    char *slash;
    while ((slash = strrchr (full, '/')) != NULL) {
        *slash = '\0';
        if (strlen (full) <= strlen (ctx->repo.work_tree)) break;
        if (rmdir (full) < 0) break;        /* something else is in it */
    }
}

/* A stash is two commits: one for the index as it stood, and one for the
   working tree, whose parents are where HEAD was and that index commit.
   The stack of them is refs/stash's own reflog, which is why stash@{2} is
   just a revision. */
static int
git_stash_commit (git_context *ctx, const char *tree, const char *const *parents,
                  int n_parents, const char *message, int newline,
                  char out[41])
{
    char author[1024], committer[1024];
    if (bgit_ident (&ctx->cfg, 0, author, sizeof author) < 0 ||
        bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0)
        return git_fatal ("cannot determine the identity to use");
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) return -1;
    fprintf (builder, "tree %s\n", tree);
    for (int i = 0; i < n_parents; i++) fprintf (builder, "parent %s\n", parents[i]);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    /* git ends the index commit's message with a newline and the working
       tree commit's without one; the ids only match if this matches. */
    fprintf (builder, "\n%s%s", message, newline ? "\n" : "");
    fclose (builder);
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1, out);
    free (body);
    return rc;
}

/* "On main" or, with no branch, "on (no branch)" — the words git puts in
   front of every stash message. */
static void
git_stash_where (git_context *ctx, const struct git_state *state, char *out,
                 size_t outsz)
{
    (void) ctx;
    if (state->branch && !strncmp (state->branch, "refs/heads/", 11))
        snprintf (out, outsz, "%s", state->branch + 11);
    else
        snprintf (out, outsz, "(no branch)");
}

/* The stash stack, newest first, read from refs/stash's reflog. */
static int
git_stash_entries (git_context *ctx, char ***out, size_t *n_out)
{
    char **lines = NULL;
    size_t n = 0;
    if (bgit_reflog_lines (&ctx->repo, "refs/stash", &lines, &n) < 0) {
        *out = NULL;
        *n_out = 0;
        return 0;
    }
    *out = lines;
    *n_out = n;
    return 0;
}

/* What one reflog line says: the id it recorded and the message. */
static void
git_stash_split (const char *line, char id[41], const char **message)
{
    id[0] = '\0';
    *message = "";
    const char *space = strchr (line, ' ');
    if (!space || space - line < 40) return;
    memcpy (id, space + 1, 40);
    id[40] = '\0';
    const char *tab = strchr (line, '\t');
    if (tab) *message = tab + 1;
}

static int
git_cmd_stash (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git stash [push] [-m <message>] [-u] [-q] | list | "
                        "show [-p] [<stash>] | apply [<stash>] | pop "
                        "[<stash>] | drop [<stash>] | clear";
    const char *verb = "push", *message = NULL, *which = NULL;
    int quiet = 0, patch = 0, stat_only = 0, include_untracked = 0;
    int first = 1;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (first && (!strcmp (w, "push") || !strcmp (w, "save") ||
                      !strcmp (w, "list") || !strcmp (w, "show") ||
                      !strcmp (w, "apply") || !strcmp (w, "pop") ||
                      !strcmp (w, "drop") || !strcmp (w, "clear"))) {
            verb = !strcmp (w, "save") ? "push" : w;
            first = 0;
            continue;
        }
        first = 0;
        if (!strcmp (w, "-m") && p->next) { message = p->next->word->word; p = p->next; }
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-p") || !strcmp (w, "--patch")) patch = 1;
        else if (!strcmp (w, "--stat")) stat_only = 1;
        else if (!strcmp (w, "-u") || !strcmp (w, "--include-untracked"))
            include_untracked = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!which) which = w;
        else return git_usage (usage);
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int status = 0;

    if (!strcmp (verb, "list")) {
        char **lines = NULL;
        size_t n = 0;
        git_stash_entries (ctx, &lines, &n);
        for (size_t i = 0; i < n; i++) {
            char id[41];
            const char *text = "";
            git_stash_split (lines[n - 1 - i], id, &text);
            printf ("stash@{%zu}: %s\n", i, text);
        }
        for (size_t i = 0; i < n; i++) free (lines[i]);
        free (lines);
        git_state_release (&state);
        return 0;
    }

    if (!strcmp (verb, "clear")) {
        char log_path[4096], existing[41];
        /* Clearing nothing is not an error, and says nothing. */
        if (bgit_ref_read (&ctx->repo, "refs/stash", existing) == 0)
            bgit_ref_delete (&ctx->repo, "refs/stash", NULL, NULL);
        if (snprintf (log_path, sizeof log_path, "%s/logs/refs/stash",
                      ctx->repo.common_dir) < (int) sizeof log_path)
            unlink (log_path);
        git_state_release (&state);
        return 0;
    }

    if (!strcmp (verb, "push")) {
        if (!state.have_head) {
            git_state_release (&state);
            return git_fatal ("You do not have the initial commit yet");
        }
        /* Nothing changed means nothing to save. */
        bgit_diff_entry *changes = NULL;
        size_t n_changes = 0;
        bgit_index_entry *head_entries = NULL;
        size_t n_head = 0;
        if (bgit_read_tree (&ctx->odb, state.head_tree, &head_entries, &n_head) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        bgit_index_entry *working = NULL;
        size_t n_working = 0;
        if (bgit_worktree_entries (&ctx->repo, &ctx->odb, ctx->odb.object_dirs[0],
                                   state.index, state.n_index, &working,
                                   &n_working) < 0 ||
            bgit_diff_entries (head_entries, n_head, working, n_working,
                               &changes, &n_changes) < 0) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        int dirty = n_changes > 0;
        bgit_diff_free (changes, n_changes);
        /* With -u the untracked files are part of what is saved, so their
           being there is reason enough to save. */
        bgit_index_entry *untracked = NULL;
        size_t n_untracked = 0;
        if (include_untracked &&
            git_stash_untracked (ctx, &state, &untracked, &n_untracked) < 0) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        dirty = dirty || n_untracked > 0;
        if (!dirty) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            printf ("No local changes to save\n");
            return 0;
        }

        char branch[256];
        git_stash_where (ctx, &state, branch, sizeof branch);
        struct git_commit head_commit;
        char head_subject[1024] = "", head_short[41];
        if (git_commit_read (ctx, state.head, &head_commit) == 0) {
            git_subject (&head_commit, head_subject, sizeof head_subject);
            git_commit_release (&head_commit);
        }
        git_abbrev (ctx, state.head, 7, head_short, sizeof head_short);

        /* The index as it stands, then the working tree over it. */
        char index_tree[41], work_tree[41];
        if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                             state.n_index, index_tree) < 0 ||
            bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], working,
                             n_working, work_tree) < 0) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        char index_message[1200], work_message[1200];
        snprintf (index_message, sizeof index_message, "index on %s: %s %s",
                  branch, head_short, head_subject);
        if (message)
            snprintf (work_message, sizeof work_message, "On %s: %s", branch,
                      message);
        else
            snprintf (work_message, sizeof work_message, "WIP on %s: %s %s",
                      branch, head_short, head_subject);

        char index_commit[41], work_commit[41];
        const char *index_parents[1] = { state.head };
        if (git_stash_commit (ctx, index_tree, index_parents, 1, index_message,
                              1, index_commit) < 0) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        /* The untracked files are a commit of their own, with no parent,
           and the stash's third — which is how git marks that it has
           them. */
        char untracked_commit[41] = "";
        if (n_untracked) {
            char untracked_tree[41], untracked_message[1200];
            snprintf (untracked_message, sizeof untracked_message,
                      "untracked files on %s: %s %s", branch, head_short,
                      head_subject);
            if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], untracked,
                                 n_untracked, untracked_tree) < 0 ||
                git_stash_commit (ctx, untracked_tree, NULL, 0,
                                  untracked_message, 1, untracked_commit) < 0) {
                bgit_index_free_entries (head_entries, n_head);
                bgit_index_free_entries (working, n_working);
                bgit_index_free_entries (untracked, n_untracked);
                git_state_release (&state);
                return GIT_EXIT_FATAL;
            }
        }
        const char *work_parents[3] = { state.head, index_commit,
                                        untracked_commit };
        if (git_stash_commit (ctx, work_tree, work_parents,
                              n_untracked ? 3 : 2, work_message,
                              0, work_commit) < 0) {
            bgit_index_free_entries (head_entries, n_head);
            bgit_index_free_entries (working, n_working);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        if (bgit_ref_update (&ctx->repo, "refs/stash", work_commit, NULL,
                             work_message) < 0)
            status = GIT_EXIT_FATAL;

        /* The working tree and index go back to HEAD; untracked files stay. */
        if (!status &&
            (bgit_checkout_tree (&ctx->repo, &ctx->odb, state.head_tree,
                                 &state.index, &state.n_index, 1, NULL) < 0 ||
             git_index_store (ctx, state.index, state.n_index) < 0))
            status = GIT_EXIT_FATAL;
        /* Putting the tree back is a hard reset, and HEAD's log says so. */
        if (!status)
            bgit_reflog_append (&ctx->repo, "HEAD", state.head, state.head,
                                "reset: moving to HEAD");
        /* What was saved as untracked is taken out of the working tree, and
           a directory left empty goes with it. */
        for (size_t i = 0; !status && i < n_untracked; i++)
            git_stash_sweep (ctx, untracked[i].path);
        bgit_index_free_entries (untracked, n_untracked);
        bgit_index_free_entries (head_entries, n_head);
        bgit_index_free_entries (working, n_working);
        if (!status && !quiet)
            printf ("Saved working directory and index state %s\n", work_message);
        git_state_release (&state);
        return status;
    }

    /* The rest work on one entry of the stack. */
    char **lines = NULL;
    size_t n_lines = 0;
    git_stash_entries (ctx, &lines, &n_lines);
    if (!n_lines) {
        free (lines);
        git_state_release (&state);
        return git_fatal ("No stash entries found.");
    }
    size_t wanted = 0;
    if (which) {
        const char *brace = strstr (which, "@{");
        if (brace) wanted = (size_t) strtoul (brace + 2, NULL, 10);
        else if (git_all_digits (which)) wanted = (size_t) strtoul (which, NULL, 10);
    }
    if (wanted >= n_lines) {
        for (size_t i = 0; i < n_lines; i++) free (lines[i]);
        free (lines);
        git_state_release (&state);
        return git_fatal ("%s is not a valid reference",
                          which ? which : "stash@{0}");
    }
    char stash_id[41];
    const char *stash_message = "";
    git_stash_split (lines[n_lines - 1 - wanted], stash_id, &stash_message);
    char kept_message[1200];
    snprintf (kept_message, sizeof kept_message, "%s", stash_message);
    for (size_t i = 0; i < n_lines; i++) free (lines[i]);
    free (lines);

    struct git_commit stash;
    if (git_commit_read (ctx, stash_id, &stash) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    if (!strcmp (verb, "show")) {
        char base_tree[41] = "";
        if (stash.n_parents &&
            bgit_commit_tree (&ctx->odb, stash.parents[0], base_tree) < 0) {
            git_commit_release (&stash);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        bgit_diff_entry *entries = NULL;
        size_t n = 0;
        if (bgit_diff_trees (&ctx->odb, stash.n_parents ? base_tree : NULL,
                             stash.tree, &entries, &n) < 0) {
            git_commit_release (&stash);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        struct git_diff_format format;
        git_diff_format_init (&format);
        if (patch) format.patch = 1;
        else format.stat = 1;
        (void) stat_only;
        git_diff_emit (ctx, stdout, &format, entries, n, 0, "");
        bgit_diff_free (entries, n);
        git_commit_release (&stash);
        git_state_release (&state);
        return 0;
    }

    if (!strcmp (verb, "drop")) {
        if (bgit_reflog_drop (&ctx->repo, "refs/stash", wanted) < 0)
            status = GIT_EXIT_FATAL;
        if (!status && !quiet)
            printf ("Dropped refs/stash@{%zu} (%s)\n", wanted, stash_id);
        git_commit_release (&stash);
        git_state_release (&state);
        return status;
    }

    if (strcmp (verb, "apply") && strcmp (verb, "pop")) {
        git_commit_release (&stash);
        git_state_release (&state);
        return git_usage (usage);
    }

    /* Applying is a three-way merge: what the stash changed against where
       it was taken, brought onto what is here now. */
    char base_tree[41] = "", our_tree[41];
    if ((stash.n_parents &&
         bgit_commit_tree (&ctx->odb, stash.parents[0], base_tree) < 0) ||
        bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                         state.n_index, our_tree) < 0) {
        git_commit_release (&stash);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0],
                          stash.n_parents ? base_tree : NULL, our_tree,
                          stash.tree, "Updated upstream", "Stashed changes",
                          &paths, &n_paths) < 0) {
        git_commit_release (&stash);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    /* A tree that would lose work is left alone — but the stash may still
       carry untracked files, and git puts those back and says where it
       stands either way. */
    int refused = git_merge_safe (ctx, &state, paths, n_paths) < 0;
    int conflicts = 0;
    for (size_t i = 0; !refused && i < n_paths; i++) {
        const bgit_merge_path *path = &paths[i];
        if (path->kind == BGIT_MERGE_AUTO || path->kind == BGIT_MERGE_CONTENT ||
            path->kind == BGIT_MERGE_ADD_ADD)
            printf ("Auto-merging %s\n", path->path);
        if (path->kind == BGIT_MERGE_CONTENT) {
            conflicts++;
            printf ("CONFLICT (content): Merge conflict in %s\n", path->path);
        } else if (path->kind == BGIT_MERGE_ADD_ADD) {
            conflicts++;
            printf ("CONFLICT (add/add): Merge conflict in %s\n", path->path);
        } else if (path->kind == BGIT_MERGE_MODIFY_DELETE) {
            conflicts++;
            printf ("CONFLICT (modify/delete): %s deleted in %s and modified "
                    "in %s.  Version %s of %s left in tree.\n", path->path,
                    path->deleted_in_ours ? "Updated upstream" : "Stashed changes",
                    path->deleted_in_ours ? "Stashed changes" : "Updated upstream",
                    path->deleted_in_ours ? "Stashed changes" : "Updated upstream",
                    path->path);
        }
    }
    if (!refused && git_merge_apply (ctx, &state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&stash);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    /* A stash taken with -u carries a third parent: the untracked files as
       they stood. They come back where nothing stands in their way, and
       what does is named rather than written over. */
    int untracked_lost = 0;
    if (stash.n_parents >= 3) {
        char untracked_tree[41];
        bgit_index_entry *files = NULL;
        size_t n_files = 0;
        if (bgit_commit_tree (&ctx->odb, stash.parents[2], untracked_tree) == 0 &&
            bgit_read_tree (&ctx->odb, untracked_tree, &files, &n_files) == 0) {
            for (size_t i = 0; i < n_files; i++) {
                char full[4096];
                struct stat st;
                if (snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                              files[i].path) >= (int) sizeof full)
                    continue;
                if (lstat (full, &st) == 0) {
                    fflush (stdout);
                    fprintf (stderr, "%s already exists, no checkout\n",
                             files[i].path);
                    untracked_lost = 1;
                    continue;
                }
                char sha[41];
                bgit_sha_to_hex (files[i].sha, sha);
                if (bgit_checkout_file (&ctx->odb, full, sha,
                                        files[i].mode) < 0)
                    untracked_lost = 1;
            }
            bgit_index_free_entries (files, n_files);
        }
        if (untracked_lost) {
            fflush (stdout);
            fprintf (stderr, "error: could not restore untracked files from "
                             "stash\n");
        }
    }

    /* Without --index the changes come back unstaged: a path HEAD knows is
       put back as HEAD has it, and only what HEAD never had stays staged. */
    if (!conflicts && !refused) {
        bgit_index_entry *head_entries = NULL;
        size_t n_head = 0;
        if (bgit_read_tree (&ctx->odb, state.head_tree, &head_entries,
                            &n_head) == 0) {
            for (size_t i = 0; i < state.n_index; i++) {
                for (size_t j = 0; j < n_head; j++) {
                    if (strcmp (state.index[i].path, head_entries[j].path)) continue;
                    memcpy (state.index[i].sha, head_entries[j].sha, 20);
                    state.index[i].mode = head_entries[j].mode;
                    break;
                }
            }
            bgit_index_free_entries (head_entries, n_head);
            if (git_index_store (ctx, state.index, state.n_index) < 0)
                status = GIT_EXIT_FATAL;
        }
    }

    if (!status && !quiet) {
        bgit_status_entry *entries = NULL;
        size_t n = 0;
        struct git_state fresh;
        if (git_state_load (ctx, &fresh) == 0) {
            if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, fresh.index,
                             fresh.n_index, fresh.have_head ? fresh.head_tree : NULL,
                             0, 0, 1, &entries, &n) == 0) {
                const char *branch_name = fresh.branch;
                if (branch_name && !strncmp (branch_name, "refs/heads/", 11))
                    branch_name += 11;
                git_status_long (ctx, &fresh, entries, n, branch_name, 0, 0);
                bgit_status_free (entries, n);
            }
            git_state_release (&fresh);
        }
    }

    int held = conflicts || untracked_lost || refused;
    if (!held && !strcmp (verb, "pop")) {
        if (bgit_reflog_drop (&ctx->repo, "refs/stash", wanted) < 0)
            status = GIT_EXIT_FATAL;
        else if (!quiet)
            printf ("Dropped refs/stash@{%zu} (%s)\n", wanted, stash_id);
    } else if (held && !strcmp (verb, "pop"))
        printf ("The stash entry is kept in case you need it again.\n");
    bgit_merge_paths_free (paths, n_paths);
    git_commit_release (&stash);
    git_state_release (&state);
    return status ? status : (held ? 1 : 0);
}

/* ---- submodules --------------------------------------------------------- */

struct git_submodule {
    char name[256];
    char path[4096];
    char url[4096];      /* as .gitmodules writes it, which may be relative */
    char sha[41];        /* the commit the index records */
};

/* Every submodule this repository has: a gitlink in the index, with the
   name and url .gitmodules gives it. A gitlink that .gitmodules says
   nothing about keeps its path for a name, which is git's fallback too. */
static int
git_submodules (git_context *ctx, struct git_state *state,
                struct git_submodule **out, size_t *n_out)
{
    *out = NULL;
    *n_out = 0;
    bgit_config modules;
    memset (&modules, 0, sizeof modules);
    char where[4096];
    if (ctx->repo.work_tree &&
        snprintf (where, sizeof where, "%s/.gitmodules",
                  ctx->repo.work_tree) < (int) sizeof where)
        bgit_config_read_file (&modules, where, 2);

    struct git_submodule *subs = NULL;
    size_t n = 0;
    for (size_t i = 0; i < state->n_index; i++) {
        if (state->index[i].mode != 0160000) continue;
        struct git_submodule *grown = realloc (subs, (n + 1) * sizeof *grown);
        if (!grown) {
            free (subs);
            bgit_config_release (&modules);
            return -1;
        }
        subs = grown;
        struct git_submodule *sub = &subs[n++];
        memset (sub, 0, sizeof *sub);
        snprintf (sub->path, sizeof sub->path, "%s", state->index[i].path);
        snprintf (sub->name, sizeof sub->name, "%s", state->index[i].path);
        bgit_sha_to_hex (state->index[i].sha, sub->sha);
        /* Whichever section names this path names the submodule. */
        for (size_t k = 0; k < modules.n; k++) {
            const char *key = modules.entries[k].key;
            size_t len = strlen (key);
            if (strncmp (key, "submodule.", 10) || len <= 15 ||
                strcmp (key + len - 5, ".path") ||
                !modules.entries[k].value ||
                strcmp (modules.entries[k].value, sub->path))
                continue;
            size_t name_len = len - 15;
            if (name_len >= sizeof sub->name) continue;
            memcpy (sub->name, key + 10, name_len);
            sub->name[name_len] = '\0';
        }
        char key[4400];
        snprintf (key, sizeof key, "submodule.%s.url", sub->name);
        const char *url = bgit_config_get (&modules, key);
        if (url) snprintf (sub->url, sizeof sub->url, "%s", url);
    }
    bgit_config_release (&modules);
    *out = subs;
    *n_out = n;
    return 0;
}

/* Was this submodule asked for? With no paths named, all of them were. */
static int
git_submodule_wanted (const struct git_submodule *sub,
                      const char *const *paths, int n_paths)
{
    if (!n_paths) return 1;
    for (int i = 0; i < n_paths; i++)
        if (!strcmp (paths[i], sub->path) ||
            (!strncmp (sub->path, paths[i], strlen (paths[i])) &&
             sub->path[strlen (paths[i])] == '/'))
            return 1;
    return 0;
}

/* A url in .gitmodules may be relative to where the superproject itself
   came from: ./x and ../x are resolved against remote.origin.url, and
   against the superproject's own directory when it has no origin. */
static void
git_submodule_url_maybe (git_context *ctx, const char *url, char *out,
                         size_t outsz, int say)
{
    if (strncmp (url, "./", 2) && strncmp (url, "../", 3)) {
        snprintf (out, outsz, "%s", url);
        return;
    }
    const char *origin = bgit_config_get (&ctx->cfg, "remote.origin.url");
    if (!origin && say) {
        /* git says this out loud, since where a relative url points then
           depends on where this repository happens to sit. */
        fflush (stdout);
        fprintf (stderr, "warning: could not look up configuration "
                         "'remote.origin.url'. Assuming this repository is "
                         "its own authoritative upstream.\n");
    }
    char base[4096];
    snprintf (base, sizeof base, "%s",
              origin ? origin : (ctx->repo.work_tree ? ctx->repo.work_tree : "."));
    size_t len = strlen (base);
    while (len > 1 && base[len - 1] == '/') base[--len] = '\0';
    const char *rest = url;
    for (;;) {
        if (!strncmp (rest, "./", 2)) { rest += 2; continue; }
        if (strncmp (rest, "../", 3)) break;
        rest += 3;
        char *slash = strrchr (base, '/');
        if (slash && slash != base) *slash = '\0';
        else if (slash) slash[1] = '\0';
    }
    snprintf (out, outsz, "%s/%s", base, rest);
}

static void
git_submodule_url (git_context *ctx, const char *url, char *out, size_t outsz)
{
    git_submodule_url_maybe (ctx, url, out, outsz, 1);
}

/* What `git describe --all --always` would call COMMIT over there: the
   nearest ref that has it, and how far back it is. That is what git puts
   in brackets after a submodule's path. Only the form `--all` gives is
   made here; a repository with tags in it would have git reach for the
   tag first. */
static int
git_describe_in (const char *repo_path, const char *commit, char *out,
                 size_t outsz)
{
    bgit_repo repo;
    bgit_odb odb;
    if (git_open_remote (repo_path, &repo, &odb) < 0) return -1;
    bgit_ref *refs = NULL;
    size_t n_refs = 0;
    bgit_refs_list (&repo, "refs/", &refs, &n_refs);

    char (*seen)[41] = NULL;
    int *depths = NULL;
    size_t n_seen = 0, at = 0;
    int found = -1;
    const char *name = NULL;
    int distance = 0;
    for (;;) {
        if (at == n_seen) {
            if (!at) {
                seen = malloc (sizeof *seen);
                depths = malloc (sizeof *depths);
                if (!seen || !depths) break;
                snprintf (seen[0], 41, "%s", commit);
                depths[0] = 0;
                n_seen = 1;
            } else break;
        }
        if (at >= n_seen || n_seen > 4096) break;
        const char *current = seen[at];
        int depth = depths[at];
        /* A tag naming it beats a branch, and a branch beats the rest,
           which is the order git looks in. */
        for (int rank = 0; rank < 3 && found < 0; rank++) {
            const char *prefix = rank == 0 ? "refs/tags/"
                               : rank == 1 ? "refs/heads/" : "refs/";
            for (size_t i = 0; i < n_refs; i++) {
                if (strncmp (refs[i].name, prefix, strlen (prefix))) continue;
                if (strcmp (refs[i].sha, current)) continue;
                name = refs[i].name + 5;      /* past "refs/" */
                distance = depth;
                found = 1;
                break;
            }
        }
        if (found > 0) break;
        char parents[BGIT_MAX_PARENTS][41];
        int n_parents = bgit_commit_parents (&odb, current, parents,
                                             BGIT_MAX_PARENTS);
        for (int i = 0; i < n_parents; i++) {
            int known = 0;
            for (size_t k = 0; k < n_seen && !known; k++)
                if (!strcmp (seen[k], parents[i])) known = 1;
            if (known) continue;
            char (*grown)[41] = realloc (seen, (n_seen + 1) * sizeof *seen);
            int *grown_depths = realloc (depths, (n_seen + 1) * sizeof *depths);
            if (grown) seen = grown;
            if (grown_depths) depths = grown_depths;
            if (!grown || !grown_depths) { n_seen = at + 1; break; }
            snprintf (seen[n_seen], 41, "%s", parents[i]);
            depths[n_seen] = depth + 1;
            n_seen++;
        }
        at++;
    }
    if (found > 0) {
        if (!distance) snprintf (out, outsz, "%s", name);
        else snprintf (out, outsz, "%s-%d-g%.7s", name, distance, commit);
    } else
        snprintf (out, outsz, "%.7s", commit);
    free (seen);
    free (depths);
    bgit_refs_free (refs, n_refs);
    bgit_odb_release (&odb);
    bgit_repo_release (&repo);
    return 0;
}

/* Run this build's own git in another directory, as a child: a submodule
   is another repository, and a command for it wants a context of its own.
   Returns the status, or -1. */
static int
git_run_in (const char *directory, const char *const *args, int n_args)
{
    fflush (stdout);
    fflush (stderr);
    pid_t child = fork ();
    if (child < 0) return -1;
    if (!child) {
        git_restore_caller_pipe ();
        char **env = git_far_environ ();
        const char *argv[24];
        int at = 0;
        argv[at++] = "bash";
        argv[at++] = "--noprofile";
        argv[at++] = "--norc";
        argv[at++] = "-c";
        argv[at++] = "builtin git \"$@\"";
        argv[at++] = "git";
        argv[at++] = "-C";
        argv[at++] = directory;
        for (int i = 0; i < n_args && at < 23; i++) argv[at++] = args[i];
        argv[at] = NULL;
        execve ("/proc/self/exe", (char *const *) argv, env);
        _exit (127);
    }
    int status = 0;
    while (waitpid (child, &status, 0) < 0 && errno == EINTR) ;
    return WIFEXITED (status) ? WEXITSTATUS (status) : -1;
}

static int
git_submodule_status (git_context *ctx, struct git_state *state, int cached,
                      const char *const *paths, int n_paths)
{
    struct git_submodule *subs = NULL;
    size_t n = 0;
    if (git_submodules (ctx, state, &subs, &n) < 0) return GIT_EXIT_FATAL;
    for (size_t i = 0; i < n; i++) {
        if (!git_submodule_wanted (&subs[i], paths, n_paths)) continue;
        char full[4096], head[41];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                  subs[i].path);
        if (bgit_submodule_head (full, head) < 0) {
            /* Nothing checked out there: git says so with a minus. */
            printf ("-%s %s\n", subs[i].sha, subs[i].path);
            continue;
        }
        const char *shown = cached ? subs[i].sha : head;
        char described[256];
        if (git_describe_in (full, shown, described, sizeof described) < 0)
            described[0] = '\0';
        printf ("%c%s %s", strcmp (head, subs[i].sha) ? '+' : ' ', shown,
                subs[i].path);
        if (described[0]) printf (" (%s)", described);
        printf ("\n");
    }
    free (subs);
    return 0;
}

/* Write submodule.<name>.url into this repository's own configuration,
   which is what tells update where to clone from. */
static int
git_submodule_register (git_context *ctx, const struct git_submodule *sub,
                        int quiet, char *resolved_out, size_t outsz)
{
    if (!sub->url[0]) {
        git_fatal ("No url found for submodule path '%s' in .gitmodules",
                   sub->path);
        return -1;
    }
    char resolved[4096];
    git_submodule_url (ctx, sub->url, resolved, sizeof resolved);
    char key[4400];
    snprintf (key, sizeof key, "submodule.%s.url", sub->name);
    char config_path[4096];
    snprintf (config_path, sizeof config_path, "%s/config", ctx->repo.git_dir);
    if (bgit_config_set_file (config_path, key, resolved, 0) < 0) return -1;
    snprintf (key, sizeof key, "submodule.%s.active", sub->name);
    if (bgit_config_set_file (config_path, key, "true", 0) < 0) return -1;
    if (!quiet) {
        fflush (stdout);
        fprintf (stderr, "Submodule '%s' (%s) registered for path '%s'\n",
                 sub->name, resolved, sub->path);
    }
    if (resolved_out) snprintf (resolved_out, outsz, "%s", resolved);
    return 0;
}

/* Where a submodule's git directory belongs once it is cloned, and the
   pairing between the two halves on its own. */
static int git_submodule_relocate (git_context *ctx,
                                   const struct git_submodule *sub);
static int git_submodule_link (git_context *ctx,
                               const struct git_submodule *sub);

/* Everything under a directory, taken away. The directory itself stays,
   which is what git leaves where a submodule was. Returns 0, or -1. */
static int
git_empty_directory (const char *path)
{
    DIR *dir = opendir (path);
    if (!dir) return -1;
    struct dirent *entry;
    int failed = 0;
    while ((entry = readdir (dir))) {
        if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, "..")) continue;
        char full[4096];
        if (snprintf (full, sizeof full, "%s/%s", path, entry->d_name) >=
            (int) sizeof full) {
            failed = 1;
            continue;
        }
        struct stat st;
        if (lstat (full, &st) < 0) { failed = 1; continue; }
        if (S_ISDIR (st.st_mode)) {
            if (git_empty_directory (full) < 0 || rmdir (full) < 0) failed = 1;
        } else if (unlink (full) < 0)
            failed = 1;
    }
    closedir (dir);
    return failed ? -1 : 0;
}

/* Take a repository in as a submodule: clone it where it is to live, write
   it down in .gitmodules, say here where it really came from, and stage
   both the file and the gitlink. */
static int
git_submodule_add (git_context *ctx, struct git_state *state, const char *url,
                   const char *given, int quiet)
{
    char path[4096];
    if (given) snprintf (path, sizeof path, "%s", given);
    else {
        /* The last part of the url, without the .git a bare one carries. */
        const char *base = strrchr (url, '/');
        base = base ? base + 1 : url;
        snprintf (path, sizeof path, "%s", base);
        size_t len = strlen (path);
        if (len > 4 && !strcmp (path + len - 4, ".git")) path[len - 4] = '\0';
    }
    size_t len = strlen (path);
    while (len && path[len - 1] == '/') path[--len] = '\0';
    if (!len) return git_fatal ("repo URL: '%s' must be absolute or begin with "
                               "./|../", url);
    for (size_t i = 0; i < state->n_index; i++)
        if (!strcmp (state->index[i].path, path))
            return git_fatal ("'%s' already exists in the index", path);

    char full[4096];
    snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree, path);
    if (!quiet) {
        fflush (stdout);
        fprintf (stderr, "Cloning into '%s'...\ndone.\n", full);
    }
    const char *clone_args[4] = { "clone", "-q", url, path };
    struct git_submodule sub;
    memset (&sub, 0, sizeof sub);
    snprintf (sub.name, sizeof sub.name, "%s", path);
    snprintf (sub.path, sizeof sub.path, "%s", path);
    snprintf (sub.url, sizeof sub.url, "%s", url);
    if (git_run_in (ctx->repo.work_tree, clone_args, 4) != 0 ||
        git_submodule_relocate (ctx, &sub) < 0)
        return git_fatal ("clone of '%s' into submodule path '%s' failed",
                          url, full);

    /* What it is called and where it came from, for whoever clones this
       repository next; the url stays as it was given, relative and all. */
    char modules[4096], key[4400];
    snprintf (modules, sizeof modules, "%s/.gitmodules", ctx->repo.work_tree);
    snprintf (key, sizeof key, "submodule.%s.path", sub.name);
    if (bgit_config_set_file (modules, key, sub.path, 0) < 0) return -1;
    snprintf (key, sizeof key, "submodule.%s.url", sub.name);
    if (bgit_config_set_file (modules, key, sub.url, 0) < 0) return -1;

    /* And where it really is, which is this repository's own business. */
    char resolved[4096], config_path[4096];
    git_submodule_url_maybe (ctx, sub.url, resolved, sizeof resolved, 0);
    snprintf (config_path, sizeof config_path, "%s/config", ctx->repo.git_dir);
    snprintf (key, sizeof key, "submodule.%s.url", sub.name);
    if (bgit_config_set_file (config_path, key, resolved, 0) < 0) return -1;
    snprintf (key, sizeof key, "submodule.%s.active", sub.name);
    if (bgit_config_set_file (config_path, key, "true", 0) < 0) return -1;

    const char *add_args[5] = { "add", "--no-warn-embedded-repo", "--",
                                ".gitmodules", sub.path };
    if (git_run_in (ctx->repo.work_tree, add_args, 5) != 0)
        return git_fatal ("Failed to add submodule '%s'", sub.path);
    return 0;
}

/* Undo what init did: empty the working tree of the submodule and forget
   where it came from. What is under .git/modules stays, so that taking it
   up again costs nothing. */
static int
git_submodule_deinit (git_context *ctx, struct git_state *state, int force,
                      int all, const char *const *paths, int n_paths)
{
    if (!all && !n_paths)
        return git_fatal ("Use '--all' if you really want to deinitialize all "
                          "submodules");
    struct git_submodule *subs = NULL;
    size_t n = 0;
    if (git_submodules (ctx, state, &subs, &n) < 0) return GIT_EXIT_FATAL;
    /* A path that names no submodule is git's usual complaint. */
    for (int i = 0; i < n_paths; i++) {
        int known = 0;
        for (size_t k = 0; k < n && !known; k++)
            if (!strcmp (subs[k].path, paths[i])) known = 1;
        if (!known) {
            free (subs);
            fflush (stdout);
            fprintf (stderr, "error: pathspec '%s' did not match any file(s) "
                             "known to git\n", paths[i]);
            return 1;
        }
    }

    int status = 0;
    char config_path[4096];
    snprintf (config_path, sizeof config_path, "%s/config", ctx->repo.git_dir);
    for (size_t i = 0; i < n && !status; i++) {
        if (!all && !git_submodule_wanted (&subs[i], paths, n_paths)) continue;
        char full[4096];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                  subs[i].path);
        char head[41];
        int there = bgit_submodule_head (full, head) == 0;
        if (there && !force) {
            int changed = 0, untracked = 0;
            bgit_submodule_dirt (full, &changed, &untracked);
            if (changed || untracked || strcmp (head, subs[i].sha)) {
                fflush (stdout);
                fprintf (stderr, "error: the following file has local "
                                 "modifications:\n    %s\n(use --cached to keep "
                                 "the file, or -f to force removal)\n",
                         subs[i].path);
                status = git_fatal ("Submodule work tree '%s' contains local "
                                    "modifications; use '-f' to discard them",
                                    subs[i].path);
                break;
            }
        }
        if (there && git_empty_directory (full) < 0) {
            status = git_fatal ("could not empty '%s'", subs[i].path);
            break;
        }
        if (there) printf ("Cleared directory '%s'\n", subs[i].path);
        char key[4400];
        snprintf (key, sizeof key, "submodule.%s.url", subs[i].name);
        bgit_config_unset_file (config_path, key);
        snprintf (key, sizeof key, "submodule.%s.active", subs[i].name);
        bgit_config_unset_file (config_path, key);
        printf ("Submodule '%s' (%s) unregistered for path '%s'\n",
                subs[i].name, subs[i].url, subs[i].path);
    }
    free (subs);
    return status;
}

/* Run a command in each submodule that is there, with the same handful of
   variables set that git sets. */
static int
git_submodule_foreach (git_context *ctx, struct git_state *state,
                       const char *command, int quiet)
{
    struct git_submodule *subs = NULL;
    size_t n = 0;
    if (git_submodules (ctx, state, &subs, &n) < 0) return GIT_EXIT_FATAL;
    int status = 0;
    for (size_t i = 0; i < n && !status; i++) {
        char full[4096], head[41];
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                  subs[i].path);
        if (bgit_submodule_head (full, head) < 0) continue;   /* not there */
        if (!quiet) printf ("Entering '%s'\n", subs[i].path);
        char quoted_dir[8192], quoted_name[8192], quoted_path[8192];
        char quoted_top[8192], script[65536];
        git_sq_quote (full, quoted_dir, sizeof quoted_dir);
        git_sq_quote (subs[i].name, quoted_name, sizeof quoted_name);
        git_sq_quote (subs[i].path, quoted_path, sizeof quoted_path);
        git_sq_quote (ctx->repo.work_tree, quoted_top, sizeof quoted_top);
        snprintf (script, sizeof script,
                  "cd %s || exit 1; name=%s; sm_path=%s; displaypath=%s; "
                  "sha1=%s; toplevel=%s; "
                  "export name sm_path displaypath sha1 toplevel; %s",
                  quoted_dir, quoted_name, quoted_path, quoted_path,
                  subs[i].sha, quoted_top, command);
        fflush (stdout);
        int rc = git_run_shell (script);
        if (rc != 0) {
            fflush (stdout);
            fprintf (stderr, "fatal: run_command returned non-zero status for "
                             "%s\n.\n", subs[i].path);
            status = GIT_EXIT_FATAL;
        }
    }
    free (subs);
    return status;
}

static int
git_submodule_init (git_context *ctx, struct git_state *state, int quiet,
                    const char *const *paths, int n_paths)
{
    struct git_submodule *subs = NULL;
    size_t n = 0;
    if (git_submodules (ctx, state, &subs, &n) < 0) return GIT_EXIT_FATAL;
    int status = 0;
    for (size_t i = 0; i < n && !status; i++) {
        if (!git_submodule_wanted (&subs[i], paths, n_paths)) continue;
        char key[4400];
        snprintf (key, sizeof key, "submodule.%s.url", subs[i].name);
        if (bgit_config_get (&ctx->cfg, key)) continue;    /* already known */
        if (git_submodule_register (ctx, &subs[i], quiet, NULL, 0) < 0)
            status = GIT_EXIT_FATAL;
    }
    free (subs);
    return status;
}

/* Put the submodule's git directory where git keeps it — .git/modules/<name>
   under the superproject — and leave a .git file pointing at it. */
static int
git_submodule_relocate (git_context *ctx, const struct git_submodule *sub)
{
    char from[4096], to[4096], link[4096], target[4096];
    snprintf (from, sizeof from, "%s/%s/.git", ctx->repo.work_tree, sub->path);
    snprintf (to, sizeof to, "%s/modules/%s", ctx->repo.common_dir, sub->name);
    /* Every directory above it, as mkdir -p would. */
    char made[4096];
    snprintf (made, sizeof made, "%s", to);
    for (char *slash = strchr (made + 1, '/'); slash; slash = strchr (slash + 1, '/')) {
        *slash = '\0';
        mkdir (made, 0777);
        *slash = '/';
    }
    if (rename (from, to) < 0) return -1;
    return git_submodule_link (ctx, sub);
}

/* Point a submodule's working tree at the git directory kept for it, and
   that git directory back at the working tree. */
static int
git_submodule_link (git_context *ctx, const struct git_submodule *sub)
{
    char to[4096], link[4096], target[4096];
    snprintf (to, sizeof to, "%s/modules/%s", ctx->repo.common_dir, sub->name);
    /* The working tree's own directory, and every one above it. */
    {
        char made[4096];
        snprintf (made, sizeof made, "%s/%s", ctx->repo.work_tree, sub->path);
        for (char *slash = strchr (made + 1, '/'); slash;
             slash = strchr (slash + 1, '/')) {
            *slash = '\0';
            mkdir (made, 0777);
            *slash = '/';
        }
        mkdir (made, 0777);
    }
    /* Back to the superproject's root from the submodule, then down. */
    size_t depth = 1;
    for (const char *p = sub->path; *p; p++) if (*p == '/') depth++;
    char up[256] = "";
    for (size_t i = 0; i < depth; i++)
        snprintf (up + i * 3, sizeof up - i * 3, "../");
    const char *git_dir_name = strrchr (ctx->repo.common_dir, '/');
    snprintf (target, sizeof target, "gitdir: %s%s/modules/%s\n", up,
              git_dir_name ? git_dir_name + 1 : ".git", sub->name);
    snprintf (link, sizeof link, "%s/%s/.git", ctx->repo.work_tree, sub->path);
    FILE *out = fopen (link, "w");
    if (!out) return -1;
    fputs (target, out);
    fclose (out);
    /* And the other half of the pairing: where its working tree is. */
    char worktree[4096];
    snprintf (worktree, sizeof worktree, "%s%s../%s", "../../",
              strchr (sub->name, '/') ? "../" : "", sub->path);
    char config_path[4096];
    snprintf (config_path, sizeof config_path, "%s/config", to);
    return bgit_config_set_file (config_path, "core.worktree", worktree, 0);
}

static int
git_submodule_update (git_context *ctx, struct git_state *state, int init,
                      int quiet, const char *const *paths, int n_paths)
{
    struct git_submodule *subs = NULL;
    size_t n = 0;
    if (git_submodules (ctx, state, &subs, &n) < 0) return GIT_EXIT_FATAL;
    int status = 0;
    for (size_t i = 0; i < n && !status; i++) {
        if (!git_submodule_wanted (&subs[i], paths, n_paths)) continue;
        char key[4400];
        snprintf (key, sizeof key, "submodule.%s.url", subs[i].name);
        const char *url = bgit_config_get (&ctx->cfg, key);
        if (!url && init) {
            /* Registering says where it is; the answer is kept here, since
               the configuration this command read is already behind. */
            char resolved[4096];
            if (git_submodule_register (ctx, &subs[i], quiet, resolved,
                                        sizeof resolved) < 0) {
                status = GIT_EXIT_FATAL;
                break;
            }
            snprintf (subs[i].url, sizeof subs[i].url, "%s", resolved);
            url = subs[i].url;
        }
        if (!url) {
            status = git_fatal ("Submodule path '%s' not initialized\n"
                                "Maybe you want to use 'update --init'?",
                                subs[i].path);
            break;
        }
        char full[4096], head[41];
        int moved = 0, reattached = 0;
        snprintf (full, sizeof full, "%s/%s", ctx->repo.work_tree,
                  subs[i].path);
        if (bgit_submodule_head (full, head) < 0) {
            /* Its git directory may still be here from before — a deinit
               leaves it — and then there is nothing to clone: the working
               tree is pointed back at it and filled from the commit. */
            char module[4096];
            struct stat st;
            snprintf (module, sizeof module, "%s/modules/%s",
                      ctx->repo.common_dir, subs[i].name);
            if (lstat (module, &st) == 0 && S_ISDIR (st.st_mode)) {
                if (git_submodule_link (ctx, &subs[i]) < 0) {
                    status = git_fatal ("could not reattach submodule path "
                                        "'%s'", subs[i].path);
                    break;
                }
                reattached = 1;
            } else {
                if (!quiet) {
                    fflush (stdout);
                    fprintf (stderr, "Cloning into '%s'...\ndone.\n", full);
                }
                const char *clone_args[4] = { "clone", "-q", url,
                                              subs[i].path };
                if (git_run_in (ctx->repo.work_tree, clone_args, 4) != 0 ||
                    git_submodule_relocate (ctx, &subs[i]) < 0) {
                    status = git_fatal ("clone of '%s' into submodule path "
                                        "'%s' failed", url, subs[i].path);
                    break;
                }
                moved = 1;
            }
        }
        if (reattached) {
            /* The working tree is empty, whatever its HEAD says, so the
               checkout has to be told to lay everything out again. */
            const char *fill_args[4] = { "checkout", "-q", "-f",
                                         subs[i].sha };
            if (git_run_in (full, fill_args, 4) != 0) {
                status = git_fatal ("Unable to checkout '%s' in submodule path "
                                    "'%s'", subs[i].sha, subs[i].path);
                break;
            }
            if (!quiet)
                printf ("Submodule path '%s': checked out '%s'\n",
                        subs[i].path, subs[i].sha);
            continue;
        }
        /* Whether it was just cloned or was already there, it is moved to
           the commit the index records. */
        if (bgit_submodule_head (full, head) == 0 &&
            strcmp (head, subs[i].sha)) {
            const char *checkout_args[3] = { "checkout", "-q", subs[i].sha };
            if (git_run_in (full, checkout_args, 3) != 0) {
                status = git_fatal ("Unable to checkout '%s' in submodule "
                                    "path '%s'", subs[i].sha, subs[i].path);
                break;
            }
            moved = 1;
        }
        /* Only a submodule that was actually moved is reported, which is
           what makes a second update say nothing. */
        if (moved && !quiet)
            printf ("Submodule path '%s': checked out '%s'\n", subs[i].path,
                    subs[i].sha);
    }
    free (subs);
    return status;
}

static int
git_cmd_submodule (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git submodule [status [--cached]] | init | "
                        "update [--init] [-q] | add <url> [<path>] | "
                        "deinit [-f] [--all] | foreach <command> [<path>...]";
    const char *verb = "status";
    const char *paths[32];
    int n_paths = 0, cached = 0, init = 0, quiet = 0, first = 1;
    int force = 0, all = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (first && (!strcmp (w, "status") || !strcmp (w, "init") ||
                      !strcmp (w, "update") || !strcmp (w, "add") ||
                      !strcmp (w, "deinit") || !strcmp (w, "foreach"))) {
            verb = w;
            first = 0;
            continue;
        }
        first = 0;
        /* What foreach is to run is a command, not an option of ours. */
        if (!strcmp (verb, "foreach") && n_paths) {
            if (n_paths < (int) (sizeof paths / sizeof *paths))
                paths[n_paths++] = w;
            continue;
        }
        if (!strcmp (w, "--cached")) cached = 1;
        else if (!strcmp (w, "--init")) init = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-f") || !strcmp (w, "--force")) force = 1;
        else if (!strcmp (w, "--all")) all = 1;
        else if (!strcmp (w, "--")) continue;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths))
            paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    int status;
    if (!strcmp (verb, "status"))
        status = git_submodule_status (ctx, &state, cached, paths, n_paths);
    else if (!strcmp (verb, "init"))
        status = git_submodule_init (ctx, &state, quiet, paths, n_paths);
    else if (!strcmp (verb, "add")) {
        if (!n_paths) {
            git_state_release (&state);
            return git_usage (usage);
        }
        status = git_submodule_add (ctx, &state, paths[0],
                                    n_paths > 1 ? paths[1] : NULL, quiet);
    } else if (!strcmp (verb, "deinit"))
        status = git_submodule_deinit (ctx, &state, force, all, paths, n_paths);
    else if (!strcmp (verb, "foreach")) {
        if (!n_paths) {
            git_state_release (&state);
            return git_usage (usage);
        }
        status = git_submodule_foreach (ctx, &state, paths[0], quiet);
    } else
        status = git_submodule_update (ctx, &state, init, quiet, paths,
                                       n_paths);
    git_state_release (&state);
    return status;
}

/* ---- cherry-pick and revert -------------------------------------------- */

/* The summary a picked or reverted commit prints: where it landed, who
   wrote it and when, then what it changed. */
static void
git_pick_summary (git_context *ctx, const struct git_state *state,
                  const char *commit, const char *subject, const char *author,
                  const char *committer, const char *author_date,
                  const char *old_tree, const char *new_tree)
{
    char abbreviated[41];
    git_abbrev (ctx, commit, 7, abbreviated, sizeof abbreviated);
    const char *branch = state->branch && !strncmp (state->branch, "refs/heads/", 11)
                         ? state->branch + 11 : NULL;
    printf ("[%s %s] %s\n", branch ? branch : "detached HEAD", abbreviated,
            subject);
    char author_who[1024], committer_who[1024];
    git_ident_who (author, author_who, sizeof author_who);
    git_ident_who (committer, committer_who, sizeof committer_who);
    if (strcmp (author_who, committer_who))
        printf (" Author: %s\n", author_who);
    char shown[128];
    git_format_date (author_date, 0, shown, sizeof shown);
    printf (" Date: %s\n", shown);

    struct git_diff_format format;
    git_diff_format_init (&format);
    format.shortstat = 1;
    format.summary = 1;
    bgit_diff_entry *entries = NULL;
    size_t n = 0;
    if (bgit_diff_trees (&ctx->odb, old_tree, new_tree, &entries, &n) == 0) {
        git_diff_emit (ctx, stdout, &format, entries, n, 0, "");
        bgit_diff_free (entries, n);
    }
}

/* Write the commit a pick or a revert makes, move the branch, and say so. */
static int
git_pick_commit (git_context *ctx, struct git_state *state, const char *tree,
                 const char *message, const char *author, const char *subject,
                 int reverting, int quiet)
{
    char committer[1024];
    if (bgit_ident (&ctx->cfg, 1, committer, sizeof committer) < 0)
        return git_fatal ("cannot determine the identity to use");
    char *body = NULL;
    size_t body_len = 0;
    FILE *builder = open_memstream (&body, &body_len);
    if (!builder) return GIT_EXIT_FATAL;
    fprintf (builder, "tree %s\n", tree);
    fprintf (builder, "parent %s\n", state->head);
    fprintf (builder, "author %s\n", author);
    fprintf (builder, "committer %s\n", committer);
    fprintf (builder, "\n%s", message);
    if (!*message || message[strlen (message) - 1] != '\n')
        fprintf (builder, "\n");
    fclose (builder);

    char commit[41];
    int rc = bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                (const unsigned char *) body, body_len, 1, commit);
    free (body);
    if (rc < 0) return GIT_EXIT_FATAL;

    char reflog[1200];
    snprintf (reflog, sizeof reflog, "%s: %s",
              reverting ? "revert" : "cherry-pick", subject);
    const char *ref = state->branch ? state->branch : "HEAD";
    char old_tree[41];
    memcpy (old_tree, state->head_tree, 41);
    if (bgit_ref_update (&ctx->repo, ref, commit, state->head, reflog) < 0)
        return GIT_EXIT_FATAL;
    if (state->branch)
        bgit_reflog_append (&ctx->repo, "HEAD", state->head, commit, reflog);
    if (!quiet) {
        /* The date the summary shows is the author's, which a pick keeps. */
        const char *date = strrchr (author, '>');
        git_pick_summary (ctx, state, commit, subject, author, committer,
                          date ? date + 2 : "", old_tree, tree);
    }
    return 0;
}

/* cherry-pick and revert are the same operation with the sides swapped:
   both take the change one commit made against its parent and merge it
   into HEAD, one forwards and one backwards. */
static int
git_cmd_pick (git_context *ctx, WORD_LIST *args, int reverting)
{
    const char *usage = reverting
        ? "git revert [--no-edit] [-n] <commit> | --continue | --abort"
        : "git cherry-pick [-n] <commit> | --continue | --abort";
    const char *name = NULL;
    int abort_it = 0, continue_it = 0, no_commit = 0, quiet = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--abort")) abort_it = 1;
        else if (!strcmp (w, "--continue")) continue_it = 1;
        else if (!strcmp (w, "-n") || !strcmp (w, "--no-commit")) no_commit = 1;
        else if (!strcmp (w, "--no-edit")) ;      /* nothing here edits */
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (!name) name = w;
        else return git_fatal ("this build's git %s takes one commit",
                               reverting ? "revert" : "cherry-pick");
    }
    if (!name && !abort_it && !continue_it) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    const char *head_file = reverting ? "REVERT_HEAD" : "CHERRY_PICK_HEAD";
    const char *verb = reverting ? "revert" : "cherry-pick";
    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    char pending[41];
    int in_progress = git_read_state_id (ctx, head_file, pending);
    int status = 0;

    if (abort_it) {
        if (!in_progress) {
            git_state_release (&state);
            return git_fatal ("no %s in progress", verb);
        }
        if (bgit_checkout_tree (&ctx->repo, &ctx->odb, state.head_tree,
                                &state.index, &state.n_index, 1, NULL) < 0 ||
            git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
        if (!status) {
            char reflog[1200];
            snprintf (reflog, sizeof reflog, "reset: moving to %s", state.head);
            bgit_reflog_append (&ctx->repo, "HEAD", state.head, state.head, reflog);
        }
        git_remove_state_file (ctx, head_file);
        git_remove_state_file (ctx, "MERGE_MSG");
        git_state_release (&state);
        return status;
    }

    if (continue_it) {
        if (!in_progress) {
            git_state_release (&state);
            return git_fatal ("no %s in progress", verb);
        }
        for (size_t i = 0; i < state.n_index; i++)
            if ((state.index[i].flags >> 12) & 3) {
                git_state_release (&state);
                fflush (stdout);
                fprintf (stderr, "error: Committing is not possible because "
                                 "you have unmerged files.\n");
                fprintf (stderr, "fatal: Exiting because of an unresolved "
                                 "conflict.\n");
                return 1;
            }
        struct git_commit picked;
        if (git_commit_read (ctx, pending, &picked) < 0) {
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        char tree[41];
        if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                             state.n_index, tree) < 0) {
            git_commit_release (&picked);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        /* The message was left in MERGE_MSG when the pick stopped. */
        char message_path[4096];
        unsigned char *message = NULL;
        size_t message_len = 0;
        if (git_state_file (ctx, "MERGE_MSG", message_path,
                            sizeof message_path) < 0 ||
            bgit_slurp_file (message_path, &message, &message_len) < 0) {
            git_commit_release (&picked);
            git_state_release (&state);
            return git_fatal ("cannot read the message left by the %s", verb);
        }
        char author[1024];
        if (reverting) {
            if (bgit_ident (&ctx->cfg, 0, author, sizeof author) < 0) {
                free (message);
                git_commit_release (&picked);
                git_state_release (&state);
                return git_fatal ("cannot determine the identity to use");
            }
        } else {
            snprintf (author, sizeof author, "%s <%s> %s", picked.author_name,
                      picked.author_email, picked.author_date);
        }
        char subject[1024];
        const char *nl = memchr (message, '\n', message_len);
        size_t take = nl ? (size_t) (nl - (const char *) message) : message_len;
        if (take >= sizeof subject) take = sizeof subject - 1;
        memcpy (subject, message, take);
        subject[take] = '\0';

        /* The reflog of a concluded pick says the commit concluded it. */
        char reflog[1200];
        snprintf (reflog, sizeof reflog, "commit (%s): %s", verb, subject);
        char committer[1024];
        char *body = NULL;
        size_t body_len = 0;
        FILE *builder = NULL;
        if (bgit_ident (&ctx->cfg, 1, committer, sizeof committer) == 0 &&
            (builder = open_memstream (&body, &body_len)) != NULL) {
            fprintf (builder, "tree %s\n", tree);
            fprintf (builder, "parent %s\n", state.head);
            fprintf (builder, "author %s\n", author);
            fprintf (builder, "committer %s\n", committer);
            fprintf (builder, "\n%.*s", (int) message_len, (const char *) message);
            fclose (builder);
        }
        free (message);
        char commit[41];
        if (!body || bgit_write_object (ctx->odb.object_dirs[0], "commit",
                                        (const unsigned char *) body, body_len,
                                        1, commit) < 0) {
            free (body);
            git_commit_release (&picked);
            git_state_release (&state);
            return GIT_EXIT_FATAL;
        }
        free (body);
        const char *ref = state.branch ? state.branch : "HEAD";
        char old_tree[41];
        memcpy (old_tree, state.head_tree, 41);
        if (bgit_ref_update (&ctx->repo, ref, commit, state.head, reflog) < 0)
            status = GIT_EXIT_FATAL;
        if (!status && state.branch)
            bgit_reflog_append (&ctx->repo, "HEAD", state.head, commit, reflog);
        if (!status && !quiet) {
            const char *date = strrchr (author, '>');
            git_pick_summary (ctx, &state, commit, subject, author, committer,
                              date ? date + 2 : "", old_tree, tree);
        }
        git_remove_state_file (ctx, head_file);
        git_remove_state_file (ctx, "MERGE_MSG");
        git_commit_release (&picked);
        git_state_release (&state);
        return status;
    }

    if (in_progress) {
        git_state_release (&state);
        return git_fatal ("a %s is already in progress", verb);
    }
    if (!state.have_head) {
        git_state_release (&state);
        return git_fatal ("cannot %s onto an empty history", verb);
    }
    for (size_t i = 0; i < state.n_index; i++)
        if ((state.index[i].flags >> 12) & 3) {
            git_state_release (&state);
            return git_fatal ("cannot %s: your index contains unmerged files",
                              verb);
        }

    char id[41], target[41];
    if (git_resolve (ctx, name, id, NULL) < 0 ||
        bgit_peel_to_type (&ctx->odb, id, BGIT_COMMIT, target) < 0) {
        git_state_release (&state);
        return git_fatal_ambiguous (name);
    }
    struct git_commit picked;
    if (git_commit_read (ctx, target, &picked) < 0) {
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (!picked.n_parents) {
        git_commit_release (&picked);
        git_state_release (&state);
        return git_fatal ("commit %s is a root commit", target);
    }
    if (picked.n_parents > 1) {
        git_commit_release (&picked);
        git_state_release (&state);
        return git_fatal ("commit %s is a merge but no -m option was given",
                          target);
    }
    char parent_tree[41];
    if (bgit_commit_tree (&ctx->odb, picked.parents[0], parent_tree) < 0) {
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    char subject[1024];
    git_subject (&picked, subject, sizeof subject);
    char abbreviated[41];
    git_abbrev (ctx, target, 7, abbreviated, sizeof abbreviated);

    /* Forwards, the commit's own tree is what is wanted; backwards, its
       parent's is, and the commit itself becomes the base. */
    const char *base_tree = reverting ? picked.tree : parent_tree;
    const char *their_tree = reverting ? parent_tree : picked.tree;
    char their_label[1200];
    if (reverting)
        snprintf (their_label, sizeof their_label, "parent of %s (%s)",
                  abbreviated, subject);
    else
        snprintf (their_label, sizeof their_label, "%s (%s)", abbreviated,
                  subject);

    bgit_merge_path *paths = NULL;
    size_t n_paths = 0;
    if (bgit_merge_trees (&ctx->odb, ctx->odb.object_dirs[0], base_tree,
                          state.head_tree, their_tree, "HEAD", their_label,
                          &paths, &n_paths) < 0) {
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (git_merge_safe (ctx, &state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    int conflicts = 0;
    for (size_t i = 0; i < n_paths; i++) {
        const bgit_merge_path *path = &paths[i];
        if (path->kind == BGIT_MERGE_AUTO || path->kind == BGIT_MERGE_CONTENT ||
            path->kind == BGIT_MERGE_ADD_ADD)
            printf ("Auto-merging %s\n", path->path);
        switch (path->kind) {
        case BGIT_MERGE_CONTENT:
            conflicts++;
            printf ("CONFLICT (content): Merge conflict in %s\n", path->path);
            break;
        case BGIT_MERGE_ADD_ADD:
            conflicts++;
            printf ("CONFLICT (add/add): Merge conflict in %s\n", path->path);
            break;
        case BGIT_MERGE_MODIFY_DELETE:
            conflicts++;
            printf ("CONFLICT (modify/delete): %s deleted in %s and modified "
                    "in %s.  Version %s of %s left in tree.\n", path->path,
                    path->deleted_in_ours ? "HEAD" : their_label,
                    path->deleted_in_ours ? their_label : "HEAD",
                    path->deleted_in_ours ? their_label : "HEAD", path->path);
            break;
        default:
            break;
        }
    }
    if (git_merge_apply (ctx, &state, paths, n_paths) < 0) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }

    /* The message the commit will carry, whichever way this went. */
    char *message = NULL;
    size_t message_len = 0;
    FILE *builder = open_memstream (&message, &message_len);
    if (!builder) {
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (reverting)
        fprintf (builder, "Revert \"%s\"\n\nThis reverts commit %s.\n", subject,
                 target);
    else
        fprintf (builder, "%s", picked.message);
    fclose (builder);
    char new_subject[1024];
    if (reverting) snprintf (new_subject, sizeof new_subject, "Revert \"%s\"",
                             subject);
    else snprintf (new_subject, sizeof new_subject, "%s", subject);

    if (conflicts) {
        char content[128];
        snprintf (content, sizeof content, "%s\n", target);
        git_write_state_file (ctx, head_file, content);
        git_write_state_file (ctx, "MERGE_MSG", message);
        free (message);
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        fflush (stdout);
        /* git says "apply" when picking and "revert" when reverting. */
        fprintf (stderr, "error: could not %s %s... %s\n",
                 reverting ? "revert" : "apply", abbreviated, subject);
        fprintf (stderr, "hint: After resolving the conflicts, mark them with\n");
        fprintf (stderr, "hint: \"git add/rm <pathspec>\", then run\n");
        fprintf (stderr, "hint: \"git %s --continue\".\n", verb);
        fprintf (stderr, "hint: You can instead skip this commit with "
                         "\"git %s --skip\".\n", verb);
        fprintf (stderr, "hint: To abort and get back to the state before "
                         "\"git %s\",\n", verb);
        fprintf (stderr, "hint: run \"git %s --abort\".\n", verb);
        return 1;
    }

    char tree[41];
    if (bgit_write_tree (&ctx->odb, ctx->odb.object_dirs[0], state.index,
                         state.n_index, tree) < 0) {
        free (message);
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    if (no_commit) {
        char content[128];
        snprintf (content, sizeof content, "%s\n", target);
        git_write_state_file (ctx, head_file, content);
        git_write_state_file (ctx, "MERGE_MSG", message);
        free (message);
        bgit_merge_paths_free (paths, n_paths);
        git_commit_release (&picked);
        git_state_release (&state);
        return 0;
    }

    char author[1024];
    if (reverting) {
        if (bgit_ident (&ctx->cfg, 0, author, sizeof author) < 0) {
            free (message);
            bgit_merge_paths_free (paths, n_paths);
            git_commit_release (&picked);
            git_state_release (&state);
            return git_fatal ("cannot determine the identity to use");
        }
    } else {
        snprintf (author, sizeof author, "%s <%s> %s", picked.author_name,
                  picked.author_email, picked.author_date);
    }
    status = git_pick_commit (ctx, &state, tree, message, author, new_subject,
                              reverting, quiet);
    free (message);
    bgit_merge_paths_free (paths, n_paths);
    git_commit_release (&picked);
    git_state_release (&state);
    return status;
}

static int
git_cmd_cherry_pick (git_context *ctx, WORD_LIST *args)
{
    return git_cmd_pick (ctx, args, 0);
}

static int
git_cmd_revert (git_context *ctx, WORD_LIST *args)
{
    return git_cmd_pick (ctx, args, 1);
}

/* ---- merge-file -------------------------------------------------------- */

static int
git_cmd_merge_file (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git merge-file [-p] [-q] [-L <label>]... "
                        "<current> <base> <other>";
    int to_stdout = 0, quiet = 0;
    const char *labels[3] = { NULL, NULL, NULL };
    int n_labels = 0;
    const char *files[3];
    int n_files = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-p") || !strcmp (w, "--stdout")) to_stdout = 1;
        else if (!strcmp (w, "-q") || !strcmp (w, "--quiet")) quiet = 1;
        else if (!strcmp (w, "-L") && p->next) {
            if (n_labels < 3) labels[n_labels++] = p->next->word->word;
            p = p->next;
        }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_files < 3) files[n_files++] = w;
        else return git_usage (usage);
    }
    if (n_files != 3) return git_usage (usage);
    (void) ctx;

    unsigned char *content[3] = { NULL, NULL, NULL };
    size_t sizes[3] = { 0, 0, 0 };
    for (int i = 0; i < 3; i++)
        if (bgit_slurp_file (files[i], &content[i], &sizes[i]) < 0) {
            for (int j = 0; j < i; j++) free (content[j]);
            return git_fatal ("Could not open '%s' for reading", files[i]);
        }

    bgit_merge_result merged;
    int rc = bgit_merge_content ((const char *) content[1], sizes[1],
                                 (const char *) content[0], sizes[0],
                                 (const char *) content[2], sizes[2],
                                 labels[0] ? labels[0] : files[0],
                                 labels[2] ? labels[2] : files[2],
                                 &merged);
    for (int i = 0; i < 3; i++) free (content[i]);
    if (rc < 0) return GIT_EXIT_FATAL;

    if (to_stdout) {
        fwrite (merged.text, 1, merged.len, stdout);
    } else {
        FILE *out = fopen (files[0], "w");
        if (!out) {
            free (merged.text);
            return git_fatal ("Could not open '%s' for writing", files[0]);
        }
        fwrite (merged.text, 1, merged.len, out);
        if (fclose (out) != 0) {
            free (merged.text);
            return git_fatal ("Could not write '%s'", files[0]);
        }
    }
    int conflicts = merged.conflicts;
    free (merged.text);
    (void) quiet;
    /* git exits with the number of conflicts, up to 127. */
    return conflicts > 127 ? 127 : conflicts;
}

/* ---- mv and clean ------------------------------------------------------ */

/* Move one tracked path in the index, keeping everything else about it. */
static int
git_index_rename (struct git_state *state, const char *from, const char *to)
{
    for (size_t i = 0; i < state->n_index; i++) {
        if (strcmp (state->index[i].path, from)) continue;
        char *path = strdup (to);
        if (!path) return -1;
        free (state->index[i].path);
        state->index[i].path = path;
        size_t len = strlen (to);
        state->index[i].flags = (uint16_t) ((state->index[i].flags & ~0xFFF) |
                                            (len > 0xFFF ? 0xFFF : len));
        return 0;
    }
    return -1;
}

/* Every directory above PATH, created as needed, as git creates them. */
static int
git_mkdirs_for (const char *path)
{
    char buf[4096];
    if (snprintf (buf, sizeof buf, "%s", path) >= (int) sizeof buf) return -1;
    char *slash = strrchr (buf, '/');
    if (!slash) return 0;
    *slash = '\0';
    for (char *p = buf + 1; *p; p++) {
        if (*p != '/') continue;
        *p = '\0';
        if (mkdir (buf, 0777) < 0 && errno != EEXIST) return -1;
        *p = '/';
    }
    return mkdir (buf, 0777) == 0 || errno == EEXIST ? 0 : -1;
}

static int
git_is_dir (const char *path)
{
    struct stat st;
    return stat (path, &st) == 0 && S_ISDIR (st.st_mode);
}

static int
git_cmd_mv (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git mv [-v] [-f] [-k] [-n] <source>... <destination>";
    int verbose = 0, force = 0, skip = 0, dry_run = 0, no_more = 0;
    const char *paths[64];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && (!strcmp (w, "-v") || !strcmp (w, "--verbose"))) verbose = 1;
        else if (!no_more && (!strcmp (w, "-f") || !strcmp (w, "--force"))) force = 1;
        else if (!no_more && !strcmp (w, "-k")) skip = 1;
        else if (!no_more && (!strcmp (w, "-n") || !strcmp (w, "--dry-run"))) dry_run = 1;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (n_paths < 2) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;

    char destination_buffer[4096];
    snprintf (destination_buffer, sizeof destination_buffer, "%s",
              paths[n_paths - 1]);
    size_t destination_len = strlen (destination_buffer);
    while (destination_len > 1 && destination_buffer[destination_len - 1] == '/')
        destination_buffer[--destination_len] = '\0';
    const char *destination = destination_buffer;
    char destination_full[4096];
    snprintf (destination_full, sizeof destination_full, "%s/%s",
              ctx->repo.work_tree, destination);
    int into_directory = git_is_dir (destination_full);
    if (n_paths > 2 && !into_directory) {
        git_state_release (&state);
        return git_fatal ("destination '%s' is not a directory", destination);
    }

    /* git checks every move before making any, so a bad second source
       cannot leave the first one already moved. */
    char (*targets)[4096] = calloc ((size_t) n_paths, sizeof *targets);
    int *skipped = calloc ((size_t) n_paths, sizeof *skipped);
    if (!targets || !skipped) {
        free (targets);
        free (skipped);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    int status = 0, moved = 0;
    for (int i = 0; i < n_paths - 1 && !status; i++) {
        const char *source = paths[i];
        if (into_directory) {
            const char *base = strrchr (source, '/');
            snprintf (targets[i], sizeof targets[i], "%s/%s", destination,
                      base ? base + 1 : source);
        } else {
            snprintf (targets[i], sizeof targets[i], "%s", destination);
        }
        if (dry_run)
            printf ("Checking rename of '%s' to '%s'\n", source, targets[i]);

        /* A source is either a tracked file or a directory holding some. */
        size_t source_len = strlen (source);
        int is_tracked = 0, is_prefix = 0;
        for (size_t j = 0; j < state.n_index; j++) {
            if (!strcmp (state.index[j].path, source)) is_tracked = 1;
            else if (!strncmp (state.index[j].path, source, source_len) &&
                     state.index[j].path[source_len] == '/')
                is_prefix = 1;
        }
        if (!is_tracked && !is_prefix) {
            if (skip) { skipped[i] = 1; continue; }
            status = git_fatal ("bad source, source=%s, destination=%s",
                                source, targets[i]);
            break;
        }
        char target_full[4096];
        snprintf (target_full, sizeof target_full, "%s/%s", ctx->repo.work_tree,
                  targets[i]);
        struct stat st;
        if (lstat (target_full, &st) == 0 && !force) {
            if (skip) { skipped[i] = 1; continue; }
            status = git_fatal ("destination exists, source=%s, destination=%s",
                                source, targets[i]);
            break;
        }
    }

    for (int i = 0; i < n_paths - 1 && !status; i++) {
        if (skipped[i]) continue;
        const char *source = paths[i], *target = targets[i];
        if (verbose || dry_run) printf ("Renaming %s to %s\n", source, target);
        if (dry_run) continue;

        char source_full[4096], target_full[4096];
        snprintf (source_full, sizeof source_full, "%s/%s", ctx->repo.work_tree, source);
        snprintf (target_full, sizeof target_full, "%s/%s", ctx->repo.work_tree, target);
        if (git_mkdirs_for (target_full) < 0 ||
            rename (source_full, target_full) < 0) {
            if (skip) continue;
            status = git_fatal ("renaming '%s' failed: %s", source,
                                strerror (errno));
            break;
        }
        size_t source_len = strlen (source);
        if (git_index_rename (&state, source, target) < 0) {
            /* A directory: every tracked path under it moves with it. */
            for (size_t j = 0; j < state.n_index; j++) {
                const char *path = state.index[j].path;
                if (strncmp (path, source, source_len) || path[source_len] != '/')
                    continue;
                char renamed[4096];
                snprintf (renamed, sizeof renamed, "%s%s", target, path + source_len);
                char *kept = strdup (renamed);
                if (!kept) { status = GIT_EXIT_FATAL; break; }
                free (state.index[j].path);
                state.index[j].path = kept;
                size_t len = strlen (kept);
                state.index[j].flags = (uint16_t) ((state.index[j].flags & ~0xFFF) |
                                                   (len > 0xFFF ? 0xFFF : len));
            }
        }
        moved = 1;
    }
    if (!status && moved) {
        if (state.n_index > 1)
            qsort (state.index, state.n_index, sizeof *state.index,
                   bgit_index_path_cmp);
        if (git_index_store (ctx, state.index, state.n_index) < 0)
            status = GIT_EXIT_FATAL;
    }
    free (targets);
    free (skipped);
    git_state_release (&state);
    return status;
}

/* Remove a file, or a directory and everything in it. */
static int
git_remove_path (const char *full)
{
    struct stat st;
    if (lstat (full, &st) < 0) return -1;
    if (!S_ISDIR (st.st_mode)) return unlink (full);
    DIR *dir = opendir (full);
    if (!dir) return -1;
    struct dirent *entry;
    int rc = 0;
    while ((entry = readdir (dir))) {
        if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, "..")) continue;
        char child[4096];
        if (snprintf (child, sizeof child, "%s/%s", full, entry->d_name) >=
            (int) sizeof child) { rc = -1; continue; }
        if (git_remove_path (child) < 0) rc = -1;
    }
    closedir (dir);
    return rmdir (full) < 0 ? -1 : rc;
}

static int
git_clean_cmp (const void *a, const void *b)
{
    const bgit_status_entry *left = *(const bgit_status_entry *const *) a;
    const bgit_status_entry *right = *(const bgit_status_entry *const *) b;
    return strcmp (left->path, right->path);
}

static int
git_cmd_clean (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git clean [-d] [-f] [-n] [-q] [-x | -X] [--] <path>...";
    int directories = 0, force = 0, dry_run = 0, quiet = 0;
    int with_ignored = 0, only_ignored = 0, no_more = 0;
    const char *paths[32];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!no_more && !strcmp (w, "--")) { no_more = 1; continue; }
        if (!no_more && w[0] == '-' && w[1] && w[1] != '-') {
            for (const char *flag = w + 1; *flag; flag++) {
                switch (*flag) {
                case 'd': directories = 1; break;
                case 'f': force = 1; break;
                case 'n': dry_run = 1; break;
                case 'q': quiet = 1; break;
                case 'x': with_ignored = 1; break;
                case 'X': only_ignored = 1; break;
                default: return git_usage (usage);
                }
            }
        }
        else if (!no_more && !strcmp (w, "--dry-run")) dry_run = 1;
        else if (!no_more && !strcmp (w, "--force")) force = 1;
        else if (!no_more && !strcmp (w, "--quiet")) quiet = 1;
        else if (!no_more && w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (!force && !dry_run)
        return git_fatal ("clean.requireForce is true and -f not given: "
                          "refusing to clean");
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");
    if (!ctx->repo.work_tree)
        return git_fatal ("this operation must be run in a work tree");

    struct git_state state;
    if (git_state_load (ctx, &state) < 0) return GIT_EXIT_FATAL;
    bgit_status_entry *entries = NULL;
    size_t n = 0;
    if (bgit_status (&ctx->repo, &ctx->odb, &ctx->cfg, state.index, state.n_index,
                     state.have_head ? state.head_tree : NULL, 0,
                     with_ignored || only_ignored, 0, &entries, &n) < 0) {
        git_state_release (&state);
        return git_fatal ("cannot read the working tree");
    }

    /* git reports what it would remove in path order, whether a candidate
       is untracked or ignored; the status walk groups them instead. */
    const bgit_status_entry **candidates = calloc (n ? n : 1, sizeof *candidates);
    if (!candidates) {
        bgit_status_free (entries, n);
        git_state_release (&state);
        return GIT_EXIT_FATAL;
    }
    size_t n_candidates = 0;
    for (size_t i = 0; i < n; i++) {
        const bgit_status_entry *entry = &entries[i];
        if (!entry->untracked && !entry->ignored) continue;
        if (entry->ignored && !with_ignored && !only_ignored) continue;
        if (entry->untracked && only_ignored) continue;
        candidates[n_candidates++] = entry;
    }
    if (n_candidates > 1)
        qsort (candidates, n_candidates, sizeof *candidates, git_clean_cmp);

    int status = 0;
    for (size_t i = 0; i < n_candidates && !status; i++) {
        const bgit_status_entry *entry = candidates[i];
        size_t len = strlen (entry->path);
        int is_directory = len && entry->path[len - 1] == '/';
        int named = 0;
        if (n_paths) {
            for (int j = 0; j < n_paths && !named; j++) {
                char trimmed[4096];
                snprintf (trimmed, sizeof trimmed, "%.*s",
                          (int) (is_directory ? len - 1 : len), entry->path);
                if (git_path_in_spec (trimmed, paths[j])) named = 1;
            }
            if (!named) continue;
        } else if (*ctx->prefix &&
                   strncmp (entry->path, ctx->prefix, strlen (ctx->prefix))) {
            /* Run under a directory, git clears out what is under it. */
            continue;
        }
        /* Without -d a directory is left alone, unless it was named. */
        if (is_directory && !directories && !named) continue;
        if (!quiet) {
            char here[8192];
            printf ("%s %s\n", dry_run ? "Would remove" : "Removing",
                    git_path_from_here (ctx, entry->path, here, sizeof here));
        }
        if (dry_run) continue;
        char full[4096];
        snprintf (full, sizeof full, "%s/%.*s", ctx->repo.work_tree,
                  (int) (is_directory ? len - 1 : len), entry->path);
        if (git_remove_path (full) < 0)
            status = git_fatal ("failed to remove %s", entry->path);
    }
    free (candidates);
    bgit_status_free (entries, n);
    git_state_release (&state);
    return status;
}

/* ---- check-ignore ------------------------------------------------------ */

/* Load the .gitignore of every directory above PATH, once each. */
static int
git_ignore_dirs_for (bgit_ignore *ignore, git_context *ctx, const char *path,
                     char (*loaded)[4096], size_t *n_loaded, size_t max)
{
    char prefix[4096] = "";
    const char *at = path;
    for (;;) {
        const char *slash = strchr (at, '/');
        if (!slash) break;
        size_t len = (size_t) (slash - path);
        if (len >= sizeof prefix) break;
        memcpy (prefix, path, len);
        prefix[len] = '\0';
        int seen = 0;
        for (size_t i = 0; i < *n_loaded && !seen; i++)
            if (!strcmp (loaded[i], prefix)) seen = 1;
        if (!seen && *n_loaded < max) {
            snprintf (loaded[*n_loaded], sizeof loaded[0], "%s", prefix);
            (*n_loaded)++;
            if (bgit_ignore_add_dir (ignore, &ctx->repo, prefix) < 0) return -1;
        }
        at = slash + 1;
    }
    return 0;
}

static int
git_cmd_check_ignore (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git check-ignore [-v] [--non-matching] [--no-index] "
                        "<pathname>...";
    int verbose = 0, non_matching = 0;
    const char *paths[64];
    int n_paths = 0;

    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "-v") || !strcmp (w, "--verbose")) verbose = 1;
        else if (!strcmp (w, "-n") || !strcmp (w, "--non-matching")) non_matching = 1;
        else if (!strcmp (w, "--no-index")) { /* we never consult the index */ }
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n_paths < (int) (sizeof paths / sizeof *paths)) paths[n_paths++] = w;
        else return git_fatal ("too many paths");
    }
    if (!n_paths) return git_usage (usage);
    if (git_context_open (ctx) != 0) return GIT_EXIT_FATAL;
    /* A path was written from where the command was run. */
    if (git_paths_from_here (ctx, paths, n_paths) < 0)
        return git_fatal ("too many paths");

    bgit_ignore ignore;
    if (bgit_ignore_load (&ignore, &ctx->repo, &ctx->cfg) < 0)
        return git_fatal ("cannot read the exclude files");
    static char loaded[64][4096];
    size_t n_loaded = 0;
    int any = 0, status = 0;
    for (int i = 0; i < n_paths; i++) {
        if (git_ignore_dirs_for (&ignore, ctx, paths[i], loaded, &n_loaded,
                                 sizeof loaded / sizeof loaded[0]) < 0) {
            status = GIT_EXIT_FATAL;
            break;
        }
        struct stat st;
        int is_dir = stat (paths[i], &st) == 0 && S_ISDIR (st.st_mode);
        const bgit_ignore_rule *rule = NULL;
        bgit_ignore_match (&ignore, paths[i], is_dir, &rule);
        /* git reports any rule that matched, a negation included, and its
           status says whether a pattern matched at all. */
        if (rule) any = 1;
        if (!rule && !non_matching) continue;
        if (verbose) {
            if (rule)
                printf ("%s:%ld:%s\t%s\n", rule->source, rule->line,
                        rule->text, paths[i]);
            else
                printf ("::\t%s\n", paths[i]);
        } else {
            printf ("%s\n", paths[i]);
        }
    }
    bgit_ignore_release (&ignore);
    if (status) return status;
    return any ? 0 : 1;
}

/* ---- attributes -------------------------------------------------------- */

struct git_attr_rule {
    char *pattern, *words, *base;
    int macro;
};

struct git_attr_state {
    struct git_attr_rule *rules;
    size_t n_rules, cap_rules;
    struct { char *name, *value; } *values;
    size_t n_values, cap_values;
};

static void
git_attr_release (struct git_attr_state *s)
{
    for (size_t i = 0; i < s->n_rules; i++) {
        free (s->rules[i].pattern);
        free (s->rules[i].words);
        free (s->rules[i].base);
    }
    for (size_t i = 0; i < s->n_values; i++) {
        free (s->values[i].name);
        free (s->values[i].value);
    }
    free (s->rules);
    free (s->values);
}

static int
git_attr_value (struct git_attr_state *s, const char *name, const char *value)
{
    size_t i = 0;
    while (i < s->n_values && strcmp (s->values[i].name, name)) i++;
    if (i == s->n_values) {
        if (s->n_values == s->cap_values) {
            size_t cap = s->cap_values ? s->cap_values * 2 : 16;
            void *grown = realloc (s->values, cap * sizeof *s->values);
            if (!grown) return -1;
            s->values = grown;
            s->cap_values = cap;
        }
        s->values[i].name = strdup (name);
        s->values[i].value = NULL;
        if (!s->values[i].name) return -1;
        s->n_values++;
    }
    char *copy = value ? strdup (value) : NULL;
    if (value && !copy) return -1;
    free (s->values[i].value);
    s->values[i].value = copy;
    return 0;
}

/* Keep all rules until every file has been read: a macro may be defined in a
   stronger file than the rule that uses it. */
static int
git_attr_read (struct git_attr_state *s, FILE *f, const char *base)
{
    if (!f) return 0;
    char *line = NULL;
    size_t cap = 0;
    int rc = 0;
    while (getline (&line, &cap, f) >= 0) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (!*p || *p == '#' || *p == '\n') continue;
        char *end = p;
        if (*p == '"') {
            end++;
            while (*end && *end != '\n') {
                if (*end == '\\' && end[1]) { end += 2; continue; }
                if (*end == '"') break;
                end++;
            }
            if (*end != '"') continue;
            end++;
        } else
            while (*end && *end != ' ' && *end != '\t' && *end != '\r' &&
                   *end != '\n') end++;
        if (!*end) continue;
        *end++ = '\0';
        while (*end == ' ' || *end == '\t') end++;
        end[strcspn (end, "\r\n")] = '\0';
        if (!*end) continue;
        if (*p == '"') {
            char *read = p + 1, *write = p;
            while (*read && read < end - 2) {
                if (*read == '\\' && read + 1 < end - 2) {
                    read++;
                    if (*read == 'n') *write++ = '\n';
                    else if (*read == 't') *write++ = '\t';
                    else if (*read == 'r') *write++ = '\r';
                    else if (*read >= '0' && *read <= '7') {
                        int value = 0, digits = 0;
                        while (digits < 3 && read < end - 2 &&
                               *read >= '0' && *read <= '7') {
                            value = value * 8 + (*read++ - '0');
                            digits++;
                        }
                        *write++ = (char) value;
                        continue;
                    } else *write++ = *read;
                    read++;
                } else *write++ = *read++;
            }
            *write = '\0';
        }
        if (s->n_rules == s->cap_rules) {
            size_t next = s->cap_rules ? s->cap_rules * 2 : 32;
            void *grown = realloc (s->rules, next * sizeof *s->rules);
            if (!grown) { rc = -1; break; }
            s->rules = grown;
            s->cap_rules = next;
        }
        struct git_attr_rule *r = &s->rules[s->n_rules];
        r->macro = !*base && !strncmp (p, "[attr]", 6);
        r->pattern = strdup (r->macro ? p + 6 : p);
        r->words = strdup (end);
        r->base = strdup (base);
        if (!r->pattern || !r->words || !r->base) {
            free (r->pattern); free (r->words); free (r->base);
            rc = -1; break;
        }
        s->n_rules++;
    }
    if (ferror (f)) rc = -1;
    free (line);
    fclose (f);
    return rc;
}

/* --cached uses the index; otherwise a missing worktree file falls back to
   its index entry. The temporary stream owns a copy of an index blob. */
static FILE *
git_attr_open (git_context *ctx, const char *path, int cached,
               const bgit_index_entry *entries, size_t count)
{
    if (!cached && ctx->repo.work_tree) {
        char full[8192];
        struct stat st;
        if ((size_t) snprintf (full, sizeof full, "%s/%s",
                               ctx->repo.work_tree, path) < sizeof full &&
            lstat (full, &st) == 0 && S_ISREG (st.st_mode)) {
            FILE *f = fopen (full, "r");
            if (f) return f;
        }
    }
    for (size_t i = 0; i < count; i++) {
        if (strcmp (entries[i].path, path)) continue;
        char hex[41];
        enum bgit_type type;
        unsigned char *data = NULL;
        size_t n = 0;
        bgit_sha_to_hex (entries[i].sha, hex);
        if (bgit_odb_read (&ctx->odb, hex, &type, &data, &n) < 0 ||
            type != BGIT_BLOB) { free (data); return NULL; }
        FILE *f = tmpfile ();
        if (!f || fwrite (data, 1, n, f) != n) {
            if (f) fclose (f);
            f = NULL;
        } else rewind (f);
        free (data);
        return f;
    }
    return NULL;
}

static int
git_attr_match (const struct git_attr_rule *r, const char *path)
{
    size_t len = strlen (r->pattern);
    if (!len || r->macro || r->pattern[0] == '!' ||
        r->pattern[len - 1] == '/') return 0;
    const char *relative = path;
    if (*r->base) {
        size_t base = strlen (r->base);
        if (strncmp (path, r->base, base) || path[base] != '/') return 0;
        relative = path + base + 1;
    }
    const char *pattern = r->pattern;
    if (*pattern == '/') pattern++;
    if (strchr (pattern, '/')) return bgit_wild (pattern, relative);
    const char *name = strrchr (relative, '/');
    return bgit_wild (pattern, name ? name + 1 : relative);
}

static int
git_attr_words (struct git_attr_state *s, const char *words, int depth)
{
    char *copy = strdup (words);
    if (!copy) return -1;
    char *save = NULL;
    for (char *word = strtok_r (copy, " \t", &save); word;
         word = strtok_r (NULL, " \t", &save)) {
        const char *name = word, *value = "set";
        int bare = 1;
        if (*name == '-') { name++; value = "unset"; }
        else if (*name == '!') { name++; value = NULL; }
        char *eq = strchr (word, '=');
        if (eq && name == word) {
            *eq = '\0'; value = eq + 1; bare = 0;
        }
        if (!*name) { free (copy); return -1; }
        if (depth < 8 && bare && name == word) {
            const char *macro = !strcmp (name, "binary")
                                ? "-diff -merge -text" : NULL;
            for (size_t i = 0; i < s->n_rules; i++)
                if (s->rules[i].macro && !strcmp (s->rules[i].pattern, name))
                    macro = s->rules[i].words;
            if (macro && git_attr_words (s, macro, depth + 1) < 0) {
                free (copy); return -1;
            }
        }
        if (git_attr_value (s, name, value) < 0) {
            free (copy); return -1;
        }
    }
    free (copy);
    return 0;
}

static int
git_attr_report (git_context *ctx, const char *shown, const char *const *attrs,
                 int n_attrs, int all, int zero, int cached,
                 const bgit_index_entry *entries, size_t count)
{
    char path[8192], source[8192];
    if (git_path_join_prefix (ctx->prefix, shown, path, sizeof path) < 0)
        return git_fatal ("path is too long: %s", shown);
    struct git_attr_state state = {0};
    const char *global = bgit_config_get (&ctx->cfg, "core.attributesfile");
    if (!global) {
        const char *xdg = getenv ("XDG_CONFIG_HOME");
        const char *home = getenv ("HOME");
        if (xdg && *xdg)
            snprintf (source, sizeof source, "%s/git/attributes", xdg);
        else
            snprintf (source, sizeof source, "%s/.config/git/attributes",
                      home ? home : "");
        global = source;
    } else if (global[0] == '~' && global[1] == '/' && getenv ("HOME")) {
        snprintf (source, sizeof source, "%s/%s", getenv ("HOME"), global + 2);
        global = source;
    }
    if (git_attr_read (&state, fopen (global, "r"), "") < 0) goto failed;
    if (git_attr_read (&state,
                       git_attr_open (ctx, ".gitattributes", cached,
                                      entries, count), "") < 0) goto failed;
    for (char *slash = strchr (path, '/'); slash;
         slash = strchr (slash + 1, '/')) {
        size_t len = (size_t) (slash - path);
        if (len + 16 >= sizeof source) goto failed;
        memcpy (source, path, len);
        source[len] = '\0';
        char base[8192];
        memcpy (base, source, len + 1);
        snprintf (source + len, sizeof source - len, "/.gitattributes");
        if (git_attr_read (&state, git_attr_open (ctx, source, cached,
                                                  entries, count), base) < 0)
            goto failed;
    }
    snprintf (source, sizeof source, "%s/info/attributes", ctx->repo.git_dir);
    if (git_attr_read (&state, fopen (source, "r"), "") < 0) goto failed;
    for (size_t i = 0; i < state.n_rules; i++)
        if (git_attr_match (&state.rules[i], path) &&
            git_attr_words (&state, state.rules[i].words, 0) < 0) goto failed;

    char quoted[8192];
    const char *display = zero ? shown
                          : bgit_quote_path (shown, quoted, sizeof quoted);
    if (all) {
        for (size_t i = 0; i < state.n_values; i++) {
            const char *value = state.values[i].value;
            if (!value) continue;
            if (zero) printf ("%s%c%s%c%s%c", display, 0,
                              state.values[i].name, 0, value, 0);
            else printf ("%s: %s: %s\n", display, state.values[i].name, value);
        }
    } else for (int i = 0; i < n_attrs; i++) {
        const char *value = "unspecified";
        for (size_t j = 0; j < state.n_values; j++)
            if (!strcmp (attrs[i], state.values[j].name))
                value = state.values[j].value ? state.values[j].value
                                               : "unspecified";
        if (zero) printf ("%s%c%s%c%s%c", display, 0, attrs[i], 0, value, 0);
        else printf ("%s: %s: %s\n", display, attrs[i], value);
    }
    git_attr_release (&state);
    return 0;
failed:
    git_attr_release (&state);
    return git_fatal ("cannot read attributes");
}

static int
git_cmd_check_attr (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git check-attr [--cached] [--source=<tree-ish>] "
                        "[-a | --all | <attr>...] [--] <pathname>... | --stdin [-z]";
    size_t n_args = 0;
    for (WORD_LIST *p = args; p; p = p->next) n_args++;
    if (n_args > SIZE_MAX / (2 * sizeof (const char *)))
        return git_fatal ("too many arguments");
    const char **words = calloc (n_args ? 2 * n_args : 1, sizeof *words);
    if (!words) return git_fatal ("out of memory");
    const char **attrs = words, **paths = words + n_args;
    int n_attrs = 0, n_paths = 0, all = 0, cached = 0, input = 0, zero = 0;
    int after_dashes = 0;
    const char *source_tree = NULL;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!after_dashes && !strcmp (w, "--")) { after_dashes = 1; continue; }
        if (!after_dashes && (!strcmp (w, "-a") || !strcmp (w, "--all"))) all = 1;
        else if (!after_dashes && !strcmp (w, "--cached")) cached = 1;
        else if (!after_dashes && !strncmp (w, "--source=", 9))
            source_tree = w + 9;
        else if (!after_dashes && !strcmp (w, "--source") && p->next) {
            source_tree = p->next->word->word;
            p = p->next;
        }
        else if (!after_dashes && !strcmp (w, "--stdin")) input = 1;
        else if (!after_dashes && !strcmp (w, "-z")) zero = 1;
        else if (!after_dashes && w[0] == '-' && w[1]) goto usage_error;
        else if (after_dashes || (all && !input)) {
            paths[n_paths++] = w;
        } else {
            attrs[n_attrs++] = w;
        }
    }
    if (!input && !after_dashes && !all && n_attrs > 1) {
        for (int i = 1; i < n_attrs; i++) paths[n_paths++] = attrs[i];
        n_attrs = 1;
    }
    if ((!all && !n_attrs) || (!input && !n_paths) || (input && n_paths))
        goto usage_error;
    if (git_context_open (ctx) != 0) {
        free (words);
        return GIT_EXIT_FATAL;
    }
    bgit_index_entry *entries = NULL;
    size_t count = 0;
    if (source_tree) {
        char id[41], tree[41];
        if (git_resolve (ctx, source_tree, id, NULL) < 0 ||
            bgit_peel_to_type (&ctx->odb, id, BGIT_TREE, tree) < 0 ||
            bgit_read_tree (&ctx->odb, tree, &entries, &count) < 0) {
            free (words);
            return git_fatal ("%s: not a valid tree-ish source", source_tree);
        }
        cached = 1;
    } else if (git_index_load (ctx, &entries, &count) < 0) {
        free (words);
        return git_fatal ("cannot read the index");
    }
    int status = 0;
    for (int i = 0; i < n_paths && !status; i++)
        status = git_attr_report (ctx, paths[i], attrs, n_attrs, all, zero,
                                  cached, entries, count);
    if (input && !status) {
        char *line = NULL;
        size_t cap = 0;
        ssize_t n;
        clearerr (stdin);
        while ((n = getdelim (&line, &cap, zero ? '\0' : '\n', stdin)) >= 0) {
            if (n && line[n - 1] == (zero ? '\0' : '\n')) line[n - 1] = '\0';
            status = git_attr_report (ctx, line, attrs, n_attrs, all, zero,
                                      cached, entries, count);
            if (status) break;
        }
        if (ferror (stdin)) status = git_fatal ("cannot read standard input");
        free (line);
    }
    bgit_index_free_entries (entries, count);
    free (words);
    return status;
usage_error:
    free (words);
    return git_usage (usage);
}

/* ---- config ------------------------------------------------------------ */

/* A configured value as the type asked for writes it: git's truth words
   for a bool, a plain number for an int (with the k, m and g it allows),
   and the value itself otherwise. */
static int
git_config_shown (git_context *ctx, const char *type, const char *key,
                  const char *value, char *out, size_t outsz)
{
    (void) ctx;
    if (!type || !strcmp (type, "string")) {
        snprintf (out, outsz, "%s", value);
        return 0;
    }
    if (!strcmp (type, "bool") || !strcmp (type, "bool-or-int")) {
        static const char *const yes[] = { "true", "yes", "on", "1", NULL };
        static const char *const no[] = { "false", "no", "off", "0", "", NULL };
        for (int i = 0; yes[i]; i++)
            if (!strcasecmp (value, yes[i])) {
                snprintf (out, outsz, "true");
                return 0;
            }
        for (int i = 0; no[i]; i++)
            if (!strcasecmp (value, no[i])) {
                snprintf (out, outsz, "false");
                return 0;
            }
        if (!strcmp (type, "bool"))
            return git_fatal ("bad boolean config value '%s' for '%s'", value,
                              key) ? -1 : -1;
    }
    if (!strcmp (type, "int") || !strcmp (type, "bool-or-int")) {
        char *end = NULL;
        long long number = strtoll (value, &end, 10);
        long long scale = 1;
        if (end && *end) {
            if (!end[1] && (*end == 'k' || *end == 'K')) scale = 1024;
            else if (!end[1] && (*end == 'm' || *end == 'M')) scale = 1024 * 1024;
            else if (!end[1] && (*end == 'g' || *end == 'G'))
                scale = 1024 * 1024 * 1024;
            else {
                git_fatal ("bad numeric config value '%s' for '%s': invalid "
                           "unit", value, key);
                return -1;
            }
        }
        snprintf (out, outsz, "%lld", number * scale);
        return 0;
    }
    if (!strcmp (type, "path")) {
        char home[4096];
        if (value[0] == '~' && value[1] == '/' &&
            bgit_env ("HOME", home, sizeof home))
            snprintf (out, outsz, "%s/%s", home, value + 2);
        else snprintf (out, outsz, "%s", value);
        return 0;
    }
    git_fatal ("unrecognized --type argument, %s", type);
    return -1;
}

static int
git_cmd_config (git_context *ctx, WORD_LIST *args)
{
    const char *usage = "git config [--global | --local | --file <file>] [-z] "
                        "[--name-only] [--type=<type> | --bool | --int] "
                        "[--default <value>] (--list | --get <key> | "
                        "--get-all <key> | --get-regexp <pattern> | "
                        "--unset <key> | --unset-all <key> | "
                        "--remove-section <name> | --add <key> <value> | "
                        "<key> [<value>])";
    int list = 0, get = 0, get_all = 0, unset = 0, add = 0, zero = 0;
    int get_regexp = 0, remove_section = 0, name_only = 0;
    const char *type = NULL, *fallback = NULL;
    int global = 0, local = 0, system_scope = 0;
    const char *file = NULL;
    const char *positional[2] = { NULL, NULL };
    int n = 0;

    (void) ctx;
    for (WORD_LIST *p = args; p; p = p->next) {
        const char *w = p->word->word;
        if (!strcmp (w, "--list") || !strcmp (w, "-l")) list = 1;
        else if (!strcmp (w, "--get")) get = 1;
        else if (!strcmp (w, "--get-all")) get_all = 1;
        else if (!strcmp (w, "--unset")) unset = 1;
        else if (!strcmp (w, "--unset-all")) unset = 1;
        else if (!strcmp (w, "--get-regexp")) get_regexp = 1;
        else if (!strcmp (w, "--remove-section")) remove_section = 1;
        else if (!strcmp (w, "--name-only")) name_only = 1;
        else if (!strcmp (w, "--bool")) type = "bool";
        else if (!strcmp (w, "--int")) type = "int";
        else if (!strcmp (w, "--path")) type = "path";
        else if (!strncmp (w, "--type=", 7)) type = w + 7;
        else if (!strcmp (w, "--default") && p->next)
            fallback = (p = p->next)->word->word;
        else if (!strncmp (w, "--default=", 10)) fallback = w + 10;
        else if (!strcmp (w, "--add")) add = 1;
        else if (!strcmp (w, "-z") || !strcmp (w, "--null")) zero = 1;
        else if (!strcmp (w, "--global")) global = 1;
        else if (!strcmp (w, "--local")) local = 1;
        else if (!strcmp (w, "--system")) system_scope = 1;
        else if (!strcmp (w, "--file") && p->next) { file = p->next->word->word; p = p->next; }
        else if (!strncmp (w, "--file=", 7)) file = w + 7;
        else if (w[0] == '-' && w[1]) return git_usage (usage);
        else if (n < 2) positional[n++] = w;
        else return git_usage (usage);
    }
    if (list + get + get_all + unset + add + get_regexp + remove_section > 1)
        return git_usage (usage);
    if (!list && !positional[0]) return git_usage (usage);

    bgit_repo repo;
    int have_repo = bgit_repo_discover (".", &repo) == 0;
    bgit_config cfg;
    if (bgit_config_load (&cfg, have_repo ? &repo : NULL, git_overrides,
                          git_n_overrides) < 0) {
        if (have_repo) bgit_repo_release (&repo);
        return git_fatal ("cannot read configuration");
    }

    int status = 0;
    int writing = add || unset || remove_section ||
                  (!list && !get && !get_all && !get_regexp && positional[1]);
    if (writing) {
        char path[4096];
        if (file) {
            snprintf (path, sizeof path, "%s", file);
        } else if (global) {
            if (bgit_config_global_file (path, sizeof path) < 0) {
                status = git_fatal ("$HOME not set");
                goto done;
            }
        } else {
            if (!have_repo) {
                status = git_fatal ("--local can only be used inside a git repository");
                goto done;
            }
            bgit_config_repo_file (&repo, path, sizeof path);
        }
        if (remove_section) {
            int rc = bgit_config_remove_section_file (path, positional[0]);
            /* git says nothing of a section that was not there, and
               leaves with the status it keeps for that. */
            status = rc < 0 ? GIT_EXIT_FATAL : rc ? 128 : 0;
            if (rc > 0) {
                fflush (stdout);
                fprintf (stderr, "fatal: no such section: %s\n", positional[0]);
            }
        }
        else if (unset)
            status = bgit_config_get (&cfg, positional[0]) == NULL ? 5
                   : (bgit_config_unset_file (path, positional[0]) < 0
                      ? GIT_EXIT_FATAL : 0);
        else if (!positional[1])
            status = git_usage (usage);
        else
            status = bgit_config_set_file (path, positional[0], positional[1],
                                           add) < 0 ? GIT_EXIT_FATAL : 0;
        goto done;
    }

    if (list) {
        /* --system, --global and --local each keep to the file they name,
           which is what makes `--list --local` the repository's own. */
        int only = system_scope ? 0 : global ? 1 : local ? 2 : -1;
        for (size_t i = 0; i < cfg.n; i++) {
            if (only >= 0 && cfg.entries[i].level != only) continue;
            /* A key with no value is listed on its own, as git lists it. */
            const char *key = cfg.entries[i].key, *value = cfg.entries[i].value;
            if (name_only)
                printf (zero ? "%s%c" : "%s\n", key, '\0');
            else if (zero)
                printf (value ? "%s\n%s%c" : "%s%.0s%c", key, value ? value : "", '\0');
            else
                printf (value ? "%s=%s\n" : "%s%.0s\n", key, value ? value : "");
        }
        goto done;
    }
    if (get_regexp) {
        /* The keys a pattern picks out, each with its value beside it. */
        regex_t compiled;
        if (regcomp (&compiled, positional[0], 0) != 0) {
            status = git_fatal ("invalid pattern: %s", positional[0]);
            goto done;
        }
        int found = 0;
        for (size_t i = 0; i < cfg.n; i++) {
            const char *key = cfg.entries[i].key, *value = cfg.entries[i].value;
            if (regexec (&compiled, key, 0, NULL, 0) != 0) continue;
            found = 1;
            if (name_only) printf (zero ? "%s%c" : "%s\n", key, '\0');
            else if (zero)
                printf (value ? "%s\n%s%c" : "%s%.0s%c", key,
                        value ? value : "", '\0');
            else
                printf (value ? "%s %s\n" : "%s%.0s\n", key,
                        value ? value : "");
        }
        regfree (&compiled);
        status = found ? 0 : 1;
        goto done;
    }
    if (get_all) {
        const char **values = NULL;
        size_t count = bgit_config_get_all (&cfg, positional[0], &values);
        for (size_t i = 0; i < count; i++) {
            char shown[4096];
            if (git_config_shown (ctx, type, positional[0], values[i], shown,
                                  sizeof shown) < 0) {
                free (values);
                status = GIT_EXIT_FATAL;
                goto done;
            }
            printf (zero ? "%s%c" : "%s\n", shown, '\0');
        }
        free (values);
        status = count ? 0 : 1;
        goto done;
    }
    /* --get, or a bare key, both read the last value. */
    const char *value = bgit_config_get (&cfg, positional[0]);
    if (!value) value = fallback;
    if (!value) { status = 1; goto done; }
    char shown[4096];
    if (git_config_shown (ctx, type, positional[0], value, shown,
                          sizeof shown) < 0) {
        status = GIT_EXIT_FATAL;
        goto done;
    }
    printf (zero ? "%s%c" : "%s\n", shown, '\0');

done:
    bgit_config_release (&cfg);
    if (have_repo) bgit_repo_release (&repo);
    return status;
}

